\title{Non-perturbative determination of the sphaleron rate for first-order phase transitions}

\author{Jaakko Annala}
\email{jaakko.annala@helsinki.fi}
\affiliation{Department of Physics and Helsinki Institute of Physics, PL 64 (Gustaf H\"allstr\"omin katu 2), FI-00014 University of Helsinki, Finland}

