\section{The functions $\zeta(t)$ and $t(\zeta)$}
\label{sec:zeta-t-properties}
Throughout our work, an important role is played by the function $\zeta:(-1,+\infty)\to\mathbb{R}$ defined for $t>1$ by 
\begin{equation}
    \zeta(t):=\left(\frac{3}{2}\int_1^{t}\sqrt{\tau^2-1}\,\dd\tau\right)^{2/3},\quad t>1
    \label{eq:zeta-define}
\end{equation}
and continued analytically to the half-line $t>-1$ as a Schwarz-symmetrical function. An explicit formula for $\zeta$ on the interval $-1<t<1$ is:
\begin{equation}
    \zeta(t)=-\left(\frac{3}{2}\int_t^1\sqrt{1-\tau^2}\,\dd\tau\right)^{2/3},\quad -1<t<1.
\label{eq:zeta-less-than-1}
\end{equation}
We have the asymptotic behavior
\begin{equation}
    \zeta(t) = \left(\frac{3}{4}\right)^{2/3}t^{4/3}(1+O(t^{-1})),\quad t\to+\infty.
    \label{eq:zeta-asymp}
\end{equation}
Note that $\zeta(t)$ vanishes linearly at $t=1$, and it is strictly increasing on $(-1,+\infty)$, so it has an analytic inverse denoted $t:(\zeta(-1),+\infty)\to (-1,+\infty)$.  It is straightforward to show that $t(\diamond)$ and its derivatives have the following asymptotic behavior:
    \begin{equation}
    \begin{gathered}
        t(\zeta)=\left(\frac{4}{3}\right)^{1/2}\zeta^{3/4}(1+O(\zeta^{-1})),\quad
t'(\zeta)=\left(\frac{3}{4}\right)^{1/2}\zeta^{-1/4}(1+O(\zeta^{-1})),\\ t''(\zeta)=-\frac{1}{4}\left(\frac{3}{4}\right)^{1/2}\zeta^{-5/4}(1+O(\zeta^{-1})),\quad t'''(\zeta)=\frac{5}{16}\left(\frac{3}{4}\right)^{1/2}\zeta^{-9/4}(1+O(\zeta^{-1})).
\end{gathered}
\label{eq:t-large-z}
    \end{equation}
From \eqref{eq:zeta-define}--\eqref{eq:zeta-less-than-1} we can easily derive the differential equation
\begin{equation}
    \left(\frac{\dd t}{\dd\zeta}\right)^2(t^2-1)=\zeta.
    \label{eq:t-zeta-ODE}
\end{equation}


\section{Estimates of parabolic cylinder functions}
\label{sec:PC-bounds}
Here we develop some simple estimates for quadratic expressions in the parabolic cylinder functions $U(a,z)$ and $V(a,z)$.  These estimates take different forms depending on whether or not the nonnegative parameter $a\le 0$ is bounded or unbounded.
\subsection{Estimates of $U(a,z)$ and $V(a,z)$ for $a$ bounded}
The parabolic cylinder functions $U(a,z)$ and $V(a,z)$ are jointly entire in $(a,z)\in\mathbb{C}^2$.  Therefore, both functions are bounded on any bidisk $\{|a|<r_a\}\times\{|z|<r_z\}$.  The asymptotic formul\ae\ \eqref{eq:UV-asymp} follow from steepest descent analysis of contour integral representations of $U(a,z)$ and $V(a,z)$, and one can use this analysis to verify that the $O(z^{-2})$ error terms are uniform for bounded $a$.  Therefore if we restrict $a$ to a bounded interval of negative values, say $-\frac{1}{2}M^2\le a\le 0$, and $z$ to nonnegative values $z\ge 0$, then we may bound the real-valued functions $U(a,z)^2$, $V(a,z)^2$, and $U(a,z)V(a,z)$ by a constant on any given finite interval $0\le z\le N^2$, but for unbounded $z>0$ we get bounds instead from the large-$z$ asymptotic \eqref{eq:UV-asymp}.  We therefore define a weight function by setting
\begin{equation}
    W(a,z):=\begin{cases}\left(e^{z^2/4}z^a\right)^2,&\quad z>M\\
    \left(\ee^{M^2/4}M^a\right)^2,&\quad0\le z\le M,
    \end{cases}
\label{eq:PC-weight}
\end{equation}
which has the property that it is positive and nondecreasing as a function of $z\ge 0$.  Then combining a uniform bound for bounded $z$ with the asymptotic behavior \eqref{eq:UV-asymp} proves the following.
\begin{lemma}[Estimates for weighted quadratic expressions in $U(a,z)$ and $V(a,z)$ valid for bounded $a<0$]
Fix $M>0$ and define a weight function $W(a,z)$ by \eqref{eq:PC-weight}.  Then the estimates
\begin{equation}
        U(a,z)^2W(a,z)\lesssim\frac{1}{\sqrt{1+z^2}},\quad 
        V(a,z)^2W(a,z)^{-1}\lesssim\frac{1}{\sqrt{1+z^2}},\quad
        |U(a,z)V(a,z)|\lesssim\frac{1}{\sqrt{1+z^2}}
\end{equation}
hold for $-\frac{1}{2}M^2\le a\le 0$ and $z\ge 0$ (the implied constant depends on $M$).
\label{lem:PC-bound-bounded-a}
\end{lemma}

\subsection{Estimates of $U(a,z)$ and $V(a,z)$ for $a$ large}
Here, we follow \cite[\S 12.10(vii)]{DLMF}, in which for $a<0$, the functions $U(a,z)$ and $V(a,z)$ are written in terms of a rescaled variable $t:=z/\sqrt{-4a}$ exactly in the forms
\begin{equation}
\begin{split}
    U(a,z)&=2\sqrt{\pi}(-2a)^{1/6}G(a)\phi(t)\left[\mathrm{Ai}((-2a)^{2/3}\zeta(t))A^U(t;a) + (-2a)^{-4/3}\mathrm{Ai}'((-2a)^{2/3}\zeta(t))B^U(t;a)\right],\\
    V(a,z)&=2\sqrt{\pi}(-2a)^{1/6}H(a)\phi(t)\left[\mathrm{Bi}((-2a)^{2/3}\zeta(t))A^V(t;a) + (-2a)^{-4/3}\mathrm{Bi}'((-2a)^{2/3}\zeta(t))B^V(t;a)\right],
\end{split}
\label{eq:UV-large-a-exact}
\end{equation}
where $G(a)$ is a well-defined function having asymptotic behavior 
\begin{equation}
    G(a)=\frac{1}{\sqrt{2}}\ee^{a/2}(-a)^{-a/2-1/4}(1+O(a^{-1})),\quad a\to -\infty,
\label{eq:G-expansion}
\end{equation}
$H(a):=G(a)/\Gamma(\frac{1}{2}-a)$ has corresponding behavior
\begin{equation}
    H(a)=\frac{1}{2\sqrt{\pi}}\ee^{-a/2}(-a)^{a/2-1/4}(1+O(a^{-1})),\quad a\to -\infty,
\label{eq:H-expansion}
\end{equation}
$\zeta(t)$ is defined in Appendix~\ref{sec:zeta-t-properties}, and 
\begin{equation}
    \phi(t):=\left(\frac{\zeta(t)}{t^2-1}\right)^{1/4},\quad t>-1,
\end{equation}
where the positive fourth root is meant (of a strictly positive argument).  The coefficients $A^U(t;a)$ and $A^V(t;a)$ are well-defined functions having a common asymptotic expansion:
\begin{equation}
    A^{U,V}(t;a)\sim\sum_{s=0}^\infty A_s(t)(-2a)^{-2s},\quad a\to -\infty,
\label{eq:A-series}
\end{equation}
and likewise the coefficients $B^U(t;a)$ and $B^V(t;a)$ are well-defined and have the same asymptotic expansion:
\begin{equation}
    B^{U,V}(t;a)\sim\sum_{s=0}^\infty B_s(t)(-2a)^{-2s},\quad a\to -\infty,
\label{eq:B-series}
\end{equation}
with all four expansions holding uniformly for $t\ge -1+\delta$ for fixed small $\delta>0$.  The expansion coefficients have the forms
\begin{equation}
\begin{split}   A_s(t)&:=\zeta(t)^{-3s}\sum_{m=0}^{2s}\beta_m\phi(t)^{6(2s-m)}u_{2s-m}(t)\\
B_s(t)&=-\zeta(t)^{-3s-2}\sum_{m=0}^{2s+1}\alpha_m\phi(t)^{6(2s-m+1)}u_{2s-m+1}(t)
\end{split}
\end{equation}
in which $\alpha_m$ and $\beta_m$ are numerical coefficients defined in \cite[12.10.43]{DLMF} the specific values of which we will not need, and $u_k(t)$ is a well-defined polynomial in $t$ with $u_0(t)=1$ and otherwise $u_k(t)$ has degree $3k$ for $k$ odd and $3k-2$ for $k\ge 2$ even.

Since $\zeta(t)$ and $\phi(t)$ are analytic functions for $t>-1$, they are clearly bounded uniformly on compact subsets, and it is easy to see from \eqref{eq:zeta-asymp} that $\phi(t)=(\frac{3}{4})^{1/6}t^{-1/6}(1+O(t^{-1}))$ as $t\to+\infty$.  It is then straightforward to check that for each $s=0,1,2,\dots$, there is a constant $C_s>0$ such that 
\begin{equation}
  |A_s(t)|\le C_s\quad\text{and}\quad|B_s(t)|\le   \frac{C_s}{(1+|t|)^{2/3}},\quad t\ge -1+\delta.
\end{equation}
Hence \eqref{eq:A-series} implies that for $M>0$ sufficiently large,
\begin{equation}
    |A^U(t;a)|\le 2C_0\quad\text{and}\quad |A^V(t;a)|\le 2C_0.
\end{equation}
both hold if $a\le -\frac{1}{2}M^2$ and $t\ge -1+\delta$.
Similarly, \eqref{eq:B-series} implies that for $M>0$ sufficiently large,
\begin{equation}
    |B^U(t;a)|\le \frac{2C_0}{(1+|t|)^{2/3}}\quad\text{and}\quad |B^V(t;a)|\le\frac{2C_0}{(1+|t|)^{2/3}}
\end{equation}
both hold under the same conditions.  Since also $|\phi(t)|\lesssim(1+|t|)^{-1/6}$ for $t\ge -1+\delta$, while \eqref{eq:G-expansion} and \eqref{eq:H-expansion} imply respectively that if $M>0$ is sufficiently large,
\begin{equation}
    \left|(-2a)^{1/6}G(a)\right|\le  (-2a)^{1/6}\cdot 2\frac{1}{\sqrt{2}}\ee^{a/2}(-a)^{-a/2-1/4}=2^{2/3}\ee^{a/2}(-a)^{-a/2-1/12}
\end{equation}
and
\begin{equation}
    \left|(-2a)^{1/6}H(a)\right|\le (-2a)^{1/6}\cdot 2\frac{1}{2\sqrt{\pi}}\ee^{-a/2}(-a)^{a/2-1/4} = \frac{2^{1/6}}{\sqrt{\pi}}\ee^{-a/2}(-a)^{a/2-1/12}
\end{equation}
both hold for $a\le -\frac{1}{2}M^2$, from \eqref{eq:UV-large-a-exact} we obtain
\begin{equation}
\begin{split}
    |U(a,z)|&\lesssim \frac{\ee^{a/2}(-a)^{-a/2-1/12}}{(1+|t|)^{1/6}}\left[\left|\mathrm{Ai}((-2a)^{2/3}\zeta(t))\right| + \frac{(-2a)^{-4/3}}{(1+|t|)^{2/3}}\left|\mathrm{Ai}'((-2a)^{2/3}\zeta(t))\right|\right]\\
    |V(a,z)|&\lesssim \frac{\ee^{-a/2}(-a)^{a/2-1/12}}{(1+|t|)^{1/6}}\left[\left|\mathrm{Bi}((-2a)^{2/3}\zeta(t))\right| + \frac{(-2a)^{-4/3}}{(1+|t|)^{2/3}}\left|\mathrm{Bi}'((-2a)^{2/3}\zeta(t))\right|\right]
\end{split}
\end{equation}
valid for $a\le -\frac{1}{2}M^2$ and $t\ge -1+\delta$.  

Finally, we can apply the estimates
\begin{equation}
    |\mathrm{Ai}(w)|\lesssim\frac{\ee^{-2w^{3/2}_+/3}}{|w|^{1/4}},\quad |\mathrm{Ai}'(w)|\lesssim |w|^{1/4}\ee^{-2w_+^{3/2}/3},\quad|\mathrm{Bi}(w)|\lesssim\frac{\ee^{2w_+^{3/2}/3}}{|w|^{1/4}},\quad|\mathrm{Bi}'(w)|\lesssim|w|^{1/4}\ee^{2w_+^{3/2}/3}
\end{equation}
that hold for all $w\in\mathbb{R}$, where $w_+$ denotes the positive part of $w$, i.e., $w_+=w$ for $w>0$ and $w_+=0$ otherwise.  Thus,
\begin{equation}
    \begin{split}
        |U(a,z)|&\lesssim\frac{\ee^{a/2}(-a)^{-a/2-1/12}}{(1+|t|)^{1/6}}\frac{\ee^{4a\zeta_+(t)^{3/2}/3}}{(-a)^{1/6}|\zeta(t)|^{1/4}}\left[1+(-2a)^{-1}\frac{|\zeta(t)|^{1/2}}{(1+|t|)^{2/3}}\right],\\
        |V(a,z)|&\lesssim\frac{\ee^{-a/2}(-a)^{a/2-1/12}}{(1+|t|)^{1/6}}\frac{\ee^{-4a\zeta_+(t)^{3/2}/3}}{(-a)^{1/6}|\zeta(t)|^{1/4}}\left[1+(-2a)^{-1}\frac{|\zeta(t)|^{1/2}}{(1+|t|)^{2/3}}\right].
    \end{split}
\end{equation}
Since $|\zeta(t)|^{1/2}/(1+|t|)^{2/3}$ is uniformly bounded for $t\ge -1+\delta$ and $a\le -\frac{1}{2}M^2$, we obtain simply
\begin{equation}
        |U(a,z)|\lesssim\frac{\ee^{a/2}(-a)^{-a/2-1/4}\ee^{4a\zeta_+(t)^{3/2}/3}}{(1+|t|)^{1/6}|\zeta(t)|^{1/4}}\quad\text{and}\quad
|V(a,z)|\lesssim\frac{\ee^{-a/2}(-a)^{a/2-1/4}\ee^{-4a\zeta_+(t)^{3/2}/3}}{(1+|t|)^{1/6}|\zeta(t)|^{1/4}}
\end{equation}
both valid for $a\le -\frac{1}{2}M^2$ and $t\ge -1+\delta$.  These imply the following.
\begin{lemma}[Estimates for weighted quadratic expressions in $U(a,z)$ and $V(a,z)$ valid for large $a<0$]
Writing $t:=z/\sqrt{-4a}$ for $a<0$, let a weight function be defined for $t>-1$ by
\begin{equation}
    Y(a,z):=\ee^{-a}(-a)^{a}\ee^{-8a\zeta_+(t)^{3/2}/3}=\begin{cases}\ee^{-a}(-a)^a,& t\le 1,\\
    \ee^{-a}(-a)^a\ee^{-8a\zeta(t)^{3/2}/3},&t>1,
    \end{cases}
    \label{eq:PC-weight-large-a}
\end{equation}
where $\zeta(t)$ is an analytic function of $t>-1$ defined by \eqref{eq:zeta-define}, strictly increasing, with $\zeta(1)=0$ and $\zeta(t)=(\frac{3}{4})^{2/3}t^{4/3}(1+O(t^{-1}))$ as $t\to+\infty$.  Then for $M>0$ sufficiently large and $a\le -\frac{1}{2}M^2$ and $t\ge -1+\delta$, the following estimates hold:
\begin{equation}
\begin{split}
    U(a,z)^2Y(a,z)&\lesssim \frac{1}{(-a)^{1/2}(1+|t|)^{1/3}|\zeta(t)|^{1/2}},\\ V(a,z)^2Y(a,z)^{-1}&\lesssim \frac{1}{(-a)^{1/2}(1+|t|)^{1/3}|\zeta(t)|^{1/2}},\\|U(a,z)V(a,z)|&\lesssim \frac{1}{(-a)^{1/2}(1+|t|)^{1/3}|\zeta(t)|^{1/2}}.
\end{split}
\end{equation}
\label{lem:PC-bound-large-a}
\end{lemma}

