\subsection{Proof of Lemma~\ref{lm:moments} for the mean and variance of Hamming distance}\label{sec:proof-e-var}

\begin{proof}
  Using the definition of Hamming distance~(\ref{eq:hamming}) as a sum of elementary distances $1-\delta_{x_iy_i}\in\{0,1\}$ we have
  \begin{align*}
    \bE_P\{d(x,y)\}&=\bE_P\left\{\sum_{i=1}^l(1-\delta_{x_iy_i})\right\}=\sum_{i=1}^l\bE_P\{1-\delta_{x_iy_i}\}\,,\\
    \sigma_P^2\{d(x,y)\}&=\bE_P\left\{\left(\sum_{i=1}^l(1-\delta_{x_iy_i})\right)^2\right\}-\left(\bE_P\left\{\sum_{i=1}^l(1-\delta_{x_iy_i})\right\}\right)^2\\
                   &=\sum_{i=1}^l\bE_P\{(1-\delta_{x_iy_i})^2\}+\sum_{i=1}^l\sum_{\substack{j=1\\j\neq i}}^l\bE_P\{(1-\delta_{x_iy_i})(1-\delta_{x_jy_j})\} -\\
                   &\hspace{.5\textwidth} - \left(\sum_{i=1}^l\bE_P\{1-\delta_{x_iy_i}\}\right)^2\,,
  \end{align*}
  where we used additivity of the expected value and the square of the sum formula: $\left(\sum_ia_i\right)^2=\sum_ia_i^2 + 2\sum_{i<j}a_ia_j=\sum_ia_i^2 + \sum_i\sum_{j\neq i}a_ia_j$.   Noticing that $(1-\delta_{x_iy_i})^2=1-\delta_{x_iy_i}$ and denoting the average values of the expectations under summations by $\langle P_i\rangle$ and $\langle P_{ij}\rangle$ (see their definitions in Lemma~\ref{lm:moments}) we obtain the following formulae:
  \begin{align*}
    \bE_P\{d(x,y)\}&=l\langle P_i\rangle\,,\\
    \sigma_P^2\{d(x,y)\}&=l\langle P_i\rangle+l(l-1)\langle P_{ij}\rangle-(l\langle P_i\rangle)^2\,.
  \end{align*}
\end{proof}

The symbol $\langle P_i\rangle$ introduced above is the average (over all positions $i\in\{1,\ldots,l\}$) of the probability that $x_i\neq y_i$.  Indeed, the differences $1-\delta_{x_iy_i}$ are non-zero (and equal to one) only when $x_i\neq y_i$, and therefore the expectations $\bE_P\{1-\delta_{x_iy_i}\}$ are the probabilities that letters $x_i\neq y_i$ at positions $i\in\{1,\ldots,l\}$ (and these probabilities can be different for different $i$).

Similarly, $\langle P_{ij}\rangle$ is the average of joint probability that $x_i\neq y_i$ and $x_j\neq y_j$ at two different positions $i\neq j$ (there are $l(l-1)$ off-diagonal elements).  Indeed, the products $(1-\delta_{x_iy_i})(1-\delta_{x_jy_j})$ are non-zero only when both $x_i\neq y_i$ and $x_j\neq y_j$, and the expectations $\bE_P\{(1-\delta_{x_iy_i})(1-\delta_{x_jy_j})\}$ are the corresponding joint probabilities.

\subsection{Proof of Lemma~\ref{lm:spheres} for intersection of spheres in $\cH_\alpha^l$}\label{sec:proof-spheres}

\begin{proof}
  A substitution of letter $x_i$ at position $i\in\{1,\ldots,l\}$ may result in one of three possibilities:
\begin{itemize}
\item Letter $x_i\neq\top_i$ is substituted to $y_i=\top_i$ resulting in a beneficial substitution.  Such substitutions can only occur in $n=d(\top,x)$ letters $x_i\neq\top_i$.  Denoting by $r_+$ the total number of beneficial substitutions gives $\binom{n}{r_+}$ combinations.
\item Letter $x_i=\top_i$ is substituted to any of $\alpha-1$ letters $y_i\neq\top_i$ resulting in a deleterious substitution.  Such substitutions can only occur in $l-d(\top,x)=l-n$ letters $x_i=\top_i$.  Denoting by $r_-$ the total number of deleterious substitutions gives $(\alpha-1)^{r_-}\binom{l-n}{r_-}$ possibilities.
\item Letter $x_i\neq\top_i$ is substituted to one of the remaining $\alpha-2$ letters $y_i\neq\top_i$ resulting in a neutral substitution.  Such substitutions can only occur in $n=d(\top,x)$ letters $x_i\neq\top_i$ minus the number $r_+$ of beneficial substitutions.  Denoting by $r_0$ the total number of neutral substitutions gives $(\alpha-2)^{r_0}\binom{n-r_+}{r_0}$ possibilities.
\end{itemize}
For specific values of $r_+$, $r_-$ and $r_0$, the total number of combinations is
\[
  (\alpha-2)^{r_0}\binom{n-r_+}{r_0}(\alpha-1)^{r_-}\binom{l-n}{r_-}\binom{n}{r_+}\,.
\]
By equations~(\ref{eq:rm-sum}) and (\ref{eq:rm-difference}), the values of $r_-$ and $r_0$ are related to $r_+\in[0,r]$:
\begin{align*}
&r_-=r_+ -(n-m)\,,\\
&r_0=r-(r_++r_-)=r-2r_++(n-m)\,.
\end{align*}
Formula~(\ref{eq:intersection-sphere}) is obtained by summing over all feasible values of $r_+$ subject to constraints $r_-\geq0$ and $r_0\geq0$.%\qed
\end{proof}


\subsection{Proof of Proposition~\ref{pr:mutation}}\label{sec:proof-e-var-mutation}

\begin{proof}
  Here we use formulae~(\ref{eq:e-lp}) and (\ref{eq:var-lp}) with the following average probabilities:
  \begin{align*}
    \langle P_i\rangle&:=\mathbb{P}\{y_i\neq\top_i\mid x\in S(\top,n),y\in S(x,r)\}\,,\\
    \langle P_{ij}\rangle&:=\mathbb{P}\{y_i\neq\top_i\wedge y_j\neq\top_j\mid i\neq j,x\in S(\top,n),y\in S(x,r)\}\,,
  \end{align*}
  where the conditions are defined by the fact that string $y\in S(x,r)\subset\cH_\alpha^l$ is obtained from $x\in S(\top,n)$ by a substitution of $d(x,y)=r$ letters.  Indices $i$ and $j\in\{1,\ldots,l\}$ are positions of letters in the strings $x=(x_1,\ldots,x_l)$, $y=(y_1,\ldots,y_l)$ and $\top=(\top_1,\ldots,\top_l)$.  For each position $i\in\{1,\ldots,l\}$ there are three mutually exclusive possibilities for event $y_i\neq\top_i$:
  \begin{itemize}
  \item Letter $x_i\neq\top_i$ is not substituted, so that $y_i=x_i\neq\top_i$.  The number of letters $x_i\neq\top_i$ is $n=d(\top,x)$, and there are $l-r$ letters that remain not substituted in $y$, which means that the corresponding probability is $(n/l)(1-r/l)$.
  \item Letter $x_i\neq\top_i$ is substituted by $y_i\neq\top_i$, $y_i\neq x_i$.  There are $\alpha-1$ letters in the alphabet not equal to $\top_i$, and there are $\alpha-2$ remaining possibilities for $y_i\neq\top_i$.  Given that there are $n=d(\top,x)$ letters $x_i\neq\top_i$ and $r$ letters are substituted, the corresponding probability is $(n/l)[(\alpha-2)/(\alpha-1)](r/l)$.
  \item Letter $x_i=\top_i$ is substituted by any other letter $y_i\neq\top_i$.  The number of letters $x_i=\top_i$ is $l-n=l-d(\top,x)$, and there are $r$ letters that are substituted, which corresponds to the probability $(1-n/l)(r/l)$.
  \end{itemize}
  Adding the above probabilities for disjoint events gives the desired average probability:
  \[
    \langle P_i\rangle=\frac{n}{l}\left(1-\frac{r}{l}\right)+\frac{n}{l}\left(\frac{\alpha-2}{\alpha-1}\right)\frac{r}{l}+\left(1-\frac{n}{l}\right)\frac{r}{l}\,.
  \]
  Because $\langle P_i\rangle$ is the average probability across all positions $i\in\{1,\ldots,l\}$, its value is the same for all $i$, and the expected value $\bE_P\{m\mid n,r\}$ can be computed as $l\langle P_i\rangle$.  Its expression can be simplified as follows:
  \[
    l\langle P_i\rangle=n\left(1-\frac{1}{\alpha-1}\frac{r}{l}\right)+(l-n)\frac{r}{l}\,.
  \]
  The expression above can also be transformed into formula~(\ref{eq:e-mutation}).

  The average joint probability $\langle P_{ij}\rangle:=\mathbb{P}\{y_i\neq\top_i\wedge y_j\neq\top_j\mid i\neq j,n,r\}$ is factorized into the product $\mathbb{P}\{y_i\neq\top_i\mid n,r\}\mathbb{P}\{y_j\neq\top_j\mid y_i\neq\top_i,i\neq j,n,r\}$, where the first probability for the first event $z_i\neq\top_i$ is the average probability $\langle P_i\rangle$ derived above.  The second is the average conditional probability of the second event $z_j\neq\top_j$ for $j\neq i$ (and conditioned on the first event $z_i\neq\top_i$).  This conditional probability can be determined from the following considerations.

  For each of the three possibilities for $y_i\neq\top_i$ in the string of length $l$, there are three possibilities for $y_j\neq\top_j$ in the remaining string of length $l-1$.  Thus, there are $3\times 3=9$ joint events, the probabilities of which are defined similarly, but using numbers $n-1$ or $n$ and $r-1$ or $r$ depending on the type and position of the first event $y_i\neq\top_i$.  Thus, the product $l(l-1)\langle P_{ij}\rangle$ is as follows:
  \begin{align*}
    l(l-1)\langle P_{ij}\rangle=n\left(1-\frac{r}{l}\right)&\left[(n-1)\left(1-\frac{1}{\alpha-1}\frac{r}{l-1}\right)+(l-n)\frac{r}{l-1}\right]\\
                +n\left(\frac{\alpha-2}{\alpha-1}\right)\frac{r}{l}&\left[(n-1)\left(1-\frac{1}{\alpha-1}\frac{r-1}{l-1}\right)+(l-n)\frac{r-1}{l-1}\right]\\
                +(l-n)\frac{r}{l}&\left[n\left(1-\frac{1}{\alpha-1}\frac{r-1}{l-1}\right)+(l-1-n)\frac{r-1}{l-1}\right]\,.
  \end{align*}
  Formula~(\ref{eq:var-mutation}) for the variance is obtained by substituting the expressions for $l\langle P_i\rangle$ and $l(l-1)\langle P_{ij}\rangle$ into equation $l\langle P_i\rangle+l(l-1)\langle P_{ij}\rangle-(l\langle P_i\rangle)^2$.
  % \qed
\end{proof}

\subsection{Proof of Proposition~\ref{pr:dual}}\label{sec:pr:dual}

\begin{proof}
  Let us denote by $r'=l-r$ the recombination radius of the dual recombination $z'$, and let $r_+'$, $r_-'$ and $r_0'$ be respectively the numbers of beneficial, deleterious and neutral substitutions into $x$.  Because the dual recombination is a substitution of the remaining $l-r$ letters, we have
  \[
    r_++r_+'=h_+\,, \qquad r_-+r_-'=h_-\,.
  \]
  Using the above equations and equations~(\ref{eq:rr-difference}), (\ref{eq:nr-difference}) we have
  \begin{align*}
    r_+'-r_-'&=h_+-h_--(r_+-r_-)\\
            &=(n-k)-(n-m)\,.
  \end{align*}
  On the other hand, by analogy with equation~(\ref{eq:rr-difference}), we have
  \begin{equation}
    r_+'-r_-'=n-m'\,. \label{eq:rr-difference-2}
  \end{equation}
  Therefore, $n-k-(n-m)=m-k=n-m'$.
\end{proof}

\subsection{Proof of Proposition~\ref{pr:recombination}}\label{sec:proof-e-var-recombination}

\begin{proof}
  Here we use formulae~(\ref{eq:e-lp}) and (\ref{eq:var-lp}) with the following average probabilities
  \begin{align*}
    \langle P_i\rangle&:=\mathbb{P}\{z_i\neq\top_i\mid x\in S(\top,n),y\in S(\top,k),d(x,y)=h,r\}\,,\\
    \langle P_{ij}\rangle&:=\mathbb{P}\{z_i\neq\top_i\wedge z_j\neq\top_j\mid i\neq j,x\in S(\top,n),y\in S(\top,k),d(x,y)=h,r\}\,,
  \end{align*}
  where the conditions are defined by the fact that string $z\in S(\top,m)\subset\cH_\alpha^l$ is obtained from $x\in S(\top,n)$ by a substitution of $r\in[0,l]$ letters from string $y\in S(\top,k)\cap S(x,h)$.  Indices $i$ and $j\in\{1,\ldots,l\}$ are positions of letters in the strings.  For each position $i\in\{1,\ldots,l\}$ there are two mutually exclusive possibilities for $z_i\neq\top_i$:
  \begin{itemize}
  \item Letter $x_i\neq\top_i$ is not substituted by $y_i$, so that in the offspring $z_i=x_i\neq\top_i$.  The number of letters $x_i\neq\top_i$ is $n=d(\top,x)$, and there are $l-r$ letters that remain not substituted in $z$, which means that the corresponding probability is $(n/l)(1-r/l)$.
  \item Letter $x_i=\top_i$ is substituted by letter $y_i\neq\top_i$, so that in the offspring $z_i=y_i\neq\top_i$.  The number of letters $y_i\neq\top_i$ is $k=(\top,y)$, and there are $r$ letters that are substituted, which corresponds to probability $(k/l)(r/l)$.
  \end{itemize}
  Adding the above probabilities for disjoint events gives the desired average probability:
  \[
    \langle P_i\rangle=\frac{n}{l}\left(1-\frac{r}{l}\right)+\frac{k}{l}\frac{r}{l}\,.
  \]
  Because $\langle P_i\rangle$ is the average probability across all positions $i\in\{1,\ldots,l\}$, its value is the same for all $i$, and the expected value $\bE_P\{m\mid n,k,h,r\}$ can be computed as $l\langle P_i\rangle$:
  \[
    l\langle P_i\rangle=n\left(1-\frac{r}{l}\right)+k\frac{r}{l}\,.
  \]
  The above expression gives formula~(\ref{eq:e-recombination}).

  The average joint probability $\langle P_{ij}\rangle:=\mathbb{P}\{z_i\neq\top_i\wedge z_j\neq\top_j\mid i\neq j,n,k,h,r\}$ is factorized into the product $\mathbb{P}\{z_i\neq\top_i\mid n,k,h,r\}\mathbb{P}\{z_j\neq\top_j\mid z_i\neq\top_i,i\neq j,n,k,h,r\}$, where the first probability for the first event $z_i\neq\top_i$ is the average probability $\langle P_i\rangle$ derived above.  The second is the average conditional probability of the second event $z_j\neq\top_j$ for $j\neq i$ (and conditioned on the first event $z_i\neq\top_i$).  This conditional probability can be determined from the following considerations.

  Let us decompose each of the two cases of the first event $z_i\neq\top_i$ into three subcases resulting in $2\times 3 = 6$ mutually exclusive subcases of event $z_i\neq\top_i$.  These subcases were not considered for the probability $\langle P_i\rangle$, because it concerns only one index $i$.  When two indices $i$ and $j\neq i$ are considered for the joint probability $\langle P_{ij}\rangle$, these subcases are important, because they influence the numbers that are required for the probability of the second event $z_j\neq\top_j$.

  First, let us consider when any of $n$ letters $x_i\neq\top_i$ are not substituted by $y_i$.  There are three subcases for such non-substitutions.  They can be among
  \begin{enumerate}
  \item $h_+$ letters $y_i=\top_i$ (i.e. some of $h_+$ possible beneficial substitutions do not occur).
  \item $h_0$ letters $y_i\neq\top_i$, $y_i\neq x_i$ (i.e. some of $h_0$ neutral substitutions do not occur).
  \item $n-h_0-h_+$ identical letters $y_i=x_i\neq\top_i$.
  \end{enumerate}
  If a non-substitution occurs at position $i$, then the number $n$ reduces to $n-1$, but the recombination radius $r$ remains the same.  The number $k$ of letters $y_i\neq\top_i$ remains the same in the first subcase (because $x_i\neq\top_i$ was not substituted by one of $l-k$ letters $y_i=\top_i$), but it reduces to $k-1$ in the last two subcases.  The length $l$ of the remaining string is $l-1$.

  Second, let us consider when letters $x_i$ are substituted by any of $k$ letters $y_i\neq\top_i$.  Again, there are three subcases for such substitutions.  They can be among
  \begin{enumerate}
  \item $h_-$ letters $y_i\neq\top_i$ (i.e. some of $h_-$ possible deleterious substitutions occur).
  \item $h_0$ letters $y_i\neq\top_i$, $y_i\neq x_i$ (i.e. some of $h_0$ neutral substitutions occur).
  \item $k-h_0-h_-$ identical letters $y_i=x_i\neq\top_i$.
  \end{enumerate}
  Note that $k-h_0-h_-=n-h_0-h_+$, which follows from $h_+-h_-=n-k$.  If a substitution by letter $y_i\neq\top_i$ occurs at position $i$, then the number $k$ reduces to $k-1$, and the recombination radius $r$ reduces to $r-1$.  The number $n$ of letters $x_i\neq\top_i$ remains the same in the first subcase (because one of $l-n$ letters $x_i=\top_i$ was substituted by $y_i\neq\top_i$), but it reduces to $n-1$ in the last two subcases.  The length $l$ of the remaining string is $l-1$.

  For each of the six subcases, there are two possibilities for the second event $z_j\neq\top_j$ in the remaining string of length $l-1$, so that there are $6\times 2=12$ joint events.  Note that the values $h_+$, $h_0$ and $h_-$ are generally random and related by equations~(\ref{eq:nr-sum}) and (\ref{eq:nr-difference}).  Thus, initially we derive the formula for the product $l(l-1)\langle P_{ij}\rangle$ assuming that specific values of $h_+$, $h_0$ and $h_-$ have been fixed:
  \begin{align*}
    l(l-1)\langle P_{ij}\rangle=\left(1-\frac{r}{l}\right)\Biggl\{h_+&\left[(n-1)\left(1-\frac{r}{l-1}\right)+k\frac{r}{l-1}\right]\\
    +h_0&\left[(n-1)\left(1-\frac{r}{l-1}\right)+(k-1)\frac{r}{l-1}\right]\\
    +(n-h_0-h_+)&\left[(n-1)\left(1-\frac{r}{l-1}\right)+(k-1)\frac{r}{l-1}\right]\Biggr\}\\
    +\frac{r}{l}\Biggl\{h_-&\left[n\left(1-\frac{r-1}{l-1}\right)+(k-1)\frac{r-1}{l-1}\right]\\
    +h_0&\left[(n-1)\left(1-\frac{r-1}{l-1}\right)+(k-1)\frac{r-1}{l-1}\right]\\
    +(k-h_0-h_-)&\left[(n-1)\left(1-\frac{r-1}{l-1}\right)+(k-1)\frac{r-1}{l-1}\right]\Biggr\}
  \end{align*}
  The formula above contains six lines corresponding to six subcases of the first event $z_i\neq\top_i$: three non-substitutions of $x_i\neq\top_i$ and three substitutions of $x_i=\top_i$.  Expressions in square brackets on each line correspond to two cases of the second event $z_j\neq\top_j$, $j\neq i$: non-substitutions of $x_j\neq\top_j$ and substitutions of $x_j=\top_j$.  Factoring and noticing that $h_++h_0+n-h_0-h_+=n$ and $h_-+h_0+k-h_0-h_-=k$ we obtain:
  \begin{align*}
    l(l-1)\langle P_{ij}\rangle=\left(1-\frac{r}{l}\right)\Biggl\{n&\left[(n-1)\left(1-\frac{r}{l-1}\right)+(k-1)\frac{r}{l-1}\right]+h_+\frac{r}{l-1}\Biggr\}\\
    +\frac{r}{l}\Biggl\{k&\left[(n-1)\left(1-\frac{r-1}{l-1}\right)+(k-1)\frac{r-1}{l-1}\right] + h_-\left(1-\frac{r-1}{l-1}\right)\Biggr\}
  \end{align*}
  The right-hand-side of the above equation can be written as
  \begin{align*}
    \left(1-\frac{r}{l}\right)\Biggl\{n&\left[(n-1)\left(1-\frac{r-1}{l-1}\right)+(k-1)\frac{r-1}{l-1}\right]+n\left(\frac{k-1}{l-1}-\frac{n-1}{l-1}\right)+h_+\frac{r}{l-1}\Biggr\}\\
    +\frac{r}{l}\Biggl\{k&\left[(n-1)\left(1-\frac{r-1}{l-1}\right)+(k-1)\frac{r-1}{l-1}\right] + h_-\left(1-\frac{r-1}{l-1}\right)\Biggr\}\,,
  \end{align*}
  which allows us to factor the members as follows:
  \begin{multline*}
    \left[\left(1-\frac{r}{l}\right)n+\frac{r}{l}k\right]\left[\left(1-\frac{r-1}{l-1}\right)(n-1)+\frac{r-1}{l-1}(k-1)\right]+\\
     +\left(1-\frac{r}{l}\right)\left(\frac{n}{l-1}(k-n) + h_+\frac{r}{l-1}\right) + \frac{r}{l}h_-\left(1-\frac{r-1}{l-1}\right)\,.
  \end{multline*}
  Substituting $h_-=h_++(k-n)$ the expression for $l(l-1)\langle P_{ij}\rangle$ becomes
  \begin{multline*}
    \left[\left(1-\frac{r}{l}\right)n+\frac{r}{l}k\right]\left[\left(1-\frac{r-1}{l-1}\right)(n-1)+\frac{r-1}{l-1}(k-1)\right]+\\
    +\left(1-\frac{r}{l}\right) \frac{(n+r)(k-n)+2rh_+}{l-1}\,.
  \end{multline*}
  It can now be combined with the expression for $l\langle P_i\rangle$ in equation $l\langle P_i\rangle+l(l-1)\langle P_{ij}\rangle-(l\langle P_i\rangle)^2$ to derive the variance formula with fixed $h_+$:
  \begin{align*}
    \sigma_P^2\{m\mid n,k,h,r,h_+\}&=\frac{l2h_+-k^2+lk+2nk-ln-n^2}{l^2(l-1)}r(l-r)\\
                                 &=\frac{l[2h_+ - (n - k)] - k^2 + 2nk - n^2}{l^2(l-1)}r(l-r)\\
                                 &=\left[2h_+ - (n - k) - \frac{(n - k)^2}{l}\right]\frac{r(l-r)}{l(l-1)}\\
                                 &=\left[h-h_0 - \frac{(n-k)^2}{l}\right]\frac{r(l-r)}{l(l-1)}\,.
  \end{align*}
  Formula~(\ref{eq:var-recombination}) for the variance is obtained by averaging over all possible values of $h_+$ or $h_0=h-2h_++n-k$, which means that they are replaced by their expected values $\langle h_+\rangle$ or $\langle h_0\rangle:=\bE\{h_0\mid n,k,h\}$ with respect to $P(h_+\mid n,k,h)$~(\ref{eq:p-h+}).
\end{proof}

\subsection{Proof of Proposition~\ref{pr:symmetry}}\label{sec:proof-symmetry}

\begin{proof}
  Looking at factorization~(\ref{eq:p-recombination-marginal}) of probability $P(m\mid n,k,h,r)$, one can see that probability $P(h_+\mid n,k,h)$ does not influence the result, because it does not include variables $m$ and $r$.  Thus, we only need to consider probability $P(m\mid n,k,h,r,h_+)$ given by equation~(\ref{eq:p-intersection-h+}).  Using symmetry of binomial coefficients $\binom{l}{r}=\binom{l}{l-r}$, one can see that
  \[
    \binom{l-h_+-h_-}{r-r_+-r_-}\binom{h_-}{r_-}\binom{h_+}{r_+}=
    \binom{l-h_+-h_-}{r'-r'_+-r'_-}\binom{h_-}{r'_-}\binom{h_+}{r'_+}\,,
  \]
  where $r'=l-r$, $r'_+=h_+-r_+$ and $r'_-=h_--r_-$.  Note that $r'=l-r$ is recombination radius of the dual recombination $z'=(1-\lambda)y\oplus\lambda x$, and $r'=r'_++r'_-+r'_0$.  Therefore, $P(m\mid n,k,h,r,h_+)=P(m'\mid n,k,h,l-r,h_+)$, where $m'=n+k-m$ by Proposition~\ref{pr:dual}.%\qed
\end{proof}


