\begin{algorithm}
\caption{MeZO \citep{malladi2023fine}}
\label{alg:mezo}
\begin{algorithmic}[1]
\Require Model parameters $\theta \in \mathbb{R}^d$, loss function $L : \mathbb{R}^d \rightarrow \mathbb{R}$, training iterations $T$, perturbation step size $\epsilon$, data batch $B$, learning rate $\eta_t$
\For{$j = 1, \dots, T$}
    \State Set random seed $s$ and sample batch $B \subset D$
    \State $\theta \leftarrow \text{PerturbParameters}(\theta, \epsilon)$
    \State $\ell_+ \leftarrow L(\theta; B)$
    \State Reset RNG with seed $s$
    \State $\theta \leftarrow \text{PerturbParameters}(\theta, -2\epsilon)$
    \State $\ell_- \leftarrow L(\theta; B)$
    \State Reset RNG with seed $s$
    \State $\theta \leftarrow \text{PerturbParameters}(\theta, \epsilon)$
    \State $g \leftarrow (\ell_+ - \ell_-) / (2\epsilon)$
    \State Reset RNG with seed $s$
    \State $\theta \leftarrow \text{UpdateParameters}(\theta, g)$
\EndFor
\Statex
\Function{UpdateParameters}{$\theta, g$}
    \For{each $\theta_i \in \theta$, where $\theta_i \in \mathbb{R}^{d_i}$}
        \State $z_i \sim \mathcal{N}(0,1) \in \mathbb{R}^{d_i}$
        \State $\theta_i \leftarrow \theta_i - \eta_t \cdot g \cdot z_i$
    \EndFor
    \State \Return $\theta$
\EndFunction
\Statex
\Function{PerturbParameters}{$\theta, \epsilon$}
    \For{each $\theta_i \in \theta$, where $\theta_i \in \mathbb{R}^{d_i}$}
        \State $z_i \sim \mathcal{N}(0,1) \in \mathbb{R}^{d_i}$
        \State $\theta_i \leftarrow \theta_i + \epsilon z_i$
    \EndFor
    \State \Return $\theta$
\EndFunction
\end{algorithmic}
\end{algorithm}


\begin{figure}[htbp]
    \centering
    \includegraphics[width=\linewidth]{figures/zo2.png}
    \caption{ZO2 \citep{wang2025zo2scalablezerothorderfinetuning} workflow.}
    \label{fig:zo2}
\end{figure}


\begin{algorithm}
\caption{ZO2 \citep{wang2025zo2scalablezerothorderfinetuning} Computation with RNG State Manager}
\label{alg:zo2}
\begin{algorithmic}[1]
\Require{Transformer blocks $\{W_i\}_{i=1}^N$ with number of transformer blocks $N$, embedding parameters $Embedding$, and LM head $LM head$, module parameter $\theta$, module forward function $forward$, loss function $L$, training iterations $T$, perturbation step size $\epsilon$, data batch $B$, learning rate $\eta_t$, random seed $s$, random state buffer $rsb$, last iteration's random state $lrs$.}
\State Initialize $g=0$.
\For{$j = 1, \dots, T$}
    \State Set random seed $s$ and sample batch $B \subset D$
    \State Get random state $rs$ = GetRngState($s$), and push $rs$ into $rsb$.
    \If{$j$ > 1}
        \State Update last iteration's random state $lrs$ = PopLeft($rsb$)
    \Else
        \State $lrs$ = $None$
    \EndIf
    \State $out_+, out_-, rs, lrs$ = DualForward(
        \Statex $Embedding, \epsilon, s, rs, lrs, g, B, B$)
    \For{$i=1$ to $N$}
        \State $out_+, out_-, rs, lrs$ = DualForward(
        \Statex $W_i, \epsilon, s, rs, lrs, g, out_+, out_-$)
    \EndFor
    \State $out_+, out_-, rs, lrs$ = DualForward(
    \Statex $LM head, \epsilon, s, rs, lrs, g, out_+, out_-$)
    \State $\ell_+ = L(out_+)$, $\ell_- = L(out_-)$
    \State $g \leftarrow (\ell_+ - \ell_-) / (2\epsilon)$
\EndFor
\Statex
\Function{DualForward}{$\theta, \epsilon, s, rs, lrs, g, input_+, input_-$}
    \If{$g$ != 0}
        \State SetRngState($s, lrs$)
        \State $\theta, lrs \leftarrow$ UpdateParameters($\theta, g$)
    \EndIf
    \State SetRngState($s, rs$), $\theta \leftarrow \text{PerturbParameters}(\theta, \epsilon)$
    \State $out_+ \leftarrow forward(\theta; input_+)$
    \State SetRngState($s, rs$), $\theta \leftarrow \text{PerturbParameters}(\theta, -2\epsilon)$
    \State $out_- \leftarrow forward(\theta; input_-)$
    \State SetRngState($s, rs$), $\theta \leftarrow \text{PerturbParameters}(\theta, \epsilon)$
    \State $rs$ = GetRngState($s$)
    \State \Return $out_+, out_-, rs, lrs$
\EndFunction
\Statex
\Function{SetRngState}{$s, rs$}
    \State Store $rs$ associated with seed $s$. 
\EndFunction
\Statex
\Function{GetRngState}{$s$}
    \State \Return $rs$ associated with seed $s$ from the storage.
\EndFunction
\Statex
\Function{UpdateParameters}{$\theta, g$}
    \State Same as Algorithm \ref{alg:mezo}'s UpdateParameters
\EndFunction
\Statex
\Function{PerturbParameters}{$\theta, \epsilon$}
    \State Same as Algorithm \ref{alg:mezo}'s PerturbParameters
\EndFunction
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[htbp]
\caption{ZO2 \citep{wang2025zo2scalablezerothorderfinetuning} Dynamic Scheduler}
\label{alg:zo2-scheduler}
\begin{algorithmic}[1]
\Require{Transformer blocks $\{W_i\}_{i=1}^N$ with number of transformer blocks $N$, embedding parameters $Embedding$, and LM head $LM head$}.
\State Initialize a dynamic scheduler $S\{ \cdot \}$ to control dual forward computation $C( \cdot )$, uploading $U( \cdot )$, and offloading $O( \cdot )$ operations.
\State Asynchronously launch $S\{C(Embedding), U(W_1)\}$.
\For{$i=1$ to $N-1$}
    \State Synchronously wait until $U(W_i)$ finished.
    \If{$i=1$}
        \State Asynchronously launch $S\{C(W_{i}), U(W_{i+1})\}$.
    \Else
        \State Synchronously wait until $C(W_{i-1})$ finished.
        \State Asynchronously launch $S\{O(W_{i-1}), C(W_{i}), U(W_{i+1})\}$.
    \EndIf
\EndFor
\State Synchronously wait until $C(W_{N-1})$ and $U(W_N)$ finished.
\State Asynchronously launch $S\{O(W_{N-1}), C(W_N)\}$.
\State Synchronously wait until $C(W_N)$ finished.
\State Asynchronously launch $S\{O(W_N), C(LM head)\}$.
\end{algorithmic}
\end{algorithm}

\section{Full Related Work} \label{sec:related-work}

Zeroth-order (ZO) optimization has emerged as a memory-efficient alternative for fine-tuning large language models (LLMs), as it avoids backward passes by estimating gradients using forward-only computations. MeZO~\citep{malladi2023fine} and ZO2~\citep{wang2025zo2scalablezerothorderfinetuning} demonstrate that ZO methods can significantly reduce memory usage and enable tuning of multi-hundred-billion-parameter models on a single GPU. However, these methods suffer from low throughput and poor scalability. 

\subsection{Zeroth-Order Optimization}

Zeroth-order (ZO) optimization provides a gradient-free alternative to first-order methods by estimating gradients solely from function evaluations. Foundational approaches such as random perturbation-based gradient estimation~\citep{flaxman2004online} and two-point finite differences~\citep{nesterov2017random} have established theoretical guarantees under smoothness assumptions. ZO methods have found applications in black-box adversarial attacks~\citep{chen2017zoo}, reinforcement learning~\citep{salimans2017evolution}, and model-agnostic optimization.

Despite scalability concerns due to dimension-dependent query complexity, techniques such as block-coordinate estimation~\citep{cai2021zeroth} and sparsity-aware gradient estimation~\citep{cai2022zeroth} have been proposed to improve efficiency in high-dimensional settings.

\subsection{Zeroth-Order Optimization for LLM Fine-Tuning}

As large language models (LLMs) grow in scale, memory-efficient fine-tuning becomes increasingly critical. MeZO~\citep{malladi2023fine} introduced a backpropagation-free fine-tuning framework using ZO-SGD, enabling forward-only updates with drastically reduced memory footprint. This approach eliminates the need to store activation states and gradient tensors, allowing large-scale models to be fine-tuned on commodity hardware.

Subsequent work~\citep{zhang2024revisitingzerothorderoptimizationmemoryefficient} expanded the study of ZO methods by benchmarking a wide range of optimizers, including ZO-Adam, momentum-based ZO-SGD, and block-wise strategies. These improvements yield better stability and convergence, although most assume the full model fits in GPU memory.

More recently, ZO2~\citep{wang2025zo2scalablezerothorderfinetuning} demonstrated that ZO optimization is particularly well-suited for CPU offloading due to its forward-only execution pattern. ZO2 introduces system-level innovations such as an RNG state manager, a lightweight CUDA stream-based scheduler, and AMP-aware low-bit communication. These enable efficient fine-tuning of models up to 175B parameters using just 18GB of GPU memory, without sacrificing accuracy or throughput.

Together, these works show that ZO-based fine-tuning, once considered too inefficient for large-scale models, is becoming a practical solution for memory-constrained LLM training.

\subsection{Distributed Computing}

Meanwhile, distributed training strategies such as Distributed Data Parallelism (DDP)~\citep{li2020pytorchdistributedexperiencesaccelerating} is widely used in first-order training~\citep{ruder2017overviewgradientdescentoptimization, loshchilov2017decoupled}, but require adaptation for ZO due to its scalar-gradient nature and dual forward passes. In particular, DDP must synchronize scalar gradients and coordinate consistent perturbation vectors across devices. These adaptations are non-trivial and introduce scheduling and communication challenges.

To address these, DistZO2 first introduces Perturbation Parallelism (PertP), and then adapts DDP to support ZO training. Furthermore, it proposes a unified 2D parallelism framework that combines PertP with DDP, enabling parallelism along both perturbation and data dimensions. It further proposes a hardware-aware communication strategy that slices parameter blocks and redistributes them via fast interconnects like NVLink to alleviate PCIe bottlenecks. These innovations allow DistZO2 to significantly improve throughput while preserving ZO2’s memory efficiency. Our approach is also compatible with recent forward acceleration techniques such as FlashAttention~\citep{dao2023flashattention2fasterattentionbetter} and \texttt{torch.compile}~\citep{ansel2024pytorch}, which further emphasize the need for efficient communication in forward-only training.

