\subsubsection{Detailed Dynamics}

\textls[-15]{Hawking radiation arises from quantum fluctuations near the event horizon, where particle--antiparticle pairs are created~\cite{Hawking1975}. In the standard picture, one particle falls into the black hole, while the other escapes to infinity. The escaping particles form Hawking radiation, which is traditionally considered to be purely thermal and uncorrelated with the infalling matter. In the QMM framework, the outgoing Hawking radiation interacts with the QMM, allowing information stored in quantum imprints to influence the radiation. The interaction Hamiltonian between the QMM and the Hawking radiation is provided by  Equation~\eqref{eq:hawking_interaction_hamiltonian}. The cumulative imprint operator $\hat{I}_{\text{HR}}$ is defined as the sum over all imprints at the event horizon:}
\vspace{-1pt}
\begin{equation}
\hat{I}_{\text{HR}} = \sum_{x \in \mathcal{H}} \hat{I}_x
\label{eq:cumulative_imprint}
\end{equation}
where $\mathcal{H}$ denotes the set of space--time quanta at the event horizon.

The initial state of the Hawking radiation can be modeled as a vacuum state $|0\rangle_{\text{HR}}$ with no particles. The total initial state is then

\begin{equation}
|\Psi(0)\rangle = |\Psi_{\text{fields}}(0)\rangle \otimes |\Psi_{\text{QMM}}(0)\rangle \otimes |0\rangle_{\text{HR}}.
\end{equation}

{Under the combined Hamiltonian $\hat{H} = \hat{H}_{\text{fields}} + \hat{H}_{\text{QMM}} + \hat{H}_{\text{int}} + \hat{H}_{\text{HR}}$, the state evolves~as follows:}
\vspace{-3pt}
\begin{equation}
|\Psi(t)\rangle = e^{-i\hat{H}t/\hbar} |\Psi(0)\rangle.
\label{eq:total_time_evolution}
\end{equation}

\textls[-20]{The interaction Hamiltonian $\hat{H}_{\text{HR}}$ causes entanglement between the QMM and the Hawking radiation. This entanglement allows information stored in the QMM to be transferred to the outgoing radiation. We can express the state of the Hawking radiation after interaction as}

\begin{equation}
|\Psi_{\text{HR}}(t)\rangle = \sum_{\{n_k\}} C_{\{n_k\}}(t) |\{n_k\}\rangle_{\text{HR}} \otimes |\chi_{\{n_k\}}\rangle_{\text{QMM}},
\label{eq:hawking_state}
\end{equation}
where:

\begin{itemize}
    \item $\{n_k\}$ represents the occupation numbers of the Hawking radiation modes.
    \item $C_{\{n_k\}}(t)$ are time-dependent coefficients.
    \item $|\chi_{\{n_k\}}\rangle_{\text{QMM}}$ are states of the QMM correlated with the radiation modes.
\end{itemize}

The presence of correlations between the radiation modes and QMM states indicates that the Hawking radiation carries information about the quantum imprints, and consequently about the infalling matter.

\subsubsection{Concrete Example}

\textls[-20]{While a full numerical simulation of this process requires extensive computational resources and a detailed model of the QMM dynamics, we can consider a simplified example. Assume that the Hawking radiation consists of a single mode $k$ and that the QMM has two relevant states $|0\rangle_{\text{QMM}}$ and $|1\rangle_{\text{QMM}}$, respectively corresponding to the absence or presence of a quantum imprint.}

The interaction Hamiltonian simplifies to

\begin{equation}
\hat{H}_{\text{HR}} = \gamma \left( \hat{a}_k^\dagger \otimes \hat{\sigma}_+ + \hat{a}_k \otimes \hat{\sigma}_- \right),
\label{eq:simplified_hamiltonian}
\end{equation}
where $\hat{\sigma}_+ = |1\rangle_{\text{QMM}} \langle 0|$ and $\hat{\sigma}_- = |0\rangle_{\text{QMM}} \langle 1|$ are the raising and lowering operators for the two-level QMM system and $\gamma$ is a coupling constant.

Starting from the initial state $|0\rangle_{\text{HR}} \otimes |1\rangle_{\text{QMM}}$, the evolution under $\hat{H}_{\text{HR}}$ leads to

\begin{equation}
|\Psi(t)\rangle = \cos(\gamma t) |0\rangle_{\text{HR}} \otimes |1\rangle_{\text{QMM}} - i \sin(\gamma t) |1\rangle_{\text{HR}} \otimes |0\rangle_{\text{QMM}}.
\end{equation}

At time $t = \pi/(2\gamma)$, the state becomes

\begin{equation}
|\Psi\left( \tfrac{\pi}{2\gamma} \right)\rangle = -i |1\rangle_{\text{HR}} \otimes |0\rangle_{\text{QMM}}.
\end{equation}

This indicates that the information initially stored in the QMM has been transferred to the Hawking radiation mode.



