\section{First example: Painlev\'e III$_3$}
\label{sec:three}

In this section we will study in detail the Joyce structure of class $S[A_1]$ labelled by the genus $g=0$ and pole orders $m=(3,3)$. This is the Joyce structure associated to the DT theory of the   Kr\"onecker 2-quiver.  The base parameterises quadratic differentials on $\bP^1$  with 2 poles of order 3, and simple zeros.
%\begin{equation}Q_0(x)  \, dx^{\tensor 2}= \frac{1}{x^2}\left(tx+H +x^{-1}\right) dx^{\tensor 2},\end{equation}
The corresponding Painlev\'e equation is the  III\,(D$_8$) equation, also known as Painlev\'e III$_3$, associated to perhaps the most famous class $S$ theory: pure $SU(2)$ super Yang-Mills, the original setting of Seiberg-Witten theory \cite{Seiberg1994,Bonelli2017}.

\subsection{Higgs field and quadratic differential}

Take $q,t\in \bC^*$ and $p\in \bC$ and consider the meromorphic Higgs field $\Phi=\Phi(x) \, \dd x$ on the trivial rank 2 vector bundle over $\bP^1$ defined by

\begin{equation}
\Phi(x)=\frac{1}{x^2}\left(\begin{array}{cc}
		0 & -q \\
		0 & 0
	\end{array} \right)+\frac{1}{x}\left(\begin{array}{cc}
		pq & 1 \\
		-q^{-1} & -pq
	\end{array} \right)+
	\left(\begin{array}{cc}
		0 & 0 \\
		t & 0
	\end{array} \right).
\end{equation}
Note  that $\Phi$ has double poles at $x=0$  and $x=\infty$ with nilpotent leading order behaviour. Thus $x=0$ and $x=\infty$ are irregular singularities of the connection $d-\Phi$ of Poincar\'e rank $\frac{1}{2}$.

Then matrix $\Phi(x)$ is a Lax matrix for the Painlev\'e III$_3$ equation (see for example \cite[Section 2]{Gavrylenko2017})
\begin{equation}\label{eq:PIII}
\frac{\dd^2q}{\dd t^2}=\frac{1}{q}\left(\frac{\dd q}{\dd t} \right)^2-\frac{1}{t}\frac{\dd q}{\dd t}+\frac{2q^2}{t}-\frac{2}{t^2},
\end{equation}
in the sense that \eqref{eq:PIII} describes isomonodromic deformation of the connection $\dd-\Phi$.



A slight complication in this case is that the poles are branch points of the spectral curve, so that one would need to modify the connection along the lines of \cite[Section 2.1]{Gavrylenko2017}  in order for equations \eqref{eq:tH} to hold. We will circumvent this issue by introducing the parameter $H$ simply as
\begin{equation}\label{eq:PIIIHam}
    H=\Res_{x=0} \left(\frac{x}{2} \tr\Phi(x)^2\,dx\right)=p^2q^2-tq-q^{-1}.
\end{equation}

Since $t\in \bC^*$, the spectral invariant
\begin{equation}\label{qu} \frac{1}{2} \tr(\Phi^2)= Q_0(x)  \, dx^{\tensor 2}= \frac{1}{x^2}\left(tx+H +x^{-1}\right) dx^{\tensor 2}\end{equation}
is a meromorphic quadratic differential  on $\bP^1$ with poles of order 3 at the points $x=0$ and $x=\infty$. Conversely any quadratic differential  on $\bP^1$ with  2 poles of order 3 and no other poles  can be put in the form \eqref{qu} by applying an automorphism of $\bP^1$.

The base $M$ of our Joyce structure will parameterise  differentials of the form \eqref{qu} which have simple zeros. Thus 
\begin{equation}
    M=\big\{(t,H)\in \bC^2: t(H^2-4t)\neq 0\big\}.\end{equation}
   One exceptional feature in this example is that every differential of the form \eqref{qu} is preserved by a unique non-trivial  automorphism of $\bP^1$, namely $x\mapsto (tx)^{-1}$. %This automorphism will show up several times below
   In more  abstract language, the stack $\Quad(g,m)$ of quadratic differentials  has generic stabilizer $\bZ_2$ in this example \cite[Section 2.7]{BS}.


    We will construct a Joyce structure on $M$ by considering isomonodromic flows for meromorphic connections of the form 
\begin{equation}
\label{family}
	\nabla_\e= \dd-A_\e (x)\dd x, \qquad A_\e (x)=A_\infty(x)+\frac{1}{\e}\, \Phi(x), %\qquad A_\infty(x)=\frac{1}{x} \left(\begin{array}{cc}
	%	r & 0 \\
	%	0 & -r
	%\end{array} \right).
\end{equation}
where   $A_\epsilon(x)$  is  obtained from $\Phi(x)$ by the shift $p\mapsto p+\e rq^{-1}$. Explicitly
\begin{equation}
    \label{con2}
\nabla_\epsilon=\dd-  \left(\begin{array}{cc}
		r & 0 \\
		0 & -r
	\end{array} \right)\frac{\dd x}{x}-\frac{1}{\e}\left(\begin{array}{cc}
		pq & 1-qx^{-1} \\
		 tx-q^{-1}  & -pq
	\end{array} \right)\frac{\dd x}{x}. \end{equation}We view this  connection as  being parameterised by $\epsilon \in \bC^*$ together with the variables $(t,H,q,r)$, with $p$ defined implicitly by \eqref{eq:PIIIHam}.




\subsection{Extended isomonodromic flows}



Let us fix $\epsilon\in \bC^*$. If we move the point $(t,H)\in M$ we can vary $q=q(t,H)$ and $r=r(t,H)$ in such a way that the generalised monodromy of the connection \eqref{con2} is constant. The following result gives an explicit basis for the resulting two-dimensional space of  isomonodromic flows.

\begin{prop}
    The generalised monodromy of \eqref{con2} is preserved by the  vector fields 
\begin{equation}
\label{oneblue}
    w_1=t\frac{\partial}{\partial t}+\frac{2pq^2}{\e }\frac{\partial}{\partial q}+2qr\frac{\partial}{\partial q}-\frac{1}{2\e pq^2}(2rq^2 t-2r+q^2t)\frac{\partial}{\partial r},
\end{equation}
\begin{equation}\label{two1}
	w_2=\frac{\partial}{\partial H}-\frac{1}{2\e p q}\frac{\partial}{\partial r}.
\end{equation}
\end{prop}


\begin{proof}
Let us first consider the connection $d-A_\e(x) dx$ as being a function of  the variables $(t,q,p,r)$,  with $H$ determined by \eqref{eq:PIIIHam}.  We can describe isomonodromic deformations  of  this connection  with parameter $t$ as the compatibility conditions of the linear systems
\begin{equation}
\label{systems}
     \partial_x Y(x)=A_\e(x)Y(x), \qquad
 	\partial_t Y(x)=B_\e(x)Y(x). 
\end{equation}
The consistency condition
\begin{equation}
\label{consistency}
    \partial_t A_\e(x)-\partial_xB_\epsilon(x)+[A_\e(x),B_\e(x)]=0
\end{equation}
requires that we take
\begin{equation}
    B_\epsilon(x) =\frac{1}{\e t}\left(\begin{array}{cc}
	pq+\e r & 1 \\
	0 & -pq-\e r
\end{array} \right)+ \frac{x}{\e}\left(\begin{array}{cc}
	0 & 0 \\
	1 & 0
\end{array} \right),
\end{equation}
and gives the equations
\begin{equation}
\label{peg}
    t\frac{\dd q}{\dd t}=\frac{2pq^2}{\e}+2qr, \qquad 
    t\frac{\dd }{\dd t}(pq+\e r)=\frac{1}{\e}\left(q t-q^{-1} \right).
\end{equation}
Differentiating \eqref{eq:PIIIHam} then gives
\begin{equation}
    \frac{dH}{dt}=\frac{2r-q^2t(2r+1)}{tq}-2pq\epsilon\,  \frac{dr}{dt}.
\end{equation}

The equations \eqref{peg} do not uniquely  determine an isomonodromic flow because everything depends only on the combination $pq+\e r$, meaning that both $\partial_x-A_\e(x)$ and $\partial_t-B_\epsilon(x) $, and in particular the monodromy of $\nabla_\e $, are constant along the vector field
\begin{equation}
\label{w2}
    \widetilde{w_2}=\frac{\partial}{\partial r}-\frac{\e}{q}\frac{\partial}{\partial p}
\end{equation}
To fix this ambiguity  we impose that $\frac{\dd H}{\dd t}=0$ by adding a multiple of the vector field $\tilde{w}_2$.

We now rewrite the flows in the variables $(t,H,q,r)$, with $p$  determined by \eqref{eq:PIIIHam}. The first flow becomes
\begin{equation}
    \label{eq:isomonodromyPIII}
     t\frac{\dd q}{\dd t}=\frac{2pq^2}{\e}+2qr, \qquad  t\frac{\dd r}{\dd t}=\frac{2 r-q^2 t (2 r +1)}{2 p q^2  \e },
\end{equation}
which is generated by the vector field $w_1$. Moreover \eqref{w2} becomes
\begin{equation}
    \widetilde{w_2}=\frac{\partial}{\partial r}-2\e pq
    \frac{\partial}{\partial H},
\end{equation}
which is equivalent to $w_2$ by a simple rescaling.
\end{proof}
\begin{remark}
The combination $w_1-qtw_2$ gives the flow
\begin{equation}\label{eq:ReferencePIII}
    t\frac{dq}{dt}=\frac{2pq^2}{\e}+2qr,\qquad t\frac{dp}{dt}=-\frac{2p^2q-t+q^{-2}}{\e}+\frac{r \left(-4 p^2 q^3+2 q^2 t-2\right)}{2 p q^3},\qquad t\frac{dH}{dt}=-tq.
\end{equation}
When $r=0$ this reproduces the usual Painlev\'e flow defined by the Hamiltonian $H$ and the symplectic form $tdq\wedge dp$. 
In contrast to what happens in the usual treatment of Painlev\'e equations, however, in the presence of a reference connection the flow in $t$ can be normalised so that $H$ is conserved. However, since $q$ is unaffected by the flow $w_2$, irrespective of how we normalise the flow, the second order isomonodromy equation for $q$ is still the ($\e$-deformed) Painlev\'e III$_3$ equation 
\begin{equation}\label{pa}
	\frac{\dd^2 q}{\dd t^2}=\frac{1}{q}\left(\frac{\dd q}{\dd t} \right)^2-\frac{1}{t}\frac{\dd q}{\dd t}+\frac{1}{\e^2}\left(\frac{2q^2}{t}-\frac{2}{t^2}\right)
\end{equation}
This phenomenon was observed in the Painlev\'e I example in \cite[Section 6.1]{DM2}.
\end{remark}

\subsection{Spectral curve and its homology}


Let us fix a point $(t,H)\in M$. The spectral curve $\Sigma$  is a smooth curve of genus one which is a double cover $p\colon \Sigma\to \bP^1$  branched over 4 points of $\bP^1$. We denote by $\sigma\colon \Sigma\to \Sigma$ the covering involution. The branch points of $p$ include the points $0,\infty\in \bP^1$, and we will also write $0,\infty\in \Sigma$ for the unique points of $\Sigma$ lying over them. 

The open subset $\Sigma^0\subset \Sigma$ is  the complement $\Sigma^0=\Sigma\setminus\{0,\infty\}$. This subset  can be identified with the set of points $(x,y)\in \bC^*\times \bC$ satisfying
\begin{equation}\label{eq:SigmaPIII}
	y^2=Q_0(x)=\frac{t}{x}+\frac{H}{x^2}+\frac{1}{x^3}.
\end{equation}
The projection is then $p(x,y)=x$ and the covering involution is $\sigma(x,y)=(x,-y)$.


\begin{lemma}
\label{nak}
    The inclusion $i\colon \Sigma^0\hookrightarrow \Sigma$ induces an embedding
of anti-invariant homology groups \begin{equation}\label{istar}i_*\colon H_1(\Sigma^0,\bZ)^-\hookrightarrow H_1(\Sigma,\bZ)^-=H_1(\Sigma,\bZ)\end{equation}
whose image  has index 2. 
\end{lemma}

\begin{proof}
By uniformisation we can identify $\Sigma$ with the quotient of $\bC$ by a lattice generated by $\omega_1,\omega_2\in \bC^*$ with $\Im(\omega_2/\omega_1)>0$. We can assume that $0\in \bC$  corresponds to $0\in \Sigma$, and that the  involution $\sigma$ is induced by $z\mapsto -z$ on $\bC$. Then $\infty\in \Sigma$ will correspond to some half-period, without loss of generality $\half(\omega_1+\omega_2)$. The homology group $H_1(\Sigma,\bZ)$ has a basis consisting of cycles $\alpha_1,\alpha_2$ which we can represent by the images of the closed intervals $[0,\omega_i]\subset \bC$. It is then obvious that $\sigma^*(\alpha_i)=-\alpha_i$ and hence that $H_1(\Sigma,\bZ)^-=H_1(\Sigma,\bZ)$.

 The inclusion $i\colon \Sigma^0\hookrightarrow \Sigma$ induces a surjection $i_*\colon H_1(\Sigma^0,\bZ)\to H_1(\Sigma,\bZ)$ whose kernel is freely generated by the class $\delta$ defined by a small anti-clockwise loop  around the point $\half(\omega_1+\omega_2)$.
Let us lift the cycles $\alpha_i\in H_1(\Sigma,\bZ)$ to elements $\tilde{\alpha}_i \in H_1(\Sigma^0,\bZ)$. Since the $\alpha_i$ pass through $0\in \bC$  this requires us to first perturb them in some way. There is no canonical way to do this but we can take for example $\tilde{\alpha}_1=\tfrac{1}{4}\omega_2+[0,\omega_1]$ and $\tilde{\alpha}_2=\tfrac{1}{4}\omega_1+[0,\omega_2]$. The group $H_1(\Sigma^0,\bZ)$ then has a basis consisting of $\tilde{\alpha}_1,\tilde{\alpha}_2$ and $\delta$.

It is easy to see that $\sigma^*(\tilde{\alpha}_1)+\tilde{\alpha}_1=\delta$ and $\sigma^*(\tilde{\alpha}_2)+\tilde{\alpha}_2=-\delta$. Also $\sigma^*(\delta)=\delta$. 
Thus the anti-invariant subgroup $H_1(\Sigma^0,\bZ)^-\subset H_1(\Sigma^0,\bZ)$ is spanned by $\tilde{\alpha}_1+\tilde{\alpha}_2$ and $\tilde{\alpha}_1-\tilde{\alpha}_2-\delta$. It follows that the map \eqref{istar} is injective, and its image is the index 2  subgroup  spanned by $\alpha_1+\alpha_2$ and $\alpha_1-\alpha_2$. 
\end{proof}

In what follows we will
 fix a basis $(\gamma_1,\gamma_2)$ for the group $H_1(\Sigma^0,\bZ)^-$. The intersection form on $H_1(\Sigma,\bZ)$ pulls back along $i_*$ to give a skew-symmetric pairing  on  $H_1(\Sigma^0,\bZ)^-$.  Since the image of $i_*$ has   index 2 we can order our basis so that $\<\gamma_1,\gamma_2\>=2$. %The canonical quadratic refinement of Section \ref{quad_ref} satisfies $\xi(\gamma_1)=-1=\xi(\gamma_2)$ and will play no role in this example.


\subsection{Forms and periods}
By the gauge transformation \eqref{gauge} we can rewrite \eqref{con2} as a scalar equation of the form \eqref{above2}. In this case we have $Q_0(x)$ as in \eqref{qu} above, and
\begin{equation}\label{nf}
 Q_1(x)=-\frac{pq^2}{x^2(x-q)}+\frac{2pqr}{x^2}, \qquad Q_2(x)=\frac{3}{4(x-q)^2}-\frac{x+rq}{x^2(x-q)}+\frac{r^2}{x^2}.
\end{equation}
As in Section \ref{sec:Quad} we introduce  meromorphic differentials on $\Sigma$ by the expressions
\begin{equation}\label{nff}\lambda = y\, \dd x, \qquad \theta=-\frac{Q_1(x) \, dx }{2\sqrt{Q_0(x)} }.\end{equation}

The Seiberg-Witten differential $\lambda$ has double poles at the points $0,\infty\in \Sigma$, and
no other poles. 
The differential $\theta$  has simple poles at the points $(q,\pm p)$ with residues $\pm \half$ respectively, and no other poles. 
We introduce the periods 
\begin{equation}\label{pers}z_i=\oint_{\gamma_i} \lambda, \qquad \theta_i=\oint_{\gamma_i} \theta.\end{equation}
Note that the expressions $\theta_i$ are only well-defined up to the addition of integer multiples of $2\pi i$. To specify them we must lift the  cycles $\gamma_i$ to the complement $\Sigma^*=\Sigma^0\setminus \{(q,\pm p)\}$. We can always do this so that the resulting elements $\gamma^*_i\in H_1(\Sigma^*,\bZ)$ are anti-invariant. Since $\theta$ has residues $\pm \half$ at the points $(q,\pm p)$, taking different  lifts changes the result by a multiple of $2\pi i$. 

Let us set $s=\log(t)$ and take $(s,H)$ as local co-ordinates  on the base $M$. There are 
corresponding linear coordinates $(\theta_s,\,\theta_H)$ on the fibres of the projection $\pi\colon X=T_M\to M$ defined by the relation\begin{equation}\label{fafa}
\theta_s\, \frac{\partial }{\partial s} +\theta_H\, \frac{\partial }{\partial H} =\theta_1\,  \frac{\partial }{\partial z_1} +\theta_2\, \frac{\partial }{\partial z_2} .
\end{equation}

 Introduce the differentials
\begin{equation}\label{fafafa}\omega=\frac{\partial \lambda}{\partial H} =\frac{dx}{2x^2y}, \qquad \beta=\frac{\partial \lambda}{\partial s} =\frac{t\, dx}{2x y}.\end{equation}
Then $\omega$ is a holomorphic differential on $\Sigma$, and $\beta$ has a pole of order 2  with vanishing residue at the branch-point $x = \infty$  and no other poles. We denote the corresponding periods by $\omega_{i}$ and $\beta_i$ respectively. There is an obvious relation
\begin{equation}\label{fink}dz_i=\frac{\partial z_i}{\partial s} \, ds+\frac{\partial z_i}{\partial H} \, dH=\beta_i \, ds+\omega_i \, dH,\end{equation}
and using \eqref{fafa} we get
\begin{equation}\label{eq:thetatHdef}\theta_i=\beta_i\theta_s+\omega_i\theta_H.\end{equation}


\subsection{Computation of periods}In this section we use the Riemann bilinear relations to give explicit expressions for $\theta_s$ and $\theta_H$.

\begin{lemma}\label{thm:lemmathetaIII}
   There are formulae
    \begin{equation}\label{ths}\theta_s=\frac{1}{2} \int_{(q,-p)}^{(q,p)} \frac{dx}{2x^2y}, \qquad  \theta_H= -\frac{1}{2} \int_{(q,-p)}^{(q,p)} \frac{t\, dx}{2xy}-2pqr.\end{equation}
\end{lemma}

\begin{proof}
Note that $y=\sqrt{Q_0(x)}$ is a uniformising parameter at the point $\infty\in \Sigma$. We denote by  $x^{1/2}$  the  choice of square-root near this point for which  $y\simeq t^{1/2}x^{-1/2}$. The differentials introduced above have leading order behaviour
\begin{equation}\label{lord}
    \omega=\frac{\dd x}{2t^{1/2}x^{3/2}}+O\left(\frac{\dd x}{x^{5/2}} \right), \qquad \beta=\frac{t^{1/2} \dd x}{2x^{1/2}}+O\left(\frac{\dd x}{x^{3/2}} \right), \end{equation}
    \begin{equation}\qquad \theta=-\frac{pqr \, dx}{t^{1/2}x^{3/2}}+O\left(\frac{\dd x}{x^{5/2}} \right).
\end{equation}





The Riemann bilinear relations for meromorphic differentials (see Proposition 3.4.1 in \cite{BertolaLectures}, a direct consequence e.g. of equations 3.0.1 and 3.0.2 in \cite{FarkasKra})   give
 \begin{equation}\label{l1a}\omega_1\beta_{2}-\omega_2\beta_{1} = 2\pi i \cdot \langle\gamma_1,\gamma_2\rangle\cdot  \Res_{x=\infty}\left( \beta\int^x\omega\right). \end{equation}
Note that although this formula is usually given in the case that the cycles $\gamma_1,\gamma_2\in H_1(\Sigma,\bZ)$ satisfy $\<\gamma_1,\gamma_2\>=1$, the case of an arbitrary pair of linearly independent cycles follows immediately from this. Note also that the form $dx/x$ has residue $-2$ at the point $\infty\in \Sigma$.
Using  $\<\gamma_1,\gamma_2\>=2$ and the expressions \eqref{lord} we then get
\begin{equation}\label{l1}\langle\omega,\beta\rangle:=\omega_1\beta_{2}-\omega_2\beta_{1} =4\pi i.\end{equation}

We can write similar expressions
 \begin{equation}\label{lorda}\langle\omega,\theta\rangle  :=\omega_1\theta_2-\omega_2\theta_1 = 4\pi i \sum_{x_i\in \{(q,\pm p)\}}\Res_{x=x_i}\left(\theta\int^x\omega\right)
 =2\pi i  \int_{(q,-p)}^{(q,p)}\omega,\end{equation}
 \begin{equation}\label{lordb} \langle\beta,\theta\rangle:=\beta_{1}\theta_2-\beta_{2}\theta_1 = 4\pi i \sum_{x_i\in\{(q,\pm p),\infty\}}\Res_{x=x_i}\left(\theta\int^x\beta \right)=2\pi i \int_{(q,-p)}^{(q,p)}\beta+8\pi i pqr.
\end{equation}
Using \eqref{eq:thetatHdef} we then have
\begin{equation}
   2\pi i  \int_{(q,-p)}^{(q,p)}\omega=  \langle\omega,\theta\rangle=\theta_s\langle\omega,\beta\rangle=4\pi i\theta_s,
\end{equation}
\begin{equation}
     2\pi i\int_{(q,-p)}^{(q,p)}\beta+8\pi i pqr=\langle\beta,\theta\rangle=\theta_H\langle\beta,\omega\rangle=-4\pi i\theta_H,
\end{equation}
and comparing with \eqref{fafafa} gives the result.
\end{proof}

\begin{remark}
    Since the $\theta_i$ are only well-defined up to the addition of integer multiples of  $2\pi i$, it follows from \eqref{eq:thetatHdef} and \eqref{l1} that the pair $(\theta_{s},\theta_H)$ is only well-defined up to the addition of integer combinations  of the vectors $(\omega_i,-\beta_i)$. This matches the indeterminacy in the choice of path in the formulae \eqref{ths} which should be taken to be anti-invariant under the covering involution $\sigma$.
\end{remark}

Recall from \eqref{poisson} that the Poisson structure on $M$ is defined by the condition \begin{equation}\{z_1,z_2\}=2\pi i \, \<\gamma_1,\gamma_2\>=4\pi i.\end{equation} Inverting this gives the symplectic form  
\begin{equation}\label{handy} \Omega_0=-\frac{1}{4\pi i} \cdot dz_1\wedge dz_2 = \frac{1}{4\pi i}  (\omega_1\beta_{2}-\omega_2\beta_{1})\cdot ds\wedge dH=ds\wedge dH,\end{equation}
where we used  \eqref{fink} and \eqref{l1}.


\subsection{Abelian holonomy map}

Denote by $\Xi$ the change of coordinates $(s,H,q,r)\mapsto(s,H,\theta_s,\theta_H)$.
Applying the chain rule  to Lemma \ref{thm:lemmathetaIII} gives
	\begin{equation}\label{eq:dstodthetaIII}
	\Xi_*\left(\frac{\partial}{\partial s} \right)=\frac{\partial}{\partial s}-t\kappa_3 \frac{\partial}{\partial\theta_s}+\left(%\zeta(v)+\frac{Hv}{3}
 -\frac{t}{4} \int_{(q,-p)}^{(q,p)} \frac{dx}{xy}+t^2\kappa_2 -\frac{rt}{p} \right)\frac{\partial}{\partial\theta_H},
\end{equation}
\begin{equation}\label{eq:dqtodthetaIII}
\Xi_* \Big(\frac{\partial}{\partial H}\Big)=\frac{\partial}{\partial H}-\kappa_4 \frac{\partial}{\partial \theta_s} + \Big(t \kappa_3 -\frac{r}{qp}\Big)\frac{\partial}{\partial \theta_H},\end{equation}
\begin{equation}\Xi_* \Big(\frac{\partial}{\partial q}\Big)=\frac{1}{2q^2p} \frac{\partial}{\partial \theta_s} +\frac{2r-2trq^2-tq^2}{2pq^3}\frac{\partial}{\partial \theta_H},\qquad \label{eq:drtodthetaIII}
\Xi_* \Big(\frac{\partial}{\partial r}\Big)=-2qp \frac{\partial}{\partial \theta_H},\end{equation}
where we introduced
\begin{equation}\kappa_i:=\frac{1}{8}\int_{(q,-p)}^{(q,p)} \frac{dx}{x^i y^3},\qquad i=2,3,4.\end{equation}
Inverting the relations \eqref{eq:dqtodthetaIII} and \eqref{eq:drtodthetaIII} gives
\begin{equation}
\label{two2}\Xi_*^{-1} \Big(\frac{\partial}{\partial \theta_s}\Big)={2q^2p} \frac{\partial}{\partial q} +\frac{2r-2trq^2-tq^2}{2pq^2}\frac{\partial}{\partial r},\qquad 
\Xi_*^{-1} \Big(\frac{\partial}{\partial \theta_H}\Big)=-\frac{1}{2qp}\frac{\partial}{\partial r}.\end{equation}
% and
%\begin{equation}\frac{\partial}{\partial t}=\frac{1}{t}\frac{\partial}{\partial s}-\frac{\theta_t}{t^2}\cdot \frac{\partial}{\partial \theta_s}, \qquad \frac{\partial}{\partial \theta_t}=\frac{1}{t}\cdot \frac{\partial}{\partial \theta_s},\end{equation}


Fix a point $(t,H)\in M$ and a basis $(\gamma_1,\gamma_2)\in H^1(\Sigma^0,\bZ)^-$ as above.

\begin{lemma}\label{abhol}
      The  map
    \begin{equation}\label{map} \big\{(q,p)\in (\bC^*)^2: p^2=Q_0(q)\big\}\times \big\{r\in \bC\big\}\to \big\{(e^{\theta_1},e^{\theta_2})\big\}\in (\bC^*)^2\end{equation}
    defined by the equations \eqref{nf}, \eqref{nff} and \eqref{pers} is  an unramified double cover.
\end{lemma}

\begin{proof}  The degree 0 divisor $(q,p)-\infty$ on $\Sigma$ defines a line bundle whose local sections are meromorphic functions on $\Sigma$ with a zero at $(q,p)$ and at worst a simple pole at  $\infty$.
    Consider the form \begin{equation}
    \label{thnew}
       \theta'=\theta+\frac{dx}{2(x-q)}
    \end{equation} on $\Sigma$. It has a simple pole at $(q,p)$ with residue $+1$, a simple pole  at  $\infty$ with residue $-1$, and no other poles. It follows that $\partial=d-\theta'$ defines a holomorphic connection on $L$. Since  $\theta'-\theta$  is pulled back from $\bP^1$, the form $\theta'$ has the same periods as $\theta$. Thus the monodromy of the connection $(L,\partial)$   around the cycle $\gamma_i\in H_1(\Sigma^0,\bZ)^-$ is given by multiplication by $\exp(\theta_i)\in \bC^*$. 


    Suppose there are three points $(q_i,p_i,r_i)$ with  $i=1,2,3$ in the source of \eqref{map} which are mapped to the same point. Since the cycles $\gamma_1,\gamma_2$ span an index 2  subgroup of $H_1(\Sigma,\bZ)$, at least two of the points (without loss of generality corresponding to $i=1,2$) must correspond to line bundles with connection $(L_i,\partial_i)$ which have identical monodromy around all cycles in $H_1(\Sigma,\bZ)$. The abelian Riemann-Hilbert correspondence tells us that such line bundles with connection $(L_i,\nabla_i)$ are isomorphic. But it is a well-known fact (easily proved using the Riemann-Roch theorem) that the line bundles $L_i$ defined by different points $(q_i,p_i)\in \Sigma$ are all non-isomorphic. So we conclude that $(q_1,p_1)=(q_2,p_2)$. But the formulae \eqref{eq:thetatHdef} - \eqref{ths} then imply that also $r_1=r_2$. Indeed $\omega_1,\omega_2\in \bC^*$ do not lie on the same ray, so changing $r$ cannot move both $\theta_i$ by an imaginary number.

  The derivative of the map \eqref{map} is computed by \eqref{eq:dstodthetaIII} and \eqref{eq:dqtodthetaIII} together with \eqref{eq:thetatHdef} and is everywhere invertible.  Thus \eqref{map} is a finite unramified cover of degree at most 2. Now it is easy to check that our map is invariant under the  involution
    \begin{equation}\label{inv}
         (q,p,r)\mapsto \left((qt)^{-1},-tpq^2 ,-(r+\half)\right),
    \end{equation}
    and this involution is moreover fixed-point free. Therefore the map is a double cover.%\footnote{The reason this involution preserves the isomonodromy flows is as follows. If we apply it to the formula \eqref{con} for the connection we get a new connection related to the first by (i) pulling back by $x\mapsto q/x$ and (ii) a gauge transformation by $\operatorname{diag}((x/q)^{1/2}, (x/q)^{-1/2})$.}
\end{proof}


\subsection{Isomonodromic flows in new coordinates}


We now write the isomonodromic flows in coordinates $(s,H,\theta_s,\theta_H)$.


\begin{proposition}
\label{propIII}
  The push-forward of the isomonodromic flows along $\Xi$ can be written in the form
  \begin{equation}\label{11}
    \Xi_*(w_1)=\frac{\partial}{\partial s}+\frac{1}{\e}\frac{\partial}{\partial\theta_s}+\frac{\partial^2K}{\partial\theta_s\partial\theta_H}\frac{\partial}{\partial\theta_s}-\frac{\partial^2K}{\partial\theta_s^2}\frac{\partial}{\partial\theta_H},
\end{equation}
\begin{equation}\label{12}
    \Xi_*(w_2)=\frac{\partial}{\partial H}+\frac{1}{\e}\frac{\partial}{\partial\theta_H}+\frac{\partial^2K}{\partial\theta_H^2}\frac{\partial}{\partial\theta_s}-\frac{\partial^2K}{\partial\theta_s\partial\theta_H}\frac{\partial}{\partial\theta_H},
\end{equation}
where $K\colon X^\hash\to \bC$ is a single locally-defined function.
\end{proposition}



\begin{proof}
The formulae \eqref{oneblue} - \eqref{two1} for the isomonodromic flows and the relations \eqref{eq:dstodthetaIII} - \eqref{eq:drtodthetaIII} give

\begin{gather}
\Xi_*(w_1)=\frac{\partial}{\partial s}+\frac{1}{\e}\frac{\partial}{\partial \theta_s}+b\frac{\partial}{\partial \theta_s} - a\frac{\partial}{\partial \theta_H},\\
\Xi_*(w_2)=\frac{\partial}{\partial H}+\frac{1}{\e}\frac{\partial}{\partial \theta_H}+c\frac{\partial}{\partial \theta_s} -b\frac{\partial}{\partial \theta_H},\end{gather}
where we introduced
\begin{equation}
\label{jimmy}
     a=\frac{t}{4} \int_{(q,-p)}^{(q,p)} \frac{dx}{xy}-t^2\kappa_2+\frac{2rt}{p}+\frac{2r^2(tq^2-1)}{pq^2}, \qquad b=\frac{r}{qp}-t\kappa_3,\qquad 
c=-\kappa_4. \end{equation}

Using \eqref{two2} we find that 
\begin{equation}
\label{sno}
    \frac{\partial b}{\partial \theta_s}=\frac{\partial a}{\partial \theta_H}, \qquad \frac{\partial c}{\partial \theta_s}=\frac{\partial b}{\partial \theta_H}.
\end{equation}
This implies the existence of a single locally-defined  function $K$ such that
    \begin{equation}\label{park}
\frac{\partial^2 K}{\partial \theta_s^2}=a , \qquad \frac{\partial^2 K}{\partial \theta_s \partial \theta_H}=b,\qquad \frac{\partial^2 K}{\partial \theta_H^2}=c,\end{equation}
and the result follows. 
\end{proof}

Applying the operators \eqref{two2} to the expressions \eqref{jimmy} gives
