\section{Second example: Painlev\'e II}
\label{sec:two}

Our second example will be the Joyce structure of class $S[A_1]$ corresponding to genus $g=0$ and pole order $m=(8)$. This Joyce structure is related to the DT theory of the A$_3$ quiver and to the  Painlev\'e II equation. The corresponding field theory of class $S$ is known as Argyres-Douglas theory $H_0$, or the $(A_1,A_3)$ theory \cite{Bonelli2017}. The relevant quadratic differentials take the form
\begin{equation}\label{q0}Q_0(x)  dx^{\tensor 2}=(x^4+tx^2-2 \alpha x+2H )dx^{\tensor 2}\end{equation}
and the associated flat connections feature both nontrivial Stokes data and local monodromy determined  by the parameter $\alpha\in \bC$. 

To obtain a Joyce structure, we must impose that the quadratic differential \( Q_0 \) has zero residue at the pole \( x = \infty \), which corresponds to the condition \( \alpha = 0 \). Consequently, the base \( M \) of the Joyce structure has natural coordinates \( (t, H) \). However, since most of our computations are valid for arbitrary values of $\alpha$,  we will retain it as a  variable for most of the section.

\subsection{Connections}

The relevant Higgs field is the Jimbo-Miwa Lax matrix for Painlev\'e II
\begin{equation}\label{eq:HiggsPII}
	\Phi(x)=x^2\left( \begin{array}{cc}
		1 & 0 \\
		0 & -1
	\end{array} \right)+
	x\left( \begin{array}{cc}
		0 & 1 \\
		t-2p+2q^2 & 0
	\end{array} \right)
	+\left( \begin{array}{cc}
		p-q^2 & -q \\
		-2\alpha+q(t-2p+2q^2) & -p+q^2
	\end{array} \right).
\end{equation}
It is a classical result \cite{JMU1981II} that isomonodromic deformations of the flat connection $\dd-\Phi(x)\dd x$ are described by the second Painlev{\'e} equation 
\begin{equation}\label{p2}
	\frac{d^2q}{dt^2}=2q^3+qt-\alpha+\frac{1}{2}.
\end{equation}

\begin{remark}
    \label{footnote:PII}The matrix
\begin{equation}
	\Phi(x)= \left( \begin{array}{cc}
	1 & 0 \\
	0 & -1		
	\end{array} \right)x^2 
	+ \left( \begin{array}{cc}
		0 & u \\
		-\frac{2z}{u} & 0
	\end{array} \right)x
	+\left( \begin{array}{cc}
		z+\frac{t}{2} & -u y \\
		-\frac{2}{u}(\theta+yz) & -z-\frac{t}{2}
	\end{array} \right)
\end{equation}
of \cite{JMU1981II}  is parameterised in terms of $y,z,u,\alpha,t$. To obtain \eqref{eq:HiggsPII}, we set $u=1$ by a diagonal gauge transformation, and write our Higgs field in terms of spectral Darboux coordinates $\alpha=\theta$, $q=y$ and $p=z+q^2+\half t$.  
\end{remark}

As before, we introduce a parameter $\e\in \bC^*$ and consider  connections $\dd-A_\e(x) \dd x$, where
\begin{equation}
	A_\e (x)=A_\infty+\frac{1}{\e}\Phi(x),\qquad A_\infty=\left(\begin{array}{cc}
		r & 0 \\
		-2s-1-2r(x+q) & -r
	\end{array} \right).
\end{equation}
This is obtained from \eqref{eq:HiggsPII} by shifting
\begin{equation}
    p\mapsto p+\e r,\qquad \alpha\mapsto\alpha+\e\left(s+\frac{1}{2}\right).
\end{equation}
% The reference connection $d-A_\infty(x) \dd x$ depends on new variables $r,s$ and is the most general connection on the trivial vector bundle with ...
We then define the Hamiltonian
\begin{equation}\label{eq:PIIHam}
    H=\frac{1}{2}\left(p^2-q^4-tq^2+2\alpha q\right),
\end{equation}
and view the connection \eqref{family} as being parameterised by $\e\in \bC^*$ together with the variables $(t,H, \alpha,q,r,s)$, with $p$ defined implicitly by  \eqref{eq:PIIHam}.



\subsection{Extended isomonodromic flows}
We consider isomonodromic flows obtained by varying $(t,H,\alpha)$ and insisting that the generalised monodromy of $\dd-A_\e (x) \dd x$ is constant.


\begin{prop}
    The isomonodromy flows are generated by the vector fields
   \begin{equation}\label{eq:IsoFlow1}
	w_1=\frac{\partial}{\partial t} +  \left(r+\frac{p}{\e}\right)\frac{\partial}{\partial q}-\frac{1}{\e}\left[s+\frac{q^2}{2p} +\frac{r}{p}(2q^3+tq-\alpha)\right]\frac{\partial}{\partial r} ,
\end{equation}
\begin{equation}\label{eq:IsoFlow2}
	w_2=\frac{\partial}{\partial H}-\frac{1}{\e p}\frac{\partial}{\partial r},\qquad w_3=\frac{\partial}{\partial \alpha}-\frac{1}{\e}\frac{\partial}{\partial s}+\frac{q}{ \e p} \frac{\partial}{\partial r}.
\end{equation}
\end{prop}
\begin{proof}
    We first consider the connection as a function of the variables $(t,\alpha,q,p,r,s)$, with $H$ defined by \eqref{eq:PIIHam}. As before, we can describe isomonodromic deformations of $d-A_\e(x)\, dx$ with parameter $t$ as the compatibility conditions \eqref{consistency} of the linear systems \eqref{systems}. This forces
%     \begin{equation}
% \begin{cases}
% 	\partial_x Y(x)=A_\e(x)Y(x), \\
% 	\partial_t Y(x)=B(x)Y(x), 
% %	\partial_r Y(x)=\partial_s Y(x)=0, \\
%\end{cases}\qquad 
\begin{equation}B_\epsilon(x)=\left( \begin{array}{cc}
        0 & 0 \\
        -r & 0
    \end{array} \right)+
    \frac{1}{2\e}\left(
\begin{array}{cc}
 q+x & 1 \\
 -2 p+2 q^2 +t & -q-x \\
\end{array}
\right),
\end{equation}
and gives the conditions

\begin{equation}
\label{normal}
    \frac{\dd q}{\dd t}=\left(\frac{p}{\e}+r \right), \qquad
    \frac{\dd }{\dd t}(p+\e r)=\frac{2q^3+tq-\alpha}{\epsilon} -s, \qquad  \frac{\dd }{\dd t}(\alpha+\e s)=0.
\end{equation}

The isomonodromic flow is still undetermined, due to the additional  flows 
\begin{equation}
\label{extramore}
    \frac{\partial}{\partial p}-\frac{1}{\e }\frac{\partial}{\partial r}, \qquad \frac{\partial}{\partial \alpha}-\frac{1}{\e }\frac{\partial}{\partial s},
\end{equation}
reflecting the fact that $A_\epsilon(x)$ and $B_\epsilon(x)$ depend only on the combinations $p+\e r$ and $\alpha+\e s$. We now rewrite our flows in the co-ordinates $(t,H,\alpha,q,r,s)$ with $p$ defined by \eqref{eq:PIIHam}. Taking linear combinations of \eqref{extramore} gives  the flows
\begin{equation}
\label{extra}
    {w}_2=\frac{\partial}{\partial H}-\frac{1}{\e p}\frac{\partial}{\partial r}, \qquad w_3=\frac{\partial}{\partial\alpha}-\frac{1}{\e}\frac{\partial}{\partial s}+\frac{q}{ \e p} \frac{\partial}{\partial r}.
\end{equation}
We can add copies of  these flows  to normalise \eqref{normal} in such a  way that $\frac{\dd H}{\dd t}=\frac{\dd \alpha}{\dd t}=0$. This gives the system of equations

\begin{gather}
\label{eq:IsoPII}
  \frac{\dd q}{\dd t}=\left(r+\frac{p}{\e}\right), \qquad 
    \frac{\dd p}{\dd t}=\frac{q^2}{2p}+\left(\frac{1}{\e}+\frac{r}{p} \right)(2q^3+tq-\alpha) , \\
    \frac{ \dd r}{\dd t}=-\frac{1}{\e}\left[s+\frac{q^2}{2p}+\frac{r}{p}\left(2q^3+tq-\alpha \right) \right],
\end{gather}
generated by the flow $w_1$.
\end{proof}
\begin{remark}
    As in the example from the previous section, 
irrespectively of how we normalise the flow in $t$, the resulting nonlinear second order nonlinear ODE for $q$ is the appropriate Painlev\'e equation, in this case the $\e$-deformed Painlev\'e II equation with shifted monodromy parameter
\begin{equation}
    \e^2\frac{\dd^2 q}{\dd t^2}=2q^3+qt-(\alpha+\e s).
\end{equation}
This reduces to \eqref{p2} when $\epsilon=1$ and $s=-\half$.
\end{remark}


\subsection{Spectral curve}

By the gauge transformation \eqref{gauge} we can rewrite \eqref{family} as a scalar equation of the form \eqref{above2}. In this case $Q_0(x)$ is given by \eqref{q0}, and
\begin{equation}\label{eq:Q0Q1PII}
	Q_1(x)=-\frac{p}{x-q}
	+2pr-2s(x-q),
\qquad
	Q_2(x)=\frac{3}{4(x-q)^2}-\frac{r}{x-q}+r^2.
\end{equation}

Let us fix the parameters $(t,H,\alpha)$. The corresponding spectral curve $\Sigma$ is a smooth curve of genus 1 with a double cover $p\colon \Sigma\to \bP^1$ branched over 4 points $x_i\in \bC^*$. We denote by $\infty_{\pm}$ the two inverse images of the point $x=\infty$. The open subset $\Sigma^0\subset \Sigma$ is then the complement $\Sigma^0=\Sigma\setminus\{\infty_\pm\}$, and is the  affine quartic  curve
\begin{equation}\label{eq:SigmaPII}
	y^2=x^4+tx^2-2x\alpha+2H.
\end{equation}




Similar reasoning to the proof of Lemma \ref{nak} shows that the inclusion $i\colon \Sigma^0\hookrightarrow \Sigma$ induces a short exact sequence
\begin{equation}
    0\lra \bZ\lra H^1(\Sigma^0,\bZ)^-\stackrel{i_*}{\lra} H^1(\Sigma,\bZ)^-\lra 0,\end{equation}
   where  as before $H_1(\Sigma,\bZ)^-=H_1(\Sigma,\bZ)$. The kernel of $i_*$ is generated by a small anti-clockwise loop $\gamma_3$ around the point $\infty_+$. Note that this class  is anti-invariant because $\sigma^*(\gamma_3)$ is represented by   a small anti-clockwise loop around $\infty_-$ and thus is homologous to $-\gamma_3$.

We take generators $\gamma_1,\gamma_2,\gamma_3$ for $H_1(\Sigma^0,\bZ)^-$ such that $\gamma_1,\gamma_2$ project to  generators of $H_1(\Sigma,\bZ)\isom\bZ^{\oplus 2}$.  
With appropriate ordering of $\gamma_1,\gamma_2$ we then  have
 \begin{equation}
     \<\gamma_1,\gamma_2\>=1, \qquad \<\gamma_1,\gamma_3\>=0=\<\gamma_2,\gamma_3\>.
 \end{equation}

Let us introduce the meromorphic differentials
\begin{equation}\lambda = y \dd x, \qquad \theta=-\frac{Q_1(x) \,dx}{2\sqrt{Q_0(x)} },\end{equation}
and the associated periods
\begin{equation}\label{eq:PeriodII}z_i=\oint_{\gamma_i} \lambda, \qquad \theta_i=\oint_{\gamma_i} \theta.\end{equation}

The differential
 $\lambda$ has a pole of order 4 at the points $\infty_\pm$, and we can order them so that near $\infty_\pm$ we have
\begin{equation}\label{eq:lambdaPIIExp}
	\lambda=\pm\left[x^2+\frac{t}{2}-\frac{\alpha}{x}+\frac{1}{x^2}\left(H-\frac{t^2}{8} \right)+O(x^{-3}) \right]\dd x.
\end{equation}In particular $\lambda$ has residue $\alpha$ at $\infty_+$, so that 
\begin{equation}\label{z3}z_3=\oint_{\gamma_3} \lambda=2\pi i \alpha.\end{equation}

The differential $\theta$ has a simple pole at $\infty_\pm$ with residue $\mp s$, where the leading behaviour is
\begin{equation}
	\theta=\mp\left[-\frac{s}{x}+ \frac{pr+qs}{x^2}+\frac{st-p}{2x^3}+ O(x^{-4}) \right]\dd x.
\end{equation}
It also has   simple poles at the points $x=(q,\pm p)$ with residue $\pm \half$.



As before, defining  the periods $\theta_i$ requires choosing lifts of the cycles $\gamma_i\in H_1(\Sigma^0,\bZ)^-$ to elements $\gamma_i^*\in H_1(\Sigma^*,\bZ)^-$, where $\Sigma^*=\Sigma^0\setminus\{(q,\pm p)\}$. Different choices 
affect the values of $\theta_i$ by the addition of integer multiples of $2\pi i$. Note that lifting $\gamma_3\in H_1(\Sigma,\bZ)^-$  in the most obvious way does not define an anti-invariant cycle on $\Sigma^*$. Instead, we take $\gamma_3^*\in H_1(\Sigma^*,\bZ)^-$ to be the sum of small anti-clockwise loops around the points $\infty_+$ and $(q,p)$.



\subsection{Computation of periods}
Introduce the differentials
\begin{equation}
	\omega=\frac{\partial\lambda}{\partial H}=\frac{\dd x}{y}, \qquad \beta_t=\frac{\partial\lambda}{\partial t}=\frac{x^2\, \dd x}{2y}, \qquad \beta_\alpha=\frac{\partial\lambda}{\partial \alpha}=-\frac{x\, \dd x}{y} .%=:\dd f,
\end{equation}
Then 
$\omega$ is holomorphic on $\Sigma$, with leading order behaviour  at $\infty_{\pm}$ given by
\begin{equation}
\omega=\pm\left[\frac{1}{x^2}+O(x^{-3}) \right]\dd x.
%-\frac{t}{4x^4}
\end{equation} The differential $\beta_t$ has poles of order 2 at $\infty_\pm$ with zero residue, 
whereas $\beta_\alpha$ has simple poles at $\infty_\pm$  with residue $\pm 1$. Differentiating \eqref{eq:lambdaPIIExp}, the expansions at $\infty_\pm$ are 
\begin{equation}
	\beta_t=\pm\left[\frac{1}{2}-\frac{t}{4x^2} +O(x^{-3}) \right]\dd x,\qquad \beta_\alpha=\pm\left[-\frac{1}{x}+O(x^{-3}) \right]\dd x.
\end{equation}
Since these differentials are regular on $\Sigma^0$ the corresponding periods $\beta_{t,i}$, $\omega_i$, $\beta_{\alpha,i}$ are  well-defined.

Define $\theta_t,\,\theta_H,\,\theta_\alpha$ through the relation
\begin{equation}
    \theta_1\,\frac{\partial}{\partial z_1}+\theta_2\,\frac{\partial}{\partial z_2}+\theta_3\,\frac{\partial}{\partial z_3}=\theta_t\,\frac{\partial}{\partial t}+\theta_H\,\frac{\partial}{\partial H}+\theta_\alpha\,\frac{\partial}{\partial \alpha}.
\end{equation}
Using the obvious relation
\begin{equation}
\label{againy}
dz_i=\frac{\partial z_i}{\partial t} dt + \frac{\partial z_i}{\partial H} dH +\frac{\partial z_i}{\partial \alpha} d\alpha=\beta_{t,i}\, dt+\omega_i\, dH+\beta_{\alpha,i} \, d\alpha ,
\end{equation}it follows that
\begin{equation}\label{hi}
	\theta_i=\theta_t\beta_{t,i}+\theta_H\omega_i+\theta_\alpha\beta_{\alpha,i}.
\end{equation}


\begin{lemma}
\label{74}
There are identities\begin{equation}\label{eq:thetat1}
	\theta_t=\frac{1}{2}\int_{(q,-p)}^{(q,p)}\omega-\frac{1}{2}\int_{\infty_-}^{\infty_+}\omega
    %{\color{red}\,- \int_{\infty_-}^{\infty_+}\omega}
    ,  \qquad  \theta_\alpha =\half -s,\end{equation}
    \begin{equation}\label{eq:thetah1}
	\theta_H=-\frac{1}{2}\int_{(q,-p)}^{(q,p)}\beta_t-(pr+qs)-\Res_{x=\infty_+}\left(\frac{dx}{x}\int^x\beta_t \right).
\end{equation}

\end{lemma}

    \begin{proof}Recall that  we can lift the cycles $\gamma_i\in H_1(\Sigma^0,\bZ)^-$ to elements $\gamma_i^*\in H_1(\Sigma^*,\bZ)^-$. The periods $\theta_i$ are then well-defined. As above, we 
     take $\gamma_3^*$ to be  the sum of anti-clockwise cycles round the points $\infty_+$ and $(q,p)$.



    To apply the Riemann bilinear relations we first cut the surface $\Sigma^*$ along the  cycles  $\gamma_1^*,\gamma_2^*$  to obtain a simply-connected fundamental domain. We take all integrals along paths in this region. Using notation as in the proof of Lemma \ref{thm:lemmathetaIII}, we have
\begin{equation}
\label{hand}
	\langle\omega,\beta_t\rangle=2\pi i\sum_{x_i\in \{\infty_{\pm}\}}\Res_{x=x_i}\left(\beta_t\int^x\omega \right)=2\pi i,
\end{equation}
\begin{equation}
    \langle\omega,\,\beta_\alpha\rangle=2\pi i\sum_{x_i\in \{\infty_{\pm}\}}\Res_{x=x_i}\left(\beta_\alpha\int^x\omega \right)=2\pi i\int_{\infty_-}^{\infty_+}\omega,
\end{equation}
\begin{equation}
\label{problem?}
    \langle\beta_t,\,\beta_\alpha\rangle=2\pi i\sum_{x_i\in \{\infty_{\pm}\}}\Res_{x=x_i}\left(\beta_\alpha\int^x\beta_t \right)
    =-4\pi i\,\Res_{x=\infty_+}\left(\frac{dx}{x}\int^x\beta_t \right),
\end{equation}
\begin{equation}
	\langle\omega,\,\theta\rangle=2\pi i\sum_{x_i\in \{(q,\pm p),\infty_{\pm}\}}\Res_{x=x_i}\left(\theta\int^x\omega \right) =\pi i\int_{(q,-p)}^{(q,p)}\omega-s\<\omega,\beta_\alpha\>,
\end{equation}
\begin{equation}
	\langle\beta_t,\,\theta\rangle=2\pi i\sum_{x_i\in \{(q,\pm p),\infty_{\pm}\}}\Res_{x=x_i}\left(\theta\int^x\beta_t \right)=\pi i\int_{(q,-p)}^{(q,p)}\beta_t+2\pi i (pr+qs)-s\<\beta_t,\beta_\alpha\>.
\end{equation}


By our choice of the lift $\gamma_3^*$ we have
 $\theta_3=2\pi i (\half-s)$. Moreover $\omega_3=\beta_{t,3}=0$ and $\beta_{\alpha,3}=2\pi i $ so from \eqref{hi} we get $\theta_\alpha=\half-s$. 
Then
\begin{equation}
	\pi i\int_{(q,-p)}^{(q,p)}\omega-2\pi is\int_{\infty_-}^{\infty_+}\omega =\langle\omega,\,\theta\rangle=\theta_t\langle\omega,\,\beta_t\rangle+\theta_\alpha\langle\omega,\,\beta_\alpha\rangle=2\pi i\theta_t+2\pi i\theta_\alpha\int_{\infty_-}^{\infty_+}\omega,
\end{equation}
which gives  \eqref{eq:thetat1}. Equation \eqref{eq:thetah1} follows in the same way. 
 \end{proof}


\begin{remark}
Note that
\begin{equation}
    \label{thatone}
\theta_t=\frac{1}{2}\int_{(q,-p)}^{(q,p)}\omega-\frac{1}{2}\int_{\infty_-}^{\infty_+}\omega=\frac{1}{2} \int_{(q,-p)}^{\infty_-}\omega+ \frac{1}{2}\int_{\infty_+}^{(q,p)}\omega=\int_{\infty_+}^{(q,p)}\omega\end{equation}
using anti-invariance of $\omega$. 
Taking a base-point $(x_0,y_0)\in \Sigma$ we have

\begin{equation}
\begin{split}\Res_{x=\infty_{+}}\left(\frac{dx}{x}\int^{(x,y)}_{(x_0,y_0)}\beta_t \right) &= \Res_{x=\infty_{+}}\left(\frac{dx}{x}\int^{(x,y)}_{(x_0,y_0)}(\beta_t- \half dx) \right)+  \Res_{x=\infty_{+}}\left(\frac{dx}{x}\int_{x_0}^{x} \half dx \right)\\
&=-\int_{(x_0,y_0)}^{\infty_+} (\beta_t- \half dx) + \half x_0.\end{split}\end{equation}
Choosing $(x_0,0)\in \Sigma$ to be a branch-point we can then use anti-invariance of $\beta_t$ to write
\begin{equation}
 \label{thisone}
\begin{split}\theta_H&=-\int_{(x_0,0)}^{(q,p)} (\beta_t-\half dx)-\half(q-x_0) -(pr+qs)+\int_{(x_0,0)}^{\infty_+} (\beta_t-\half dx) -\half x_0 \\
   &=-\int_{\infty_+}^{(q,p)} (\beta_t-\half dx) -(pr+qs)-\frac{q}{2}.\end{split}\end{equation}
\end{remark}



\subsection{Isomonodromic flows in new coordinates}

 Let $\Xi:\,(t,H,\alpha, q,r,s)\rightarrow(t,H,\alpha,\theta_t,\theta_H,\theta_\alpha)$ be the change of coordinates given by the formulae of Lemma \ref{74}.  


\begin{proposition}\label{thm:XiII}
    The push-forward of the isomonodromic flows along $\Xi$ can be written in the form
\begin{equation}
	\Xi_*(w_1)=\frac{\partial}{\partial t}+\frac{1}{\e}\frac{\partial}{\partial \theta_t}+\frac{\partial^2K}{\partial\theta_t\partial\theta_H}\frac{\partial}{\partial\theta_t}-\frac{\partial^2K}{\partial\theta_t^2}\frac{\partial}{\partial\theta_H},
\end{equation}
\begin{equation}
	\Xi_*(w_2)=\frac{\partial}{\partial H}+\frac{1}{\e}\frac{\partial}{\partial \theta_H}+\frac{\partial^2K}{\partial\theta_H^2}\frac{\partial}{\partial\theta_t}-\frac{\partial^2K}{\partial\theta_H\partial\theta_t}\frac{\partial}{\partial\theta_H},
\end{equation}
\begin{equation}\Xi_*(w_3)=\frac{\partial}{\partial \alpha}+\frac{1}{\e}\frac{\partial}{\partial \theta_\alpha}+\frac{\partial^2K}{\partial\theta_\alpha\partial \theta_H}\frac{\partial}{\partial\theta_t}-\frac{\partial^2K}{\partial\theta_\alpha\partial\theta_t}\frac{\partial}{\partial\theta_H}.\end{equation}
\end{proposition}

\begin{proof}
For $i=0,\ldots, 4$ we define
\begin{equation}
	\kappa_i:=\frac{1}{4}\int_{(q,-p)}^{(q,p)}\frac{x^i\dd x}{y^3}+\frac{1}{2}\Res_{\zeta=\infty_+}\left(\frac{d\zeta}{\zeta}\int^\zeta \frac{x^idx}{y^3} \right).
\end{equation} 
Differentiating the change of coordinates gives
\begin{equation}
	\Xi_*\left(\frac{\partial}{\partial t} \right)=\frac{\partial}{\partial t}-\kappa_2\frac{\partial}{\partial\theta_t}+\frac{1}{2}\left(\kappa_4-\frac{rq^2}{p} \right)\frac{\partial}{\partial \theta_H},
\end{equation}
\begin{equation}
	\Xi_*\left(\frac{\partial}{\partial H} \right)=\frac{\partial}{\partial H}-2\kappa_0\frac{\partial}{\partial\theta_t}+\left(\kappa_2-\frac{r}{p} \right)\frac{\partial}{\partial\theta_H},
\end{equation}
\begin{equation}
	\Xi_*\left(\frac{\partial}{\partial\alpha} \right)=\frac{\partial}{\partial\alpha}+2\kappa_1\frac{\partial}{\partial\theta_t}-\left(\kappa_3-\frac{rq}{p}\right)\frac{\partial}{\partial\theta_H},
\end{equation}
\begin{equation}
	\Xi_*\left(\frac{\partial}{\partial r} \right)=-p\frac{\partial}{\partial\theta_H},\qquad \Xi_*\left(\frac{\partial}{\partial s} \right)=-\frac{\partial}{\partial\theta_\alpha}-q\frac{\partial}{\partial\theta_H},
\end{equation}
\begin{equation}
	\Xi_*\left(\frac{\partial}{\partial q} \right)=\frac{1}{p}\frac{\partial}{\partial\theta_t}-\left(\frac{r}{p}(2q^3+tq-\alpha)+s+\frac{q^2}{2p}\right)\frac{\partial}{\partial\theta_H}.
\end{equation}
We can invert this to find
\begin{equation}
\label{pegg}
	\Xi_*^{-1}\left(\frac{\partial}{\partial\theta_t} \right)=p\frac{\partial}{\partial q}-\left(\frac{r}{p}(2q^3+tq-\alpha)+s+\frac{q^2}{2p}\right)\frac{\partial}{\partial r},
\end{equation}
\begin{equation}
\label{pegg2}
	\Xi_*^{-1}\left(\frac{\partial}{\partial\theta_H} \right)=-\frac{1}{p}\frac{\partial}{\partial r}, \qquad \Xi_*^{-1}\left(\frac{\partial}{\partial\theta_\alpha} \right)=-\frac{\partial}{\partial s}+\frac{q}{p}\frac{\partial}{\partial r}.
\end{equation}

The isomonodromy flows become
\begin{equation}
 \Xi_*(w_1)  = \frac{\partial}{\partial t}+\frac{1}{\e}\frac{\partial}{\partial\theta_t}-\left(\kappa_2-\frac{r}{p} \right)\frac{\partial}{\partial\theta_t}+\left(\frac{\kappa_4}{2}-\frac{q^2r}{p}-rs-\frac{r^2}{p}(2q^3+tq-\alpha)\right)\frac{\partial}{\partial\theta_H},
\end{equation}
\begin{equation}
    \Xi_*(w_2) = \frac{\partial}{\partial H}+\frac{1}{\e}\frac{\partial}{\partial\theta_H}-2\kappa_0\frac{\partial}{\partial\theta_t}+\left(\kappa_2-\frac{r}{p} \right)\frac{\partial}{\partial\theta_H},
\end{equation}
\begin{equation}
    \Xi_*(w_3)=\frac{\partial}{\partial\alpha} +\frac{1}{\e}\frac{\partial}{\partial\theta_\alpha} +2\kappa_1\frac{\partial}{\partial\theta_t}-\left(\kappa_3-\frac{rq}{p}\right)\frac{\partial}{\partial\theta_H},
\end{equation}
and arguing as in the proof of Proposition \ref{propIII}  gives the existence of the required function $K$.
\end{proof}

The function $K$ satisfies
\begin{equation}\label{herehere1}
    \frac{\partial^3K}{\partial\theta_H^3}=0, \qquad \frac{\partial^3K}{\partial\theta_H^2\partial\theta_t}=-\frac{1}{p^2},\qquad \frac{\partial^3K}{\partial\theta_H\partial\theta_t^2}=-\frac{2r \left(2 q^3+ tq -\alpha\right)}{p^2}-\frac{q^2}{p^2}-\frac{s}{p},
\end{equation}
\begin{multline}\label{herehere2}
    \frac{\partial^3K}{\partial\theta_t^3}=-\frac{3 q^4}{4 p^2}+r \left(2q-\frac{3 q^2 \left(2q^3+tq-\alpha \right)}{p^2}\right)\\+  r^2 \left(6 q^2+t-\frac{3 \left(2q^3+tq-\alpha \right)^2}{p^2}\right)
    -\frac{3sq^2}{2p}-\frac{3sr\left(2q^3+tq-\alpha\right)}{p}-s^2,
\end{multline}

\begin{equation}
    \frac{\partial^3K}{\partial\theta_\alpha \partial \theta_H^2}=0, \qquad \frac{\partial^3K}{\partial\theta_\alpha \partial \theta_H \partial \theta_t}=\frac{q}{p^2}, \qquad \frac{\partial^3K}{\partial\theta_\alpha \partial \theta_t^2}=\frac{q^3}{p^2}-r+\frac{sq}{p} +\frac{2rq}{p^2} (2q^3+tq-\alpha),
\end{equation}
\begin{equation}
   \frac{\partial^3K}{\partial\theta_\alpha^2 \partial \theta_H}=0, \qquad \frac{\partial^3K}{\partial\theta_\alpha^2 \partial \theta_t}=-\frac{q^2}{p^2}. 
\end{equation}



\subsection{Pleba{\'n}ski function}



We explained in Section \ref{sec:Quad} that to obtain a Joyce structure we must restrict to the symplectic leaf \eqref{m} obtained by setting the residue $\alpha=0$. Equivalently, by \eqref{z3}, this is  the locus $z_3=0$. Recall from \eqref{poisson} that the Poisson structure  is given by \begin{equation}\{z_1,z_2\}=2\pi i \, \<\gamma_1,\gamma_2\>=2\pi i.\end{equation} Inverting this gives the symplectic form  
\begin{equation}\label{handyII} \Omega_0=-\frac{1}{2\pi i} \cdot dz_1\wedge dz_2 = \frac{1}{2\pi i}  (\omega_1\beta_{t,2}-\omega_2\beta_{t,1})\cdot dt\wedge dH=dt\wedge dH,\end{equation}
on $M$, where we used  \eqref{againy} and \eqref{hand}.

We must also  restrict the value of $\theta_3=2\pi i \theta_\alpha$. As discussed in Remark \ref{earlyish} this is a slightly subtle point. To get a Joyce structure it is necessary to take $\theta_3\in \pi i \bZ$. In what follows we shall make the choice $\theta_3=\pi i$, which by Lemma \ref{74} corresponds to setting $s=0$.


\begin{theorem}
Take $\alpha=0=s$. Then in terms of the co-ordinates $(z_1,z_2,\theta_1,\theta_2)$	the isomonodromic flows  take the form
\begin{equation}
\label{eq:thmPlebII}
