\subsection{Behaviour on the zero section via uniformisation}

Recall that we have set $\alpha=0=s$. Introducing the variables 
\begin{equation}
    \label{haha}X=\frac{t}{12}+\frac{1}{2}(y+x^2), \qquad Y=\frac{tx}{2}+xy+x^3,\end{equation}
the spectral curve \eqref{eq:SigmaPII}  takes the standard Weierstrass form
\begin{equation}Y^2=4X^3-g_2 X -g_3, \qquad g_2=\frac{1}{12}(24H+t^{2}), \qquad g_3=\frac{ t}{216}(72H -t^{2}).
\end{equation}
The inverse transformation to \eqref{haha} is
\begin{equation}\label{trees}x = \frac{3Y}{6X+t}, \qquad y =  \frac{144X^2+48Xt+72H-5t^2}{24(6X+t)}.\end{equation}


We can uniformise $\Sigma$ by writing $X=\wp(u)$ and $Y=\wp'(u)$, with $\wp(u)$ the Weierstrass $\wp$-function for the lattice spanned by the periods $\omega_i$. Beware that the involution $u\mapsto -u$ does not correspond to $\sigma\colon (x,y)\mapsto (x,-y)$ but rather to $\sigma'\colon (x,y)\mapsto (-x,y)$. A calculation shows that
\begin{equation}\omega=\frac{dx}{y}=\frac{dX}{Y}=du, \qquad \beta_t=\frac{x^2\omega}{2} = \frac{X\, dX}{Y}-\frac{t\, dX}{12Y} -\frac{dx}{2}.\end{equation}

Recall from Section \ref{summy} the definition of the function $S=S(t,H)$ and the linear Joyce connection.

% The branch points of the map $(X,Y)\mapsto X$ are $(X,Y)=(e_i,0)$ with $i=1,2,3$, and $(X,Y)=(\infty,\infty)$, where
%  \begin{equation} e_1=\frac{t+6\sqrt{H}}{3}, \qquad e_2=\frac{t-6\sqrt{H}}{3},\qquad e_3=-\frac{2t}{3}.\end{equation}
% %We can choose periods $\omega_1,\omega_2$ so that  $e_i=\wp(\half\omega_i)$ for $i=1,2$ and then $e_3=\wp(\half\omega)$ with $\omega=\omega_1+\omega_2$.
% In the co-ordinates $(X,Y)$ the points $\infty_\pm\in \Sigma$ correspond to $(e_3,0)$ and $(\infty,\infty)$. %Note that $(e_1,0)$ and $(e_2,0)$ are the two points of $\Sigma$  lying over $x=0$,  $(e_3,0)$ is  $\infty_-$, and $(\infty,\infty)$  is  $\infty_+$. 







\begin{theorem}\label{thm:Pleba{'n}skiOperII}
\begin{itemize}
    \item[(i)]The Pleba{\'n}ski function $W$ is regular on the locus $\theta_t=\theta_H=0$.

    \item[(ii)] There is an identity
     \begin{equation}S= \log \left(H^2(8H-t^2)\right)^{-\frac{1}{48}}.\end{equation}
 \item[(iii)] The co-ordinates $(t,H-\tfrac{1}{8}
 t^2)$ on $M$ are flat for the linear Joyce connection.
 \end{itemize}
\end{theorem}

\begin{proof}
Recall that we have set $\alpha=0=s$. We denote by $v\in \bC$ a point corresponding to the point $(q,p)\in \Sigma$.  Using the involution $\sigma'$ the formula \eqref{thisone} becomes 
       \begin{equation}\label{shoulder}\theta_H=-\frac{1}{2}\int_{(-q,p)}^{(q,p)}(\beta_t-\half dx) -pr-\frac{q}{2}=\zeta(v) +\frac{tv}{12}+\frac{q}{2}-pr.\end{equation}
       Using the expansion
\begin{equation}\zeta(v)=\frac{1}{v}-\left(\frac{H}{30}+\frac{t^2}{720}\right)v^3 +O(v^5),\end{equation}
and introducing a new parameter $w$ by writing \begin{equation}\label{rr}r=\frac{v}{2} - wv^2+\frac{tv^3}{12}\end{equation} we then have
\begin{equation}\label{care}\theta_t=v, \qquad \theta_H=w+\frac{twv^2}{6} +O((v,w)^3).\end{equation}

The formulae \eqref{trees} and the expansion of $\wp(v)=-\zeta'(v)$  gives
\begin{equation}
    q= -\frac{1}{v}+\frac{tv}{6}+\left(\frac{H}{5}-\frac{7t^2}{360}\right) v^3+O(v^5), \qquad p=\frac{1}{v^2}+\frac{t}{6}+\left(\frac{3H}{5}-\frac{7t^2}{120}\right) v^2 + O(v^4).
\end{equation}
Substituting these expressions and \eqref{rr} into \eqref{plebII} we find that $W$ is regular  along the locus $\theta_t=\theta_H=0$ with leading order behaviour 
\begin{equation}W=\frac{tv}{24(8H-t^2)}\ - \frac{(12H-t^2)w}{24H(8H-t^2)} + O((v,w)^3).\end{equation}
This gives (i) and (ii). For (iii) we substitute \eqref{care} into \eqref{herehere1} - \eqref{herehere2} to get
\begin{equation}\frac{\partial^3 K}{\partial \theta_t^3}\bigg\vert_{\theta_t=\theta_H=0}=-\frac{1}{4}, \qquad \frac{\partial^3 K}{\partial \theta_t^2\theta_H}\bigg\vert_{\theta_t=\theta_H=0}=\frac{\partial^3 K}{\partial \theta_H^3}\bigg\vert_{\theta_t=\theta_H=0}=\frac{\partial^3 K}{\partial \theta_t\partial \theta_H^2}\bigg\vert_{\theta_t=\theta_H=0}=0.\end{equation}
  It follows that the linear Joyce connection $\nabla^J$  satisfies
  \begin{equation}
      \nabla^J_{\frac{\partial}{\partial t}}\left(\frac{\partial}{\partial t}\right)=-\frac{1}{4}\frac{\partial}{\partial H}, \qquad \nabla^J_{\frac{\partial}{\partial H}}\left(\frac{\partial}{\partial t}\right)=0, \qquad \nabla^J_{\frac{\partial}{\partial t}}\left(\frac{\partial}{\partial H}\right)=\nabla^J_{\frac{\partial}{\partial H}}\left(\frac{\partial}{\partial H}\right)=0,
  \end{equation}
  and a basis of flat vector fields is therefore given by $(\partial_t+\tfrac{1}{4} t\partial_H,\partial_H)$. The corresponding flat co-ordinates are $(t,H- \tfrac{1}{8}t^2)$ as claimed.
  % \tab{These are extremely close but it seems not equal to the flat co-ordinates for the A$_3$ Frobenius manifold which are $(t,H-\frac{1}{16}t^2)$.}
\end{proof}




\subsection{Alternative approach: poles of Painlev\'e II}
In the same way as for the case of Painlev\'e III, we can alternatively study the limit $\theta_t=\theta_H=0$ by studying the behaviour of the Pleba\'nski function at a pole $t=t_0$ of the Painlev\'e II equation
\begin{equation}
	\e^2\frac{d^2q}{dt^2}=2q^3+qt-\alpha.
\end{equation}
We set $s=0$ but keep $\alpha$ as a parameter for now. Choosing one of the two branches at infinity we find the following behaviour 
\begin{equation}
	q=-\frac{\e }{t-t_0}+\frac{t_0 (t-t_0)}{6 \e }+\alpha\frac{(t-t_0)^2 }{4 \e ^2}+
    %\frac{\e}{t-t_0}-\frac{t_0}{6}\frac{t-t_0}{\e}+\frac{\alpha-\e}{4}\left(\frac{t-t_0}{\e} \right)^2+q_0(t-t_0)^3 +O(t-t_0)^3 ,
    q_0 (t-t_0)^3
\end{equation}
\begin{equation}
p=\frac{\e ^2}{(t-t_0)^2}+\frac{t_0}{6}+O(t-t_0), \qquad 
	r=c (t-t_0)^2+\frac{ (t-t_0)}{2 \hbar },
\end{equation}
with the parameters $c,q_0$ left undetermined by the equations. 
We have
\begin{equation}
	\theta_t=\frac{t-t_0}{\e }+\frac{(t-t_0)^4}{12 \e ^3}+O(t-t_0)^5,\qquad \theta_H=-\e^2 c+\frac{(t-t_0)^2}{8 \e }+O(t-t_0)^3,
\end{equation}
so that $t-t_0$ and $c$ parametrise, at leading order, the deviations from the zero section, which is parametrised by $t_0$ and $H_0:=H\left(q(t_0),p(t_0),t_0 \right)$. For $\alpha\ne0$, the function $W$ does not vanish for $\theta=0$. It is given by
\begin{equation}
    W_0(H_0,t_0,\alpha)=\frac{\alpha\,  t_0}{24H_0(8H_0-t_0^2)}
    %-\frac{\alpha}{24\Delta}  \left(45 \alpha ^2-56 H_0 t_0+t_0^3\right)
\end{equation}
In particular it is regular along $\theta=0$. When $\alpha=0$, $W$ is associated to a Joyce structure, and
\begin{equation}
	 W\big|_{\alpha=s=0}\simeq  \frac{t_0^2-12 H_0}{24 H_0 \left(8 H_0-t_0^2\right)}\theta_H+\frac{t_0}{24 H_0 \left(8 H_0-t_0^2\right)}\theta _t,
\end{equation}
so that, analogously to what happened in the Painlev\'e III and I cases, the function vanishes linearly. The generating function is $S=\log\left(H^2(8H-t^2) \right)^{-\frac{1}{48}}$, matching with the result from uniformization.

We could do the same compuation by expanding instead arouns $s=1/2$, i.e. $\theta_\alpha=0$. The resulting expression would have been
\begin{equation}
	 W\big|_{\alpha=0,\,\theta_\alpha=0}\simeq  \frac{t_0^2-12 H_0}{24 H_0 \left(8 H_0-t_0^2\right)}\theta_H+\frac{t_0}{24H_0(8 H_0- t_0^2)}\theta _t,
\end{equation}
which has generating function $S=-\frac{1}{24}\log\left(H(8H-t^2)^2 \right)=\log\Delta^{-\frac{1}{24}} $.


