\title{Nine circles of elastic brittle fracture: A series of challenge problems to assess fracture models\vspace{0.1cm}}

\author[Illinois]{Farhad Kamarei}
\ead{kamarei2@illinois.edu}

\author[Duke]{Bo Zeng}
\ead{Bo.zeng@duke.edu}


