\caption{\small Poker-chip test on the PU elastomer. Contour plots of the phase field $z$ over the undeformed configuration of the specimen right after fracture nucleation, as predicted by the \texttt{AT}$_1$ and phase-field models for regularization length $\varepsilon=0.025$ mm.}\label{Fig17}
\end{figure}
