\section*{Appendix A. The phase-field formulation of \cite*{KFLP18}}


In this Appendix, we briefly recall the phase-field model introduced by \cite*{KFLP18}. For simplicity of exposition, consistent with the choices in the main body of the text of the soda-lime glass and the PU elastomer as representative hard and soft materials, we present the model for the basic case of elastic brittle materials with Neo-Hookean elasticity and its specialization to linear elasticity in the limit of small deformations. For a complete account, including mathematical well-posedness, thermodynamic consistency, FE schemes to solve the resulting governing equations, and validation with experiments the interested reader is referred to \cite{KFLP18,KRLP18,KLP20,KBFLP20,KLP21,KRLP22,KLDLP24,LDLP24}; and \cite{KKLP24}.


\paragraph{Initial configuration, kinematics, and boundary conditions} Consider a generic specimen that, initially, at time $t=0$, occupies the open bounded domain $\Omega$. We denote its boundary by $\partial \Omega$, its outward unit normal by $\bfN$, and identify material points by their initial position vector $\bfX\in \Omega$. The specimen is subjected a deformation $\overline{\bfy}(\bfX,t)$ on a part $\partial \Omega_{\mathcal{D}}$ of the boundary, and a surface force (per unit undeformed area) $\overline{\bfs}(\bfX,t)$ on the complementary part $\partial \Omega_{\mathcal{N}}=\partial\Omega\setminus\partial \Omega_{\mathcal{D}}$; for simplicity, body forces are considered to be absent. In response to these boundary conditions, the position vector $\bfX$ of a material point in the specimen will move to a new position specified by 
%
\begin{equation}
\bfx=\bfy(\bfX,t)=\bfX+\bfu(\bfX,t),\label{def-mapping}
\end{equation}
%
where $\bfy(\bfX,t)$ and $\bfu(\bfX,t)$ are the deformation and displacement fields. We write the associated deformation gradient at $\bfX$ and $t$ as $\bfF(\bfX,t)=\nabla\bfy(\bfX,t)=\bfI+\nabla\bfu(\bfX,t)$. In addition to the deformation (\ref{def-mapping}), the boundary conditions may result in the nucleation and subsequent propagation of cracks in the specimen. We describe such cracks in a regularized fashion via the phase field
%
\begin{equation*}
z=z(\bfX,t)
\end{equation*}
%
taking values in the range $[0, 1]$. The value $z=1$ identifies the intact regions of the material and $z=0$ the regions that have been fractured, while the transition from $z=1$ to $z=0$ is set to occur smoothly over regions of small thickness of regularization length scale $\varepsilon>0$.

\paragraph{Constitutive behavior} As noted above, the specimen is taken to be made of a homogeneous, isotropic, elastic brittle material whose elastic behavior is characterized by the Neo-Hookean elastic energy density (\ref{W-NH}). It follows that the first Piola-Kirchhoff stress at any material point $\bfX\in\Omega$ and time $t\in[0,T]$ is given by
%
\begin{equation}
\bfS(\bfX,t)=\dfrac{\partial \psi}{\partial \bfF}(\bfF)=\mu(\bfF-\bfF^{-T})+\Lambda(\det\bfF-1)(\det\bfF)\bfF^{-T}.\label{S-NH}
\end{equation}
%
Moreover, the strength of the material is characterized by the Drucker-Prager strength surface (\ref{DP}), where we recall that $\mathcal{I}_1=s_1+s_2+s_3$ and $\mathcal{J}_2=1/3(s_1^2+s_2^2+s_3^2-s_1 s_2-s_1 s_3-s_2s_3)$ stand for the first and second principal invariants of the Biot stress tensor $\bfS^{(1)}=(\bfS^T\bfR+\bfR^T\bfS)/2$, with $s_1$, $s_2$, $s_3$ denoting the principal Biot stresses and $\bfR$ the rigid rotation from the polar decomposition $\bfF=\bfR\bfU$, while the material constants $s_{\texttt{ts}}>0$ and $s_{\texttt{hs}}>0$ stand for the uniaxial tensile and hydrostatic strengths of the material. That is, they denote the critical nominal stress values at which fracture nucleates under uniform states of monotonically increased uniaxial tension $\bfS={\rm diag}(s>0,0,0)$ and hydrostatic stress $\bfS={\rm diag}(s>0,s>0,s>0)$, respectively. Finally, the critical energy release rate of the material is characterized by the scalar (\ref{Gc}).


\paragraph{Governing equations} According to the phase-field fracture formulation put forth by \citet*{KFLP18}, the deformation field $\bfy_k(\bfX)=\bfy(\bfX,t_k)$ and phase field $z_k(\bfX)=z(\bfX,t_k)$ at any material point $\bfX \in \overline{\Omega}=\Omega\cup\partial\Omega$ and at any given discrete time $\{t_{k}\}_{k=0,1,\ldots,M}$, with $t_{0} = 0$ and $t_{M} = T$, are determined by the system of coupled partial differential equations\footnote{The Neumann boundary condition (\ref{BVP-z-theory})$_2$ may be replaced by the Dirichlet boundary condition $z_k=0$ at the front of any pre-existing crack and sharp corner that the boundary $\partial\mathrm{\Omega}$ of the specimen may feature. The simulations for the pure-shear test, the double cantilever beam test, and the trousers test in the main body of the text are carried out with this Dirichlet boundary condition. On the other hand, the simulations for the single edge notch test are carried out with the Neumann boundary condition.}
%
\begin{equation}
\left\{\begin{array}{ll}
{\rm Div}\left[z_{k}^2 (2\mu(\nabla \bfy_{k}-\nabla \bfy_{k}^{-T})+\Lambda(J_k-1)J_k\nabla \bfy_{k}^{-T})\right]=\textbf{0},& \,\bfX\in\Omega\vspace{0.2cm}\\
\bfy_k(\bfX)=\overline{\bfy}(\bfX,t_k), & \; \bfX\in\partial\Omega_{\mathcal{D}}\vspace{0.2cm}\\
\left(z_{k}^2 (2\mu(\nabla \bfy_{k}-\nabla \bfy_{k}^{-T})+\Lambda(J_k-1)J_k\nabla \bfy_{k}^{-T})\right)\bfN=\overline{\bfs}(\bfX,t_k),& \; \bfX\in\partial\Omega_{\mathcal{N}}
\end{array}\right. \label{BVP-y-theory}
\end{equation}
%
and
%
\begin{equation}
\left\{\begin{array}{ll}
\hspace{-0.15cm} \varepsilon\, \delta^\varepsilon G_c \triangle z_k=\dfrac{8}{3}z_{k} \psi(\nabla\bfy_k)-\dfrac{4}{3}c_\texttt{e}(\bfX,t_{k})-\dfrac{\delta^\varepsilon G_c}{2\varepsilon}+\dfrac{8}{3\,\zeta} \, p(z_{k-1},z_k),& \bfX\in \Omega
\vspace{0.2cm}\\
\hspace{-0.15cm}\nabla z_k\cdot\bfN=0,&  \bfX\in \partial\Omega
\end{array}\right. \label{BVP-z-theory}
\end{equation}
%
with $p(z_{k-1},z_k)=|z_{k-1}-z_k|-(z_{k-1}-z_k)-|z_k|+z_k$. In these equations, $\nabla \bfy_k(\bfX)=\nabla \bfy(\bfX,t_k)$, $J_k=\det\nabla\bfy_k$, $\nabla z_k(\bfX)=\nabla z(\bfX,t_k)$, $\triangle z_k(\bfX)=\triangle z(\bfX,t_k)$, $\zeta$ is a penalty parameter\footnote{The penalty function $p(z_{k-1},z_k)$ and penalty parameter $\zeta$ in (\ref{BVP-z-theory}) enforce that the phase field remains in the physically admissible range $0\leq z\leq 1$ and that fracture is irreversible. These requirements can be enforced by means of different strategies \citep{Wick15}, the penalty approach spelled out here being one of them. In the RACCOON implementation, for example, these inequalities are enforced using the primal-dual active set strategy.}  such that\footnote{Typically, it suffices to set $\zeta^{-1}=10^4 \delta^\varepsilon G_c/(2\varepsilon)$.} $\zeta^{-1}\gg \delta^\varepsilon G_c/(2\varepsilon)$, and, making use of the constitutive prescription\footnote{The constitutive prescription for $c_{\texttt{e}}$ depends on the particular form of the strength surface $\mathcal{F}(\bfS)=0$ of the material. For the case of the Drucker-Prager strength surface (\ref{DP}) of interest here, it is given by (\ref{ce}). For other strength surfaces, corresponding prescriptions for $c_{\texttt{e}}$ can be constructed by following the blueprint outlined by \cite{KLP20} and \cite{KBFLP20}.} in \citep{KKLP24}, 
%
\begin{align}
c_{\texttt{e}}(\bfX,t)&=z^2\beta_2\sqrt{\mathcal{J}_2}+z^2\beta_1\mathcal{I}_1+z\left(1-\dfrac{\sqrt{\mathcal{I}^2_1}}{\mathcal{I}_1}\right)\psi(\bfF)\label{ce}
\end{align}
%
with 
%
\begin{equation}
\left\{\hspace{-0.15cm}\begin{array}{l}
\beta_1=-\dfrac{1}{\shs}\delta^\varepsilon\dfrac{G_c}{8\varepsilon}+\dfrac{2\psi_{\texttt{hs}}}{3\shs}\vspace{0.2cm}\\
\beta_2=-\dfrac{\sqrt{3}(3\shs-\sts)}{\shs\sts}\delta^\varepsilon\dfrac{G_c}{8\varepsilon}-
\dfrac{2\psi_{\texttt{hs}}}{\sqrt{3}\shs}+\dfrac{2\sqrt{3}\psi_{\texttt{ts}}}{\sts}
\end{array}\right.\quad {\rm and}\quad \delta^\varepsilon=\left(\dfrac{\sts+(1+2\sqrt{3})\,\shs}{(8+3\sqrt{3})\,\shs}\right)\dfrac{3 G_c}{16\psi_{\texttt{ts}}\varepsilon}+\dfrac{2}{5}. \label{deltaeps}
\end{equation}
%
In these last expressions, $\psi_{\texttt{ts}}$ and $\psi_{\texttt{hs}}$ stand for the values of the stored-energy function (\ref{W-NH}) along uniform uniaxial tension and hydrostatic stress states at which the strength surface (\ref{DP}) is violated:
%
\begin{equation*}
\psi_{\texttt{ts}}=\dfrac{\mu}{2}(\l^2_{\texttt{ts}}+2\l^2_l-3)-\mu\ln(\l_{\texttt{ts}}\l_l^2)+\dfrac{\Lambda}{2}(\l_{\texttt{ts}}\l_l^2-1)^2\quad {\rm and}\quad \psi_{\texttt{hs}}=\dfrac{\mu}{2}(3\l^2_{\texttt{hs}}-3)-\mu\ln(\l^3_{\texttt{hs}})+\dfrac{\Lambda}{2}(\l^3_{\texttt{hs}}-1)^2,%\label{Wt}
\end{equation*}
%
where the pair of stretches ($\l_{\texttt{ts}}, \l_l$) and the stretch $\l_{\texttt{hs}}$ are defined implicitly as the roots closest to $(1,1)$ and $1$ of the non-linear algebraic equations
%
\begin{align*}
&\left\{\begin{array}{l}
s_{\texttt{ts}}=\mu(\l_{\texttt{ts}}-\l_{\texttt{ts}}^{-1})+\Lambda(\l_{\texttt{ts}}\l_l^4-\l_l^2)\\[10pt]
0=\mu(\l_l-\l_l^{-1})+\Lambda\l_{\texttt{ts}}\l_l(\l_{\texttt{ts}}\l_l^2-1)\end{array}\right. \quad {\rm and}\quad s_{\texttt{hs}}=\mu(\lambda_{\texttt{hs}}-\lambda_{\texttt{hs}}^{-1})+\Lambda\lambda_{\texttt{hs}}^2(\lambda_{\texttt{hs}}^3-1),  %\label{Eqts}
\end{align*}
%
respectively. For the PU elastomer with the material constants listed in Table \ref{Table2},  $\l_{\texttt{ts}}=1.2342$, $\l_l=0.9007$, $\lambda_{\texttt{hs}}=1.0038$, and hence $\psi_{\texttt{ts}}=37.31$ kPa and $\psi_{\texttt{hs}}=5.718$ kPa.

\begin{remark}
\emph{As noted throughout the main body of the text, the strength of a material is inherently stochastic. This is because the strength at any given macroscopic material point depends on the varying nature of the underlying defects where fracture originates. Consequently, the strength constants $\sts$ and $\shs$ in the equations above should be considered as stochastic material constants, and not as deterministic values. In all the phase-field simulations presented in the main body of the text, $\sts$ is assigned random values within $\pm 5\%$ of those listed in Tables \ref{Table1} and \ref{Table2}. These random values are applied across random subdomains of size $5\varepsilon$.}
\end{remark}

\begin{remark}
\emph{When using the FE method to solve the governing equations (\ref{BVP-y-theory})-(\ref{BVP-z-theory}), meshes of small enough element size $\texttt{h}$ ought to be used so as to appropriately resolve the spatial variations of the phase field $z_k$ over lengths of order $\varepsilon$. Nevertheless, an error is incurred that scales with $\texttt{h}$. It is possible to include a correction in the formula (\ref{deltaeps})$_2$ for $\delta^\varepsilon$ so that the FE solutions of equations (\ref{BVP-y-theory})-(\ref{BVP-z-theory}) are consistent with the actual value $G_c$ of the critical energy release rate of the material. For first-order FEs of size $\texttt{h}$, the formula for $\delta^\varepsilon$ with the correction reads \citep{KKLP24}
%
\begin{equation*}
\delta^\varepsilon=\left(1+\dfrac{3}{8}\dfrac{\texttt{h}}{\varepsilon}\right)^{-2}\left(\dfrac{\sts+(1+2\sqrt{3})\,\shs}{(8+3\sqrt{3})\,\shs}\right)\dfrac{3 G_c}{16\psi_{\texttt{ts}}\varepsilon}+\left(1+\dfrac{3}{8}\dfrac{\texttt{h}}{\varepsilon}\right)^{-1}\dfrac{2}{5}.
\label{delta-eps-final-h}
\end{equation*}
%
}
\end{remark}


\paragraph{Governing equations: The limit of small deformations} In the limit of small deformations, the elasticity of the material reduces to isotropic linear elasticity. In particular, to leading order, the elastic energy density (\ref{W-NH}) and stress-deformation relation (\ref{S-NH})  reduce to (\ref{W-Lin}) and
%
\begin{equation*}
\bfS(\bfX,t)=\dfrac{\partial W}{\partial \bfE}(\bfE)=2\mu\,\bfE+\Lambda ({\rm tr}\,\bfE)\bfI,%\label{S-Lin}
\end{equation*}
%
respectively. Making use of the displacement field $\bfu(\bfX,t)=\bfy(\bfX,t)-\bfX$ instead of the deformation field $\bfy(\bfX,t)$ and rewriting the phase-field as $v(\bfX,t)$ instead of $z(\bfX,t)$ for further clarity of notation, it follows that the governing equations (\ref{BVP-y-theory})-(\ref{BVP-z-theory}) reduce to 
%
\begin{equation}
\left\{\begin{array}{ll}
\hspace{-0.15cm} {\rm Div}\left[v_{k}^2 \left(2\mu\,\bfE(\bfu_{k})+\Lambda({\rm tr}\,\bfE(\bfu_{k}))\bfI\right)\right]=\textbf{0},& \bfX\in\Omega\vspace{0.2cm}\\
\hspace{-0.15cm} \bfu_k(\bfX)=\overline{\bfu}(\bfX,t_k), & \bfX\in\partial\Omega_{\mathcal{D}}\vspace{0.2cm}\\
\hspace{-0.15cm}v_{k}^2 \left(2\mu\,\bfE(\bfu_{k})+\Lambda ({\rm tr}\,\bfE(\bfu_{k}))\bfI\right)\bfN=\overline{\bfs}(\bfX,t_k),&  \bfX\in\partial\Omega_{\mathcal{N}}
\end{array}\right. \label{BVP-u-theory}
\end{equation}
%
and
%
\begin{equation}
\left\{\begin{array}{ll}
\hspace{-0.15cm} \varepsilon\, \delta^\varepsilon G_c \triangle v_k=\dfrac{8}{3}v_{k} W(\bfE(\bfu_k))-\dfrac{4}{3}c_\texttt{e}(\bfX,t_{k})-\dfrac{\delta^\varepsilon G_c}{2\varepsilon}+\dfrac{8}{3\,\zeta} \, p(v_{k-1},v_k),& \bfX\in \Omega
\vspace{0.2cm}\\
\hspace{-0.15cm}\nabla v_k\cdot\bfN=0,&  \bfX\in \partial\Omega
\end{array}\right., \label{BVP-v-theory}
\end{equation}
%
where $\overline{\bfu}(\bfX,t)=\overline{\bfy}(\bfX,t)-\bfX$ and where
%
\begin{align*}
c_{\texttt{e}}(\bfX,t)&=v^2\beta_2\sqrt{\mathcal{J}_2}+v^2\beta_1\mathcal{I}_1+v\left(1-\dfrac{\sqrt{\mathcal{I}^2_1}}{\mathcal{I}_1}\right)W(\bfE(\bfu))%\label{ce}
\end{align*}
%
with $\mathcal{I}_1=(2\mu+3\Lambda){\rm tr}\,\bfE$, $\mathcal{J}_2=2\mu^2{\rm tr}\,\bfE_D^2$, $\bfE_D=\bfE-\frac{1}{3}({\rm tr}\,\bfE)\bfI$, 
%
\begin{equation*}
\left\{\hspace{-0.15cm}\begin{array}{l}
\beta_1=-\dfrac{1}{\shs}\delta^\varepsilon\dfrac{G_c}{8\varepsilon}+\dfrac{2 W_{\texttt{hs}}}{3\shs}\vspace{0.2cm}\\
\beta_2=-\dfrac{\sqrt{3}(3\shs-\sts)}{\shs\sts}\delta^\varepsilon\dfrac{G_c}{8\varepsilon}-
\dfrac{2W_{\texttt{hs}}}{\sqrt{3}\shs}+\dfrac{2\sqrt{3}W_{\texttt{ts}}}{\sts}
\end{array}\right.,\quad \quad \delta^\varepsilon=\left(\dfrac{\sts+(1+2\sqrt{3})\,\shs}{(8+3\sqrt{3})\,\shs}\right)\dfrac{3 G_c}{16 W_{\texttt{ts}}\varepsilon}+\dfrac{2}{5},
\end{equation*}
%
$W_{\texttt{ts}}=\sts^2/(2E)$, and $W_{\texttt{hs}}=\shs^2/(2\kappa)$. Note that for the soda-lime glass with the material constants listed in Table \ref{Table1}, $W_{\texttt{ts}}=11.43$ kPa and $W_{\texttt{hs}}=9.27$ kPa.


\section*{Appendix B. The classical variational \texttt{AT}$_1$ phase-field model}

The strength surface $\mathcal{F}(\bfS)=0$ of the material enters the phase-field model (\ref{BVP-y-theory})-(\ref{BVP-z-theory}) via the driving force $c_{\texttt{e}}$ and the coefficient $\delta^\varepsilon$. When the presence of the strength surface is removed, 
%
\begin{equation*}
c_{\texttt{e}}=0\quad {\rm and}\quad \delta^\varepsilon=1,
\end{equation*}
%
the phase-field model (\ref{BVP-y-theory})-(\ref{BVP-z-theory}) reduces to the classical variational \texttt{AT}$_1$ phase-field model for a Neo-Hookean elastic material:
%
\begin{equation}
\left\{\begin{array}{ll}
{\rm Div}\left[z_{k}^2 (2\mu(\nabla \bfy_{k}-\nabla \bfy_{k}^{-T})+\Lambda(J_k-1)J_k\nabla \bfy_{k}^{-T})\right]=\textbf{0},& \,\bfX\in\Omega\vspace{0.2cm}\\
\bfy_k(\bfX)=\overline{\bfy}(\bfX,t_k), & \; \bfX\in\partial\Omega_{\mathcal{D}}\vspace{0.2cm}\\
\left(z_{k}^2 (2\mu(\nabla \bfy_{k}-\nabla \bfy_{k}^{-T})+\Lambda(J_k-1)J_k\nabla \bfy_{k}^{-T})\right)\bfN=\overline{\bfs}(\bfX,t_k),& \; \bfX\in\partial\Omega_{\mathcal{N}}
\end{array}\right. \label{BVP-y-theory-AT1}
\end{equation}
%
and
%
\begin{equation}
\left\{\begin{array}{ll}
\hspace{-0.15cm} \varepsilon\,  G_c \triangle z_k=\dfrac{8}{3}z_{k} \psi(\nabla\bfy_k)-\dfrac{G_c}{2\varepsilon}+\dfrac{8}{3\,\zeta} \, p(z_{k-1},z_k),& \bfX\in \Omega
\vspace{0.2cm}\\
\hspace{-0.15cm}\nabla z_k\cdot\bfN=0,&  \bfX\in \partial\Omega
\end{array}\right. . \label{BVP-z-theory-AT1}
\end{equation}
%

By the same token, when the strength surface $\mathcal{F}(\bfS)=0$ of the material is not accounted for, the phase-field model (\ref{BVP-u-theory})-(\ref{BVP-v-theory}) reduces to the classical variational \texttt{AT}$_1$ phase-field model for an isotropic linear elastic material:
%
\begin{equation}
\left\{\begin{array}{ll}
\hspace{-0.15cm} {\rm Div}\left[v_{k}^2 \left(2\mu\,\bfE(\bfu_{k})+\Lambda({\rm tr}\,\bfE(\bfu_{k}))\bfI\right)\right]=\textbf{0},& \bfX\in\Omega\vspace{0.2cm}\\
\hspace{-0.15cm} \bfu_k(\bfX)=\overline{\bfu}(\bfX,t_k), & \bfX\in\partial\Omega_{\mathcal{D}}\vspace{0.2cm}\\
\hspace{-0.15cm}v_{k}^2 \left(2\mu\,\bfE(\bfu_{k})+\Lambda ({\rm tr}\,\bfE(\bfu_{k}))\bfI\right)\bfN=\overline{\bfs}(\bfX,t_k),&  \bfX\in\partial\Omega_{\mathcal{N}}
\end{array}\right. \label{BVP-u-theory-AT1}
\end{equation}
%
and
%
\begin{equation}
\left\{\begin{array}{ll}
\hspace{-0.15cm} \varepsilon\, G_c \triangle v_k=\dfrac{8}{3}v_{k} W(\bfE(\bfu_k))-\dfrac{G_c}{2\varepsilon}+\dfrac{8}{3\,\zeta} \, p(v_{k-1},v_k),& \bfX\in \Omega
\vspace{0.2cm}\\
\hspace{-0.15cm}\nabla v_k\cdot\bfN=0,&  \bfX\in \partial\Omega
\end{array}\right. . \label{BVP-v-theory-AT1}
\end{equation}
%

\begin{remark}
\emph{When using first-order FEs of size $\texttt{h}$ to solve the governing equations (\ref{BVP-y-theory-AT1})-(\ref{BVP-z-theory-AT1}), or (\ref{BVP-u-theory-AT1})-(\ref{BVP-v-theory-AT1}), the correction 
%
\begin{equation*}
G_c\mapsto \left(1+\dfrac{3\texttt{h}}{8\varepsilon}\right)^{-1}G_c
\end{equation*}
%
