\section{Preliminaries}\label{Preliminaries}

In this section we will collect some analytic definitions and results relevant for the core of the paper. These are mainly related to Sobolev spaces and low regularity geometric structures.
Moreover, in this section we will review some key properties from the Yamabe problem for low regularity metrics. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Sobolev spaces on closed manifolds}
\label{SectionSobolevSpaces}

Given an arbitrary domain $\Omega \subset \nR^n$ we denote by $L^p(\Omega)$, $W^{k,p}(\Omega)$ and $C^{k,\alpha}(\Omega)$ the usual Lebesgue, Sobolev and Hölder spaces and use the notation $W^{k,p}_0(\Omega)$ and $C^{k,\alpha}_0(\Omega)$ for the traceless and compactly supported spaces, respectively. We also say that $u \in W^{k,p}_{loc}(\Omega)$ if $u \in W^{k,p}(K)$ for all 
smooth\footnote{Throughout the paper, we say that a domain is \emph{smooth} if it has smooth boundary.} $K \subset\subset \Omega$. If $E \to \Omega$ is a vector bundle, we write $W^{k,p}(E)$ for the space of $W^{k,p}$ sections of $E$, and likewise for the other spaces. For the precise definitions and properties about these Banach spaces we refer the reader to \cite{GT,AdamsFournierBook} and references therein. 

It will be fundamental for our analysis to be able to preserve Sobolev regularity of functions under rough coordinate transformations. When the coordinate transformation is a $C^k$-diffeomorphism, this is standard \cite[Theorem 3.41]{AdamsFournierBook}, but in the present work we will be concerned with coordinate transformations that are less regular. We call a $W^{k,q}$-diffeomorphism to a $W^{k,q}$-map that is also a $C^1$-diffeomorphism. By an implicit function theorem argument, one can in fact show that the inverse is a $W^{k,q}_{loc}$-map as well, provided that $k \geq 2$ and $q > \tfrac{n}{2}$ --see \cref{IFTSobolevAppendix} for details--. 
\begin{lemma}
    \label{lemma: Adams diffeo lemma}
    Fix $k \geq 2$, $q > \tfrac{n}{2}$ and let $\phi : \Omega \to \Omega'$ be a $W^{k+1,q}$-diffeomorphism between two bounded smooth domains in $\nR^n$.
    %with smooth boundary. 
    If $u \in W^{l,p}(\Omega)$, then $Au\doteq u \circ \phi^{-1} \in W_{loc}^{l,p}(\Omega')$ provided that $l \leq k+1$ and $1\leq p \leq q$. Moreover, \begin{align}
        \label{ChangeOfCoordsMapSob.1}
        \begin{split}
            A:W_{loc}^{l,p}(\Omega)&\to W_{loc}^{l,p}(\Omega')
        \end{split}
    \end{align}    
    is bounded with bounded inverse, meaning that, given any smooth domain $K \subset\subset \Omega$, there exists a constant $C =C(n,p,q,l,K,\phi)$ such that
    \begin{align}
    \label{ChangeOfCoordsMapSob.2}
        \begin{split}
            \Vert Au \Vert_{W^{l,p}(\phi(K))}&\leq C\Vert u \Vert_{W^{l,p}(K)} \,,
            \\
            \Vert A^{-1}v \Vert_{W^{l,p}(K)}&\leq C\Vert v \Vert_{W^{l,p}(K)}
        \end{split}
    \end{align}
    hold for all $u \in W^{l,p}_{loc}(\Omega)$ and $v \in W^{l,p}_{loc}(\Omega')$.
\end{lemma}
\begin{proof}
    We name $K' = \phi(K) \subset\subset \Omega'$ for simplicity. By \cref{LemmaInvFunctThmSobReg} we know that $\phi^{-1} \in W^{k+1,q}_{loc}(\Omega')$ and therefore $\phi^{-1} \in W^{k+1,q}(K')$. The Sobolev embeddings 
    \begin{align*}
        W^{k+1,q}(K) \hookrightarrow C^{k-1}(K) \,, \qquad W^{k+1,q}(K') \hookrightarrow C^{k-1}(K')
    \end{align*}
    imply that $\phi: K \to K'$ is a $C^{k-1}$-diffeomorphism, so it follows from \cite[Theorem 3.41]{AdamsFournierBook} that $Au \in W^{l,p}(K')$ for all $u \in W^{l,p}_{loc}(\Omega)$ and the continuity estimates \eqref{ChangeOfCoordsMapSob.2} for $A$ and $A^{-1}$ hold for each $l \leq k-1$.

    Now, if $l = k$ or $l = k+1$, we need to show that $\phi$ preserves, respectively, one or two more levels of Sobolev regularity. We assume that $k = 2$, as the $k > 2$ case follows from the same computations applied to the $(k-2)$-th derivatives. Let $x = (x^1, \ldots, x^n)$ be a point in $K$ and denote by $y = (\phi^1(x), \ldots, \phi^n(x))$ its image in $K'$. The chain rule gives
    \begin{align}
        \label{eq: chain rule 2}
        \begin{split}
        \frac{\partial^2(u \circ \phi^{-1})}{\partial y^i \partial y^j}(y) = &\frac{\partial^2 u}{\partial x^a \partial x^b}(\phi^{-1}(y)) \frac{\partial (\phi^{-1})^a}{\partial y^i}(y) \frac{\partial (\phi^{-1})^b}{\partial y^j}(y)
        \\
        & + \frac{\partial u}{\partial x^a}(\phi^{-1}(y)) 
        \frac{\partial^2(\phi^{-1})^a}{\partial y^i \partial y^j}(y) \,,
        \end{split}
    \end{align}
    where $(\phi^{-1})^a\doteq x^a\circ\phi^{-1}$. Since $q > \tfrac{n}{2}$, $\phi$ is a $C^1$-diffeomorphism and by \cite[Theorem 3.41]{AdamsFournierBook} one has 
    \begin{equation}
        \label{cond: Lp du}
        \frac{\partial^2 u}{\partial x^a \partial x^b} \circ \phi^{-1} \in L^p(K') \qquad \text{and} \qquad \frac{\partial u}{\partial x^a} \circ \phi^{-1} \in W^{1,p}(K') \,,
    \end{equation}
    with estimates
    \begin{align*}
        \Big\Vert \frac{\partial^2 u}{\partial x^a \partial x^b} \circ \phi^{-1}\Big\Vert_{L^p(K')}&\leq  \Vert \phi\Vert^{\frac{1}{p}}_{C^1(K)}\Big\Vert \frac{\partial^2 u}{\partial x^a \partial x^b} \Big\Vert_{L^p(K)} \,,
        \\
        \Big\Vert \frac{\partial u}{\partial x^a } \circ \phi^{-1}\Big\Vert_{W^{1,p}(K')}&\leq  C\bigl(n,p,K,K',\Vert \phi\Vert_{C^1(K)},\Vert \phi^{-1}\Vert_{C^1(K')}\bigr)\:\Big\Vert \frac{\partial u}{\partial x^a} \Big\Vert_{W^{1,p}(K)} \,.
    \end{align*}
    In view of \eqref{eq: chain rule 2}, since by \cref{LemmaInvFunctThmSobReg} we know that $\phi^{-1}\in W^{3,q}(K')$, we conclude that $u \circ \phi^{-1} \in W^{2,p}(K')$ provided that the Sobolev multiplications
    \begin{align}
        \label{ChangeCoordMult1}
        \begin{split}
        L^p(K') \otimes W^{2,q}(K') \otimes W^{2,q}(K') \hookrightarrow L^p(K') \,, 
        \\
        \quad W^{1,p}(K') \otimes W^{1,q}(K') \hookrightarrow L^p(K')
        \end{split}
    \end{align}
    hold. Appealing to Theorem \ref{SobolevMultLocal}, the first of these embeddings is always true for $q > \tfrac{n}{2}$, whereas the second one holds for all $\tfrac{1}{p} > \tfrac{1}{q} - \tfrac{1}{n}$ and hence in particular if $p \leq q$. Therefore we find that $Au = u\circ\phi^{-1}\in W^{2,p}(K')$ with an estimate of the form
    \begin{align}
        \label{ChangeCoordEstimate2}
        \Vert Au\Vert_{W^{2,p}(K')}\leq C\bigl(n,p,K,K',\Vert \phi\Vert_{C^1(K)},\Vert \phi^{-1}\Vert_{C^1(K')}\bigr)\:\Vert u\Vert_{W^{2,p}(K)},
    \end{align}
    and thus for $l = k = 2$, we are done. Let us now proceed with the case $l = k +1 = 3$, for which we compute 
    \begin{align}
        \label{eq: chain rule 3}
        \frac{\partial^3(u \circ \phi^{-1})}{\partial y^i \partial y^j \partial y^k} (y) &= \frac{\partial^3 u}{\partial x^a \partial x^b \partial x^c}(\phi^{-1}(y)) \, \frac{\partial (\phi^{-1})^a}{\partial y^i}(y) \frac{\partial (\phi^{-1})^b}{\partial y^j}(y)  \frac{\partial (\phi^{-1})^c}{\partial y^k}(y) \nonumber
        \\
        &\quad + 3\frac{\partial^2 u}{\partial x^a \partial x^b}(\phi^{-1}(y)) 
        \frac{\partial^2 (\phi^{-1})^a}{\partial y^i \partial y^j}(y) \frac{\partial (\phi^{-1})^b}{\partial y^k}(y) 
        \\
        \nonumber
        &\quad + \frac{\partial u}{\partial x^a}(\phi^{-1}(y)) 
        \frac{\partial^3(\phi^{-1})^a}{\partial y^i \partial y^j \partial y^k}(y) \,.
    \end{align}
    As a consequence of the case $l = k = 2$ case, we now know that $\phi : K \to K'$ preserves $W^{2,p}$-regularity. In combination with the hypothesis $u \in W^{3, p}(K)$, we can upgrade the conditions \eqref{cond: Lp du} to
    \begin{align*}
        \frac{\partial^3 u}{\partial x^a \partial x^b \partial x^b} \circ \phi^{-1} \in L^p(K')\,, \quad \frac{\partial^2 u}{\partial x^a \partial x^b} \circ \phi^{-1} \in W^{1,p}(K')\,, \quad \frac{\partial u}{\partial x^a} \circ \phi^{-1} \in W^{2,p}(K') \,.
    \end{align*}

    \noindent
    Again, we conclude that $Au = u \circ \phi^{-1} \in W^{3,p}(K')$ provided that the following Sobolev 

    \noindent
    multiplications hold
    \begin{align*}
        &L^p(K') \otimes W^{2,q}(K') \otimes W^{2,q}(K')\otimes W^{2,q}(K') \hookrightarrow L^p(K'), 
        \\
        & W^{1,p}(K') \otimes W^{1,q}(K')\otimes W^{2,q}(K') \hookrightarrow L^p(K'), 
        \\
        & W^{2,p}(K') \otimes L^{q}(K') \hookrightarrow L^p(K').
    \end{align*}
    The first one holds by the same arguments as those granting the first embedding in \eqref{ChangeCoordMult1}. The second one also follows by the same arguments as the second one in \eqref{ChangeCoordMult1} since $W^{1,q}(K')\otimes W^{2,q}(K') \hookrightarrow W^{1,q}(K')$. Finally, the last one follows again by \cref{SobolevMultLocal} as long as $p\leq q$. Moreover, going back to \eqref{eq: chain rule 3}, using \eqref{ChangeCoordEstimate2} and the continuity of the above multiplication properties, we also obtain the estimate
    \begin{align}
        \label{ChangeCoordEstimate3}
        \Vert Au\Vert_{W^{3,p}(K')}\leq C\bigl(n,p,K,K',\Vert \phi\Vert_{C^1(K)},\Vert \phi^{-1}\Vert_{W^{3,q}(K')}\bigr)\Vert u\Vert_{W^{3,p}(K)} \,.
    \end{align}
    Since $K$ (and thus $K'$) was arbitrary, we conclude in any case that $Au \in W^{l,p}_{loc}(\Omega')$. Additionally, we may interchange the roles of $\phi$ and $\phi^{-1}$ to obtain the second estimate in \eqref{ChangeOfCoordsMapSob.2}.
\end{proof}
A similar statement to \cref{lemma: Adams diffeo lemma} holds true for tensor fields. The key difference is that coordinate transformations of tensors involve the Jacobian of the coordinate change, and therefore, one level less of regularity is preserved. We denote by $T_s\Omega$ the bundle of $s$-covariant tensor fields over $\Omega$ and by $W^{l,p}(T_s\Omega)$ the sections of $T_s\Omega$ with coefficients in $W^{l,p}(\Omega,\nR^s)$.
\begin{lemma}
    \label{prop: tensor_regularity}
    Fix $k \geq 2$, $q > \tfrac{n}{2}$ and let $\phi : \Omega \to \Omega'$ be a $W^{k+1,q}$-diffeomorphism between two bounded smooth domains in $\nR^n$.
    If $u \in W^{l,p}(T_s\Omega)$, then $Au \doteq \phi_*u \in W^{l,p}_{loc}(T_s\Omega')$ provided that $l \leq k$ and $p \leq q$. Moreover, 
    \begin{align}
        A:W_{loc}^{l,p}(T_s\Omega)&\to W_{loc}^{l,p}(T_s\Omega')
    \end{align}    
    is bounded with bounded inverse, meaning that, given any smooth domain $K \subset\subset \Omega$, there exists a constant $C =C(n,p,q,l,K,\phi)$ such that
    \begin{align*}
        \Vert Au \Vert_{W^{l,p}(\phi(K))}&\leq C\Vert u \Vert_{W^{l,p}(K)} \,,
        \\
        \Vert A^{-1}v \Vert_{W^{l,p}(K)}&\leq C\Vert v \Vert_{W^{l,p}(K')}
    \end{align*}
    hold for all $u \in W^{l,p}_{loc}(T_s\Omega)$ and $v \in W^{l,p}_{loc}(T_s\Omega')$.
\end{lemma}
\begin{proof}
    Due to the prevalence of 2-tensors throughout the paper, we carry out the proof for $s =2$, but other cases are completely analogous. For each point $x = (x^1, \ldots, x^n)$ in $K$, the tensor field $u$ may be expressed by
    \begin{align*}
        u_x = u_{ij}(x) \, dx^i \otimes dx^j \qquad \text{with} \qquad u_{ij}(x)=u_x\bigl(\partial_{x^i},\partial_{x^j}\bigr) \,.
    \end{align*}
    Letting $y = (\phi^1(x), \ldots, \phi^n(x)) \in K'$, where $K' \doteq \phi(K)$, standard transformation rules read
    \begin{align*}
        (Au)_y(\partial_{y^a},\partial_{y^b}) & = u_{\phi^{-1}(y)}\left(d(\phi^{-1})_y(\partial_{y^a}), d(\phi^{-1})_y(\partial_{y^b})\right) \\
        & = \partial_{y^a}(\phi^{-1})^i \partial_{y^b} (\phi^{-1})^j u_{\phi^{-1}(y)}\left(\partial_{x^i}|_{\phi^{-1}(y)}, \partial_{x^j}|_{\phi^{-1}(y)}\right) \\
        & = \partial_{y^a}(\phi^{-1})^i \partial_{y^b} (\phi^{-1})^j (u_{ij}  \circ \phi^{-1}(y)).
    \end{align*}
    Since $u \in W^{l,p}(T_2\Omega)$ implies that $u_{ij} \in W^{l,p}(K)$, then it follows from \cref{lemma: Adams diffeo lemma} that
    \begin{align*}
        (u_{ij}  \circ \phi^{-1}) \in W^{l,p}(K')
    \end{align*}
    provided that $l \leq k+1$ and $p \leq q$, which holds true by hypothesis. Since we also know that $\phi^{-1}\in W^{k+1,q}(K')$ by \cref{LemmaInvFunctThmSobReg}, then the Sobolev multiplication properties of \cref{SobolevMultLocal} imply
    \begin{align*}
        W^{k,q}(K') \otimes W^{k, q}(K') \otimes W^{l,p}(K') \hookrightarrow W^{l,p}(K')
    \end{align*}
    under our hypotheses. Thus $(Au)_{ab} \in W^{l,p}(K')$ and therefore $Au \in W^{l,p}(T_sK')$ together with an estimate
    \begin{align*}
        \Vert Au \Vert_{W^{l,p}(K')}&\leq C\Vert u \Vert_{W^{l,p}(K)} \,,
    \end{align*}
    where $C=C(n,p,q,l,K,\phi)$ is provided by the above multiplication constants and the estimates of \cref{lemma: Adams diffeo lemma}. Since $K$ (and thus $K'$) was arbitrary, we conclude that $Au \in W^{l,p}_{loc}(T_s\Omega')$ and by interchanging the role of $\phi$ and $\phi^{-1}$ we obtain the second estimate of the Lemma.
\end{proof}
There are many distinct but equivalent ways of defining Sobolev spaces on smooth, closed manifolds. One common approach --see e.g. \cite{HebeyBook}-- is to use a smooth background Riemannian metric $g$, which induces a smooth measure $\mu_{g}$ and a covariant derivative $\nabla$, which in turn can be used to define Sobolev norms
\begin{equation}
    \label{eq: SobolevNorm backgroundmetric}
    \|u\|_{W^{k,p}(M,d\mu_{g})} = \sum_{i=0}^k\left(\int_M|\nabla^iu|^p \, d\mu_g\right)^{\frac{1}{p}} \,.
\end{equation}
In this work, however, it will be convenient to adopt a \textit{local} approach. We denote by $\Gamma(T_sM)$ the space of measurable sections of the tensor bundle $T_sM$.
\begin{definition}
    \label{SobSpacesManifoldDefnTensors.1}
    Let $M$ be a smooth, closed manifold and $s\in \mathbb{N}_0$. For $k \in \mathbb{N}_0$ and $1\leq p< \infty$, we define the Sobolev spaces
    \begin{align*}
        W^{k,p}(T_sM) \doteq \bigl\{u \in \Gamma(T_sM) \; : \; \varphi_* u \in W^{k,p}_{loc}\bigl(T_s(\varphi(U)\bigr) \; \text{for all charts} \; (U, \varphi)\bigr\} \,.
    \end{align*}
    Given a finite atlas $\mathcal A = \{(U_\alpha, \varphi_\alpha)\}_{\alpha=1}^N$ and a subordinate partition of unity $\{\eta_\alpha\}_{\alpha=1}^N$, we consider the norms\footnote{The Sobolev norm of a tensor field $T = T_{i_1, \ldots, i_s}(x) dx^{i_1} \otimes \ldots \otimes dx^{i_s}$ in Euclidean space is just $\|T\|_{W^{k,p}} = \sum_{i_1=1}^n \cdots \sum_{i_s=1}^n  \|T_{i_1 \ldots i_s}\|_{W^{k,p}}$.}
    \begin{align}
        \label{SobolevNormTensorFields}
        \|u\|_{W^{k,p}(M,\mathcal A)} \doteq \sum_{\alpha=1}^N \|(\varphi_\alpha)_*(\eta_\alpha u)\|_{W^{k,p}(\varphi_\alpha(U_\alpha))} \,,
    \end{align}
    which make the above space Banach.
\end{definition}
\begin{remark}
    Notice that by Lemma \ref{prop: tensor_regularity} applied to the case of smooth diffeomorphisms, distinct choices of atlases and subordinate partitions of unity yield equivalent norms for (\ref{SobolevNormTensorFields}). In fact, we will not make reference to the chosen atlas and simply denote the norms by $\|\cdot\|_{W^{k,p}(M)}$. One can check, for instance, from the proof of the second half of \cite[Theorem 2.20]{AubinBook}, that the norms \eqref{eq: SobolevNorm backgroundmetric} and \eqref{SobolevNormTensorFields} are equivalent. 
\end{remark}
Using that the map
\begin{align*}
    W^{l,p}(M)&\to W^{l,p}(\varphi_{1}(U_{1}))\times \cdots\times W^{l,p}(\varphi_{N}(U_{N})),
    \\
    u&\mapsto \left((\varphi_1)_{*}(\eta_1 u),\cdots,(\varphi_N)_{*}(\eta_N u))\right) \,.
\end{align*}
is an isometric isomorphism, it is immediate to see that the usual properties of local Sobolev spaces (such as embeddings, density theorems or multiplication properties) transfer to the global ones. We will also need to work with Sobolev spaces of \textit{negative} regularity, which locally are defined simply by duality
\begin{align}
    \label{NegativeSobolevLocal}
    W^{-k,p'}(\Omega) \doteq \bigl(W_0^{k,p}(\Omega)\bigr)'.
\end{align}
Properties of these spaces can be found, for instance, in \cite[Chapter 3]{AdamsFournierBook}. Given a smooth closed manifold $M$, one can extend this local definition to that of $W^{-k,p'}(M)$, similarly to the case of $W^{k,p}(M)$ with $k\in \mathbb{N}$.  
To accurately introduce the associated definitions, let us denote by $\mathscr{D}(M)$ the space of test functions on $M$, which is $C^{\infty}(M)$ equipped with the usual inductive limit topology. Since $M$ is compact, this space is Fréchet. Then, the space of distributions $\mathscr{D}'(M)$ on $M $ is defined 
as the topological dual to $\mathscr{D}(M)$. In order to have a local characterization of elements in $\mathscr{D}'(M)$, consider a local chart $(U_{\alpha},\varphi_{\alpha})$ in $M$ and notice that by, for instance, 
\cite[Theorem 46]{HolstBehzadanSobSpaces} the map
\begin{align}
    \label{CoordRepD}
    \begin{split}
    T_{\alpha}:\mathscr{D}(U)&\to \mathscr{D}(\varphi_{\alpha}(U)),
    \\
    v&\mapsto v\circ\varphi_{\alpha}^{-1} 
    \end{split}
\end{align} 
is a topological isomorphism. 
The dual map $T_{\alpha}^{*}:\mathscr{D}'(\varphi_{\alpha}(U_{\alpha}))\to \mathscr{D}'(U_{\alpha})$ then reads 
\begin{align*}
    (T^{*}_{\alpha}u)(v)=u(T_{\alpha}v)=u(v\circ\varphi_{\alpha}^{-1}) \,, 
\end{align*} 
for $u\in \mathscr{D}'(\varphi_{\alpha}(U_{\alpha}))$ and $v\in \mathscr{D}(U_{\alpha})$ is again a linear topological isomorphism. We denote $\hat{T}_{\alpha}\doteq (T_{\alpha}^{*})^{-1}$ and notice that this map assigns to each distribution on $U_{\alpha}\subset M$ a distribution on $\varphi_{\alpha}(U_{\alpha})\subset\mathbb{R}^n$. Then, given $u\in \mathscr{D}'(U_{\alpha})$ one regards $\hat{T}_{\alpha}u\in \mathscr{D}'(\varphi_{\alpha}(U_{\alpha}))$ as its \emph{local} coordinate
representation, in the same way that  
$T_{\alpha}v$ 
is the local coordinate representation of $v$ in (\ref{CoordRepD}). Observe that whenever $M$ is equipped with a continuous Riemannian metric $g$ and $u \in L^1(M,d\mu_g)$ is regarded as a regular distribution, then $\hat{T}_{\alpha}u = u \circ \varphi_\alpha^{-1}$: letting $v\in \mathscr{D}(\varphi_{\alpha}(U_{\alpha}))$ and denoting by $\{x^i\}_{i=1}^n$ the associated coordinates, we have
\begin{align}
    \label{RegDistribM}
    \begin{split}
        (\hat{T}_{\alpha}u)(v)&=u(T_{\alpha}^{-1}v)=\int_{M}u(v\circ\varphi_{\alpha}) d\mu_g = \int_{\varphi_{\alpha}(U_{\alpha})}(u\circ\varphi_{\alpha}^{-1})(x)v(x)d\mu_g(x)
        \\
        &=(u\circ\varphi_{\alpha}^{-1})(v),
    \end{split}
\end{align}
where each identity in the first line follows by definition, and the meaning of the second line is the usual action of $u\circ\varphi_{\alpha}^{-1}\in L^1_{loc}(\varphi_{\alpha}(U_{\alpha}))$ as an element of $\mathscr{D}'(\varphi_{\alpha}(U_{\alpha}))$ on $v\in \mathscr{D}(\varphi_{\alpha}(U_{\alpha}))$. The above construction extends this to the general case of elements of $\mathscr{D}'(M)$ and allows for the following definition.
\begin{definition}
    \label{def: NegativeSobolevGLobal}
    Let $M$ be a smooth, closed manifold. For $k\in \nN$ and $1<p<\infty$ we define 
    \begin{align*}
        W^{-k,p'}(M) \doteq \bigl\{ u \in \mathscr D'(M) \; : \; \hat{T}_{\alpha}u \in W^{-k,p}(\varphi_{\alpha}(U_{\alpha})) \; \text{for all charts} \; (U_{\alpha}, \varphi_{\alpha})\bigr\} \,.
    \end{align*}
    Given a finite atlas $\mathcal{A}=\{(U_{\alpha},\varphi_{\alpha})\}_{\alpha=1}^N$ and a subordinate partition of unity $\{\eta_{\alpha}\}_{\alpha}^N$, we consider the norms
    \begin{align*}
        \|u\|_{W^{-k,p}(M,\mathcal A)} \doteq \sum_{\alpha=1}^N \|\hat{T}_{\alpha}(\eta_\alpha u)\|_{W^{-k,p'}(\varphi_\alpha(U_\alpha))} \,,
    \end{align*}
    which make the above space Banach.
\end{definition}
It is easy to see by the local duality properties and \cite[Theorem 3.41]{AdamsFournierBook} for smooth diffeomorphisms that distinct choices of atlas or partition of unity yield equivalent norms (an explicit proof of the local statement can be found in \cite[Theorem 75]{HolstBehzadanSobSpaces}). By the local nature of \cref{def: NegativeSobolevGLobal}, these spaces are easily seen to satisfy most of the properties of their local counterparts $W^{-k,p'}(\Omega)$; in particular, they are reflexive and smooth functions are dense. This allows to relate $W^{-k,p'}(M)$ and $(W^{k,p}(M))'$:
\begin{theorem}
    \label{SobolevDualIso}
    Let $M$ be a smooth, closed manifold and fix $k\in \mathbb{N}$ and $1<p<\infty$. Given a continuous Riemannian metric $g$ on $M$, the bilinear form
    \begin{align*}
        C^{\infty}(M) \times C^{\infty}(M) \to \nR \,, \qquad (u,v) \mapsto \langle u,v\rangle_{L^2(M,d\mu_g)}
    \end{align*}
    extends uniquely by continuity to a continuous bilinear form
    \begin{align}
        \label{SobPairing.2}
        W^{-k,p'}(M) \times W^{k,p}(M) \to \mathbb{R} \,, \qquad (u,v) \mapsto \langle u,v\rangle_{(M,g)} \,.
    \end{align}
    Moreover, the $S_{k,p}:W^{-k,p'}(M)\to (W^{k,p}(M))'$ mapping defined by $(S_{k,p}u)(v)=\langle u,v\rangle_{(M,g)}$ for all $v\in W^{k,p}(M)$ is a linear topological isomorphism.
\end{theorem}
\begin{proof}
    The first assertion follows directly from the straightforward inequality
    \begin{align*}
        |\langle u,v\rangle_{L^2(M,d\mu_g)}|\leq C(M,g)\Vert u\Vert_{W^{-k,p'}(M)}\Vert v\Vert_{W^{k,p}(M)} \,,
    \end{align*}
    so let us show the isomorphism. First, notice that the map $S_{k,p}$ is linear and well-defined and that for any continuous Riemannian metric $g$ one has $L^{p'}(M,d\mu_g) \cong (L^p(M,d\mu_g))'$. One may then parallel the discussion of \cite[Chapter 3, Section 3.13]{AdamsFournierBook} closely observing that, for each $u\in L^{p'}(M,d\mu_g)$, the functionals $L_u:W^{k,p}(M)\to \mathbb{R}$ given by $L_u(v)\doteq \langle u,v\rangle_{L^2(M,d\mu_g)}$, define elements in $(W^{k,p}(M))'$ and, moreover, that the set $\{L_u \: :\: u\in L^{p'}(M,d\mu_g)\} \subset (W^{k,p}(M))'$ is dense. Since $C^{\infty}(M)$ is dense in $L^{p'}(M,d\mu_g)$ as well, we see that for any $u\in (W^{k,p}(M))'$ there is a sequence $\{u_j\}_{j=1}^{\infty}\subset C^{\infty}(M)$ such that
    \begin{align}
        \label{DualPairing.1}
        u(v)=\lim_{j\to \infty}\langle u_j,v\rangle_{L^2(M,d\mu_g)}
    \end{align}
    for all $v \in W^{k,p}(M)$. In other words, $\Vert u-L_{u_j}\Vert_{(W^{k,p}(M))'} \to 0$ as $j\to\infty$, where each $L_{u_j}\in W^{-k,p'}(M)$ by (\ref{RegDistribM}). On the other hand, simply using the definition of the global norms,
    \begin{align*}
        \Vert L_{u_j}-L_{u_k}\Vert_{W^{-k,p'}(M)}&=\sum_{\alpha}\Vert \hat{T}_{\alpha}(\eta_{\alpha}(L_{u_j}-L_{u_k}))\Vert_{W^{-k,p'}(\varphi_{\alpha}(U_{\alpha}))} \,,
    \end{align*}
    and noticing that since $\eta_{\alpha}(L_{u_j}-L_{u_k})\in L^{p'}(M,d\mu_g)$ are regular distributions, we have
    \begin{align*}
        \Vert \hat{T}_{\alpha}(\eta_{\alpha}(L_{u_j}&-L_{u_k}))\Vert_{W^{-k,p'}(\varphi_{\alpha}(U_{\alpha}))}
        \\
        &=\sup_{v\in W_0^{k,p}(\varphi_{\alpha}(U_{\alpha}))}\frac{|\langle (\eta_{\alpha}(u_j-u_k)\circ\varphi^{-1}_{\alpha}),v\rangle_{L^2(\varphi_{\alpha}(U_{\alpha}),d\mu_g)}|}{\Vert v\Vert_{W^{k,p}(\varphi_{\alpha}(U_{\alpha}))}}
        \\
        &\leq C_{\alpha}\sup_{v\in W_0^{k,p}(\varphi_{\alpha}(U_{\alpha}))}\frac{|\langle u_j-u_k,v\circ\varphi_{\alpha})\rangle_{L^2(U_{\alpha},d\mu_g)}|}{\Vert v\circ\varphi_{\alpha}\Vert_{W^{k,p}(U_{\alpha})}}
        \\
        &\leq C_{\alpha}\sup_{v\in W^{k,p}(M)}\frac{|\langle u_j-u_k,v\rangle_{L^2(M,d\mu_g)}|}{\Vert v\Vert_{W^{k,p}(M)}} = C_\alpha\Vert L_{u_j} - L_{u_k}\Vert_{(W^{k,p}(M))'} \to 0 
    \end{align*}
    as $j,k\to\infty$, where the second inequality follows from $\varphi^{*}(W_0^{k,p}(\varphi_{\alpha}(U_{\alpha})))\subset W^{k,p}(M)$ and the last limit holds as by hypothesis $\{L_{u_j}\}_{j=1}^{\infty}$ is a Cauchy sequence in $(W^{k,p}(M))'$. This implies $\{L_{u_j}\}_{j=1}^{\infty}$ is a Cauchy sequence in $W^{-k,p'}(M)$ as well and, by completeness, there is some $\hat{u}\in W^{-k,p'}(M)$ such that $L_{u_j}\to\hat{u}$ in $W^{-k,p'}(M)$. But then, by the definition of the bilinear form \eqref{SobPairing.2} we have that
    \begin{align*}
        u(v)=\lim_{j\to \infty}\langle u_j,v\rangle_{L^2(M,dV_g)}=\langle \hat{u},v\rangle_{(M,g)}
    \end{align*}
    for all $v\in W^{k,p}(M)$. Therefore, $S_{k,p}$ is surjective. 

    Concerning injectivity, assume that $(S_{k,p}\hat{u})(v)=0$ for all $v\in W^{k,p}(M)$. In particular,
    \begin{align*}
        0 = \langle \hat{u},v\rangle_{(M,g)}=\lim_{j\to\infty}L_{u_j}(v) \,,
    \end{align*}
    where $L_{u_j}\to \hat{u}$ in $W^{-k,p'}(M)$. We claim that the action of $\hat{u}$ on $\mathscr{D}(M)$ can be computed in terms of $\langle \hat{u},v\rangle_{(M,g)}$ restricted to $v\in \mathscr{D}(M)$. For this, letting $(U_{\alpha},\varphi_{\alpha})$ be an arbitrary chart, we see that
    \begin{align*}
        L_{u_j}(v)\to \hat{u}(v) \: \forall\: v\in \mathscr{D}(M) &\Longleftrightarrow L_{u_j}(v)\to \hat{u}(v) \: \forall\: v\in \mathscr{D}(U_{\alpha}) \; \forall \, U_\alpha
        \\
        &\Longleftrightarrow (\hat{T}_{\alpha}L_{u_j})(T_{\alpha}v)\to (\hat{T}_{\alpha}\hat{u})(T_{\alpha}v) \: \forall\: v\in \mathscr{D}(U_{\alpha}) \; \forall \, U_\alpha
        \\
        &\Longleftrightarrow (\hat{T}_{\alpha}L_{u_j})(\tilde{v})\to (\hat{T}_{\alpha}\hat{u})(\tilde{v}) \: \forall\: \tilde{v}\in \mathscr{D}(\varphi_{\alpha}(U_{\alpha})) \; \forall \, U_\alpha
    \end{align*}
    where we have used that $T_\alpha$ and $\hat T_\alpha$ are topological isomorphisms. But then, since $\hat{T}_{\alpha}L_{u_j}\to\hat{T}_{\alpha}\hat{u}$ in $W^{-k,p'}(\varphi_{\alpha}(U_{\alpha}))$ and $W^{-k,p'}(\varphi_{\alpha}(U_{\alpha}))\hookrightarrow \mathscr{D}'(\varphi_{\alpha}(U_{\alpha}))$,\footnote{Since $\varphi_{\alpha}(U_{\alpha})$ is a domain in $\mathbb{R}^n$, then $\mathscr{D}(\varphi_{\alpha}(U_{\alpha}))\overset{\iota}{\hookrightarrow} W_{0}^{k,p}(\varphi_{\alpha}(U_{\alpha}))$ and thus $W^{-k,p'}(\varphi_{\alpha}(U_{\alpha}))\overset{\iota^{*}}{\hookrightarrow} \mathscr{D}'(\varphi_{\alpha}(U_{\alpha}))$.} we have that $\hat{T}_{\alpha}L_{u_j}\to\hat{T}_{\alpha}\hat{u}$ in $\mathscr{D}'(\varphi_{\alpha}(U_{\alpha}))$ as well, implying that indeed 
    \begin{align*}
        (\hat{T}_{\alpha}L_{u_j})(\tilde{v})\to (\hat{T}_{\alpha}\hat{u})(\tilde{v})
    \end{align*}
    for all $\tilde{v}\in \mathscr{D}(\varphi_{\alpha}(U_{\alpha}))$. Therefore, we conclude that $L_{u_j}(v)\to \hat{u}(v)$ and consequently
    \begin{align*}
        \langle \hat{u},v\rangle_{(M,g)}=\hat{u}(v)
    \end{align*}
    holds for all $v\in \mathscr{D}(M)$, showing that $\hat{u}=0$ as an element of $\mathscr{D}'(M)$. This establishes injectivity. We have therefore shown that $S_{k,p}$ is a bounded isomorphism between Banach spaces and thus it is topological isomorphism since the inverse must then be bounded by the open mapping theorem.
\end{proof}
Let us finally briefly discuss \emph{interpolating Sobolev spaces}, which will be useful on a few occasions, although
in this paper we will work mostly with Sobolev spaces with integer degree of regularity.
A family of Banach spaces interpolating between two selected Banach spaces can be obtained via \emph{complex interpolation theory} --for a detailed description 
we refer the reader to \cite{Calderon1,Triebel1}, despite most of the properties we shall use being contained more concisely in \cite[Chapter 4, Section 2]{Taylor1}--. 
In particular, following \cite[Chapter VII, Section 7.66]{Adams1st}, given a smooth bounded domain $\Omega \subset \nR^n$, $1<p<\infty$, $\theta\in (0,1)$ and $k\in \mathbb{N}_0$, we define
\begin{align}
    \label{BesselPotentials.3}
    H^{s,p}(\Omega)\doteq [L^p(\Omega),W^{k,p}(\Omega)]_{\theta}, \text{ for } s=\theta k,
\end{align}
denoting the family of spaces interpolating between $L^p(\Omega)$ and $W^{k,p}(\Omega)$, parametrized by $\theta\in (0,1)$.
We then denote by $H^{s,p}_0(\Omega)$ the closure of $C^{\infty}_0(\Omega)$ in $H^{s,p}(\Omega)$, and for $1<p<\infty$ and $s<0$ a real number,
\begin{align}
    \label{BesselPotentials.4}
    H^{s,p'}(\Omega)\doteq [H_0^{-s,p}(\Omega)]'.
\end{align}
If $\Omega$ is substituted by $\nR^n$, these spaces coincide with the usual \emph{Bessel potentials} defined via the Fourier transform --see \cite[Proposition 6.2]{Taylor3}--.

