\subsection{Weighted Sobolev spaces and AE manifolds}
\label{AESection}
The classical strategy to solve the Yamabe problem on closed manifolds in low dimensions relies on a tight relation with the positive mass theorem of general relativity. We then review some standard terminology and results associated with asymptotically Euclidean manifolds. Following the conventions in \cite{Bartnik86}, we use the norms 
\begin{align}\label{WeightedSobolevNormsDefs}
\begin{split}
    \|u\|_{W^{k,p}_{\delta}(\mathbb{R}^n)} &\doteq \sum_{|\beta|\leq k} \|\sigma^{-\delta-\frac{n}{p}+|\beta|}\partial^{\beta}u\|_{L^p(\nR^n)}
    \\
    \|u\|_{C^{k,\alpha}_{\delta}(\nR^n)} &\doteq \sum_{|\beta|<k}\|\sigma^{-\delta+|\beta|}\partial^\beta u\|_{C^0(\nR^n)} + \sup_{|\beta|=k} \|\sigma^{-\delta+k+\alpha}\partial^\beta u\|_{C^{0,\alpha}(\nR^n)}
\end{split}
\end{align}
with weight $\sigma(x)\doteq (1+|x|^2)^{\frac{1}{2}}$ in Euclidean space. Most properties of the associated weighted Sobolev spaces can be found in \cite{Bartnik86,NirenbergWalker,McOwen,Lockhart,CB-C}.
\begin{definition}
    \label{WeightedSobSpacesManifold}
    Let $M$ be a smooth $n$-manifold and $\Phi$ a Euclidean structure at infinity, that is, a smooth diffeomorphism
    \begin{equation*}
        \Phi : M \setminus K \to \nR^n \setminus \overline{B_R}
    \end{equation*}
    for some compact set $K \subset M$ and radius $R > 0$. For each $s \in \nN_0$, $k \in \nN_0$, $1\leq p< \infty$ and $\delta \in \nR$, we define the weighted Sobolev spaces 
    \begin{equation*}
        W^{k,p}_{\delta}(T_sM,\Phi) \doteq \Bigl\{u \in W^{k,p}_{loc}(T_sM) \;:\; \|\Phi_*u\|_{W^{k,p}_{\delta}(\nR^n\setminus\overline{B_R})} < \infty\Bigr\} \,.
    \end{equation*}
    Given a finite coordinate cover $\mathcal A = \{(U_\alpha,\varphi_\alpha)\}_{\alpha=1}^{N-1}$ of $K$ and a partition of unity $\{\eta_\alpha\}_{\alpha=1}^{N}$ subordinate to $\mathcal A \cup (M \setminus K,\Phi)$, we consider the norms
    \begin{equation*}
        \|u\|_{W^{k,p}_\delta(T_sM,\Phi)} = \sum_{\alpha=1}^{N-1} \|(\varphi_\alpha)_*(\eta_\alpha u)\|_{W^{k,p}(\varphi_\alpha(U_\alpha))} + \|\Phi_*(\eta_{N} u)\|_{W^{k,p}_\delta(\nR^n \setminus \overline{B_R})}
    \end{equation*}
    which make the above spaces Banach. We will omit, if no confusion arises, the reference to the structure at infinity $\Phi$.
\end{definition}
Analogously, one can define weighted Hölder spaces on manifolds admitting a Euclidean structure at infinity. For the convenience of the reader, we summarize here the properties of these weighted spaces most relevant for us:
\begin{lemma}
    \label{AEWeightedEmbeedings}
    Let $M$ and $\Phi$ be as in \cref{WeightedSobSpacesManifold} and fix $s \in \nN_0$, $k,l \in \nN_0$, $1 \leq p,q < \infty$ and $\delta \in \nR$. Then, the following continuous embeddings hold:
    \begin{enumerate}
        \item[(i)] If $1< p\leq q<\infty $ and $\delta_2<\delta_1$, then $L^{q}_{\delta_2}(T_sM) \hookrightarrow L^p_{\delta_1}$.
        \item[(ii)] If $kp<n$, then $W^{k,p}_{\delta}(T_sM) \hookrightarrow L^{q}_{\delta}(T_sM)$ for all $p\leq q\leq \frac{np}{n-kp}$.
        \item[(iii)] If $kp=n$, then $W^{k,p}_{\delta}(T_sM) \hookrightarrow L^q_{\delta}(T_sM)$ for all $p\leq q<\infty$.
        \item[(iv)] If $kp>n$, then $W^{k+l,p}_{\delta}(T_sM) \hookrightarrow C^l_{\delta}(T_sM)$.
        \item[(v)] If $1<p\leq q<\infty $ and $k_1+k_2>\frac{n}{q}+k$ where $k_1,k_2\geq k$ are non-negative integers, then, we have a continuous multiplication property $W^{k_1,p}_{\delta_1}(T_sM)\otimes W^{k_2,q}_{\delta_2}(T_sM) \hookrightarrow W^{k,p}_{\delta}(T_sM)$ for any $\delta>\delta_1+\delta_2$. In particular, $W^{k,p}_{\delta}$ is an algebra under multiplication for $k>\frac{n}{p}$ and $\delta<0$.
    \end{enumerate}
\end{lemma} 
 Using the above notion of weighted Sobolev spaces, we now introduce 
 AE manifolds, namely, non-compact manifolds endowed with a metric decaying  
to the Euclidean one along an end.
\begin{definition}
    \label{AE-Manifolds}
	Let $(M,g)$ be a Riemannian $n$-manifold and $\Phi$ a Euclidean structure at infinity. Then, $(M,g)$ is called $W^{k,p}_{\delta}$-asymptotically Euclidean with respect to $\Phi$ if
    \begin{enumerate}
        \item[(i)] $g \in W^{k,p}_{loc}(T_2M)$ for some $k>\frac{n}{p}$,
        \item[(ii)] $g-\Phi^{*}g_{\nR^n}\in W^{k,p}_{\delta}(T_2M)$ for some $\delta<0$.
    \end{enumerate}
\end{definition}
AE manifolds arise as models for isolated gravitational systems and have been intensively studied in the last decades. Conservation principles give rise to associated geometric invariants, such as the so called ADM energy, which captures the total energy of the system. For our discussion, we restrict ourselves to 3 dimensions:
\begin{definition}
    Let $(M,g)$ be a $C^{1}_{-\tau}$-AE 3-manifold with respect to a structure at infinity $\Phi_x$ with asymptotic coordinates $\{x^i\}_{i=1}^3$ for some $\tau>0$. Then, its ADM energy is defined by
    \begin{align}
        \label{ADMEnergy}
        E_{ADM}(g)\doteq \frac{1}{16\pi}\lim_{r\to\infty}\int_{S_r}\left( \partial_{i}g_{ij}-\partial_{j}g_{ii} \right)\frac{x^i}{|x|}d\omega_r,
    \end{align}
    whenever the limit exists, and where $S_r$ denotes a topological sphere of radius $r$ contained in the end of $M^3$ and $d\omega_r$ its induced Euclidean volume form.
\end{definition}
The above definition has been presented in a rather broad context due to its use in this paper,
but it leaves open the question of when it is indeed well-defined. It is known since the work of R. Bartnik (\cite[Section 4]{Bartnik86}) that the ADM energy is finite and independent of the asymptotic coordinates or sequence of topological spheres,
provided that $(M,g)$ is $W^{2,q}_{-\tau}$-AE with $\tau > \tfrac{1}{2}$, $q > 3$ and $\R_g \in L^1(M,d\mu_g)$. Its computation becomes particularly simple when the manifold is asymptotic to the spacial Schwarzschild manifold, which will be exploited in the resolution of the Yamabe problem in \cref{The Yamabe Problem}.
\begin{definition}
    Let $(M,g)$ be a $C^k_{-\tau}$-AE 3-manifold with respect to a structure at infinity $\Phi_x$ with coordinates $\{x^i\}_{i=1}^3$ for some $k\in \mathbb{N}_0$ and $\tau>0$. We say that $(M,g)$ is asymptotically Schwarzschildian of order $k$ with respect to $\Phi_x$ if 
    \begin{align}
        \label{ASDefn}
        g_{ij}(x) = \left(1+\frac{4m}{|x|}\right)\delta_{ij} + O_k(|x|^{-1-\varepsilon}),
    \end{align}
    for some constant $m$ and some $\varepsilon>0$. In such case, we say that $g\in AS_{\varepsilon}(k)$.
\end{definition} 
Notice that for any $AS_{\varepsilon}(1)$ metric $g$, direct computations give that $E_{ADM}=m$.



