\subsection{A Yamabe classification}\label{The Yamabe classification}

Let $g \in W^{2,q}(T_2M)$ be a Riemannian metric on a smooth, closed manifold $M$ of dimension $n \geq 3$ with $q > \tfrac{n}{2}$. It is in particular Hölder continuous. Given a positive function $u \in W^{2,q}(M)$, a standard computation shows that the conformal metric $\tilde g \doteq u^{\frac{4}{n-2}} g$ has scalar curvature
\begin{equation}
    \label{eq: ConformalScalar}
    \R_{\tilde g} = u^{-\frac{n+2}{n-2}}\Big(-a_n\Delta_gu + \R_g u\Big) \,, \qquad a_n \doteq 4 \, \frac{n-1}{n-2} \,.
\end{equation}
Notice that $W^{2,q}(M) \otimes W^{2,q} \hookrightarrow W^{2,q}(M)$ by the multiplication properties of \cref{SobolevMultLocal}, implying that $\tilde g \in W^{2,q}(T_2M)$ and consequently $\R_{\tilde g} \in L^q(M)$. In view of \eqref{eq: ConformalScalar}, the metric $\tilde g$ has constant scalar curvature equal to $\lambda$ if and only if $u$ solves the semi-linear elliptic PDE
\begin{equation}
    \label{eq: Yamabe equation 1}
    \Lg u \doteq -a_n \Delta_g u + \R_g u = \lambda \, u^{\frac{n+2}{n-2}} \,,
\end{equation}
which is the Euler--Lagrange equation of
\begin{equation*}
    Q_g(u) \doteq \frac{E_g(u)}{\|u\|_{L^{2^*}(M,d\mu_g)}^2} \,, \qquad E_g(u) \doteq \int_M \bigl(a_n|\nabla u|^2_g + \R_g u^2\bigr) \, d\mu_g \,.
\end{equation*}
Here $2^* \doteq \tfrac{2n}{n-2}$ denotes the optimal Sobolev embedding power of $W^{1,2}(M)$. More generally, one may consider for any $s \in [2, 2^*]$ the Rayleigh quotient
\begin{equation}
    \label{eq: Qs functionals}
    Q_g^s(u) \doteq \frac{E_g(u)}{\|u\|_{L^{s}(M,d\mu_g)}^2}
\end{equation}
with critical points satisfying the Euler--Lagrange equation
\begin{equation}
    \label{eq: sPDE}
    \Lg u = q_s u^{s-1} \,, \qquad q_s \doteq Q_g^s(u) \,.
\end{equation}
It follows from the $W^{1,2}(M) \hookrightarrow L^{2^*}(M)$ embedding that the bilinear functional $A_g : W^{1,2}(M) \times W^{1,2}(M) \to \nR$ defined by
\begin{align}
    \label{YamabeBilinearForm}
    A_g(u, v) \doteq \int_M \Big(a_n \langle\nabla u, \nabla v\rangle_g + \R_g u \, v \Big) \, d\mu_g
\end{align}
is continuous and therefore it is convenient to use $W^{1,2}(M)$ as the space of admissible functions for the variational problem. In the present context, it is worth noticing that since the metric $g$ is continuous, it is easy to check by a standard computation that the $\|\cdot\|_{W^{1,2}(M,d\mu_g)}$ norm defined in \eqref{eq: SobolevNorm backgroundmetric} is equivalent to the one introduced in \cref{SobSpacesManifoldDefnTensors.1} for scalar fields\footnote{For scalar fields $\nabla u$ does not involve Christoffel symbols and, thereby, the norm $\|\cdot\|_{W^{1,2}(M,d\mu_g)}$ is well-defined for $C^0$-Riemannian metrics.}. Below, and whenever necessary, we will make use of this equivalence.
Using multiplication properties on the interpolation Sobolev spaces introduced in Section \ref{SectionSobolevSpaces}, one can show the following:
\begin{proposition}
    \label{lemma: Ru2 interpolation}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ with $q > \tfrac{n}{2}$. Then, the $W^{1,2}(M) \to \nR$ map
    \begin{align*}
        u \mapsto \int_M \R_g u^2 d\mu_g
    \end{align*}
    is weakly continuous and for every $\varepsilon > 0$ there exists a constant $C_\varepsilon > 0$ such that
    \begin{equation}
        \int_M \R_g u^2 \, d\mu_g \leq \|\R_g\|_{L^q(M,d\mu_g)} \Big(\varepsilon \|u\|^2_{W^{1,2}(M,d\mu_g)} + C_\varepsilon \|u\|^2_{L^2(M,d\mu_g)}\Big) \,.
    \end{equation}
    Moreover, for each $s \in [2, 2^*]$ the functional $Q_g^s$ defined in \eqref{eq: Qs functionals} is bounded from below in $W^{1,2}(M)$.
\end{proposition}
\begin{proof}
    See \cite[Lemma 4.2 and Lemma 4.3]{avalos2024sobolev}, where the proof basically follows the ideas of \cite[Lemma 3.1]{Maxwell1}). A similar result also appears in \cite[Proposition 2.3 and Lemma 4.2]{ZhangW1pAubin} via different techniques.
\end{proof}
\cref{lemma: Ru2 interpolation} in particular justifies the definition
\begin{equation}
    \lambda_s(M, g) \doteq \inf \Big\{Q_g^s(u) \; : \; u \in W^{1,2}(M) \,, \; u \neq 0\Big\} \,.
\end{equation}
The case $s=2$ of \eqref{eq: sPDE} corresponds to the eigenvalue problem of the operator $\Lg$ and $\lambda_2(M,g)$ is thus its first eigenvalue. The special case $\lambda_{2^*}(M,g)$ is the \textit{Yamabe invariant} of $(M, g)$ and it follows immediately from the fact that
\begin{align*}
    Q_{v^{2^*-2}g}(u) = Q_{g}(vu)
\end{align*}
for any positive $v\in W^{2,q}(M)$, that $\lambda(M,g) \doteq \lambda_{2^*}(M,g)$ is an invariant of the conformal class 
\begin{align*}
    [\,g\,]_{W^{2,q}} = \Bigl\{u^{\frac{4}{n-2}}g \: : \: u\in W^{2,q}(M)\,, \: u>0 \Bigr\} \,.
\end{align*}
As a consequence, the Yamabe invariant of the round sphere $\nS^n$ equals to $\tfrac{a_n}{C_S}$, where $C_S$ is the optimal constant in the $W^{1,2}(\nR^n) \hookrightarrow L^{2^*}(\nR^n)$ Sobolev inequality --see \cite[Theorem 3.3]{Lee-Parker}--. Another consequence of \cref{lemma: Ru2 interpolation}, combined with the Rellich--Kondrachov compactness, is that direct methods allow for minimization of $Q_g^s$ whenever $s$ is subcritical:
\begin{proposition}
    \label{prop: subcritical existence}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ with $q > \tfrac{n}{2}$. For each $s \in [2, 2^*)$ there exists a nonnegative function $u \in W^{1,2}(M)$ with $\|u\|_{L^s(M,d\mu_g)} = 1$ such that $Q_g^s(u) = \lambda_s(M, g)$.
\end{proposition}
\begin{proof}
    Since $Q_g^s$ is bounded from below by \cref{lemma: Ru2 interpolation}, we consider a sequence $\{u_k\}_{k=1}^{\infty} \subset W^{1,2}(M)$ with $\|u_k\|_{L^s(M,d\mu_g)} = 1$ such that $\lim_{k\to \infty} Q_g^s(u_k) = \lambda_s(M, g)$. Since $Q_g(|u_k|) = Q_g(u_k)$, we may as well assume that $u_k \geq 0$. In addition, using \cref{lemma: Ru2 interpolation}, we estimate
    \begin{align*}
        &\Vert u_k\Vert^2_{W^{1,2}(M,d\mu_g)}=\Vert \nabla u_k\Vert^2_{L^{2}(M,d\mu_g)} + \Vert u_k\Vert^2_{L^{2}(M,d\mu_g)}
        \\
        &\leq \frac{1}{a_n}Q^s_g(u_k) - \frac{1}{a_n}\langle \R_g,u_k^2\rangle_{L^2(M,d\mu_g)} + \Vert u_k\Vert^2_{L^{2}(M,d\mu_g)}
        \\
        &\leq \frac{1}{a_n} Q^s_g(u_k) + \frac{1}{a_n}\Vert \R_g\Vert_{L^q(M,d\mu_g)}\Big(\varepsilon\Vert u_k\Vert^2_{W^{1,2}(M,d\mu_g)} +C_{\varepsilon}\Vert u_k\Vert^2_{L^2(M,d\mu_g)}\Big) + \Vert u_k\Vert^2_{L^{2}(M,d\mu_g)}.
    \end{align*}
    Picking $\varepsilon$ small enough allows us to absorb the second term in the left-hand side and, together the Hölder inequality $\Vert u_k\Vert_{L^2(M,d\mu_g)}\leq C(M,g)\Vert u_k\Vert_{L^s(M,d\mu_g)}=C(M,g)$, conclude that
    \begin{align*}
        \|u_k\|^2_{W^{1,2}(M,d\mu_g)} \leq C_1(M,g)(Q_g^s(u_k)+1) \,.
    \end{align*}
    In particular, $\{u_k\}_{k=1}^{\infty}$ is a bounded sequence in $W^{1,2}(M)$ and Rellich--Kondrachov compactness implies that there exists a subsequence, which we still call $\{u_k\}_{k=1}^{\infty}$, such that $u_k \to u$ in $L^s(M)$. On the other hand, $W^{1,2}(M)$ is weakly sequentially compact and therefore there exists a subsequence, also named $\{u_k\}_{k=1}^{\infty}$, converging $u_k \rightharpoonup \bar u$ weakly in $W^{1,2}(M)$ and thus, in particular, $u_k \rightharpoonup \bar u$ weakly in $L^{2}(M)$. Since $L^s(M)\hookrightarrow L^2(M)$ implies that $u_k\to u$ strongly in $L^2(M)$ and strong convergence implies weak convergence, uniqueness of weak $L^2(M)$ limits gives $\bar u = u \in W^{1,2}(M)$. Strong $L^s(M)$ convergence also implies that $\|u\|_{L^s(M,d\mu_g)} = 1$ and consequently $u \neq 0$. Notice now that weak $W^{1,2}$ convergence of $\{u_k\}_{k=1}^{\infty}$ implies by \cite[Chapter 3, Proposition 3.5(iii)]{BrezisBook} that
    \begin{align}
        \label{CalcVar.1}
        \|u\|_{W^{1,2}(M,d\mu_g)}\leq\liminf_{k\to\infty} \Vert u_k\Vert_{W^{1,2}(M,d\mu_g)} \,,
    \end{align}
    which combined with the fact that $\|u_k\|_{L^2(M)} \to \|u\|_{L^2(M)}$ by the strong $L^2(M)$ convergence, implies that
    \[\int_M |\nabla u|^2_g d\mu_g \leq \liminf_{k \to \infty} \int_M |\nabla u_k|^2_g d\mu_g \,.
    \]
    On the other hand, by \cref{lemma: Ru2 interpolation}
    \[\int_M \R_g u^2 d\mu_g = \lim_{k\to\infty} \int_M \R_g u_k^2 d\mu_g \,,
    \]
    and therefore the limit $u$ attains the minimum.
\end{proof}
\cref{prop: subcritical existence} above gives existence of non-negative weak solutions to \eqref{eq: sPDE}. The regularity theory developed in \cref{The Conformal Laplacian with Sobolev coefficients} together with a Harnack inequality due to Trudinger will allow us to promote them to positive solutions in $W^{2,q}(M)$ --see Corollary \ref{prop: subcritical regularity}--.
An important consequence is the following classification.
The analogue result for metrics of class $W^{s,2}(M)$ with $s > \tfrac{3}{2}$ can be found in \cite[Proposition 3.3]{Maxwell1} and the proof below is a 
combination of \cite[Proposition 3.3]{Maxwell1} and \cite[Theorem 4.8]{avalos2024sobolev}, where  
the latter is a special case of \cref{prop: subcritical regularity}. 
\begin{corollary}[Yamabe classification]
    \label{cor: Yamabe classification}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ with $q > \tfrac{n}{2}$. 
    \begin{enumerate}
        \item[(i)] $\lambda(M, g) > 0$ if and only if there exists some element in $[\,g\,]_{W^{2,q}}$ with $W^{2, q}$ positive scalar curvature.
        \item[(ii)] $\lambda(M, g) = 0$ if and only if there exists some element in $[\,g\,]_{W^{2,q}}$ with zero scalar curvature.
        \item[(iii)] $\lambda(M, g) < 0$ if and only if there exists some element in $[\,g\,]_{W^{2,q}}$ with $W^{2, q}$ negative scalar curvature.
    \end{enumerate}
\end{corollary}
\begin{proof}
    The first step in this proof is to notice that $\lambda(M,g)>0$ (respectively $=0$ or $<0$) implies  $\lambda_2(M)>0$ (respectively $=0$ or $<0$). This follows from the exact same  arguments as the implication $(2)\Longrightarrow (3)$ in \cite[Proposition 3.3]{Maxwell1}.\footnote{In that paragraph of \cite[Proposition 3.3]{Maxwell1} there appears to be a typo in the estimate $\Vert f\Vert^2_{L^2}\lesssim \Vert f\Vert^2_{L^6}$, which should be $\Vert f\Vert^2_{L^2}\lesssim \Vert f\Vert^2_{L^{2^{*}}}$. This typo appears to reflect the case of $n=3$ where $2^{*}=6$.} Once this is established, it is enough to work with the case of the first conformal eigenvalue $\lambda_2(M,g)$. 
    In all the forward statements, one can appeal to Corollary \ref{prop: subcritical regularity} in the special case of $s=2$ to conclude that the non-negative minimisers $u\in W^{1,2}(M)$ of $Q_g^2$ are actually positive $W^{2,q}$-solutions to the eigenvector equation\footnote{This result, especialised in the case of $s=2$, has already been proved in \cite[Theorem 4.8]{avalos2024sobolev}, which would be be enough to conclude our proof.}
    \begin{align*}
        -a_n\Delta_gu + \R_gu=\lambda_2(M,g)u.
    \end{align*}
    Via the conformal covariance of $\R_g$, this directly implies that $\tilde{g}=u^{\frac{4}{n-2}}g\in W^{2,q}(M)$ satisfies $\R_{\tilde{g}}=\lambda_2(M,g)u^{-\frac{4}{n-2}}\in W^{2,q}(M)$, which finishes the proof of all the forward implications.

    To establish all the backwards implications, one also follows \cite[Proposition 3.3]{Maxwell1} by noticing that if there some $\tilde{g}\in [\,g\,]_{W^{2,q}}$ such that $\R_{\tilde{g}}>0$ (respectively $=0$, $<0$), then the conformal invariance of $\lambda(M,g)$ allows to directly reduce to the case where this holds for $g$ itself. Then, the proof of the implication $(1)\Longrightarrow (2)$ in \cite[Proposition 3.3]{Maxwell1} works in our setting as well to establish that $\lambda(M,g)>0$ (respectively $=0$, $<0$), establishing then all the backwards implications.
\end{proof}



