\vspace{0.5cm}
\section{Analytical Results}
\label{Analytical Results}

In this section, we investigate the main analytical properties of the conformal Laplacian $\Lg$ of $W^{2,q}$-Riemannian metrics on closed manifolds of dimension $n \geq 3$ and $q > \tfrac{n}{2}$. We develop a local and global regularity theory and establish isomorphism ranges for positive Yamabe metrics. Although the associated local theory for $W^{1,2}$-weak solutions for operators like $\Lg$ is well-known from standard references such as \cite[Chapter 8]{GT}, we will work with weaker a-priori solutions and therefore outside of the scope of the results therein. Some results closely related to our thresholds can be found in \cite[Chapter 3, Proposition 1.13]{TaylorToolsForPDEs}, which one may for instance compare to \cref{thm: main global elliptic regularity}. It is also worth noting that similar mapping properties of $\mathscr{L}_g$ for rough metrics have been studied in the context of the Einstein constraint equations of general relativity \cite{Maxwell1}. Once again, our results are slightly outside of the scope of these references and hence we need to develop a theory tailored for our applications. 

Along this section we will provide some regularity statements which apply to a set of \emph{extremely weak} solutions to elliptic equations associated with operators with rough coefficients --see \cref{thm: 12 local elliptic regularity} items $(i)-(ii)$ and \cref{thm: conf Laplace elliptic regularity} item $(i)$--. In particular, we will often work with a priori solutions below $W^{1,2}$, where the De Giorgi--Nash theory or related results (such as those developed in \cite{Morrey}) do not apply. We refer the reader to \cite{Brezis1,Serrin} and the introduction to \cite{avalos2024sobolev} for further discussions on this topic.



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Laplace--Beltrami operator with Sobolev coefficients}
\label{SectionLapceOp}
We begin by studying the Laplace--Beltrami operator
\begin{equation*}
    \Delta_g \doteq \tr_g\nabla^2
\end{equation*}
of metrics of Sobolev regularity. For a Riemannian metric $g \in W^{2,q}(T_2M)$, the operator $\Delta_g : C^{\infty}(M) \to W^{1,q}(M)$ can locally be written in divergence form
\begin{equation*}
    \Delta_gu = \frac{1}{\sqrt{\mathrm{det}(g)}}\partial_{i}(g^{ij}\sqrt{\mathrm{det}(g)}\partial_{j}u)
\end{equation*}
and as a consequence of \cref{SobolevMultLocal}, it extends to a bounded map $\Delta_g:W^{2,p}(M)\to L^{p}(M)$ for all $1< p\leq q$. If $u\in C^{\infty}(M)$ is a regular distribution in $\mathscr{D}'(M)$ and $v\in \mathscr{D}(U_\alpha)$ for a coordinate chart $(U_{\alpha},\varphi_{\alpha})$, then $\Delta_gu\in \mathscr{D}'(M)$ is defined by
\begin{align}
    \label{DistributionalLapGlboal.1}
    (\Delta_gu)(v)=\langle u,\Delta_gv\rangle_{L^2(M,d\mu_g)}=\langle u,\Delta_gv\rangle_{(M,g)} \,.
\end{align}
Thus, using the notation of \cref{SectionSobolevSpaces}, we can directly compute the local representative $\hat{T}_{\alpha}\Delta_gu$ for $u\in C^{\infty}(M)$ on any coordinate chart, given by
\begin{align*}
    (\hat{T}_{\alpha}\Delta_gu)(\tilde{v})&=(\Delta_gu)(\tilde{v}\circ\varphi_{\alpha})=\langle u,\Delta_g\tilde{v}\circ\varphi_{\alpha}\rangle_{L^2(U_{\alpha},d\mu_g)}
    \\
    &=\langle \Delta_g(u\circ\varphi^{-1}_{\alpha}),(\mathrm{det}(g)\circ\varphi_{\alpha}^{-1})^{\frac{1}{2}}\tilde{v}\rangle_{L^2(\varphi_{\alpha}(U_{\alpha}),dx)}
\end{align*}
for all $\tilde v \in \mathscr D(\varphi_\alpha(U_\alpha))$, that is, 
\begin{align}
    \label{DistributionalLapLocal}
    \hat{T}_{\alpha}\Delta_gu=(\mathrm{det}(g)\circ\varphi_{\alpha}^{-1})^{\frac{1}{2}}\Delta_g(u\circ\varphi^{-1}_{\alpha}) \,.
\end{align}
Appealing again to \cref{SobolevMultLocal}, 
it is not hard to see that one may extend $\Delta_g$ by continuity to a bounded map $L^p(M) \to W^{-2,p}(M)$ for all $p \geq q'$ and it is locally represented by \eqref{DistributionalLapLocal}. Moreover, this extension grants that the dual pairing \eqref{DistributionalLapGlboal.1} extends by continuity as well, that is, for all $u\in W^{-2,p}(M)$ and all $v\in W^{2,p'}(M)$ with $p\geq q'$ there holds
\begin{align*}
    \langle \Delta_gu,v\rangle_{(M,g)}&=\lim_{j\to \infty}\langle \Delta_gu_j,v\rangle_{(M,g)}=\lim_{j\to \infty}\langle u_j,\Delta_gv\rangle_{L^2(M,d\mu_g)}=\langle u,\Delta_gv\rangle_{L^2(M,d\mu_g)} \,.
\end{align*}

In a previous paper, the first-named author established
\begin{theorem}[\cite{avalos2024sobolev}, Corollary 4.2 and Corollary 4.4]
    \label{thm: Rodri Global W1p W2p regularity}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ on $M$ with $q > \tfrac{n}{2}$. 
    \begin{enumerate}
        \item[(i)] If $u \in L^{q'}(M)$ and $\Delta_g u \in W^{-1,p}(M)$ for some $\tfrac{1}{q} - \tfrac{1}{n} \leq \tfrac{1}{p} < \tfrac{1}{q'} + \tfrac{1}{n}$, then it follows that $u \in W^{1,p}(M)$.
        \item[(ii)] If $u \in L^{q'}(M)$ and $\Delta_g u \in L^p(M)$ for some $1 < p \leq q$, then it follows that $u \in W^{2,p}(M)$.
    \end{enumerate}
\end{theorem}
From here, we obtain the following local version, extending \cite[Corollary 4.5]{avalos2024sobolev}:
\begin{theorem}
    \label{thm: 12 local elliptic regularity}
    Let $\Omega \subset \nR^n$ be an open, bounded domain with smooth boundary and consider a Riemannian metric $g \in W^{2,q}(T_2\Omega)$ with $q > \tfrac{n}{2}$.
    \begin{enumerate}
        \item[(i)] If $u \in L^{q'}(\Omega)$ and $\Delta_gu \in W^{-1,p}(\Omega)$ for some $\tfrac{1}{q} - \tfrac{1}{n} \leq \tfrac{1}{p} < \tfrac{1}{q'} + \tfrac{1}{n}$, then it follows that $u \in W^{1,p}_{loc}(\Omega)$.
        \item[(ii)] If $u \in L^{q'}(\Omega)$ and $\Delta_gu \in L^{p}(\Omega)$ for some $\tfrac{1}{q} \leq \tfrac{1}{p} < \tfrac{1}{q'} + \tfrac{1}{n}$, then it follows that $u \in W^{2,p}_{loc}(\Omega)$.
        \item[(iii)] If $u \in L^{q'}(\Omega) \cap W^{1,p}(\Omega)$ and $\Delta_gu \in L^{p}(\Omega)$ for some $1 < p \leq q$, then it follows that $u \in W^{2,p}_{loc}(\Omega)$.
    \end{enumerate}
\end{theorem}
\begin{proof}
    Consider a cube $Q = [-L, L]^n \subset \nR^n$ large enough so that $\Omega \subset \subset Q$. Since $\partial\Omega$ is smooth, we might extend $g$ to a $W^{2,q}$-Riemannian metric in a tubular neighbourhood
    \begin{equation*}
        \Omega_\varepsilon \doteq \{x \in \nR^n \;:\; |x - y| < \varepsilon \; \text{for some} \; y \in \Omega\} \subset\subset Q \,.
    \end{equation*}
    Using a smooth cutoff function $\chi : Q \to [0,1]$ such that $\chi \equiv 1$ on $\Omega$ and $\supp \chi \subset\subset \Omega_\varepsilon$ we may consider a new Riemannian metric
    \begin{equation*}
        \bar g_{ij} \coloneqq \chi g_{ij} + (1-\chi) \delta_{ij}
    \end{equation*}
    which extends to the whole cube $Q$ and is equal to the Euclidean metric in $Q \setminus \Omega_\varepsilon$. Hence, the torus $T^n$ obtained by identifying sides of $Q$ can be endowed with a Riemannian metric locally isometric to $\bar{g}$, which we shall still denote by $\bar g$\footnote{This is obtained by considering $\mathbb{Z}^n_{2kL}$ as the group of integers $\mathbb{Z}^n$ acting on $\mathbb{R}^n$ by $\mathbb{Z}^n\times \mathbb{R}^n\to \mathbb{R}^n$, $(k,x)\mapsto (x^1+2k^1L,\cdots,x^n+2k^nL)$. Since $y=Tx$ for any $y\in \mathbb{R}^n$ and a unique $T\in \mathbb{Z}_{2kL}$, $x\in Q$, and $T$ is a local smooth diffeomorphism, one may extend $\bar{g}$ isometrically to $\mathbb{R}^n$ as $(\bar{g}_{\mathbb{R}^n})_y(T_xv,T_xw)\doteq \bar{g}_x(v,w)$. Then, $T^n=\mathbb{R}^n\backslash \mathbb{Z}^n_{2kL}$ and $(\pi^{-1})^{*}\bar{g}_{\mathbb{R}^n}$ is a locally isometric of $\bar{g}_{\mathbb{R}^n}$, where $\pi:\mathbb{R}^n\to T^n$ is the projection map.}. Likewise, for any $\Omega' \subset\subset \Omega$ we might use a cutoff function $\eta \in C^\infty_0(\Omega)$ with $\eta \equiv 1$ on $\Omega'$ to extend $u$ to a function $\bar u \coloneqq \eta u$ on $T^n$ with compact support in $\Omega$. 
    We then compute
    \begin{equation}
        \label{eq: lap bar u bar}
        \Delta_{\bar g} \bar u = \Delta_{g} \bar u = \eta \Delta_{g} u + u \Delta_{g} \eta + 2g(\nabla u, \nabla \eta) \,.
    \end{equation}

    (\textit{i}) If $\Delta_gu \in W^{-1,p}(\Omega)$ then $\eta \Delta_gu \in W^{-1,p}(T^n)$ as a consequence of
    \begin{align*}
        C^\infty_0(\Omega) \otimes W^{-1,p}(\Omega) \hookrightarrow W^{-1,p}(T^n) \,.
    \end{align*}
    This follows from the localization provided by $\eta$: for any $\varphi \in W^{1,p'}(T^n)$ one can easily check that $(\eta \Delta_g u) (\varphi) = \Delta_g u (\eta \varphi)$ is well-defined and bounded, as $\eta \varphi \in W^{1,p'}_0(\Omega)$. By the same argument, $u \in L^{q'}(\Omega)$ implies that $g(\nabla u, \nabla \eta) \in W^{-1,q'}(T^n)$ and thus the right-hand-side of \eqref{eq: lap bar u bar} is in $W^{-1,\min\{p,q'\}}(T^n)$. We claim that $g(\nabla u, \nabla\eta)$, and in turn $\Delta_{\bar g}\bar u$, is indeed in $W^{-1,p}(T^n)$. If $p \leq q'$, it is immediate. On the other hand, if $p > q'$, one can check that $\tfrac{1}{q} - \tfrac{1}{n} \leq  \tfrac{1}{q'} < \tfrac{1}{q'} + \tfrac{1}{n}$ due to $q > \tfrac{n}{2} \geq \tfrac{2n}{n + 1}$ for $n \geq 3$. Hence, applying \cref{thm: Rodri Global W1p W2p regularity} we obtain $\bar u \in W^{1, q'}(T^n)$. Therefore,
    \begin{equation*}
        g(\nabla u, \nabla \eta ) \in L^{q'}(T^n) \hookrightarrow W^{-1, p_0}(T^n)
    \end{equation*}
    with $\tfrac{1}{p_0} \doteq \tfrac{1}{q'} - \tfrac{1}{n} $ due to the Sobolev embedding $W^{1, p_0'}(T^n) \hookrightarrow L^{q}(T^n)$. Notice that due to $q > \tfrac{n}{2}$, there holds $\tfrac{1}{q'} - \tfrac{1}{n} > 1 - \tfrac{2}{n} - \tfrac{1}{n} \geq 0$ for $n \geq 3$. Now, if $p \leq p_0$, we are done. Instead, if $p > p_0$, in particular $\tfrac{1}{q} - \tfrac{1}{n} \leq \frac{1}{p}<\tfrac{1}{p_0} < \tfrac{1}{q'} + \tfrac{1}{n}$ holds, where the first inequality follows by our hypotheses on $p$, and we may apply \cref{thm: Rodri Global W1p W2p regularity} to get $\bar u \in W^{1,p_0}(T^n)$. If $p_0 \geq n$, then $ g(\nabla u, \nabla \eta ) \in L^{p_0}(T^n) \hookrightarrow W^{-1, l}(T^n)$ for every $l < \infty$, in particular for $l = p$ and we are done. If not, that is if $p_0<\min\{n,p\}$, fixing $\tfrac{1}{p_1} \doteq \tfrac{1}{p_0} - \tfrac{1}{n}$ one has $L^{p_0}(T^n) \hookrightarrow W^{-1, p_1}(T^n)$. This follows since 
    \begin{align*}
        L^{p_0}(T^n) \hookrightarrow W^{-1, p_1}(T^n)\Longleftrightarrow W^{1, p'_1}(T^n)\hookrightarrow L^{p'_0}(T^n).
    \end{align*}
    By definition of $p_0$, one has $\frac{1}{p'_0}=\frac{1}{q}+\frac{1}{n}>\frac{1}{n}$ and thus $p'_0<n$. Since $\frac{1}{p'_1}=\frac{1}{p'_0}+\frac{1}{n}$, this in turn implies $p'_1<p'_0<n$ and therefore $W^{1, p'_1}(T^n)\hookrightarrow L^{\frac{np'_1}{n-p'_1}}(T^n)=L^{p'_0}(T^n)$, due to $\frac{1}{p'_1}-\frac{1}{n}=\frac{1}{p'_0}$. Having then $L^{p_0}(T^n) \hookrightarrow W^{-1, p_1}(T^n)$ established, if $\min\{p,n\} \leq p_1$, we conclude as before. Otherwise, we can iterate the above argument with a sequence $\tfrac{1}{p_{i+1}} \doteq \tfrac{1}{p_i} - \tfrac{1}{n}$ for $i \in \mathbb{N}$ until $p_i \geq \min\{p, n\}$. Once the right-hand side is in $W^{-1,p}(T^n)$ it follows from \cref{thm: Rodri Global W1p W2p regularity} that $\bar u \in W^{1,p}(T^n)$ and consequently, $u \in W^{1,p}(\Omega')$. Since $\Omega' \subset\subset \Omega$ was arbitrary, the claim follows.

    (\textit{ii}) If $\Delta_g u \in L^p(\Omega)$ by hypothesis for $\tfrac{1}{p} < \tfrac{1}{q'} + \tfrac{1}{n}$, then $\Delta_gu \in W^{-1,q'}(\Omega)$ and the same localization argument as above implies that the right-hand-side of \eqref{eq: lap bar u bar} is in $W^{-1,q'}(T^n)$. Just as above, one can also check that $q'$ satisfies the hypothesis of \cref{thm: Rodri Global W1p W2p regularity} part (\textit{i}) and hence it follows that $\bar u \in W^{1,q'}(T^n)$. Now if $p \leq q'$, then $\Delta_{\bar g}\bar u \in L^p(T^n)$ by \eqref{eq: lap bar u bar} and \cref{thm: Rodri Global W1p W2p regularity} part (\textit{ii}) shows that $\bar u \in W^{2,p}(T^n)$. If $q' < p \leq q$ instead, then $\Delta_{\bar g}\bar u \in L^{q'}(T^n)$ and we may apply \cref{thm: Rodri Global W1p W2p regularity} to obtain $\bar u \in W^{2,q'}(T^n)$. Observe that $q > \tfrac{n}{2}$ implies that $q' < \tfrac{n}{n-2} \leq n$, so we may use the Sobolev embedding $W^{2,q'}(T^n) \hookrightarrow W^{1,p_0}(T^n)$ with $\tfrac{1}{p_0} \doteq \tfrac{1}{q'} - \tfrac{1}{n}$ to conclude that $g(\nabla u, \nabla\eta) \in L^{p_0}(T^n)$. If $p_0 \geq p$, then $\Delta_{\bar g}\bar u \in L^p(T^n)$ and we conclude. If $p_0 < p \leq q$ instead, $\Delta_{\bar g}\bar u \in L^{p_0}(T^n)$ and part (\textit{ii}) of \cref{thm: Rodri Global W1p W2p regularity} yields $\bar u \in W^{2,p_0}(T^n)$. If $p_0 \geq \tfrac{pn}{p+n}$, then $W^{2,p_0}(T^n) \hookrightarrow W^{1,p}(T^n)$ and we are done, as $\Delta_{\bar g}\bar u \in L^p(T^n)$. If $p_0 < \tfrac{pn}{p+n} < n$, we use that $W^{2,p_0}(T^n) \hookrightarrow W^{1,p_1}(T^n)$ with $\tfrac{1}{p_1} \doteq \tfrac{1}{p_0} - \tfrac{1}{n}$ to obtain that $\Delta_{\bar g}\bar u \in L^{p_1}(T^n)$. At this point, it is easy to see that we can iterate the process to obtain a finite sequence $q' < p_0 < p_1 < \ldots < p_N$ defined by $\tfrac{1}{p_i} \doteq \tfrac{1}{p_{i-1}} - \tfrac{1}{n}$ with $p_N \geq \tfrac{pn}{p+n}$ for which $\bar u \in W^{2,p_i}(T^n)$. Consequently, $\Delta_{\bar g}\bar u \in L^p(T^n)$ and after using part (\textit{ii}) of \cref{thm: Rodri Global W1p W2p regularity} we obtain that $\bar u \in W^{2,p}(T^n)$. Thus, we conclude as before that $u \in W^{2,p}(\Omega')$ and the claim follows.

    (\textit{iii}) If $u \in L^{q'}(\Omega) \cap W^{1,p}(\Omega)$ and $\Delta_gu \in L^p(\Omega)$, the right-hand-side of \eqref{eq: lap bar u bar} is in $L^p(T^n)$ and we directly get the desired result applying part (\textit{ii}) of \cref{thm: Rodri Global W1p W2p regularity}.
\end{proof}
By an induction argument, we further obtain:
\begin{theorem}
    \label{thm: main local elliptic regularity}
    Let $\Omega \subset \nR^n$ be an open, bounded domain with smooth boundary and consider a Riemannian metric $g \in W^{k,q}(T_2\Omega)$ with $q > \tfrac{n}{2}$ and $k \geq 2$. If $u \in W^{k-2, q'}(\Omega)\, \cap \,W^{k-1, p}(\Omega)$ and $\Delta_g u \in W^{k-2, p}(\Omega)$ for some $1 < p \leq q$, then it follows that $u \in W^{k,p}_{loc}(\Omega)$.
\end{theorem}
\begin{proof}
    We will proceed by induction on $k \geq 2$. Notice that the base case $k = 2$ has been proven in part (\textit{iii}) of \cref{thm: 12 local elliptic regularity}. Let us then assume that the theorem holds for $k-1 \geq 2$ and show that it holds for $k$. By hypothesis $\Delta_g u = f$ with $f \in W^{k-2, p}(\Omega)$. Hence, differentiating it in direction $x^a$, we get 
    \begin{align*}
        \Delta_g (\partial_a u) = \partial_a f - (\partial_a g^{ij}) \left(\partial_i \partial_j u  - \Gamma_{ij}^l \,\partial_l u \right) + g^{ij} \partial_a \Gamma_{ij}^l \,\partial_l u\,.
    \end{align*}
    Notice that since $k \geq 3$, then $\partial_a g^{ij}$ and  $\Gamma_{ij}^l$ are $W^{k-1, q}(\Omega)$ with $k - 1 \geq 2$ and $q > \tfrac{n}{2}$; in turn, in combination with the hypothesis $u \in W^{k-1, p}(\Omega)$, the second term of the right hand side is in $W^{k-3, p}(\Omega)$ by Theorem \ref{SobolevMultLocal}. On the other hand, also by the multiplication properties of \cref{SobolevMultLocal}, 
    \[\partial_a \Gamma_{ij}^l \,\partial_l u \in W^{k-2, q}(\Omega) \otimes W^{k-2, p}(\Omega) \hookrightarrow W^{k-3, p}(\Omega) \,.
    \]
    Hence, by combining these observation with the hypotheses on $f$ and $u$, the function $\partial_a u \in  W^{k-3, q'}(\Omega)\, \cap \,W^{k-2, p}(\Omega)$ satisfies $\Delta_g (\partial_a u) \in W^{k-3, p}(\Omega)$. By the inductive hypothesis, we can immediately conclude that $\partial_a u \in W^{k-1, p}_{loc}(\Omega)$, from which the desired result follows. 
\end{proof}
We can then extend \cref{thm: main local elliptic regularity} to compact manifolds.
\begin{theorem}
    \label{thm: main global elliptic regularity}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{k,q}$-Riemannian metric $g$ on $M$ with $k \geq 2$ and $q > \tfrac{n}{2}$. If $u \in W^{k-2, q'}(M)\, \cap \,W^{k-1, p}(M)$ and $\Delta_g u \in W^{k-2, p}(M)$ for some $1 < p \leq q$, then $u \in W^{k,p}(M)$.
\end{theorem}
\begin{proof}
   Let us consider a chart $(U, \varphi)$ on $M$, so that $\varphi(U) \subset \nR^n$ is an open, bounded domain with smooth boundary. Consider then a cutoff function $\eta \in C^{\infty}_0(\varphi(U))$ and notice that $\eta (u \circ \varphi^{-1}) \in W^{k-2, q'}(\varphi(U)) \cap W^{k-1, p}(\varphi(U))$ by hypothesis. 
    Now, we can compute 
   \[ \Delta_g (\eta (u \circ \varphi^{-1})) = \eta \,\Delta_g (u \circ \varphi^{-1}) + g\left( \nabla\eta,\, \nabla (u \circ \varphi^{-1}) \right) + \Delta_g \eta \, (u \circ \varphi^{-1})\,.\]
   It is easy to see that the right-hand side is in $W^{k-2, p}(\varphi(U))$, in particular relying on $\eta (u \circ \varphi^{-1}) \in W^{k-1, p}(\varphi(U))$.
   Hence, we can apply \cref{thm: main local elliptic regularity} and obtain that $\eta (u \circ \varphi^{-1}) \in W^{k, p}(\varphi(U))$. Since the chart and the partition of unity were arbitrary, the proof concludes.
\end{proof}
\begin{remark}\label{rmk: main global elliptic regularity}
    Notice that if $p = q$, the embedding $W^{k-1, q}(M) \hookrightarrow W^{k-2, q'}(M)$ holds and therefore the condition $u \in W^{k-2, q'}(M)$ in \cref{thm: main global elliptic regularity} is redundant. 
\end{remark}


