\subsection{The conformal Laplacian with Sobolev coefficients}
\label{The Conformal Laplacian with Sobolev coefficients}

We now move on to study the \textit{conformal Laplacian}
\begin{align*}
    \Lg = -a_n\Delta_g + \R_g \,.
\end{align*}
As observed in \cref{The Yamabe classification}, it is a very special Schrödinger-type operator that naturally shows up in conformal deformations of the scalar curvature. As such, it is not only invariant under diffeomorphisms, but also covariant under conformal deformations: for a conformal metric $\tilde g = u^{\frac{4}{n-2}} g$, the operator transforms like
\begin{equation}
    \label{eq: conformal covariance Lg}
    \mathscr L_{\bar g} \,v = u^{-\frac{n+2}{n-2}} \Lg(uv) \,.
\end{equation}
This symmetry will be conveniently exploited later on.
\begin{lemma}
    \label{lemma: Lg is Fredholm}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{k,q}$-Riemannian metric $g$ on $M$ with $k \geq 2$ and $q > \tfrac{n}{2}$. For each $1 < p \leq q$ the operator 
    \begin{equation*}
        \Lg : W^{k,p}(M) \to W^{k-2,p}(M)
    \end{equation*}
    is Fredholm of index zero and there exists a constant $C = C(M,g,n,p,q)$ such that
    \begin{equation}\label{estimate: semi-Fredholm}
        \|u\|_{W^{k,p}(M)} \leq C \Big(\|\Lg u \|_{W^{k-2,p}(M)} + \|u\|_{W^{k-2,p}(M)}\Big)
    \end{equation}
    holds for all $u \in W^{k,p}(M)$.
\end{lemma}
\begin{proof}  
    First, observe that if a sequence of metrics $\{g_j\}_{j=1}^{\infty} \subset C^{\infty}(T_2M)$ converges to $g$ in $W^{2,q}(T_2M)$, it is not hard to check that $\mathscr{L}_{g_j} \to \Lg$ in operator norm between the Banach spaces $W^{k,p}(M)$ and $W^{k-2,p}(M)$, that is, for any $u \in W^{k,p}(M)$ with $\|u\|_{W^{k,p}(M)} = 1$ there holds
    \begin{equation*}
        \| (\Lg - \mathscr{L}_{g_j})u  \|_{W^{k-2,p}(M)}  \leq C(M, p, q) \, \|g - g_j\|_{W^{k, q}(M)}\,.
    \end{equation*}
    Now, since the conformal Laplacian of a smooth metric is formally self-adjoint, it follows from standard results on linear operators that the operators $\mathscr{L}_{g_j}$ are Fredholm with index zero for all $j$. In addition, it is well-known --see e.g \cite[Theorem 5.16]{Kato}-- that the Fredholm index is locally constant in the space of semi-Fredholm operators acting between two given Banach spaces. Hence, once we show that $\Lg$ is semi-Fredholm, we can immediately conclude that it is Fredholm of index zero. Therefore, it suffices to prove the elliptic estimate \eqref{estimate: semi-Fredholm}.

    The case $k = 2$ of \eqref{estimate: semi-Fredholm} is known to hold, for instance from \cite[Theorem 3.1]{avalos2024sobolev}, so we proceed by induction: assume it holds for some $k \geq 2$ and using the hypothesis $g \in W^{k+1,q}(T_2M)$, let us prove it for $k+1$. Let us suppose first that $u \in W^{k+1,p}_0(U_\alpha)$ for some coordinate ball $(U_\alpha, \varphi_\alpha)$ and name $B_\alpha \doteq B_{r_\alpha}(0) = \varphi_\alpha(U_\alpha)$ and $u_\alpha \doteq u \circ \varphi^{-1}_{\alpha}$. By the induction hypothesis, we know in particular that there exists a positive constant $C_\alpha = C(M,g,n,p,q,r_\alpha)$ such that
    \begin{equation}
        \label{eq: ellipest10}
        \|\partial_au_\alpha\|_{W^{k,p}(B_\alpha)} \leq C_{\alpha} \Big(\|\Lg(\partial_au_{\alpha}) \|_{W^{k-2,p}(B_\alpha)} + \|\partial_au_{\alpha}\|_{W^{k-2,p}(B_\alpha)}\Big) \,.
    \end{equation}
    Below, we will keep using $C_\alpha$ to denote some constant with the same dependence, though its value might change from line to line. Direct computation gives
    \begin{equation}
        \label{eq: ellipest1}
        \Lg(\partial_{a}u_{\alpha}) = \partial_{a} \Lg u_{\alpha} + a_n\partial_{a}g^{ij}\bigl(\partial_{i}\partial_{j}u_{\alpha} - \Gamma^l_{ij}\partial_lu_\alpha\bigr) - \partial_{a}\R_gu_{\alpha} - a_ng^{ij}\partial_{a}\Gamma^l_{ij}\partial_{l}u_{\alpha}
    \end{equation}
    and using the Sobolev multiplications
    \begin{align*}
        W^{k,q}(B_\alpha) \otimes W^{k-2,p}_0(B_\alpha) \hookrightarrow  W^{k-2,p}_0(B_\alpha) \,,
        \\
        W^{k-2,q}(B_\alpha) \otimes W^{k,p}_0(B_\alpha) \hookrightarrow  W^{k-2,p}_0(B_\alpha)
    \end{align*}
    which hold since $p\leq q$ and $k\geq 2>\frac{n}{q}$ by hypothesis (see \cref{SobolevMultLocal}), we obtain for the first four terms of the right-hand-side of \eqref{eq: ellipest1} the inequalities
    \begin{equation*}
        \|\partial_a\Lg u_\alpha\|_{W^{k-2,p}(B_\alpha)} \leq \|\Lg u_\alpha\|_{W^{k-1,p}(B_\alpha)} \,,
    \end{equation*}
    \begin{align*}
         \|\partial_{a}g^{ij} \partial_{i}\partial_{j}u_{\alpha}\|_{W^{k-2,p}(B_\alpha)} \leq C_\alpha\|\partial_ag^{ij}\|_{W^{k,q}(B_\alpha)}\|\partial_i\partial_ju_\alpha\|_{W^{k-2,p}(B_\alpha)} \leq C_\alpha \|u_\alpha\|_{W^{k,p}(B_\alpha)} \,,
    \end{align*}
    \begin{align*}
         \|\partial_{a}g^{ij} \Gamma^l_{ij}\partial_lu_{\alpha}\|_{W^{k-2,p}(B_\alpha)} &\leq C_\alpha\|\partial_ag^{ij}\|_{W^{k,q}(B_\alpha)}\|\Gamma^l_{ij}\|_{W^{k,q}(B_\alpha)}\|\partial_lu_\alpha\|_{W^{k-2,p}(B_\alpha)} 
         \\
         &\leq C_\alpha \|u_\alpha\|_{W^{k,p}(B_\alpha)} \,,
    \end{align*}
    \begin{align*}
         \|\partial_{a}\R_g u_{\alpha}\|_{W^{k-2,p}(B_\alpha)} \leq C_\alpha\|\partial_a\R_g\|_{W^{k-2,q}(B_\alpha)}\|u_\alpha\|_{W^{k,p}(B_\alpha)} \leq C_\alpha \|u_\alpha\|_{W^{k,p}(B_\alpha)} \,.
    \end{align*}
    For the last term, we note that 
    \begin{equation*}
        W^{k-2,q}(B_\alpha) \otimes H^{s,p}(B_\alpha) \hookrightarrow W^{k-2,p}(B_\alpha) 
    \end{equation*}
    holds for all $s\in \mathbb{R}$ as long as $1<p\leq 1$, $k-2\leq s\leq k$, and $s>\frac{n}{q}$. Since $\frac{n}{q}<2\leq k$ by hypothesis, then $\max\{k-2,\tfrac{n}{q}\} < k$ and we can always fix some $s\in (\max\{k-2,\frac{n}{q}\},k)$ depending on $n$, $k$ and $q$ so that
    \begin{align*}
        \|g^{ij} \partial_{a}\Gamma^l_{ij}\partial_{l}u_{\alpha}\|_{W^{k-2,p}(B_\alpha)} &\leq C_\alpha\|g^{ij} \partial_{a}\Gamma^l_{ij}\|_{W^{k,q}(B_\alpha)}\|\partial_lu_\alpha\|_{H^{s,p}(B_\alpha)} \leq C_\alpha\|u_\alpha\|_{H^{s+1,p}(B_\alpha)}
    \end{align*}
    holds. In view of \eqref{eq: ellipest10} and \eqref{eq: ellipest1}, we establish via the triangle inequality the estimate
    \begin{equation}
        \label{eq: ellipest 5}
        \|u_\alpha\|_{W^{k+1,p}(B_\alpha)} \leq C_{\alpha} \Big(\|\Lg u_{\alpha}\|_{W^{k-1,p}(B_\alpha)} + \|u_{\alpha}\|_{H^{s+1,p}(B_\alpha)} + \|u_{\alpha}\|_{W^{k-1,p}(B_\alpha)}\Big) \,.
    \end{equation}
    Now we may apply Ehrling's lemma to the compact-continuous embeddings
    \begin{equation*}
        W^{k+1,p}(B_\alpha) \hookrightarrow H^{s+1,p}(B_\alpha) \hookrightarrow W^{k-1,p}(B_\alpha)
    \end{equation*}
    to get that for each $\varepsilon > 0$ there exists some $C_\varepsilon > 0$ such that
    \begin{equation*}
        \|u_\alpha\|_{H^{s+1,p}(B_\alpha)} \leq \varepsilon \|u_\alpha\|_{W^{k+2,p}(B_\alpha)} + C_\varepsilon \|u_\alpha\|_{W^{k-1,p}(B_\alpha)} \,.
    \end{equation*}
    In combination with \eqref{eq: ellipest 5} and choosing $\varepsilon = \tfrac{1}{2C_\alpha}$, we conclude
    \begin{equation}
        \label{eq: ellipest 7}
        \|u_\alpha\|_{W^{k+1,p}(B_\alpha)} \leq C_{\alpha} \Big(\|\Lg u_{\alpha}\|_{W^{k-1,p}(B_\alpha)} + \|u_{\alpha}\|_{W^{k-1,p}(B_\alpha)}\Big) \,,
    \end{equation}
    as desired.

    For the general case $u\in W^{k+1,p}(M)$, one may take a finite covering $\{(U_{\alpha},\varphi_{\alpha})\}_{\alpha=1}^N$ of $M$ by coordinate balls as above and a subordinate partition of unity $\{\eta_{\alpha}\}_{\alpha=1}^N$ to write $u=\sum_{\alpha=1}^N\eta_{\alpha}u$ with $\eta_{\alpha}u\in W^{k+1,p}(U_{\alpha})$. Then, 
    \begin{align*}
        \|u\|_{W^{k+1,p}(M)} \leq \sum_{\alpha=1}^N\| \eta_{\alpha}u\|_{W^{k+1,p}(M)} \,,
    \end{align*}
    where now \eqref{eq: ellipest 7} can be applied directly to each $u_{\alpha}\doteq (\eta_{\alpha}u)\circ \varphi_{\alpha}^{-1}$ which grants the existence of a positive constant $C_{\alpha}=C(M,p,q,k,g,r_{\alpha})$ such that
    \begin{align}
        \label{FredholmEstimateLocal.1}
        \|\eta_{\alpha}u\|_{W^{k+1,p}(M)} &\leq C_{\alpha}\Big(\Vert \mathscr{L}_g(\eta_{\alpha}u) \Vert_{W^{k-1,p}(M)}  + \Vert \eta_{\alpha}u\Vert_{L^{p}(M)}\Big).
    \end{align}
    One may estimate $\|\eta_{\alpha} u\|_{L^{p}(M)}\leq \|u\|_{L^{p}(M)}$ and after we expanding 
    \begin{align*}
        \Lg(\eta_{\alpha}u) = \eta_{\alpha}\Lg u - 2a_ng(\nabla\eta_{\alpha},\nabla u) - a_n u \Delta_g\eta_\alpha
    \end{align*}
    we also get
    \begin{align}
        \label{FredholmInduction.10}
        \|\Lg(\eta_{\alpha}u)\|_{W^{k-1,p}(M)} \leq C_\alpha \Big(\|\Lg u\|_{W^{k-1,p}(M)} + \|\nabla u\|_{W^{k-1,p}(M)} + \|u\|_{W^{k-1,p}(M)}\Big) \,.
    \end{align}
    In conclusion, we obtain
    \begin{align*}
        \|u\|_{W^{k+1,p}(M)} &\leq \sum_{\alpha=1}^N C_\alpha \Big(\|\Lg u\|_{W^{k-1,p}(M)} + \|u\|_{W^{k,p}(M)}\Big)
        \\
        &\leq C(M,g,n,p,q) \Big(\|\Lg u\|_{W^{k-1,p}(M)} + \|u\|_{W^{k,p}(M)}\Big)
    \end{align*}
    and the assertion follows from the $W^{k+1}(M) \hookrightarrow W^{k,p}(M) \hookrightarrow W^{k-1,p}(M)$ interpolation inequality
    \begin{align*}
        \|u\|_{W^{k,p}(M)} \leq \varepsilon \|u\|_{W^{k+1,p}(M)} + C_{\varepsilon}\|u\|_{W^{k-1,p}(M)}
    \end{align*}
    after choosing $\varepsilon > 0$ small enough.
\end{proof}

The above lemma plays a crucial role in providing, among others, a regularity claim for $\Ker(\Lg|_{W^{2,p}(M)})$, as can be seen in the following statement.
\begin{lemma}
    \label{lemma: kernel_improvement}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{k,q}$-Riemannian metric $g$ on $M$ with $k \geq 2$ and $q > \tfrac{n}{2}$. For each $1< p \leq q$ there holds that
    \begin{equation*}
        \Ker(\Lg|_{W^{2,p}(M)}) = \Ker(\Lg|_{W^{2, q}(M)}) \,.
    \end{equation*}
    That is, in the cited range for $p$, $\Ker(\Lg|_{W^{2,p}(M)})$ is independent of $p$.
\end{lemma}
\begin{proof}
    Since $q \geq p$ and $q' \leq p'$, we have the inclusions $W^{2,q}(M) \hookrightarrow W^{2,p}(M)$ and $L^{p'}(M) \hookrightarrow L^{ q'}(M)$. By Lemma \ref{lemma: Lg is Fredholm} above, we know that $\Lg|_{W^{2,q}(M)}$ has index zero, implying that
    \begin{align*}
        \dim(\Ker(\Lg|_{W^{2,q}(M)})) &\leq \dim(\Ker(\Lg|_{W^{2,p}(M)})) = \dim(\Ker(\Lg^*|_{L^{ p'}(M)}))
        \\
        &\leq \dim(\Ker(\Lg^*|_{L^{q'}(M)})) = \dim(\Ker(\Lg|_{W^{2, q}(M)})) \,
    \end{align*}
    where the index property was used in each of the identities, while the functional inclusions in the corresponding inequalities. We see that equality must hold all the way through. We further claim that $\Ker(\Lg|_{W^{2,q}(M)}) = \Ker(\Lg^*|_{L^{q'}(M)})$. To see this, consider $v \in W^{2,q}(M)$, which is, by Sobolev embeddings, in $L^r(M)$ for each $r \geq 1$. Then, we may apply the adjoint operator $\Lg^* : L^{q'}(M) \to W^{-2, q'}(M)$ to $v$ and implicitly using \cref{SobolevDualIso} evaluate against an arbitrary element $\phi \in W^{2,q}(M)$
    \begin{equation}
        \label{eq: int by parts}
        (\Lg^*v)(\phi) = v(\Lg\phi) = \int_M v \left(-a_n\Delta_g \phi + \R_g \phi\right) d\mu_g \,.
    \end{equation}
    The $W^{2,q}(M)$ regularity on $v$ allows us to integrate by parts through a rather canonical approximation argument and obtain that
    \begin{align}
        \label{ConfLapIntParts}
        \begin{split}
            \int_M v \left(-a_n\Delta_g \phi + \R_g \phi\right) d\mu_g &= \int_M \bigl(a_ng(\nabla v,\nabla \phi) + \R_g v\phi\bigr) d\mu_g
            \\
            & = \int_M \left(-a_n\Delta_g v + \R_gv\right) \phi \, d\mu_g.
        \end{split}
    \end{align}
    One may prove the above identities first for $u,v\in C^{\infty}(M)$ and a rough metric $g\in W^{2,q}(M)$ by considering the corresponding identities along a sequence of smooth metrics $\{g_j\}_{j=1}^{\infty}$ such that $g_{j} \to g$ in $W^{2,q}(T_2M)$. Once this is established for $u,v\in C^{\infty}(M)$ and $g\in W^{2,q}(M)$, the full claim also follows by approximating $u,v\in W^{2,q}(M)$ with sequences of smooth functions in $W^{2,q}(M)$ norm and noticing that each of the integrals converges to the corresponding limit. Now, if $\Lg v = 0$, the identities \eqref{eq: int by parts} and \eqref{ConfLapIntParts} imply that $\Lg^*v = 0$, whence $\mathrm{Ker}(\mathscr{L}_g|_{W^{2,q}(M)})\subset \Ker(\Lg^*|_{L^{q'}(M)})$. As we have proven these two spaces have the same finite dimension, we conclude $\Ker(\Lg|_{W^{2,q}(M)}) = \Ker(\Lg^*|_{L^{q'}(M)})$ and the proof concludes. 
\end{proof}

Next, we prove the main existence result for $\Lg$. 
Again, the conformal nature of the operator becomes apparent, as the positivity of the Yamabe invariant suffices in order to show invertibility.
For general Schrödinger-type operators, purely analytic arguments suggest imposing positivity of the \textit{potential term} for a maximum principle type argument, or at least a smallness condition on its negative part to grant coercitivity --see, for instance \cite{DruetLaurain} or \cite{DruetHebeyRobert}--. 
\begin{theorem}
    \label{lemma: positive yamabe isomorphism _ final}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{k,q}$-Riemannian metric $g$ on $M$ with $k \geq 2$ and $q > \tfrac{n}{2}$. If $\lambda(M, g) > 0$, then the operator 
    \begin{equation*}
        \Lg : W^{k,p}(M) \to W^{k-2, p}(M)
    \end{equation*}
    is an isomorphism for every $1 < p \leq q$ and $k \geq 2$.
\end{theorem}
\begin{proof}
    We first observe that $\Lg : W^{k,p}(M) \to W^{k-2,p}(M)$ is Fredholm of index zero for $1 < p \leq q$ and $k \geq 2$ by \cref{lemma: Lg is Fredholm}, so it suffices to show injectivity. Since $W^{k,p}(M) \hookrightarrow W^{2, p}(M)$ for all $k \geq 2$, it is enough to prove injectivity of $\Lg : W^{2,p}(M) \to L^{p}(M)$ to conclude, and due to \cref{lemma: kernel_improvement}, we are done once we show that $\Ker\bigl(\Lg |_{W^{2,q}(M)}\bigr) = 0$. To do so, suppose $u \in \Ker(\Lg|_{W^{2,q}(M)})$ is non-trivial and thus can be normalized so that $\|u\|_{L^{2^*}(M,d\mu_g)} = 1$. But then,
    \begin{equation*}
        0 = u\Lg u = a_n \int_M |\nabla u|^2 \, d\mu_g + \int_M \R_g u^2 \, d\mu_g = Q_g(u) \,,
    \end{equation*}
    and since $W^{2,q}(M) \hookrightarrow W^{1,2}(M)$ for $q > \tfrac{n}{2}$, it contradicts the positivity of the Yamabe invariant.
\end{proof}
Having the above existence and uniqueness result available, we now examine regularity properties of solutions to $\mathscr{L}_gu=f$.
These results follow from those already established in \cref{SectionLapceOp} for 
the Laplace--Beltrami operator, which can be written as
\begin{equation}
    \label{eq: Conformal to Beltrami Laplacian}
    \Delta_g u = -a_n^{-1} \bigl(\Lg u + \R_g u \bigr)\,.
\end{equation}
Using that $\R_g \in W^{k-2, q}(M)$ together with \cref{thm: Rodri Global W1p W2p regularity} and \cref{thm: main global elliptic regularity}, we establish the main regularity theorem for the conformal Laplacian.
\begin{theorem}
    \label{thm: conf Laplace elliptic regularity}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a  $W^{k,q}$-Riemannian metric $g$ on $M$ with $k \geq 2$ and $q > \tfrac{n}{2}$. 
    \begin{enumerate}
        \item[(i)] For $k = 2$, if $u \in L^{q'}(M)$ and $\Lg u \in L^p(M)$ for some $1 < p \leq q$, then it follows that $u \in W^{2,p}(M)$.
        \item[(ii)] For $k \geq 3$, if $u \in W^{k-2,q'}(M) \cap W^{k-1,p}(M)$ and $\Lg u \in W^{k-2,p}(M)$ for some $1 < p \leq q$, then it follows that $u \in W^{k,p}(M)$.
    \end{enumerate}
\end{theorem}
\begin{proof}
    (\textit{i}) In order to apply the results in \cref{thm: Rodri Global W1p W2p regularity} to the equation \eqref{eq: Conformal to Beltrami Laplacian}, we need to control the regularity of the term $\R_g u$. Notice that for any $\tfrac{1}{p_0} > 1-\tfrac{1}{n}=\tfrac{1}{n'}$ there holds
    \begin{equation*}
        \R_g u \in L^q(M) \otimes L^{q'}(M) \hookrightarrow L^1(M) \hookrightarrow W^{-1, p_0}(M)
    \end{equation*} 
    and since $1-\tfrac{1}{n} < 1 - \tfrac{1}{q} + \tfrac{1}{n}$ due to $q > \tfrac{n}{2}$, we may fix $p_0 > 1$ such that $1 - \tfrac{1}{n} <  \tfrac{1}{p_0} < \tfrac{1}{q'} + \tfrac{1}{n}$. In particular, $p_0$ satisfies the hypotheses of \cref{thm: Rodri Global W1p W2p regularity} part (\textit{i}). On the other hand, since $p_0' > n$, there holds $L^p(M) \hookrightarrow W^{-1,p_0}(M)$ for any $p \geq 1$ and we get that $\Delta_gu \in W^{-1,p_0}(M)$. It follows from \cref{thm: Rodri Global W1p W2p regularity} part (\textit{i}) that $u \in W^{1, p_0}(M)$. Since $p_0 < \tfrac{n}{n-1} < n$ due to $p_0'>n$, \cref{SobolevMultLocal} yields
    \begin{equation*}
        L^q(M) \otimes W^{1, p_0}(M) \hookrightarrow L^{p_1}(M) \quad \text{with} \quad \frac{1}{p_1} \doteq \frac{1}{p_0} + \frac{1}{q} - \frac{1}{n} \,,
    \end{equation*}
    so $\R_g u \in L^{p_1}(M)$. If $p_1 \geq p$, we immediately deduce that $\Delta_g u \in L^p(M)$ and  part $(ii)$ of \cref{thm: Rodri Global W1p W2p regularity} gives the result. Otherwise, it gives $u \in W^{2,p_1}(M)$. Now we claim that if $p_1 \geq \tfrac{n}{2}$ we are done. In fact, for $p_1 > \tfrac{n}{2}$, 
     we can check that $\R_g u \in L^q(M) \otimes W^{2, p_1}(M) \hookrightarrow L^p(M)$ so that $\Delta_g u \in L^p(M)$ and part $(ii)$ of \cref{thm: Rodri Global W1p W2p regularity} allows to conclude. If instead $p_1 = \tfrac{n}{2}$, we are done with one additional step: we use the embedding
     \begin{equation*}
         L^q(M) \otimes W^{2, \frac{n}{2}}(M) \hookrightarrow L^t(M), \qquad \frac{1}{t} \doteq \frac{1}{2q} + \frac{1}{n}
     \end{equation*}
     and it is easy to see that $\tfrac{n}{2} < t < q$. We then conclude since we fall in the previous case.
     On the other hand, if $p_1 < \tfrac{n}{2}$, we consider the embedding
    \begin{equation*}
        L^q(M) \otimes W^{2, p_1}(M) \hookrightarrow L^{p_2}(M)\,, \qquad \frac{1}{p_2} \doteq \frac{1}{p_1} + \frac{1}{q} - \frac{2}{n} \,,
    \end{equation*}
    and if $p_2 \geq \tfrac{n}{2}$, we immediately conclude as before. Otherwise, we get $u \in W^{2, p_2}(M)$ again by part $(ii)$ of \cref{thm: Rodri Global W1p W2p regularity}. We can then iterate the procedure for an increasing sequence of embeddings
    \begin{align*}
        L^q(M) \otimes W^{2, p_i}(M) \hookrightarrow L^{p_{i+1}}(M)\,, \qquad \frac{1}{p_{i+1}} \doteq \frac{1}{p_i} + \frac{1}{q} - \frac{2}{n}
    \end{align*} 
    for $i > 1$, until $p_{i+1} \geq \tfrac{n}{2}$. 

    (\textit{ii}) As before, in order to apply \cref{thm: main global elliptic regularity} to the equation \eqref{eq: Conformal to Beltrami Laplacian}, we need to control the regularity of the term $\R_g u$.
    For $k \geq 3$, provided that $q > \tfrac{n}{2}$, it is easy to check from \cref{SobolevMultLocal} that
    \begin{equation*}
        W^{k-2,q}(M) \otimes W^{k-1,p}(M) \hookrightarrow W^{k-2,p}(M)
    \end{equation*}
    and hence we immediately have that $\Delta_gu \in W^{k-2,p}(M)$. The claim follows from \cref{thm: main global elliptic regularity}.
\end{proof}
A consequence of the previous results is a regularity statement for solutions to all the subcritical equations related to \eqref{eq: sPDE}.
\begin{corollary}
    \label{prop: subcritical regularity}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{k,p}$-Riemannian metric $g$ on $M$ with $k \geq 2$ and $q > \tfrac{n}{2}$. Suppose that $u \in W^{1,2}(M)$ is a non-negative weak solution of
    \begin{equation*}
        \Lg u = \lambda u^{s-1}
    \end{equation*}
    for some $s \in [2, 2^*)$ and $\lambda \in \nR$. Then, $u$ is either identically zero or is a strictly positive $W^{2,q}(M)$ function.
\end{corollary}
\begin{proof}
    We begin by showing that $u \in W^{2,q}(M)$. The Sobolev embedding $W^{1, 2}(M) \hookrightarrow L^{2^*}(M)$ ensures that
    \begin{equation*}
        \Lg u = \lambda u^{s-1} \, \in L^{\frac{2^*}{s-1}}(M) \,.
    \end{equation*}
    The hypothesis $u \in L^{q'}(M)$ of  \cref{thm: conf Laplace elliptic regularity} is satisfied since $L^{2^*}(M) \hookrightarrow L^{q'}(M)$ as $q' \leq 2^*$ or equivalently $q \geq \tfrac{2n}{n+2}$, which is guaranteed by $q > \tfrac{n}{2}$ and $n \geq 3$. If $\tfrac{2^*}{s-1} \geq q$, then $\Lg u \in L^q(M)$ and  the claim follows directly by applying part $(i)$
    of \cref{thm: conf Laplace elliptic regularity}. Otherwise, for $\tfrac{2^*}{s-1} < q$,
    we obtain $u \in W^{2, \frac{2^*}{s-1}}(M)$. Let us then consider the embedding
    \begin{equation*}
        W^{2, \tfrac{2^*}{s-1}}(M) \hookrightarrow L^{r_1}(M) \,.
    \end{equation*}
    If $\tfrac{2^*}{s-1} \geq \frac{n}{2}$ or, equivalently, $s \leq \tfrac{n+2}{n-2}$, then the embedding works in particular for $r_1 = (s-1)q$, so that $\Lg u \in L^q(M)$ and the assertion follows from \cref{thm: conf Laplace elliptic regularity}. If $\tfrac{2^*}{s-1} < \frac{n}{2}$ instead, then the embedding holds for
    $\tfrac{1}{r_1} \doteq \tfrac{s-1}{2^*} - \tfrac{2}{n} \,>\, 0.$
    Observe that
    \begin{equation*}\label{ineq_s_2*}
        \frac{s-1}{2^*}- \frac{2}{n} < \frac{1}{2^*} \, \iff  \, \frac{n-2}{2n} (s-2) < \frac{2}{n}  \, \iff  \, s-2 < \frac{4}{n-2}  \, \iff  \, s < 2^*,
    \end{equation*}
    so it follows that $r_1 > 2^*$. Now, if $\tfrac{r_1}{s-1} \geq q$ we conclude by \cref{thm: conf Laplace elliptic regularity} since $\Lg u \in L^q(M)$. Otherwise,
    $\Lg u \in L^{\tfrac{r_1}{s-1}}(M)$ and \cref{thm: conf Laplace elliptic regularity} implies that $u \in W^{2, \tfrac{r_1}{s-1}}(M)$. As before, the claim follows if $\tfrac{r_1}{s-1} \geq \tfrac{n}{2}$. Otherwise, we iterate the procedure for a sequence 
    \begin{equation*}
        \frac{1}{r_k} \doteq \frac{s-1}{r_{k-1}} - \frac{2}{n}
    \end{equation*}
    until $\tfrac{r_k}{s-1} \geq \tfrac{n}{2}$, which is possible due to the following reasoning. First, by induction we can show that $r_k > 2^*$ for all $k \geq 1$. Since we have already computed $r_1 > 2^*$, let us assume $r_k > 2^*$ so that
     \begin{equation*}
         \frac{1}{r_{k+1}} = \frac{s-1}{r_{k}} - \frac{2}{n} < \frac{s-1}{2^*} - \frac{2}{n} = \frac{1}{r_1} < \frac{1}{2^*}
     \end{equation*}
     and the claim is proven. Consequently, the difference between $r_{k-1}$ and $r_{k}$ is a positive number independent of $k$, as it can be seen from
     \begin{align*}
         \frac{1}{r_{k-1}} - \frac{1}{r_k} &= -\frac{(s-2)}{r_{k-1}} + \frac{2}{n}
         \\
         &\geq -\frac{(s-2)}{2^*} + \frac{2}{n} = \frac{4 - (s-2)(n-2)}{2n} > 0 \,.
     \end{align*} 
     We remark that the strict positivity is ensured exactly because $s < 2^*$. By the reasoning above, we have established that $u \in W^{2,q}(M)$.

     Regarding positivity, Trudinger's Harnack inequality \cite[Theorem 5.2]{TrudingerMeasurableCoef} applies to

     \noindent
     our case and implies that if $u(\p) = 0$ at some $\p \in M$, then $u \equiv 0$ in any open coordinate chart around $\p$. In particular, $u^{-1}(0)$ is open. On the other hand, $u \in W^{2,q}(M)$ and hence continuous, implying that $u^{-1}(0)$ is closed. Therefore, it must be that either $u > 0$ or $u \equiv 0$ on $M$.
\end{proof}

\begin{remark}
    \label{rmk: conformal gauge}
    As explained in \cref{The Yamabe classification}, the Yamabe classification in Corollary \ref{cor: Yamabe classification} follows from the eigenvalue case  $(s = 2)$, which is a special case of \cref{prop: subcritical regularity}. In simple terms, this tells us that each $W^{2,q}$-conformal class contains a metric of continuous (in fact, $W^{2,q}$) scalar curvature. Such a representative could be regarded as a good conformal gauge and it will make the analysis in the following sections considerably simpler.
\end{remark}

