\section{The conformal Green function}
\label{The Conformal Green's function}
Before presenting the main result of this section, let us introduce some definitions and subtleties related to the conformal Green function 
for rough metrics. Recall that if $g \in C^\infty(T_2M)$, then $\mathscr{L}_g$ acts by duality as a map $\mathscr{D}'(M)\to \mathscr{D}'(M)$ and a Green function $G_p \in \mathscr D'(M)$ of $\Lg$ centered at $p \in M$ is a solution to
\begin{equation*}
    \Lg G_p = \delta_p \,,
\end{equation*}
where $\delta_p \in \mathscr D'(M)$ is defined by
\begin{equation}
    \label{eq: delta_p def smooth}
    \delta_p(\phi) = \phi(p) \quad \text{for all } \: \phi \in \mathscr D(M) \,.
\end{equation}
In contrast, if $g$ is not smooth, then $\mathscr{L}_g$ cannot be made to act naturally in this way on all of $\mathscr{D}'(M)$. However, using multiplication properties of \cref{SobolevMultLocal} one gets the following.
\begin{lemma}
    \label{lemma: conf Lap for Lt}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ with $q > \tfrac{n}{2}$. Then, the operator $\Lg : C^\infty(M) \to L^q(M)$ extends by duality to a bounded map
    \begin{equation*}
        \Lg : L^t(M) \to W^{-2,t}(M)
    \end{equation*}
    provided that $t \geq q'$. Moreover, 
    \begin{align}
        \langle \mathscr{L}_gu,\phi \rangle_{(M,g)}=\langle u,\mathscr{L}_g\phi \rangle_{L^2(M,d\mu_g)}
    \end{align}
    holds for any $u \in L^t(M)$ and $\phi \in W^{2,t'}(M)$.
\end{lemma}
\begin{proof}
    The first part of the statement is a special case of \cite[Lemma 2.2]{avalos2024sobolev}. For the self-adjointness, consider sequences of functions $\{u_j\}_{j=1}^{\infty}\subset C^{\infty}(M)$ and metrics $\{g_j\}_{j=1}^\infty \subset C^\infty(T_2M)$ converging $u_j \to u$ in $L^t(M,d\mu_g)$ and $g_j \to g$ in $W^{2,q}(T_2M)$ as $j \to \infty$ and notice that
    \begin{align*}
        \langle \mathscr{L}_gu,\phi \rangle_{(M,g)} &= \lim_{j\to\infty}\langle \mathscr{L}_{g_j}u_j,\phi \rangle_{L^2(M,d\mu_g)} = \lim_{j\to\infty}\langle \mathscr{L}_{g_j}u_j,\phi \rangle_{L^2(M,d\mu_{g_j})} 
        \\
        &= \lim_{j\to\infty}\langle u_j,\mathscr{L}_{g_j}\phi \rangle_{L^2(M,d\mu_{g_j})} = \langle u,\mathscr{L}_g\phi \rangle_{L^2(M,d\mu_g)} \,,
    \end{align*}
    where the last identity is a direct consequence of Hölder's inequality.
\end{proof}
Another observation is that \eqref{eq: delta_p def smooth} makes sense as long as $\phi$ is continuous and consequently, in view of \cref{SobolevDualIso}, we can define the distribution $\delta_p \in W^{-2,t}(M)$ by
\begin{equation}
    \label{eq: delta_p def rough}
    \langle\delta_p, \phi\rangle_{(M,g)} = \phi(p) \quad \text{for all } \: \phi \in W^{2,t'}(M)
\end{equation}
provided that $t' > \tfrac{n}{2}$, or equivalently, $t < \tfrac{n}{n-2}$. Since $q > \tfrac{n}{2}$ is equivalent to $q' < \tfrac{n}{n-2}$, we are lead to
\begin{definition}
    \label{GreenFunctionDefn}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ with $q > \frac{n}{2}$. For $q' \leq t < \tfrac{n}{n-2}$ we say that $G_p\in L^t(M)$ is a Green function for $\Lg$ with a pole at $p \in M$ if it satisfies
    \begin{equation}
        \langle\Lg G_p, \phi\rangle_{(M,g)} = \phi(p)
    \end{equation}
    for all $\phi \in W^{2,t'}(M)$.
\end{definition}
An important direct consequence of \cref{GreenFunctionDefn} and \cref{lemma: conf Lap for Lt}, which mimics the known results for smooth metrics, is the following conformal transformation property for $G_p$.
\begin{proposition}
    \label{prop: conformal Green transformation}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and let $g$ be a $W^{2,q}$-Riemannian metric with $q > \tfrac{n}{2}$. Consider a positive function $u \in W^{2,q}(M)$ and the conformal metric $\tilde g \doteq u^{\frac{4}{n-2}}g$. If $G_p$ is a Green function for $\Lg$ centered at $p \in M$, then
    \begin{equation}
        \label{eq: Green transformation rule}
        \widetilde G_p \doteq u^{-1}(p)u^{-1}G_p
    \end{equation}
    is a Green function for $\mathscr{L}_{\bar g}$ centered at $p$.
\end{proposition}
\begin{proof}
    First, due the hypotheses on $u$ and $q$, we know that $u^{-1}$ is a positive continuous function on $M$, which implies that $\widetilde{G}_{p}\in L^t(M)$. Then, for arbitrary $\phi \in W^{2,t'}(M)$ \cref{lemma: conf Lap for Lt} gives
    \begin{align*}
        \bigl\langle \mathscr L_{\tilde{g}} \widetilde{G}_{p}, \phi \bigr\rangle_{(M, \tilde{g})} &= \int_{M} \widetilde{G}_{p} \, \mathscr L_{\widetilde{g}} \,\phi \,\, d\mu_{\tilde{g}} = u(p)^{-1} \int_M G_{p} \Lg(u \phi) \,\, d\mu_g \\
        &= u(p)^{-1} \bigl\langle \Lg G_{p}, u \phi \bigr\rangle_{(M,g)} 
        = \phi(p) \,,
    \end{align*}
    where we have used that $u \phi\in W^{2,t'}(M)$ due to $t'\leq q$. 
\end{proof}
We can now tackle the main result of the section.
\begin{reptheorem}{theorem C}
    \label{thm: greens existence}
    \emph{
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ with $q > \tfrac{n}{2}$ and $\lambda(M, g) > 0$. Then, for each point $p \in M$, the conformal Laplacian $\Lg$ admits a unique, positive Green function $G_{p} \in W_{loc}^{2, q}\bigl(M\setminus\{p\}\bigr)$ centered at $p$. Moreover, there exists a conformal harmonic chart\footnote{This \textit{conformal harmonic chart} refers to harmonic coordinates of a conformal metric $\tilde{g} \in [\,g\,]_{W^{2,q}}$ chosen so that $\R_{\tilde{g}}$ is continuous and positive. The existence of such metric is ensured by \cref{cor: Yamabe classification}.} $(U,x^i)$ around $p$ such that
    \begin{equation}
        \label{CGF_Expansion}
         G_{p}(x) = \frac{B}{|x|^{n-2}}  + h(x) 
    \end{equation}
    for some $B>0$ and a function $h \in W^{2,r}(U)$ satisfying
   \begin{equation}
        \label{h_decay}
        h(x) = A + \BO\bigl(|x|^{2-\frac{n}{r}}\bigr) \quad \text{as} \quad |x| \to 0
    \end{equation}
    for each $1 \leq r < \tfrac{nq}{q(n-2) + n}$ and some $A \in \nR$. If $q > n$, there additionally holds
    \begin{equation}
        \label{h_decay_qn}
        h(x) = A + \BO_1\bigl(|x|^{2-\frac{n}{r}}\bigr) \quad \text{as} \quad |x| \to 0
    \end{equation}
    for each $1 \leq  r < \tfrac{nq}{q(n-2) + n}$ and harmonic coordinates can be substituted by normal coordinates.}
\end{reptheorem}
\begin{proof}
    First, we claim that due to \cref{prop: conformal Green transformation}, it suffices to show the theorem for some element in the conformal class $[\,g\,]_{W^{2,q}}$. Then, existence, uniqueness, regularity and positivity of any other conformal metric follow directly from the transformation rule \eqref{eq: Green transformation rule} of the Green function under conformal changes. For the expansion near the pole, observe that \cref{cor: reg change harmonic to smooth} implies that if $u \in W^{2,q}(M)$, then also $u(x) \in W^{2,q}(\psi(V))$ in a $g$-harmonic coordinate chart $(V,\psi)$ centered at $p$ with coordinates $\{x^i\}_{i=1}^n$. In particular, $u(x)$ is Hölder continuous and therefore 
    \begin{equation*}
        u(x) = u(0) + O\bigl(|x|^{2-\frac{n}{q}}\bigr) \quad \text{as} \quad |x| \to 0 \,.
    \end{equation*}
    Consequently, using \eqref{eq: Green transformation rule}, \eqref{CGF_Expansion} and \eqref{h_decay} we obtain that the Green function $\widetilde{G}_p$ associated to the conformal metric $\tilde g \doteq u^{\frac{4}{n-2}}$ satisfies
    \begin{align*}
        \widetilde{G}_{0}(x) & = \frac{1}{u(0)} \frac{1}{u(0) + \BO\bigl(|x|^{2- \frac{n}{q}}\bigr)} \left( \frac{B}{|x|^{n-2}} + A + \BO\bigl(|x|^{2-\frac{n}{r}}\bigr)\right) 
        \\
        & = \frac{1}{u(0)^2}  \, \left( \frac{B}{|x|^{n-2}} + A + \BO\bigl(|x|^{2-\frac{n}{r}}\bigr) \right) + \BO\bigl(|x|^{2-\frac{n}{q}}\bigr) + \BO\bigl(|x|^{4-\frac{n}{q} -n}\bigr) + \BO\bigl(|x|^{4-\frac{n}{q} - \frac{n}{r}}\bigr) 
        \\
        & = \frac{1}{u(0)^2}  \, \left(\frac{B}{|x|^{n-2}} + A + \BO\bigl(|x|^{2-\frac{n}{r}}\bigr) \right)
    \end{align*}
    as $|x| \to 0$, where the last identity holds since for all $n \geq 3$,  $q > \tfrac{n}{2}$ and $1 \leq r < \tfrac{nq}{q(n-2) + n}$ we have
    \begin{equation*}
        2 - \frac{n}{r} < 4-\frac{n}{q} - n \leq 4- \frac{n}{q} - \frac{n}{r} \,, \qquad 2 - \frac{n}{r} < 2 - \frac{n}{q} \,.
    \end{equation*}
    If $q > n$, notice that $u$ is furthermore $C^{1,2-\frac{n}{q}}$-regular over the pole in harmonic coordinates and consequently it admits the expansion
    \begin{equation*}
        u(x) = u(0) + \BO_1\bigl(|x|^{2-\frac{n}{q}}\bigr) \quad \text{as} \quad |x| \to 0 \,.
    \end{equation*}
    The same expansion holds in $g$-normal coordinates due to item \textit{(ii)} of \cref{NormalCoordsC1}. In any case, we have that
    \begin{align*}
        \widetilde{G}_{p}(x) & = \frac{1}{u(0)^2}  \, \left(\frac{B}{|x|^{n-2}} + A + \BO_1\bigl(|x|^{2-\frac{n}{r}}\bigr) \right)
    \end{align*}
    and the claim is proven.

    In light of \cref{cor: Yamabe classification}, the above claim allows us to assume that $g$ has positive scalar curvature $\R_g \in W^{2,q}(M)$.


    \textit{Step 1: Existence.} Consider a harmonic coordinate chart $(V,\psi)$ centered at $p$ with coordinates $\{x^i\}_{i=1}^n$, which exists by \cref{prop: Existence and Regularity of harmonic coordinates} and satisfy
    \begin{equation}
        \label{eq: harmonic properties 2}
        \psi(p) = 0 \,, \quad g_{ij}(0) = \delta_{ij} \,, \quad g^{ij}\Gamma^k_{ij} \equiv 0 \,.
    \end{equation}
    Let $U \subset\subset W \subset\subset V$ be smooth neighborhoods of $p$ and consider a cut-off function $\eta\in C^{\infty}_0(W)$ such that $\eta\equiv 1$ in $U$. We define
    \begin{align}
        \label{GreenFunct0}
        u(x) \doteq 
        \begin{dcases}
            b_n\eta(x) |x|^{2-n} &\text{in} \; V
            \\
            0  &\text{in} \; M \setminus V
        \end{dcases}
        ,
    \end{align}
    with $b_n \doteq \frac{1}{4(n-1)|\nS^{n-1}|}$. Since the function $|x|^{2-n}$ is in $L^t$ for all $t < \tfrac{n}{n-2}$ in bounded regions around the origin, it is not hard to check that \cref{cor: reg change harmonic to smooth} then implies that $u \in L^t(M)$ for all $t < \tfrac{n}{n-2}$. As $q' < \tfrac{n}{n-2}$ due to $q > \tfrac{n}{2}$, the function $\Lg u$ is well-defined in regard of \cref{lemma: conf Lap for Lt}. In order to compute $\Lg u$, consider some $\phi \in W^{2,t'}(M)$ and suppose first that $\supp\phi \subset\subset V$. Using \cref{lemma: conf Lap for Lt},
    \begin{align*}
        \langle &\Lg u, \phi\rangle_{(M,g)} = \int_{V}u\Lg\phi \, d\mu_g = \int_{\psi(V)} u(x) (\Lg\phi)(x) \sqrt{\det g(x)} \, dx
        \\
        &
        = -a_n\int_{\psi(V)} u(x) \partial_i\bigl(\sqrt{\det g(x)}g^{ij}(x)\partial_j\phi(x)\bigr) dx + \int_{\psi(V)} u(x) \R_g(x)\phi(x) \sqrt{\det g(x)} \, dx
        \\
        &
        = \Bigl\langle u(x), -a_n\sqrt{\det g(x)}\,\Delta_{g(x)}\phi(x) + \R_g(x)\phi(x) \sqrt{\det g(x)}\Bigr\rangle_{\psi(V)}
        \\
        &
        = \Bigl\langle\mathscr L_{g(x)} u(x), \sqrt{\det g(x)} \phi(x)\Bigr\rangle_{\psi(V)} \,,
    \end{align*}
    where $\langle\cdot,\cdot\rangle_\Omega :W^{-k,p'}(\Omega) \times W^{k,p}_0(\Omega) \to \nR$ for $\Omega\subset\nR^n$ stands for the standard duality pairing. It should be mentioned that in the second equality one would, by definition, write the integral in a smooth chart of $M$. Since harmonic coordinates are $W^{3,q}$-compatible with the smooth differentiable structure of $M$, however, the change to harmonic coordinates is justified. For general $\phi \in W^{2,t'}(M)$, we may consider a smooth partition of unity $\{\chi_\alpha\}_{\alpha=1}^N$ such that $\chi_1 \equiv 1$ on $W$ and $\supp\chi_1 \subset\subset V$. Then, since $\supp u \cap \supp\chi_\alpha$ is empty for all $\alpha \neq 1$,
    \begin{align}
        \label{eq: eq: Lg dual local action}
        \langle\Lg u, \phi\rangle_{(M,g)} &= \sum_{\alpha=1}^N \langle\Lg u, \chi_\alpha\phi\rangle_{(M,g)} = \langle\Lg u, \chi_1\phi\rangle_{(M,g)} + \sum_{\alpha=2}^N \int_M u \Lg(\chi_\alpha\phi) d\mu_g \nonumber
        \\
        &= \Bigl\langle\mathscr L_{g(x)} u(x), \sqrt{\det g(x)} \,\chi_1(x)\phi(x)\Bigr\rangle_{\psi(V)} \,.
    \end{align}
    Now, using the properties \eqref{eq: harmonic properties 2} of harmonic coordinates (and simplifying notation), we formally compute
    \begin{align*}
        \Delta_g\bigl(\eta|x|^{2-n}\bigr) &= g^{ij}\,\partial_i\partial_j\bigl(\eta|x|^{2-n}\bigr) 
        \\
        & = \eta \, g^{ij} \partial_i \partial_j |x|^{2-n} +  g^{ij} \partial_i \partial_j\eta \, |x|^{2-n} + 2 g^{ij} \partial_i \eta \, \partial_j |x|^{2-n}
        \\
        & = \eta \Delta |x|^{2-n} + \eta \, \bigl(g^{ij} - \delta^{ij}\bigr)  \partial_i \partial_j |x|^{2-n} +  g^{ij} \Big( \partial_i \partial_j\eta \, |x|^{2-n} + 2 \partial_i \eta \, \partial_j |x|^{2-n} \Big) \,.
    \end{align*}
    Since the last two terms involve derivatives of $\eta$, which are supported away from $\psi(U)$, we have that
    \begin{equation*}
        f_1 \doteq g^{ij} \Big( \partial_i \partial_j\eta \, |x|^{2-n} + 2 \partial_i \eta \, \partial_j |x|^{2-n} \Big) \in W^{2,q}(\psi(V)) \subset C^{0, 2 - \frac{n}{q}}(\psi(V)) \,.
    \end{equation*}
    Here we are using that $g_{ij}(x) \in W^{2,q}(\psi(V))$ by \cref{cor: reg change harmonic to smooth}. On the other hand, a simple computation gives
    \begin{align*}
        \partial_{i}\partial_j|x|^{2-n} = (2-n)\left(\frac{\delta_{ij}}{|x|^n} - n \frac{x^ix^j}{|x|^{n+2}} \right) = \BO(|x|^{-n}) \quad \text{as} \quad |x| \to 0 \,,
    \end{align*}
    while the Hölder continuity of the metric components, together with \eqref{eq: harmonic properties 2}, implies
    \begin{equation*}
        g^{ij}-\delta^{ij} = \BO\bigl(|x|^{2-\frac{n}{q}}\bigr) \quad \text{as} \quad |x| \to 0 \,.
    \end{equation*}
    It follows that
    \begin{equation*}
        f_2 \doteq \eta \, (g^{ij} - \delta^{ij})  \partial_i \partial_j |x|^{2-n} = \BO(|x|^{-\gamma}) \quad \text{as} \quad |x| \to 0
    \end{equation*}
    for $\gamma \doteq n + \tfrac{n}{q} - 2$. Finally, we use that $\R_g \in W^{2,q}(M)$ in our good conformal gauge

    \noindent and, by \cref{cor: reg change harmonic to smooth}, $\R_g$ is continuous in harmonic coordinates too, implying that
    \begin{equation*}
        f_3 \doteq \R_g \eta \, |x|^{2-n} = \BO\bigl(|x|^{2-n}\bigr) \quad \text{as} \quad |x| \to 0 \,.
    \end{equation*}
    Combining the above, we obtain
    \begin{equation*}
        \begin{split}
            \Lg\bigl(\eta \, |x|^{2-n}\bigr) &= -a_n \Delta_g \bigl(\eta \, |x|^{2-n}\bigr) + \R_g \eta \, |x|^{2-n}
            \\
            & = -a_n \eta\Delta\bigl(|x|^{2-n}\bigr) - a_n \, f_1(x) - a_n \, f_2(x) + f_3(x) 
            \\
            &\doteq -a_n \eta\Delta\bigl(|x|^{2-n}\bigr) + f(x) \,,
        \end{split}
    \end{equation*}
    with $f(x) = \BO(|x|^{-\gamma})$ as $|x| \to 0$.\footnote{If one works with normal coordinates in the $q > n$ case, an extra $g^{ij}\Gamma^k_{ij}\partial_k\bigl(\eta |x|^{2-n}\bigr)$ term shows up in the definition of $f$. However, since $\Gamma^k_{ij} \in W^{1,q}(V) \subset C^{0,1-\frac{n}{q}}$ with $\Gamma^k_{ij}(0) = 0$, it follows that $\eta g^{ij}\Gamma^k_{ij}\partial_k|x|^{2-n} = \BO\bigl(|x|^{1-\frac{n}{q}}\bigr)\BO\bigl(|x|^{1-n}\bigr) = \BO\bigl(|x|^{-\gamma}\bigr)$ and the qualitative behavior of $f$ is unaffected.} Observe that $|x|^{-\gamma} \in L^r_{loc}(\mathbb{R}^n)$ as long as $n - \gamma r > 0$, or equivalently, 
    \begin{equation*}
        r < \frac{n}{\gamma} = \frac{nq}{q(n-2) + n} \,,
    \end{equation*}
    so there holds that $f(x)  \in L^r(\psi(V))$ for all $r < \tfrac{nq}{q(n-2) + n}$. We remark that $\frac{nq}{q(n-2) + n} > 1$ is guaranteed by $q > \tfrac{n}{2}$. From \cref{cor: reg change harmonic to smooth} we also get that $f \in L^r(V)$, which we extend by zero to the whole manifold and still call it $f$. In light of \eqref{eq: eq: Lg dual local action}, we establish that for any $\phi \in W^{2,t'}(M)$ with $t < \tfrac{n}{n-2}$ there holds
    \begin{align*}
        \langle \Lg u, \phi\rangle_{(M,g)} &= \Bigl\langle-a_n \eta\Delta\bigl(|x|^{2-n}\bigr) + f(x), \sqrt{\det g(x)}\,\chi_1(x) \phi(x)\Bigr\rangle_{\psi(V)}
        \\
        &= \frac{-1}{(n-2)|\nS^{n-1}|}\int_{\psi(V)}|x|^{2-n} \Delta\Bigl(\eta(x) \chi_1(x) \phi(x) \sqrt{\det g(x)}\Bigr) dx 
        \\
        &\hspace{3cm} + b_n\int_{\psi(V)} f(x)\chi_1(x)\phi(x) d\mu_g(x)
        \\
        &= \phi(p) + b_n\int_M f \phi \,d\mu_g \,.
    \end{align*}
    Since $f \in L^r(M)$ for all $r < \tfrac{nq}{q(n-2) + n} \leq q$, we may apply \cref{lemma: positive yamabe isomorphism _ final} to obtain a unique solution $h \in W^{2,r}(M)$ to the equation $\Lg h = -b_n f$. We claim that
    \begin{equation}
        \label{eq: global Gp}
        G_{p} \doteq u + h 
    \end{equation}
    is a Green function of $\Lg$ with pole $p$. If $r$ can be chosen greater or equal than $\tfrac{n}{2}$, then $h \in L^t(M)$ for all $t<\infty$ and consequently $G_p \in L^t(M)$ for all $t < \tfrac{n}{n-2}$. If $r<\frac{n}{2}$ one has $W^{2,r}(M)\hookrightarrow L^s(M)$ for all $s$ such that 
    \begin{align*}
        \frac{1}{s} = \frac{1}{r}-\frac{2}{n}>\frac{n-2}{n}+\frac{1}{q} - \frac{2}{n}=1 + \frac{1}{q}-\frac{4}{n}.
    \end{align*}  
    That is, $h \in L^s(M)$ for some $q'\leq s$ if and only if
    \begin{align*}
        \frac{1}{q'}=1-\frac{1}{q}>1 + \frac{1}{q}-\frac{4}{n}\Longleftrightarrow \frac{2}{n}>\frac{1}{q},
    \end{align*}
    which is satisfied by hypothesis. We conclude that $G_p\in L^t(M)$ for some $q'\leq t< \frac{n}{n-2}$. Moreover, for all $\phi \in W^{2,t'}(M)$ there holds
    \begin{align*}
        \langle \Lg G_p, \phi\rangle_{(M,g)} &= \langle \Lg u, \phi\rangle_{(M,g)} + \langle \Lg h, \phi\rangle_{(M,g)}
        \\
        &= \phi(p) + b_n \int_M f \phi \, d\mu_g - b_n\langle f, \phi\rangle_{(M,g)} = \phi(p) 
    \end{align*}
    as desired.

    \medskip
    \textit{Step 2: Uniqueness.} Suppose now there exists another Green function $\widetilde G_p \in L^t(M)$, $t \geq q'$, and let $H = G_p - \widetilde G_p$. Then, by definition,
    \begin{align*}
        \bigl\langle\Lg H, \phi\bigr\rangle_{(M,g)} = \bigl\langle\Lg G_p, \phi\bigr\rangle_{(M,g)} - \bigl\langle\Lg \widetilde G_p, \phi\bigr\rangle_{(M,g)} = 0
    \end{align*}
    holds for all $\phi \in W^{2,t'}(M)$ and \cref{SobolevDualIso} implies that $\Lg H = 0$. Since $H \in L^{q'}(M)$ in particular, \cref{thm: conf Laplace elliptic regularity} implies that $H \in W^{2,q}(M)$, but in view of the hypothesis $\lambda(M,g) > 0$ \cref{lemma: positive yamabe isomorphism _ final} implies that $H = 0$. Hence $G_p = \widetilde G_p$.

    \medskip
    \textit{Step 3: Regularity.} Let us now study the regularity of $G_{p}$ away from the singular point. By the definition \eqref{GreenFunct0}, we know that $u$ is smooth away from $p$ in harmonic coordinates, so \cref{cor: reg change harmonic to smooth} implies that $u \in W^{3,q}(M \setminus B_{\varepsilon}(p))$  for any $\varepsilon > 0$. Fix some small $\varepsilon > 0$ and consider a smooth cut-off function $\xi$ supported in $M\setminus B_{\varepsilon}(p)$ and $\xi \equiv 1$ on $M\setminus B_{2\varepsilon}(p)$. Then,  $\xi G_{p} \in W^{2,r}(M)$ due to the regularity of $h$ and it satisfies
    \begin{align*}
        \Lg \bigl(\xi \, G_{p} \bigr) &= -a_n \Delta_g \bigl(\xi \, G_{p}\bigr) + \R_g \xi \, G_{\p} 
        \\
        & = - \xi \Lg G_{p} - 2a_n \,g(\nabla \xi, \nabla G_{p}) - a_n \,\Delta_g \xi \,G_{p} + \R_g \xi \, G_{p} 
        \\
        & =  -2a_n \,g(\nabla \xi, \nabla G_{p}) - a_n \, \Delta_g\xi \,G_{p} + \R_g \xi \, G_{p} 
    \end{align*}
    From our analysis above, we know that $W^{2, r}(M) \hookrightarrow L^{q'}(M)$ and thus $\xi G_{\p} \in L^{q'}(M)$. In addition, since $r < \tfrac{nq}{q(n-2)+n} < n$, we may use the embedding
    \begin{equation*}
        \xi G_{\p} \in W^{2, r}(M) \hookrightarrow W^{1,r_1}(M) \qquad \text{with} \qquad \frac{1}{r_1} \doteq \frac{1}{r} - \frac{1}{n} \,,
    \end{equation*}
    to get that  $g(\nabla \xi, \nabla G_{p}) \in L^{r_1}(M)$ and consequently $\Lg\bigl(\xi\,G_{p}\bigr) \in L^{r_1}(M)$ (recall that $\R_g \in W^{2,q}(M)$). If $r_1 \geq q$ \cref{thm: conf Laplace elliptic regularity} immediately implies that $\xi G_{p} \in W^{2,q}(M)$. If not, it allows us to conclude that  $\xi G_{p} \in W^{2,r_1}(M)$. If $r_1 \geq \tfrac{qn}{q+n}$, then $W^{2,r_1}(M) \hookrightarrow W^{1,q}(M)$ and we are done by the same reasoning. If $r_1 \leq \tfrac{qn}{q+n} < q$, we have that
    \begin{equation*}
        \xi G_{p} \in W^{2,r_1}(M) \hookrightarrow W^{1,r_2}(M) \qquad \text{with} \qquad \frac{1}{r_2} \doteq \frac{1}{r_1} - \frac{1}{n}
    \end{equation*}
    and we can repeat the reasoning. In fact, we can iterate the argument considering for each integer $k \geq 1$ the Sobolev embeddings
    \begin{equation*}
        W^{1, r_k}(M) \hookrightarrow L^{r_{k+1}}(M) \qquad \text{with} \qquad \frac{1}{r_{k+1}} \doteq \frac{1}{r_k} - \frac{1}{n}
    \end{equation*} 
    and using \cref{thm: conf Laplace elliptic regularity} to conclude that $\xi G_{p} \in W^{2, r_{k+1}}(M)$. Since $\tfrac{1}{r_{k}} - \tfrac{1}{r_{k+1}} = \tfrac{1}{n}$, it follows that $r_k$ reaches $q$ in finitely many steps, showing that $\xi G_{p} \in W^{2,q}(M)$. As $\varepsilon > 0$ was arbitrary, we establish that $G_{p} \in W^{2,q}_{loc}\bigl(M\setminus\{p\}\bigr)$.

    \medskip
    \textit{Step 4: Positivity and expansion.} We claim that the positivity of $G_{p}$ follows from the expansion \eqref{h_decay} of $h$. In fact, in view of \eqref{eq: global Gp}, if $h$ blows up strictly slower than $|x|^{2-n}$ in the harmonic coordinates $\{ x^i\}_{i=1}^n$, then there is some $\varepsilon > 0$ small enough such that $G_{p} > 1$ on $\overline{B_\varepsilon(p) }\setminus \{p\}$. Suppose by contradiction that there is some $\q \in M \setminus \overline{B_\varepsilon(p) }$ such that 
    \begin{equation*}
        \inf_{M \setminus B_\varepsilon(p)} G_{p} = G_{p}(\q) \doteq \m \leq 0 \,.
    \end{equation*}
    Then, on any coordinate chart $(W, y^i)$ around $\q$ with $W \cap B_\varepsilon(p) = \emptyset$ there holds
    \begin{equation*}
        \sqrt{\det g} \, \Lg G_{p} = -a_n\partial_{i}\Big(\sqrt{\det g}\, g^{ij}\partial_{j}G_{p}\Big) + \sqrt{\det g}\R_g G_{p} = 0
    \end{equation*}
    with $\R_g > 0$ by hypothesis, so the strong maximum principle \cite[Theorem 8.19]{GT} implies that $G_{p} \equiv \m \leq 0$ on $W$. This shows that $G_{p}^{-1}(\m)$ is open in $M\backslash\overline{B_\varepsilon(p)}$. On the other hand, it is also closed due to the continuity of $G_{p}$ and therefore equal to $M \setminus\overline{B_\varepsilon(p) }$. However, this contradicts $G_{p}|_{\partial B_\varepsilon(p)} > 1$ and it follows that $G_{p}$ is positive provided that \eqref{h_decay} holds.

    Let us concentrate on the expansion \eqref{h_decay} of $h$ in harmonic coordinates. From \emph{Step 1} and \emph{Step 3} we know that $h \in W^{2,q}_{loc}\bigl(M\setminus\{\p\}\bigr) \cap W^{2,r}(M)$ satisfies
    \begin{equation*}
        \Lg h = -b_nf
    \end{equation*}
    on $M$ and in light of \cref{cor: reg change harmonic to smooth} and \eqref{eq: harmonic properties 2}, $h(x) \in W^{2,q}_{loc}\bigl(\psi(V)\setminus\{0\}\bigr) \cap W^{2,r}_{loc}(\psi(V))$ satisfies
    \begin{equation}
        \label{eq: PDE h locally}
        -a_n g^{ij}(x)\partial_{i}\partial_{j} h(x) + \R_g(x) h(x) = -b_nf(x)
    \end{equation}
    in the harmonic chart $(V,\psi)$. The principal part coefficients $g^{ij}(x)$ as well as the scalar curvature $\R_g(x)$ are in $W^{2,q}_{loc}(\psi(V))$ by the same reasoning as in \emph{Step 1}. Moreover, we also know that $f  = \BO\bigl(|x|^{-\gamma}\bigr)$ with $\gamma = n + \frac{n}{q} - 2$, so the hypotheses of \cref{prop: blow-up behaviour} below are full-filled. Notice that if we prove that the expansion \eqref{h_decay} hold for a sufficiently large $r < \tfrac{nq}{n + (n-2)q}$, then it holds, in particular, for any smaller $r$.

    If $\tfrac{n}{2} < \tfrac{nq}{n + (n-2)q}$, then $h(x) \in C^{0,2-\frac{n}{r}}(\psi(U))$ for all $ \tfrac{n}{2} < r < \tfrac{nq}{n + (n-2)q}$ and thus it reads
    \begin{equation*}
        h(x) = h(0) + \BO\bigl(|x|^{2-\frac{n}{r}}\bigr) \quad \text{as} \quad |x| \to 0 \,.
    \end{equation*}
    In particular, $h$ is bounded in $U$ and the positivity of $G_{p}$ follows. Additionally, since
    \begin{equation*}
        \gamma \leq \frac{n}{r}  \quad \iff \quad r \leq \frac{nq}{n+(n-2)q} \,,
    \end{equation*}
    item $(ii)$ in \cref{prop: blow-up behaviour} with $\beta = 2 - \tfrac{n}{r}$ implies the first order decay
    \begin{equation*}
        h(x) = h(0) + \BO_1\bigl(|x|^{2-\frac{n}{r}}\bigr) \quad \text{as} \quad |x| \to 0
    \end{equation*}
    whenever $q > n$. 

    If $\tfrac{n}{2} \geq \tfrac{nq}{n+(n-2)q} > r$, the function $h$ need not be bounded in $U$ and we need to work with part $(i)$ of \cref{prop: blow-up behaviour}.
    We can consider the optimal Sobolev embedding $W^{2,r}(U) \hookrightarrow L^{\frac{rn}{n-2r}}(U)$ and notice that $r$ can be chosen so that  $\tfrac{2q}{2q - 1} < \tfrac{rn}{n-2r}$ as in the hypothesis of \cref{prop: blow-up behaviour}. In fact, combining this with the upper bound on $r$, it is equivalent to require $1-\tfrac{1}{2q} > \tfrac{1}{r} - \tfrac{2}{n} > 1 + \tfrac{1}{q} - \tfrac{4}{n}$ and we can check that $\tfrac{1}{2q} < \tfrac{4}{n} - \tfrac{1}{q}$ is
    ensured by $q > \tfrac{n}{2}$.
     The second condition of item $(i)$ in \cref{prop: blow-up behaviour} follows directly from
    \begin{align*}
        \frac{n}{r} - 2 > n + \frac{n}{q} - 4 = \gamma - 2 \,.
    \end{align*}
    At this point, the claim is implied by part $(i)$ of \cref{prop: blow-up behaviour}.
\end{proof} 

\subsection{Blow-up analysis}
\label{Blow-up analysis}
In the remainder of the section, we show a \emph{quantitative removable singularity} result for linear elliptic equations with rough coefficients, which is key in the last step of the proof of the previous \cref{theorem C}. The statement is rather general and it applies to a large family of linear elliptic operators: given a smooth, 
bounded domain $\Omega \subset \nR^n$ around the origin, we consider a linear operator
\begin{equation}
    \label{eq: Linear Elliptic Operator}
    \LL \doteq a^{ij}(x) \partial_{i} \partial_{j}  + b^i (x) \partial_{i} + c(x) \,,
\end{equation}
where the coefficients $a^{ij} \in W^{2,q}(\Omega)$ and $b^i, c \in L^{\infty}(\Omega)$ with $q > \tfrac{n}{2}$ satisfy
\begin{align}
    \label{coeff conditions 1}
    \inf_{\Omega} a^{ij}\xi_i \xi_j \geq \lambda |\xi|^2 & \qquad \text{for all} \; \xi \in \nR^n \,, 
    \\
    \label{coeff conditions 2}
    \|a^{ij}\|_{C^{0,2 - \frac{n}{q}}(\Omega)} \,, 
    \quad
    \sum_{k = 1}^n \|\partial_{k} a^{ij}\|_{L^{2q}(\Omega)} & \,, \quad
    \sup_{\Omega}|b^i|\,, \quad \sup_{\Omega} |c| \; \leq \; \Lambda 
\end{align}
for some positive constants $\lambda$ and $\Lambda$. Notice that the above norms are well defined due to the Sobolev embeddings $W^{2, q}(\Omega) \hookrightarrow C^{0, 2 - \frac{n}{q}}(\Omega)$ and $W^{1, q}(\Omega) \hookrightarrow L^{2q}(\Omega)$; the latter is clear if $q \geq n$, while it is ensured for $q < n$  by the inequality $2q < \tfrac{nq}{n-q}$ for $q > \tfrac{n}{2}$.

\begin{theorem}
    \label{prop: blow-up behaviour}
    Let $\Omega \subset \nR^n$ be a smooth, bounded domain around the origin and let $\LL$ be an operator of the form of \eqref{eq: Linear Elliptic Operator} with coefficients satisfying \eqref{coeff conditions 1} and \eqref{coeff conditions 2}.  Let $u \in W^{2,q}_{loc}\bigl(\Omega \setminus \{0\}\bigr)$ be a solution of $\LL u = f$ in $\Omega$ with $f \in L^q(\Omega)$ and suppose that $f = \BO(|x|^{-\gamma})$ as $|x| \to 0$ for some $\gamma \geq 0$. 
    \begin{enumerate}
        \item[(i)] If $u \in  L^p(\Omega)$ for
        $p > \tfrac{2q}{2q-1}$
        and $\gamma \leq 2 + \tfrac{n}{p}$, then
        \begin{equation*}
            u = \BO\bigl(|x|^{-\frac{n}{p}}\bigr) \quad \text{as} \quad |x| \to 0 \,.
        \end{equation*}
        Moreover, if $q > n$, then
        \begin{equation*}
            u = \BO_1\bigl(|x|^{-\frac{n}{p}}\bigr) \quad \text{as} \quad |x| \to 0 \,.
        \end{equation*}
        \item[(ii)] If $u \in C^{0,\beta}(\Omega)$ for $0 < \beta < 1$, $\gamma \leq 2 - \beta$ and $q > n$, then
        \begin{equation*}
            u = u(0) + \BO_1\bigl(|x|^\beta\bigr) \quad \text{as} \quad |x| \to 0 \,.
        \end{equation*}
    \end{enumerate}
\end{theorem}
In order to prove \cref{prop: blow-up behaviour}, we first need the following two technical lemmas. The first one is an adaptation of \cite[Lemma 3.2]{avalos2024sobolev} to our context, where the dependence of the constant appearing in the elliptic estimate is carefully tracked down.
\begin{lemma}
    \label{lemma: Avalos 3.2 adaptation}
    Let $\Omega \subset \nR^n$ be a smooth, bounded domain around the origin and $\LL$ be an operator of the form of \eqref{eq: Linear Elliptic Operator} with coefficients satisfying \eqref{coeff conditions 1} and \eqref{coeff conditions 2}. For every smooth bounded domains $\Omega'' \subset \subset \Omega' \subset \subset \Omega$ and $1 < p < \infty$ satisfying $\tfrac{1}{q} - \tfrac{1}{n} \leq \tfrac{1}{p} < \tfrac{1}{q'} + \tfrac{1}{2q}$,\footnote{
    The upper bound $\tfrac{1}{p} < \tfrac{1}{q'} + \tfrac{1}{2q}$ is strictly below the usual 
    bound $\tfrac{1}{q'} + \tfrac{1}{n}$. 
    It is equivalent to $\tfrac{1}{2q} < \tfrac{1}{p'}$ and allows ensuring that the constant $C$ will depend, among others, on $\| \partial_k a^{ij}\|_{L^{2q}}$. This bound is not restrictive for our application to the Green function expansion in \cref{theorem C}.
    Dealing with 
    $\tfrac{1}{p'} \leq \tfrac{1}{2q}$ is possible, but 
    requires control over a different norm and hence to distinguish the two cases. } there exists a constant $C = C(n, p, q, \lambda, \Lambda, \Omega', \Omega'') > 0$ such that
    \[\|u\|_{W^{1, p}(\Omega'')} \leq C \left(\| \LL u \|_{W^{-1, p}(\Omega')} + \| u \|_{L^p(\Omega')}\right)
    \]
    holds for all $u \in W^{1, p}(\Omega)$.
\end{lemma}

\begin{proof} 
  The proof consists of two steps:

    \textit{Step 1.}
    We first assume that $u$ is compactly supported in some small ball $B_r(x_0) \subset \subset \Omega'$ centered at $x_0 \in \Omega''$. Since the estimate holds for constant coefficients operators (see e.g. \cite[Lemma 2.19]{MaxHolTso2}), we freeze the coefficients at $x_0$ to obtain
    \begin{align*}
        \|u\|_{W^{1, p}(\Omega')} & \leq C_{0} \Big(\|a^{ij}(x_0)\partial_i\partial_j u\|_{W^{-1, p}(\Omega')} + \|u\|_{L^p(\Omega')}\Big) 
        \\
        & \leq C_{0} \, \Big(\|\LL u\|_{W^{-1, p}(\Omega')} +  \|u\|_{L^p(\Omega')}  
        \\
        & + \|(a^{ij} - a^{ij}(x_0)) \,\partial_i \partial_j u\|_{W^{-1, p}(\Omega')} +\|b^k \,\partial_k u\|_{W^{-1, p}(\Omega'))} + \|c\, u\|_{W^{-1, p}(\Omega'))} \Big) \,.
    \end{align*}
    The constant $C_0$ depends only on the principal symbol of the frozen coefficient operator, which is controlled by the ellipticity constant $\lambda$ and $\Lambda$; in particular,  it is independent of $r$. Being $u$ supported in a small ball will allow us to estimate the error terms as follows: consider a test function $\phi \in W_0^{1, p'}(\Omega')$ and observe that 
    \begin{align*}
        (a^{ij} - a^{ij}(x_0)) \, \phi \in W^{2, q} (\Omega) \otimes W^{1, p'}_0 (\Omega') \hookrightarrow  W^{1, p'}_0 (\Omega')
    \end{align*}
    as $\tfrac{1}{p} \leq \tfrac{1}{q'} + \tfrac{1}{n}$. Hence, we can estimate
    \begin{align}
        \label{eq: term1}
        \big|\langle (a^{ij} - a^{ij}(x_0))   \,\partial_i \partial_j u, \,\phi \rangle \big| & = \left|\langle \partial_i \partial_j u, \, (a^{ij} - a^{ij}(x_0)) \, \phi \rangle \right| 
        \nonumber
        \\
        & = \left|\bigl\langle \partial_j u, \, \partial_i \bigl(( a^{ij} - a^{ij}(x_0)) \, \phi\bigr) \bigr\rangle \right| 
        \nonumber
        \\
        &\leq \int_{\Omega'} |\partial_j u \, \partial_i a^{ij} \, \phi| \, +  \int_{\Omega'} | a^{ij} - a^{ij}(x_0)| \, |\partial_j u \, \partial_i\phi| 
        \nonumber
        \\
        & = \int_{B_r(x_0)} |\partial_j u \, \partial_i a^{ij} \, \phi| \, +  \int_{B_r(x_0)} | a^{ij} - a^{ij}(x_0)| \, |\partial_j u \, \partial_i\phi| \,.
    \end{align}
    To get a bound on the first term, fix some $s$ such that
    \begin{equation}
        \label{eq: s range}
        \max\left\{\frac{1}{p'} - \frac{1}{n}, \; 0\right\} < \frac{1}{s} < \frac{1}{p'} - \frac{1}{2q}
    \end{equation}
    and observe that $W^{1,p'}_{loc}(\Omega') \hookrightarrow L^s(\Omega)$ always holds. Notice that such $s$ can always be chosen due to $q > \tfrac{n}{2}$ and $\tfrac{1}{p} < \tfrac{1}{q'} + \tfrac{1}{2q} = 1 - \tfrac{1}{2q}$. Then, defining $\tfrac{1}{l} \doteq \tfrac{1}{p'} - \tfrac{1}{2q} - \tfrac{1}{s}$, we notice that $1 < l < \infty$ and we may estimate
    \begin{align*}
        \nonumber
        \int_{B_{r}(x_0)} |\partial_j u \, \partial_i a^{ij} \,\phi| &\leq \|\partial_j u\|_{L^p(B_{r}(x_0))} \, \|\partial_i a^{ij} \, \phi \|_{L^{p'}(B_{r}(x_0))} 
        \\ 
        \nonumber
        & \leq \|\partial_j u\|_{L^p(\Omega')} \,|B_r|^{\frac{1}{l}}\, \|\partial_i a^{ij}\|_{L^{2q}(B_{r}(x_0))} \, \|\phi\|_{L^{s}(\Omega')} 
        \\
        &\leq C(n, p, q, \Omega') \, \Lambda \, r^{\frac{n}{l}}\, \|u\|_{W^{1,p}(\Omega')} \, \|\phi\|_{W^{1,p'}(\Omega')}  \,.
     \end{align*}
     On the other hand, 
     the second term of \eqref{eq: term1}  can be estimated by 
     using the Hölder continuity of $a^{ij}$ as 
     \begin{align*}
         \int_{B_{r}(x_0)} | a^{ij} - a^{ij}(x_0)| \,|\partial_j u \, \partial_i\phi| &\leq \sup_{x \in B_r\setminus\{x_0\}}\frac{\bigl|a^{ij}(x) - a^{ij}(x_0)\bigr|}{|x-x_0|^{2 - \frac{n}{q}}} \, r^{2-\frac{n}{q}} \int_{B_{r}(x_0)} |\partial_j u \, \partial_i\phi|
         \\
         & \leq \Lambda  \, r^{2-\frac{n}{q}} \,\|\partial_j u\|_{L^p(B_{r}(x_0))} \,\|\partial_i \phi\|_{L^{p'}(B_{r}(x_0))} 
         \\
         & \leq \Lambda  \, r^{2-\frac{n}{q}} \,\|u\|_{W^{1, p}(\Omega')} \,\|\phi\|_{W^{1, p'}(\Omega')} \,.
     \end{align*}
     Similarly, one can estimate the lower-order error terms: with the same $s$ as before, satisfying \eqref{eq: s range}, we get
     \begin{align*}
         \left|\langle b^i \partial_i u, \, \phi \rangle \right| & = \int_{B_{r}(x_0)} |b^i \, \partial_i u \, \phi| \leq \sup_{\Omega} |b^i| \int_{B_{r}(x_0)} |\partial_i u \, \phi| 
         \\
         &\leq \Lambda \,|B_r|^{\frac{1}{p'}-\frac{1}{s}} \,\|\partial u\|_{L^p(B_r(x_0))} \|\phi\|_{L^s(B_r(x_0))} 
         \\
         & \leq C(n, p, q, \Lambda,\Omega') \,  r^{\frac{n}{p'} - \frac{n}{s}} \, \|u\|_{W^{1,p}(\Omega')} \, \| \phi \|_{W^{1, p'}(\Omega')} 
     \end{align*}
     as well as
     \begin{align*}
         \left|\langle c \, u, \, \phi \rangle \right| & = \int_{B_{r}(x_0)} |c \, u \, \phi| \leq \sup_{\Omega}|c| \int_{B_r} |u \, \phi|
         \\
         & \leq \Lambda \, |B_r|^{\frac{1}{p'}-\frac{1}{s}} \, \|u\|_{L^{p}(B_{r}(x_0))} \, \| \phi \|_{L^{s}(B_{r}(x_0))} 
         \\
         & \leq C(n, p, q, \Lambda, \Omega') \, r^{\frac{n}{p'} - \frac{n}{s}} \, \|u\|_{W^{1, p}(\Omega')} \, \| \phi \|_{W^{1, p'}(\Omega')} \,.
     \end{align*}
     Combining the estimates on all the error terms and assuming without loss of generality that $r < 1$, we obtain that
     \begin{equation*}
         \|u\|_{W^{1,p}(\Omega')} \leq C_0 \Big(\|\LL u\|_{W^{-1,p}(\Omega')} + \|u\|_{L^p(\Omega')}\Big) + C(n, p, q, \Lambda, \Omega') \, r^\sigma \, \|u\|_{W^{1,p}(\Omega')} \,,
     \end{equation*}
     where
     \begin{equation*}
         \sigma \doteq \min \left\{2-\frac{n}{q}, \frac{n}{l}, \frac{n}{p'} - \frac{n}{s}\right\} > 0 \,.
     \end{equation*}
     Thereby, taking $r > 0$ small enough depending on $n$, $p$, $q$, $\Lambda$ and $\Omega'$, the error term can be absorbed in the left-hand-side, yielding the estimate
    \begin{equation}\label{eq: localized_estimate}
        \|u\|_{W^{1,p}(\Omega')} \leq C\Big(\|\LL u\|_{W^{-1,p}(\Omega')} + \|u\|_{L^p(\Omega')}\Big) \,.
    \end{equation}
    for a constant $C=C(n,p,q,\lambda,\Lambda,\Omega')>0$.

    \vspace{0.3cm}
    \textit{Step 2.}  To get the global estimate, given $x\in \Omega''$, we first notice that \eqref{eq: localized_estimate} holds for all $u\in W_0^{1,p}(B_{r_x}(x))$ and some $r_x>0$, which we may take small enough so that $B_{r_x}(x)\subset\subset \Omega'$. Due to the compactness of $\overline{\Omega''}$, there exists a finite amount of such points $\{x_k\}_{k=1}^{K}$ such that $\Omega'' \subset \cup_{k=1}^K B^k$, where $B^k \doteq B_{r_k}(x_k)\subset\subset \Omega'$ and now \eqref{eq: localized_estimate} holds on each $B^k$ for all $u\in W^{1,p}_0(B^k)$ with a constant $C_k=C_k(n,p,q,\lambda,\Lambda,\Omega')$. Let us consider a smooth partition of unity $\{\eta_k\}_{k = 1}^K$ subordinate to $\{B^k\}_{k = 1}^K$ and estimate
    \begin{align*}
            \|u\|_{W^{1,p}(\Omega'')} &\leq \sum_{k=1}^K \|\eta_k u\|_{W^{1,p}(\Omega')}
            \\
            &\leq C \, \sum_{k=1}^K \Big(\|\eta_k \, \LL u\|_{W^{-1,p}(\Omega')} + \|u\|_{L^p(\Omega')}\Big)
            \\
            &\hspace{-1.5cm} + C \, \sum_{k=1}^K \Big(\bigl\|\bigl(a^{ij}\partial_i\partial_j \eta_k + b^i\partial_i\eta_k\bigr)u\bigr\|_{W^{-1,p}(\Omega')} + \bigl\|a^{ij} \bigl(\partial_i\eta_k\partial_j u + \partial_j\eta_k\partial_i u\bigr)\bigr\|_{W^{-1,p}(\Omega')} \Big),
    \end{align*}
    for a constant $C=C(n,p,q,\lambda,\Lambda,\Omega',\Omega'')$ which can be taken to be $C=\max\{C_k, \: k=1,\cdots,N\}$. It is easy to see that for any test function $\phi \in W_0^{1,p'}(\Omega')$, there holds
    \begin{equation*}
        \left|\langle  a^{ij} \partial_i \partial_j \eta_k \, u + b^i \partial_i \eta_k \, u ,\, \phi \rangle \right| \leq C(\eta_k, \Omega') \, \Lambda \, \| u \|_{L^p(\Omega')} \, \| \phi \|_{W^{1, p'}(\Omega')}
    \end{equation*}
    while the last term can be estimated as
    \begin{align*}
        \left|\langle  a^{ij} \partial_i \eta_k \, \partial_ju  ,\, \phi \rangle \right| & =  \left|\langle u,\, \partial_j(a^{ij} \partial_i \eta_k \,\phi) \rangle \right| 
        \\
        &\leq C(\eta_k, \Omega') \, \int_{\Omega'} |u \,( \partial_ja^{ij} \,\phi + a^{ij}(\partial_j\phi + \phi))| 
        \\
        &\leq C(\eta_k, \Omega') \, \left( \|u\|_{L^p(\Omega')}\,\|\partial_ja^{ij} \,\phi\|_{L^{p'}(\Omega')} + \Lambda  \, \| u\|_{L^p(\Omega')} \,\|\phi\|_{
        W^{1,p'}(\Omega')}\right) \\
        &\leq C'(\eta_k, \Omega') \, \|u\|_{L^p(\Omega')}\, \left( \|\partial_ja^{ij}\|_{L^{2q}(\Omega')} \, \|\phi\|_{L^{s}(\Omega')} + \Lambda \, \|\phi\|_{W^{1, p'}(\Omega')}\right)  
        \\
        & \leq C''(\eta_k, \Omega') \, \Lambda \, \|u\|_{L^p(\Omega')}\,\|\phi\|_{W^{1,p'}(\Omega')}\,,
    \end{align*}
    where, following a similar strategy to the one above, we have chosen $\tfrac{1}{s} \doteq \tfrac{1}{p'} - \tfrac{1}{2q} > \tfrac{1}{p'} - \tfrac{1}{n}$ to ensure the last Sobolev inequality and is well-defined due to $\tfrac{1}{p} < \tfrac{1}{q'} + \tfrac{1}{2q}$ equivalent to $\tfrac{1}{2q} < \tfrac{1}{p'}$. The assertion then follows by combining the three estimates above.
\end{proof}
The above lemma allows us to prove 
a refined version of \cite[Theorem 9.11]{GT}:
\begin{lemma}
    \label{lemma: GT 9.11 adaptation}
    Let $\Omega\subset \mathbb{R}^n$ be a smooth, bounded domain around the origin and let $\LL$ be an operator of the form of \eqref{eq: Linear Elliptic Operator} with coefficients satisfying \eqref{coeff conditions 1}-\eqref{coeff conditions 2}. Let $u \in W^{2,q}(\Omega)$ be a solution of $\LL u = f$ in $\Omega$ with $f \in L^q(\Omega)$. Then, for every smooth, bounded $\Omega'' \subset \subset \Omega$ and every 
    $p > \tfrac{2q}{2q-1}$, there exists a positive constant $C = C\bigl(n, q, p, \lambda, \Lambda, \Omega'', \Omega\bigr)$ such that
    \begin{equation*}
        \|u\|_{W^{2, q}(\Omega'')} \leq C \Big(\|u\|_{L^{p}(\Omega)} + \| f\|_{L^q(\Omega)}\Big) \,.
    \end{equation*}
\end{lemma}
\begin{proof}
    Fix $d \coloneqq \text{dist}(\Omega'', \partial\Omega)$ and for each $k = 0, 1, 2, \ldots$ define
    \begin{equation*}
        \Omega_k \coloneqq \Big\{x \in \Omega \; : \; \operatorname{dist}(x, \partial\Omega) > \tfrac{d}{2+k+k_0}\Big\} \,,
    \end{equation*}
    so that $\Omega'' \subset \subset \Omega_0 \subset \subset \Omega_1 \subset \subset \dots \subset \subset \Omega$ and $k_0>0$ is chosen large enough so that $\partial\Omega_k$ are smooth for all $k$. From \cite[Theorem 9.11]{GT} there exists a positive constant $C_0 = C_0\bigl(n, q, \lambda, \Lambda, \Omega'', \Omega\bigr)$ such that
    \begin{equation}
        \label{eq: GT 9.11 estimate}
        \|u\|_{W^{2, q}(\Omega'')} \leq C_0 \Big(\|u\|_{L^{q}(\Omega_0)} + \| f\|_{L^q(\Omega)}\Big) \,.
    \end{equation}
    If $p \geq q$ the statement follows by H\"older inequality, so let us consider $p < q$. Notice that the lower bound on $p$ corresponds to $\tfrac{1}{p} < \tfrac{1}{q'} + \tfrac{1}{2q}$.
    Define then the number
    \begin{equation*}
        \delta \doteq \min\left\{\frac{1}{n}, \; \frac{1}{q'} + \frac{1}{2q} - \frac{1}{p}\right\} > 0\,,
    \end{equation*}
    and set  
    \begin{equation*}
        p_0 = q \,, \qquad \frac{1}{p_{k}} \doteq \frac{1}{p_{k-1}} + \delta = \frac{1}{q} + k\delta
    \end{equation*}
    for integers $k \geq 1$. Let $N \in \nN$ be the smallest integer such that $p_N \leq p$. Observe that all $p_0 > p_1 > \ldots > p_{N}$ satisfy $W^{1,p_{k+1}}(\Omega_k) \hookrightarrow L^{p_k}(\Omega_k)$ and $\tfrac{1}{q} \leq \tfrac{1}{p_k} < \tfrac{1}{q'} + \tfrac{1}{2q} $; the strict inequality is clear for $k \leq N-1$ due to $\tfrac{1}{p_{N-1}} < \tfrac{1}{p} < \tfrac{1}{q'}+\tfrac{1}{2q}$ by hypothesis, but it also holds true for $p_N$, due to the step size $\delta \leq \tfrac{1}{q'} + \tfrac{1}{2q} - \tfrac{1}{p}$. Therefore, we can apply \cref{lemma: Avalos 3.2 adaptation} to get
    \begin{align*}
        \|u\|_{L^{p_k}(\Omega_k)} &\leq C(n, q, p, \Omega_k) \, \|u\|_{W^{1, p_{k+1}}(\Omega_k)}
        \\
        &\leq C(n, q, p, \Omega_k, \lambda, \Lambda, \Omega_{k+1}) \Big(\|u\|_{L^{p_{k+1}}(\Omega_{k+1})} + \|f\|_{W^{-1, p_{k+1}}(\Omega_{k+1})}\Big) 
        \\
        &\leq C(n, q, p,\Omega_k, \lambda, \Lambda,\Omega_{k+1}) \Big(\|u\|_{L^{p_{k+1}}(\Omega_{k+1})} + \|f\|_{L^q(\Omega_{k+1}})\Big)
        \\
         &\leq C(n, q, p, \Omega_k, \lambda, \Lambda, \Omega_{k+1}) \Big(\|u\|_{L^{p_{k+1}}(\Omega_{k+1})} + \|f\|_{L^q(\Omega})\Big)
    \end{align*}
     where the third inequality is given by the fact that 
     \begin{equation*}
         L^q(\Omega_{k+1}) \hookrightarrow W^{-1, p_{k+1}}(\Omega_{k+1}) \quad \iff \,\,\, W^{1, p_{k+1}'}_0(\Omega_{k+1}) \hookrightarrow L^{q'}(\Omega_{k+1}) \,,
     \end{equation*}
     which is guaranteed by $\tfrac{1}{p_{k+1}} \geq \tfrac{1}{q} - \tfrac{1}{n}$. By concatenating the estimates and noticing that all the domains $\Omega_k$ are determined by $\Omega$, $\Omega''$, $n$, $q$ and $p$, we establish
     \begin{align*}
         \|u\|_{L^q(\Omega_0)} &\leq C(n, q, p, \lambda, \Lambda, \Omega_0, \ldots \Omega_N) \Big(\|u\|_{L^{p_{N}}(\Omega)} + \| f\|_{L^q(\Omega)}\Big) 
         \\
         &\leq C(n, q, p, \lambda, \Lambda,\Omega'', \Omega) \Big(\|u\|_{L^{p}(\Omega)} + \| f\|_{L^q(\Omega)}\Big) \,.
     \end{align*}
     The assertion follows by combining it with \eqref{eq: GT 9.11 estimate}.
\end{proof}
Finally, we are ready to prove \cref{prop: blow-up behaviour}. The proof is a scaling argument inspired by \cite[Proposition 9.1]{TaylorToolsForPDEs}.
\begin{proof}[Proof of \cref{prop: blow-up behaviour}]
    Since by hypothesis $f = O\bigl(|x|^{-\gamma}\bigr)$ as $|x| \to 0$, there exists a fixed $\rho_0\in (0,1)$ and a constant $C_{\rho_0}>0$ such that if $\rho < \rho_0$
    \begin{align}
        \label{RadChoice.1}
        \sup_{x\in B_{\rho}(0)}|f(x)||x|^{\gamma}\leq C_{\rho_0}.
    \end{align}
    Having such $\rho_0$ fixed, consider $\rho>0$ such that $0 < 4\rho\leq \rho_0 < 1$ and $B_{4\rho}(0) \subset\subset \Omega$. Let us then consider some fixed $x_0 \in \partial B_{2\rho}(0)$.  Define $u_{\rho}(x) \doteq u(\rho(x-x_0) + x_0)$ and observe that it satisfies
    \begin{equation*}
        \LL_{\rho} u_\rho = a_{\rho}^{ij}\partial_i\partial_j u_{\rho} + b^i_{\rho}\partial_iu + c_\rho u_{\rho} = \rho^2 f_\rho \qquad \text{in} \quad B_1(x_0) \,,
    \end{equation*}
    where
    \begin{align*}
        &a_{\rho}^{ij}(x) = a^{ij}(\rho(x-x_0) + x_0) \,, &&b^i_{\rho}(x) = \rho \, b^i(\rho(x-x_0) + x_0) \,, 
        \\
        &c_\rho(x) = \rho^2 c(\rho(x-x_0) + x_0) \,, \quad &&f_{\rho}(x) = f(\rho(x-x_0) + x_0) \,.
    \end{align*}
    Since $u \in W^{2,q}\bigl(B_{\rho}(x_0)\bigr)$, then $u_{\rho} \in W^{2,q}\bigl(B_1(x_0)\bigr)$. Similarly, if $u \in L^p\bigl(B_{\rho}(x_0)\bigr)$ for given $p > \tfrac{2q}{2q-1}$ in the case $(i)$, then $u_{\rho} \in L^p \bigl(B_1(x_0)\bigr)$. The same applies in the case $(ii)$ for any such $p$. Thus, we may use \cref{lemma: GT 9.11 adaptation} with $\Omega'' = B_{3/4}(x_0)$ and $\Omega = B_1(x_0)$ to obtain
    \begin{equation}
        \label{eq: elliptic estimate in Prop}
        \|u_{\rho}\|_{W^{2,q}(B_{3/4}(x_0))} \leq C_0 \Big(\|u_{\rho}\|_{L^{p}(B_1(x_0))} + \rho^2\|f_{\rho}\|_{L^{q}(B_1(x_0))} \Big)
    \end{equation}
    with a constant $C_0$ depending on $n$, $q$, $p$ and the constants $\lambda$ and $\Lambda$ from \cref{lemma: GT 9.11 adaptation} corresponding to the operator $\LL_{\rho}$. Observe that by
    \begin{equation*}
        \inf_{B_1(x_0)} a_{\rho}^{ij} = \inf_{B_{\rho}(x_0)} a^{ij} \geq \inf_\Omega a^{ij} \,,
    \end{equation*}
    the ellipticity constant $\lambda$ can be chosen independent of $\rho$. Similarly, using that $\rho < 1$ and $q > \tfrac{n}{2}$, one can check that
    {
    \allowdisplaybreaks
    \begin{align*}
        \|a^{ij}_\rho\|_{C^{0,2 - \frac{n}{q}}(B_1(x_0))} &= \sup_{B_{\rho}(x_0)} |a^{ij}| + \rho^{2 - \frac{n}{q}}\sup_{\underset{x\neq y}{x,y \in B_{\rho}(x_0)}}\frac{\bigl|a^{ij}(x) - a^{ij}(y)\bigr|}{|x-y|^{2 - \frac{n}{q}}} \leq \|a^{ij}\|_{C^{0,2-\frac{n}{q}}(\Omega)} \,,
        \\
        \|\partial_k a_{\rho}^{ij}\|_{L^{2q}(B_1(x_0))}
        &= \rho^{1 - \frac{n}{2q}} \, \| \partial_k a^{ij}\|_{L^{2q}(B_\rho(x_0))} \leq \| \partial_k a^{ij}\|_{L^{2q}(\Omega)} \,,
        \\
        \sup_{B_1(x_0)}|b^i_{\rho}| &= \rho \sup_{B_{\rho}(x_0)} |b^i| \leq \sup_{\Omega} |b^i| \,,
        \\
        \sup_{B_1(x_0)}|c_{\rho}| &= \rho^2 \sup_{B_{\rho}(x_0)} |c| \leq \sup_{\Omega} |c| \,.
    \end{align*}
    }
    It follows that also $\Lambda$, and consequently $C_0$, can be chosen independently of $\rho$. The second term in \eqref{eq: elliptic estimate in Prop} can be estimated as follows. By our choice of $\rho\leq \rho_0$, from \eqref{RadChoice.1} we know that
    \begin{align*}
        |f(x)|\leq C_{\rho_0}|x|^{-\gamma}
    \end{align*}
    for all $x\in B_{\rho}(x_0)$. Moreover, since $B_{\rho}(x_0)\subset B_{3\rho}(0)\backslash B_{\rho}(0)$, then $|x|\geq \rho$ for all $x\in B_{\rho}(x_0)$ and thus 
    \begin{align*}
        \sup_{x\in B_{\rho}(x_0)}|f(x)|\leq C_{\rho_0}\rho^{-\gamma} \,.
    \end{align*}
    Therefore, we may estimate
    \begin{equation}
        \label{eq: first f term estimate}
        \rho^2 \|f_\rho\|_{L^q(B_1(x_0))} = \rho^{2-\frac{n}{q}}\|f\|_{L^q(B_\rho(x_0))} \leq C_{\rho_0} \rho^{2-\frac{n}{q}-\gamma} |B_{\rho}(x_0)|^{\frac{1}{q}} \leq C_1 \rho^{2-\gamma}
    \end{equation} 
    with $C_1$ depending only on $n$, $q$ and $\rho_0$.

    In the case (\textit{i}), we estimate the first term of \eqref{eq: elliptic estimate in Prop} by
    \begin{equation*}
        \|u_{\rho}\|_{L^p(B_{1}(x_0))} = \rho^{-\frac{n}{p}}\|u\|_{L^{p}(B_{\rho}(x_0))} \leq \rho^{-\frac{n}{p}}\|u\|_{L^{p}(\Omega)}
    \end{equation*}
    and observe that if $\gamma \leq 2 + \tfrac{n}{p}$ the first term dominates over the second for small enough $\rho$. Thus, we establish
    \begin{equation*}
        \|u_{\rho}\|_{W^{2,q}(B_{3/4}(x_0))} \leq C_2 \, \rho^{-\frac{n}{p}}
    \end{equation*}
    for some $C_2$ depending on $n$, $q$, $p$, $\lambda$, $\Lambda$, $\rho_0$ and $\|u\|_{L^p(\Omega)}$. Using the Sobolev embedding $W^{2,q}(B_{3\rho/4}(x_0)) \hookrightarrow C^{0,2-\frac{n}{q}}(B_{3\rho/4}(x_0))$, we obtain
    \begin{align*}
        \sup_{B_{3\rho/4}(x_0)} |u| = \sup_{B_{3/4}(x_0)} |u_{\rho}| \leq \|u_{\rho}\|_{C^{0,2-\frac{n}{q}}(B_{3/4}(x_0))} \leq C(n, q) \|u_{\rho}\|_{W^{2,q}(B_{3/4}(x_0))} \leq C_3 \, \rho^{-\frac{n}{p}} \,.
    \end{align*}
    Clearly, this implies that $|u(x_0)|\leq  C_3 \rho^{-\frac{n}{p}}=2^{\frac{n}{p}}C_3|x_0|^{-\frac{n}{p}}$ and since $x_0 \in \partial B_{2\rho}(0)$ was arbitrary, it follows that $u(x) = \BO\bigl(|x|^{-\frac{n}{p}}\bigr)$. In addition if $q > n$, then we can use the $W^{2,q}(B_{3/4}(x_0)) \hookrightarrow C^{1,1-\frac{n}{q}}(B_{3/4}(x_0))$ embedding to additionally obtain
    \begin{align*}
        \rho \, \sup_{B_{3\rho/4}(x_0)} |\partial u| &=\sup_{B_{3/4}(x_0)} |\partial u_{\rho}|
        \\
        &\leq \|u_{\rho}\|_{C^{1,1-\frac{n}{q}}(B_{3/4}(x_0))} \leq C(n, q) \|u_{\rho}\|_{W^{2,q}(B_{3/4}(x_0))} \leq C_3 \, \rho^{-\frac{n}{p}} \,,
    \end{align*}
    which shows that $\partial u = \BO\bigl(|x|^{-\frac{n}{p}-1}\bigr)$ as desired.

    In the case (\textit{ii}), we can use the Hölder continuity of $u$ through the origin to expand
    \begin{equation*}
        u = u(0) + \BO\bigl(|x|^\beta\bigr) \quad \text{as} \quad |x| \to 0 \,.
    \end{equation*}
    Notice that without loss of generality, we can assume $u(0) = 0$. In fact, considering the function $v \coloneqq u - u(0)$, it solves $\LL v = f - c\, u(0)$ and the right hand side is then still in $L^q(\Omega)$ and $\BO(|x|^{-\gamma})$. We can estimate the first term of \eqref{eq: elliptic estimate in Prop} as
    \begin{align*}
        \|u_\rho\|_{L^p(B_1(x_0))} &= \rho^{-\frac{n}{p}} \left(\int_{B_\rho(x_0)} |u(x)|^p dx\right)^{1/p}
        \\
        &\leq \sup_{\underset{x \neq y}{x,y \in \Omega}}\frac{\bigl|u(x) - u(y)\bigr|}{|x-y|^{\beta}} \, 2^\beta \rho^{-\frac{n}{p}+\beta}|B_\rho|^{\frac{1}{p}} 
        \,\leq C_4 \, \rho^\beta 
        \,.
    \end{align*}
    Combined with \eqref{eq: first f term estimate} and the hypothesis $\beta \leq 2 - \gamma$, we obtain
    \begin{equation*}
        \|u_\rho\|_{W^{2,q}(B_{3/4}(x_0))} \leq C_5 \, \rho^\beta \,, 
    \end{equation*}
    where $C_5$ depends only on $n$, $q$, $p$, $\lambda$, $\Lambda$, $\rho_0$. Same as before, if $q > n$ we use the $W^{2,q}(B_{3/4}(x_0)) \hookrightarrow C^{1,1-\frac{n}{q}}(B_{3/4}(x_0))$ embedding to obtain
    \begin{align*}
        \rho \, \sup_{B_{3\rho/4}(x_0)} |\partial u| &=\sup_{B_{3/4}(x_0)} |\partial u_{\rho}| \leq \|u_{\rho}\|_{C^{1,1-\frac{n}{q}}(B_{3/4}(x_0))} 
        \\
        &\leq C(n, q) \|u_{\rho}\|_{W^{2,q}(B_{3/4}(x_0))} \leq C_4 \, \rho^{\beta},
    \end{align*}
    which grants that $u(x)-u(0)=O_1(|x|^{\beta})$.
\end{proof}

In view of the \emph{Step 3: Positivity and expansion} part of the proof of \cref{theorem C},
we recall that whenever $\tfrac{n}{2} < \tfrac{nq}{n+(n-2)q}$ the fundamental solution $|x|^{2-n}$ is the only singular part of the conformal Green's function and the error $h(x)$ has a H\"older expansion. This is only possible whenever $n = 3$ and $q > 3$; in particular, this also gives control on the first derivative of the error. In conclusion, we have established the following:
\begin{corollary}
    \label{cor: unnormalized Green 3dim}
    Let $M$ be a smooth, closed 3-manifold and consider a $W^{2,q}$-Riemannian metric $g$ on $M$ with $q > 3$ and $\lambda(M, g) > 0$. Then, for each point $p \in M$ there exists a positive function $\G \in W^{2,q}_{loc}\bigl(M \setminus \{\p\}\bigr)$ satisfying $\Lg\G = 0$ on $M \setminus \{p\}$ such that
    \begin{equation*}
        \G(x) = \frac{1}{|x|} + \h(x) \,, \qquad \h(x) = A + \BO_1\bigl(|x|^{2-\frac{3}{r}}\bigr) \quad \text{as} \quad |x| \to 0
    \end{equation*}
    in a normal coordinate chart $(U,x^i)$ around $p$ with $\h \in W^{2,r}(U)$ for all $r < \tfrac{3q}{3+q}$.
\end{corollary}
Naturally, the function in \cref{cor: unnormalized Green 3dim} is given by $\G = b_nG_p$. Such normalization will make computations simpler later in \cref{Decompactification via Conformal Green's function}.

