% ====================================
\vspace{0.5cm}
\section{The Yamabe Problem}
\label{The Yamabe Problem}
In this section we prove \cref{theorem A} following the classic approach: first, we extend the Aubin--Trudinger--Yamabe Theorem to our setting of rough metrics and then we appeal to Schoen's idea of using the conformal Green function to 
get an AE manifold and construct an appropriate test function with the help the Positive Mass Theorem of general relativity. 



% ------------------------------------
% ------------------------------------
\subsection{The Aubin--Trudinger--Yamabe Theorem}\label{The Aubin--Trudinger--Yamabe Theorem}
For smooth Riemannian metrics, the Aubin--Trudinger--Yamabe Theorem asserts that the Yamabe problem can be solved provided that the Yamabe invariant is below that of the round sphere. In the following, we show the analogue result for $W^{k,q}$-Riemannian metrics with $k \geq 2$ and $q > \tfrac{n}{2}$ in \cref{thm: Aubin-Trudinger-Yamabe} below, which in particular establishes \cref{theorem B}. As explained in \cref{Introduction}, we remark that the same result for $W^{1,p}$-Riemannian manifolds with $q > n$ has been proven by H. Zhang \cite{ZhangW1pAubin}.

The strategy we follow is the same as in the smooth case: we perturb the variational problem in favour of better compactness properties, find a minimizer via direct methods and finally extract a limit solution of the original problem. The main difficulty one encounters in the low-regularity setting is that the coefficients of the variational PDE are rough, and consequently standard elliptic regularity does not apply. On the other hand, the following two well-known results from the analysis of the classic Yamabe problem for smooth metrics do extend directly to the case of metrics of $W^{2,q}$-regularity.
\begin{lemma}
    \label{lemma: continuity yamabe invariant}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ on $M$ with $q > \tfrac{n}{2}$ and $\vol_g(M) = 1$. Then, the map $s \mapsto |\lambda_s(M,g)|$ non-increasing for $s \in [2,2^*]$. Moreover, if $\lambda(M,g) \geq 0$, it is continuous from the left. 
\end{lemma}
\begin{proof}
    The proof is identical to the one known for smooth metrics and can be consulted in \cite[Lemma 4.3]{Lee-Parker}.
\end{proof}
\begin{proposition}
    \label{prop: uniform Lr bound}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ on $M$ with $q > \tfrac{n}{2}$ satisfying $\vol_g(M) = 1$, $\R_g\in C^{0}(M)$ and $\lambda(M,g) < \lambda(\nS^n)$. Let $u_s \in W^{2,q}(M)$ be positive minimizers of $Q_g^s$ normalized by $\|u_s\|_{L^s(M,d\mu_g)} = 1$.\footnote{The existence of such minimisers is granted by Proposition \ref{prop: subcritical existence} and their regularity by Corollary \ref{prop: subcritical regularity}.} Then, there are constants $s_0 < 2^*$, $\delta=\delta(s_0) > 0$ and $C$ such that $\|u_s\|_{L^{2^*(1+\delta)}(M)} \leq C$ for all $s \in [s_0,2^*)$.\footnote{It follows from the proof as given in \cite[Proposition 4.4]{Lee-Parker} that $\delta=\delta(s_0)$ only depends on $\lambda_{s_0}(M,g)$.}
\end{proposition}
\begin{proof}
    Exploiting the fact that $\R_g\in C^0(M)$, the proof follows exactly in the same way as in \cite[Proposition 4.4]{Lee-Parker}, working with smooth approximations when integrating by parts, as explained in \cref{lemma: kernel_improvement}. Aubin's Sobolev inequality needed in the proof can easily be seen to hold for $C^{0,\alpha}$-metrics, for instance, by using coordinates such that $g_{ij}(x) = \delta_{ij} + O\bigl(|x|^\alpha\bigr)$ rather than normal coordinates in the proof of \cite[Theorem 9]{AubinIsoperim}.
\end{proof}
\begin{remark}
    \label{RemarkCompasionZhang.1}
    Let us highlight that the above proposition is also needed for even lower regularity cases --see \cite[Proposition 4.4]{ZhangW1pAubin}--. We again emphasize that the conformal invariance of the problem and \cref{cor: Yamabe classification}, which allow us to consider the case $\R_g\in C^{0}(M)$, essentially reduces the above proposition to the one known for smooth metrics.
\end{remark}
Using the above results, 
we can prove the Aubin--Trudinger--Yamabe theorem:
\begin{theorem}
    \label{thm: Aubin-Trudinger-Yamabe}
    Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{2,q}$-Riemannian metric $g$ on $M$ with $q > \tfrac{n}{2}$. If $\lambda(M,g) < \lambda(\nS^n)$, there exists a Riemannian metric in the $W^{2,q}$ conformal class of $g$ of constant scalar curvature.
\end{theorem}
\begin{proof}
    Since $\lambda(M, g)$ is a conformal invariant, by \cref{cor: Yamabe classification} we can assume without loss of generality that $\R_g$ is continuous. Moreover, we may rescale the metric such that $\vol_g(M) = 1$. By \cref{prop: uniform Lr bound} we know that there are fixed numbers $s_0< 2^*$ and $\delta=\delta(s_0) > 0$, such that $\|u_s\|_{L^r(M)} \leq C_0$ for all $s\in (s_0,2^{*})$, where $r = 2^*(1 + \delta)$ and $u_s \in W^{2,q}(M)$ are positive minimizers of $Q_g^s$ normalized by $\|u_s\|_{L^s(M,d\mu_g)} = 1$. We may, without loss of generality, assume that $C_0 \geq 1$. Fix some $\tfrac{n}{2} < t < \min\{q, \tfrac{r}{2^*-2}\}$, which is always possible because
    \begin{equation*}
        \frac{r}{2^* - 2} = \frac{2^*(1 + \delta)}{2^* - 2} = \frac{n}{2}(1 + \delta)
    \end{equation*}
    and $\frac{n}{2} < q$ by hypothesis.

    \vspace{0.5cm}
    \textit{Step 1.} We first aim to obtain an estimate on $\|u_s\|_{W^{2,t}(M)}$ uniform in $s\in (s_0,2^{*})$, since the Sobolev inequality
    \begin{equation*}
        \|u_s\|_{C^{0,2-\frac{n}{t}}(M)} \leq C(M,n,t) \, \|u_s\|_{W^{2, t}(M)}
    \end{equation*}
    would imply a uniform Hölder bound ($t$ depends on $n$, $q$ and $\delta$, but not on $s$). By Lemma \ref{lemma: Lg is Fredholm} we know that
    \begin{equation}
        \label{eq: 2t elliptic estimate}
        \|u_s\|_{W^{2,t}(M)} \leq C(M,g,n,t,q)\bigl(\|u_s^{s-1}\|_{L^t(M)} + \|u_s\|_{L^t(M)}\bigr)
    \end{equation}
    holds for all $s \in (s_0, 2^*)$. If $t \leq r$ we use that $\mathrm{vol}_g(M)=1$ to directly estimate the second term with the $L^r(M)$ norm via Hölder. If $t > r$ instead, we have the sequence
    \begin{equation*}
        W^{2,t}(M) \hookrightarrow L^t(M) \hookrightarrow L^r(M)
    \end{equation*}
    with the first embedding being compact, and hence we can interpolate
    \begin{equation}
        \label{eq: Lt interpolation}
        \|u_s\|_{L^t(M)} \leq \varepsilon \|u_s\|_{W^{2,t}(M)} + C_\varepsilon(M,n,t,r) \,\|u_s\|_{L^r(M)} \,.
    \end{equation}
    Thus, we see that regardless of $t$ being above or below $r$, given any $\varepsilon>0$ there is a constant $C_\varepsilon(M,n,t,r)>0$ (independent of $s$) such that we can estimate the second term in \eqref{eq: 2t elliptic estimate} by \eqref{eq: Lt interpolation} for all $s \in (s_0, 2^*)$. On the other hand, we can manipulate the first term like
    \begin{align*}
        \|u_s^{s-1}\|_{L^t(M)} &= \|u_s^{s-2} u_s\|_{L^t(M)} 
        \\
        &\leq \|u_s^{s-2}\|_{L^{\frac{r}{s-2}}(M)} \|u_s\|_{L^p(M)} = \|u_s\|^{s-2}_{L^r(M)} \|u_s\|_{L^p(M)} \leq C_0^{2^* - 2}\|u_s\|_{L^p(M)} \,,
    \end{align*}
    where $p$ is the Hölder conjugate 
    \begin{equation*}
        \frac{1}{p} \doteq \frac{1}{t} - \frac{s - 2}{r}
    \end{equation*}
    and it is well-defined due to
    \begin{equation*}
        0 < \frac{1}{t} - \frac{2^* - 2}{r} < \frac{1}{t} - \frac{s - 2}{r} < \frac{1}{t} < 1 \,.
    \end{equation*}
    Now, if $p < r$, we simply use the Hölder inequality together with $\vol_g(M) = 1$ to estimate $\|u_s\|_{L^p(M)} \leq \|u_s\|_{L^r(M)}$. If $p \geq r$, define $l \doteq \tfrac{tr}{r - t(2^*-2)}$, which is well-defined, independent of $s$ and by
    \begin{equation*}
        \frac{1}{l} = \frac{1}{t} - \frac{2^* - 2}{r} < \frac{1}{t} - \frac{s - 2}{r} = \frac{1}{p}
    \end{equation*}
    it satisfies that $r \leq p < l$. Again, the compact-continuous embeddings
    \begin{equation*}
        W^{2,t}(M) \hookrightarrow L^{l}(M) \hookrightarrow L^r(M)
    \end{equation*}
    yield that for every $\eta > 0$ we have that
    \begin{equation*}
        \|u_s\|_{L^{l}(M)} \leq \eta \|u_s\|_{W^{2,t}(M)} + C_\eta(M,n,t,r) \|u_s\|_{L^r(M)} \,,
    \end{equation*}
    which combined with the Hölder inequality $\|u_s\|_{L^p(M)} \leq \|u_s\|_{L^l(M)}$ allows us to estimate the first term in \eqref{eq: 2t elliptic estimate} by
    \begin{equation*}
        \|u_s^{s-1}\|_{L^t(M)} \leq C_0^{2^*-2}\bigl(\eta \|u_s\|_{W^{2,t}(M)} + C_\eta(M,n,t,r) \|u_s\|_{L^r(M)}\bigr) \,.
    \end{equation*}
    Putting it all together and noticing that $r = r(n, \delta)$ and $t = t(n, q, \delta)$ we obtain
    \begin{align*}
        \|u_s\|_{W^{2,t}(M)} &\leq C(M,g,n,q,\delta) C_0^{2^*-2}\Big(\eta\|u_s\|_{W^{2,t}(M)} + C_\eta(M,n,q, \delta) \|u_s\|_{L^r(M)}\Big) 
        \\
        &\qquad + C(M,g,n,q,\delta) \Big(\varepsilon \|u_s\|_{W^{2,t}(M)} + C_\varepsilon(M,n,q,\delta) \,\|u_s\|_{L^r(M)}\Big)
        \\
        &\leq C(M,g,n,q,\delta) \bigl(C_0^{2^*-2}\eta + \varepsilon\bigr) \|u_s\|_{W^{2,t}(M)} + C(M,g,n,q,\delta,C_0,\varepsilon,\eta) \,.
    \end{align*}
    Therefore, we see that choosing $\eta = \varepsilon = C(M,g,n,q,\delta)^{-1}(2C_0^{2^*-2} + 2)^{-1}$ we absorb the first term in the right-hand side above into the left-hand side and establish
    \begin{equation*}
        \|u_s\|_{W^{2,t}(M)} \leq 2C(M,g,n,q,\delta,C_0)
    \end{equation*}
    for all $s \in (s_0,2^*)$, as desired.

    \vspace{0.5cm}
    \textit{Step 2.} By the previous step, we have a uniform Hölder bound $\|u_s\|_{C^{0,2-\frac{n}{t}}(M)}\leq C_1(M,g,n,q,\delta,C_0)$ for all $s\in (s_0,2^{*})$, which we may assume to be $C_1(M,n,q,\delta,C_0) \geq 1$. By Arzelà--Ascoli, taking a sequence $\{u_{s_j}\}_{j=1}^{\infty}$ with $s_0<s_j<2^{*}$ such that $s_j\to 2^{*}$, we can then extract a sub-sequence, which we still denote by $\{u_{s_j}\}_{j=1}^{\infty}$, converging uniformly to $u \in C^0(M)$. Since $W^{2,t}(M) \hookrightarrow W^{1,2}(M)$, then $u_s$ are also uniformly bounded in $W^{1,2}(M)$. Consequently, up to a further subsequence to which we restrict and still denote by $\{u_{s_j}\}_{j=1}^{\infty}$, $u_{s_j} \rightharpoonup u$ in $W^{1,2}(M)$. Moreover, by \cref{prop: subcritical regularity}, each such $u_{s_j}\in W^{2,q}(M)$ satisfies $\mathscr{L}_gu_{s_j}=\lambda_{s_j}u_{s_j}^{s_j-1}$ and by \cref{lemma: Lg is Fredholm},
    \begin{align*}
        \Vert u_{s_j}\Vert_{W^{2,q}(M)} &\leq C(M,g,q)\bigl(\Vert \lambda_{s_j}u_{s_j}^{s_j-1}\Vert_{L^q(M)} + \Vert u_{s_j}\Vert_{L^q(M)}\bigr)
        \\
        &\leq C(M,g,q)\bigl(|\lambda_{s_j}|\Vert u_{s_j}\Vert_{C^0(M)}^{s_j-1} + \Vert u_{s_j}\Vert_{C^0(M)}\bigr)
        \\
        &\leq C(M,g,q)\Bigl(|\lambda_{s_j}| C^{s_j-1}_1(M,g,n,q,\delta,C_0) + C_1(M,g,n,q,\delta,C_0)\Bigr) \,,
    \end{align*}
    where above we have appealed to the uniform Hölder bound and the volume normalization $\vol_g(M)=1$. Since $C_1\geq 1$, we can also estimate $C_1 \leq C^{s_j-1}_1 \leq C^{2^{*}-1}_1$, and in combination with \cref{lemma: continuity yamabe invariant}, which grants $|\lambda_{s_j}|\leq |\lambda_2|$, we obtain
    \begin{align*}
        \Vert u_{s_j}\Vert_{W^{2,q}(M)}&\leq C(M,g,n,q,\delta,C_0)|\lambda_{2}| \,.
    \end{align*}
    Since $W^{2,q}(M)\hookrightarrow W^{1,2}(M)$ is compact due to $q>\frac{n}{2}$, this implies that there is a further subsequence, to which we restrict and still denote by $\{u_{s_j}\}_{j=1}^{\infty}$, such that $u_{s_j} \to \hat{u}$ in $W^{1,2}(M)$. Clearly, by uniqueness of the weak $W^{1,2}$-limit, $\hat{u}=u\in C^{0}(M)$. 
    Moreover, since $\Vert u_{s_j}\Vert_{L^{s_j}(M,d\mu_g)}=1$ for all $j$, then 
    \begin{align*}
        \Vert u\Vert_{L^{2^{*}}(M,d\mu_g)}=\lim_{j\to\infty}\Vert u_{s_j}\Vert_{L^{2^{*}}(M,d\mu_g)}\geq \lim_{j\to\infty}\Vert u_{s_j}\Vert_{L^{s_j}(M,d\mu_g)}=1,
    \end{align*}
    by $L^{2^{*}}(M)\hookrightarrow L^{s_j}(M)$ and $\vol_g(M)=1$. Thus, we deduce that $u\not\equiv 0$ and $u\geq 0$, the latter inequality holding since $u$ is the uniform limit of positive functions $u_{s_j}>0$. Now, to extract a limit equation for $u\in W^{1,2}(M)\cap C^0(M)$, we start with the associated sequence of $\{u_{s_j}\}_{j=1}^{\infty}\subset W^{1,2}(M)$ which satisfies
    \begin{align}
        \label{AubinSeqMinim}
        \Lg u_{s_j} = \lambda_{s_j}u_{s_{j}}^{s_j-1}.
    \end{align}
    Since $\{\lambda_{s_j}\}_{j=1}^n$ is a bounded sequence, it converges possibly up to a subsequence to some $\bar{\lambda}\in \mathbb{R}$. Restricting to the corresponding subsequence of functions $\{u_{s_j}\}_{j=1}^\infty$, the continuity of $\Lg : W^{1,2}(M) \to W^{-1,2}(M)$ implies that $\Lg u_{s_j} \to \Lg u$ in $W^{-1,2}(M)$. Besides, the $C^{0}(M)$ convergence of $u_{s_j} \to u$ implies point-wise convergence $u^{s_j-1}_{s_j} \to u^{2^{*}-1}$, and since $\|u_{s_j}\|_{C^0(M)} \leq C_1$, by dominated convergence there holds
    \begin{align}
        \label{DCTConv}
        \int_{M}u^{s_j-1}_{s_{j}}v \, d\mu_g \to  \int_{M}u^{2^{*}-1}v \, d\mu_g
    \end{align}
    for all $v \in W^{1,2}(M)$. Thus, $u^{s_j-1}_{s_j} \to u^{2^{*}-1}$ in $W^{-1,2}(M)$ as well. We deduce that the limit function satisfies
    \begin{align}
        \label{AubinSeqMinim.2}
        \Lg u = \bar{\lambda} u^{2^{*}-1},
    \end{align}
    as an equation in $W^{-1,2}(M)$. On the other hand, we have that
    \begin{equation*}
        \int_{M}u^{s_j}_{s_{j}}d\mu_g\to \int_{M}u^{2^{*}} d\mu_g \,,
    \end{equation*}
    as $u_{s_j}^{s_j} \to u^{2^*}$ point-wise, and consequently $\|u\|_{L^{2^*}(M,d\mu_g)} = 1$. Testing \eqref{AubinSeqMinim.2} with $u$ itself implies that $\bar{\lambda}=Q_g(u)$. When $\lambda(M,g) \geq 0$, we know that $s \mapsto \lambda_s$ is continuous from the left by \cref{lemma: continuity yamabe invariant} and thus $\bar{\lambda}=\lim_{j\to \infty}\lambda_{s_j}=\lambda(M,g)$. On the other hand, when  $\lambda(M,g)< 0$, again by \cref{lemma: continuity yamabe invariant} we know that $-\lambda_s(M,g)$ is non-increasing in $s$. Thus, one has $\lambda_{s_j}(M,g)\leq \lambda(M,g)$ for all $s_j<2^{*}$, which implies that $Q_g(u)=\bar{\lambda}\leq \lambda(M,g)$, so it must be that $\bar{\lambda}=\lambda(M,g)$. We have therefore established that, regardless of the sign of $\lambda(M,g)$, the function  $u \in C^0(M)\cap W^{1,2}(M)$ is a $L^{2^*}(M,d\mu_g)$-normalized, non-negative weak solution to the Yamabe PDE
    \begin{align*}
        \Lg u=\lambda(M,g)u^{2^{*}-1}.
    \end{align*}
    Since $u^{2^*-1} \in L^p(M)$ for any $p \geq 1$, \cref{thm: conf Laplace elliptic regularity} implies that $u \in W^{2,2}(M)$. By the
    \begin{align*}
        W^{2,2}(M) \hookrightarrow W^{1,p_0}(M) \;, \qquad p_0 \doteq \frac{2n}{n-2} > 2
    \end{align*}
    Sobolev embedding, we get that $u \in W^{1,p_0}(M)$ and item $(ii)$ of \cref{thm: conf Laplace elliptic regularity} implies in turn that $u \in W^{2,p_0}(M)$. If $p_0 \geq q$ we are done. Also, if $p_0\geq n$, then in particular $u\in W^{1,q}(M)$ and again \cref{thm: conf Laplace elliptic regularity} implies in one step that $u\in W^{2,q}(M)$. Otherwise, if $p_0<\min\{q,n\}$, we may use
    \begin{align*}
        W^{2,p_0}(M) \hookrightarrow W^{1,p_1}(M) \;, \qquad p_1 \doteq \frac{p_0n}{n-p_0} > p_0
    \end{align*}
    again and bootstrap the process to obtain $u\in W^{2,p_k}(M)$ along a sequence $\{p_k\}_k$ as long as $p_{k-1}<\min\{q,n\}$. Since
    \begin{align*}
        \frac{1}{p_k} - \frac{1}{p_{k+1}} = \frac{1}{n} \,,
    \end{align*}
    the sequence will reach $\min\{q,n\}$ in finitely many steps, granting $u\in W^{2,q}(M)$. Finally, since $u\geq 0$, the same reasoning as in the last part of the proof of \cref{prop: subcritical regularity} applies to show that $u$ must be strictly positive. Therefore, the metric $u^{\frac{4}{n-2}}g\in W^{2,q}(M)$ has constant scalar curvature and the proof concludes.
\end{proof}
We notice that the above \cref{thm: Aubin-Trudinger-Yamabe} settles the Yamabe problem for the case of non-positive Yamabe invariant. In particular, in light of the regularity theory of \cref{thm: conf Laplace elliptic regularity}, a straightforward bootstrap argument yields, as an immediate corollary
\begin{reptheorem}{theorem B}
\label{Coro-Yamabenegative}
  \emph{  Let $M$ be a smooth, closed manifold of dimension $n \geq 3$ and consider a $W^{k,q}$-Riemannian metric $g$ with $k \geq 2$ and $q > \tfrac{n}{2}$. Suppose that $\lambda(M,g) \leq 0$. Then, there exists a $W^{k,q}$-Riemannian metric conformal to $g$ of constant scalar curvature.}
\end{reptheorem}


