\subsection{Decompactification via conformal Green function}
\label{Decompactification via Conformal Green's function}
Let $M$ be a smooth, closed 3-manifold and $g$ be a $W^{2,q}$-Riemannian metric on $M$ with $q > 3$ and $\lambda(M, g) > 0$. Fix an arbitrary point $p \in M$ and consider the \textit{unnormalized Green function} $\G$ given in \cref{cor: unnormalized Green 3dim}. We define the non-compact Riemannian manifold
\begin{equation}
    \label{eq: decompactified metric}
    \hat{M} \doteq M\setminus \{p\} \,, \quad \hat g \doteq \G^4 g \,.
\end{equation}
In view of \cref{cor: unnormalized Green 3dim}, there exists a normal coordinate chart $(U,x^i)$ at $p$ such that
\begin{equation}
    \label{expansion_with_v}
    \G^4(x) = \frac{1}{|x|^4}\bigl(1 + |x|\h(x)\bigr)^4 \doteq \frac{1}{|x|^4}\bigl(1 + v(x)\bigr)
\end{equation}
for some function $\h \in W^{2,r}(U, d\mu_g)$, for any $r < \tfrac{3q}{q+3} < 3$. Since $|x| \in W^{2,r}(U, d\mu_g)$ and $W^{2,r}$ is an algebra under multiplication for $r\in (\frac{3}{2},\tfrac{3q}{q+3})$, it follows that $v \in W^{2,r}(U, d\mu_g)$. It is easy to see that $v(0) = 0$. On the other hand, by \cref{NormalCoordsC1}, in normal coordinates $g$ can be written as
\begin{equation*}
    g_{ij}(x) = \delta_{ij} + k_{ij}(x)
\end{equation*}
for some symmetric $k_{ij} \in W^{2,q}(U, d\mu_g)$ satisfying $k_{ij}(0) = 0$ and $\partial k_{ij}(0) =0$. Combining these expressions, we get that
\begin{equation}
    \label{def: k}
    \hat g_{ij}(x) = \frac{1}{|x|^4}\bigl(1 + v(x)\bigr)\bigl(\delta_{ij} + k_{ij}(x)\bigr) \,.
\end{equation}
Using the Kelvin transformed coordinates or \emph{asymptotic coordinates}
\begin{equation}
    \label{eq: asyCoord_z}
    z^i \doteq \frac{x^i}{|x|^2}
\end{equation}
on $\hat U \doteq U \setminus \{\p\} \subset \hat M$ we can write 
\begin{align}
    \label{eq: definition hat k}
        \hat g_{ab}(z) &= \frac{\partial x^i}{\partial z^a} \frac{\partial x^j}{\partial z^b} \, \hat g_{ij}(x) = \delta_{ab} + v(x)\delta_{ab} \nonumber
        \\
        &\quad + \left(k_{ab}(x) - \frac{2 \left( k_{aj}(x) z^jz^b + k_{bj}(x) z^j z^a \right)}{|z|^2} + 4k_{ij}(x) \frac{z^iz^jz^az^b}{|z|^4}\right)\bigl(1 + v(x)\bigr)
        \\
        &\doteq \delta_{ab} + \hat k_{ab}(z) \,. \nonumber
\end{align}

\begin{proposition}
    \label{prop: regularity_g_hat}
    Let $M$ be a smooth, closed 3-manifold and $g$ a $W^{2,q}$-Riemannian metric  with $q > 3$ and $\lambda(M, g) > 0$. Let $(\hat M, \hat g)$ be defined as in \eqref{eq: decompactified metric}. Then, 
    \begin{itemize}
        \item[(i)] $\hat g \in W^{2,q}_{loc}(\hat M)$ has zero scalar curvature,
        \item[(ii)] $(\hat M, \hat g)$ is $AS_\beta(1) \cap W^{2,r}_{-\tau}$-asymptotically Euclidean with respect to the structure at infinity given by the inverted coordinates $\{z^i\}_{i=1}^3$ introduced in \eqref{eq: asyCoord_z} for all $\tfrac{3}{2} < r < \frac{3q}{3+q}$ and $\tau = 2 - \tfrac{3}{r}$, where $\beta \doteq 2-\tfrac{3}{r}.$
    \end{itemize}
\end{proposition}

\begin{proof}
    $(i)$ From \cref{cor: unnormalized Green 3dim} we know that $\G \in W^{2,q}_{loc}(\hat M)$, so the regularity statement for $\hat g$ follows since $W^{2,q}_{loc}(\hat M)$ is an algebra under multiplication. Moreover, $\Lg\G = 0$ in $\hat M$, so $\R_{\hat g} \equiv 0$ by \eqref{eq: ConformalScalar}.

    $(ii)$ Notice that the function $v$ defined in \eqref{expansion_with_v}, due to the expansion of $\h$ in \cref{cor: unnormalized Green 3dim}, takes the form
    \begin{equation}
        \label{eq: v_expansion}
        v(x) = 4A |x|+ \BO_1(|x|^{1 + \beta}) \qquad \text{as} \quad |x| \to 0 \,.
    \end{equation}
    In particular, $\partial v = \BO(1)$. Thus, combining \eqref{eq: definition hat k} with
    \begin{equation*}
        k_{ij}(z) = \BO_1(|z|^{-1-\alpha}), \quad v(z) = \frac{4A}{|z|} + \BO_1\left(|z|^{-1-\beta}\right)
    \end{equation*}
    we get the expansion
    \begin{equation}
        \label{AS(1)condition}
        \hat g_{ij}(z) = \left(1 + \frac{4A}{|z|}\right)\delta_{ij} + \BO_1\bigl(|z|^{-1-\beta}\bigr) \qquad \text{as} \quad |z| \to \infty \,,
    \end{equation}
    which establishes the $AS_\beta(1)$ condition in these coordinates.

    To further show that $(\hat M, \hat g)$ is $W^{2,r}_{-\tau}$-AE, we follow \cite[Lemma 5.2]{MaxDil}, where 
    the singular part of the Green function $|x|^{2-n}$ is used as a conformal factor, instead of $\G$. From the discussion above, we must show that the functions $\hat k_{ij}$ defined by \eqref{eq: definition hat k} are in $W^{2,r}_{-\tau}(\nR^3 \setminus \overline{B}, d\mu_{\hat g})$. To that purpose, using that $k_{ij} \in C^1(U)$ and suppressing the indices, we compute
{
\allowdisplaybreaks
    \begin{align}
        \label{eq: firstDerivative_k_hat}
        \nonumber
            \frac{\partial \hat k}{\partial z} &= \frac{\partial x}{\partial z} \cdot \frac{\partial \hat k}{\partial x} 
            \\
            \nonumber
            &= \BO_1(|x|^2)  \BO_1(\partial_x v) + \BO_1(|x|^2)\Big(\BO_1(\partial_x k) + \BO_1(k)\BO_1(|x|) \Big)\bigl(1 + v\bigr) 
            \\
            & \qquad \qquad + \BO_1(|x|^2)\,\BO_1(k)\BO_1(\partial_x v)
            \\ 
            \nonumber
            &= \BO_1(|x|^2)\BO_1(\partial_x v)\Big(1 + \BO_1(k)\Big) + \Big(\BO_1(\partial_x k)\BO_1(|x|^2) 
            \\ 
            \nonumber
            & \qquad \qquad+ \BO_1(k)\BO_1(|x|)\Big)\bigl(1 + v\bigr)\,,
    \end{align}
}

\noindent
    where we have used \eqref{eq: definition hat k} and $\tfrac{\partial x}{\partial z} = \BO_1(|x|^2)$.
    Similarly, the second derivatives read
{
\allowdisplaybreaks
    \begin{align}
        \label{eq: second_derivative_k_hat} 
            \frac{\partial^2\hat k}{\partial z^2} &= \frac{\partial}{\partial z}\left(\frac{\partial\hat k}{\partial z}\right) = \frac{\partial x}{\partial z} \cdot \frac{\partial }{\partial x}\left(\frac{\partial\hat k}{\partial z}\right) 
            \nonumber
            \\ 
            &=  \BO_1(|x|^2)\biggl(\BO(|x|)\BO_1(\partial_x v)\Big(1 + \BO_1(k)\Big) + \BO_1(|x|^2)\BO(\partial_x^2v)\Big(1 + \BO_1(k)\Big) 
            \nonumber
            \\
            &\qquad + \BO_1(|x|^2)\BO_1(\partial_x v)\BO(\partial_x k)
            + \Big(\BO(\partial_x^2k)\BO_1(|x|^2) + \BO_1(\partial_x k)\BO(|x|) 
            \nonumber
            \\ 
            &\qquad + \BO(\partial_x k)\BO_1(|x|) + \BO_1(k)\Big)\bigl(1+v)
            + \BO_1(\partial_x k)\BO_1(|x|^2)\BO(\partial_x v) 
            \nonumber
            \\ 
            & \qquad+ \BO_1(k)\BO_1(|x|)\BO(\partial_x v)\biggr) 
            \\ 
            &= \BO_1(|x|^4)\Big(\BO(\partial_x^2v)\bigl(1 + \BO_1(k)\bigr) + \BO(\partial_x v)\BO(\partial_x k) + \BO(\partial_x^2k)\bigl(1+v\bigr)\Big)
            \nonumber
            \\
            &\qquad + \BO(|x|^3)\Big(\BO_1(\partial_x v)\bigl(1 + \BO_1(k)\bigr) + \BO_1(\partial_x k)\bigl(1+v\bigr)\Big) 
            \nonumber
            \\ 
            &\qquad + \BO_1(|x|^2)\BO_1(k)\bigl(1+v\bigr) \,.
            \nonumber
    \end{align}
}

\noindent
    Since the integral estimate of the first derivative is a simpler version of the one for the second derivative, we only carry out the details of the latter.
    Using that
    \begin{equation*}
        d\mu_{\hat g}(z) = (1+v)^{3/2}|z|^{6} d\mu_g(x)
    \end{equation*}
    and setting $-3 + \tau r + 2r = 4r - 6$, we can use \eqref{eq: second_derivative_k_hat} to obtain 
    \begingroup
\allowdisplaybreaks
    \begin{align*}
        \int_{\nR^3 \setminus B} &\biggl|\frac{\partial^2\hat k}{\partial z^2}\biggr|^r  |z|^{4r-6} \,d\mu_{\hat g}(z) = \\
        & = 
        \int_{B} \Big|\BO(\partial^2v)\bigl(1 + \BO_1(k)\bigr) + \BO(\partial v)\BO(\partial k) + \BO(\partial^2k)\bigl(1+v\bigr)\Big|^r (1+v)^{3/2} d\mu_g(x)
        \\
        &\quad + \int_B |x|^{-r}\Big|\BO_1(\partial v)\bigl(1 + \BO_1(k)\bigr) + \BO_1(\partial k)\bigl(1+v\bigr)\Big|^r (1+v)^{3/2} d\mu_g(x)
        \\
        &\quad + \int_B |x|^{-2r}\big|\BO_1(k)\bigl(1+v\bigr)\big|^r (1+v)^{3/2} d\mu_g(x)
    \end{align*}
    \endgroup
    Recalling that $v \in W^{2,r}(U, d\mu_g) \subset C^{0,\beta}(U)$ and  $k \in W^{2,q}(U, d\mu_g) \subset C^{1,\alpha}(U)$, as well

    \noindent as the Sobolev multiplication
    \begin{equation*}
        W^{1,r}(U) \otimes W^{1,q}(U) \hookrightarrow W^{1,r}(U) \,,
    \end{equation*}
    it is not hard to see that the first integral is finite. For the second integral, we essentially have to estimate 
    \begin{equation*}
        \int_B \frac{|\partial v|^r}{|x|^{r}} d\mu_g \qquad \text{and} \qquad \int_B \frac{|\partial k|^r}{|x|^{r}} d\mu_g \,. 
    \end{equation*}
    This is precisely the estimate (5.9) in \cite[Lemma 5.2]{MaxDil}, which we can use since $\tfrac{3}{2} < r < 3$ and $v(0) = k_{ij}(0) = 0$. Our third integral can be estimated using the same argument via the estimate (5.8) in \cite[Lemma 5.2]{MaxDil}. For details on these estimates, see also \cite[Lemma B.1 and Proposition B.1]{avalos2024sobolev}. This concludes the proof.
\end{proof}
\cref{prop: regularity_g_hat} allows us to transfer the Yamabe problem from the compact manifold $(M, g)$ to the AE manifold $(\hat M, \hat g)$. Following \cite{MaxDil} we define the Yamabe invariant of a $W^{2,r}_{-\tau}$-AE manifold $(\hat M, \hat g)$, with $r > \tfrac{3}{2}$ and $\tau > 0$ to be
\begin{equation}
    \label{YamabeInvAE}
    \lambda(\hat M, \hat g) \doteq \inf\left\{Q_{\hat g}(u) \; : \; u \in W^{1,2}_{-1/2}(\hat M) \;, \; u \not\equiv 0 \right\} \,.
\end{equation}
By the results within \cite[Section 3]{MaxDil}, this is well-defined and in fact $W^{1,2}_{-1/2}(\hat M)$ is the largest sensible function space for this variational problem. In parallel to \cite[Proposition 5.3]{MaxDil}, one can easily check the following:
\begin{proposition}
    \label{prop: compac-noncompact yamabe correspondence}
    Let $M$ be a smooth, closed $3$-manifold and $g$ a $W^{2,q}$-Riemannian metric on $M$ with $q > 3$ and $\lambda(M,g)$. Then,
    \begin{equation*}
        \lambda(\hat M, \hat g) = \lambda(M, g) \,,
    \end{equation*}
    where $(\hat M, \hat g)$ is the asymptotically Euclidean Riemannian manifold defined in \eqref{eq: decompactified metric}.
\end{proposition}



