\subsection{3-manifolds of positive Yamabe invariant}
\label{SectionProofMainThm}

We are now ready to solve the Yamabe problem for closed 3-manifolds by constructing a test function $\psi \in W^{1,2}_{-1/2}(\hat M)$ such that $Q_{\hat g}(\psi) < \lambda(\nS^3)$ and appealing to \cref{thm: Aubin-Trudinger-Yamabe} and \cref{prop: compac-noncompact yamabe correspondence}. For this, we follow the strategy adopted in the case of smooth metrics as presented in \cite[Section 7]{Lee-Parker}. The basic intuition is that, since $\hat{g}$ is close to the Euclidean metric near infinity, one may use so called \textit{Aubin bubbles}
\begin{equation}
    \label{eq: AubinBubbles}
    u_a(z) \doteq \left(\frac{|z|^2 + a^2}{a}\right)^{-\frac{1}{2}} \qquad \text{with} \qquad a > 0 
\end{equation}
to construct the desired test function. These are smooth solutions to
\begin{equation}
    \label{AubinBubble.1}
    -\Delta u_a = 3\,u_a^{2^*-1} \qquad \text{in} \;\; \nR^3 \,,
\end{equation}
which therefore saturate the optimal Sobolev inequality in $\nR^3$ and consequently satisfy --see \cite[Theorem 3.3]{Lee-Parker} or \cite{Talenti}--
\begin{align}
    \label{AubinBubble.2}
    24\|u_a\|^{2^{*}-2}_{L^{2^{*}}(\nR^3)} = 8\frac{\|\nabla u_a\|^2_{L^2(\nR^3)}}{\|u_a\|^{2^{*}}_{L^{2^{*}}(\nR^3)}} = \lambda(\nS^3) \,.
\end{align}
Observe that for large values of the parameter $a$, the functions $u_a$ become approximately constant in a ball $B_R(0)$ with $a>>R$. Thus, we fix some large radius $R > 0$ and let $\hat M_\infty \doteq \{|z| > R\}\subset \hat{M}$. Below, we shall use the notation $\rho(z) = |z|$ for the asymptotic radial coordinate. We define
    \begin{equation}
        \label{eq: test function}
        \psi_a(z) \doteq \begin{cases}
            u_a(z) \,, \quad \rho(z) \geq R
            \\
            u_a(R) \,, \quad \rho(z) \leq R
        \end{cases}
    \end{equation}
with $a >> R$ to be chosen latter. Clearly, $\psi_a \in W^{1,2}_{-1/2}(\hat M)$ and it is thus a candidate test function. Before going to the main proof, let us show the following, based on \cite[Lemma 3.5]{Lee-Parker}.
\begin{lemma}
    \label{PropIntegralEstimateYamabe}
    Let $a>R>0$ and $-1<k<3$ be real numbers. Then, there exists a constant $C=C(k)>0$ such that
    \begin{align}
        \label{IntegralEstimateYamabe}
        \int_{R}^{\infty}\rho^{-k}\frac{a}{(a^2+\rho^2)^2} \rho^{2}d\rho\leq Ca^{-k} 
    \end{align} 
\end{lemma}
\begin{proof}
    First, let us rewrite introduce the change of variables $\sigma\doteq \frac{\rho}{a}$ so that
    \begin{align*}
        \int_{R}^{\infty}\rho^{2-k}\frac{a}{(a^2+\rho^2)^2}d\rho
        &= a^{-k}\int_{\frac{R}{a}}^{\infty}\sigma^{2-k}(1+\sigma^2)^{-2}d\sigma
        \\
        &= a^{-k}\left(\int_{\frac{R}{a}}^1\sigma^{2-k}(1+\sigma^2)^{-2}d\sigma + \int_{1}^{\infty}\sigma^{2-k}(1+\sigma^2)^{-2}d\sigma\right) \,.
    \end{align*}
    To estimate the second integral, we notice that $(1+\sigma^2)^{-2} \leq \sigma^{-4}$ for all $\sigma\in [1,\infty)$, so using that $k>-1$, we have
    \begin{align*}
        \int_{1}^{\infty}\sigma^{2-k}(1+\sigma^2)^{-2}d\sigma\leq \int_{1}^{\infty}\sigma^{-2-k}d\sigma = \frac{1}{1+k}.
    \end{align*}
    For the first integral, we now notice that if $\frac{R}{a} \leq \sigma \leq 1$, then $1+\left(\frac{R}{a}\right)^2 \leq 1+\sigma^2\leq 2$, and thus $(1+\sigma^2)^{-2}\leq \left( 1+\left(\frac{R}{a}\right)^2 \right)^{-2}$. Then, using that $k<3$ and $a > R$,
    \begin{align*}
        \int_{\frac{R}{a}}^1\sigma^{2-k}(1+\sigma^2)^{-2}&d\sigma \leq \left( 1+\left(\frac{R}{a}\right)^2 \right)^{-2}\int_{\frac{R}{a}}^1\sigma^{2-k}d\sigma
        \\
        &= \left( 1+\left(\frac{R}{a}\right)^2\right)^{-2}\frac{1}{3-k}\left(1 - \left(\frac{R}{a}\right)^{3-k} \right) \leq \frac{1}{3-k}
    \end{align*}
    and the assertion follows.
\end{proof}
We are now ready to establish the main result of the section. We stress that the orientability hypothesis below is only required to apply \cref{PropPMTforGp} and were \cref{thm: LeeLF} to hold true, either without the spin assumption or allowing for multiple ends, one could immediately drop it.
\begin{theorem}
    \label{thm: Yamabe Problem 3d}
    Let $M$ be an orientable, smooth, closed 3-manifold and $g$ a $W^{2,q}$-Riemannian metric  with $q > 3$ and $\lambda(M, g) > 0$. Then, there exists a Riemannian metric in the conformal class $[\,g\,]_{W^{2,q}}$ of positive constant scalar curvature.
\end{theorem}
\begin{proof}
    Let $\bigl(\hat M, \hat g\bigr)$ be the AE manifold constructed in \cref{Decompactification via Conformal Green's function}. In view of \cref{thm: Aubin-Trudinger-Yamabe} and Proposition \ref{prop: compac-noncompact yamabe correspondence}, all we need to do is to verify that the test function $\psi_a \in W^{1,2}_{-1/2}(\hat M)$ defined in \eqref{eq: test function} satisfies $Q_{\hat g}(\psi_a) < \lambda(\nS^3)$ for some $a > R$ large enough. Using that $\R_{\hat g} \equiv 0$ and $\psi_a$ is constant in $\hat M \setminus \hat M_\infty$, we get
    \begin{align*}
        E_{\hat g}(\psi_a) = 8\int_{\hat M} |\nabla\psi_a|^2_{\hat g} \, d\mu_{\hat g} = 8\int_{\hat M_{\infty}} |\nabla u_a|^2_{\hat g} \, d\mu_{\hat g} \,.
    \end{align*}
    Following \cite[Proposition 7.1]{Lee-Parker}, 
    \begin{align}
        \label{YamabeEnergyAubinBubble}
            E_{\hat g}(\psi_a)
            &= 8\lim_{L \to \infty} \int_{\{R < \rho < L\}} \hat g^{\rho\rho} \partial_\rho u_a \partial_\rho u_a \, \sqrt{\det\hat g} \, \rho^{2} d\omega d\rho \nonumber
            \\
            &= -8 \lim_{L \to \infty}\int_{\{R < \rho < L\}} u_a \partial_\rho\bigl(\rho^{2} \partial_\rho u_a\bigr) \, \hat g^{\rho\rho} \sqrt{\det\hat g}\, d\omega d\rho \nonumber
            \\
            &\quad - 8 \lim_{L \to \infty} \int_{\{R < \rho < L\}} u_a \partial_\rho u_a \partial_\rho \bigl(\hat g^{\rho\rho}\sqrt{\det\hat g}\bigr) \, \rho^{2} d\omega d\rho
            \\
            &\quad + 8 \lim_{L \to \infty} \int_{\partial B_R \cup \partial B_L} u_a \partial_\rho u_a \, \hat g^{\rho\rho} \sqrt{\det\hat g}\; \rho^{2} d\omega \,. \nonumber
    \end{align}
    Let us start computing the first integral. Exploiting that $u_a$ is radial, the Euclidean Laplacian reads $\Delta u_a = \rho^{-2}\partial_\rho(\rho^{2}\partial_\rho u_a)$, so we get
    \begin{align*}
        -8\int_{\{R < \rho < L\}} &u_a \partial_\rho\bigl(\rho^{2} \partial_\rho u_a\bigr) \, \hat g^{\rho\rho} \sqrt{\det\hat g}\, d\omega d\rho
        \\
        &= -8\int_{\{R < \rho < L\}} u_a \Delta u_a \, \hat g^{\rho\rho} \sqrt{\det\hat g}\, dz
        \\
        &=24\int_{\{R < \rho < L\}} u_a^{2^{*}} \hat{g}^{\rho\rho} \sqrt{\det\hat g}\, dz
        \\
        &=24\left(\int_{\{R < \rho < L\}} u_a^{2^{*}} dz\right)^{\frac{2^{*}-2}{2^{*}}}  \left(\int_{\{R < \rho < L\}} u_a^{2^{*}} \Bigl(\hat{g}^{\rho\rho} \sqrt{\det\hat g}\Bigr)^{\frac{2^{*}}{2}} dz\right)^{\frac{2}{2^{*}}}
        \\
        &\leq \lambda(\nS^3) \left(\int_{\{R < \rho < L\}} u_a^{2^{*}} \Bigl(\hat{g}^{\rho\rho} \sqrt{\det\hat g}\Bigr)^{\frac{2^{*}}{2}} dz\right)^{\frac{2}{2^{*}}} \,,
    \end{align*}
    where the second equality is due to \eqref{AubinBubble.1} and the fourth inequality due to \eqref{AubinBubble.2}. Since $\hat g \in AS_\beta(1)$ by \cref{prop: regularity_g_hat}, it follows that
    \begin{align}
        \label{DetExpansion}
        \sqrt{\det\hat{g}} = 1 + \frac{6A}{\rho} + \BO_1(\rho^{-1-\beta}) \qquad \text{and} \qquad \hat{g}^{\rho\rho} = 1 - \frac{4A}{\rho} + \BO_1(\rho^{-1-\beta})
    \end{align}
    as $\rho \to \infty$. This implies, in particular, that
    \begin{align*}
        \hat{g}^{\rho\rho} \sqrt{\det\hat{g}} = (\det\hat{g})^{\frac{1}{6}} + \BO_1(\rho^{-1-\beta}) \,,
    \end{align*}
    and noting that in 3 dimensions $2^{*}=6$, we estimate the first term in \eqref{YamabeEnergyAubinBubble} by
    \begin{align}
        \label{YamabeQuotientIntegral1}
        \lambda(\nS^3)\left(\int_{\hat M_\infty} u_a^{2^{*}} d\mu_{\hat{g}} + \int_{\hat M_\infty} u_a^{2^{*}}O(\rho^{-1-\beta}) dz \right)^{\frac{2}{2^{*}}} \,.
    \end{align}
    Now, set $C_1=C_1(R)$ to be a constant such that $|\BO(\rho^{-1-\beta})|\leq C_1\rho^{-1-\beta}$ and thus
    \begin{align*}
        \Bigl| \int_{\hat M_\infty} &u_a^{2^{*}} \BO(\rho^{-1-\beta}) dz\Bigr| \leq C_1\int_{\hat M_\infty} u_a^{2^{*}}\rho^{-1-\beta} dz 
        \\
        &= 4\pi C_1\int_R^\infty \rho^{1-\beta}\frac{a^3}{(a^2+\rho^2)^3}d\rho = 4\pi C_1 \int_R^L\rho^{1-\beta}\frac{a^2}{(a^2+\rho^2)}\frac{a}{(a^2+\rho^2)^2}d\rho 
        \\
        &\leq 4\pi C_1 \int_R^{\infty}\rho^{-(1+\beta)}\frac{a}{(a^2+\rho^2)^2}\rho^2 d\rho
    \end{align*}
    Observe that $-1 < 1+\beta < 3$ due to $\beta\in (0,1)$, so \cref{PropIntegralEstimateYamabe} implies that
    \begin{align*}
         \left| \int_{\hat M_\infty} u_a^{2^{*}} \BO(\rho^{-1-\beta}) dz\right| \leq C(R,\beta) a^{-1-\beta} \,.
    \end{align*}
    We conclude that the first term in \eqref{YamabeEnergyAubinBubble} can be estimated by
    \begin{align}
        \label{eq: I_1 estimate}
        \begin{split}
            I_1 &\leq \lambda(\nS^3)\Bigl(\|\psi_a\|^{2^{*}}_{L^{2^{*}}(\hat{M},d\mu_{\hat{g}})} + C(R,\beta)a^{-1-\beta} \Bigr)^{\frac{2}{2^{*}}}
            \\
            &\leq \lambda(\nS^3)\|\psi_a\|^{2}_{L^{2^{*}}(\hat{M},d\mu_{\hat{g}})} + \BO(a^{-1-\beta})
        \end{split}
    \end{align}
    as $a \to \infty$.

    Let us go back to \eqref{YamabeEnergyAubinBubble} and estimate the second term on the right-hand side. Appealing again to \eqref{DetExpansion}, we have that
    \begin{equation*}
        \partial_\rho\left(\hat g^{\rho\rho} \sqrt{\det\hat g}\right) = -\frac{2A}{\rho^2} + \BO\bigl(\rho^{-2-\beta}\bigr) \qquad \text{as} \; \rho \to \infty \,.
    \end{equation*}
    Then, using the co-area formula, we get
    \begin{align*}
        -\int_{\hat M_\infty} u_a \partial_\rho u_a \partial_\rho \bigl(\hat g^{\rho\rho}\sqrt{\det\hat g}\bigr) \, &\rho^{2} d\omega d\rho = -\int_R^\infty u_a \partial_\rho u_a\int_{\partial B_\rho} \partial_\rho \bigl(\hat g^{\rho\rho}\sqrt{\det\hat g}\bigr) \rho^2 d\rho \, d\omega
        \\
        &= -4\pi\int_R^\infty u_a \partial_\rho u_a \left(-\frac{2A}{\rho^2} + \BO\bigl(\rho^{-2-\beta}\bigr)\right) \rho^2 d\rho
        \\
        &= 4\pi  \int_R^\infty \rho\frac{a}{(\rho^2 + a^2)^2} \bigl(-2A + \BO(\rho^{-\beta})\bigr) d\rho \,.
    \end{align*}
    The first integral can be computed explicitly via the coordinate change $\sigma = \tfrac{\rho}{a}$ as
    \begin{align*}
        -8\pi A\int_R^\infty \frac{a}{(\rho^2 + a^2)^2} \rho \, d\rho = \frac{-8\pi A}{a}\int_{R/a}^\infty \frac{\sigma}{\bigl(1 + \sigma^2)^{2}} d\sigma = \frac{-4\pi a}{a^2 + R^2} \, A \,,
    \end{align*}
    whereas the second one may be estimated by
    \begin{align*}
        4\pi \int_R^\infty \rho\frac{a}{(\rho^2 + a^2)^2} \BO(\rho^{-\beta}) d\rho \leq 4\pi C_1 \int_R^\infty \rho^{-(1+\beta)}\frac{a}{(\rho^2 + a^2)^2} \rho^2 d\rho \leq C(R,\beta) a^{-1-\beta}
    \end{align*}
    again using \cref{PropIntegralEstimateYamabe}. We conclude that the second term in \eqref{YamabeEnergyAubinBubble} can be estimated by
    \begin{align}
        \label{YamabeQuotientIntegral2.3}
        I_2 \leq -C(R)A a^{-1} + \BO\bigl(a^{-1-\beta}\bigr) \qquad \text{as} \quad a \to \infty \,.
    \end{align}

    For the last term in the right-hand-side of \eqref{YamabeEnergyAubinBubble}, observe first that the $\partial B_L$ boundary term vanishes as $L \to \infty$, as $u_a\partial_\rho u_a = \BO(\rho^{-3})$ as $\rho \to \infty$ for each fixed $a$. The interior boundary instead can be estimated, using that $u_a\partial_\rho u_a = \BO(a^{-3})$ as $a \to \infty$ for fixed $\rho$, by
    \begin{align}
        \label{eq: estimate I_3}
        I_3 \leq 8 \sup_{\hat{M}_{\infty}}\left|\hat g^{\rho\rho}\sqrt{\det\hat g}\right| \int_{\partial B_R} u_a \partial_\rho u_a \, \rho^2 d\omega = \BO\bigl(a^{-3}\bigr)
    \end{align}
    as $a \to \infty$. Hence, coming back to \ref{YamabeEnergyAubinBubble} and combining \eqref{eq: I_1 estimate}, \eqref{YamabeQuotientIntegral2.3} and \eqref{eq: estimate I_3}, we establish
    \begin{align}
        \label{YamabeEnergyAubinBubbleFinal}
        E_{\hat g}(\psi_a) \leq  \Lambda \|\psi_a\|_{L^{2^*}(\hat M)} - C(R) A a^{-1} + \BO\bigl(a^{-1-\beta}\bigr) \qquad \text{as} \quad a \to \infty
    \end{align}
    In light of \cref{PropPMTforGp} and  \cref{thm: A=0 case}, we know that $A>0$ unless $(M,g)$ is $W^{3,q}$-conformal to $\nS^3$. In latter case we are done, while if $A>0$, the inequality \eqref{YamabeEnergyAubinBubbleFinal} implies that $Q_{\hat g}(\psi_a) < \Lambda$ for $a$ large enough. In this case, \cref{thm: Aubin-Trudinger-Yamabe} grants the assertion.
\end{proof}
Using the regularity theory developed in \cref{Analytical Results}, we finally demonstrate the main result of the work \cref{theorem A}:
\begin{proof}[Proof of \cref{theorem A}]
    We prove the Theorem by induction in $k$. The case $k = 2$ is proven in \cref{thm: Yamabe Problem 3d}, so assume that the statement holds for some integer $k \geq 2$. In particular this implies the existence of a conformal factor $u \in W^{k,q}(M)$ satisfying
    \begin{equation*}
        -8\Delta_g u = \Lg u - \R_g u = \lambda u^{2^*-1} - \R_g u \,.
    \end{equation*}
    Now, if $g \in W^{k+1,q}(T_2M)$, then $\R_g \in W^{k-1,q}(M)$ and consequently $\Delta_g u \in W^{k-1,q}(M)$. But then \cref{thm: main global elliptic regularity} implies that $u \in W^{k+1,q}(M)$ and the conformal metric $\bar g = u^{2^*-2} g$ is of class $W^{k+1,q}(T_2M)$.
\end{proof}

