\section{Sobolev Multiplication Properties}
In this section, we collect some multiplication properties of Sobolev functions, which are repeatedly employed throughout the text. Closely related multiplication properties can be found, for instance in \cite[Chapter 9]{PalaisBook} and \cite{HolstBehzadanMult} (see also \cite[Corollary 3]{HolstBehzadanSobSpaces}), and for the case of positive integer Sobolev spaces also in \cite[Chapter VI]{ChoquetDeWitt} for example. The case treated below does not seem to be fully treated by any of the previous references, but it is almost covered by the first-named author in \cite[Theorem 2.2]{avalos2024sobolev}. The only difference is that the alternative conditions \eqref{MultiplicationConditions.2} and \eqref{MultiplicationConditionsDuals.2} are not considered. 
Since the proof is essentially the same, we skip it and we just refer the reader to \cite[Theorem 2.2]{avalos2024sobolev}.
\begin{theorem}
    \label{SobolevMultLocal}
    Consider a smooth, bounded domain $\Omega \subset \nR^n$ and fix $k_1,k_2,p_1,p_2,p \in \nR$ and $k \in \nZ$ such that $k_1 + k_2 \geq 0$, $k_1,k_2 \geq k$ and $1 < p_1,p_2,p \leq \infty$. If $k_1,k_2,k\geq 0$, then the continuous embeddings
    \begin{align}                   \label{LocalMultiPropPositive}
        H^{k_1,p_1}(\Omega)\otimes H^{k_2,p_2}(\Omega)\hookrightarrow H^{k,p}(\Omega) \,,
    \end{align}
    \begin{align}               \label{LocalMultiPropPositive0}
        H^{k_1,p_1}(\Omega)\otimes H_0^{k_2,p_2}(\Omega)\hookrightarrow H_0^{k,p}(\Omega)
    \end{align}
    hold provided that
    \begin{subequations}
        \begin{align}
            k_i-k&\geq n\left(\frac{1}{p_i} - \frac{1}{p}\right) \quad \text{and} \quad k_1+k_2-k> n\left(\frac{1}{p_1} + \frac{1}{p_2} - \frac{1}{p} \right) \,, \quad \text{or} \label{MultiplicationConditions}
            \\
            k_i-k&> n\left(\frac{1}{p_i} - \frac{1}{p}\right) \quad \text{and} \quad k_1+k_2-k\geq n\left(\frac{1}{p_1} + \frac{1}{p_2} - \frac{1}{p} \right) \,. \label{MultiplicationConditions.2}
        \end{align}
        \label{eqn:all-lines}
    \end{subequations}
    If $\min\{k_1,k_2\}<0$ instead, then \eqref{LocalMultiPropPositive} holds if additionally one imposes $p_i<\infty$ and
    \begin{subequations}
        \begin{align} 
            k_1+k_2&\geq n\left( \frac{1}{p_1}+\frac{1}{p_2} - 1 \right) \quad \text{whenever \eqref{MultiplicationConditions} is satisfied} , \text{ or }\label{MultiplicationConditionsDuals}
            \\
            k_1+k_2&> n\left( \frac{1}{p_1}+\frac{1}{p_2} - 1 \right) \quad \text{whenever \eqref{MultiplicationConditions.2} is satisfied} \,.\label{MultiplicationConditionsDuals.2}
        \end{align}
        \label{eqn:all-lines}
    \end{subequations}
    \end{theorem}


