\section{Sobolev diffeomorphisms}
\label{IFTSobolevAppendix}
It is a consequence of the \emph{inverse function theorem} that the inverse of an invertible $C^k$-map is also $C^k$.
The analogue statement for Sobolev regularity does not seem to be addressed in the literature. The main purpose of this appendix is to fill that gap.
\begin{theorem}
    \label{LemmaInvFunctThmSobReg}
    Let $\phi : \Omega \to \Omega'$ be a $C^1$-diffeomorphism between bounded domains of $\nR^n$ with smooth boundary. Suppose that $\phi \in W^{k,q}(\Omega,\Omega')$ for $k \geq 3$ and $q > \tfrac{n}{2}$. Then, $\phi^{-1} \in W^{k,q}_{loc}(\Omega',\Omega)$. 
\end{theorem}
In the proof, we will employ the following Morrey inequality. It is essentially contained in the proof of \cite[Lemma 4.28]{AdamsFournierBook}, but since we need to keep track of the explicit dependence of the constant, we spell it out here.
\begin{lemma}
    \label{MorreyInequalThm}
    For each $p > n$ there is a positive constant $C=C(n,p)$ such that
    \begin{equation*}
        |u(x)-u(y)| \leq C(n,p) \|\partial u\|_{L^p\bigl(B_{4\sqrt{n}r}(0)\bigr)} |x-y|^{1-\frac{n}{p}}
    \end{equation*}
    holds all $x,y \in B_{r}(0)$ and all $u \in W^{1,p}(B_{4\sqrt{n}r}(0))$\footnote{As it is evident in the proof, the dependence on the dimension $n$ in the radius can be removed by considering the cube $Q_{4r} \subset B_{4 \sqrt{n}r}$ instead of the ball, along the lines of \cite[Lemma 4.28]{AdamsFournierBook}.}.
\end{lemma}
\begin{proof}
    By density, it suffices to show the statement for $u \in C^1(B_{4\sqrt{n}r}(0))$. Following the proof of \cite[Lemma 4.28]{AdamsFournierBook}, fix points $x,y \in B_r(0)$  
    and a closed cube $Q_\sigma(\xi)$ of edge-length $\sigma \doteq |x-y|$ and center $\xi \in B_r(0)$ containing $x$ and $y$. There holds 
    \begin{align*}
        |u(x)-u(z)| &\leq \sqrt{n}\sigma \int_0^1|\partial u(x+t(z-x))|dt
    \end{align*}
    for any point $z \in Q_\sigma(\xi)$, and therefore
    \begin{align*}
        \left|u(x) - \frac{1}{\sigma^n}\int_{Q_\sigma(\xi)}u(z)dz\right| &\leq \frac{1}{\sigma^n}\int_{Q_\sigma(\xi)}|u(x)-u(z)|dz
        \\
        &\leq \frac{\sqrt{n}}{\sigma^{n-1}}\int_0^1\int_{Q_\sigma(\xi)}|\partial u(x+t(z-x))|dz \, dt
        \\
        &= \frac{\sqrt{n}}{\sigma^{n-1}}\int_0^1\left(\int_{Q_{t\sigma}(x+t(\xi-x))}|\partial u(\zeta)| d\zeta\right) t^{-n} dt \,.
    \end{align*}
    Notice that $Q_{t\sigma}(x+t(\xi-x)) \subset Q_{4r}(0) \subset B_{4\sqrt{n}r}(0)$ for any fixed $t\in [0,1]$ and thereby using Hölder's inequality we estimate
    \begin{align*}
        \int_{Q_{t\sigma}(x+t(\xi-x))}|\partial u(\zeta)|d\zeta &\leq \|\partial u\|_{L^p\left(B_{4\sqrt{n}r}(0)\right)}(t\sigma)^{\frac{n}{p'}}
    \end{align*}
    and find
    \begin{align*}
        \left|u(x) - \frac{1}{\sigma^n}\int_{Q_\sigma(\xi)}u(z)dz\right| &\leq C(n,p) \sigma^{1-\frac{n}{p}}\|\partial u\|_{L^p(B_{4\sqrt{n}r}(0))} \,.
    \end{align*}
    The same computations hold with $x$ replaced with $y$, so the assertion follows from the triangle inequality.
\end{proof}
\begin{proof}[Proof of \cref{LemmaInvFunctThmSobReg}]
    It suffices to show that around any $p' \in \Omega'$, we can find a neighborhood $U' \subset \subset \Omega'$ such that $\psi \doteq \phi^{-1} \in W^{k,q}(U')$. Given such $p'$, let $p \doteq \psi(p') \in \Omega$ and define $\Omega_p \doteq \{x \in \Omega \;:\; 2d(x,\partial\Omega) > d(p,\partial\Omega)\}$ as well as $\Omega_p' \doteq \phi(\Omega_p)$. 
    Note that $B_r(p) \subset B_{16\sqrt{n} r}(p) \subset\subset \Omega_p$ for $r > 0$ small enough by the openness of $\Omega_p$. We show that indeed $\psi \in W^{k,q}(\phi(B_r(p)))$ for $r$ sufficiently small. 

    For any $x \in B_r(p)$ we may write the linear map $D\phi_x : T\nR^n_x \to T\nR^n_{\phi(x)}$ like
    \begin{equation}
        \label{eq: Phi def}
        D\phi_x = D\phi_p \cdot \bigl(\Id_p - D\phi^{-1}_p \cdot (D\phi_p - D\phi_x)\bigr) \,.
    \end{equation}
    Set now $\Phi(x) \doteq D\phi^{-1}_p \cdot (D\phi_p-D\phi_x)$ and note that $\Phi\in W^{2,q}(\Omega,\GL(n))$ by the hypothesis $\phi \in W^{3,q}(\Omega,\Omega')$. Due to the invertibility of $D\phi_x$ for every $x \in \Omega$, by \eqref{eq: Phi def}, we have that $\Id_p - \Phi(x)$ is invertible as well at each point  $x \in \Omega$. This gives
    \begin{align*}
        D\psi_y&=D(\phi^{-1})_y = [D\phi_{\psi(y)}]^{-1}=[\mathrm{Id}_{\psi(y)}-\Phi_{\psi(y)}]^{-1}\cdot D\phi_p^{-1}
    \end{align*}
    for any $y \in \phi(B_r(p))$. Using the operator $Au \doteq u \circ \psi$, we rewrite it simply as
    \begin{align}
        \label{NeumannSeries.0}
        D\psi &= [A(\mathrm{Id} - \Phi)]^{-1}\cdot D\phi_p^{-1} \,.
    \end{align}

\medskip
    \textit{Step 1.} Let us show that there exists some $t > n$ and $r > 0$ small enough such that the sequence of partial sums $\{\Theta_j\doteq \sum_{l=0}^{j}(A\Phi)^l\}_{j=0}^{\infty}$ converges 
    in $W^{1,t}(\phi(B_r(p)))$ and moreover
    \begin{equation}
        \label{eq: claim 1}
        \sum_{l=0}^\infty(A\Phi)^l = [A(\mathrm{Id} - \Phi)]^{-1}
    \end{equation}
    holds on $\phi(B_r(p))$. Fix some $t > n$ such that the embedding $W^{2,q}(\Omega) \hookrightarrow W^{1,t}(\Omega)$ holds and for a fixed $r> 0$, let $0 \leq \eta_r \leq 1$ be a smooth cut-off function satisfying

    \begin{equation*}
        \eta_r|_{B_r(p)} \equiv 1 \,, \qquad \supp\eta_r \subset\subset B_{2r}(p) \,, \qquad |\partial\eta_r| \leq \frac{c_n}{r} \,. 
    \end{equation*}
    with fixed constant $c_n > 0$. For each $l \in \nN$, we estimate
    \begin{align}
        \label{estimate_APhi}
        \begin{split}
        \|(A\Phi)^l\|_{W^{1,t}(\phi(B_r(p))} & \leq \| (A(\eta_r\Phi))^l\|_{W^{1,t}(\Omega_p')} \leq C_0^{l-1}\|A(\eta_r\Phi)\|^{l}_{W^{1,t}(\Omega_p')} 
        \\
        &\leq C_0^{l-1}C_1^l \|\eta_r\Phi\|^{l}_{W^{1,t}(\Omega_p)} 
        = C_0^{l-1}C_1^l \|\eta_r\Phi\|^{l}_{W^{1,t}(B_{2r}(p))}
        \end{split}
    \end{align}
    where $C_0 = C_0(n,t,\Omega_p')$ is the Sobolev constant of the multiplication $W^{1,t}(\Omega_p') \otimes W^{1,t}(\Omega_p') \hookrightarrow W^{1,t}(\Omega_p')$ and $C_1 = C_1(n,t,\Omega_p,\Omega_p')$ is the continuity constant of the map $A : W^{1,t}(\Omega_p) \to W^{1,t}(\Omega_p')$ given in \cite[Theorem 3.41]{AdamsFournierBook}. Since neither of them depends on $r$, we aim to make the right-hand side arbitrarily small by choosing $r$ sufficiently small. We first estimate
    \begin{align}
        \label{InvFThmLocal.1}
        \begin{split}
        \|\eta_r\Phi\|^t_{W^{1,t}(B_{2r}(p))}& = \|\eta_r\Phi\Vert^t_{L^{t}(B_{2r}(p))} + \|\eta_r\partial\Phi + \partial\eta_r\Phi \|^t_{L^{t}(B_{2r}(p))} 
        \\
        &\leq 2^{t-1}\left(\Vert \Phi\Vert^t_{W^{1,t}(B_{2r}(p))} + \Vert \partial\eta_r\Phi\Vert^t_{L^{t}(B_{2r}(p))} \right) \,,
        \end{split}
    \end{align}
    where we used that for any $a, b >0$, it holds $(a + b)^t \leq 2^{t-1} (a^t + b^t)$ and that $\vert \eta_r \vert \leq 1$. Now, to estimate the second term, we can use the Morrey inequality from \cref{MorreyInequalThm} and the fact that $\Phi(p)=0$, as follows 
    \begin{align}
        \label{MorreyEstimate.0}
        \nonumber
        \|\partial\eta_r\Phi\|^t_{L^{t}(B_{2r}(p))} &\leq c^t_n \int_{B_{2r}(p)}r^{-t}|\Phi(x)|^t dx
        \\
        \nonumber
        &= c^t_n r^{-t}\int_{B_{2r}(p)}\left(\frac{|\Phi(x)-\Phi(p)|}{|x-p|^{1-\frac{n}{t}}}\right)^t|x-p|^{t(1-\frac{n}{t})}dx
        \\
        &\leq c^t_n r^{-t}\Big(\sup_{x,y\in B_{2r}(p)}\frac{|\Phi(x)-\Phi(y)|}{|x-y|^{1-\frac{n}{t}}}\Big)^t\int_{B_{2r}(0)}|x|^{t-n}dx
        \\
        \nonumber
        &= c^t_n\frac{2^t\omega_{n-1}}{t}\Big(\sup_{x,y\in B_{2r}(p)}\frac{|\Phi(x)-\Phi(y|}{|x-y|^{1-\frac{n}{t}}}\Big)^t
        \\
        \nonumber
        &\leq C(n,t) \|\partial\Phi\|_{L^t\left( B_{8\sqrt{n} r}(p)\right)}^t \leq C(n,t) \|\Phi\|_{W^{1,t}\left( B_{8\sqrt{n} r}(p)\right)}^t \,.
    \end{align}
    Combining \eqref{estimate_APhi}, \eqref{InvFThmLocal.1} and \eqref{MorreyEstimate.0}, and assuming without loss of generality that $C_0 \geq 1$, we find that for each $l \in \nN$ there holds
    \begin{equation}
        \label{estimate_APhi_Phi}
         \|(A\Phi)^l\|_{W^{1,t}(\phi(B_r(p))} \leq \left( C_0 \,C_1 \, C_2 \| \Phi \|_{W^{1, t}\left( B_{8\sqrt{n} r}(p)\right)} \right)^l \,.
    \end{equation}
    Since $C_0, C_1$ and $C_2$ only depend on $n, t, \Omega_p$ and $\Omega_p'$, we can fix
    $r = r(n, t, \Omega_p, \Omega_p') > 0$ small enough so that $b \doteq C_0 \,C_1 \, C_2 \|\Phi\|_{W^{1,t}\left( B_{8\sqrt{n} r}(p)\right)} < 1$. This implies that 
    \begin{equation*}
        \lim_{i, j \to \infty} \|\Theta_j-\Theta_i\|_{W^{1,t}(\phi(B_r(p))} = 0 \,,
    \end{equation*}
    being it controlled by the tail of a geometric series
    \begin{align*}
        \|\Theta_j-\Theta_i\|_{W^{1,t}(\phi(B_r(p))} \leq \sum_{l=i}^j \|(A\Phi)^l\|_{W^{1,t}(\phi(B_r(p))} \leq \sum_{l=i}^j  b^l\,.
    \end{align*}
    We conclude that $\{\Theta_j\}_{j=0}^\infty \subset W^{1,t}(\phi(B_r(p)))$ is a Cauchy sequence and thus the Neumann series on the left-hand side of \eqref{eq: claim 1} is convergent. In particular, it converges pointwise and we have 

    \begin{equation}
        \begin{split}
        \label{estimate_almost_claim1}
        (\Theta_j)(y) \cdot (\mathrm{Id}_{\psi(y)} - (A\Phi)_y) &=(\mathrm{Id}_{\psi(y)} + (A\Phi)_y + \cdots + (A\phi)_y^j)(\mathrm{Id}_{\psi(y)}-(A\Phi)_y)
        \\
        &=\mathrm{Id}_{\psi(y)} - (A\Phi)^{j+1}_y,
        \end{split}
    \end{equation}
    To show that $\lim_{j\to\infty}(A\Phi)^{j+1}_y = 0$, we use the same cut-off trick as in \eqref{estimate_APhi} to obtain
    \begin{align*}
        \|(A\Phi)^{j+1}\|_{C^0(\phi(B_{r}(p)))} & \leq C_3\|(A\eta_{r}\Phi)^{j+1}\|_{W^{1,t}(\phi(B_{2r}(p)))}\\
        &\leq C_3 \left( C_0 \,C_1 \, C_2 \|\Phi\|_{W^{1, t}\left( B_{16\sqrt{n} r}(p)\right)} \right)^{j+1}
    \end{align*}
    with $C_3=C_3(n,t,\Omega_p')$ being the Sobolev embedding constant $W^{1,t}(\Omega_p') \hookrightarrow C^0(\Omega_p')$ and the last inequality holds due to \eqref{estimate_APhi_Phi}. Letting $r$ be so small that $\|\Phi\|_{W^{1,t}\left( B_{16\sqrt{n} r}(p)\right)} < \tfrac{1}{2C_0C_1C_2}$, we obtain
    \begin{align*}
        \|(A\Phi)^{j+1}\|_{C^0(\phi(B_{r}(p)))} \leq \frac{C_3}{2^{j+1}} \to 0
    \end{align*}
    as $j \to \infty$. Combining this with \eqref{estimate_almost_claim1} concludes the proof of the identity \eqref{eq: claim 1}.

     \medskip
    \textit{Step 2.}
    In view of \eqref{NeumannSeries.0}, the previous step implies that $\psi \in W^{2,t}(\phi(B_r(p)))$ for some $t > n$. Next, we promote it to $\psi \in W^{3,q}(\phi(B_r(p)))$. By the chain rule,
    \begin{align}
        \label{NeumannSeries.3}
        D\Theta_j &= \sum_{l=0}^{j}\sum_{a=1}^lA\Phi\cdots A(D\Phi)\cdot_a D\psi\cdots A\Phi \,,
    \end{align}
    where above the notation $A(D\Phi)\cdot_a D\psi$ denotes that, at some given $y\in \phi(B_r(p))$, the linear map $A(D\Phi)\cdot_a D\psi$ appears in the ``$a$-th factor" in the composition of $l$-linear maps $(A\Phi)_y\cdots A(D\Phi)\cdot_a D\psi\cdots (A\Phi)_y$ with $(l-1)$ factors given by $(A\Phi)_y$. From the $W^{1,t}(\phi(B_r)) \otimes W^{1,q}(\phi(B_r)) \hookrightarrow W^{1,q}(\phi(B_r))$ multiplication and \eqref{estimate_APhi_Phi}, we see that
    \begin{align*}
        &\|D\Theta_j - D\Theta_i\|_{W^{1,q}(\phi(B_r(p)))} \leq \sum_{l=i}^{j}\sum_{a=1}^l\| A\Phi\cdots A(D\Phi)\cdot_a D\psi\cdots A\Phi\|_{W^{1,q}(\phi(B_r(p)))}
        \\
        &\leq C(n,q,r) \|A(D\Phi)\|_{W^{1,q}(\phi(B_{r}(p)))} \|D\psi\|_{W^{1,t}(\phi(B_{r}(p)))} \sum_{l=i}^{j} l \|(A\Phi)^{l-1}\|_{W^{1,t}(\phi(B_{r}(p)))} 
        \\
        &\leq C(n,q,r) \|A(D\Phi)\|_{W^{1,q}(\phi(B_{r}(p)))} \|D\psi\|_{W^{1,t}(\phi(B_{r}(p)))} \sum_{l=i}^{j} l \, b^{l-1} \,.
    \end{align*}
    Since $\phi \in W^{3,q}(B_r(p)) \subset W^{2,t}(B_r(p)) \subset C^{1}(B_r(p))$ by hypothesis and having shown that $\psi \in W^{2,t}(\phi(B_r(p))) \subset C^1(\phi(B_r(p)))$ in \textit{Step 1}, it follows that $D\Phi \in W^{1,t}(B_r(p))$ and thus $A(D\Phi) \in W^{1,t}(\phi(B_r(p))$ by \cite[Theorem 3.41]{AdamsFournierBook}. We deduce that the terms outside the sum above are finite for $r>0$ small enough, as chosen in the previous step.
    Setting $b_l \doteq l \, b^{l-1}$ we observe that due to $b < 1$,
    \begin{equation}
        \label{eq: series convergence criteria}
        \frac{b_{l+1}}{b_l} = \frac{l+1}{l}b < 1
    \end{equation}
    for $l$ large enough, which implies that $\lim_{i,j\to\infty} \sum_{l=i}^jb_l = 0$. We conclude that $\{\Theta_j\}_{j=0}^\infty$ 
    is Cauchy and thus convergent in $W^{2,q}(\phi(B_r))$. In light of \eqref{NeumannSeries.0} and \eqref{eq: claim 1}, we find 


    \noindent
    that $\psi \in W^{3,q}(\phi(B_r(p)))$.

    Having established the $k=3$ case, we proceed by induction: assume $\phi \in W^{k,q}(\Omega)$ implies that $\{\Theta_j\}_{j=0}^\infty$ converges in $W^{k-1,q}(\phi(B_r))$ and $\psi \in W^{k,q}(\phi(B_r))$, and let us show the same holds for $k+1$.
    Since $\phi \in W^{k+1,q}(\Omega)$ by assumption, the induction hypothesis implies that $\psi \in W^{k,q}_{loc}(\Omega')$. Along the lines of \textit{Step 1} above, we first estimate
    \begin{align*}
        \|D^{k-2}&\Theta_i - D^{k-2}\Theta_j\|_{W^{1,t}(\phi(B_r(p))} \leq \sum_{l=i}^j \sum_{|\alpha|=k-2} \|D^{\alpha_1}(A\Phi) \cdots D^{\alpha_l}(A\Phi)\|_{W^{1,t}(\phi(B_r(p))} \,,
    \end{align*}
    where $\alpha = (\alpha_1,\ldots,\alpha_l)$ is a multi-index and $i >> k$. Observe that
    \begin{align*}
        &\|D^{\alpha_1}(A\Phi) \cdots D^{\alpha_l}(A\Phi)\|_{W^{1,t}(\phi(B_r(p))} 
        \\
        &\leq C^{k-2}_{ttt}\|(A\Phi)^{l-(k-2)}\|_{W^{1,t}(\phi(B_r(p))}\|D^{\alpha_{m_1}}(A\Phi)\|_{W^{1,t}(\phi(B_r(p))} \cdots \|D^{\alpha_{m_{k-2}}}(A\Phi)\|_{W^{1,t}(\phi(B_r(p))}
        \\
        &\leq C^{k-2}_{ttt} \|(A\Phi)^{l-(k-2)}\|_{W^{1,t}(\phi(B_r(p))} \|A\Phi\|_{W^{k-1,t}(\phi(B_r(p))}^{k-2}
    \end{align*}
    with $C_{ttt}=C_{ttt}(n,t,r)$ being the $W^{1,t}(\phi(B_r)) \otimes W^{1,t}(\phi(B_r)) \hookrightarrow W^{1,t}(\phi(B_r))$ multiplication constant and thereby\footnote{The binomial $\binom{l-1+p}{l-1}$ equals to the number of solutions to $\alpha_1+\ldots+\alpha_l=p$ with $\alpha_i \in \nN_0$.}
    \begin{align*}
        \|D^{k-2}&\Theta_i - D^{k-2}\Theta_j\|_{W^{1,t}(\phi(B_r(p))} 
        \\
        &\leq C_{ttt}^{k-2}\|A\Phi\|_{W^{k-1,t}(\phi(B_r(p))}^{k-2} \sum_{l=i}^j \sum_{|\alpha|=k-2} \|(A\Phi)^{l-(k-2)}\|_{W^{1,t}(\phi(B_r(p))}
        \\
        &= C_{ttt}^{k-2}\|A\Phi\|_{W^{k-1,t}(\phi(B_r(p))}^{k-2} \sum_{l=i}^j \binom{l+k-3}{l-1} \|(A\Phi)^{l-(k-2)}\|_{W^{1,t}(\phi(B_r(p))} \,.
    \end{align*}
    A simple calculation shows that $\binom{l+k-3}{l-1} \leq (l+k-3)^{k-2}$, which combined with \eqref{estimate_APhi_Phi} yields, for $r$ sufficiently small,
    \begin{align*}
        \|D^{k-2}&\Theta_i - D^{k-2}\Theta_j\|_{W^{1,t}(\phi(B_r(p))} \leq C_{ttt}^{k-2}\|A\Phi\|_{W^{k-1,t}(\phi(B_r(p))}^{k-2} \sum_{l=i}^j (l+k-3)^{k-2} b^l
    \end{align*}
    where $b<1$. Now, since $\phi \in W^{k+1,q}(\Omega_p) \subset W^{k,t}(\Omega_p) \subset C^{k-1}(\Omega_p)$ by hypothesis, $\Phi \in W^{k-1,t}(\Omega_p)$ and thus $A\Phi \in W^{k-1,t}(\Omega_p')$ by \cite[Theorem 3.41]{AdamsFournierBook}. We deduce that $C_{ttt}\|A\Phi\|_{W^{k-1,t}(\phi(B_r(p))}$ is finite for fixed small $r>0$. On the other hand, the same reasoning as in \eqref{eq: series convergence criteria} shows that the above is the tail of a convergent series, allowing us to conclude that 
    \begin{align*}
        \lim_{i,j\to\infty}\|D^{k-2}&\Theta_i - D^{k-2}\Theta_j\|_{W^{1,t}(\phi(B_r(p))} = 0 \,.
    \end{align*}
    This, combined with the inductive hypothesis, establishes the $W^{k-1,t}$-convergence of $\{\Theta_j\}_{j=0}^\infty$ and hence $\psi \in W^{k,t}(\phi(B_r(p)))$. In order to promote $\psi \in W^{k+1,q}(\phi(B_r(p)))$, similar to \textit{Step 2} above, we now estimate
    \begin{align*}
        \|D^{k-1}&\Theta_i - D^{k-1}\Theta_j\|_{W^{1,q}(\phi(B_r(p))} \leq \sum_{l=i}^j \|D^{k-1}(A\Phi)^l\|_{W^{1,q}(\phi(B_r(p))}
        \\
        &\leq C_{tqq} \|D^{k-1}(A\Phi)\|_{W^{1,q}(\phi(B_r(p))} \sum_{l=i}^j l \|(A\Phi)^{l-1}\|_{W^{1,t}(\phi(B_r(p))}
        \\
        &\qquad + \sum_{l=i}^j\sum_{\substack{|\alpha|=k-1 \\ \alpha_m \neq k-1}} \|D^{\alpha_1}(A\Phi) \cdots D^{\alpha_l}(A\Phi)\|_{W^{1,q}(\phi(B_r(p))} \,,
    \end{align*}
    where $C_{tqq}=C_{tqq}(n,q,t,r)$ is the $W^{1,t}(\phi(B_r)) \otimes W^{1,q}(\phi(B_r)) \hookrightarrow W^{1,q}(\phi(B_r))$ multiplication constant.
    Now, we observe that
    \begin{align*}
        \|D^{k-1}(A\Phi)\|_{W^{1,q}(\phi(B_r(p))} &\leq \|D(A\Phi)\|_{W^{k-1,q}(\phi(B_r(p))}
        \\
        &\leq C_{tqq}\|A(D\Phi)\|_{W^{k-1,q}(\phi(B_r(p))} \|D\psi\|_{W^{k-1,t}(\phi(B_r(p))}
    \end{align*}
    where we used the induction hypothesis combined with \cite[Theorem 3.41]{AdamsFournierBook} giving $A(D\Phi) \in W^{1-1, q}(\phi(B_r(p)))$ and  the promotion $\psi \in W^{k,t}(\phi(B_r(p)))$ performed in the previous step.
    In addition, we estimate for $\alpha_m < k-1$
    \begin{align*}
        &\|D^{\alpha_1}(A\Phi) \cdots D^{\alpha_l}(A\Phi)\|_{W^{1,q}(\phi(B_r(p))} 
        \\
        &\leq C^{k-1}_{ttq}\|(A\Phi)^{l-(k-1)}\|_{W^{1,t}(\phi(B_r(p))}\|D^{\alpha_{m_1}}(A\Phi)\|_{W^{1,t}(\phi(B_r(p))} \cdots \|D^{\alpha_{m_{k-1}}}(A\Phi)\|_{W^{1,t}(\phi(B_r(p))}
        \\
        &\leq C^{k-1}_{ttq} \|(A\Phi)^{l-(k-1)}\|_{W^{1,t}(\phi(B_r(p))} \|A\Phi\|_{W^{k-1,t}(\phi(B_r(p))}^{k-1}
    \end{align*}
    where $C_{ttq}=C_{ttq}(n,q,t,r)$ is the $W^{1,t}(\phi(B_r)) \otimes W^{1,t}(\phi(B_r)) \hookrightarrow W^{1,q}(\phi(B_r))$ multiplication constant.
     We then obtain
    \begin{align*}
        \|D^{k-1}&\Theta_i - D^{k-1}\Theta_j\|_{W^{1,t}(\phi(B_r(p))} 
        \\
        &\leq C_{tqq}^2 \|A(D\Phi)\|_{W^{k-1,q}(\phi(B_r(p))} \|D\psi\|_{W^{k-1,t}(\phi(B_r(p))} \sum_{l=i}^j l \|(A\Phi)^{l-1}\|_{W^{1,t}(\phi(B_r(p))}
        \\
        &\quad + C^{k-1}_{ttq}\|A\Phi\|_{W^{k-1,t}(\phi(B_r(p))}^{k-1} \sum_{l=i}^j \binom{l+k-2}{l-1} \|(A\Phi)^{l-(k-1)}\|_{W^{1,t}(\phi(B_r(p))} \,.
    \end{align*}
    By the same reasoning as above, knowing now that $\psi \in W^{k,t}(\phi(B_r(p)))$, one concludes that $\{\Theta_j\}_{j=0}^\infty$ converges in $W^{k,q}(\phi(B_r(p)))$ and hence $\psi \in W^{k+1,q}(\phi(B_r(p)))$.
\end{proof}

Likewise, one can show an analogue of \cref{LemmaInvFunctThmSobReg} for coordinates at infinity using weighted Sobolev spaces:
\begin{theorem}
    \label{LemmaInvFunctThmSobRegAsymptotic}
    Let $\phi : \nR^n \setminus \Omega \to \nR^n \setminus \Omega'$ be a $C^1$-diffeomorphism, where $\Omega,\Omega' \subset \nR^3$ are bounded domains. Suppose that $\phi-\Id \in W^{k,q}_{-\varepsilon}(\nR^n\setminus\Omega)$ for $k \geq 2$, $q > n$ and $\varepsilon > 0$. Then, $\phi^{-1} - \Id \in W^{k,q}_{-\varepsilon}(\nR^n\setminus\Omega'')$ for some $\Omega''\supset\supset\Omega'$.
\end{theorem}
\begin{proof}
    Name $v \doteq \Id - \phi$, $\psi \doteq \phi^{-1}$ and note that since $v \in W^{k,q}_{-\varepsilon}(\nR^n\setminus\Omega)$ by hypothesis, for any $\delta > 0$ we can find $R > 0$ large enough so that $\|v\|_{C^1_{-\varepsilon}(\nR^n \setminus B_R)} < \delta$. In particular, we can ensure that
    \begin{equation*}
        |\phi(x)| \leq 2|x| \qquad \text{and} \qquad |Dv_x| < 1
    \end{equation*}
    hold for any $x \in \nR^n \setminus B_R$. In view of $D\phi_x = \Id - Dv_x$, we may then write for each $y \in \nR^n \setminus \phi(B_R)$

    \begin{equation*}
        D\psi_y = (D\phi_{\psi(y)})^{-1} = \sum_{l=0}^\infty (Dv_x)^{l} = \Id + \sum_{l=1}^\infty (ADv)_y^{l} \,,
    \end{equation*}
    where $Au \doteq u \circ \psi$. Denote $\Phi \doteq Dv$ and observe that 
    \begin{align*}
        \sum_{l=1}^j&\|(A\Phi)^l\|_{C^0_{-1-\varepsilon}(\nR^n \setminus \phi(B_R))} \leq \sum_{l=1}^j \|A\Phi\|^l_{C^0_{-1-\varepsilon}(\nR^n \setminus \phi(B_R))} 
        \\
        &= \sum_{l=1}^j \sup_{y \in \nR^n \setminus \phi(B_R)}|\Phi(\psi(y))|^l|y|^{l(1+\varepsilon)} \leq \sum_{l=1}^j \sup_{x \in \nR^n \setminus B_R}|\Phi(x)|^l|\phi(x)|^{l(1+\varepsilon)}
        \\
        &\leq \sum_{l=1}^j \Bigl(2^{1+\varepsilon} \|\Phi\|_{C^0_{-1-\varepsilon}(\nR^n \setminus B_R)}\Bigr)^l \,,
    \end{align*}
    which shows that, up to making $R>0$ larger, the sequence of partial sums $\{\Theta_j \doteq \sum_{l=1}^j(A\Phi)^l\}_{j=1}^{\infty}$ converges in $C^0_{-1-\varepsilon}(\nR^n \setminus\phi(B_R))$. In turn, this grants $L^q_{-\varepsilon}$-convergence, perhaps for a smaller $\varepsilon>0$ to which we restrict. Now, concerning $W^{1,q}_{-1-\varepsilon}$ convergence, along the same lines as in the proof of \cref{LemmaInvFunctThmSobReg}, we have
    for $j>i$
    \begin{align*}
        \|D\Theta_j - D\Theta_i&\|_{L^{q}_{-2-\varepsilon}(\nR^n\setminus\phi(B_R))} \leq \sum_{l=i}^{j}\sum_{a=1}^l\|A\Phi\cdots A(D\Phi)\cdot_a D\psi\cdots A\Phi\|_{L^{q}_{-2-\varepsilon}(\nR^n\setminus\phi(B_R))}
        \\
        &\leq \|A(D\Phi)\|_{L^{q}_{-2-\varepsilon}(\nR^n\setminus\phi(B_R))}\|D\psi\|_{C^{0}(\nR^n\setminus\phi(B_R))}\sum_{l=i}^{j}l\|A\Phi\|^{l-1}_{C^{0}(\nR^n\setminus\phi(B_R))}.
    \end{align*}
    Notice that, because the diffeomorphism $\phi: \nR^n \setminus B_R \to \nR^n \setminus \phi(B_R)$ satisfies $\phi - \Id \in C^1_{-\varepsilon}(\nR^n \setminus B_R)$ and $\phi^{-1} - \Id \in C^1_{-\varepsilon}(\nR^n \setminus \phi(B_R))$, then $A:L^q_{\delta}(\nR^n \setminus B_R)\to L^q_{\delta}(\nR^n \setminus \phi(B_R))$ is a bounded isomorphism for any $\delta\in \mathbb{R}$. Therefore, we see that $\|A(D\Phi)\|_{L^{q}_{-2-\varepsilon}(\nR^n\setminus\phi(B_R))}$ is finite and the same analysis as in \cref{LemmaInvFunctThmSobReg} shows the desired $W^{1,q}_{-1-\varepsilon}$ convergence. This settles $\phi^{-1} - \Id \in W^{2,q}_{-\varepsilon}(\nR^n\setminus\phi(B_R)$. The $k > 2$ cases follow along the same lines of \cref{LemmaInvFunctThmSobReg}.
\end{proof}

