\section{Weighted estimates revisited}
\label{Weighted estimates revisited}
This appendix is intended to provide a decay bootstrap for solutions to 
\begin{align*}
    \label{LaplaceEqAppendix}
    \Delta_gu = f
\end{align*}
on AE manifolds, very close to that presented in \cite[Theoren A.3]{avalos2024sobolev}. The main difference in our case is that we only assume the manifold to be $W^{1,q}_{\tau}$-AE with $q>n$, rather than $W^{2,q}_{\tau}$-AE with $q>\tfrac{n}{2}$, but assume on the other hand a better local regularity of the metric $g\in W^{2,q}_{loc}(T_2M)$ and the a-priori solution $u\in W^{2,p}_{loc}(M)\cap L^{p}_{\delta}(M)$. It should be mentioned that a stronger statement than ours is claimed in \cite[Proposition 1.6]{Bartnik86}, although there are reasons to be skeptical about its validity in the generality stated there. We refer the reader to \cite[Appendix A]{avalos2024sobolev} for a discussion on this matter. 
\begin{theorem}
    \label{BartniksProp1.6}
    Let $(M,g)$ be a $W^{1,q}_{\tau}$-AE manifold such that $g\in W^{2,q}_{loc}(M)$ with $q>n$ and $\tau<0$. If $u\in W^{2,p}_{loc}(M)\cap L^{p}_{\delta}(M)$ and $\Delta_gu\in L^p_{\delta-2}(M)$ for some $1<p\leq q$ and $\delta\in\nR$, then $u\in W^{2,p}_{\delta}(M)$ and 
    \begin{align*}
        \Vert u\Vert_{W^{2,p}_{\delta}(M)}\leq C\left(\Vert \Delta_gu\Vert_{L^p_{\delta-2}(M)} + \Vert u\Vert_{L^p_{\delta}(M)} \right).
    \end{align*}
\end{theorem}
The proof of \cref{BartniksProp1.6} is the same in spirit to that of \cite[Theorem A.3]{avalos2024sobolev}, with Sobolev multiplications applied differently in certain estimates. For the convenience of the reader, we outline the proof and point out the main differences. The first step is to establish the following result, which is a version of of \cite[Theorem A.2]{avalos2024sobolev} adapted to the hypothesis of \cref{BartniksProp1.6}.
\begin{theorem}
    \label{WeightedEstimatesPreliminarThm}
    Let $g\in W^{2,q}_{loc}(T_2\nR^n)$ be a $W_{\tau}^{1,q}$-AE Riemannian metric on $\nR^n$ for some $q > n$ and $\tau<0$. For every $1<p\leq q$ and $\delta\in\nR$ there is a constant $C>0$ such that
    \begin{align*}
        \|u\|_{W^{2,p}_{\delta}(\nR^n)} \leq C\left(\|\Delta_g u\|_{L^p_{\delta-2}(\nR^n)} + \|u\|_{L^p_{\delta}(\nR^n)}\right)
    \end{align*}
    holds for all $u\in W^{2,p}_{\rho}(\nR^n)$.
\end{theorem}
\begin{proof}
    Fix $R > 0$ and let $\chi$ be a smooth cut-off function, with $0 \leq \chi \leq 1$, satisfying
    \begin{equation*}
        \chi|_{\overline{B_R(0)}} \equiv 1 \,, \quad \supp\chi \subset\subset B_{2R}(0) \,, \quad |\partial^k\chi(x)|\leq C(n,k)R^{-k}
    \end{equation*}
    for all $k \in \nN$. Decompose $u = \chi u + (1-\chi) u \doteq u_1 + u_2$ and by the same reasoning as in \cite[Theorem A.2]{avalos2024sobolev} one may estimate
    \begin{equation}
        \label{eq: u1 estimate}
        \|u_1\|_{W^{2,p}_{\delta}(\nR^n)}\leq C(g,n,p,R)\left(\|\Delta_g u\|_{L^p_{\delta}(\nR^n)} + \|u\Vert_{W^{1,p}_{\delta}(\nR^n)}\right).
    \end{equation}
    In order to estimate $u_2$, we write
    \begin{align*}
        \Delta_g u_2 &= \Delta u_2 + (g^{ij}-\delta_{ij})\partial_{i}\partial_{j} u_2 + g^{ij}\Gamma^l_{ij}\partial_lu_2
    \end{align*}
    and apply the weighted elliptic estimate for the Euclidean Laplacian $\Delta$ to obtain (see \cite[Lemma A.1]{avalos2024sobolev}, which is a mild adaptation of \cite[Inequality (2.7)]{NirenbergWalker})
    \begin{align*}
        \|u_2\|_{W^{2,p}_{\delta}(\mathbb{R}^n)}
        &\leq C\|\Delta_g u_2\|_{L^p_{\delta-2}(\nR^n)}
        \\
        &\quad + C\Bigl(\|(g^{ij}-\delta_{ij})\partial_{ij}u_2 \|_{L^{p}_{\delta-2}(\nR^n)} + \|g^{ij}\Gamma^l_{ij}\partial_lu_2 \|_{L^{p}_{\delta-2}(\nR^n)} + \|u_2\|_{L^p_{\delta}(\nR^n)}\Bigr).
    \end{align*}
    Since $W^{1,q}_{\tau}(\mathbb{R}^n)\hookrightarrow C^{0}_{\tau}(\mathbb{R}^n)$ for $q > n$, the same argument as in \cite[Theorem A.2]{avalos2024sobolev} allows us to estimate the higher order error term like
    \begin{align*}
        \|(g^{ij}-\delta_{ij})\partial_{ij}u_2 \|_{L^{p}_{\delta-2}(\nR^n)} &\leq C(g)R^{\tau}\Vert u_2 \Vert_{W^{2,p}_{\delta}(\nR^n\backslash\overline{B_R(0)})}.
    \end{align*}
    Concerning the lower order term, first notice that $g^{ij}\Gamma^k_{ij} \in L^q_{\tau-1}(\nR^n) \hookrightarrow L^q_{\gamma-1}(\nR^n)$ for any $\tau < \gamma < 0$. As $\partial u_2$ is supported away from $B_R(0)$, let us fix a smooth cut-off function $\eta$ such that $\eta \equiv 1$ on $\nR^{n}\backslash \overline{B_{R}(0)}$ and it is zero in $B_{R/2}(0)$, and appeal to the multiplication property
    \begin{align*}
        L^{q}_{\gamma-1}(\nR^n)\otimes W^{1,p}_{\delta-1}(\nR^n)\hookrightarrow L^p_{\delta-2}(\nR^n)
    \end{align*}
    of \cref{AEWeightedEmbeedings} to estimate
    \begin{align*}
        \|g^{ij}\Gamma^l_{ij} \partial_lu_2\|_{L^{p}_{\delta-2}(\nR^n)} &= \| \eta g^{ij}\Gamma^l_{ij} \partial_lu_2\|_{L^{p}_{\delta-2}(\nR^n)}
        \\
        &\leq C(n,q,p) \|\eta g^{ij}\Gamma^l_{ij}\|_{L^{q}_{\gamma-1}(\nR^n)}\Vert \partial_lu_2\Vert_{W^{1,p}_{\delta - 1}(\nR^n)}
        \\
        &\leq C(n,q,p,g) \|\eta\Gamma^l_{ij}\|_{L^{q}_{\gamma-1}(\nR^n)}\| u_2\Vert_{W^{2,p}_{\delta}(\nR^n)} \,.
    \end{align*}
    Now using that $\tau<\gamma<0$, we have
    \begin{align*}
        \|\eta\Gamma^l_{ij} \|_{L^{q}_{\gamma-1}(\nR^n)} &\leq 2\|  \Gamma^l_{ij}\|_{L^{q}_{\gamma-1}(\nR^n\backslash\overline{B_{R/2}(0)})} \leq CR^{-(\gamma-\tau)}\| \Gamma^l_{ij}\|_{L^{q}_{\tau-1}(\nR^n\backslash\overline{B_{R/2}(0)})}
    \end{align*}
    and thereby
    \begin{align*}
        \|g^{ij}\Gamma^l_{ij} \partial_{l}u_2\|_{L^{p}_{\delta-2}(\nR^n\backslash\overline{B_R(0)})}&\leq C(n,p,q,g)R^{-(\gamma-\tau)}\|u_2\|_{W^{2,p}_{\delta}(\nR^n)}.
    \end{align*}
    We conclude that there is a constant $C>0$ independent $R$ such that
    \begin{align*}
        \|u_2\|_{W^{2,p}_{\delta}(\nR^n)}
        &\leq C\| \Delta_gu_2\|_{L^{p}_{\delta-2}(\nR^n)} + C\bigl(R^{\tau}+R^{-(\gamma-\tau)}\bigr)\|u_2 \|_{W^{2,p}_{\delta}(\nR^n)} + C\| u_2\|_{L^p_{\delta}(\nR^n)} \,,
    \end{align*}
    so we may pick $R$ large enough depending only on $n$, $p$, $q$ and $g$ such that
    \begin{equation}
        \label{eq: u2 estimate}
        \|u_2\|_{W^{2,p}_{\delta}(\nR^n)}
        \leq C(n,p,q,g)\big(\| \Delta_gu_2\|_{L^{p}_{\delta-2}(\nR^n)} + \|u_2\|_{L^p_{\delta}(\nR^n)}\big).
    \end{equation}
    Once we have \eqref{eq: u1 estimate} and \eqref{eq: u2 estimate}, one concludes the proof exactly as in \cite[Theorem A.2]{avalos2024sobolev}.
\end{proof}
Next, we use a partition of unity argument to establish the desired decay estimate for general AE manifolds.
\begin{proof}[Proof of \cref{BartniksProp1.6}]
    Notice that as $u \in W^{2,p}_{loc}(M)$ by hypothesis, all we need to show is that $v \doteq \eta u \in W^{2,p}_{\delta}(M)$ for some smooth cut-off function $\eta$ supported in the asymptotic end $M \setminus K$. For simplicity, we regard $v$ as a compactly supported function in $\nR^n \setminus \overline{B_1(0)}$, which is in $W^{2,p}_{loc}(\nR^n) \cup L^p_\delta(\nR^n)$ by hypothesis. Define for large $R>1$ the rescaled cut-off function $\chi_R(x) = \chi(\tfrac{x}{R})$, where $\chi \in C^\infty_0(B_2(0))$ is a standard non-negative a cut-off function with $\chi \equiv 1$ on $B_1(0)$. A lengthy computation carried out in the proof of \cite[Theorem A.3]{avalos2024sobolev} yields
    \begin{align*}
        \sum_{|\alpha|\leq2}\|\chi_R^2 \sigma^{|\alpha|+\delta-\frac{n}{p}} \partial^\alpha v\|_{L^p(\nR^n)} &\leq C\Bigl(\|\chi^2_Rv\|_{W^{2,p}_\delta(\nR^n)} + \|\chi_R \sigma^{1+\delta-\frac{n}{p}} \partial v\|_{L^p(B_{2R}(0))} 
        \\
        &\qquad + \|\chi_R \sigma^{\delta-\frac{n}{p}} v\|_{L^p(B_{2R}(0))} + \|\sigma^{\delta-\frac{n}{p}} v\|_{L^p(B_{2R}(0))}\Bigr) \,,
    \end{align*}
    and applying \cref{WeightedEstimatesPreliminarThm} to $\chi_R^2v$ we estimate the first term in the right-hand-side by
    \begin{align*}
        \|\chi_R^2v\|_{W^{2,p}_{\delta}(\nR^n)} &\leq C\left(\|\Delta_g \bigl(\chi_R^2v\bigr)\|_{L^p_{\delta-2}(\nR^n)} + \|\chi_R^2v\|_{L^p_{\delta}(\nR^n)}\right)
        \\
        &\leq C\left(\|\chi_R^2\Delta_g v\|_{L^p_{\delta-2}(\nR^n)} + \|[\Delta_g,\chi_R^2] v\|_{L^p_{\delta-2}(\nR^n)} + \|\chi_R^2v\|_{L^p_{\delta}(\nR^n)}\right) \,.
    \end{align*}
    In order to deal with the commutator term, one can follow the exact same steps as in the proof of \cite[Theorem A.3]{avalos2024sobolev} with the exception of a Christoffel symbol term, which can simply be estimated like
    \begin{align*}
        \|v\Gamma\partial \chi_R^2&\|_{L^p_{\delta-2}(B_{2R}\setminus\overline{B_R})} \leq R^{-1}\|\partial\chi(R^{-1}\cdot)\Gamma\chi_R v\|_{L^p_{\delta-2}(\nR^n)} 
        \\
        &\leq C(n, p)R^{-1}\|\partial\chi(R^{-1}\cdot)\Gamma\|_{L^q_{\tau-1}(\nR^n)} \|\chi_R v\|_{W^{1,p}_{\delta-1}(\nR^n)}
        \\
        &\leq C(n,p,g)\Bigl(R^{-1}\|\chi_R v\|_{L^p_{\delta-1}(\nR^n)} + R^{-2}\|v\|_{L^p_{\delta-2}(B_{2R}\setminus\overline{B_R})} + R^{-1}\|\chi_R \partial v\|_{L^p_{\delta-2}(\nR^n)}\Bigr)
    \end{align*}
    thanks to the Sobolev multiplication
    \begin{equation*}
        L^q_{\tau-1}(\nR^n) \otimes W^{1,p}_{\delta-1}(\nR^n) \hookrightarrow L^p_{\delta-2}(\nR^n)
    \end{equation*}
    for $q > n$ and the hypothesis that $g$ is $W^{1,q}_{\tau}$-AE. All the rest remains unchanged and one is able to reduce the initial estimate to
    \small
    \begin{align*}
        \sum_{|\alpha|\leq2}\|\chi_R^2 \sigma^{|\alpha|+\delta-\frac{n}{p}} \partial^\alpha v\|_{L^p(\nR^n)} &\leq C\Bigl(\|\chi^2_R\Delta_gv\|_{L^{p}_{\delta-2}(\nR^n)} + \|\chi_R \sigma^{1+\delta-\frac{n}{p}} \partial v\|_{L^p(\nR^n)} + \|v\|_{L^p_\delta(\nR^n)}\Bigr).
    \end{align*}
    \normalsize
    At this point, one can use a weighted interpolation inequality \cite[Lemma A.2]{avalos2024sobolev} to get rid of the first-order term on the right-hand side and let $R \to \infty$ to obtain the desired estimate.    
\end{proof}





