	\appendix
	\section{Analysis of the 2D-BO integral operator $\hat{G}[h]$ for axisymmetric pulses}\label{G1-operator-transformation}
	The Appendix details  axisymmetric reduction of the 2D-BO integral operator.
	In \S\ref{Axisymmetric reduction} we first perform  transformation of the 2D-BO integral operator \eqref{hkhat-integral-operator2} from the Cartesian frame into polar coordinates,  which reduces  the 2D-BO to a one dimensional hypersingular integral equation. The hypersingular integral is understood in the Cauchy-Hadamard sense.
	In \S\ref{Inner} we further simplify the integrand.The results are briefly summarized in  \S\ref{A-concl}.
	\subsection{Axisymmetric reduction of the 2D-BO integral operator $\hat{G}[h]$}\label{Axisymmetric reduction}

	We begin with the general form of the stationary 2D-BO equation first derived and examined in 	 \cite{abramyan1992multidimensional}. In \S\ref{Self-similarity},  \ref{Quantative Comparisons} it was shown  that the 	evolution of collapses is self-similar and that the instantaneous  spatial distribution described by the self-similar
	solution is governed by the steady 2D-BO  equation %(see  \eqref{A-spatial-dependence-2})
	\begin{equation}\label{stationary 2-D BO}
		V_{m}^{*}h+\frac{h^{2}}{2}-\hat{G}[h]=0,
	\end{equation}
	where $V_{m}^{*}$ is a constant, while the independent Cartesian variables $\xi_{1}, \, \xi_{2}$ are  $\xi_{1}=\frac{(x-x_{m}(\tau))}{\tau^{\lambda}}$ and $\xi_{2}=\frac{(y-y_{m}(\tau))}{\tau^{\lambda}}$. Consider the dispersion integral operator employing traditional $x,y$ notation:  $\hat{G}[h(x,y)]$. The dispersion integral operator $\hat{G}[h(x,y)]$  is the hypersingular integral understood as the Cauchy-Hadamard integral
		\begin{equation}\label{Ghat-operator-1}
			\hat{G}[h(x,y)]=\frac{1}{2\pi}\int_{-\infty}^{\infty} \int_{-\infty}^{\infty}	 \frac{h(x^{\prime},y^{\prime})\,dx^{\prime}\,dy^{\prime}}{[(x-x^{\prime})^{2}+(y-y^{\prime})^{2}]^{3/2}}.
		\end{equation}
		The  numerical considerations of  \S\ref{axial-symmetry} strongly suggest a robust  tendency of localized solutions towards axial symmetry. It is therefore tempting to assume \emph{a priori } axial symmetry and exploit the simplification provided by the symmetry. To proceed, we first transform the integral operator \eqref{Ghat-operator-1} given in in terms of Cartesian coordinates $x,y,x^{\prime}, y^{\prime}$ into  the polar coordinates $r, \theta$
		$$x=r\cos{\theta},\quad y=r\sin{\theta},\quad x^{\prime}=r^{\prime}\cos{\theta^{\prime}},\quad y^{\prime}=r^{\prime}\sin{\theta^{\prime}}.$$
		Then we express the binomials under the square root  in polar coordinates
		\begin{equation}\label{polar-x}
			(x-x^{\prime})^{2}=(r\cos{\theta}-r^{\prime}\cos{\theta^{\prime}})^{2}=
			 r^{2}\cos^{2}{\theta}-2rr^{\prime}\cos{\theta}\cos{\theta^{\prime}}+r^{\prime\,2}\cos^{2}{\theta^{\prime}},
		\end{equation}

		\begin{equation}\label{polar-y}
			(y-y^{\prime})^{2}=(r\sin{\theta}-r^{\prime}\sin{\theta^{\prime}})^{2}=
			r^{2}\sin^{2}{\theta}-2rr^{\prime}\sin{\theta}\sin{\theta^{\prime}}+r^{\prime\,2}
			\sin^{2}{\theta^{\prime}},
		\end{equation}
		and  sum-up equations \eqref{polar-x} and \eqref{polar-y}. Using standard trigonometric identities we obtain
		\begin{equation}\label{polar-x-y}
			(x-x^{\prime})^{2}+(y-y^{\prime})^{2}=r^{2}+r^{\prime\,2}-
			2rr^{\prime}\cos{(\theta^{\prime}-\theta)}.
		\end{equation}
		On substituting equation \eqref{polar-x-y} into \eqref{Ghat-operator-1}  and noting that $dx^{\prime}dy^{\prime}=r^{\prime}dr^{\prime}d\theta^{\prime},$
		we find
		\begin{equation}\label{khat-integral-operator1}
			\hat{G}[h(\boldsymbol r)]=\frac{1}{2\pi}\int_0
			^{\infty}dr^{\prime}  \int_{0}^{2\pi} \frac{h(r^{\prime}\cos{\theta^{\prime}},r^{\prime}\sin{\theta^{\prime}},\tau)\,r^{\prime}d\theta^{\prime}}{[r^{2}+r^{\prime\,2}-
				2rr^{\prime}\cos{(\theta^{\prime}-\theta)}]^{3/2}}.
		\end{equation}
		To distinguish usage of operator $\hat{G}[h(\boldsymbol r)]$ in the full 2D space $x,y$ from the situations where it is applied to the class of axially symmetric functions we introduce a new notation  $ \hat{G}_{1}[h(r)] $ for the latter.

		\subsection{Inner integral $I_{1}$}\label{Inner}
		First, we re-write and investigate the inner integral which we denote here as $I_1$. The integration   is with respect to the dummy variable $\theta^{\prime}$. Without loss of generality we set $\theta=0$. Finally, we present  the inner  integral in  the following compact form,
		\begin{equation}\label{Integral-I}
			I_1=\int_{0}^{2\pi}\frac{d\theta^{\prime}}{\sqrt{(a-b\cos{\theta^{\prime}})^{3}}},\qquad a=r^{2}+r^{\prime\,2},\quad b=2rr^{\prime}.
		\end{equation}
		Consider the inner integral $I_{1}$ given by equation \eqref{Integral-I} after renaming the dummy variable $\theta^{\prime}$ by $x$ to obtain,
		\begin{equation}\label{new-integral-I1} I_{1}=\int_{0}^{2\pi}\frac{dx}{(m-n\cos{(x)})^{\frac{3}{2}}}=2\int_{0}^{\pi}\frac{dx}{\sqrt{(m-n\cos(x))^{3}}},\qquad m=r^{2}+r^{\prime\,2},\quad n=2rr^{\prime}.
		\end{equation}
		The elliptic integral \eqref{new-integral-I1}  can be expressed as (see e.g. \cite{zwillinger2007table} p. 182 equation 291.01) ,
		\begin{equation}
			I_{1}=\frac{2}{(m-n)(\sqrt{(m+n)})}E(\delta,\gamma^{\prime}),
		\end{equation}
		where   $E(\delta, \gamma^{\prime} )$ is the incomplete elliptic integral of the second kind. The parameters $\delta$ and the modulus of elliptic integral $\gamma^{\prime}$ are
		$$\delta=\sin^{-1}\left(\sqrt{(\frac{(m+n)(1-\cos{x})}{2(m-n\cos{x})})}\right),\quad \gamma^{\prime}=\sqrt{\frac{2n}{m+n}},\quad m>n>0,\quad 0\leq x\leq \pi.$$
		On substituting the above expressions for $m$ and $n$ into equation \eqref{new-integral-I1},  while making use of the limits of integration and  the property  of incomplete elliptic integral of the second kind, that $E(\frac{\pi}{2},\gamma^{\prime})=E(\gamma^{\prime})$ (see e.g. \cite{olver2010nist} p. 491 equation 19.6.9), we  simplify the expression for $I_{1}$,
		\begin{equation}
			I_{1}=\frac{4}{(r^{\prime}-r)^{2}(r+r^{\prime})}E(\gamma^{\prime}),\qquad \gamma^{\prime}=\frac{2\sqrt{rr^{\prime}}}{r+r^{\prime}},
		\end{equation}
		where $E(\gamma^{\prime})$ is the complete elliptic integral of the second kind. On substituting this result  for $I_{1}$ into equation \eqref{khat-integral-operator1} we express the 2D integral operator in  one-dimensional form in terms of $r$ as,
		\begin{equation}\label{khat-integral-operator-Radial-2}
			\hat{G}_{1}[h(r)]=\frac{2}{\pi}
			\int_0
			 ^{\infty}\frac{h(r^{\prime},\tau)\,r^{\prime}\,E(\gamma^{\prime})\,dr^{\prime}}{(r^{\prime}-r)^{2}(r+r^{\prime})}.
		\end{equation}
		This is the exact axisymmetric  reduction of integral \eqref{Ghat-operator-1}.	The properties of the complete elliptic integral of the second kind $E(\gamma^{\prime})$ are well known, in particular, we note that $E(1)=1$ and $E(0)=\frac{\pi}{2}$ (Olver et. al 2010).

		Thus, the problem of solving 2D-BO stationary equation \eqref{stationary 2-D BO} in the class of axisymmetric functions has been reduced to solving one-dimensional nonlinear   Fredholm integral equation of the second kind
		\begin{equation}\label{radial Fredholm}
			V_{m}^{*}h+\frac{h^{2}}{2}-\hat{G}_{1}[h]=0,
		\end{equation}
		where $\hat{G}_{1}[h]$ is given by \eqref{khat-integral-operator-Radial-2}. By construction the numerical solution of \ref{radial Fredholm} coincides with that of \ref{eqnn-spatial-symmetric}.

		Figure  (\ref{Benjamin-ono-soliton})  shows the soliton-like numerical solution of \eqref{stationary 2-D BO} obtained in \cite{abramyan1992multidimensional} and its Benjamin-Ono fit. It illustrates how well the Benjamin-Ono fit   \eqref{BO-soliton} given by the expression
		\begin{equation}\label{radial-spatial-solution}
			h(r)=\frac{4a_{0}}{1+a_{0}^{2}r^{2}},
		\end{equation}
		captures  the exact numerical solution of  equation  \eqref{stationary 2-D BO}  or its equivalent \eqref{radial}.
		Here $a_{0}$ is a constant characterizing both the amplitude and width. It is obtained numerically by fitting
		the cross-section and given by the parameter  $a_{0}=V_{m}^{*}=2.8876$ with over 95\% confidence interval.
		This is an illustration of the so-called the `ground  mode' solution,  there are also solitary wave solutions with oscillatory tails which we do not consider here.

		\subsection{Conclusions }	\label{A-concl}
		We have simplified the integral equation governing the spatial structure of collapses and found that  the radial Benjamin-Ono soliton fit captures  well the exact numerical solution. However, the problem of finding the solution analytically with a desired accuracy remains open.

