This section illustrates algorithms described in Section \ref{sub:model}. We implement the algorithms by Python. The Python scripts are available at the replication package.\footnote{\href{https://github.com/Yonggeun-Jung/monthly_gdp}{https://github.com/Yonggeun-Jung/monthly\_gdp}}

\subsection{Data Preprocessing}
\begin{algorithm}[H]
\SetAlgoLined
\KwData{Master file \texttt{master\_country.csv} with columns: \texttt{DATE}, $X_1, \dots, X_k$, $Y$; pre-defined \texttt{log\_diff\_cols}}
\KwResult{Transformed monthly explanatory variables \texttt{X\_prime\_m\_df}}

Load \texttt{master\_country.csv} into DataFrame \texttt{df}.\;
Convert \texttt{DATE} column to datetime format.\;
Create \texttt{quarter} column by extracting quarter from \texttt{DATE}.\;

Initialize \texttt{X\_prime\_m\_df} with columns \texttt{DATE} and \texttt{quarter}.\;

\For{each explanatory variable $X_j \in \{X_1, \dots, X_k\}$}{
    Conduct ADF test on $X_j$ to check stationarity and define \texttt{log\_diff\_cols}.\;
    \eIf{$X_j \in$ \texttt{log\_diff\_cols}}{
        $X'_{m,j} \leftarrow \log(X_j) - \log(X_{j,\text{prev}})$\;
    }{
        $X'_{m,j} \leftarrow X_j$\;
    }
    Add $X'_{m,j}$ to \texttt{X\_prime\_m\_df}.\;
}
\caption{Monthly Transformation of Explanatory Variables}
\label{algo1}
\end{algorithm}

In Algorithm \ref{algo1}, we preprocess the dataset. The data collected for each country are stored in files named \texttt{master\_<country\_name>.csv}, each containing columns for \texttt{DATE}, \(X_1, \dots, X_k\), and \(Y\). The primary task is to determine how to transform the \(X\) variables. For each \(X_j\), we conduct an ADF test using \texttt{tsa.stattools.adfuller} function from \texttt{statsmodels} package to detect a unit root. If \(X_j\) exhibits a unit root and is not included in the exception list of variables that should be treated as growth rates, we apply a log-difference transformation. Otherwise, we retain \(X_j\) in its original form.

% --------------------
\begin{algorithm}[H]
\SetAlgoLined
\KwData{Transformed monthly \texttt{X\_prime\_m\_df}; \texttt{log\_diff\_cols}}
\KwResult{Quarterly dataset \texttt{X\_q\_processed}, \texttt{Y\_q\_processed}}

\texttt{quarters} $\leftarrow$ unique sorted quarters from \texttt{X\_prime\_m\_df}\;

\For{each quarter $q$ in \texttt{quarters}}{
    \texttt{X\_current\_q} $\leftarrow$ rows in quarter $q$ from \texttt{X\_prime\_m\_df}\;

    \For{each variable $j$ in explanatory variables}{
        \eIf{$j \in$ \texttt{log\_diff\_cols}}{
            $X_{q,j} \leftarrow \sum_{m \in q} X'_{m,j}$\;
        }{
            $X_{q,j} \leftarrow \frac{1}{3} \sum_{m \in q} X'_{m,j}$\;
        }
        \texttt{X\_q\_row[$j$]} $\leftarrow X_{q,j}$\;
    }
}

Extract $Y_q$ as the first month of each quarter in \texttt{df}.\;
\texttt{Y\_q\_processed} $\leftarrow$ $Y_q \leftarrow \log(Y_q) - \log(Y_{q-1})$, dropping first value.\;

\texttt{X\_q\_processed} $\leftarrow$ concatenate log-diff and non-log columns.\;

\caption{Quarterly Aggregation and Final Processing}
\label{algo2}
\end{algorithm}

In Algorithm \ref{algo2}, we aggregate the monthly transformed variables into quarterly observations to match the frequency of the dependent variable $Y$. For each quarter $q$, we sum the monthly values of log-differenced variables and average the monthly values of non-log-differenced variables.\footnote{In case of the non-log-differenced variables, we standardize it only after splinting data into training/test sets to avoid data leakage.} The $Y_q$ is computed as the log difference.

\subsection{Main Body of Models}

\subsubsection{MLP: Multi-Layer Perceptron}

In Algorithm \ref{algo3}, we identify the optimal set of hyperparameters by iteratively training multiple MLP network specifications. Among the candidate models, we retain the one that achieves the lowest validation MSE as the final model. This procedure is implemented using the \texttt{keras-tuner} library provided by \texttt{TensorFlow}.

\begin{algorithm}[H]
\SetAlgoLined
\KwData{\texttt{X\_q\_processed}; \texttt{Y\_q\_processed}; \texttt{non\_log\_cols}}
\KwResult{The best-performing trained model, $\hat{f}(\cdot; \hat{\theta})$}

\tcc{Split Dataset and Standardization}
Split \texttt{X\_q\_processed} and \texttt{Y\_q\_processed} into 80\% training sets:\; ($X_q^{\text{train}}$, $Y_q^{\text{train}}$) and 20\% test sets ($X_q^{\text{test}}$, $Y_q^{\text{test}}$)\;

\If{\texttt{non\_log\_cols} is not empty}{
    $scaler \leftarrow \text{StandardScaler()}$\;
    Fit $scaler$ on the \texttt{non\_log\_cols} of $X_q^{\text{train}}$ and transform them\;
    Transform the \texttt{non\_log\_cols} of $X_q^{\text{test}}$ using the fitted $scaler$\;
}

\tcc{Hyperparameter Tuning}
Define a hyperparameter search space $H$ for MLP architecture\;
Initialize a Bayesian Optimization tuner to search space $H$, with the objective of minimizing the validation mean squared error (\texttt{val\_mse})\;

\tcc{Model Search and Selection}
Execute the hyperparameter search on the training set, using the test set for validation\;
\tcp{The tuner iteratively builds, compiles, and trains MLP models. Each model is trained using the Adam optimizer and employs Early Stopping to prevent overfitting.}
$\hat{f}(\cdot; \hat{\theta}) \leftarrow$ Retrieve the best model with the lowest \texttt{val\_mse}\;

\caption{Neural Network Training and Hyperparameter Optimization}
\label{algo3}
\end{algorithm}

While the search space can be expanded for better performance, We impose certain constraints to account for computational limitations. These constraints primarily involve setting upper bounds on the number of hidden layers, neurons, and training epochs. The default configuration uses up to 5 hidden layers and 512 neurons per layer, with the number of epochs\footnote{An epoch refers to one complete pass through the entire training dataset during model training \citep{james2023introduction}.} set to 2,000. While the exact values may vary by country, these defaults provide a reasonable balance between model flexibility and computational efficiency. The candidate activation functions include Rectified Linear Unit (ReLU), hyperbolic tangent (Tanh), Exponential Linear Unit (ELU), Scaled Exponential Linear Unit (SELU), and Swish, with the final layer using a linear function to reflect the continuous nature of the GDP growth.

\subsubsection{LSTM: Long Short-Term Memory}

\begin{algorithm}[H]
\SetAlgoLined
\KwData{\texttt{X\_q\_processed}; \texttt{Y\_q\_processed}; \texttt{non\_log\_cols}; \texttt{TIME\_STEPS}}
\KwResult{The best-performing trained LSTM model, $\hat{f}_{\text{LSTM}}(\cdot; \hat{\theta})$}

\caption{LSTM Training and Hyperparameter Optimization}
\label{algo:lstm}

\tcc{Split Dataset and Standardization}
Split \texttt{X\_q\_processed} and \texttt{Y\_q\_processed} into training and test sets\;
Standardize \texttt{non\_log\_cols} using a scaler fitted only on the training data\;

\tcc{Create Time Series Dataset}
\For{each dataset (training and test)}{
    Transform the 2D data $(N, k)$ into a 3D sequential dataset $(N - T, T, k)$ using a sliding window of size \texttt{TIME\_STEPS}\;
    Store as $X_{\text{LSTM}}^{\text{train}}, Y_{\text{LSTM}}^{\text{train}}, X_{\text{LSTM}}^{\text{test}}, Y_{\text{LSTM}}^{\text{test}}$\;
}

\tcc{Hyperparameter Tuning}
Define a search space $H$ for LSTM architecture (e.g., layers, units), dropout rates, and learning rate\;
Initialize a Bayesian Optimization tuner to search space $H$, with the objective of minimizing \texttt{val\_mse}\;

\tcc{Model Search and Selection}
Execute the hyperparameter search on $X_{\text{LSTM}}^{\text{train}}$, using $X_{\text{LSTM}}^{\text{test}}$ for validation\;
\tcp{The tuner iteratively builds and trains LSTM models using the Adam optimizer and Early Stopping.}
$\hat{f}_{\text{LSTM}}(\cdot; \hat{\theta}) \leftarrow$ Retrieve the best model with the lowest \texttt{val\_mse}\;
\end{algorithm}

The hyperparameter tuning for the LSTM is also conducted using \texttt{TensorFlow}’s \texttt{keras-tuner} library, making the underlying code structure very similar to that of the MLP. However, since the LSTM takes into account historical data, we must define the length of the input sequence, denoted as $t$, and reshape the dataset into a 3D structure accordingly. A larger value of $t$ allows the model to learn from a longer history, but it also results in the loss of more observations—especially important in our case, as training is performed on quarterly data. Taking this trade-off into account, we set the default value of $t$ to 4.

\subsubsection{XGBoost: Extreme Gradient Boosting}

\begin{algorithm}[H]
\SetAlgoLined
\KwData{\texttt{X\_q\_processed}; \texttt{Y\_q\_processed}; \texttt{non\_log\_cols}}
\KwResult{The best-performing trained XGBoost model, $\hat{f}_{\text{XGB}}(\cdot; \hat{\theta})$}

\caption{XGBoost Training and Hyperparameter Optimization}
\label{algo:xgboost}

\tcc{Split Dataset and Standardization}
Split \texttt{X\_q\_processed} and \texttt{Y\_q\_processed} into training and test sets\;
Standardize \texttt{non\_log\_cols} using a scaler fitted only on the training data\;

\tcc{Hyperparameter Tuning}
Define a hyperparameter grid $H$ for XGBoost (e.g., \texttt{n\_estimators}, \texttt{max\_depth}, \texttt{learning\_rate}, \texttt{subsample})\;
Initialize a \texttt{GridSearchCV} or \texttt{RandomizedSearchCV} instance with an \texttt{XGBRegressor} estimator, the search space $H$, and $K$-fold cross-validation\;

\tcc{Model Search and Selection}
Execute the hyperparameter search by fitting the search instance on the training set ($X_q^{\text{train}}$, $Y_q^{\text{train}}$)\;
$\hat{f}_{\text{XGB}}(\cdot; \hat{\theta}) \leftarrow$ Retrieve the best estimator (model) from the search results that yielded the best cross-validation score\;
\end{algorithm}

XGBoost is implemented using the \texttt{xgboost} library in Python. As with other models, its key hyperparameters—such as tree depth (which controls the ability to capture complex relationships), step size (to prevent overfitting), and the minimum loss reduction required for further partitioning—must be carefully tuned by the researcher.

To reduce computation time, one can use \texttt{RandomizedSearchCV}, which tests a random subset of hyperparameter combinations and selects the best among them. Alternatively, \texttt{GridSearchCV} allows the user to explicitly define a wide search space, offering more precise tuning at the cost of significantly greater computation time.

A hybrid approach—conducting a randomized search first, then performing a grid search around the best-performing region—can strike a balance between efficiency and accuracy.

In this study, we prioritize predictive accuracy and therefore apply \texttt{GridSearchCV} from the outset. However, \texttt{RandomizedSearchCV} or a combined approach may be more appropriate in cases where computational efficiency is critical.

\subsubsection{Elastic Net}
\begin{algorithm}[H]
\SetAlgoLined
\KwData{Quarterly dataset \texttt{X\_q\_processed}, \texttt{Y\_q\_processed}}
\KwResult{Optimal hyperparameters $(\lambda_1^*, \lambda_2^*)$ and coefficient estimates $\hat{\beta}_{\text{orig}}$}

\tcc{Split into Train and Test Sets}
Define training and test set: $(X_{\text{train}}, Y_{\text{train}})$, $(X_{\text{test}}, Y_{\text{test}})$\;
Standardize \texttt{non\_log\_cols} using \texttt{StandardScaler} in each set\;

\tcc{Define Penalized Loss Function}
Elastic Net loss:
$\mathcal{L}(\beta) = \sum_q (Y_q - X_q^\top \beta)^2 + \lambda_1 \sum_j |\beta_j| + \lambda_2 \sum_j \beta_j^2$\;

\tcc{Cross Validation on Training Set}
Define candidate values for $(\alpha, \rho)$.\;
Map to $(\lambda_1 = \alpha \rho, \lambda_2 = \alpha (1 - \rho))$.\;
Split $(X_{\text{train}}, Y_{\text{train}})$ into $K$ sequential folds.\;
\For{each pair $(\alpha, \rho)$ in the grid}{
    Initialize \texttt{total\_cv\_error} $\leftarrow 0$\;
    \For{each fold $k = 1$ to $K$}{
        Use folds $1$ to $k$ as training set; fold $k+1$ as validation set.\;
        Fit ElasticNet$(\alpha, \rho)$ and obtain $\hat{\beta}^{(k)}$\;
        Predict on validation set and compute MSE $e_k$\;
        \texttt{total\_cv\_error} $\leftarrow \texttt{total\_cv\_error} + e_k$\;
    }
    \If{\texttt{total\_cv\_error} $<$ \texttt{min\_cv\_error}}{
        Update best $(\alpha^*, \rho^*)$\;
    }
}

\tcc{Initial Model Estimation on the Training Set}
Fit ElasticNet$(\alpha^*, \rho^*)$ on $(X_{\text{train}}, Y_{\text{train}})$ to obtain $\hat{\beta}_{\text{initial}}$\;
Return $(\lambda_1^* = \alpha^* \rho^*,\; \lambda_2^* = \alpha^* (1 - \rho^*))$ and $\hat{\beta}_{\text{initial}}$\;

\caption{Hyperparameter Tuning and Initial Estimation}
\label{algo:enet1}
\end{algorithm}

\begin{algorithm}[H]
\SetAlgoLined
\KwData{Original training data (\texttt{X\_q\_train}, \texttt{Y\_q\_train}), optimized hyperparameters $(\lambda_1^*, \lambda_2^*)$, transformed monthly explanatory variables \texttt{X\_prime\_m\_df}}
\KwResult{Monthly GDP estimates $\hat{y}_m$ and optional confidence intervals}

\tcc{3.2 Bootstrap Procedure and Final Coefficient Estimation}
$B \leftarrow 50000$ 	\tcc*{Number of bootstrap}
Initialize list \texttt{beta\_hat\_bootstrap\_list}\;
\For{$b = 1$ to $B$}{
    $(X_{q,b}^*, Y_{q,b}^*) \leftarrow$ Resample with replacement from \texttt{X\_q\_train}, \texttt{Y\_q\_train}\;
    $\hat{\beta}_b^* \leftarrow \text{ElasticNet}(X_{q,b}^*, Y_{q,b}^*, \lambda_1^*, \lambda_2^*)$\;
    Add $\hat{\beta}_b^*$ to \texttt{beta\_hat\_bootstrap\_list}\;
}
$\hat{\beta} \leftarrow \frac{1}{B} \sum_{b=1}^{B} \hat{\beta}_b^*$ 	\tcc*{Use average}

\tcc{4. Monthly GDP Growth Estimation}
\texttt{X\_prime\_m\_for\_prediction} $\leftarrow$ \texttt{X\_prime\_m\_df}\;
$\hat{y}_m \leftarrow (X'_m)^\top \hat{\beta}$\;

\For{each month $m$}{
    Initialize list \texttt{y\_m\_bootstrap\_predictions}\;
    \For{each $\hat{\beta}_b^*$ in \texttt{beta\_hat\_bootstrap\_list}}{
        Add $(X'_m)^\top \hat{\beta}_b^*$ to \texttt{y\_m\_bootstrap\_predictions}\;
    }
    Compute 2.5th and 97.5th percentiles $\rightarrow$ CI for $\hat{y}_m$\;
}
\caption{Bootstrap Estimation}
\label{algo:enet2}
\end{algorithm}

\subsection{Monthly GDP Estimation}
Algorithm \ref{algo4} produces a preliminary $\tilde{Y}_m = \hat{f}(X_m; \hat{\theta})$. Each $\tilde{Y}_m$ is an estimate on a quarterly scale and their aggregation is not arithmetically consistent with the observed quarterly totals. For each quarter, an adjustment factor ($k_q$) is calculated by taking the ratio of the actual quarterly growth to the sum of the preliminary monthly estimates within that quarter. This factor is then applied to scale each preliminary estimate, yielding the final adjusted monthly growth rate, $\hat{y}_m$.

\begin{algorithm}[H]
\SetAlgoLined
\KwData{
    $\hat{f}(\cdot; \hat{\theta})$; \texttt{X\_prime\_m\_df}; \texttt{Y\_q\_processed}; \texttt{non\_log\_cols}
}
\KwResult{The final series of adjusted monthly GDP growth estimates $\hat{y}_m$}

\tcc{Prepare Monthly Input Data}
\texttt{X\_prime\_m\_scaled} $\leftarrow$ Create a copy of the relevant columns from \texttt{X\_prime\_m\_df}\;
\If{\texttt{non\_log\_cols} is not empty}{
    Transform the \texttt{non\_log\_cols} of \texttt{X\_prime\_m\_scaled}\;
}

\tcc{Generate Preliminary Monthly Estimates}
$\tilde{Y}_m \leftarrow \hat{f}(\text{\texttt{X\_prime\_m\_scaled}}; \hat{\theta})$ for all months $m$\;
$\hat{p}_m \leftarrow \tilde{Y}_m / 3$ for all months $m$ \tcp*{Calculate naive monthly estimates}

\tcc{Reconcile Monthly Estimates with Quarterly Actuals}
Initialize an empty series for final monthly estimates, $\hat{y}_m$\;
\For{each quarter $q$}{
    $\text{sum\_naive} \leftarrow \sum_{j \in q} \hat{p}_j$ \tcp*{Sum of naive estimates in the quarter}
    \If{quarter $q$ has a corresponding value in \texttt{Y\_q\_processed}}{
        $Y_q \leftarrow$ The actual observed growth for quarter $q$\;
        \eIf{$\text{sum\_naive} \neq 0$}{
            $k_q \leftarrow Y_q / \text{sum\_naive}$ \tcp*{Calculate adjustment factor}
            \For{each month $m$ in quarter $q$}{
                $\hat{y}_m \leftarrow k_q \cdot \hat{p}_m$ \tcp*{Apply adjustment factor}
            }
        }{
            \tcp{Distribute actual growth evenly if sum of naive estimates is zero}
            $\hat{y}_m \leftarrow Y_q / (\text{number of months in } q)$ for each month $m \in q$\;
        }
    }{
        \tcp{Use naive estimates if no actual quarterly data}
        $\hat{y}_m \leftarrow \hat{p}_m$ for each month $m \in q$\;
    }
}

\caption{Monthly GDP Growth Estimation and Reconciliation}
\label{algo4}

\end{algorithm}

