%----------------------------------------------------------
\section{Partial effects in sharp RK designs} \label{sec:id}
%----------------------------------------------------------
\subsection{Model and parameters of interest} \label{sec:id.paraDef}
The observed random variables comprise $\{Y, D, X\}$, where $Y$ is the outcome variable of interest, $D$ is a continuous target variable that a policymaker aims to intervene, and $X$ is the running variable; their supports are denoted by $\supp{Y}\subset\R$, $\supp{D}\subset \R$, and $\supp{X} \subset \R$, respectively.

We consider the canonical sharp regression kink (RK) design. For a deterministic assignment function $b:\R \to \R$, we let $D:=b(X)$ and assume that $Y$ is generated by
\begin{flalign}
    Y:= m(D, X, U) = m(b(X),X,U), \label{dgp:y}
\end{flalign}
where $U$ captures all the unobserved factors with dimension $d_u \geq 1$. Let $\supp{U}\subset \R^{d_u}$ denote the support for $U$.

% //////////////
To induce a counterfactual intervention in a target variable, suppose the policymaker selects a suitable \textit{intervention function} $\intven(\cdot,\delta)$ that changes the current $D$ to
\begin{flalign}
    D_\delta := \intven(D,\delta)
    = \intven(b(X),\delta). \label{dgp:d_dta}
\end{flalign}
Such a policy experiment $\intven$ satisfies $\intven(d,0)=d$; that is, $\delta =0$ corresponds to the status quo policy. Intervention (\ref{dgp:d_dta}) can be considered a generalization of the \textit{location shift} $D_\delta = D+\delta$ studied by \citet{firpo2009} and \citet{rothe2010el}. With the above mentioned induced change in $D$, the counterfactual outcome is
\begin{flalign}
    Y_{\delta}&:= m\left(D_\delta, X, U\right)
    = m\left(\intven(D,\delta), X, U\right)
    = m\left(\intven(b(X),\delta), X, U\right), \label{dgp:y_delta}
\end{flalign}
with structural function $m(\cdot,\cdot,\cdot)$ holding constant. %
Let $x_0$ denote the threshold point. The parameter of interest is defined as follows:
\begin{definition} \label{def:upe_0}
    For any functional $\phi: \mathrm{D}(\R) \subset \ell^{\infty}(\R) \to \mathbb{E}$,\footnote{In this study, $(\mathbb{T},d)$ denotes a (semi-)metric space; $\ell^\infty(\mathbb{T})$ denotes the set of all bounded real-valued functions on metric space $\mathbb{T}$; $\mathrm{D}(\mathbb{T})$ denotes the set of all  functions $f:\mathbb{T}\to\R$ that are right continuous with left-hand limits existing everywhere in $\R$; $\mathbb{E}$ and $\mathbb{D}$ denote Banach spaces.} the \textit{Partial Effect at the threshold} ($\upe$) is defined as
    \begin{flalign}
        \upe
        :=\lim\limits_{\delta\to 0}\frac{\phi(F_{Y_\delta|X=x_0})-\phi(F_{Y|X=x_0})}{\delta} \notag,
    \end{flalign}
    provided that the limit exists.
\end{definition}
$\upe$ measures the effect of an infinitesimal change in $D$ on functional $\phi$ of the conditional distribution of $Y$ given $X=x_0$. Unlike $\mathrm{UPE}:=\lim_{\delta\to 0}(\phi(F_{Y_\delta})-\phi(F_Y))/\delta$ considered by \citet{firpo2009} and \citet{rothe2010el,rothe2012}, $\upe$ is defined in terms of the conditional distribution $F_{\cdot|X=x_0}$. This is attributable to the restriction of the identification strength in the regression discontinuity/kink designs. %
Before describing the identification results, we present concrete examples of $\upe$.
% Distribution effect ////////////////////////
\begin{example}[\normalfont Distribution effect]
    Consider a trivial case where $\phi$ is an identity mapping $\phi_{Id}: F \mapsto F$. Then, the {\itshape  Distribution Partial Effect at the threshold} $(\udpe)$ is defined as
    \begin{flalign}
        \udpe(y)
        :=\lim\limits_{\delta\to 0}\frac{F_{Y_{\delta}|X}(y|x_0)-F_{Y|X}(y|x_0)}{\delta}. \notag
    \end{flalign}
    The parameter plays a crucial role in identifying $\upe$.
\end{example}

% Mean effect ////////////////////////
\begin{example}[\normalfont Mean effect]
    Estimating the mean (or average) effects is a typical point of interest in empirical studies. Let $\phi_{E}: F_{\cdot|X=x_0} \mapsto \int y \,dF_{\cdot|X}(y|x_0)=:E[\cdot|X=x_0]$ denote the mean functional. Then, the {\itshape Mean Partial Effect at the threshold} $(\umpe)$ is defined as
    \begin{flalign}
        \umpe
        &:= \lim\limits_{\delta\to 0} \frac{E(Y_{\delta}|\,X=x_0) - E(Y|\,X=x_0)}{\delta}. \notag
    \end{flalign}
\end{example}

% Quantile effect ////////////////////////
\begin{example}[\normalfont Quantile effect]
    Researchers tend to estimate the (conditional) quantile effect to capture policy heterogeneity.
    Let $$\phi_{Q,\tau}: F_{\cdot|X=x_0}\mapsto \inf\{y : F_{\cdot|X}(y|x_0) \geq \tau\}=:Q_{\cdot|X}(\tau|x_0)$$ denote the quantile functional. Then, the \textit{Quantile Partial Effect at the threshold} ($\uqpe$) is defined as
    \begin{flalign}
        \uqpe(\tau)
        :=\lim\limits_{\delta\to 0}\frac{Q_{Y_{\delta}|X}(\tau|x_0)-Q_{Y|X}(\tau|x_0)}{\delta}. \notag
    \end{flalign}
\end{example}

% Inequality measures ////////////////////////
\begin{example}[\normalfont Inequality measures]
    Some inequality measures can be expressed as the functionals of their distribution functions (see, for example, \citet{firpo2016}).
    We consider the interquartile range (IQR) operator $\phi_{IQR}:=\phi_{Q,0.75}-\phi_{Q,0.25}$. Subsequently, the \textit{Interquartile Range Partial Effect at the threshold} ($\iqrpe$) is defined as
    \begin{flalign*}
        \iqrpe&:=\lim_{\delta\to 0}\frac{IQR(Y_{\delta}|X=x_0)-IQR(Y|X=x_0)}{\delta}
    \end{flalign*}
    where $IQR(\cdot|X=x_0):=Q_{\cdot|X}(0.75|x_0)-Q_{\cdot|X}(0.25|x_0)$.

    Another popular inequality measure is the coefficient of variation (CV). Let $\phi_V:F_{\cdot|X=x_0}\mapsto \int (y-\mu_0)^2\,dF_{\cdot|X}(y|x_0)$ be the variance operator, where $\mu_0:=E[Y|X=x_0]$. The $\mathrm{CV}$ operator is denoted as $\phi_{CV}:=\sqrt{\phi_V}/\phi_E$ provided that $\phi_E(F_{\cdot|X=x_0})\ne 0$. Then, we define the \textit{coefficient of variation partial effect at the threshold} ($\cvpe$) as
    \begin{flalign*}
        \cvpe:=\lim_{\delta\to 0}\frac{CV(F_{Y_\delta|X=x_0})-CV(F_{Y|X=x_0})}{\delta},
    \end{flalign*}
    where $CV(F_{\cdot|X=x_0}):=\frac{\int (y-\mu_0)^2\,dF_{\cdot|X}(y|x_0)}{\int y\,dF_{\cdot|X}(y|x_0)}$.
\end{example}

%-----------------------------------------------------------
\subsection{Identification results} \label{sec:id.mainResults}
%-----------------------------------------------------------
The first step in identifying $\upe$ is to identify $\udpe$, which can be achieved by leveraging the kink's characteristics. %
Let $I_{x_0}$ denote a small closed interval of kink $x_0$. Write $b'(x_0^+):=\lim_{x\downarrow x_0} b'(x)$ and $b'(x_0^-):=\lim_{x\uparrow x_0} b'(x)$. The basic assumptions of the RK design (see, for example, \citet{card2015ecta} and \citet{cs2019}) are as follows:
\begin{assumptionsk}[\normalfont Sharp Kink Design]\label{A:sk}
    (a) $b(\cdot)$ is continuous on $I_{x_0}$ and continuously differentiable on $I_{x_0}\backslash\{x_0\}$.
    (b) Both $b'(x_0^+)$ and $b'(x_0^-)$ exist but $b'(x_0^+) \ne b'(x_0^-)$.
\end{assumptionsk}

We now introduce some notation.
Let $I_{d,0}:=\{d \in \R : d=b(x) \text{ for some } x \in I_{x_0} \}$ denote the image of $b(\cdot)$ on $I_{x_0}$ and $I_{y_{\tau},0}:=\{y\in\R : y=Q_{Y|X}(\tau|x) \text{ for some } x \in I_{x_0} \}$ denote the image of conditional quantile $Q_{Y|X}(\tau|\cdot)$ on $I_{x_0}$ for any $\tau \in (0,1)$. We express $N_{\varepsilon}:=\{\delta:|\delta|\leq \varepsilon\}$ for any small $\varepsilon > 0$.
The following assumptions are used to identify $\udpe$:
\begin{assumption}\label{A:struct.m.G}
    (a) $m(\cdot, \cdot, u)$ is continuously differentiable on $ I_{d,0} \times I_{x_0}$ for any $u$.
    (b) $\intven(\cdot,\delta)$ is continuous on $ I_{d,0}$ for any $\delta \in N_\varepsilon$; $\intven(d,\cdot)$ is continuously differentiable on $N_\varepsilon$ for any small $\varepsilon > 0$ and $d\in I_{d,0}$. Moreover, $\intven(d,0) = d$ for any $d \in \R$.
\end{assumption}

\begin{assumption}\label{A:f_YX}
    For any $x\in I_{x_0}$, the conditional distribution $F_{Y|X=x}$ is absolutely continuous with respect to Lebesgue measure\footnote{For simplicity, henceforth, we shall omit the statement ``with respect to the Lebesgue measure''.} and has strictly positive density $f_{Y|X=x}$.
    Moreover, $f_{Y|X}(\cdot|\cdot)$ is bounded and continuous on $I_{y_{\tau},0}\times I_{x_0}$ for any $\tau \in (0,1)$. %
\end{assumption}

Assumption \ref{A:struct.m.G}(a) is a condition on the continuity of structural derivatives $\dev{D}{m}$ and $\dev{X}{m}$, which is parallel to Assumptions 1(ii) and 2 of \citet{card2015ecta} and Assumption 2(i) of \citet{cs2019}. Noteworthily, $\frac{\partial m}{\partial x}(b(x),x,u)=b'(x)\dev{D}{m}(b(x),x,u)+\dev{X}{m}(b(x),x,u)$, and thus, $\frac{\partial m}{\partial x}(b(\cdot),\cdot,u)$ should not be continuous at kink $x_0$ given $u$. Assumption \ref{A:struct.m.G}(b) is slightly weaker than Assumption 1 of \citet{mms2024}, because no monotonic restriction is imposed on $\intven(\cdot,\delta)$. Assumption \ref{A:f_YX} is a condition on the continuity and boundedness of Lebesgue density $f_{Y|X}(\cdot|\cdot)$ over a local region, and is necessary for calculating the certain functional derivatives.

%/////////////////////////////
For any random variable $W$, let $\supp{W,0}:=\{w: f_{W|X}(w|x_0) > 0\}$ denote the support of conditional distribution $F_{W|X=x_0}$.
We write $\dev{X}{F_Y}(y|x_0^+):= \lim_{x \downarrow x_0}\dev{X}{F_{Y|X}}(y|x)$ and $\dev{X}{F_Y}(y|x_0^-):= \lim_{x \uparrow x_0}\dev{X}{F_{Y|X}}(y|x)$. The following theorem presents the identification of $\udpe$.
\begin{theorem} \label{thm:id.udpe}
    Suppose that Assumptions  \ref{A:sk},  \ref{A:struct.m.G}, \ref{A:f_YX} and regularity Assumptions \ref{A:hm.Qyxsmooth.mdta}--\ref{A:f_uxy.dct} (stated in Appendix \ref{apdx:id}) hold. Then,
    \begin{flalign*}
        \udpe(y)
        = \kappa_0\frac{\dev{X}{F_Y}(y|x_0^+)-\dev{X}{F_Y}(y|x_0^-)}{b'(x_0^+) - b'(x_0^-)}
        =:\kappa_0\rkd{D}(y)
    \end{flalign*}
    for any $ y \in \supp{Y,0}$, where $\kappa_0:=\dev{\delta}{\intven}(b(x_0),\delta)|_{\delta=0}$.
\end{theorem}

Subsequently, we discuss the identification of $\upe$. %
In general, achieving this objective without imposing constraints on the functional $\phi$ may not be feasible. The essential assumption regarding smoothness is as follows:
\begin{assumption} \label{A:phi-hadamard}
    $\phi: \mathrm{D}(\R) \subset \ell^{\infty}(\R) \to \mathbb{E}$ is Hadamard-differentiable at $F_{Y|X=x_0}\in \mathrm{D}(\R)$ tangentially to a subset $\mathbb{D}_0 \subset \ell^{\infty}(\R)$ (see Definition \ref{def:hadamard-diff} in Appendix \ref{apdx:id}); its Hadamard derivative at $F_{Y|X=x_0}$ is denoted by $\phi'_{F_{Y,0}}:\mathbb{D}_0 \to \mathbb{E}$.
\end{assumption}

The following theorem presents the identification of $\upe$.
\begin{theorem} \label{thm:id.upe}
    Suppose that the conditions of Theorem \ref{thm:id.udpe} are satisfied and Assumption \ref{A:phi-hadamard} holds. Then,
    \begin{flalign*}
        \upe = \phi'_{F_{Y,0}} \left(\udpe(\cdot)\right)
        = \kappa_0 \phi'_{F_{Y,0}} \left(\rkd{D}(\cdot)\right).
    \end{flalign*}
\end{theorem}
%
\begin{remark}
    Theorem \ref{thm:id.upe} indicates that $\upe$ can be identified in the RK design for Hadamard-differentiable functionals $\phi$. %
    In practice, estimating the $\upe$ of interest necessitates first calculating the corresponding Hadamard derivative $\phi'_{F_{Y,0}}$.
    We present concrete examples in Section \ref{sec:id.application}.
\end{remark}
%
\begin{remark}
    \citet{chs2019} define a \textit{general class of local Wald ratio estimands} $\uptau(\cdot)$, which can be expressed in the following form:
    \begin{flalign}
        \uptau(\cdot):=\varUpsilon(W)(\cdot), \; %
        \text{ where }
        W(\cdot,\cdot):= \frac{\varphi\left(\hdev{X}{\nu}{\mu_1}(x_0^+,y)\right)(\cdot)-\varphi\left(\hdev{X}{\nu}{\mu_1}(x_0^-,y)\right)(\cdot)}{\psi\left(\hdev{X}{\nu}{\mu_2}(x_0^+,d)\right)(\cdot)-\psi\left(\hdev{X}{\nu}{\mu_2}(x_0^-,d)\right)(\cdot)}; \label{def:localWald}
    \end{flalign}
    $\mu_1(x,y):=E[g(Y,y)|X=x]$ and $\mu_2(x,d):=E[h(D,d)|X=x]$.
    Theorem \ref{thm:id.upe} discovers the causal interpretation of the specific case of $\uptau(\cdot)$.
    If we set $(\varUpsilon,\varphi, \psi)=(\phi'_{F_{Y,0}},Id,Id)$ ($Id$ denotes the identity mapping), $g(Y,y)=1\{Y\leq y\}$, $h(D,d)=D=b(X)$ and $\nu = 1$, we obtain $\uptau=\phi'_{F_{Y,0}}(\rkd{D})$, which identifies $\upe$ associated with location shift $\intven(D,\delta)=D+\delta$.
\end{remark}

\begin{remark}[Covariates] \label{rmk:upe.covabs}
    Extending the above identification results to include covariates is convenient. Formally, let the assumptions of Theorem \ref{thm:id.udpe} hold conditional on covariates $Z$. Then,
    \begin{flalign*}
        \udpe(y)
        &=\kappa_0\frac{E\big[\dev{X}{F_Y}(y|x_0^+,Z)-\dev{X}{F_Y}(y|x_0^-,Z)\big|X=x_0\big]}{b'(x_0^+)-b'(x_0^-)}.
    \end{flalign*}
    Technical details regarding this equality are provided in Appendix \ref{apdx:id}.
\end{remark}


%----------------------------------------------------------
\subsection{Applications of Theorem \ref{thm:id.upe}} \label{sec:id.application}
%----------------------------------------------------------
This section presents the identification results obtained from Theorem \ref{thm:id.upe}.
We demonstrate that numerous RK estimands can be causally interpreted as the corresponding $\upe$s.
\subsubsection{Quantile Partial Effect}
Under Assumption \ref{A:f_YX} and certain regularity conditions, applying Lemma 21.4 of \citet{vaart2000} yields the Hadamard derivative of the quantile functional as $[\phi_{Q,\tau}]'_{F_{Y,0}}: h \mapsto - (h/f_{Y|X=x_0}) \circ Q_{Y|X=x_0}(\tau)$. Formally, the following corollary presents the identification of $\uqpe$:
\begin{coryQ} \label{cory:id.uqpe}
    Suppose that the conditions of Theorem \ref{thm:id.upe} are satisfied and Assumption \ref{A:id.cory}(a) (see Appendix \ref{apdx:id}) holds. Then,
    \begin{flalign*}
        \uqpe (\tau)
        = - \kappa_0 \frac{\rkd{D}(Q_{Y|X}(\tau|x_0))}{f_{Y|X}(Q_{Y|X}(\tau|x_0)|x_0)},
    \end{flalign*}
    for any $\tau \in (0,1)$.
\end{coryQ}

\begin{remark} \label{rmk:uqpe.qrkd}
    Let $\dev{X}{Q_Y}(\tau|x_0^+):=\lim_{x\downarrow x_0}\dev{X}{Q_{Y|X}}(\tau|x)$, with the same for $\dev{X}{Q_Y}(\tau|x_0^-)$.
    \citet{cs2019} study the causal interpretation of the estimand
    \begin{flalign}
        \rkd{Q}(\tau):= \frac{\dev{X}{Q_Y}(\tau|x_0^+) - \dev{X}{Q_Y}(\tau|x_0^-)}{b'(x_0^+) - b'(x_0^-)}. \notag
    \end{flalign}
    Under Assumptions \ref{A:f_YX} and \ref{A:hm.mdxt}(a),
    $\dev{X}{Q_Y}(\tau|x)=-\dev{X}{F_Y}(y_\tau(x)|x)/f_{Y|X}(y_\tau(x)|x)$, where $y_\tau(x):=Q_{Y|X}(\tau|x)$ for simplicity. Then, we can see that
    $\rkd{Q}(\tau)=-\frac{\rkd{D}(y_\tau(x_0))}{f_{Y|X}(y_\tau(x_0)|x_0)}$. Therefore, Corollary \ref{cory:id.uqpe} implies that $\rkd{Q}(\tau)$ identifies $\uqpe(\tau)$ associated with location shift $\intven(D,\delta)=D+\delta$.
\end{remark}

\begin{remark}[Covariates]
    When some covariates are observed, \citet{cs2019} apply nonparametric quantile regression with the covariates to estimate $\uqpe$ based on estimand $\rkd{Q}$. According to Remark \ref{rmk:upe.covabs} and Corollary \ref{cory:id.uqpe}, $\uqpe(\tau)$ can also be estimated by
    \begin{flalign*}
        -\kappa_0\frac{E\big[\dev{X}{F_Y}(y_\tau(x_0)|x_0^+,Z)-\dev{X}{F_Y}(y_\tau(x_0)|x_0^-,Z) \big|X=x_0\big] \big/ \left(b'(x_0^+)-b'(x_0^-)\right)}{f_{Y|X}(y_\tau(x_0)|x_0)}
    \end{flalign*}
    in the presence of the covariates. %
    One advantage of this estimator is that if $\udpe(y_\tau(x_0))$ (the numerator) is estimated initially, $\uqpe(\tau)$ can be obtained directly after estimating $f_{Y|X}$, eliminating the need to run quantile regressions for each $\tau$ again.
\end{remark}


\subsubsection{Mean Partial Effect}
As $\phi_E$ is linear, it is also Hadamard-differentiable with derivative $[\phi_{E}]'_{F_{Y,0}}: h \mapsto \int y \,dh(y)$. The following corollary presents the identification of $\umpe$.
\begin{coryE}\label{cory:id.umpe}
    Suppose that the conditions of Theorem \ref{thm:id.upe} are satisfied and Assumption \ref{A:id.cory} holds. Then,
    \begin{flalign}
        \umpe =\kappa_0 \frac{\dev{X}{E}(Y|x_0^+) - \dev{X}{E}(Y|x_0^-)}{b'(x_0^+) - b'(x_0^-)} =: \kappa_0 \rk. \notag
    \end{flalign}
    where $\dev{X}{E}(Y|x_0^+):=\lim_{x \downarrow x_0}\dev{X}{}E[Y|X=x]$ and similarly for $\dev{X}{E}(Y|x_0^-)$.
\end{coryE}
\begin{remark}
    Under Assumption \ref{A:struct.m.G},
    \begin{flalign*}
        Y_{\delta} - Y
        &:= m\left(\intven(b(X),\delta), X, U\right) - m(\underbrace{b(X)}_{\equiv\intven(b(X),0)},X,U)
        = \delta \kappa(X) \dev{D}{m}(b(X),X,U) + o(\delta)
    \end{flalign*}
    as $\delta \to 0$, where $\kappa(x):=\dev{\delta}{\intven}(b(x),\delta)|_{\delta=0}$. Subsequently, from the linearity of $\phi_E$, Assumption \ref{A:struct.m.G}(a) and a condition that permits the order of limit and integration to be interchanged,\footnote{For example, one may impose that $\sup_{|\delta|\in N_\varepsilon\backslash \{0\}}\big|\frac{m(\intven(b(x_0),\delta),x_0,u)-m(b(x_0),x_0,u)}{\delta} f_{U|X}(u|x_0)\big|<\infty$ for any $u$ to facilitate the dominated convergence theorem.} we obtain that
    \begin{flalign}
        \umpe
        = E\left[ \lim\limits_{\delta\to 0} \frac{Y_{\delta} - Y}{\delta} \big|\,X=x_0 \right]
        = \kappa_0 E\left[\dev{D}{m}(b(x_0),x_0,U) |\,X=x_0 \right]. \notag
    \end{flalign}
    Hence, $\umpe$ is $\kappa_0$ times the ``local average treatment effect'' considered by \citet{card2015ecta} under the aforementioned conditions. Moreover, if the location shift intervenes in the target variable, then $\kappa_0 = 1$, and thus  Corollary \ref{cory:id.umpe} is consistent with the conclusion of  \citeauthor{card2015ecta}'s (\citeyear{card2015ecta}) Proposition 1.
\end{remark}

\subsubsection{Inequality Partial Effects}
As $\iqrpe$ can be written as
\begin{flalign*}
    \iqrpe&:=\lim_{\delta\to 0}\frac{IQR(Y_{\delta}|X=x_0)-IQR(Y|X=x_0)}{\delta}\\
    &:= \lim_{\delta\to 0}\left\{\frac{Q_{Y_\delta|X}(0.75|x_0)-Q_{Y_\delta|X}(0.25|x_0)}{\delta}-\frac{Q_{Y|X}(0.75|x_0)-Q_{Y|X}(0.25|x_0)}{\delta}\right\} \\
    & = \lim_{\delta\to 0}\left\{\frac{Q_{Y_\delta|X}(0.75|x_0)-Q_{Y|X}(0.75|x_0)}{\delta}-\frac{Q_{Y_\delta|X}(0.25|x_0)-Q_{Y|X}(0.25|x_0)}{\delta}\right\} \\
    & = \uqpe(0.75) - \uqpe(0.25),
\end{flalign*}
the identification of $\iqrpe$ follows directly from Corollary \ref{cory:id.uqpe}.
\begin{coryI} \label{cory:id.iqrpe}
    Suppose that the conditions of Theorem \ref{thm:id.upe} are satisfied and Assumption \ref{A:id.cory}(a) holds. Then,
    \begin{flalign*}
        \iqrpe
        = - \kappa_0 \left\{\frac{\rkd{D}(Q_{Y|X}(0.75|x_0))}{f_{Y|X}(Q_{Y|X}(0.75|x_0)|x_0)}
        + \frac{\rkd{D}(Q_{Y|X}(0.25|x_0))}{f_{Y|X}(Q_{Y|X}(0.25|x_0)|x_0)}
        \right\}.
    \end{flalign*}
\end{coryI}

For $\cvpe$, the Hadamard derivative of CV operator $\phi_{CV}$ is given by
\begin{flalign*}
    [\phi_{CV}]'_{F_{Y,0}}: h \mapsto \frac{(\mu_0/2)\,\int (y-\mu_0)^2 \,dh(y) - v_0\, \int y \,dh(y)}{\mu_0^2 \sqrt{v_0}}
\end{flalign*}
where $\mu_0:=E[Y|X=x_0]$ and $v_0:=Var[Y|X=x_0]$. The following corollary elucidates the identification of $\cvpe$.
\begin{coryCV}\label{cory:id.cvpe}
    Suppose that the conditions of Theorem \ref{thm:id.upe} are satisfied and Assumption \ref{A:id.cory} holds. If $\mu_0 \ne 0$ and $v_0>0$, then
    \begin{flalign*}
        \cvpe = \kappa_0\frac{\dev{X}{E}(\gamma_V (Y-\mu_0)^2-\gamma_E  Y|x_0^+)-\dev{X}{E}(\gamma_V (Y-\mu_0)^2-\gamma_E Y|x_0^-)}{b'(x_0^+) - b'(x_0^-)},
    \end{flalign*}
    where $\gamma_V:=1/(2\mu_0\sqrt{v_0})$ and $\gamma_E:=\sqrt{v_0}/\mu_0^2$.
\end{coryCV}

