% **********************************************************
\section{Estimation and Inference: Practical Guidelines} \label{sec:stats}
In this section, we apply local polynomial regression to estimate $\upe$ and the bootstrap-based robust methodology proposed by \citet{chs2019} to conduct the inference. For completeness, we provide practical guidelines in Section \ref{sec:stats.procedures} and present the formal asymptotic theory in Appendix \ref{apdx:asy}. The detailed proofs are provided in the Supplementary Appendix C.
%----------------------------------------------------------
\subsection{Estimation} \label{sec:stats.esti}
%----------------------------------------------------------
First, we introduce some notation. We write
$$z_p(x):=(1,x,x^2,\cdots,x^p)^{\trans}, \;
\beta_p^\pm(y):=\left(F_{Y|X}(y|x_0), \frac{\dev{X}{F_Y}(y|x_0^\pm)h}{1!},\ldots \frac{\hdev{X}{p}{F_Y}(y|x_0^\pm)h^p}{p!}\right)^\trans.$$
Let $K(\cdot)$ denote a bounded kernel function, and $h_{n,-}(y)$ and $h_{n,+}(y)$ denote the pointwise bandwidth sequences. Then, the $p$th-order local polynomial estimator of $\beta^\pm_p(y)$ is given by
\begin{flalign}
    \betan{p}^\pm(y)
    &= \argmin{\beta\in \R^{p+1}} \sumn \di{\pm} \left[\I{Y_i\leq y}-\Zhtrans{p}{X_i}{\pm}\beta \right]^2 \Kh{X_i}{\pm}, \label{esti:beta}
\end{flalign}
where $\di{+}=d^+(X_i):=\I{X_i \geq x_0}$ and similarly for $\di{-}$. Therefore, the plug-in estimator of $\upe$ is given by
\begin{flalign}
    \upehat
    =\widehat{\phi}'_{F_{Y,0}}\left( \udpehat(\cdot) \right)
    =\kappa_0 \widehat{\phi}'_{F_{Y,0}} \bigg(\underbrace{\frac{ \widehat{\dev{X}{F_Y}}(\cdot|x_0^+) - \widehat{\dev{X}{F_Y}}(\cdot|x_0^-)}{b'(x_0^+) - b'(x_0^-)}}_{=:\rkdhat{D}(\cdot)}\bigg) , \label{esti:upe}
\end{flalign}
where $\widehat{\dev{X}{F_Y}}(\cdot|x_0^\pm)=e_{1,p}^{\trans}\betan{p}^\pm(\cdot)/h_{n,\pm}(\cdot)$ and $e_{\nu,p}$ denotes the $(\nu+1)$-th standard basis of $\R^{p+1}$, for example, $e_{1,2}=(0,1,0)^{\trans}$.
Notably, for different targeted $\upe$s, some unknown functions may exist in their Hadamard derivatives $[\phi]'_{F_{Y,0}}$, and thus require estimation on a case-by-case basis. Two examples are presented to illustrate this point.
% /////////////////////////////////
\begin{example}[\normalfont Quantile effect] \label{ex:uqpe.esti} %
    As discussed in Section \ref{sec:id.application}, the Hadamard derivative of the quantile operator is $[\phi_{Q,\tau}]'_{F_{Y,0}}: h \mapsto - (h/f_{Y|X=x_0})\circ Q_{Y|X}(\tau|x_0)$. Hence, the estimator of $\uqpe$ is
    \begin{flalign}
        \uqpehat(\tau)
        = - \kappa_0 [\widehat{\phi}_{Q,\tau}]'_{F_{Y,0}}(\rkdhat{D})
        = -\kappa_0\frac{\rkdhat{D}(\widehat{Q}_{Y|X}(\tau|x_0))}{\widehat{f}_{Y|X}(\widehat{Q}_{Y|X}(\tau|x_0)|x_0)}, \notag
    \end{flalign}
    where $\widehat{Q}_{Y|X}(\tau|x_0)$ and $\widehat{f}_{Y|X}(y|x_0)$ are uniformly consistent estimators of $Q_{Y|X}(\tau|x_0)$ and $f_{Y|X}(y|x_0)$, respectively. $\rkdhat{D}$ is defined in estimator (\ref{esti:upe}).
\end{example}
\begin{example}[\normalfont Mean effect]
    The Hadamard derivative of the mean operator is $[\phi_E]'_{F_{Y,0}}: h \mapsto \int y \,dh(y)$. As $\int y \,d\rkd{D}(y)=\rk$ (see the proof of Corollary \ref{cory:id.umpe}), the estimator of $\umpe$ is
    \begin{flalign}
        \umpehat
        =\kappa_0 [\widehat{\phi}_{E}]'_{F_{Y,0}}(\rkdhat{D})
        =\kappa_0[\phi_E]'_{F_{Y,0}} (\rkdhat{D})
        =\kappa_0\widehat{\rk}_n.\notag
    \end{flalign}
    Hence, computing $\umpehat$ is convenient by replacing $\I{Y_i\leq y}$ with $Y_i$ in estimator (\ref{esti:beta}).
\end{example}

%----------------------------------------------------------
\subsection{Inference: an overview} \label{sec:stats.infer}
%----------------------------------------------------------
To construct uniform confidence bands and conduct hypothesis tests, we apply the \textit{multiplier bootstrap} approach proposed by \citet{chs2019} to approximate the asymptotic distribution of $\sqrt{nh_n^3(\vartheta)}(\upehat(\vartheta)-\upe(\vartheta))$.

First, under the assumptions stated in Appendix \ref{apdx:asy}, we derive the uniform approximation (i.e., the \textit{Uniform Bahadur Representation}, UBR) of the processes $\sqrt{nh_{n,\pm}^3(y)}(\widehat{\dev{X}{F_Y}}(y|x_0^\pm)-\dev{X}{F_Y}(y|x_0^\pm))$ as
\begin{flalign*}
    \bahan{\pm}(y):=\frac{e_{1,p}^{\trans} [\Gamma_p^\pm]^{-1}}{f_X(x_0)}\frac{1}{\sqrt{nh_{n,\pm}(y)}}\sum_{i=1}^{n} d^\pm_i K\left(\frac{X_i-x_0}{h_{n,\pm}(y)}\right) z_p\left(\frac{X_i-x_0}{h_{n,\pm}(y)}\right)\varepsilon_i(y),
\end{flalign*}
where $\varepsilon_i(y):= \I{Y_i\leq y} - E[\I{Y_i\leq y}|X_i]$ and $\Gamma_p^\pm:=\int_{\R_\pm} z_p(u)z_p^\trans(u)\,du$.

Second, drawing a standard normal random sample $\{\xi_i\}_{i=1}^n$ independently from the data $\{Y_i,D_i,X_i\}_{i=1}^n$, we propose the \textit{estimated multiplier bootstrap processes  (EMP) } of $\bahan{\pm}$ as
\begin{flalign*}
    &\bahambhatn{\pm}(y)
    :=\frac{e_{1,p}^{\trans} [\Gamma_p^\pm]^{-1}}{\widehat{f}_X(x_0)}\frac{1}{\sqrt{nh_{n,\pm}(y)}}\sum_{i=1}^{n} \xi_i d^\pm_i K\left(\frac{X_i-x_0}{h_{n,\pm}(y)}\right) z_p\left(\frac{X_i-x_0}{h_{n,\pm}(y)}\right)\widehat{\varepsilon}_i(y)
\end{flalign*}
where
$$\widehat{\varepsilon}_i(y)
= \I{Y_i\leq y}
- d_i^+ \Zhtrans{p}{X_i}{+} \betan{p}^+(y)
- d_i^- \Zhtrans{p}{X_i}{-} \betan{p}^-(y)$$
is the first-stage residual estimator, and $\widehat{f}_X$ can be computed using standard kernel density estimation. Under the assumptions in Appendix \ref{apdx:asy}, we demonstrate that $\widehat{\varepsilon}_i(y) \pto{P} \varepsilon_i(y)$ uniformly and $\bahambhatn{\pm}$ are asymptotically equivalent to $\bahan{\pm}$.


Third, using the \textit{Functional Delta Method for bootstrap} (see, for example, Theorem 2.9 of \citet{kosorok2008}), we may approximate the limit process of $\sqrt{nh_n^3(\vartheta)}(\upehat(\vartheta)-\upe(\vartheta))$ by
\begin{flalign}
    \bahambhatn{\upe}
    :=\kappa_0 \widehat{\phi}'_{F_{Y,0}}
    \left(\frac{\bahambhatn{+}(\cdot)/c_+^{3/2}(\cdot) - \widehat{\mathrm{B}}^- _{\xi,n}(\cdot)/c_-^{3/2}(\cdot)}{b'(x_0^+)-b'(x_0^-)}\right), \label{asydist:upe.emp}
\end{flalign}
where $c_\pm(\cdot)$ satisfies Assumption \ref{A:asy.bandwidth}(a); the item in the outer brackets above is the EMP of $\sqrt{nh_n^3(\cdot)}(\rkdhat{D}(\cdot)-\rkd{D}(\cdot))$.
\begin{remark}
    As Hadamard derivative $\phi'_{F_{Y,0}}$ is a continuous linear operator in its domain $\mathbb{D}_0$ (see Definition \ref{def:hadamard-diff}), we have
    $\phi'_{F_{Y,0}}\left(g+\delta_n h_n\right)-\phi'_{F_{Y,0}}(g)=\delta_n\phi'_{F_{Y,0}}(h_n)$ for functional $g \in \mathbb{D}_0 \subset \ell^\infty(\R)$. This implies that the Hadamard derivative of $\phi'_{F_{Y,0}}$ at $g=\rkd{D}$ (i.e., $\phi''_{F_{Y,0},\rkd{D}}$) is equal to $\phi'_{F_{Y,0}}$.
\end{remark}

Once the approximations of these limit processes are established, we may conduct the following statistical inference procedures.
\newline
\textit{(i) Uniform confidence bands:} %////////////////////////////
Let $\varTheta^o$ denote the interior of $\varTheta \ni \vartheta$.
Using the EMP (\ref{asydist:upe.emp}), we compute $\overline{G}_{\xi,n}:=\sup_{\vartheta\in\varTheta^o}|\bahambhatn{\upe}(\vartheta)|$ and obtain its ($1-\alpha$)-quantile estimates $\widehat{Q}_{\overline{G}_{\xi,n}}(1-\alpha)$ given $\alpha \in (0,1)$. Hence, the uniform confidence bands of $\upe$ assume the form of
$$\left[\upehat(\vartheta) \pm \frac{1}{\sqrt{nh_n^3(\vartheta)}}\widehat{Q}_{\overline{G}_{\xi,n}}(1-\alpha)\right].$$
\textit{(ii) Test of treatment nullity:} %///////////////////////////
To test the null hypothesis of uniform treatment nullity
\begin{flalign*}
    \mathscr{H}^S_0: \upe(\vartheta) = 0 \; \text{ for any $\vartheta \in \varTheta^o$,}
\end{flalign*}
we may use $T^{\upe}:=\sup_{\vartheta\in\varTheta^o}\sqrt{nh_n^3(\vartheta)}|\upehat(\vartheta)|$ as the test statistic and the $(1-\alpha)$-quantile of  $\sup_{\vartheta\in\varTheta^o}|\bahambhatn{\upe}(\vartheta)|$ as the critical value. \\
\textit{(iii) Test of treatment homogeneity:} %/////////////////////
For the heterogeneous effects $\udpe$ and $\uqpe$, to test the null hypothesis of treatment homogeneity
\begin{flalign*}
    &\mathscr{H}^H_0: \udpe(y) = \udpe(y')\; \text{ for any } y,y' \in \supp{Y,0}^o \\
    \text{and }\, &\mathscr{H}^H_0: \uqpe(\tau) = \uqpe(\tau')\; \text{ for any } \tau,\tau' \in \mathcal{T}\subset(0,1),
\end{flalign*}
we can use
\begin{flalign*}
    &\sup_{y\in \supp{Y,0}^o}\sqrt{nh_n^3(y)}\left| \udpehat(y)-\frac{1}{|\supp{Y,0}^o|}\int_{y\in\supp{Y,0}^o}\udpehat(y)\,dy \right| \\
    \text{and }\,
    &\sup_{\tau\in \mathcal{T}}\sqrt{nh_n^3(\tau)}\left| \uqpehat(\tau)-\frac{1}{|\mathcal{T}|}\int_{\tau\in\mathcal{T}}\uqpehat(\tau)\,d\tau \right|
\end{flalign*}
as the test statistics, respectively, where $\lvert A \rvert$ represents the length (Lebesgue measure) for any set $A$. Then, the critical values of the above-given two test statistics are the $(1-\alpha)$-quantiles of
\begin{flalign*}
    &\sup_{y\in \supp{Y,0}^o}\sqrt{nh_n^3(y)}\left| \bahambhatn{\udpe}(y)-\frac{1}{|\supp{Y,0}^o|}\int_{y\in\supp{Y,0}^o}\bahambhatn{\udpe}(y)\,dy \right| \\
    \text{ and }\,
    &\sup_{\tau\in \mathcal{T}}\sqrt{nh_n^3(\tau)}\left| \bahambhatn{\uqpe}(\tau)-\frac{1}{|\mathcal{T}|}\int_{\tau\in\mathcal{T}}\bahambhatn{\uqpe}(\tau)\,d\tau \right|,
\end{flalign*}
respectively.

%---------------------------------------------------------
\subsection{Step-by-step procedures} \label{sec:stats.procedures}
%---------------------------------------------------------
In this section, we summarize the previous overview into the step-by-step procedures.
Recall that $e_{\nu,p}:=(0,\ldots,1_{\nu+1},0,\ldots,0)^\trans$ denotes the $(\nu+1)$-th standard basis of $\R^{p+1}$;
% covariance
$\di{+}:=\I{X_i \geq x_0}$ and the same is true for $\di{-}$.
%Let $\varepsilon_i(y):= \I{Y_i\leq y} - E[\I{Y_i\leq y}|X_i]$.

% //////////////////////////////////////////////////////////
\begin{algorithm}[\normalfont Estimation and inference]\label{alg:infer}~\\
    The bandwidth selectors used in each of the following steps are presented in Appendix D.
    \begin{enumerate}[\textit{Step} 1.]
        \item \label{alg:esti.ytau}
        We pick a finite set $\mathcal{T}\subset (0,1)$ of grid points of quantiles $\tau$ and estimate $Q_{Y|X}(\tau|x_0)$ by
        \begin{flalign*}
            \widehat{Q}_{Y|X}(\tau|x_0) = \argmin{\alpha\in\R}\sumn \rho_{\tau}\left(Y_i-\alpha\right)K\left(\frac{X_i-x_0}{h_{Q,\tau}}\right),
        \end{flalign*}
        where $\rho_{\tau}(u):=(\tau-\I{u<0})u$ is the check function.
        To save space, we write $\ytau:=\widehat{Q}_{Y|X}(\tau|x_0)$.

        \item \label{alg:beta}
        We set an integer $p \geq 1$ as the order for the main local polynomial regressions  and compute the coefficient estimators
        \begin{flalign*}
            \betan{p}^\pm(\ytau)
            = \argmin{\beta\in \R^{p+1}} \sumn \di{\pm} \left[\I{Y_i\leq \ytau} - z^\trans_p\left(\frac{X_i-x_0}{h_{n,\pm}(\ytau)}\right) \beta \right]^2 K\left(\frac{X_i-x_0}{h_{n,\pm}(\ytau)}\right).
        \end{flalign*}
        for each $\tau \in \mathcal{T}$.
        Then, we obtain $\widehat{\dev{X}{F_Y}}(\ytau|x_0^\pm)= e_{1,p}^\trans \betan{p}^\pm(\ytau)/h_{n,\pm}(\ytau)$ and the first-stage residual estimates
        \begin{flalign*}
            \widehat{\varepsilon}_i(\ytau)
            = \I{Y_i\leq \ytau}
            - d_i^+ z^\trans_p\left(\frac{X_i-x_0}{h_{n,+}(\ytau)}\right)\betan{p}^+(\ytau)
            - d_i^- z^\trans_p\left(\frac{X_i-x_0}{h_{n,-}(\ytau)}\right) \betan{p}^-(\ytau).
        \end{flalign*}

        \item (Estimate $\udpe$) \label{alg:udpe}
        Considering intervention $\intven(d,\delta)$, we calculate $\kappa_0:=\dev{\delta}{\intven}(b(x_0),\delta)|_{\delta=0}$. Then, we use the estimates $\widehat{\dev{X}{F_Y}}(\ytau|x_0^\pm)$ from Step \ref{alg:beta} to compute
        \begin{flalign*}
            \udpehat(\ytau)= \kappa_0 \frac{\widehat{\dev{X}{F_Y}}(\ytau|x_0^+)-\widehat{\dev{X}{F_Y}}(\ytau|x_0^-)}{b'(x_0^+)-b'(x_0^-)}.
        \end{flalign*}

        \item (Estimate $\uqpe$) \label{alg:fyx.uqpe}
        First, we estimate conditional density function $f_{Y|X}$ by
        \begin{flalign*}
            \hat{f}_{Y|X}(\ytau|x_0)
            = \frac{1}{h_Y}\frac{\sumn K\left(\frac{Y_i-\ytau}{h_Y}\right)K\left(\frac{X_i-x_0}{h_X}\right)}{\sumn K\left(\frac{X_i-x_0}{h_X}\right)}.
        \end{flalign*}
        Then, we use estimates $\udpehat(\ytau)$ from Step \ref{alg:udpe} to compute
        \begin{flalign*}
            \uqpehat(\tau) = -\frac{\udpehat(\ytau)}{\hat{f}_{Y|X}(\ytau|x_0)}.
        \end{flalign*}

        \item \label{alg:fx}
        We estimate $f_X(x_0)$ by $\hat{f}_{X}(x_0) = \frac{1}{n h_f}\sumn K\left(\frac{X_i-x_0}{h_f}\right)$.

        \item\label{alg:ubr.B}
        We set a positive integer $B$ of bootstrap iterations. For each iteration $b=1,\ldots B$, we generate multiplier $\{\xi^b_i\}_{i=1}^n \sim \mathcal{N}(0,1)$ independently from the data. Then, we use residual estimates $\widehat{\varepsilon}_i(\ytau)$ from Step \ref{alg:beta} and density estimates $\hat{f}_{X}(x_0)$ from Step \ref{alg:fx} to compute
        \begin{flalign*}
            \widehat{\mathrm{B}}_{\xi^b,n}^{\pm}(\ytau)
            =\frac{e_{1,p}^{\trans} [\Gamma_p^\pm]^{-1}}{\widehat{f}_X(x_0)}\frac{1}{\sqrt{nh_{n,\pm}(\ytau)}}\sum_{i=1}^{n} \xi^b_i d^\pm_i K\left(\frac{X_i-x_0}{h_{n,\pm}(\ytau)}\right) z_p\left(\frac{X_i-x_0}{h_{n,\pm}(\ytau)}\right)\widehat{\varepsilon}_i(\ytau).
        \end{flalign*}

        \item \label{alg:G.udpe}
        Let $h_n(\ytau) = \min\{h_{n,-}(\ytau),h_{n,+}(\ytau)\}$ and $c_\pm(\ytau) = h_{n,\pm}(\ytau)/h_n(\ytau)$. We use $\widehat{\mathrm{B}}_{\xi^b,n}^{\pm}(\ytau)$ from Step \ref{alg:ubr.B} to compute the EMP of $\sqrt{nh_n^3(\ytau)}(\udpehat(\ytau) - \udpe(\ytau))$ as
        \begin{flalign*}
            \widehat{G}^\udpe_{\xi^b,n}(\ytau)
            =\kappa_0\frac{\widehat{\mathrm{B}}^+_{\xi^b,n}(\ytau)/c_+^{3/2}(\ytau) - \widehat{\mathrm{B}}^-_{\xi^b,n}(\ytau)/c_-^{3/2}(\ytau)}{b'(x_0^+)-b'(x_0^-)},
        \end{flalign*}
        Then, we obtain $\overline{G}^{\udpe}_{\xi^b,n} =\max_{\tau \in \mathcal{T}}\big|\widehat{G}^{\udpe}_{\xi^b,n}(\ytau)\big|$.

        \item
        We use $\widehat{f}_{Y|X}(\ytau|x_0)$ from Step \ref{alg:fyx.uqpe} and $\widehat{G}^{\udpe}_{\xi^b,n}(\ytau)$ from Step \ref{alg:G.udpe} to compute the EMP of $\sqrt{nh_n^3(\ytau)}(\uqpehat(\tau) - \uqpe(\tau))$ for the $b$-th bootstrap iteration as
        \begin{flalign*}
            \widehat{G}^{\uqpe}_{\xi^b,n}(\tau)
            =-\frac{\widehat{G}^{\udpe}_{\xi^b,n}(\ytau)}{\hat{f}_{Y|X}(\ytau|x_0)},
        \end{flalign*}
        and, thus, obtain $\overline{G}^{\uqpe}_{\xi^b,n} =\max_{\tau \in \mathcal{T}}\big|\widehat{G}^{\uqpe}_{\xi^b,n}(\tau)\big|$.

        \item
        After $B$ iterations of the bootstrap, we obtain bootstrapped distributions    $\{\overline{G}^{\udpe}_{\xi^b,n}\}_{b=1}^B$ and $\{\overline{G}^{\uqpe}_{\xi^b,n}\}_{b=1}^B$. Compute their $(1-\alpha)$-th empirical quantiles $\widehat{Q}^*_{\{\overline{G}^{\udpe}_{\xi^b,n}\}_{b=1}^B}(1-\alpha)$ and $\widehat{Q}^*_{\{\overline{G}^{\uqpe}_{\xi^b,n}\}_{b=1}^B}(1-\alpha)$, respectively.

        \item(Construct the uniform confidence bands)
        Use the above empirical quantiles to construct the asymptotically valid $100(1-\alpha)\%$ uniform confidence bands as
        \begin{flalign*}
            &\udpe(\ytau): \quad \left[\udpehat(\ytau) \pm \frac{1}{\sqrt{nh_n^3(\ytau)}} \widehat{Q}^*_{\{\overline{G}^{\udpe}_{\xi^b,n}\}_{b=1}^B}(1-\alpha) \right]; \\
            \text{and }\; &\uqpe(\tau): \quad \left[\uqpehat(\tau) \pm \frac{1}{\sqrt{nh_n^3(\ytau)}} \widehat{Q}^*_{\{\overline{G}^{\uqpe}_{\xi^b,n}\}_{b=1}^B}(1-\alpha) \right],
        \end{flalign*}
        where estimates $\udpehat$ are from Step \ref{alg:udpe} and $\uqpehat$ are from Step \ref{alg:fyx.uqpe}.

        \item(Test the uniform treatment nullity) \label{alg:test.null}\\
        (i) For $\udpe(\ytau)$, we use $T^{\udpe}_S:=\max_{\tau \in \mathcal{T}}\big|\sqrt{nh_n^3(\ytau)} \udpehat(\ytau)\big|$ as the test statistic and $\widehat{Q}^*_{\{\overline{G}^{\udpe}_{\xi^b,n}\}_{b=1}^B}(1-\alpha)$ as the critical value.\\
        (ii) For $\uqpe(\tau)$, we use $T^{\uqpe}_S:=\max_{\tau \in \mathcal{T}}\big|\sqrt{nh_n^3(\ytau)}\uqpehat(\tau)\big|$ as the test statistics and  $\widehat{Q}^*_{\{\overline{G}^{\uqpe}_{\xi^b,n}\}_{b=1}^B}(1-\alpha)$ as the critical value.

        \item(Test the treatment homogeneity)\label{alg:test.homo}\\
        (i) For $\udpe(\ytau)$, we use
        $$T^{\udpe}_H:=\max_{\tau \in \mathcal{T}}\sqrt{nh_n^3(\ytau)}\left|\udpehat(\ytau) - \frac{1}{|\mathcal{T}|} \sum_{\tau \in \mathcal{T}}\udpehat(\ytau)\right|$$
        as the test statistic and
        $$(1-\alpha)\text{-quantile of } \bigg\{\max_{\tau \in \mathcal{T}}\big|%
        \overline{G}^{\udpe}_{\xi^b,n}(\ytau) -  \frac{1}{|\mathcal{T}|}\sum_{\tau \in \mathcal{T}} \overline{G}^{\udpe}_{\xi^b,n}(\ytau)
        \big|\bigg\}_{b=1}^B$$
        as the critical value.\\
        (ii) For $\uqpe(\tau)$, we use
        $$T^{\uqpe}_H:=\max_{\tau \in \mathcal{T}}\sqrt{nh_n^3(\ytau)}\left|\uqpehat(\tau) - \frac{1}{|\mathcal{T}|}\sum_{\tau\in\mathcal{T}}\uqpehat(\tau)\right|$$
        as the test statistics and
        $$(1-\alpha)\text{-quantile of } \bigg\{\max_{\tau \in \mathcal{T}}\big|%
        \overline{G}^{\uqpe}_{\xi^b,n}(\tau) -  \frac{1}{|\mathcal{T}|}\sum_{\tau \in \mathcal{T}} \overline{G}^{\uqpe}_{\xi^b,n}(\tau)
        \big|\bigg\}_{b=1}^B$$
        as the critical value.
    \end{enumerate}
\end{algorithm}

%/////////////////////////////////////////
\begin{remark}
    We can apply these procedures analogously to some homogeneous $\upe$s, where the main differences are the estimators in Steps \ref{alg:esti.ytau} and \ref{alg:beta}.
    For $\umpehat$, we do not need to estimate $Q_{Y|X}(\tau|x_0)$ or replace $\I{Y_i \leq \ytau}$ with $Y_i$ in Step \ref{alg:beta}.
    For $\cvpehat$, we should first estimate constants $\mu_0$, $v_0$, $\gamma_V$, and $\gamma_E$, and, subsequently, replace $\I{Y_i \leq \ytau}$ with $\widehat{\gamma}_V (Y-\widehat{\mu_0})^2-\widehat{\gamma}_E  Y$ in Step \ref{alg:beta}. Notably, the residual estimates do not depend on $\tau$ for the homogeneous effects.
\end{remark}

%////////////////////////////////////////
\begin{remark}
    Further, we can compute the \textit{multiplier bootstrap $p$-value} for the test statistics in Steps \ref{alg:test.null} and \ref{alg:test.homo} of Algorithm \ref{alg:infer}: For example, the $p$-value of $T^{\uqpe}_H$ is defined as $p_H:=\frac{1}{B}\sum_{b=1}^{B} 1\{ T^{\uqpe}_{H,b} > T^{\uqpe}_H \}$.
\end{remark}
These procedures are sufficient to achieve several empirical goals. Appendix B presents the formal theory justifying these procedures.

