%------------------------------------------------------------------------
\subsection{Regularity assumptions} \label{apdx:id.assu}
%------------------------------------------------------------------------

First, we present the concept of \textit{Hadamard-differentiability}, which is consistent with that in Section 2.2.4 of \citet{kosorok2008} or that in Chapter 3.10 of \citet{vw2023}.
\begin{definition}[\normalfont Hadamard-Differentiability] \label{def:hadamard-diff}
    Let $\mathbb{D}$ and $\mathbb{E}$ be normed spaces. A functional $\phi: \mathbb{D}_\phi \subset \mathbb{D} \to \mathbb{E}$ is called \textit{Hadamard-differentiable at $F \in \mathbb{D}_\phi$ tangentially to a subset $\mathbb{D}_0 \subset \mathbb{D}$} if there exists a continuous linear functional $\phi'_F:\mathbb{D}_0 \subset \mathbb{D} \to \mathbb{E}$ such that
    \begin{flalign}
        \left\| \frac{\phi\left(F+\delta_n\,h_n\right)-\phi(F)}{\delta_n} - \phi'_F(h)\right\|_{\mathbb{E}} \to 0 \notag
    \end{flalign}
    for all sequences $\{h_n\} \subset \mathbb{D}$ and $\{\delta_n\} \subset \R$ such that $F+\delta_n h_n \in \mathbb{D}_\phi$ for any $n$ and $\delta_n \to 0$, $h_n\to h$ as $n\to \infty$. We call $\phi'_F$ the Hadamard derivative of $\phi$ at $F$. Moreover, if $\mathbb{D}_0 = \mathbb{D}$, then  $\phi: \mathbb{D}_\phi \subset \mathbb{D} \to \mathbb{E}$ is called Hadamard-differentiable at $F \in \mathbb{D}_\phi$, for simplicity.
\end{definition}

In addition to Assumptions \ref{A:sk}, \ref{A:struct.m.G} and \ref{A:f_YX} given in the main text,  we propose the following regularity conditions.

Let $\dev{D}{m}^{x}(U):=\dev{D}{m}(b(x),x,U)$ and $\dev{D}{m}(U):=\dev{D}{m}(b(x_0),x_0,U)$. Write $\dev{\delta}{m}(U)$ for $\dev{\delta}{m(\intven(b(x_0),\delta),x_0,U)}|_{\delta=0}=\kappa_0 \dev{D}{m}(U)$, where $\kappa_0:=\dev{\delta}{\intven}(b(x_0),\delta)|_{\delta=0}$.
\begin{assumptionA} \label{A:hm.Qyxsmooth.mdta}
     Suppose that $\dev{\delta}{m}(U)$ is Borel measurable and satisfies
    \begin{flalign}
        P\left[\big|m(\intven(b(x_0),\delta),x_0,U)-m(b(x_0),x_0,U)-\delta\dev{\delta}{m}(U)\big|\geq\varepsilon\,|\delta|\big|X=x_0\right] =  o(\delta)\notag
    \end{flalign}
    as $\delta \to 0$ for any $\varepsilon > 0$.
\end{assumptionA}


\begin{assumptionA}\label{A:f_Y_mdta.dct}
    (a) The conditional distribution $F_{Y,\dev{\delta}{m}|X=x_0}$ is absolutely continuous; its conditional density $f_{Y,\dev{\delta}{m}|X}(y,y'|x_0)$ is continuous in $y$ for any $y'$.
    (b) There exists a Lebesgue integrable function $g:\R \to (0,\infty)$ satisfying $\int|y'|g(y')\,dy' < \infty$ such that
    $f_{Y,\dev{\delta}{m}|X}(y,y'|x_0) \leq g(y')$ for any $y$ and $y'$.
\end{assumptionA}


%////////////////////////////
Let $I_{x_0}^o:=I_{x_0} \backslash \{x_0\}$, $\dev{D}{\bar{m}}^x(U):= b'(x)\dev{D}{m}^x(U)$ and $\nabla_x m^x(U) := \left(\dev{D}{\bar{m}}^x(U), \dev{X}{m}^x(U) \right)$. %
\begin{assumptionA} \label{A:hm.mdxt}
%    (a) $Q_{Y|X}(\tau|\cdot)$ is continuous on $I_{x_0}$ and partially differentiable on $I_{x_0}^o$ for any $\tau \in (0,1)$.
    % Moreover, the derivative $\dev{X}{Q_Y}(\tau|x)$ is continuous in $\tau$ given $x\in I^o_{x_0}$.
    (a) For any $\tau\in (0,1)$ and $y \in I_{ y_{\tau,0}}$, $F_{Y|X}(y|\cdot)$ is continuous at $x_0$ and partially differentiable on $I^o_{x_0}$, moreover, $\dev{X}{F_Y}(y|x^\pm_0)$ are continuous in $y$.
    % and the derivatives $\dev{X}{F_Y}(y|x^\pm_0)$ are continuous in $y$.
    (b) For any $x\in I_{x_0}^o$ and $t>0$ sufficiently small such that $x+t \in I_{x_0}^o$,
    $\nabla_x m^x(U)$ is Borel measurable and satisfies
    \begin{flalign*}
        P\left[\left\lvert m \left(b(x+t),x+t, U \right)-m\left(b(x), x, U \right)-
        \nabla_x m^x(U)\, \mathbf{t}\right\rvert \geq \varepsilon \left\| \mathbf{t}\right\| \big| X=x\right]= o(t)
    \end{flalign*}
    as $t \downarrow 0$ for any $\varepsilon > 0$, where $\mathbf{t}:=(t, t)^{\trans}$.
\end{assumptionA}

%-----
We let $I^o_{ y_{\tau,0}}:=I_{y_{\tau},0}\backslash\{y_\tau(x_0)\}$ and write $\dev{D}{m}^x=\dev{D}{m}^x(U)$, $\dev{D}{\bar{m}}^x=\dev{D}{\bar{m}}^x(U)$ and $\dev{X}{m}^x=\dev{X}{m}^x(U)$ to save space.
\begin{assumptionA} \label{A:f_y.bar_md.mx.dct}
    For any $x \in I_{x_0}^o$ and $ y \in I^{o}_{ y_{\tau,0}}$,
    (a) the conditional distribution $F_{Y,\dev{D}{\bar{m}}^x,\dev{X}{m}^x|X=x}$ is absolutely continuous; its density $f_{Y,\dev{D}{\bar{m}}^x,\dev{X}{m}^x|X}(y,\bar y,y''|x)$ is continuous in $y$ given $\bar{y}$ and $y''$;
    (b) there exists a Lebesgue integrable function $\eta: \R^2 \to [0,\infty)$ such that for any $\bar{y}$ and $y''$, $f_{Y,\dev{D}{\bar{m}}^x, \dev{X}{m}^x|X}(y,\bar{y},y''|x) \leq \eta(\bar{y},y'')$, where $\eta$ satisfies $\iint |\Bar{y}|\eta(\bar{y},y'')\,d\bar{y}\,dy'' < \infty $ and $\iint |y''|\eta(\bar{y},y'')\,d\bar{y}\, dy'' < \infty $.
\end{assumptionA}

Let $\mathcal{U}(x,y):=\{u \in \R^{d_u} : m(b(x),x,u) \leq y \}$. %
\begin{assumptionA}\label{A:fux.dct}
    For any $\tau \in (0,1)$, $x \in I_{x_0}$ and $u \in \mathcal{U}(x,y_{\tau}(x))$,
    (a) the conditional distribution $F_{U|X=x}$ is absolutely continuous; its density $f_{U|X}(u|x)$ is continuously differentiable in $x$ given $u$;
    (b) there exists a Lebesgue integrable function $\bar{f}:\R^{d_u} \to [0,\infty)$ such that
    $\sup_{t\in N_\varepsilon\backslash\{0\}}\lvert (f_{U|X}(u|x+t)-f_{U|X}(u|x))/t\rvert \leq \bar{f}(u)$.
\end{assumptionA}
%-----
\begin{assumptionA} \label{A:f_uxy.dct}
    For any $\tau \in (0,1)$, $x \in I_{x_0}$ and $y \in I_{y_{\tau,0}}$, (a) the conditional distribution $F_{U|X=x,Y=y}$ is absolutely continuous; its density $f_{U|X,Y}(u|x,y)$ is continuous at $(x,y)=(x_0,y_{\tau}(x_0))$ given $u$;
    (b) there exist Lebesgue integrable functions $g_1, g_2: \R^{d_u} \to [0,\infty)$ such that $|\dev{D}{m}(b(x),x,u)| \leq g_1(u)$ and $|\dev{X}{m}(b(x),x,u)| \leq g_2(u)$ for any $u\in \mathcal{U}(x,y_{\tau}(x))$, where $g_1, g_2$ satisfy $E[g_1(U)|X=x,Y=y]<\infty$ and $E[g_2(U)|X=x,Y=y]<\infty$, respectively.
\end{assumptionA}
%------
\begin{assumptionA} \label{A:id.cory}
    (a) $F_{Y|X=x_0}$ has the compact support $\supp{Y,0}$. %
    (b) There exists a Lebesgue integrable function $\lambda:\R \to [0,\infty)$ such that $\int |y|\lambda(y)\,dy < \infty$ and $|\dev{X}{F_Y}(y|x)|\leq \lambda(y)$ for any $x\in I_{x_0}^o$ and  $y\in\supp{Y,0}$.
\end{assumptionA}

Assumptions \ref{A:hm.Qyxsmooth.mdta} and \ref{A:hm.mdxt} are used to approximate the structural derivative at different $x$ in a probabilistic sense. Assumptions \ref{A:f_Y_mdta.dct}, \ref{A:f_y.bar_md.mx.dct}, \ref{A:fux.dct} and \ref{A:f_uxy.dct} are used to facilitate the Dominated Convergence Theorem (DCT) when taking the limit $\delta \to 0$ or $x \to x_0$, where Assumption \ref{A:fux.dct} is parallel to Assumption 4 of \citet{card2015ecta} and Assumption 2 (iii) and 5 (ii) of \citet{cs2019}. Assumption \ref{A:id.cory} is used to derive the Hadamard derivatives in the proofs of the corollaries.


%--------------------------------------------
\subsection{Auxiliary lemmas}\label{apdx:id.assu.lem}
%--------------------------------------------
The following lemmas are used to prove the identification of $\udpe$. Lemma \ref{lem:udpe.ocqr} establishes the relationship between $\udpe$ and an outcome conditioned structural derivative
\begin{flalign*}
    \ocqr{D}(x_0,y)
    &:=E\big[\dev{D}{m}(b(x_0),x_0,U)|X=x_0,Y=y\big].
\end{flalign*}
Lemma \ref{lem:qpd.decomp.ocqr} presents a structural decomposition (or reduced-form representation) of the distribution partial derivative $\dev{X}{F_Y}(y|x)$.
% //////////////////////////
\begin{lemmaA} \label{lem:udpe.ocqr}
    Suppose that the data are generated by (\ref{dgp:y}) and we adopt the policy intervention (\ref{dgp:d_dta}). If Assumptions \ref{A:struct.m.G}, \ref{A:f_YX},  \ref{A:hm.Qyxsmooth.mdta} and \ref{A:f_Y_mdta.dct} hold, then
    \begin{flalign}
        \udpe(y)
        =-\kappa_0 \ocqr{D}(x_0,y) f_{Y|X}\left(y|x_0\right) \notag
    \end{flalign}
    for any $ y \in \supp{Y,0}$.
\end{lemmaA}


\begin{lemmaA}\label{lem:qpd.decomp.ocqr}
    If Assumptions \ref{A:sk}(a), \ref{A:struct.m.G}, \ref{A:f_YX}, and \ref{A:hm.Qyxsmooth.mdta}--\ref{A:fux.dct} hold, we have
%    \begin{flalign}
%        \dev{X}{Q_Y}(\tau|x)
%        = b'(x) \ocqr{D}(x,y_\tau(x)) + \ocqr{X}(x,y_\tau(x)) - \frac{1}{f_{Y|X}(y_\tau(x)|x)} \int_{\mathcal{U}(x,y_\tau(x))}\dev{X}{f_{U|X}}(u|x)\,du\notag
%    \end{flalign}
%    for any $\tau \in (0,1)$ and $x\in I_{x_0}^o$, where $\ocqr{X}(x,y):=E[\dev{X}{m}^x(U)|X=x,Y=y]$ and $\dev{X}{m}^x(u):=\dev{X}{m}(b(x),x,u)$.
    \begin{flalign*}
        \dev{X}{F_Y}(y|x)
        =-\left\{ b'(x) \ocqr{D}(x,y) + \ocqr{X}(x,y) \right\} f_{Y|X}(y|x) + \int_{\mathcal{U}(x,y)}\dev{X}{f_{U|X}}(u|x)\,du
    \end{flalign*}
    for any $x\in I_{x_0}^o$ and $y \in \supp{Y|X=x}$, where $\ocqr{X}(x,y):=E[\dev{X}{m}^x(U)|X=x,Y=y]$ and $\dev{X}{m}^x(u):=\dev{X}{m}(b(x),x,u)$.
\end{lemmaA}

