\subsection{Proof for identification results}\label{apdx:id.pf}
%------------------------------------------------------
\begin{proof}[\normalfont\textbf{Proof of Lemma \ref{lem:udpe.ocqr}}]
    For $\delta \ne 0 $, according to the definition of $\udpe(y)$ and counterfactual outcome (\ref{dgp:y_delta}), we have
    \begin{flalign}
        \udpe(y)
        = \lim\limits_{\delta \to 0}\delta^{-1} A_\delta(y), \label{udpe-limA.dta}
    \end{flalign}
    where
    \begin{flalign}
        A_\delta(y)
        &:= F_{Y_{\delta}|X}(y|x_0)-F_{Y|X}(y|x_0) \notag\\
        &= P\left[m(\intven(b(x_0);\delta), x_0, U) \leq y \right|X=x_0]
        - P\left[m(b(x_0), x_0, U) \leq y \right|X=x_0] \notag\\
        &= P\left[ Y \leq y-\{m(\intven(b(x_0);\delta), x_0, U)-m(b(x_0), x_0, U)\}|X=x_0\right]- P\left[Y \leq y |X=x_0 \right] \notag\\
        &\eq{(1)}{=} P\left[ y< Y \leq y-\{m(\intven(b(x_0);\delta), x_0, U)-m(b(x_0), x_0, U)\}|X=x_0\right] \notag\\
        &\quad- P\left[ y-\{\intven(b(x_0);\delta), x_0, U)-m(b(x_0), x_0, U)\} < Y \leq y |X=x_0 \right] \notag\\
        &\eq{(2)}{=}P\left[ y \leq Y \leq y- \delta \dev{\delta}{m}(U) |X=x_0 \right] - P\left[ y -\delta \dev{\delta}{m}(U) \leq Y \leq y |X=x_0 \right] + o(\delta) \notag
    \end{flalign}
    as $\delta\to 0$, where equality (1) follows from the law of total probability; equality (2) follows from Assumptions \ref{A:struct.m.G} and \ref{A:hm.Qyxsmooth.mdta}.

    If $\delta > 0$, then for $\delta \downarrow 0$,
    \begin{flalign}
        A_\delta(y)
        &=P\left[ Y \geq y, \dev{\delta}{m}(U) \leq \frac{y-Y}{\delta} \big|\,X=x_0 \right] - P\left[ Y \leq y, \dev{\delta}{m}(U) \geq \frac{y-Y}{\delta} \big|\,X=x_0 \right] + o(\delta) \notag\\
        &= \int_{y}^{\infty}\int_{-\infty}^{\frac{y-t}{\delta}} f_{Y,\dev{\delta}{m}|X}(t,y'|x_0)\,dy'\,dt - \int_{-\infty}^{y}\int_{\frac{y-t}{\delta}}^{\infty} f_{Y,\dev{\delta}{m}|X}(t,y'|x_0)\,dy'\,dt + o(\delta) \notag\\
        &\eq{(3)}{=}\delta \int_{-\infty}^{0}\int_{-\infty}^{u} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,dy'\,du  \notag\\
        &\quad -\delta \int_{0}^{\infty}\int_{u}^{\infty} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,dy'\,du + o(\delta) \notag \\
        &\eq{(4)}{=}\delta \int_{-\infty}^{0}\int_{y'}^{0} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,du\,dy' \notag\\
        &\quad -\delta \int_{0}^{\infty}\int_{0}^{y'} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,du\,dy' + o(\delta) \notag \\
        &=\delta \int_{-\infty}^{\infty}\int_{y'}^{0} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,du\,dy' + o(\delta), \notag
    \end{flalign}
    where equality (3) follows from the change of variable $u=(y-t)/\delta$ ($\delta > 0$); equality (4) follows from interchanging the order of integration.

    If $\delta < 0$, then for $\delta \uparrow 0$,
    \begin{flalign}
        A_\delta(y)
        &=P\left[ Y \geq y, \dev{\delta}{m}(U) \geq \frac{y-Y}{\delta} \big|\,X=x_0 \right] - P\left[ Y \leq y, \dev{\delta}{m}(U) \leq \frac{y-Y}{\delta} \big|\,X=x_0 \right] + o(\delta) \notag\\
        &= \int_{y}^{\infty}\int_{\frac{y-t}{\delta}}^{\infty} f_{Y,\dev{\delta}{m}|X}(t,y'|x_0)\,dy'\,dt - \int_{-\infty}^{y}\int_{-\infty}^{\frac{y-t}{\delta}} f_{Y,\dev{\delta}{m}|X}(t,y'|x_0)\,dy'\,dt + o(\delta) \notag\\
        &\eq{(5)}{=}-\delta \int_{0}^{\infty}\int_{u}^{\infty} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,dy'\,du \notag\\
        &\quad +\delta \int_{-\infty}^{0}\int_{-\infty}^{u} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,dy'\,du + o(\delta) \notag \\
        &\eq{(6)}{=}-\delta \int_{0}^{\infty}\int_{0}^{y'} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,du\,dy' \notag\\
        &\quad + \delta \int_{-\infty}^{0}\int_{y'}^{0} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,du\,dy' + o(\delta) \notag\\
        &=\delta \int_{-\infty}^{\infty}\int_{y'}^{0} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,du\,dy' + o(\delta),\notag
    \end{flalign}
    where equality (5) follows from the change of variable $u=(y-t)/\delta$ ($\delta < 0$); equality (6) follows from interchanging the order of integration.

    Thus, for $\delta\to 0$, we have
    \begin{flalign}
        A_\delta(y)= \delta \int_{-\infty}^{\infty}\int_{y'}^{0} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,du\,dy' + o(\delta). \notag
    \end{flalign}
    Furthermore, substituting the above into (\ref{udpe-limA.dta}) yields
    \begin{flalign}
        \udpe (y)
        &=\lim\limits_{\delta \to 0} \int_{-\infty}^{\infty}\int_{y'}^{0} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,du\,dy' \notag\\
        &\eq{(7)}{=}\int_{-\infty}^{\infty}\int_{y'}^{0}\lim\limits_{\delta \to 0} f_{Y,\dev{\delta}{m}|X}(y-\delta u,y'|x_0)\,du\,dy' \notag\\
        &\eq{(8)}{=}-\int y' f_{Y,\dev{\delta}{m}|X}(y,y'|x_0) \,dy' \notag \\
        &=-E\left[\dev{\delta}{m}(U)|X=x_0,Y=y\right] f_{Y|X}(y|x_0) \notag\\
        &=-\underbrace{\dev{\delta}{\intven}(b(x_0),\delta)|_{\delta=0}}_{\kappa_0}\,
        \underbrace{E\left[\dev{D}{m}(U)|X=x_0,Y=y\right]}_{\ocqr{D}(x_0,y)}f_{Y|X}(y|x_0), \notag
    \end{flalign}
    where equality (7) follows from Assumption \ref{A:f_Y_mdta.dct}(b), using the dominated convergence theorem (hereafter DCT); equality (8) follows from Assumption \ref{A:f_Y_mdta.dct}(a); the continuity of $f_{Y|X}$ follows from Assumption \ref{A:f_YX}.
    This completes the proof.
\end{proof}

%///////////////////////////////////////////////////////////////////////
\begin{proof}[\normalfont \textbf{Proof of Lemma \ref{lem:qpd.decomp.ocqr}}]
   Let $y_{\tau}(x):=Q_{Y|X}(\tau|x)$.
%    Given closed intervals $I_{x_0}$ of $x_0$ and $I_{ y_{\tau,0}}$ of $y_{\tau}(x_0)$ for fixed $\tau \in (0,1)$, let $I^o_{x_0}:=I_{x_0}\backslash\{x_0\}$ and $I^o_{y_{\tau,0}}:=I_{y_{\tau,0}}\backslash\{y_{\tau}(x_0)\}$.
%    Since Assumption \ref{A:sk}(a) and Assumption \ref{A:hm.mdxt}(a) have the continuity of $b(\cdot)$ and $y_\tau(\cdot)$, given $x \in I^o_{x_0}$, we may choose $t >0$ sufficiently small such that $I_{x,t}:=[x-t , x+t]\subset I^{o}_{x_0}$, and the images $b(I_{x,t})\subset b(I^{o}_{x_0})$, $y_{\tau}(I_{x,t})\subset I^{o}_{y_{\tau,0}}$.
    For any $x\in I^o_{x_0}:=I_{x_0}\backslash\{x_0\}$, we let $t >0$ sufficiently small such that $[x-t, x+t]\subset I^{o}_{x_0}$.
    According to the DGP (\ref{dgp:y}), we have
    \begin{flalign}
        \tau
        &=P[Y \leq y_{\tau}(x)|X=x]
        =P[m(b(x),x,U)\leq y_{\tau}(x)|X=x] \notag\\
        \tau
        &=P[Y \leq y_{\tau}(x+t)|X=x+t]
        =P[m(b(x+t),x+t,U)\leq y_{\tau}(x+t)|X=x+t] \notag
    \end{flalign}
    Thus,
    \begin{flalign}
        0&=P[m(b(x+t),x+t,U)\le y_{\tau}(x+t)|X=x+t]-P[m(b(x),x,U)\le y_{\tau}(x)|X=x]&\notag\\
        &=A_{1,t}(\tau,x) + A_{2,t}(\tau,x)
        + A_{3,t}(\tau,x), \notag
    \end{flalign}
    where
    \begin{flalign}
        A_{1,t}(\tau,x)
        &=P[m(b(x+t),x+t,U)\le y_{\tau}(x+t)|X=x+t]\notag\\
        &\quad -P[m(b(x+t),x+t,U)\le y_{\tau}(x)|X=x+t], \label{sk3-A1}\\
        A_{2,t}(\tau,x)
        &=P[m(b(x+t),x+t,U)\le y_{\tau}(x)|X=x+t ]\notag\\
        &\quad -P[m(b(x+t),x+t,U)\le y_{\tau}(x)|X=x], \label{sk3-A2} \\
        A_{3,t}(\tau,x)
        &=P[m(b(x+t),x+t,U)\le y_{\tau}(x)|X=x]\notag\\
        &\quad -P[m(b(x),x,U) \le y_{\tau}(x)|X=x]. \label{sk3-A3}
    \end{flalign}
    This implies that
    \begin{flalign}
        0=\lim_{t \downarrow 0}t^{-1} A_{1,t}(\tau,x)
        +\lim_{t \downarrow 0}t^{-1}A_{2,t}(\tau,x)
        +\lim_{t \downarrow 0}t^{-1}A_{3,t}(\tau,x) \label{sk3_limA}
    \end{flalign}
    if the limits exist. The following claim proves this.
    \begin{claimA} \label{sk3_cla1}~
        For any $\tau \in (0,1)$ and $x\in I^{o}_{x_0}$,
        \begin{enumerate}
            \item[(i)]
            $\lim\limits_{t \downarrow 0}t^{-1} A_{1,t}(\tau,x)
%            = \dev{X}{Q_Y}(\tau|x)\,f_{Y|X}(y_{\tau}(x)|x)$;
            = -\dev{X}{F_Y}(y_{\tau}(x)|x)$.

            \item[(ii)]
            $\lim\limits_{t \downarrow 0}t^{-1} A_{2,t}(\tau,x)
            = \int_{\mathcal{U}(x,y_{\tau}(x))}\dev{X}{f_{U|X}}(u|x)\,du $, where $\mathcal{U}(x,y):=\{u \in \R^{d_u} : m(b(x),x,u) \leq y\}$.

            \item[(iii)]
            $\lim\limits_{t \downarrow 0}t^{-1} A_{3,t}(\tau,x)
            =-\left\{b'(x) \ocqr{D}(x,y_{\tau}(x)) + \ocqr{X}(x,y_{\tau}(x))\right\} f_{Y|X}( y_{\tau}(x)\,|x)$.
        \end{enumerate}
    \end{claimA}
    %	\allowdisplaybreaks
    \begin{pf}
        % prove (i)-----
        \textit{(i)} By equality (\ref{sk3-A1}), we have
        \begin{flalign}
            A_{1,t}(\tau,x)
            &= P\left[Y\leq y_{\tau}(x+t)|X=x+t \right]-P\left[Y\leq y_{\tau}(x)|X=x+t \right] \notag \\
            &= \int_{y_{\tau}(x)}^{y_{\tau}(x+t)}f_{Y|X}(y|x+t)\,dy \notag \\
            &\eq{(1)}{=} f_{Y|X}(y_{\tau,t}(x)|x+t) \left[Q_{Y|X}(\tau|x+t)- Q_{Y|X}(\tau|x)\right] \notag
%            &\eq{2}{=} \left[t \dev{X}{Q_Y}(\tau|x) + o(t)\right] f_{Y|X}(y_{\tau,t}(x)|x+t)\notag \\
%            &\eq{2}{=} t \dev{X}{Q_Y}(\tau|x) f_{Y|X} (y_{\tau,t}(x)|x+t)+o(t),\notag
        \end{flalign}
        for some $y_{\tau,t}(x)$ between $y_{\tau}(x)$ and $y_{\tau}(x+t)$, where equality (1) follows using the first mean-value theorem for the integral under Assumption \ref{A:f_YX}.
        Hence,
        \begin{flalign*}
            \lim\limits_{t \downarrow 0}t^{-1} A_{1,t}(\tau,x)
            &= \lim_{t\downarrow 0} f_{Y|X}(y_{\tau,t}(x)|x+t) \frac{Q_{Y|X}(\tau|x+t)- Q_{Y|X}(\tau|x)}{t} \\
            &\eq{(2)}{=} f_{Y|X}( y_{\tau}(x)|x)\, \dev{X}{Q_Y}(\tau|x) \\
            &\eq{(3)}{=} - \dev{X}{F_Y}(y_{\tau}(x)|x),
        \end{flalign*}
		where equalities (2) and (3) follow by taking the derivative with respect to $x$ on the both sides of $F_{Y|X}(Q_{Y|X}(\tau|x)|x) \equiv \tau $ under Assumptions \ref{A:f_YX} and \ref{A:hm.mdxt}(a), yielding $f_{Y|X}(y_{\tau}(x)|x) \dev{X}{Q_Y}(\tau|x) + \dev{X}{F_Y}(y_{\tau}(x)|x) = 0$.

        % prove (ii)------
        \textit{(ii)}  By equality (\ref{sk3-A2}), we have
        \begin{flalign}
            A_{2,t}(\tau,x)
            &= t\int \I{ m(b(x+t),x+t,u) \leq y_{\tau}(x)} \frac{f_{U|X}(u|x+t) - f_{U|X}(u|x)}{t}\,du. \label{pf.cl-bias.int}
        \end{flalign}
        Thus, under Assumptions \ref{A:struct.m.G}(a) and \ref{A:fux.dct}, applying the DCT  yields
        \begin{flalign}
            \lim\limits_{t \downarrow 0}t^{-1} A_{2,t}(\tau,x)
            &= \int \lim\limits_{t \downarrow 0} \I{m(b(x+t),x+t,u) \leq y_{\tau}(x)} \frac{f_{U|X}(u|x+t) - f_{U|X}(u|x)}{t} \,du \notag\\
            &= \int_{\mathcal{U}(x,y_{\tau}(x))} \partial_X f_{U|X}(u|x)\,du. \notag
        \end{flalign}


        % prove (iii)------
        \textit{(iii)} Based on equality (\ref{sk3-A3}), we have
        \begin{flalign}
            A_{3,t}(\tau,x)
            &\eq{(4)}{=} P\left[Y \leq  y_{\tau}(x)- \left\{m(b(x+t), x+t, U)-m(b(x), x, U)\right\}\,|X=x \right] \notag\\
            &\quad - P\left[Y \leq  y_{\tau}(x)\,|X=x \right] \notag\\
            &\eq{(5)}{=} P\left[ y_{\tau}(x)< Y \leq  y_{\tau}(x)-\left\{m(b(x+t), x+t, U) - m(b(x), x, U) \right\}\,|X=x\right] \notag\\
            &\quad - P\left[ y_{\tau}(x)-\left\{m(b(x+t), x+t, U)-m(b(x), x, U)\right\}< Y \leq  y_{\tau}(x)|X=x \right] \notag\\
            &\eq{(6)}{=} P\left[y_{\tau}(x) \leq Y \leq y_{\tau}(x) - t\,\dev{D}{\bar{m}}^x(U) -t\,\dev{X}{m}^x(U) \,|X=x \right] \notag\\
            & \quad - P\left[ y_{\tau}(x)- t\,\dev{D}{\bar{m}}^x(U) - t\,\dev{X}{m}^x(U) \leq Y \leq y_{\tau}(x)|X=x \right] + o(t), \notag
        \end{flalign}
        where equality (4) follows from the DGP (\ref{dgp:y}); equality (5) follows from the law of total probability; equality (6) follows from Assumptions \ref{A:sk}(a), \ref{A:struct.m.G}(a) and \ref{A:hm.mdxt}(b) as $t \downarrow 0$.
        Furthermore,
        \begin{flalign}
            A_{3,t}(\tau,x)
            &=P\left[Y \geq  y_{\tau}(x),\; \dev{D}{\bar{m}}^x(U) \leq \frac{y_{\tau}(x)-Y}{t} -\dev{X}{m}^x(U) \big| X=x\right]& \notag\\
            &\quad -P\left[Y \leq  y_{\tau}(x),\; \dev{D}{\bar{m}}^x(U) \geq \frac{y_{\tau}(x)-Y}{t} -\dev{X}{m}^x(U)  \big| X=x\right] +o(t)\notag\\
            &= \int_{y_{\tau}(x)}^{\infty} \int_{-\infty}^{\infty} \int_{-\infty}^{\frac{y_{\tau}(x)-y}{t}-y''} f_{Y,\dev{D}{\bar{m}}^x ,\dev{X}{m}^x |X}\left(y, \bar{y}, y''\,|x \right) \,d\bar{y}\,dy''\,dy \notag\\
            &\quad -\int_{-\infty}^{y_{\tau}(x)} \int_{-\infty}^{\infty} \int_{\frac{y_{\tau}(x)-y}{t}-y''}^{\infty} f_{Y,\dev{D}{\bar{m}}^x,\dev{X}{m}^x |X}\left(y, \bar{y}, y''\,|x \right) \,d\bar{y}\,dy''\,dy +o(t) \notag  \\
            &\eq{(7)}{=}t\,\int_{-\infty}^{0} \int_{-\infty}^{\infty} \int_{-\infty}^{u-y''} f_{Y, \dev{D}{\bar{m}}^x,\dev{X}{m}^x |X}\left( y_{\tau}(x)-t u, \bar{y}, y''\,|x\right) \,d\bar{y}\,dy''\,du \notag \\
            &\quad -t\,\int_{0}^{\infty} \int_{-\infty}^{\infty} \int_{u-y''}^{\infty} f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left( y_{\tau}(x)-t u, \bar{y}, y''\,|x \right) \,d\bar{y}\,dy''\,du +o(t) \notag\\
            &\eq{(8)}{=}t\,\int_{-\infty}^{\infty} \int_{-\infty}^{-y''}\int_{\bar{y}+y''}^{0} f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left( y_{\tau}(x)-t u, \bar{y}, y''\,|x\right)\,du\,d\bar{y}\,dy'' \notag\\
            &\quad -t\,\int_{-\infty}^{\infty} \int_{-y''}^{\infty} \int_{0}^{\bar{y}+y''} f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left( y_{\tau}(x)-t u,\bar{y}, y''\,|x \right)\,du\,d\bar{y}\,dy'' +o(t)  \notag \\
            &=t\,\int_{-\infty}^{\infty} \int_{-\infty}^{\infty} \int_{\bar{y}+y''}^{0} f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left( y_{\tau}(x)-t u, \bar{y}, y''\,|x\right) \,du\,dy''\,d\bar{y} +o(t), \notag
        \end{flalign}
        where equality (7) follows from the change of variable $u= (y_{\tau}(x)-y)/t$; equality (8) follows from interchanging the order of integration. %
        Then, applying the DCT under Assumption \ref{A:f_y.bar_md.mx.dct} yields that
        \begin{flalign}
            &\lim_{t \downarrow 0}t^{-1} A_{3,t}(\tau,x) &\notag\\
            &=\int_{-\infty}^{\infty} \int_{-\infty}^{\infty} \int_{\bar{y}+y''}^{0}\lim_{t\downarrow 0} f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left( y_{\tau}(x)-t u, \bar{y}, y''\,|x\right) \,du\,dy''\,d\bar{y} \notag\\
            &=-\int_{-\infty}^{\infty} \int_{-\infty}^{\infty} (\bar{y}+y'') f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left( y_{\tau}(x), \bar{y}, y''\,|x\right)\,dy''\,d\bar{y} \notag\\
            % &=-\bigg\{\int_{-\infty}^{\infty} \int_{-\infty}^{\infty} \lim_{t\downarrow 0} \bar{y}\,f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left( y_{\tau}(x)-t \Dot{y}, \bar{y}, y''\,|x\right)\,d\bar{y}\,dy''\notag\\
            % &\qquad + \int_{-\infty}^{\infty} \int_{-\infty}^{\infty} \lim_{t\downarrow 0} y'' \,f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left( y_{\tau}(x)-t \Dot{y}, \bar{y}, y''\,|x\right)\,dy''\,d\bar{y} \bigg\} \notag\\
            &\eq{(9)}{=}-\bigg\{\int_{-\infty}^{\infty} \int_{-\infty}^{\infty} \bar{y}\,f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left(y_{\tau}(x), \bar{y}, y''\,|x\right)\,d\bar{y}\,dy''\notag\\
            &\qquad +\int_{-\infty}^{\infty} \int_{-\infty}^{\infty} y'' \,f_{Y, \dev{D}{\bar{m}}^x , \dev{X}{m}^x |X}\left(y_{\tau}(x), \bar{y}, y''\,|x\right)\,dy''\,d\bar{y} \bigg\} \notag \\
            &=-\bigg\{
            \int_{-\infty}^{\infty} \int_{-\infty}^{\infty} \bar{y}\,f_{\dev{D}{\bar{m}}^x |X,Y,\dev{X}{m}^x }\left(\bar{y}|x,  y_{\tau}(x), y''\right)\,d\bar{y}\,dF_{\dev{X}{m}^x|X,Y}\left(y''|x,y_{\tau}(x) \right) \notag\\
            &\qquad +\int_{-\infty}^{\infty} \int_{-\infty}^{\infty} y''\,f_{\dev{X}{m}^x|X,Y,\dev{D}{\bar{m}}^x  }\left(y''|x, y_{\tau}(x), \bar{y} \right)\,dy''\,dF_{\dev{D}{\bar{m}}^x |X,Y}\left(\bar y|x,y_{\tau}(x)\right) \bigg\}
            f_{Y|X}(y_{\tau}(x)|x) \notag \\
            &=-\bigg\{
            E \left[ \dev{D}{\bar{m}}^x(U)|X=x, Y=y_{\tau}(x) \right] + E\left[\dev{X}{m}^x(U)|X=x, Y=y_{\tau}(x) \right] \bigg\} f_{Y|X}(y_{\tau}(x)|x) \notag\\
            &=-\bigg\{
            b'(x) \underbrace{E\left[\dev{D}{m}^x(U) |X=x,Y=y_{\tau}(x)\right]}_{\ocqr{D}(x,y_{\tau}(x))} + \underbrace{E\left[\dev{X}{m}^x(U)|X=x,Y=y_{\tau}(x)\right]}_{\ocqr{X}(x,y_{\tau}(x))} \bigg\} f_{Y|X}(y_{\tau}(x)|x) \notag
        \end{flalign}
        where equality (9) follows from interchanging the order of integration under Assumption \ref{A:f_y.bar_md.mx.dct};
    \end{pf}
%    Finally, substituting Claim \ref{sk3_cla1}'s (i)--(iii) into \ref{sk3_limA}} and dividing by $f_{Y|X}(y_{\tau}(x)|x)$ under Assumption \ref{A:f_YX} yields
%    \begin{flalign}
%        0=\dev{X}{Q_Y}(\tau|x)
%        + \frac{1}{f_{Y|X}(y_{\tau}(x)|x)} \int_{\mathcal{U}(x,y_{\tau}(x))}\dev{X}{f_{U|X}}(u|x)\,du
%        - b'(x) \ocqr{D}(x,y_{\tau}(x)) - \ocqr{X}(x,y_{\tau}(x)). \notag
%    \end{flalign}
%    Rearranging the terms completes the proof.
    Finally, substituting Claim \ref{sk3_cla1}'s (i)--(iii) into (\ref{sk3_limA}) yields
    \begin{flalign*}
    0&=-\dev{X}{F_Y}(y_{\tau}(x)|x) + \int_{\mathcal{U}(x,y_{\tau}(x))}\dev{X}{f_{U|X}}(u|x)\,du \\
    &\quad -\left\{b'(x) \ocqr{D}(x,y_{\tau}(x)) + \ocqr{X}(x,y_{\tau}(x))\right\} f_{Y|X}( y_{\tau}(x)\,|x)
    \end{flalign*}
    for any $\tau \in (0,1)$ and $x \in I^o_{x_0}$. Rearranging the terms and evaluating at $\tau = F_{Y|X}(y|x)$ under Assumption \ref{A:f_YX} completes the proof.
\end{proof}


