\begin{flalign*}
    \dev{X}{F_Y}(y|x)
    &= -\bigg\{ b'(x)\int_{\mathbb{R}^{d_u}} \dev{D}{m}\left(b(x),x,u\right) f_{U|X,Y}(u|x,y)\,du \\
    &\qquad + \int_{\mathbb{R}^{d_u}} \dev{X}{m}\left(b(x),x,u\right) f_{U|X,Y}(u|x,y)\,du \bigg\} f_{Y|X}(y|x) \\
    &\quad + \int \I{ m(b(x),x,u) \leq y} \dev{X}{f_{U|X}}(u|x) \,du
\end{flalign*}
for any $x\in I^o_{x_0}$ and $y \in \supp{Y|X=x}$.
Under Assumption \ref{A:f_uxy.dct}, taking the limit $x\downarrow x_0$ and applying the DCT  implies that
\begin{flalign*}
    \lim\limits_{x\downarrow x_0} \dev{X}{F_Y}(y | x)
    &= -\bigg\{\lim\limits_{x\downarrow x_0} b'(x) \int_{\R^{d_u}} \lim\limits_{x\downarrow x_0} \dev{D}{m}\left(b(x), x, u \right) f_{U|X,Y}(u|x,y)\,du \\
    &\qquad + \int_{\R^{d_u}} \lim\limits_{x\downarrow x_0} \dev{X}{m}\left(b(x), x, u \right) f_{U|X,Y}(u|x,y)\,du \bigg\} \lim\limits_{x\downarrow x_0} f_{Y|X}(y|x) \\
    &\quad + \int \lim\limits_{x\downarrow x_0} \I{m(b(x),x,u) \leq y} \dev{X}{f_{U|X}}(u|x) \,du \\
    &\eq{(1)}{=} -\bigg\{ b'(x^+_0)\int_{\R^{d_u}} \dev{D}{m}\left(b(x_0),x_0,u\right) f_{U|X,Y}(u|x_0,y)\,du \\
    &\qquad + \int_{\R^{d_u}} \dev{X}{m}\left(b(x_0),x_0,u\right) f_{U|X,Y}(u|x_0,y)\,du \bigg\} f_{Y|X}(y|x_0) \\
    &\quad + \int \I{m(b(x_0),x_0,u) \leq y} \dev{X}{f_{U|X}}(u|x_0) \,du\\
    &=- \big\{b'(x^+_0) \ocqr{D}(x_0,y) + \ocqr{X}(x_0,y) \big\} f_{Y|X}(y|x_0) + \int_{\mathcal{U}(x_0,y)} \dev{X}{f_{U|X}}(u|x_0) \,du
\end{flalign*}
for any $y\in\supp{Y,0}$, where equality (1) follows from Assumptions \ref{A:sk},  \ref{A:struct.m.G}, \ref{A:f_YX} and the continuity in Assumptions \ref{A:fux.dct} and \ref{A:f_uxy.dct}. Similarly, taking the limit $x\uparrow x_0$ produces
\begin{flalign*}
    \lim\limits_{x\uparrow x_0} \dev{X}{F_Y}(y | x)
    &=- \big\{b'(x^-_0) \ocqr{D}(x_0,y) + \ocqr{X}(x_0,y) \big\} f_{Y|X}(y|x_0) + \int_{\mathcal{U}(x_0,y)} \dev{X}{f_{U|X}}(u|x_0) \,du.
\end{flalign*}
Let $\dev{X}{F_{Y}}(y|x^+_0):=\lim\limits_{x\downarrow x_0} \dev{X}{F_Y}(y|x)$ and similarly for  $\dev{X}{F_{Y}}(y|x^-_0)$. Taking the difference yields
\begin{flalign*}
    \dev{X}{F_{Y}}(y|x^+_0)-\dev{X}{F_{Y}}(y|x^-_0)
    =-\big(b'(x^+_0) - b'(x^-_0) \big) \theta_D(x_0,y) f_{Y|X}(y|x_0).
\end{flalign*}
Finally, under Assumption \ref{A:sk}(b), multiplying by $\kappa_0/(b'(x_0^+)-b'(x_0^-))$ on the both sides and using Lemma \ref{lem:udpe.ocqr}, we obtain that
\begin{flalign*}
    \kappa_0\frac{\dev{X}{F_Y}(y|x_0^+) - \dev{X}{F_Y}(y|x_0^-)}{b'(x_0^+) - b'(x_0^-)}
    &= -\kappa_0 \ocqr{D}(x_0,y) f_{Y|X}(y|x_0) \\
    &= \udpe(y)
\end{flalign*}
for any $y\in \supp{Y,0}$. This completes the proof.
\end{proof}

