\begin{proof}[\normalfont \textbf{Proof of Theorem \ref{thm:id.upe}}]
    Since $\phi$ is Hadamard-differentiable at $F_{Y|X=x_0}$ under Assumption \ref{A:phi-hadamard}, we obtain that
    \begin{flalign*}
        \upe
        &=\lim\limits_{\delta\to 0}\frac{\phi(F_{Y_\delta|X=x_0})-\phi(F_{Y|X=x_0})}{\delta} \\
        &=\lim\limits_{\delta\to 0}\frac{\phi \left(F_{Y|X=x_0}+ \delta\, \frac{F_{{Y_\delta}|X=x_0}-F_{Y|X=x_0}}{\delta} \right)-\phi \left(F_{Y|X=x_0} \right)}{\delta} \\
        &=\phi'_{F_{Y,0}}[\udpe],
    \end{flalign*}
    where $\lim_{\delta \to 0} \frac{F_{{Y_\delta}|X=x_0}-F_{Y|X=x_0}}{\delta} =: \udpe$. Therefore, applying Theorem \ref{thm:id.udpe} completes the proof.
\end{proof}

\begin{proof}[\normalfont \textbf{Details of Remark \ref{rmk:upe.covabs}}]
    If the assumptions of Theorem \ref{thm:id.udpe} are also satisfied when controlling $Z=z\in \supp{Z,0}$, then
    \begin{flalign*}
        \udpe(y)
        &= \lim_{\delta\to 0}\int \frac{F_{Y_\delta|X,Z}(y|x_0,z)-F_{Y|X,Z}(y|x_0,z)}{\delta}\,dF_{Z|X}(z|x_0)\\
        &\eq{(1)}{=}\int \lim_{\delta\to 0} \frac{F_{Y_\delta|X,Z}(y|x_0,z)-F_{Y|X,Z}(y|x_0,z)}{\delta}\,dF_{Z|X}(z|x_0)\\
        &\eq{(2)}{=}\kappa_0\int \frac{\dev{X}{F_Y}(y|x_0^+,z)-\dev{X}{F_Y}(y|x_0^-,z)}{b'(x_0^+)-b'(x_0^-)}\,dF_{Z|X}(z|x_0) \\
        &=\kappa_0\frac{E\big[\dev{X}{F_Y}(y|x_0^+,Z)-\dev{X}{F_Y}(y|x_0^-,Z)\big|X=x_0\big]}{b'(x_0^+)-b'(x_0^-)},
    \end{flalign*}
    where equality (1) is by the corresponding dominated convergence conditions; equality (2) follows from Theorem \ref{thm:id.udpe}. To see this, we note that Lemma \ref{lem:udpe.ocqr} presents
    \begin{flalign}
        \lim_{\delta\to 0} \frac{F_{Y_\delta|X,Z}(y|x_0,z)-F_{Y|X,Z}(y|x_0,z)}{\delta}
        =-\kappa_0 \ocqr{D}(x_0,y,z) f_{Y|X,Z}(y|x_0,z), \label{udpe.ocqr_covab}
    \end{flalign}
    where $\ocqr{D}(x_0,y,z):=E[\dev{D}{m}(U)|X=x_0,Y=y,Z=z]$. By analogy with the proofs of Lemma \ref{lem:qpd.decomp.ocqr} and Theorem \ref{thm:id.udpe}, we can show that
