%        &=-\frac{1}{f_{Y|X,Z}(y,x|z)} \frac{\dev{X}{F_Y}(y|x_0^+,z)-\dev{X}{F_Y}(y|x_0^-,z)}{b'(x_0^+)-b'(x_0^-)},
%    \end{flalign*}
%    where $\dev{X}{Q_Y}(\tau|x_0^+,z):=\lim_{x\downarrow x_0}\dev{X}{Q_{Y|X,Z}}(\tau|x,z)$ and similarly for $\dev{X}{Q_Y}(\tau|x_0^-,z)$.
    \begin{flalign*}
        \kappa_0 \frac{\dev{X}{F_Y}(y|x_0^+,z)-\dev{X}{F_Y}(y|x_0^-,z)}{b'(x_0^+)-b'(x_0^-)}
        = -\kappa_0 \ocqr{D}(x_0,y,z) f_{Y|X,Z}(y|x_0,z).
    \end{flalign*}
    Thus, substituting the above into (\ref{udpe.ocqr_covab}) verifies the equality (2).
\end{proof}


% proof of corollary UQPE/////////////////
\begin{proof}[\normalfont \textbf{Proof of Corollary \ref{cory:id.uqpe}}]
     Applying Lemma 21.4 of \citet{vaart2000} under Assumption \ref{A:f_YX} and \ref{A:id.cory}(a), we obtain the Hadamard derivative of quantile functional $\phi_{Q,\tau}$, given by
    \begin{flalign*}
        [\phi_{Q,\tau}]'_{F_{Y,0}}: h \mapsto - \frac{h}{f_{Y|X=x_0}} \circ Q_{Y|X}(\tau|x_0).
    \end{flalign*}
    Therefore, using Theorem \ref{thm:id.upe} completes the proof.
\end{proof}

%/////////////////////////////////////////////////////////////////
\begin{proof}[\normalfont \textbf{Proof of Corollary \ref{cory:id.umpe}}]
    For any $\delta \ne 0$ and the sequence of the function $h_\delta$, we have
    \begin{flalign*}
        \frac{ \phi_{E}( F_{Y|X=x_0}+\delta\,h_{\delta}) - \phi_{E}( F_{Y|X=x_0})}{\delta}
        &=\frac{\int y \,d(F_{Y|X=x_0}+\delta\,h_{\delta})(y) - \int y \,dF_{Y|X=x_0}(y) }{\delta}\\
        &= \int y \,dh_{\delta}(y)
    \end{flalign*}
    Thus, for $h_\delta \to h$ as $\delta\to 0$, the Hadamard derivative of $\phi_E$ is still itself:
    $[\phi_{E}]'_{F_{Y,0}}: h \mapsto \int y \,dh(y)$.
    Next, using Theorem \ref{thm:id.upe}, we obtain that
    %	\allowdisplaybreaks
    \begin{flalign}
        \umpe
        &= [\phi_{E}]'_{F_{Y,0}}\left( \udpe(y) \right)
        = \kappa_0\int y \,d\rkd{D}(y)\notag\\
        &= \frac{\kappa_0}{b'(x_0^+) - b'(x_0^-)} \biggl\{\int y\,d\dev{X}{F_Y}(y|x_0^+) - \int y\,d\dev{X}{F_Y}(y|x_0^-)\biggr\}.  \notag
    \end{flalign}
    Then, for $x > x_0$, applying integration by parts under Assumption \ref{A:id.cory} yields that
    \begin{flalign}
        \int y\,d\dev{X}{F_Y}(y|x_0^+)
        &=y\dev{X}{F_Y}(y|x_0^+)- \int \dev{X}{F_Y}(y|x_0^+)\,dy \notag\\
        &=\lim_{x\downarrow x_0} y\dev{X}{F_Y}(y|x)
        - \int \lim_{x\downarrow x_0} \dev{X}{F_Y}(y|x)\,dy \notag\\
        &\eq{(1)}{=} \lim_{x\downarrow x_0} y\dev{X}{F_Y}(y|x)
        - \lim_{x\downarrow x_0}\partial_X \int F_Y(y|x)\,dy \notag\\
        &= \lim_{x\downarrow x_0} y\dev{X}{F_Y}(y|x)
        - \lim_{x\downarrow x_0}\partial_X \biggl\{yF_Y(y|x)-\int y\,dF_{Y|X}(y|x) \biggr\}\notag\\
        &= \lim_{x\downarrow x_0}\partial_X \int y\,dF_{Y|X}(y|x)
         =\lim_{x\downarrow x_0}\partial_X E[Y|X=x] =:\dev{X}{E}(Y|\,x_0^+) \notag
    \end{flalign}
    where equality (1) follows from Assumption \ref{A:id.cory}(b), using the DCT and interchanging the order of differentiation and integration (see, for example, Theorem 2.27 of \citet{folland1999}).
    By analogy, we have
        $\int y\,d\dev{X}{F_Y}(y|x_0^-)
        =\lim_{x\uparrow x_0}\partial_X E[Y|X=x] =:\dev{X}{E}(Y|\,x_0^-)$, and thus
    \begin{flalign}
        \umpe
        = \kappa_0\frac{ \dev{X}{E}(Y|\,x_0^+) - \dev{X}{E}(Y|\,x_0^-)}{b'(x_0^+) - b'(x_0^-)}
        =:\kappa_0 \rk. \notag
    \end{flalign}
    This completes the proof.
\end{proof}

\begin{proof}[\normalfont \textbf{Proof of Corollary \ref{cory:id.iqrpe}}]
    By evaluating $\uqpe$ at $\tau=0.75$ and $0.25$ respectively and taking the difference, the proof is completed using Corollary \ref{cory:id.uqpe}.
\end{proof}

\begin{proof}[\normalfont \textbf{Proof of Corollary \ref{cory:id.cvpe}}]
    To use Theorem \ref{thm:id.upe}, we need to calculate the Hadamard derivative $[\phi_{CV}]'_{F_{Y,0}}$. Let
    $\phi_{CV}:=\sqrt{\phi_V(F)}/\phi_E=\lambda\circ(\sqrt{\phi_V},\phi_E)$,
    where $\lambda:(f,g)\mapsto f/g$ for $(f,g) \in \mathrm{D}(\R)\times \mathrm{D}(\R)$ such that $\inf_z|g(z)|>0$. The proof of Corollary \ref{cory:id.umpe} presents that $\phi_E$ is Hadamard-differentiable with derivative $[\phi_E]'_{F_{Y,0}}(h) = \int y \,dh(y)$.
    We proceed to calculate the Hadamard derivatives of $\lambda$ and $\phi_V$.
%    and derive the conclusion from the \textit{chain rule for Hadamard-differentiable functionals} (see Lemma 6.19 in \citet{kosorok2008} or Theorem 20.9 in \citet{vaart2000}).

    For the functional $\lambda$, observe that
    \begin{flalign*}
        \frac{\lambda(f+\delta_n A_n,g+\delta_n B_n)-\lambda(f,g)}{\delta_n}
        =\frac{1}{\delta_n}\left( \frac{f+\delta_n A_n}{g+\delta_n B_n} -\frac{f}{g} \right)
        =\frac{g A_n- f B_n}{g^2+\delta_n B_n g}.
        %		\to\frac{gA-fB}{g^2}
    \end{flalign*}
    Hence, for sequences $A_n\to A$, $B_n\to B$ and $\delta_n\to 0$ as $n\to \infty$, $\lambda$ is Hadamard-differentiable at $(f,g)$ tangentially to a subset of $\ell^\infty(\R)\times\ell^\infty(\R)$
    with derivative $$\lambda'_{(f,g)}(A,B)=(gA-fB)/g^2.$$

    For the variance operator $\phi_{V}:F_{Y|X=x_0} \mapsto \int (y-\mu_0)^2\,dF_{Y|X}(y|x_0)$, where $\mu_0:=E[Y|X=x_0]$, we have
    \begin{flalign*}
        \frac{ \phi_{V}(F_{Y|X=x_0}+\delta\,h_{\delta}) - \phi_{V}(F_{Y|X=x_0})}{\delta}
        &=\frac{\int (y-\mu_0)^2 \,d(F_{Y|X=x_0}+\delta\,h_{\delta})(y) - \int (y-\mu_0)^2 \,dF_{Y|X=x_0}(y) }{\delta} \\
        &= \int (y-\mu_0)^2 \,dh_{\delta}(y), \notag
        %         \to \int (y-\mu_0)^2 \,dh(y). \notag
    \end{flalign*}
    Thus, for sequences $h_\delta \to h$ and $\delta_n \to 0$ as $n\to 0$, $\phi_{V}$ is Hadamard differentiable with derivative
    $[\phi_{V}]'_{F_{Y,0}}: h \mapsto \int (y-\mu_0)^2 \,dh(y)$.

    Subsequently, applying the \textit{chain rule for the Hadamard-differentiable functional} (see Lemma 6.19 of \citet{kosorok2008} or Theorem 20.9 of \citet{vaart2000}), $\phi_{CV}$ is Hadamard-differentiable at $F$ tangentially to a subset of $\ell^\infty(\R)$ with derivative
    \begin{flalign*}
        [\phi_{CV}]'_{F_{Y,0}}(h)
        &=\lambda'_{\left(\sqrt{\phi_V(F_{Y,0})}, \phi_E(F_{Y,0})\right)}\left([\sqrt{\phi_V}]'_{F_{Y,0}},[\phi_E]'_{F_{Y,0}}\right)(h)\\
        &=\frac{\phi_E(F_{Y,0})\, [\phi_V]'_{F_{Y,0}}(h)\big/\big(2\sqrt{\phi_V(F_{Y,0})}\big) - \sqrt{\phi_V(F_{Y,0})}\,[\phi_E]'_{F_{Y,0}}(h)}{\phi_E^2(F_{Y,0})}\\
        &\eq{(1)}{=}\frac{(\mu_0/2)\,[\phi_V]'_{F_{Y,0}}(h) - v_0\, [\phi_E]'_{F_{Y,0}}(h)}{\mu_0^2 \sqrt{v_0}},
    \end{flalign*}
    where $v_0:=Var[Y|X=x_0]$; equality (1) follows from the definitions of $\phi_E$ and $\phi_V$.
    Next, using Theorem \ref{thm:id.upe}, we obtain the identification of $\cvpe$:
    \begin{flalign*}
        \cvpe
        &=\kappa_0[\phi_{CV}]'_{F_{Y,0}}(\rkd{D}) \notag\\
        &=\kappa_0\frac{(\mu_0/2) [\phi_V]'_{F_{Y,0}}(\rkd{D}) - v_0 [\phi_E]'_{F_{Y,0}}(\rkd{D})}{\mu_0^2 \sqrt{v_0}}\notag\\
        &\eq{(2)}{=}\kappa_0\bigg\{\gamma_V \, \frac{\lim_{x \downarrow x_0} \partial_X E[(Y-\mu_0)^2|X=x]-\lim_{x \uparrow x_0} \partial_X E[(Y-\mu_0)^2|X=x]}{b'(x_0^+)-b'(x_0^-)} \notag\\
        &\qquad\qquad - \gamma_E \, \frac{\lim_{x\downarrow x_0}\partial_X E[Y|X=x] - \lim_{x\uparrow x_0}\partial_X E[Y|X=x]}{b'(x_0^+)-b'(x_0^-)} \bigg\} \\
        &=\frac{\kappa_0}{b'(x_0^+)-b'(x_0^-)'}\bigg\{
        \underbrace{\gamma_V \dev{X}{E}((Y-\mu_0)^2 |x_0^+)- \gamma_E \dev{X}{E}(Y|x_0^+)}_{=:T^+} \notag\\
        &\hspace{4cm} - \Big[ \underbrace{\gamma_V \dev{X}{E}((Y-\mu_0)^2 |x_0^-)- \gamma_E \dev{X}{E}(Y|x_0^-)}_{=:T^-} \Big] \bigg\}\notag\\
        &\eq{(3)}{=}\frac{\kappa_0}{b'(x_0^+)-b'(x_0^-)}\cdot \bigg\{ \dev{X}{E}\big( \gamma_V (Y-\mu_0)^2 - \gamma_E Y |x_0^+ \big) \notag\\
        &\hspace{4cm} - \dev{X}{E}\big( \gamma_V (Y-\mu_0)^2 - \gamma_E Y |x_0^- \big) \bigg\},
    \end{flalign*}
    where $\gamma_V:=1/(2\mu_0\sqrt{v_0})$ and $\gamma_E:=\sqrt{v_0}/\mu_0^2$.

    Equality (2) follows from Corollary \ref{cory:id.umpe} that gives $[\phi_E]'_{F_{Y,0}}(\rkd{D})$, and from
    \begin{flalign*}
        [\phi_V]'_{F_{Y,0}}(\rkd{D})
        &= \int (y-\mu_0)^2 \,\rkd{D}(y) \\
        &=\frac{1}{b'(x_0^+)-b'(x_0^-)}\biggl\{\int (y-\mu_0)^2\,d\dev{X}{F_Y}(y|x_0^+) - \int (y-\mu_0)^2\,d\dev{X}{F_Y}(y|x_0^-)\biggr\}\\
        &= \frac{1}{b'(x_0^+)-b'(x_0^-)}\biggl\{\dev{X}{E\big((Y-\mu_0)^2|x_0^+\big)} - \dev{X}{E\big((Y-\mu_0)^2|x_0^-\big)} \biggr\}.
    \end{flalign*}
    Note that the last equality above is obtained by
    \begin{flalign*}
        \int &(y-\mu_0)^2\,d\dev{X}{F_Y}(y|x_0^+)\\
        &= (y-\mu_0)^2 \dev{X}{F_Y}(y|x_0^+) - 2\int \dev{X}{F_Y}(y|x_0^+) (y-\mu_0)\,dy \notag\\
        &= \lim_{x\downarrow x_0}(y-\mu_0)^2 \dev{X}{F_Y}(y|x) - 2 \int \lim_{x\downarrow x_0}\dev{X}{F_Y}(y|x) (y-\mu_0)\,dy \\
        &= \lim_{x\downarrow x_0}(y-\mu_0)^2 \dev{X}{F_Y}(y|x) - \lim_{x\downarrow x_0}\partial_X \int F_Y(y|x)\,d(y-\mu_0)^2\\
        &=\lim_{x\downarrow x_0}(y-\mu_0)^2 \dev{X}{F_Y}(y|x) -\lim_{x\downarrow x_0}\partial_X\left\{ (y-\mu_0)^2 F_Y(y|x)-\int (y-\mu_0)^2 \,dF_Y(y|x) \right\} \\
        &= \lim_{x\downarrow x_0}\partial_X \int (y-\mu_0)^2 \,dF_Y(y|x)
        = \lim_{x \downarrow x_0} \partial_X E[(Y-\mu_0)^2|X=x],
    \end{flalign*}
    where the third equality follows from Assumption \ref{A:id.cory}, using the DCT and interchanging the order of differentiation and integration. Similarly, $\int (y-\mu_0)^2\,d\dev{X}{F_Y}(y|x_0^-) = \lim_{x \uparrow x_0} \partial_X E[(Y-\mu_0)^2|X=x]$.


    Finally, equality (3) follows from
    \begin{flalign*}
        T^+
        &=\gamma_V \lim_{x\downarrow x_0}\dev{X}{}\int (y-\mu_0)^2 \,dF_{Y|X}(y|x)
        - \gamma_E \lim_{x\downarrow x_0}\dev{X}{}\int y \,dF_{Y|X}(y|x) \\
        &=\lim_{x\downarrow x_0}\dev{X}{}\left\{ \int \gamma_V (y-\mu_0)^2 \,dF_{Y|X}(y|x) - \int \gamma_E y \,dF_{Y|X}(y|x) \right\}\\
        &=\lim_{x\downarrow x_0}\dev{X}{}\int \Big\{ \gamma_V (y-\mu_0)^2 - \gamma_E y\Big\}\,dF_{Y|X}(y|x)
        =:\dev{X}{E}\big( \gamma_V (Y-\mu_0)^2 - \gamma_E Y |x_0^+ \big),
    \end{flalign*}
    where $\dev{X}{E}(\cdot|x_0^+):=\lim_{x\downarrow x_0}\dev{X}{}E[\cdot|X=x]$. Similarly, we obtain
    \begin{flalign*}
        T^-
        =\lim_{x\uparrow x_0}\dev{X}{}\int \Big\{ \gamma_V (y-\mu_0)^2 - \gamma_E y\Big\}\,dF_{Y|X}(y|x)
        =:\dev{X}{E}\big( \gamma_V (Y-\mu_0)^2 - \gamma_E Y |x_0^- \big).
    \end{flalign*}
    This completes the proof.
\end{proof}

