\section{Technical materials for asymptotic theory} \label{apdx:asy}
This section presents the assumptions and asymptotic theory, while the detailed proofs are provided in the Supplementary Appendix C.
Recall that $\varepsilon(y):=\varepsilon(Y,X,y):= \I{Y \leq y} - E[\I{Y \leq y}|X]$. We denote the covariance by $\sigeps(y_1,y_2|x):=E[\varepsilon(y_1)\varepsilon(y_2)|X = x]$, and write $\sigeps^2(y|x)$ for $\sigeps(y,y|x)$.
Let $\mathcal{C}^s(\mathbb{T})$ denote the set of functions defined on space $\mathbb{T}$ with the continuous $s$th-order derivative. $\mathcal{C}(\mathbb{T})\equiv\mathcal{C}^0(\mathbb{T})$ denotes the set of all continuous functions on $\mathbb{T}$.
Let $[\underline{x},\overline{x}]$ be a small close interval such that $\underline{x} < x_0 < \overline{x}$; $z_p(u):= (1, u, u^2, \ldots, u^p)^\trans$.

%----------------------------------------
\subsection{Regularity assumptions}
%----------------------------------------
\begin{assumptionB}[\normalfont Regularity] \label{A:asy.regular}
    % iid
    (a) $\{Y_i,D_i,X_i\}_{i=1}^n$ are n i.i.d copies of random vector $(Y,D,X)$ defined on the probability space $(\Omega^w,\mathcal{A}^w,P^w)$;
    % pdf f_X
    (b) The density $f_X\in \mathcal{C}^1([\underline{x},\overline{x}])$ and $f_X(x_0)$ are finite and bounded away from zero;
    % Lipschitz F'
    (c) $\hdev{X}{s}{F_Y}(y|x)$ is bounded and Lipschitz continuous in $(y,x)\in \supp{Y,0} \times ([\underline{x},\overline{x}]\backslash\{x_0\})$ for any $s =0,1,\ldots,p+1$;
    % C^1 sigma
    (d) $\sigeps(y_1,y_2|\cdot) \in \mathcal{C}^1([\underline{x},\overline{x}]\backslash\{x_0\})$ with bounded derivatives and $\sigeps(y_1,y_2|x_0^\pm) < \infty$  for any $y_1$, $y_2 \in \supp{Y,0}$.
    % common envelope bar{F}
    (e) There exist a common measurable envelope $\overline{F}$ of sets $\{x\mapsto F_{Y|X}(y|x): y\in\supp{Y,0}\}$ and $\{t\mapsto\I{ t\leq y}: y\in \supp{Y,0}\}$ such that
    $\iint_{\underline{x}}^{\overline{x}}|\overline{F}(y,x)|^{2+\epsilon}\,dF_{Y,X}(y,x) < \infty$ for some $\epsilon > 0$.
\end{assumptionB}

% kernel function assumptions
\begin{assumptionB}[\normalfont Kernel] \label{A:asy.kernel}
    Let $K:[-1,1]\to\R_+$ be a kernel function.
    (a) $K$ is bounded, continuous, symmetric.
    % and satisfies $0< E[K^2] < \infty$;
    (b) $\{K(\frac{x-x_0}{h}): h>0\}$ is of VC type for any $x\in[\underline{x},\overline{x}]$.
    For any $p, q\in\mathbb{N}_+$ with $q > p$,
    (c) $\Gamma_p^\pm:=\int_{\R_\pm}K(u)z_p(u)z_p^{\trans}(u)\,du$ is positive definite;
    (d) $\int_{\R_\pm} |K(u)z_p(u)u^q |\,du < \infty$ and $\int_{\R_\pm}|K^2(u)z_p(u)z^\trans_p(u)|\,du < \infty$.
\end{assumptionB}


% bandwidth assumptions
\begin{assumptionB}[\normalfont Bandwidth] \label{A:asy.bandwidth}
    Let $\upe$ be evaluated at $\vartheta\in\varTheta$,\footnote{Note that for the homogeneous effect, such as $\umpe$, $\upe(\vartheta)$ is trivial for $\vartheta$ and $h_n(\vartheta)$ becomes $h_n$.}
    and $\{h_{n,-}(\vartheta)\}$, $\{h_{n,+}(\vartheta)\}$ denote the positive bandwidth sequences below and above kink $x_0$, respectively. (a) There exist Lipschitz functions $c_{\pm}(\vartheta)$ satisfying  $0 < \underline{c}_\pm \leq c_{\pm}(\vartheta) \leq \overline{c}_\pm < \infty$ such that $h_{n,\pm}(\vartheta)=c_{\pm}(\vartheta) h_{n}(\vartheta)$.
    As $n \to \infty$, suppose
    (b) $h_n(\vartheta) \to 0$, $nh_n^3(\vartheta) \to \infty$ and
    (c) $nh_n^{2p+3}(\vartheta)  \to 0$ for some $h_0(\vartheta) < \infty$.
\end{assumptionB}

Recall that the \textit{estimated multiplier bootstrap processes  (EMP) } of $\bahan{\pm}$ is given by
\begin{flalign*}
    &\bahambhatn{\pm}(y)
    :=\frac{e_{1,p}^{\trans} [\Gamma_p^\pm]^{-1}}{\widehat{f}_X(x_0)}\frac{1}{\sqrt{nh_{n,\pm}(y)}}\sum_{i=1}^{n} \xi_i d^\pm_i K\left(\frac{X_i-x_0}{h_{n,\pm}(y)}\right) z_p\left(\frac{X_i-x_0}{h_{n,\pm}(y)}\right)\widehat{\varepsilon}_i(y),
\end{flalign*}
where
$$\widehat{\varepsilon}_i(y)
= \I{Y_i\leq y}
- d_i^+ \Zhtrans{p}{X_i}{+} \betan{p}^+(y)
- d_i^- \Zhtrans{p}{X_i}{-} \betan{p}^-(y).
$$

% Multiplier
\begin{assumptionB}[\normalfont Multiplier] \label{A:asy.multiplier}
    $\{\xi_i\}_{i=1}^n$ is an i.i.d the standard normal pseudo random sample defined on a probability space $(\Omega^\xi,\mathcal{A}^\xi,P^\xi)$ that is independent of $(\Omega^w,\mathcal{A}^w,P^w)$.
\end{assumptionB}

% first-stage
\begin{assumptionB}[\normalfont High-level conditions] \label{A:asy.high-level}
%    (a) $\widehat{Q}_{Y|X}(\tau|x_0) \pto{P} Q_{Y|X}(\tau|x_0)$ uniformly in $\tau\in (0,1)$.
    (a) The density estimator $\widehat{f}_X(x_0) \pto{P} f_X(x_0)$.
    (b) $\sup_{\vartheta \in \varTheta}\sqrt{nh_n^3(\vartheta)}|\widehat{\phi}'_{F_{Y,0}}(\widehat{\dev{X}{F_Y}}(\cdot|x_0^\pm))(\vartheta) - \phi'_{F_{Y,0}}(\widehat{\dev{X}{F_Y}}(\cdot|x_0^\pm))(\vartheta)| = o_P(1)$.
    (c) The EMPs $\bahambhatn{\pm}$ satisfy $\sup_{\vartheta\in \varTheta}|\widehat{\phi}'_{F_{Y,0}}(\bahambhatn{\pm})(\vartheta) - {\phi}'_{F_{Y,0}}(\bahambhatn{\pm})(\vartheta)| = o_P^{w\times\xi}(1)$.
\end{assumptionB}
Assumptions \ref{A:asy.regular}--\ref{A:asy.bandwidth} and \ref{A:asy.multiplier} are parallel to Assumption 1 and 3 of \citet{chs2019}, respectively. We note that in Assumption \ref{A:asy.regular}(e), both $\{t\mapsto \I{t\leq y} : y\in \supp{Y,0}\}$ and $\{x\mapsto F_{Y|X}
(y|x): y\in \supp{Y,0}\}$ are monotonically increasing stochastic processes, applying Lemma 9.10 of \citet{kosorok2008}, they are of VC type. Assumption \ref{A:asy.kernel}(d) guarantees the existence of $\Lambda_{p,q}^\pm:=\int_{\R_\pm}K(u)z_p(u)u^q\,du$ and $\Psi_{p}^\pm := \int_{\R_\pm}K^2(u)z_p(u)z_p^{\trans}(u)\,du$, which appear in the UBR and asymptotic covariance, respectively. Assumptions \ref{A:asy.bandwidth}, \ref{A:asy.multiplier} and \ref{A:asy.high-level}(a) are standard.

Assumption \ref{A:asy.high-level}(b) is sufficient to establish the weak convergence regarding $\upe$ process; however, it can be replaced by the uniformly consistent conditions on the specific $\widehat{\phi}'_{F_{Y,0}}$. For example, considering the estimator of $\uqpe$ given in Example \ref{ex:uqpe.esti}, \citet{chs2019} impose that $f_{Y|X}(y|x)$ is Lipschitz continuous in $x$ given $y$, and $\sup_{y\in \supp{Y,0}}\big| \widehat{f}_{Y|X}(y|x_0) - f_{Y|X}(y|x_0) \big| \pto{P} 0 $. Combining these conditions with Assumptions \ref{A:sk}, \ref{A:f_YX} and \ref{A:asy.regular}--\ref{A:asy.bandwidth}, they verify Assumption \ref{A:asy.high-level}(b) when ${\phi}'_{F_{Y,0}} = [{\phi}_{Q,\tau}]'_{F_{Y,0}}$. Assumption \ref{A:asy.high-level}(c) is sufficient to establish the conditional weak convergence regarding the EMP of $\upehat$. Continuing with the $\uqpe$ example, under the aforementioned conditions, \citet{chs2019} show that $\bahambhatn{\pm}(\widehat{Q}_{Y|X}(\tau|x_0)) = \bahambhatn{\pm}(Q_{Y|X}(\tau|x_0)) + o_P^{w\times\xi}(1)$ uniformly   and $\sup_{\tau \in \mathcal{T}}\big|[\widehat{\phi}_{Q,\tau}]'_{F_{Y,0}}(\bahambhatn{\pm})(\tau) - [{\phi}_{Q,\tau}]'_{F_{Y,0}}(\bahambhatn{\pm})(\tau)\big| = o_P^{w\times\xi}(1)$, which corresponds to the case of Assumption \ref{A:asy.high-level}(c) where  ${\phi}'_{F_{Y,0}} = [{\phi}_{Q,\tau}]'_{F_{Y,0}}$. We refer interested readers to Sections C.8, E.1 and E.2 in their supplementary material for further details.


%----------------------------------------
\subsection{Auxiliary lemmas, asymptotic distributions}
%----------------------------------------
% UBR ///////////////////
\begin{lemmaB}[\normalfont Uniform Bahadur representation] \label{lem:ubr}
    Suppose that Assumptions \ref{A:asy.regular}, \ref{A:asy.kernel} and \ref{A:asy.bandwidth}(a)(b) hold and that $nh_{n}^{2p+5}(y) \to 0$ as $n\to \infty$. Then,
    \begin{flalign*}
        &\sqrt{nh^3_{n,\pm}(y)}\left( \widehat{\dev{X}{F_Y}}(y|x_0^\pm) - \dev{X}{F_Y}(y|x_0^\pm) - h_{n,\pm}^p(y)\frac{e_{1,p}^{\trans}[\Gamma_p^-]^{-1} \Lambda_{p,p+1}^\pm}{(p+1)!}\hdev{X}{p+1}{F_Y}(y|x_0^\pm) \right) \\
        &\qquad =: \bahan{\pm}(y)+o_P(1) \notag
    \end{flalign*}
    uniformly in $y\in \supp{Y,0}$, where
    \begin{flalign}
        \bahan{\pm}(y) :=\frac{e_{1,p}^{\trans} [\Gamma_p^\pm]^{-1}}{f_X(x_0)}\frac{1}{\sqrt{nh_{n,\pm}(y)}}\sum_{i=1}^{n} d^\pm_i K\left(\frac{X_i-x_0}{h_{n,\pm}(y)}\right) z_p\left(\frac{X_i-x_0}{h_{n,\pm}(y)}\right)\varepsilon_i(y).\notag
    \end{flalign}
\end{lemmaB}


\begin{theoremB}[\normalfont Weak convergence]\label{thm:asy}
    Suppose that Assumptions \ref{A:asy.regular}--\ref{A:asy.bandwidth} hold. Then,
    \begin{itemize}
        \item[(i)]
        \begin{flalign}
            \begin{bmatrix}
                \sqrt{nh^3_{n,+}(y)}\left( \widehat{\dev{X}{F_Y}}(y|x_0^+)-\dev{X}{F_Y}(y|x_0^+) \right) \\
                \sqrt{nh^3_{n,-}(y)}\left( \widehat{\dev{X}{F_Y}}(y|x_0^-)-\dev{X}{F_Y}(y|x_0^-) \right)
            \end{bmatrix}
%            =\begin{bmatrix}
%                \bahan{+}(y)+o_P(1) \\
%                \bahan{-}(y)+o_P(1)
%            \end{bmatrix} \notag
            \leadsto
            \begin{bmatrix}
                \Gauss{+}(y) \\
                \Gauss{-}(y)
            \end{bmatrix} \notag
        \end{flalign}
        uniformly in $y\in \supp{Y,0}$, where $\Gauss{\pm} \in \ell^\infty(\supp{Y,0})$ are zero-mean Gaussian processes with the covariance functions given by
        \begin{flalign}
            E\left[\Gauss{\pm}(y_1)\Gauss{\pm}(y_2)\right] = \frac{\sigeps(y_1,y_2|x_0^\pm)}{f_{X}(x_0)}e_{1,p}^{\trans}[\Gamma_p^\pm]^{-1}\Psi_p^\pm[\Gamma_p^\pm]^{-1}e_{1,p} \notag
        \end{flalign}
        for any $y_1$, $y_2 \in \supp{Y,0}$.
        \item[(ii)]
        \begin{flalign*}
            &\sqrt{nh_n^3(y)}\left(\udpehat(y)-\udpe(y)\right)
            \leadsto \Gauss{\udpe}(y)
        \end{flalign*}%
        uniformly in $y\in \supp{Y,0}$, where
        $$\Gauss{\udpe}(y) := \kappa_0\frac{\Gauss{+}(y)/c_+^{3/2}(y) - \Gauss{-}(y)/c_-^{3/2}(y)}{b'(x_0^+)-b'(x_0^-)}\in \ell^\infty(\supp{Y,0}).
        $$
        is a zero-mean Gaussian process.
        \item[(iii)]
        $$ \sqrt{nh_n^3(\vartheta)}\left(\upehat(\vartheta)-\upe(\vartheta)\right)
        \leadsto \Gauss{\upe}(\vartheta)  $$
        uniformly in its domain, where
        $\Gauss{\upe}(\vartheta):=\phi'_{F_{Y,0}}\left(\Gauss{\udpe}\right)(\vartheta) \in \ell^{\infty}(\varTheta) $ is a zero-mean Gaussian process.
    \end{itemize}
\end{theoremB}


\begin{corollaryB} \label{cory:beta.consistent}
    Under Assumptions \ref{A:asy.regular}--\ref{A:asy.bandwidth}, $\betan{p}^\pm(y) \pto{P} \beta_p^\pm(y)$ uniformly in $y \in \supp{Y,0}$.
\end{corollaryB}


%---------------------------------------
 \subsection{Multiplier bootstrap}
%---------------------------------------
\begin{theoremB}[\normalfont Consistency of multiplier bootstrap]\label{thm:asy.mb.upe}
    Suppose that Assumptions \ref{A:asy.regular}--\ref{A:asy.high-level} hold. Then,
    \begin{enumerate}
        \item[(i)] the EMPs
        $\begin{bmatrix}
            \bahambhatn{+}(y) \\
            \bahambhatn{-}(y)
        \end{bmatrix}
        \overunderset{P}{\xi}{\leadsto}
        \begin{bmatrix}
            \Gauss{+}(y)\\
            \Gauss{-}(y)
        \end{bmatrix}$
        uniformly in $y\in \supp{Y,0}$.
        \item[(ii)] For the EMP of $\udpe$,
        \begin{flalign*}
            \bahambhatn{\udpe}(y):=\kappa_0\frac{\bahambhatn{+}(y)/c_+^{3/2}(y) - \bahambhatn{-}(y)/c_-^{3/2}(y)}{b'(x_0^+)-b'(x_0^-)}
            \wto{P}{\xi} \Gauss{\udpe}(y)
        \end{flalign*}
        uniformly in $y\in \supp{Y,0}$.
        \item[(iii)] For the EMP of $\upe$, under Assumption \ref{A:asy.high-level}(c), we have
        \begin{flalign*}
            \bahambhatn{\upe}(\cdot)
            := \widehat{\phi}'_{F_{Y,0}}\left(\bahambhatn{\udpe}\right)(\cdot)
            \wto{P}{\xi} \Gauss{\upe}(\cdot).
        \end{flalign*}
        uniformly in its domain.
    \end{enumerate}
\end{theoremB}

