\begin{equation}\label{eq:nonbifunctional-hmm-general}
\begin{aligned}
&\frac{dc_{\ell p}}{dt}  = G_{\ell p}    \quad &&\text{for}\quad \ell\in R, p\in RC_\ell \cup PC_\ell, \\
&\frac{de_j}{dt}    = -\left(\sum_{\ell: \mathcal{E}_\ell=E_j}  \sum_{p\in RC_\ell\cup PC_\ell}G_{\ell p}\right) \quad &&\text{for} \quad j\in [1,d], \\
&\frac{ds_i}{dt} = L_i- \left(\sum_{\ell: i\in T_\ell} \sum_{p\in RC_\ell}G_{\ell p} +  \sum_{\ell: i\in H_\ell} \sum_{p\in PC_\ell}G_{\ell p}\right)\quad &&\text{for}\quad i\in [1,n],\\
\mbox{where} \\
&L_i =  \sum_{\ell: i\in H_\ell} k_{\ell} c_{\ell 1} - \sum_{\ell: i\in T_\ell} k_{\ell}c_{\ell 1} , \quad &&\text{for} \quad i\in[1,n].
\end{aligned}
\end{equation}


\vspace{.1in}
\noindent\textbf{With bifunctional enzymes}
\vspace{.1in}

In the presence of bifunctional enzyme(s),  the mass-action ODEs are given as follows

\begin{equation}\label{eq:bifunctional-hmm-general}
\begin{aligned}
&\frac{dc_{\ell p}}{dt}  = G_{\ell p}  + \widetilde{G}_{\ell p}  \quad &&\text{for}\quad \ell\in R, p\in RC_\ell\cup PC_\ell, \\
&\frac{de_j}{dt}    = -\left(\sum_{\ell: \mathcal{E}_\ell=E_j}  \sum_{p\in RC_\ell\cup PC_\ell}G_{\ell p}\right) \quad &&\text{for} \quad j\in [1,d], \mbox{ and }\\
&\frac{ds_i}{dt} = L_i- \left(\sum_{\ell: i\in T_\ell} \sum_{p\in RC_\ell}G_{\ell p} +  \sum_{\ell: i\in H_\ell} \sum_{p\in PC_\ell}G_{\ell p}\right)\quad &&\text{for}\quad i\in [1,n]. 
\end{aligned}
\end{equation}
where $G_{\ell p}$ and $L_i$ are defined as in \eqref{eq:nonbifunctional-hmm-general} and
\begin{equation}
\begin{aligned}
&\widetilde{G}_{\ell p} = -\left(\sum_{m\in R: \mathcal{E}_m=C_i}  \sum_{q\in RC_\ell\cup PC_\ell}G_{mq}\right).
\end{aligned}
\end{equation}
Similar to Section \ref{sec:ODEs}, here $G_{\ell p}$ and $\widetilde{G}_{\ell p}$ are the local and non-local parts of the ODEs for the compound $C_{\ell p}$. If $\widetilde{G}_{\ell p}=0$, $C_{\ell p}$ is not a bifunctional enzyme. 

