Next, we provide three lemmas which we will use in the proof of our main results for this section.
\begin{lemma}\label{lem:unimolecular}

Consider a reaction network $\mathcal{G}$ with $n$ species $\mathcal{S}=\{X_1, X_2, \dots, X_n\}$. Assume that set of complexes is $\mathcal{C}=\{0,X_1,\dots,X_n\}$ (i.e. at most unimolecular complexes). If $\mathcal{G}$ is weakly reversible and has a single connected component, then $\mathcal{G}$ has deficiency zero and thus its associated mass-action system $(\mathcal{G},\kappa)$ has a unique positive steady state for any choice of $\kappa$.

\end{lemma}

\begin{proof}
    It is easy to check that the stoichiometric subspace of $S$ contains all standard basis vectors of $\mathbb{R}^n$. Thus $\text{dim}(S)=n$ and its deficiency is $\delta = n+1 - 1 - n =0$. By Theorem \ref{thm:deficiencyzero}, $(\mathcal{G},\kappa)$ has a unique positive steady state for any choice of $\kappa$.
\end{proof}

\begin{lemma}\label{lem:scale_u}
Consider a reaction network $\mathcal{G}$ with $n$ species $\mathcal{S}=\{X_1, X_2, \dots, X_n\}$. Assume that set of complexes is $\mathcal{C}=\{0,X_1,\dots,X_n\}$ and that $G$ is weakly reversible and has a single connected component. 
For a choice of rate constants $\kappa$,  let the unique steady state of the mass-action system $(\mathcal{G},\kappa)$ be denoted by $x^*$. Let $u$ be a positive parameter, and consider a new choice of rate constants $\kappa_u$, defined as follows: 
\begin{enumerate}
\item If the reactant complex is $0$ then the rate constant of the reaction in $(\mathcal{G},\kappa)$ is multiplied by $u$ to obtain the rate constant of that reaction in $(\mathcal{G},\kappa_u)$. 
\item If the reactant complex is not $0$, then the rate constant of that reaction in $(\mathcal{G},\kappa_u)$ is the same as that in $(\mathcal{G},\kappa)$. 
\end{enumerate}

    % \item For each reaction $0\xrightarrow{k_i} X_i$ in $(\mathcal{G},\kappa)$, the reaction with new rate constant is $0\xrightarrow{k_i  u} X_i$ in $(\mathcal{G},\kappa_u)$.
    % \item For all other reactions, the rate constants are the same between $\kappa$ and $\kappa_u$.

Then the positive steady state of $(\mathcal{G},\kappa_u)$ is $x^*_u = u\cdot x^*$.
\end{lemma}

\begin{proof}
Dividing the ODEs of the mass-action system $(\mathcal{G},\kappa_u)$ by $u$ and changing the variable $x\mapsto x/u$ produces the same ODEs as the mass-action system $(\mathcal{G},\kappa)$. Thus the positive steady state of $(\mathcal{G},\kappa_u)$ is $x^*_u = u\cdot x^*$.
\end{proof}


\begin{lemma}\label{lem:cip}
    For each hyperedge $\ell$ and each compound $c_{\ell p}: p\in RC_\ell$ in the reactant block, at steady state we must have
    \[
    c_{\ell p} = h_{\ell p} \left(\prod_{i\in T_\ell} s_i \right)\varepsilon_\ell,
