Now we are ready to state the main results of this section on the consistency of substrate modification networks with general detailed model and conditions for ACR.

\begin{theorem}
Consider a substrate modification network whose detailed models satisfy Assumption \ref{assum:blocks}. Suppose there exists a positive current assignment on the skeleton $G$. Then the associated reaction network $\GG$ is consistent.
\end{theorem}
\begin{proof}
Suppose there exists a positive current assignment $\{I_\ell>0:\ell\in R\}$. We will show that there exists a choice of rate constants $\kappa$ such that the resulting mass-action system admits a positive steady state $x^*$ where the concentration of any species is equal to 1. Next, we show explicitly the choice of rate constants. From Lemma \ref{lem:LFFtilde}, we need to show that with this choice of rate constants, $x^*$ satisfies $L_i=0$ for all $i$ and $G_{\ell p}=0$ for all $\ell \in R, p\in RC_\ell\cup PC_\ell$. 
    \begin{itemize}
        \item First, we pick $k_{\ell} = I_{\ell}$ for all $\ell\in R$. At steady state $x^*$ where all $c_\ell=1$, we have
        \[
        L_i =  \sum_{\ell: i\in H_\ell} k_{\ell} c_{\ell} - \sum_{\ell: i\in T_\ell} k_{\ell}c_{\ell}  = \sum_{\ell: i\in H_\ell} I_{\ell}  - \sum_{\ell: i\in T_\ell} I_{\ell} = 0,
        \]
        where the last equality is due to the balance property of the currents.
        \item For the reactant block of hyperedge $\ell$, following the argument in the proof of Lemma \ref{lem:cip}, we consider a reaction network $\mathcal{G}_\ell$ (and associated mass-action system $(\mathcal{G}_\ell,\kappa)$) which is obtained by replacing the complex $\sum_{i\in T_\ell} S_i+\EE_\ell$ with the complex $0$. Again, since $\mathcal{G}_\ell$ is weakly reversible (and thus is consistent), there exists a choice of rate constants such that $(\mathcal{G}_\ell,\kappa)$ admits a unique steady state vector whose entries are all 1. This choice of rate constants ensures that $x^*$ satisfies $G_{\ell p}=0$ for all $\ell\in R, p\in RC_\ell$.
        \item For the product block of hyperedge $\ell$, we consider a reaction network $\mathcal{G'}_\ell$ (and associated mass-action system $(\mathcal{G'}_\ell,\kappa)$) which is obtained by replacing the complex $\sum_{i\in H_\ell} S_i+\EE_\ell$ with the complex $0$. Assumption \ref{assum:blocks} (1) ensures that $\mathcal{G'}_\ell$ is weakly reversible, and thus there exists a choice of rate constants such that $(\mathcal{G'}_\ell,\kappa)$ admits a unique steady state vector whose entries are all 1. This choice of rate constants ensures that $x^*$ satisfies $G_{\ell p}=0$ for all $\ell\in R, p\in PC_\ell$.
    \end{itemize}
Thus, $x^*$ is a positive steady state of the resulting mass-action system.
\end{proof}



The following definition is a general version of Definition \ref{def:bifunctional}. 

\begin{definition}\label{def:bifunctional_variation}
A pair of hyperedges $(\ell, m)$ is called a {\em bifunctional pair} if a reactant compound of edge $\ell$ is the enzyme of edge $m$ (i.e. $\EE_{m} = C_{\ell p}$ for some $p\in RC_\ell$). Again, we call $\ell$ the agonist hyperedge and $m$ the antagonist hyperedge.
\end{definition}


\begin{theorem}\label{thm:ACR_general}
Consider a substrate modification network whose detailed models satisfy Assumption \ref{assum:blocks}. Suppose that the skeleton $G$ contains a pair of hyperedges $(\ell,m)$ that is both bifunctional and current-balanced. Then the associated reaction network $\GG$ has concentration robustness in the tail of $m$. 
% More precisely, there is a positive number $\sigma > 0$ such that at every steady state we have 
% \[
% \prod_{i\in T_m} s_i=\sigma. 
% \]
Furthermore, if the tail of $m$ contains only one reactant substrate, then the associated reaction network $\GG$ has ACR in that substrate.
 \end{theorem}

\begin{proof}
From Lemma \ref{lem:LFFtilde}, at steady state, we have 
\[
L_i =  \sum_{\ell: i\in H_\ell} k_{\ell} c_{\ell 1} - \sum_{\ell: i\in T_\ell} k_{\ell}c_{\ell 1}  = 0
\]
for all $i\in [1,n]$. Thus, by setting $I_\ell = k_\ell c_{\ell 1}$, the set $\{I_\ell:\ell\in R\}$ forms a positive current assignment on $G$. Since $(\ell,m)$ is current-balanced, their currents must equal for any choice of currents. Thus we have
\[
I_\ell = I_m \implies k_\ell c_{\ell 1}= k_m c_{m 1}\implies c_{\ell 1}= \frac{k_m}{k_\ell} c_{m 1}
\]
Suppose that the bifunctional enzyme is $C_{\ell p}$ for a fixed $p\in RC_\ell$. Then we have $\varepsilon_m=c_{\ell p}$. From Lemma \ref{lem:cip} we have
\[
c_{m1} = h_{m1}\left(\prod_{i\in T_m}s_{i}\right)\varepsilon_{m}= h_{m1}\left(\prod_{i\in T_m}s_{i}\right)c_{\ell p} = \left(\prod_{i\in T_m}s_{i}\right)h_{m1}\frac{h_{\ell p}}{h_{\ell 1}}c_{\ell 1}= \left(\prod_{i\in T_m}s_{i}\right) h_{m1}\frac{h_{\ell p}}{h_{\ell 1}}\frac{k_m}{k_\ell}c_{m1}.
\]
Thus we have 
\[
\prod_{i\in T_m}s_{i} = \frac{h_{\ell 1}k_\ell}{h_{m1}h_{\ell p}k_{m}},
\]
at any positive steady state. Thus $\GG$ has concentration robustness in the tail of $m$. Furthermore, if there is only one $i\in T_m$, then we must have
\[
s_i = \frac{h_{\ell 1}k_\ell}{h_{m1}h_{\ell p}k_{m}}
\]
and thus $\GG$ has ACR in substrate $S_i$, the only reactant substrate of the antagonist hyperedge $m$.
\end{proof}
\begin{remark}
It is important to note from Theorem \ref{thm:ACR_general} that if a {\em product compound} is a bifunctional enzyme, we may {\em not} have an ACR species. To illustrate this, consider a simple substrate modification network $S\rightleftarrows S^*$ with the following detailed models:
\begin{align*}
  &S+E\rightleftarrows C_{1} \to C_{2}\rightleftarrows S^*+E \\ 
  &S^*+C_{2}\rightleftarrows C_3 \to S+C_2.  
\end{align*}
In this case, a product compound, $C_2$, is a bifunctional enzyme. It can be checked (for example by Mathematica) that the associated mass-action system does not have an ACR species.
\end{remark}

Finally, similar to Remark \ref{remark:non-mass-action}, the results in Theorem \ref{thm:ACR_general} can be extended to more general kinetics beyond mass-action kinetics. 




