\section{Additional Algorithms}
\label{app:algorithms}

This section contains the helper functions for Algorithms \ref{alg:llm-modulo} and \ref{alg:consensus}. Algorithm \ref{alg:attempt-parse} (Attempt\_parse) returns True and None if no formulas in a list contain syntax errors. If there are error messages it returns false and the error messages.

\begin{algorithm}
\caption{Attempt\_parse: Checks and Parses LLM Equations}
\label{alg:attempt-parse}
\KwIn{$equation\_list$}
\KwOut{$correct\_syntax$ (boolean), $error\_messages$ (if applicable)}

\Try{
    Parse $equation\_list$ through system\;
    \Return{\textbf{True}, None}\;
}
\Catch{\text{ParsingError}\;
        \Return{\textbf{False}, error\_messages}\;
    }
\end{algorithm}

Algorithm \ref{alg:check-equivalence} checks whether two lists of student equations are equivalent using the process described for equivalence in \ref{sec:metrics}.

\begin{algorithm}
\caption{Check\_Equivalence: of equation Lists}
\label{alg:check-equivalence}

\KwIn{$student\_equations$, $llm\_equations$}
\KwOut{\textbf{True} if lists are equivalent; otherwise \textbf{False}}
\SetKwFunction{FEquiv}{Z3Entailment}
\SetKwProg{Fn}{Function}{:}{end}

\ForEach{$eq_{student}$ in $student\_equations$}{
    $found \gets False$\;
    \ForEach{$eq_{llm}$ in $llm\_equations$}{
        \If{\FEquiv{$eq_{student}$, $eq_{llm}$}}{
            $found \gets True$\;
            \textbf{break}\;
        }
    }
    \If{$found = False$}{
        \Return{\textbf{False}}\;
    }
}

\ForEach{$eq_{llm}$ in $llm\_equations$}{
    $found \gets False$\;
    \ForEach{$eq_{student}$ in $student\_equations$}{
        \If{\FEquiv{$eq_{llm}$, $eq_{student}$}}{
            $found \gets True$\;
            \textbf{break}\;
        }
    }
    \If{$found = False$}{
        \Return{\textbf{False}}\;
    }
}

\Return{\textbf{True}}\;
\end{algorithm}

Algorithm \ref{alg:z3-equivalent} describes the \texttt{Z3Entailment} function used in Algorithm \ref{alg:check-equivalence}. This function calls an SMT solver to check if two equations can be shown to be unsatisfiable.


\begin{algorithm}
\caption{Z3Entailment: Check Equation Entailment using Z3}
\label{alg:z3-equivalent}
\KwIn{$eq_1$, $eq_2$}
\KwOut{\textbf{True} if $eq_1$ entails $eq_2$; otherwise \textbf{False}}

    \Try{
        $eq1\_z3 \gets ParseToZ3(eq_{1})$\;
        $eq2\_z3 \gets ParseToZ3(eq_{2})$\;
    }
    \Catch{\text{ParsingError}\;
        \Return{\textbf{False}}\;
    }

    $prog \gets InitializeZ3Program()$ \;

    \tcc{Refutational formulation of checking whether eq1 entails eq2:}

    Add constraint $eq1\_z3$ to $prog$\;
    Add constraint $\neg(eq2\_z3)$ to $prog$\;

    $result \gets ExecuteZ3(prog)$\;

    \eIf{$result = UNSAT$}{
        \Return{\textbf{True}}\;
    }{
        \Return{\textbf{False}}\;
    }
\end{algorithm}

