\subsection{Data generation: stage one optimizations using \texttt{DESC} \cite{dudt2020desc}}
\label{app:desc_optimization}


Given a set of target quantities:
\[
T = \bigl(\iota^*,\,A^*,\,E^*,\,\mathcal{O}^*\bigr)
\]
where
\begin{itemize}
  \item $\iota^*$ is the desired edge rotational transform,
  \item $A^*$ is the target aspect ratio,
  \item $E^*$ is the maximum elongation,
  \item $\mathcal{O}^*$ is the target omnigenous field,
\end{itemize}

we ran numerical optimizations to find a toroidal boundary surface~$\Sigma$ (parameterized in a Fourier‐$RZ$ basis) that simultaneously matches these goals. Note that the mirror ratio $\Delta$ is defined within $\mathcal{O}^*$.


\subsubsection{Initial Guess Generation}
An initial boundary $\Sigma_0$ is generated either by
\begin{enumerate}
  \item \textbf{Heuristic QP model (Section III from \citet{goodman2023constructing})}: prescribing average major radius~$R_0$, aspect ratio $A^*$, elongation $E^*$, mirror ratio, torsion, and field periods; or
  \item \textbf{Near‐Axis Expansion (NAE) using \texttt{pyQSC} \footnote{\url{https://github.com/rogeriojorge/pyQIC}}}: specifying~$A^*$, $E^*$, $\iota^*$, mirror ratio, field periods, and mode cutoffs.
\end{enumerate}
This yields a smooth $\Sigma_0$ expressed in the \texttt{FourierRZToroidalSurface} format of \texttt{DESC}.

\subsubsection{Equilibrium Solve}
Starting from $\Sigma_0$, we form the \texttt{DESC} equilibrium object and solve the force balance
\[
\mathcal{E}(\Sigma) = \text{Equilibrium}\bigl(\Psi,\,\Sigma,\,M,\,N\bigr)
\]
and solve the magnetostatic force‐balance equations using
\[
\mathcal{E} \;\xrightarrow{\ \text{solve}(\text{force})\ }\;\mathcal{E}^\mathrm{sol}\,.
\]

\subsubsection{Objective Function}
On the solved equilibrium~$\mathcal{E}^\mathrm{sol}$, we define individual objective terms:
\begin{align}
  J_{A}(\Sigma) &= \frac{R_0(\Sigma)}{a(\Sigma)}, 
    & f_{A} &= w_{A}\,\bigl(J_{A} - A^*\bigr)^2, \\
  J_{E}(\Sigma) &= \max_{\varphi}\frac{b(\varphi;\Sigma)}{a(\varphi;\Sigma)}, 
    & f_{E} &= w_{E}\,\bigl(J_{E} - E^*\bigr)^2, \\
  J_{\iota}(\Sigma) &= \iota\,[\mathcal{E}^\mathrm{sol}], 
    & f_{\iota} &= w_{\iota}\,\bigl(J_{\iota} - \iota^*\bigr)^2, \\
  \mathbf{J}_{\mathcal{O}}(\Sigma) &= \mathcal{O}\bigl[\mathcal{E}^\mathrm{sol},\,\mathcal{O}^*\bigr], 
    & f_{\mathcal{O}} &= w_{\mathcal{O}}\,\bigl\lVert\mathbf{J}_{\mathcal{O}}\bigr\rVert_2^2,
\end{align}
where $a,b$ are the minor/major half‐axes of the cross‐section, $\varphi$ is the toroidal angle, and the omnigenous residual $\mathbf{J}_{\mathcal{O}}$ is computed by the \texttt{DESC} \texttt{Omnigenity} objective using the target field $\mathcal{O}^*$.  


The omnigenity contribution $\bigl\lVert\mathbf{J}_{\mathcal{O}}\bigr\rVert_2^2$ is given by
\[
\bigl\lVert\mathbf{J}_{\mathcal{O}}\bigr\rVert_2^2
=\sum_{i=1}^{N_\eta}\sum_{j=1}^{N_\alpha}
w(\eta_i)\,\bigl[
B_{\rm eq}(\rho_0,\eta_i,\alpha_j)
-\;B^*(\rho_0,\eta_i,\alpha_j)
\bigr]^2,
\]
with the poloidal weight
\[
w(\eta)
=\frac{\eta_{\rm weight}+1}{2}
\;+\;
\frac{\eta_{\rm weight}-1}{2}\,\cos\eta
\quad
\bigl(\text{so }w\equiv1\text{ if }\eta_{\rm weight}=1\bigr),
\]
where \(B_{\rm eq}\) is the field strength of the equilibrium in \((\rho,\eta,\alpha)\) coordinates and \(B^*\) is the perfectly‐omnigenous target field generated by \texttt{OmnigenousField} as in \cite{dudt2024magnetic}. The residuals \(r_{ij}= \sqrt{w(\eta_i)}\bigl(B_{\rm eq}-B^*\bigr)_{ij}\) are evaluated on the same \((\eta,\alpha)\)-grid used by the target field.

On a solved equilibrium~\(\mathcal{E}^\mathrm{sol}\) at a fixed flux surface \(\rho=\rho_0\), we assemble a least‐squares objective
\[
\mathcal{L}(\Sigma) \;=\; f_{A} + f_{E} + f_{\iota} + f_{\mathcal{O}}\,.
\]

Internally, \texttt{DESC} invokes \texttt{JAX} to compute residuals, leveraging automatic differentiation to compute gradients.

The objective is then wrapped in an augmented‐Lagrangian least‐squares optimizer (\texttt{lsq-auglag}) \cite{conlin2024stellarator} to minimize \(\|r\|_2^2\) alongside the other terms.

\subsubsection{Constraints}
To enforce vacuum equilibrium and fix global invariants, the following constraints are imposed:
\[
\begin{aligned}
  &R_{0,0}(\Sigma)\;=\; 1, 
  &\quad&(\texttt{FixBoundaryR}) \\
  &j_\parallel(\Sigma)\;=\;0,
  &\quad&(\texttt{CurrentDensity}) \\
  &p(\Sigma)\;=\;0,
  &\quad&(\texttt{FixPressure}) \\
  &J_\mathrm{tor}(\Sigma)\;=\;0,
  &\quad&(\texttt{FixCurrent}) \\
  &\Psi(\Sigma)\;=\;\text{const.},
  &\quad&(\texttt{FixPsi})
\end{aligned}
\]
where each is implemented via the corresponding \texttt{DESC} linear‐objective wrapper.

\subsubsection{Nonlinear Optimization}
We employ \texttt{DESC}’s \texttt{lsq‐auglag} optimizer \cite{conlin2024stellarator} to solve
\[
\min_{\Sigma}\;\mathcal{L}(\Sigma)
\quad\text{s.t. all linear constraints,}
\]
using automatic differentiation and a trust‐region least‐squares augmented‐Lagrangian scheme.  Iterations continue until convergence (up to 200 iterations by default), yielding the optimized boundary~$\Sigma^*$.

Our exact implementation is available at \url{https://github.com/proximafusion/constellaration}.


\subsection{Stage one optimizations using \vmecpp\cite{schilling2025numerics} in the loop}

We carried out optimizations using the \texttt{NGOpt} algorithm from the \texttt{Nevergrad}~\footnote{https://github.com/facebookresearch/nevergrad} library.
To improve convergence,
we preconditioned the problem using a diagonal scaling matrix as detailed in Section A.2.1.
We parameterized the boundary with up to four poloidal and toroidal Fourier modes and ran the optimization on a single machine equipped with 32 vCPUs and 32GB of RAM.
Each run is allocated a time budget of approximately \SI{1}{\hour}.

The optimization minimizes the following objective function:

\begin{equation}
\begin{aligned}
f(\Theta) =\ 
& \int_0^{2 \pi} \int_0^{\pi / N_{\text{fp}}} \left( B(\theta, \phi) - B^{\ast}(\theta, \phi) \right)^2 \, d\theta \, d\phi \\
& + \int_0^{2 \pi} \left( \max_{\phi} B(\theta, \phi) - B(\theta, \phi = 0) \right)^2 \, d\theta \\
& + \left( \frac{A - A^{\ast}}{A^{\ast}} \right)^2 \\
& + \left( \frac{\iota_{\text{edge}} - \iota_{\text{edge}}^{\ast}}{\iota_{\text{edge}}^{\ast}} \right)^2 \\
& + \left( \max\left(0, \frac{\epsilon_{\text{max}} - \epsilon_{\text{max}}^{\ast}}{\epsilon_{\text{max}}^{\ast}} \right) \right)^2 \ .
\end{aligned}
\end{equation}

where $B$ denotes the magnetic field strength from the ideal-\gls{MHD} equilibrium in Boozer coordinates,
and $B^{\ast}$ represents the target omnigenous magnetic field strength.
The quantities $A$, $\iota_{\text{edge}}$, and $\epsilon_{\text{max}}$ correspond to the aspect ratio,
edge rotational transform,
and maximum elongation,
respectively,
with asterisks denoting their target values.
The additional target on the maxima of the magnetic field strength guides the optimizer towards more \gls{QI} fields.

In the optimization loop,
we used \vmecpp within the forward model.
To speed up the generation of the optimized boundary,
we run \vmecpp at a lower resolution than the one used to score plasma boundaries in optimization benchmarks
(e.g. reduced number of flux surfaces, higher required force tolerance to converge).

Due to the constrained time budget,
the optimization may not fully minimize the objective function but added the desired diversity to the dataset.

Our exact implementation is available at \url{https://github.com/proximafusion/constellaration}.


\subsection{Optimization baselines}\label{app:optimization_baselines}
\subsubsection{Implementation details and hyperparameters}
In this section we provide implementation details for the optimization baseline. For the SciPy-based optimizers,
we use default parameters,
and set the maximum number of iterations to a large value.

We implement a variant of the proximal \gls{ALM}~\cite{rockafellar1976augmented} where the quadratic proximal term is replaced by a trust-region constraint. This can be seen as an instance of the anisotropic proximal \gls{ALM}~ \cite{laude2023anisotropic}.
The modification is essential for improving convergence when using evolutionary algorithms (such as NGOpt),
as it restricts the sampling of new candidate solutions to a region around the current iterate.

As the degrees of freedom $\Theta$ operate on different scale,
we precondition the problem with a diagonal matrix $\mathrm{diag}(\Lambda)$ where the entries $\Lambda$ decay exponentially.
We define the rescaled variables as
$\widetilde \Theta := \mathrm{diag}(\Lambda)^{-1} \Theta$
and $\tilde f(\widetilde \Theta) := f(\mathrm{diag} (\Lambda)  \widetilde \Theta)$ and $
\tilde c_i(\widetilde \Theta) := c_i(\mathrm{diag} (\Lambda)  \widetilde \Theta)$.
In addition,
we apply a base-10 logarithmic transformation to the QI constraint.

In each iteration,
the algorithm alternates between primal and dual updates.
For each constraint $\tilde c_i$,
it tracks a penalty parameter $\rho_i^k$ and a Lagrange multiplier $y_i^k$. The complete algorithm is given in~\cref{alg:alm}.

\begin{algorithm}[H]
\caption{non-Euclidean proximal augmented Lagrangian method}
\label{alg:alm}
\begin{algorithmic}[1]
\REQUIRE $\Theta^0 \in \mathbb{R}^D$, $\rho^0 \in \mathbb{R}_{++}^m$, $y^0\in \mathbb{R}_+^m$, $\delta_0 >0$, $0<\tau,\gamma<1$, $\sigma > 1$ and $\delta_{\min}, \rho_{\max} > 0$

\FOR{$k \in \{0, 1, \ldots, N\}$}
\STATE Primal update
\begin{equation} \label{eq:primal_update}
\widetilde\Theta^{k+1}=\argmin_{\widetilde\Theta \in B(\widetilde\Theta^k, \delta_k)} ~\tilde f(\widetilde\Theta) + \tfrac{1}{2} \sum_{i=1}^m \tfrac{1}{\rho_i^k} \Big(\max\{0,  y_i^k + \rho_i^k \tilde c_i(\widetilde\Theta^k)\}^2 - (y_i^k)^2\Big)
\end{equation}
\STATE dual update
$$
y_i^{k+1}=\max\{0, y_i^k + \rho_i^k \tilde c_i(\widetilde\Theta^{k+1})\} 
$$
\STATE update penalty parameters
$$
\rho_i^{k+1} = 
    \begin{cases}
    \rho_i^k & \text{if $\tilde c_i(\widetilde\Theta^{k+1}) \leq \tau \tilde c_i(\widetilde\Theta^{k})$} \\
    \min\{\rho_{\max}, \sigma \rho_i^k \}& \text{otherwise.}
    \end{cases}
$$
\STATE decrease trust-region
$$
 \delta_{k+1} = \max\{ \delta_{\min}, \gamma \delta_k\}
$$
\ENDFOR
\end{algorithmic}
\end{algorithm}

For the geometric problem we choose $\rho_i^0=10$, $\rho_{\max}=1e9$, $\delta_0=0.5,\gamma=0.9, \delta_{\min}=0.05, 
\tau=0.8, \sigma=5$. The subproblem~\eqref{eq:primal_update} is solved with NGOpt with a budget of $\min\{20.000, 1500 + k
\cdot 260\}$ forward-model calls.

For the simple-to-build problem we choose $\rho_i^0=10$, $\rho_{\max}=1e9$, $\delta_0=0.5,\gamma=0.95, \delta_{\min}=0.05, 
\tau=0.8, \sigma=5$. The subproblem~\eqref{eq:primal_update} is solved with NGOpt with a budget of $\min\{20.000, 1500 + k
\cdot 260\}$ forward-model calls.

For the MHD-stable problems we choose $\rho_i^0=10$, $\rho_{\max}=1e8$, $\delta_0=0.33,\gamma=0.95, \delta_{\min}=0.05, 
\tau=0.8, \sigma=5$. The subproblem~\eqref{eq:primal_update} is solved with NGOpt with a budget of $\min\{20.000, 1500 + k
\cdot 300\}$ forward-model calls.

For all problems,
$\Theta^0$ is a rotating ellipse configuration.
We optimize up to four poloidal and toroidal Fourier modes,
which results in $D=80$ degrees of freedom.
During the optimization,
we run \vmecpp at low fidelity.

