\begin{algorithm}[t!]
\caption{Generative Inference of Feasible Configurations without Oracle Access}
\label{alg:feasible_generation}
\begin{algorithmic}[1]
\REQUIRE Dataset $\mathcal{D} = \{x_1, \ldots, x_N\} \subset \mathbb{R}^D$, constraint definition
\ENSURE Set of configurations $\{x^\ast\}$ predicted to lie in the feasible domain

// Dimensionality Reduction:
\STATE Compute PCA mapping $\Phi: \mathbb{R}^D \rightarrow \mathbb{R}^d$, where $d \ll D$
\STATE Project dataset to latent space: $Z \leftarrow \{\mathbf{z}_i = \Phi(x_i)\}_{i=1}^N$

// Feasibility Classification:
\STATE Train Random Forest classifiers $\{C_i(\mathbf{z})\}_{i=1}^{N_c}$ to predict feasibility label $y \in \{0,1\}$
\STATE Define soft-feasible region: $\tilde{\mathcal{F}} \leftarrow \bigcap_{i=1}^{N_c} \{p(C_i(\mathbf{z})=1) \geq \tau\}$, where $\tau_i = 0.8~\forall i$

// Density Estimation:
\STATE Fit Gaussian Mixture Model $\text{GMM}(\mathbf{z})$ on data restricted to $\tilde{\mathcal{F}}$

// Bayesian Refinement:
\STATE Define prior: $p(\mathbf{z}) \leftarrow \text{GMM}(\mathbf{z})$
\STATE Define quasi-likelihood: $\ell(\mathbf{z}) \leftarrow \sum_{i=1}^{N_c} \log C_i(\mathbf{z})$
\STATE Compute posterior using MCMC: $\{\mathbf{z}^\ast\} \sim p(\mathbf{z} \mid \text{feasible}) \propto \ell(\mathbf{z}) \cdot p(\mathbf{z})$
\STATE Inverse transform to original space: $x^\ast \leftarrow \Phi^{-1}(\mathbf{z}^\ast)$

// Oracle Validation:
\STATE Evaluate $x^\ast$ using \vmecpp oracle to confirm feasibility

\RETURN $\{x^\ast\}$
\end{algorithmic}
\end{algorithm}
