\section{Global asymptotic stability of the system }\label{sec:appendix_stability}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We prove in this Appendix section proposition \ref{prop:stability} from the main text (stated here again, for clarity):


\begin{proposition*} We assume $\alpha$ constant and the rate functions $\gamma_{i}(E)$ ($i=P,R$) satisfying (i) $\gamma_i(0)=0$, (ii) $\gamma_{i}$ is $\mathcal{C}^1$ with positive derivative $\gamma_i'>0$, and (iii) $\lim_{E\rightarrow \infty} \gamma_i(E) = \gamma_{i,\max} < \infty$.
Then, the solutions of the autonomous system \eqref{eq:dRdt}-\eqref{eq:dEdt} starting at $E(0), \ R(0) >0$ remain strictly positive for all time, and converge to a globally asymptotically stable equilibrium point 
$(R^*,E^*)$  on $\R_{>0}^2$, given by
\beq
R^* &=& \frac{\alpha}{c_R(\beta_r+U)+c_P\gamma_P(E^*)(1-V)-c_U U}\label{eq:R*}\\
E^* &=& \gamma_R^{-1}\left(\frac{\beta_r+U}{V}\right) \label{eq:E*}.
\eeq
Moreover, all solutions initialized in $\R_{>0}^2$ oscillate, in the sense that $R(t)-R^*$ changes sign infinitely often as $t\to\infty$, if and only if $\Delta<0$, where
\beq
\Delta=(c_R\gamma_R'(E^*)V+c_P\gamma_P'(E^*)(1-V))^2R^{*2}-4\alpha \gamma_R'(E^*)V.
\eeq
\end{proposition*}



\begin{proof} We first get $(R^*,E^*)$ by solving for the equilibrium point of the system with constant input and control functions. 
To assess the stability of $(R^*,E^*)$, we study the Jacobian of the system at $(R^*,E^*)$:

$$J=\pmtx 0 & \gamma_R'(E^*)V R^*\\
-\frac{\alpha}{R^*} & -(c_R\gamma_R'(E^*)V+c_P\gamma_P'(E^*)(1-V))R^*
\pmtrx.$$
The characteristic polynomial of $J$ is 
\begin{equation}\label{eq:charac_poly}
     C[X]= X^2 +(c_R\gamma_R'(E^*)V+c_P\gamma_P'(E^*)(1-V))R^* X+\alpha \gamma_R'(E^*)V,
\end{equation}
with discriminant 
$$\Delta=(c_R\gamma_R'(E^*)V+c_P\gamma_P'(E^*)(1-V))^2R^{*2}-4 \alpha \gamma_R'(E^*)V.$$
If $\Delta<0,$ the eigenvalues of $J$ have real part $-\frac{1}{2}(c_R\gamma_R'(E^*)V+c_P\gamma_P'(E^*)(1-V))R^*<0$.
If $\Delta\geq0$, eigenvalues are real and strictly negative, since the coefficients of $C[X]$ are positive.
In both cases, we can apply the Hartman-Grobman theorem \cite{guckenheimer_nonlinear_1983} to conclude that $(R^*,E^*)$ is locally asymptotically stable.\newline

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{figure}[!ht]
    \centering
         \includegraphics[width=\textwidth]{qi_region.pdf}
        \caption{Vector field associated with the dynamical system. The $R$- and $E$-nullclines (equations \eqref{eq:Rnullcline}-\eqref{eq:Enullcline}) represented in blue and black dotted lines, respectively. They partition $\mathbb{R}_{>0}^2$ into four regions $\cQ_i$, $1 \le i \le 4$ (Eq. \eqref{eq:Qi}), and we also represent the section $S$, introduced in Eq. \eqref{eq:S} to define the Poincaré map and prove the asymptotic convergence of trajectories starting from $S$.}
        \label{fig:Q1234}
\end{figure}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
To prove that $(R^*,E^*)$ is globally asymptotically stable on $\mathbb{R}_{>0}^2$, we examine the nullclines to partition the state space. The $R$- and $E$-nullclines of the system, on which $R'=0$, respectively, $E'=0$, are given by 
\begin{align}
\label{eq:Rnullcline}
  \mathcal{R}_0 &= \{(R, E^*), \ R>0 \}\\
  \mathcal{E}_0 &= \{(R_{\mathcal{E}_0}(E),E), \ E>E_{\cE_0} \}\label{eq:Enullcline},
\end{align}
where 
\begin{align}\label{eq:RE0E}
R_{\mathcal{E}_0}(E)=\frac{\alpha}{c_R \gamma_R(E)V + c_P \gamma_P (E)(1-V) - c_U U}
\end{align}
and $E_{\cE_0}$ is either the unique positive value of $E$ making the above denominator $0$, or $0$ if no such value exists. Note that $E_{\cE_0}<E^*$, and that $R_{\cE_0}$ is positive on its domain and decreases with $E$, since $\gamma_R,\gamma_P$ increase with $E$. As illustrated in Figure \ref{fig:Q1234}, we can thus partition $\R_{>0}^2$ into the disjoint union of the four open sets $\cQ_i$, $1 \le i \le 4$ given by
\begin{equation}
\label{eq:Qi}
\cQ_i := \{(R,E)\in \R_{>0}^2\colon \sgn(f_1(R,E),f_2(R,E)) = a_i\},
\end{equation}
where $a_1 = (1,1), \ a_2=(1,-1), \ a_3 = (-1,-1), \ a_4=(-1,1),$ and $f_1$ ($f_2$) is the function from equation \eqref{eq:dRdt} (\eqref{eq:dEdt}) associated with $dR/dt$ ($dE/dt$). We further introduce \beq\label{eq:S}\mathcal{S}=\left\{ (R,E^*) \ , \  0<R< R^*\right\}\eeq as the part of the $R$-nullcline that separates $\mathcal{Q}_1$ and $\mathcal{Q}_4$. Solutions of the system then verify the following lemma

\begin{lemma}\label{trajectories}

Let $\mathbf{X}(t)$ be a solution of the system with initial conditions $\mathbf{X}(0) \in \mathbb{R}_{+*}^2$ and let $t_s=\inf\{t\ge 0\colon \mathbf{X}(t) \in S\}$. If $t_s=\infty$ then $\lim_{t\to\infty} X(t) = (R^*,E^*)$.
\end{lemma}

\begin{proof}
Since the vector field $(f_1,f_2)$ is transverse to $\cR_0\cup \cE_0$ away from $(R^*,E^*)$, and looking at the direction of the vector field in Figure \ref{fig:Q1234}, if $\mathbf{X}(t) \in \cR_0\cup \cE_0 \backslash \{(R^*,E^*)\}$, then for some $t'<t<t''$ and some $i$, $\mathbf{X}(s) \in \cQ_i$ for $t'<s<t$ and $\mathbf{X}(s) \in \cQ_{i+1}$ (or $\cQ_1$ if $i=4$) for $t<s<t''$. So, defining $t_0=0$ and recursively, $t_{j+1}=\inf\{t>t_j\colon \mathbf{X}(t) \in \cR_0\cup \cE_0\}$, if $t_j<\infty$ and $j>0$ then $\mathbf{X}(t_j) \in \cR_0 \cup \cE_0$, and if $t_j<\infty$ then $\mathbf{X}(t) \in \cQ_{i(j)}$ for $t\in(t_j,t_{j+1})$, where $i(j)=i(0)+j \mod 4$. In other words, trajectories follow the itinerary $\cQ_1 \to \cQ_2\to \cQ_3\to \cQ_4\to \cQ_1$, although they may, after arriving in some $\cQ_i$, remain there forever. To prove the lemma, and  since $t_s$ is the first time the trajectory crosses from $\cQ_4$ into $\cQ_1$, we can then  show that for all $i=1,\ldots,4 $, if  $\mathbf{X}(0) \in \cQ_i$ and $t_1=\infty$ (i.e., if $\mathbf{X}(t)\in \cQ_i$ for all $t>0$) then $\lim_{t\to\infty}\mathbf{X}(t)=(R^*,E^*)$: 
\begin{enumerate}
    \item 
    $i=1$: $t\mapsto E(t)$ and $t\mapsto R(t)$ are increasing for $t\in [0,t_1)$. Since $f_1(R,E)=(\gamma_R(E)V-(\beta_R+U))R$, $f_1$ is increasing in both $R,E$ on the set $\{f_1>0\}$, so $f_1(R(t),E(t))\ge f_1(R(0),E(0))=:c>0$ and $R(t) \ge R(0)+ct$ for $0<t<t_1$. Since $R\le R^*$ on $\cQ_1$, it follows that $t_1 \le (R^*-R(0))/c$. In particular, $t_1<\infty$.
    \item 
    $i=2$: $t\mapsto R(t)$ is increasing and $t\mapsto E(t)$ is decreasing for $t\in [0,t_1)$. In particular, $E(0)\ge E(t)\ge E^*$ for all $t<t_1$, so if $t_1=\infty$ then $E_\infty:=\lim_{t\to\infty}E(t)$ exists. If $t_1=\infty$ and $R(t)\le R^*$ for all $t>0$ then $R_\infty:=\lim_{t\to\infty} R(t)$ exists. By continuity of the vector field, $(R_\infty,E_\infty)$ is an equilibrium point, so must be equal to $(R^*,E^*)$. If $R(t)>R^*$ for some $t\in [0,t_1)$, then for $s>t$,
    $$E'(s)\le \alpha + \left[- c_R \gamma_R(E^*)V - c_P \gamma_P (E^*)(1-V) + c_U U\right]R(t)=:c<0.$$
    Arguing as in Case 1, $t_1\le t + (E(t)-E^*)/c<\infty$.
    \item  $i=3$: $t\mapsto R(t)$, $t\mapsto E(t)$ are both decreasing for $t\in [0,t_1)$, and $E(0)<E^*$. Since $\R_{>0}^2$ is forward invariant, $R(t)\ge 0$ and $E(t)\ge 0$ for all $t>0$ so if $t_1=\infty$ then $(R_\infty,E_\infty)$ exist as before, so must be equal to $(R^*,E^*)$. But $E_\infty\le E(0)<E^*$ which is a contradiction, so $t_1<\infty$.
    \item  $i=4$: $t\mapsto R(t)$ is decreasing and $t\mapsto E(t)$ is increasing for $t\in [0,t_1)$. If $t\in [0,t_1)$ then $E(t) \le E^*$, and $R(t)\ge 0$ for all $t>0$, so if $t_1=\infty$ then $(R_\infty,E_\infty)$ exist and must be equal to $(R^*,E^*)$.
\end{enumerate}
\end{proof}
To prove $(E^*,R^*)$'s global stability, we now only need to show that trajectories starting at and crossing $\mathcal{S}$  eventually converge to $(R^*,E^*)$. We parameterize these trajectories by their initial position $r\in \mathcal{I}$, where  

\begin{equation}
 \mathcal{I} = \left\{ r \in ]0; R^*[ \ |  \ \mathbf{X}(0) = \pmtx r \\ E^*\pmtrx \Rightarrow \exists t>0, \ \mathbf{X}(t)\in \mathcal{S}  \right\}.  
\end{equation}
Assuming that  $\mathcal{I}$ is non-empty (if not, we can directly conclude using Lemma \ref{trajectories} that $(R^*,E^*)$ is globally asymptotically stable), we define on $\mathcal{I} \times \R_*$ the application
\begin{equation}
\begin{array}{cccccccc}
    \Phi: & \mathcal{I} \times \R_+ & \to & \R_{>0}^2 &\\
    &(r,t) & \mapsto  &  \pmtx \phi_1(r,t) \\ \phi_2(r,t)\pmtrx & =\mathbf{X}_r(t),
\end{array}
\end{equation}
where $\mathbf{X}_r$ is a solution of the system with initial condition $\mathbf{X}_r(0)= \pmtx r \\ E^*\pmtrx$. This allows us to define the so-called Poincaré map \cite{teschl2012ordinary}  associated with the system \eqref{eq:dEdt}-\eqref{eq:dRdt} and section $\mathcal{S}$, as
\begin{equation}
    \begin{array}{ccccccc}
    \mathcal{P}: & \mathcal{I} & \to & ]0;R^*[  \\
    & r  & \mapsto  & \phi_1(r,t_r)\label{eq:poincaremap}
\end{array}
\end{equation}
where $t_r = \inf\{t>0, \ \mathbf{X}_r(t) \in \mathcal{S}\}$ is the first return time to $S$ ($t_r$ exists by definition of $\mathcal{I}$).  



\begin{lemma}\label{prop:Poincareprop}
The Poincaré map $\mathcal{P}$, as defined in equation \eqref{eq:poincaremap}, satisfies the following properties:
\begin{enumerate}[label=(\roman*)]
    \item $\mathcal{P}$ is $\mathcal{C}^1$ and $\exists \ 0< r_\mathcal{P}\leq R^*, \ \mathcal{I}= ]0,r_\mathcal{P}[$ or $\mathcal{I}= ]0,r_\mathcal{P}]$.
    \item $\mathcal{P}$ has no fixed point.
\end{enumerate}
\end{lemma}



\begin{proof}
\begin{enumerate}[label=(\roman*)]
    \item \label{prop:Poincareprop-i} Let $r_0 \in \mathcal{I}$ and $t_r$ its first return time, so $\phi_2(r_0,t_r)=E^*$ and $\phi_1(r_0,t_r)\in (0,R^*)$. Since the vector field is transverse to the nullclines away from $(R^*,E^*)$, $\partial_t\phi_2(r,t_r)\ne 0$. Since $\phi_2$ is $\mathcal{C}^1$, we can apply the implicit function theorem: There exists an open set $V$ containing $r_0$, an open set $\Omega$ containing $(r_0,t_r)$ and a $\mathrm{C}^1$ function $\xi$ such as : $$((r,t)\in \Omega \And \phi_2(r,t)=E^*) \iff (r\in V \And t=\xi(r) ).$$ 
    To conclude that $\mathcal{P}(r)=\phi_1(r,\xi(r))$, we would need to know that $\xi(r)$ is the first return time of $(r,E^*)$ to $S$. This can be shown, however, for $r$ in some open $U\subset V$ containing $r_0$, using continuity of the flow together with local injectivity of $(r,t)\mapsto \phi(r,t)$ near $(r_0,0)$. In particular, the domain of $\mathcal{P}$ is open, so $\mathcal{I}$ is an interval. Since $\phi_1$ and $\xi$ are $\mathcal{C}^1$ and $r_0 \in \mathcal{I}$ is arbitrary, it follows that $\mathcal{P}$ is $\mathcal{C}^1$ on $\mathcal{I}$.

    \item \label{prop:Poincareprop-ii}This is a consequence of the Bendixson-Dulac theorem \cite{dumortier_qualitative_2006}. Let's define $\nu(R,E)=\frac{1}{R}$, $f(R,E)=\frac{d R}{dt}$ and $g(R,E)=\frac{d E}{dt}$. Then,
        $$\frac{\partial(\nu f)}{\partial R}+\frac{\partial(\nu g)}{\partial E}=-(c_P \gamma_P'(E)(1-V) +c_R \gamma_R'(E)V) $$
    which is strictly negative (as we assume $\gamma_P$ and $\gamma_R$ being strictly increasing). Upon applying the Bendixson-Dulac theorem, we find the system has no nonconstant periodic solutions, and in particular, $\mathcal{P}$ admits no fixed point.
\end{enumerate}
\end{proof}
We can now characterize the behaviour of the iterated map, as


\begin{lemma}
Solutions $\mathbf{X}_r(t)$ of the system that start from $(r,E^*)$, where $r\in \mathcal{I}$, converge to  $(R^*,E^*)$.
\end{lemma}


\begin{proof} Using lemma \ref{prop:Poincareprop}, either $\forall r \in \mathcal{I}, \ \mathcal{P}(r)>r$, or $\forall r \in \mathcal{I}, \ \mathcal{P}(r)<r$. Let us consider again $r_\mathcal{P}$, as defined in lemma \ref{prop:Poincareprop}.

If $r_\mathcal{P} =  R^*$, then there exists $r_1$ such as $\mathcal{P}(r_1)>r_1$, since $(R^*,E^*)$ is locally asymptotically stable. Thus, for all $r\in\mathcal{I}$, the iterated sequence $\mathcal{P}^n(r)$ is strictly increasing, and it converges to $R^*$ (another limit of the sequence would be a fixed point of $\mathcal{P}$, which contradicts proposition \ref{prop:Poincareprop}), and $\mathbf{X}_r(t)$ converges to $(R^*,E^*)$. \\
If $r_\mathcal{P} <  R^*$, let $r_\mathcal{P}<r_0<R^*$. By taking the reversal trajectory $\Phi(r_0,-t)$, and using similar arguments as in lemma \ref{trajectories}, we can prove that there exists a first time $t>0$, such that $\phi_1(r_0,-t)\in \mathcal{I} $. By definition, $\mathcal{P}(\phi_1(r_0,-t))=r_0>\phi_1(r_0,-t)$, so $\mathcal{P}(r)>r$ for all $r\in \mathcal{I}$. In particular, there exists $n$ such that $\mathcal{P}^n(r) > r_\mathcal{P}$, i.e. $\mathcal{P}^n(r) \notin \mathcal{I}$. Using lemma \ref{trajectories}, $\mathbf{X}_r(t)$ thus converges to $(R^*,E^*)$ 
.\end{proof}

Combined with lemma \ref{trajectories}, this last lemma shows that $(R^*,E^*)$ is globally asymptotically stable. Finally, the second part of the proposition is a direct consequence of the stable manifold theorem for a fixed point \cite{guckenheimer_nonlinear_1983}, showing that if $\Delta\geq0$ the eigenvalues are real and there is a finite number of oscillations produced as the trajectories converge, and if $\Delta<0$, eigenvalues have a non zero imaginary part leading to an infinite number of oscillations around the equilibrium point.

\end{proof}



