\section{Convergence behavior}\label{appendix_2}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this Appendix section, we study the behaviour of the autonomous system with constant $\alpha$, $U$ and $V$ such that conditions \eqref{eq:mass_conservation} and \eqref{eq:constraint2} hold.


\begin{proposition}\label{prop:oscillation}
    There exist two oscillation threshold functions $\alpha_{\osc}(V)$ and $U_{\osc}(\alpha,V)$ such that:
    \begin{enumerate}[label=(\roman*)]
        \item if $\alpha<\alpha_{\osc}(V)$, the system is infinitely oscillating around the steady state,
        \item if $\alpha\geq\alpha_{\osc}(V)$, the system is infinitely oscillating around the steady state if and only if $U>U_{osc}$.
    \end{enumerate}

\end{proposition}

\begin{proof} 
Solving $\Delta=0$ for $U$ with the values of $(R^*,E^*)$ from equations \eqref{eq:R*}-\eqref{eq:E*} leads to 
\begin{equation}\label{def_uosc}
       U= U_{\osc}:=\frac{C_0\alpha (\gamma_{R,\max}V-\beta_R)-k_D\beta_R( c_P\gamma_{P,\max}(1-V)+c_R\gamma_{R,\max}V)}{k_D( c_P\gamma_{P,\max}(1-V)+c_R\gamma_{R,\max}V)+C_0\alpha-k_D\gamma_{R,\max}Vc_U},
 \end{equation}
 where  $$C_0= \frac{k_D+E^*}{R^*}=\frac{c_P\gamma_{P,\max}k_D(1-V)+c_R \gamma_{R,\max}k_D V}{(4\alpha\gamma_{R,\max} k_D V)^{\frac{1}{2}}}.$$ For this solution to be physical, we need $U_{\osc} \geq 0$. Note that the denominator is always positive because of condition \ref{eq:mass_conservation}, so $U_{\osc} \geq 0$ yields

\begin{equation}\label{alpha_osc_part}
    \alpha > \alpha_{\osc}\coloneqq\frac{4\beta_R^2k_D\gamma_{R,\max}V}{(\gamma_{R,\max}V-\beta_R)^2}.
\end{equation}
In particular, if $\alpha \leq \alpha_{osc}$, $\Delta <0 $ and $(i)$ is proved. Assuming $\alpha > \alpha_{osc}$, solving $\Delta(U)<0$ similarly leads to $U> U_{\osc}$.
\end{proof}

\begin{proposition}\label{prop:Psi_variation}

Let $\alpha >0$ and $\Psi:=-\real(\lambda)$, where $\lambda$ is the eigenvalue with the largest real part of the Jacobian matrix of the system at $(R^*,E^*)$. 

\begin{enumerate}[label=(\roman*)]
\item Let $U_{osc}^*=U_{osc}(V=1)$ (as defined in Eq. \eqref{def_uosc}). If $U_{osc}^* >0$ and $U\leq  U_{osc}^*$, then $\Psi(V)$ is increasing  as $U_\osc(V)\leq U  $, and is decreasing for $U_\osc(V)>U $. Else, it is only increasing. 

\item
Let $V\in[0,1]$, then, if $\alpha \geq \alpha_\osc(V)$, $\Psi(U)$ is increasing as $U \leq U_\osc(V)$, and is decreasing for $U > U_\osc(V)$. Else, it is only decreasing.
\end{enumerate}

\end{proposition}


\begin{proof}   We first show that  $U_{\osc}(V)$ is increasing. We first rewrite $U_{\osc}$ as
\beqq
    U_{\osc}=\frac{\beta_R\left(\frac{\alpha}{\alpha_{\osc}}\right)^{\frac{1}{2}}-\beta_R}{1+\frac{\alpha^{\frac{1}{2}}}{(4 k_D \gamma_{R,\max}V)^{\frac{1}{2}}}-\frac{\gamma_{R,\max}Vc_U}{c_P\gamma_{P,\max}(1-V)+c_R\gamma_{R,\max}V}}.
\eeqq
Using $ -\frac{\alpha^{\frac{1}{2}}}{4( k_D \gamma_{R,\max})^{\frac{1}{2}}}V^{\frac{-3}{2}}-\frac{c_P\gamma_{P,\max}\gamma_{R,\max}c_U}{(c_P\gamma_{P,\max}(1-V)+c_R\gamma_{R,\max}V)^2}<0$,
we obtain that $U_{\osc}$ is an increasing function of $V$.

\noindent
Let's compute the function $\Psi$, using the characteristic polynomial \eqref{eq:charac_poly} and the $\gamma_{i,\max}$ defined in \eqref{eq:gamma_function}. If $\Delta\leq0 $, both roots of the polynomial have the same real value, thus :
\begin{equation}
    \Psi=R^*\frac{c_R\gamma_R'(E^*)V+c_P\gamma_P'(E^*)(1-V)}{2}=R^{*}\frac{c_R \gamma_{R,\max}k_D V + c_P\gamma_{P,\max}k_D(1-V)}{2(k_D+E^*)^2}.
\end{equation}
If $\Delta>0$,
\begin{equation}
    \begin{split}
        \Psi&=\frac{1}{2}\left[R^*(c_R\gamma_R'(E^*)V+c_P\gamma_P'(E^*)(1-V))-\sqrt{\Delta}\right]\\
        &=R^{*}\frac{c_R \gamma_{R,\max}k_D V + c_P\gamma_{P,\max}k_D(1-V)}{2(k_D+E^*)^2}\left(1-\sqrt{1-4\frac{\alpha  \gamma_{R,\max}k_D V(k_D+E^*)^2}{R^{*2}(c_P\gamma_{P,\max}k_D(1-V) +c_R \gamma_{R,\max}k_D V )^2}}\right).
    \end{split}
\end{equation}
We now prove $(i)$ and $(ii)$

\begin{enumerate}[label=(\roman*)]

\item To study $\Psi(V)$, we distinguish the two cases:
\begin{itemize}
    \item If $U\geq U_{\osc}(V)$, then $\Delta\leq0$ so $\Psi=\frac{\alpha f(V)}{(k_D+E^*)^2}$, where $f(V) = \frac{1}{\alpha} R^* (c_P\gamma_{P,\max}(1-V) +c_R \gamma_{R,\max} V)$. Note first, from equation \eqref{eq:E*}, that $(k_D+E^*)^2$ is decreasing with respect to $V$. To study $f(V)$, we first note that if $c_R \gamma_{R,\max}\geq c_P \gamma_{P,\max}$, then $f$ is increasing. Else, we derive
    $$
        \frac{df}{dV}=
         V^2 (c_R \gamma_{R,\max}-c_P \gamma_{P,\max})((c_R \gamma_{R,\max}-c_P \gamma_{P,\max})(\beta_R+U)-c_U U)+c_P^2\frac{\gamma_{P,\max}^2}{\gamma_{R,\max}}(\beta_R+U).
    $$
    In particular, if $c_R \gamma_{R,\max}\geq c_P \gamma_{P,\max}$, then $\frac{df}{dV}>0$, so in both cases,  we find that $f$ is increasing.

\item If $U< U_{\osc}$, then 
$$\Psi(V)=R^{*}\frac{c_P\gamma_{P,\max}k_D(1-V) +c_R \gamma_{R,\max}k_D V }{2(k_D+E^*)^2}\left(1-F(V)\right),$$
where
\begin{equation}\label{def:F_psi}
    F(V) = \sqrt{1-4\frac{\alpha  \gamma_{R,\max}k_D V(k_D+E^*)^2}{R^{*2}(c_P\gamma_{P,\max}k_D(1-V) +c_R \gamma_{R,\max}k_D V )^2}}.
\end{equation}
Similarly as in the previous case, we can show that $F(V)$ is increasing. We next introduce 
$$G(V)=\frac{R^{*}(c_P\gamma_{P,\max}(1-V) +c_R \gamma_{R,\max} V )}{\alpha V} = C \frac{1}{\Psi(V)(1+F(V))},$$
where $C$ is a positive constant. Upon differentiating $G$, we obtain

\begin{equation*}
    \frac{dG}{dV}=\frac{c_P\gamma_{P,\max}c_UU}{(c_P\frac{\gamma_{P,\max}}{\gamma_{R,\max}}(\beta_R+U)+(c_R(\beta_r+U)-c_U U-c_P\frac{\gamma_{P,\max}}{\gamma_{R,\max}}(\beta_R+U))V)^2} \geq0,
\end{equation*}
so $\Psi' (1+F) +  F'\Psi \leq 0.$ Using that $F'$, $\Psi$ and $(1+F) \geq 0$, we conclude that $\Psi$ is  decreasing.
\end{itemize}



\item To study $\Psi(U)$, we distinguish the two cases
\begin{itemize}
\item If $U> U_{\osc}$, $\Psi=R^{*}\frac{c_P\gamma_{P,\max}k_D(1-V) +c_R \gamma_{R,\max}k_D V }{2(k_D+E^*)^2} = Cf(U)$, where $C>0$ and
$$f(U) = (\gamma_{R,\max}k_D V)^2\frac{R^{*}}{(k_D+E^*)^2}=\frac{\alpha(\gamma_{R,\max} V-(\beta_R+U))^2}{c_R(\beta_r+U)+c_P\frac{\gamma_{P,\max}(1-V)}{\gamma_{R,\max}V}(\beta_R+U)-c_U U}.$$
In particular, we have 
$$\frac{df}{dU} = \frac{((U+\beta_R)^2- (\gamma_{R,\max} V)^2)(c_R+c_P\frac{\gamma_{P,\max}(1-V)}{\gamma_{R,\max}V}-c_U)+2 (U+\beta_R- \gamma_{R,\max} V)\beta_R c_U}{(c_R(\beta_r+U)+c_P\frac{\gamma_{P,\max}(1-V)}{\gamma_{R,\max}V}(\beta_R+U)-c_U U)^2}.$$
Using \eqref{eq:mass_conservation} and \eqref{eq:constraint2}, $\frac{df}{dU}<0$ so $\Psi$ is a decreasing function of $U$.

\item If $U< U_{\osc}$, $
\Psi(U)=R^{*}\frac{c_P\gamma_{P,\max}k_D(1-V) +c_R \gamma_{R,\max}k_D V }{2(k_D+E^*)^2}\left(1-F(U)\right),$
where $F(U)$ is the same function as in equation \eqref{def:F_psi}. Note that
\beqq
  \frac{k_D+E^*}{R^*}=\frac{k_D V\gamma_{R,\max}}{\alpha(V\gamma_{R,\max}-(\beta_R+U))}\left(\frac{c_P\gamma_{P,\max}(1-V)+c_R\gamma_{R,\max}V}{\gamma_{R,\max}V}(\beta_R+U)-c_U U\right)
\eeqq
is increasing because of the assumption \eqref{eq:mass_conservation}, so $F(U)$ is decreasing. Similarly as in $(i)$, we can show that $(1+F)\Psi' +F'\Psi \geq 0$, and conclude that $\Psi(U)$ is increasing.
\end{itemize}
\end{enumerate}

\end{proof}

\begin{lemma}\label{lemma_lower_bound}
Let $(U,V)\in \left\{U_{\min} , U_{\max} \right\}\times  \left\{ V_{\min} , V_{\max} \right\}$, then
\beqq
\Psi(U,V) \geq \min \left( \Psi(U_{\min},V_{\max}),\Psi(U_{\max},V_{\min})\right).
\eeqq
\end{lemma}

\begin{proof}
If $U\leq U_{\osc}$, and since $U_{\osc}(V)$ is increasing, then proposition \ref{prop:Psi_variation} yields $\Psi(U,V) \geq\Psi(U_{min},V_{max})$. Else, we also conclude from proposition \ref{prop:Psi_variation} that $\Psi(U,V) \geq\Psi(U_{\max},V_{\min})$.

\end{proof}


