\section{Behaviour of the objective function}\label{appendix_3}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this Appendix section, we prove the following results that are used in section \ref{sec:results_oc} of the main text.

\begin{proposition}\label{prop:rho_star}
Let $\rho^*$ be the protein production rate value at $(R^*,E^*)$, so that
\begin{equation}
\rho^*=\frac{\alpha\gamma_{P,\max}(\beta_R+U)(1-V)}{\gamma_{R,\max}V(c_R(\beta_r+U)+\frac{c_P\gamma_{P,\max}(1-V)(\beta_R+U)}{\gamma_{R,\max}V}-c_U U)}.\label{eq:rho_star}
\end{equation}
Then, $\rho^*$ is an increasing function of $U$, and decreasing function of $V$.
\end{proposition}
\begin{proof}
Differentiating Eq. \eqref{eq:rho_star} with respect to $U$ yields

\begin{equation}
    \frac{d \rho^*}{dU}=\frac{\alpha\gamma_{P,\max}(1-V)}{\gamma_{R,\max}V} \frac{c_U\beta_r }{(c_R(\beta_r+U)+\frac{c_P\gamma_{P,\max}(1-V)(\beta_R+U)}{\gamma_{R,\max}V}-c_U U)^2}>0, 
\end{equation}
so $\rho^*(U)$ is increasing. On the other hand, we can re-write Eq. \eqref{eq:rho_star} as
\begin{equation*}
       \rho^* =\frac{\gamma_{P,\max}\alpha(\beta_R+U)}{\gamma_{R,\max}}\frac{1}{\frac{V}{1-V}(c_R\beta_r+(c_R-c_U)U)+c_P\frac{\gamma_{P,\max}}{\gamma_{R,\max}}(\beta_R+U)}.
\end{equation*}
Since  $x\mapsto \frac{x}{1-x}$ is strictly increasing on $[0,1]$ and $(c_R\beta_r+(c_R-c_U)U)> 0$ (as a result of the mass conservation \eqref{eq:mass_conservation}t), we conclude that $\rho^*$ is a strictly decreasing function of $V$.
\end{proof}

We next prove proposition \ref{prop:cst_ctrl} (stated here again for clarity):

\begin{proposition*}
Let $\rho^*(U,V, \alpha)$ be the value of the production rate function $\rho$ (Eq. \eqref{eq:rho}) at the steady state $(R^*,E^*)$ associated with $(U,V, \alpha)$ (Eq. \eqref{eq:R*}-\eqref{eq:E*}), and assume that the quasi-static approximation holds (Eq. \eqref{eq:Hypothesis_char_time}). Then the optimal control problem Eq. \eqref{eq:optimal_formulation} admits a solution if and only if the equation 

\begin{equation*}
\rho^*(U,V,\alpha_{\max}) = \rho^*(U_{\max}, V_{\min},\alpha_{\min})
\end{equation*}
admits a solution $(U_s,V_s)$. In this case,
\begin{equation*}
    (\hat{U},\hat{V})(t) = \left\{
    \begin{array}{ll}
        (U_{\max},V_{\min})  & \mbox{if  } 0\leq t<\frac{\tau}{2}\\
        (U_s,V_s) & \mbox{if } \frac{\tau}{2} \leq t< \tau
    \end{array}
\right.
\end{equation*}
is optimal for Eq. \eqref{eq:optimal_formulation}, and solutions of Eq. \eqref{eq:usvs} define a 1D-manifold $\Gamma=[U_{\min},U_{\max}]\times[V_{\min},V_{\max}]\cap\{(\Tilde{F}(V),V), V\in[0,1]\}$, such that $\Tilde{F}$ is an increasing function of $V$. 
\end{proposition*}

\begin{proof}
When $\alpha=\alpha_{\min}$, proposition \ref{prop:rho_star} gives us the values for $U$ and $V$ that maximize $\rho^*$, as $U=U_{\max},V=V_{\min}$. The associated production rate is then
\beqq\label{low_prod_rate}
\rho_{0}\coloneqq\frac{\alpha_{\min}\gamma_{P,\max}(\beta_R+U_{\max})(1-V_{\min})}{\gamma_{R,\max}V_{\min}(c_R(\beta_r+U_{\max})+\frac{c_P\gamma_{P,\max}(1-V_{\min})(\beta_R+U_{\max})}{\gamma_{R,\max}V_{\min}}-c_U U_{\max})}.
\eeqq
When $\alpha=\alpha_{\max}$, and for the protein production to stay constant, the controls $U,V$ are then solutions of 
\beqq
\frac{\alpha_{\max}\gamma_{P,\max}(\beta_R+U)(1-V)}{\gamma_{R,\max}V(c_R(\beta_r+U)+\frac{c_P\gamma_{P,\max}(1-V)(\beta_R+U)}{\gamma_{R,\max}V}-c_U U)}=\rho_{0}.
\eeqq
We thus have to solve the following non-linear system
\begin{equation*}
    \begin{split}
    U\left(c_P\gamma_{P,\max}\rho_{0}-\alpha_{\max}\gamma_{P,\max}+V\left[\gamma_{R,\max}c_R\rho_{0}-c_P\gamma_{P,\max}\rho_{0}-\gamma_{R,\max}c_U\rho_{0}+\alpha_{\max}\gamma_{P,\max}\right]\right)\\
    =-V\beta_R\left[\gamma_{R,\max}c_R\rho_{0}-c_P\gamma_{P,\max}\rho_{0}+\alpha_{\max}\gamma_{P,\max}\right] -c_P\gamma_{P,\max}\beta_R\rho_{0}+\alpha_{\max}\gamma_{P,\max}\beta_R
\end{split}
\end{equation*}
Note that the term multiplying $U$ on the left hand side of the equation is not equal to 0. Otherwise, it would lead to have a value of $V$ that is not compatible with $\gamma_{R,\max}c_U\rho_{0}>0$. The following function $\Tilde{F}_{\alpha}(V)$ is hence well defined for $\alpha=\alpha_{\max}$:
\beq\label{eq:tildeF}
\Tilde{F}_{\alpha}(V)=\frac{-V\beta_R\left[\gamma_{R,\max}c_R\rho_{0}-c_P\gamma_{P,\max}\rho_{0}+\alpha\gamma_{P,\max}\right] -c_P\gamma_{P,\max}\beta_R\rho_{0}+\alpha\gamma_{P,\max}\beta_R}{c_P\gamma_{P,\max}\rho_{0}-\alpha\gamma_{P,\max}+V\left[\gamma_{R,\max}c_R\rho_{0}-c_P\gamma_{P,\max}\rho_{0}-\gamma_{R,\max}c_U\rho_{0}+\alpha\gamma_{P,\max}\right]},
\eeq
and the optimal control values  are solutions of $U=\Tilde{F}_{\alpha_{\max}}(V)$. Since $\rho^*$ is an increasing function in $U$, a decreasing function in $V$ and since $\rho^*(\Tilde{F}_{\alpha_{\max}}(V),V,\alpha_{\max})$ is constant for the set of admissible parameters, we deduce that $\Tilde{F}_{\alpha_{\max}}(V)$ is increasing. Note that with the same considerations, we deduce that $\Tilde{F}_{\alpha_{\max}}$ is a decreasing function of $\alpha_{\max}$. Moreover, by construction and because $\alpha_{\max}>\alpha_{\min}$, we know that $\Tilde{F}_{\alpha_{\max}}(V_{\min})<U_{\max}$. In particular, there exists a constant control if and only if $\Tilde{F}_{\alpha_{\max}}(V_{\max})\geq U_{\min}$
\end{proof}

