\section{Optimal control with one fixed control }\label{appendix_4}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this Appendix section, we detail the analytical calculations to support the results from section \ref{sec:constraints}. The protein production rate at steady state is 
\begin{equation}
    \rho^*(U,V,\alpha)=\frac{\gamma_{P,\max}}{\gamma_{R,\max}}(U+\beta_R)\frac{1-V}{V}\frac{\alpha}{c_R(\beta_r+U)+\frac{c_P\gamma_{P,\max}(1-V)(\beta_R+U)}{\gamma_{R,\max}V}-c_U U}.
\end{equation}
Assuming $0<V<1$, having a constant protein production over the two periods of the control (Eq. \eqref{eq:constraints_rho}) is equivalent to
\begin{equation}
    \alpha_{\min}=\alpha_{\max}\frac{(1-V_{\max})V_{\min}(c_R+c_P\frac{\gamma_{P,\max}(1-V_{\min})}{\gamma_{R,\max}V_{\min}}-c_U \frac{U}{U+\beta_R})}{(1-V_{\min})V_{\max}(c_R+c_P\frac{\gamma_{P,\max}(1-V_{\max})}{\gamma_{R,\max}V_{\max}}-c_U \frac{U_{\min}}{U_{\min}+\beta_R})}.
\end{equation}
Reordering this equation, we obtain at constant protein production
\begin{equation}\label{eq:u_hat}
    U=\hat{f}_U(U_{\min}), \text{ where $\hat{f}_U$ is defined as } \hat{f}_U(U_{\min})\coloneqq \frac{\beta_R g(U_{\min})}{1-g(U_{\min})},
\end{equation}
where 
\begin{equation}
    \begin{split}
        g(U_{\min})=&\frac{\alpha_{\min}(1-V_{\min})V_{\max}}{\alpha_{\max}(1-V_{\max})V_{\min}}\left(\frac{U_{\min}}{U_{\min}+\beta_R}\right)\\ &+\frac{c_R}{c_U}\left(1-\frac{\alpha_{\min}(1-V_{\min})V_{\max}}{\alpha_{\max}(1-V_{\max})V_{\min}}\right)+\frac{c_P}{c_U}\frac{\gamma_{P,\max}(1-V_{\min})}{\gamma_{R,\max}V_{\min}}\left(1-\frac{\alpha_{\min}}{\alpha_{\max}}\right).
    \end{split}
\end{equation}
Now that we can link $U_{\min}$ and $U$, we  estimate a range of values for $\alpha_{\min}$ that ensure constant protein production. To produce valid values $U$, the following conditions should hold 
\begin{equation}\label{eq:constraint3}
    U_{\min}\leq \hat{f}_U(U_{\min}),\quad \text{ and }\quad \beta_R+\hat{f}_U(U_{\min})\leq\gamma_{R,\max}V_{\min} \;\text{ (see \eqref{eq:constraint2})}.
\end{equation}
Note that $g$ is increasing, so $\hat{f}_U$ is also increasing. We derive now a lower bound for $\alpha_{\min}$: for a solution to Eq.\eqref{eq:constraint3} to exist, $\hat{f}_U$ has to be less than $\gamma_{R,\max}V_{\min}-\beta_R$ for some value. Thus from
\begin{equation}\label{eq:bound_alpha1}
    \hat{f}_U(0)\leq \gamma_{R,\max}V_{\min}-\beta_R,
\end{equation}
we deduce the lower bound :
\begin{equation}\label{eq:lower_bound_alpha}
    \frac{\alpha_{\min}}{\alpha_{\max}}\geq q_1\coloneqq\frac{(c_R-c_U)\gamma_{R,\max}V_{\min}+c_P\gamma_{P,\max}(1-V_{\min})+c_U\beta_R}{(1-V_{\min})\left(c_R\gamma_{R,\max}\frac{V_{\max}}{1-V_{\max}}+c_P\gamma_{P,\max}\right)}>0.
\end{equation}
Since $\hat{f}_U$ has to be positive to verify Eq.\eqref{eq:constraint3}, such that at least
\begin{equation}\label{eq:bound_alpha2_app}
    \hat{f}_U(\gamma_{R,\max}V_{\min}-\beta_R)\geq 0
\end{equation}
we derive the upper bound 


\begin{equation}\label{eq:upper_bound_alpha_app}
    \frac{\alpha_{\min}}{\alpha_{\max}}\leq q_2\coloneqq\frac{c_R\gamma_{R,\max}V_{\min}+c_P\gamma_{P,\max}(1-V_{\min})+c_U\frac{\alpha(1-V_{\min})V_{\max}}{\alpha_{\max}(1-V_{\max})V_{\min}}(\gamma_{R,\max}V_{\min}-\beta_R)}{(1-V_{\min})\left(c_R\gamma_{R,\max}\frac{V_{\max}}{1-V_{\max}}+c_P\gamma_{P,\max}\right)}>0.
\end{equation}

We now study the value of control bounds $U_{\max},V_{\min}$ enabling the existence of an optimal solution of problem \eqref{eq:optimal_formulation}, for a given protein production  $\rho_0$ at high resource intake $\alpha=\alpha_{\max}$. We use the properties of function $\Tilde{F}_{\alpha}$ detailed in the proof of Proposition \ref{prop:cst_ctrl} (Appendix \ref{appendix_3}). In this case, the domain of $(U_{\max},V_{\min})$ that allows to find optimal controls is more simple to obtain, as it is given by
\begin{equation}\label{eq:region_exist_ctrl}
    \{(U_{\max},V_{\min})\quad|\quad \rho^*(U_{\max},V_{\min},\alpha_{\min})\geq \rho_0,\; U_{\max}\geq U_{\min},\; V_{\min}\leq V_{\max} \}.
\end{equation}
In particular, solving $\rho^*(U,V,\alpha_{\min})= \rho_0$ yields an explicit expression for $U= \Tilde{F}_{\alpha_{\min}}(V)$, where  $\Tilde{F}_{\alpha}$ is defined in Appendix \ref{appendix_3}, equation \eqref{eq:tildeF}. Note that while the corresponding limit value for $\alpha_{\min}$ cannot be explicitly derived in general (non trivial optimization), we obtain a lower bound by solving
 \begin{equation}
     \Tilde{F}_{\alpha_{\min}}\left(\frac{U_{\min}+\beta_R}{\gamma_{R,\max}}\right)\leq \gamma_{R,\max}V_{\max}-\beta_R,
 \end{equation}
 which yields
 \begin{equation}\label{eq:domain_UV_app}
    \alpha_{\min}\geq\rho_{0}q_3 \coloneqq\left(\frac{U_{\min}+\beta_R}{\gamma_{R,\max}-(U_{\min}+\beta_R)}\left(c_R\frac{\gamma_{R,\max}}{\gamma_{P,\max}}-c_U\frac{\gamma_{R,\max}V_{\max}-\beta_R}{\gamma_{P,\max}V_{\max}}\right)+c_P\right)>0.
\end{equation}


