\end{gathered}
\end{equation}
where step (b) holds due to the use of normalized MRT beamforming, i.e., ${\left| \mathbf{h}_{c,c,{k_c}} \mathbf{f}_{c,k_c} \right|^2} = 1$.

Moreover, the received signal power of GU-$\{c,k_c\}$ is primarily determined by the UAV's transmit power and the corresponding path loss. As shown in \eqref{eq:interference_gain}, the interference from a neighboring UAV-$u$ is captured by the term $| \mathbf{h}_{u,c,k_c} \mathbf{f}_{u,k_u} |^2$, which depends on the relative azimuth and elevation angles between UAV-$u$ and GU-$\{c,k_c\}$. These angles are uniquely determined by the spatial positions of the UAV and the user, as well as the UAV’s orientation.
Given the positions of the GUs and UAVs, the relative angles of the GU-$\{c,k_c \}$ corresponding to the UAV-$u$ can be calculated by 
\begin{equation}\label{eq:angle_expression}
\begin{aligned}
{\alpha_{k_c}} &= \arccos \left( {\dfrac{{x_{c,k_c}}}{{\sqrt {{{\left( {x_{c,k_c} - x_{u}} \right)}^2} + {{\left( {y_{c,k_c} - y_{u}} \right)}^2}} }}} \right), \hfill \\
{\beta_{k_c}} &= \arccos \left( {\dfrac{{y_{c,k_c}}}{{\sqrt {{{\left( {x_{c,k_c} - x_{u}} \right)}^2} + {{\left( {y_{c,k_c} - y_{u}} \right)}^2}} }}} \right), \hfill \\
{\gamma_{k_c}} &= \arccos \left( {\dfrac{z_u}{{\sqrt {{{\left( {x_{c,k_c} - x_{u}} \right)}^2} + {{\left( {y_{c,k_c} - y_{u}} \right) }^2 + z_u^2}} }}} \right). \hfill
\end{aligned}
\end{equation}
Similarly, the angles ${\alpha_{k_u}}$, ${\beta_{k_u}}$, and ${\gamma_{k_u}}$ for GU-$\{u,k_u\}$ can be computed using its position in place of GU-$\{c,k_c\}$ in \eqref{eq:angle_expression}.

Considering the effect of UAV rotation, let $\omega_u$ denote the rotation angle of UAV-$u$. By substituting $\omega_u$ and the relative angles from \eqref{eq:angle_expression} into the rotation transformation in \eqref{rotation}, the resulting interference gain can be expressed as in \eqref{eq:rotated_interference_beam_gain}. Accordingly, the SINR expression in \eqref{SINR} can be reformulated to incorporate the rotation-dependent interference term. 
\begin{equation}
\begin{aligned}
    &\tilde \eta_{c,k_c}\left( \omega_1, \ldots,\omega_N\right) \hfill \\
    &= \frac{P}{{\sum\limits_{{u\in \mathcal{U}\backslash c}} {\sum\limits_{{k_u} \in {\mathcal{K}_u}} {\frac{P {L_{c,c,{k_c}}}}{{  {{K_u}} {L_{u,c,{k_c}}}}}{{\tilde g}_{\left\{ {{k_c},{k_u}} \right\}}}} } \left( {{\omega _u}} \right)   + {L_{c,c,{k_c}}}\sigma _n^2}}. \hfill \\
\end{aligned}
\end{equation}
Consequently, the achievable sum rate of the UAV orientation-aware system can be expressed as
{\small
\begin{equation}\label{sum_rate}
\begin{aligned}
&R\left(\omega_1,\ldots,\omega_{N} \right) \hfill \\
& =  \sum\limits_{c \in \mathcal{C}} \sum\limits_{k_c \in \mathcal{K}_c} {{{\log }_2}} \left( {1 + \frac{P}{{\tilde \eta_{c,k_c}\left( \omega_1, \ldots,\omega_N\right) + {L_{c,c, k_c}}}\sigma _n^2}} \right). \hfill \\
\end{aligned}
\end{equation}
}
This expression highlights that the system-wide sum rate is collectively determined by the rotation angles of all UAVs, as each orientation affects the interference experienced by neighboring users. Therefore, coordinated optimization of UAV orientations is essential for effective interference mitigation. 


\subsection{Alternating UAV Rotation Scheme}
To mitigate inter-cell interference and improve system throughput, we formulate a rotation-aware sum-rate maximization problem by treating the rotation angles of all $N$ UAVs as optimization variables, i.e.,
\begin{equation}\label{eq:optimization_problem}
\begin{aligned} &\mathop {\arg\max }\limits_{\left\lbrace \omega_1,\ldots,\omega_{N} \right\rbrace }  R\left(\omega_1,\ldots,\omega_{N} \right) \hfill \\ &s.t. \quad {\omega_k} \in \left[ {0,\frac{\pi }{2}} \right],k = 1, \ldots ,{N}. \end{aligned} 
\end{equation} 
Due to the non-convex nature of the objective function, which involves intricate trigonometric and nonlinear couplings among the UAV rotation, gradient-based methods are inapplicable.
Although exhaustive search over all possible rotation combinations can yield the global optimum, it is computationally prohibitive when the number of UAVs or the angle resolution becomes large. 
To reduce the search complexity, the UAV rotation angle is confined to the range $\left[0, \frac{\pi}{2} \right]$, taking advantage of the array symmetry described in Lemma 2.

To make the optimization tractable, we introduce a zero-order coordinate-wise alternating method, referred to as alternating UAV rotation (AUR), which iteratively updates the rotation angle of each UAV while keeping the others unchanged.
The procedure is summarized in Algorithm \ref{alg:alternating_UAV_rotation_optimization}.


\begin{algorithm}
\caption{Alternating UAV Rotation (AUR) Optimization}
\label{alg:alternating_UAV_rotation_optimization}
\KwIn{Positions of ground users: $\{x_{c,k_c}, y_{c,k_c}\}$;  Positions of UAVs: $\{x_u, y_u, z_u\}$;  \qquad \qquad \qquad Angle discretizations resolution: $W$;
\qquad \qquad \qquad Max iterations $L$;
Convergence threshold $\epsilon$;}
\KwOut{Optimal UAV rotation angles $\{\omega_1^*,\ldots,\omega_{N}^*$\};}
\textbf{Initialize:} $\omega_u^{(0)} = 0$, $R^{(0)} = 0$, $\Delta R = \infty$, $l = 0$;
Pre-compute relative angles $\alpha$, $\beta$, and $\gamma$ using \eqref{eq:angle_expression};
\While{$l \leq L$ and $\Delta R > \epsilon$}{
$l = l+1$\;
		Update the optimal rotation angle of each UAV:\\
\For{$u = 1$ \KwTo $N$}{
\small{\small{
$\omega_u^{(l)} \leftarrow  \mathop {\arg \max }\limits_{{\omega_u}  = \left\lbrace 0,\frac{\pi }{{2W}}, \ldots ,\frac{\pi }{2} \right\rbrace} R(\omega_1^{(l)}, \dots, \omega_{u-1}^{(l)}, \omega, \omega_{u+1}^{(l-1)}, \dots, \omega_N^{(l-1)})$;
}
}}
$R^{(l)} \leftarrow R(\omega_1^{(l)}, \ldots, \omega_N^{(l)})$;
$\Delta R \leftarrow R^{(l)} - R^{(l-1)}$;
}
\end{algorithm}



