\begin{rem}
\label{rem:limit-colimit-frobenius_der} 
Let $R$ be a derived $\FF_p$-algebra, and let $S:I\to \operatorname{DAlg}_{R}$ be a small diagram of $R$-algebras. Then, the relative Frobenius map of the limit is equivalent to the composition 
\[
(\lim_{i\in I}S_i) \otimes^L_{R,F} R\to \lim_{i\in I}(S_i \otimes^L_{R,F}R) \to[\lim_{i\in I}F_{S_i/R}] \lim_{i\in I}S_i.
\]
Similarly, the relative Frobenius map of the colimit is equivalent to 
\[
(\colim_{i\in I}S_i) \otimes^L_{R,F} R\to[\simeq] \colim_{i\in I}(S_i \otimes^L_{R,F}R) \to[\colim_{i\in I}F_{S_i/R}] \colim_{i\in I}S_i.
\]
\end{rem}

%An important theorem of Kunz \citep[Theorem 2.9]{Kun69} states that a Noetherian $\FF_p$-algebra is regular if and only if its absolute Frobenius map is flat. This highlights the significance of Frobenius flatness in commutative algebra and algebraic geometry in characteristic $p$. 
Using the following definition of flatness for derived rings, which is similar to \citep[Definition 7.2.2.10]{Lur17} for the underlying $E_{\infty}$-rings, we obtain a lemma that will be important for several arguments and results later in this article.

\begin{defi}
\label{def:flatness}
We call a map $R\to S$ of derived rings \emph{flat}, if and only if $S$ is a flat module over $R$, meaning that $H^0(S)$ is a flat over $H^0(R)$, and for all $k\in \ZZ$, the canonical map 
\[
H^k(R)\otimes_{H^0(R)}H^0(S)\to H^k(S),
\]
which sends $x\otimes y$ to $(H^k f)(x)\cdot y$, is an isomorphism.
\end{defi}

\begin{lem}
\label{lem:flat_frobenius_implies_coconnective}
Let $R$ be a derived $\FF_p$-algebra. If the absolute Frobenius map of $R$ is flat, then $R$ is coconnective. 
\end{lem}
\begin{proof}
The proof of \citep[Proposition 11.6]{BS17} by Bhatt and Scholze shows that the absolute Frobenius map of a derived $\FF_p$-algebra induces the zero map on negative cohomology groups. The claim then follows from the definition of flatness.
\end{proof}

In particular, for an animated commutative ring $R$, the absolute Frobenius map $F_R$ is flat if and only if $H^0(F_R)=F_{H^0(R)}$ is flat and $R$ is discrete.

If the base ring has a flat Frobenius map, the relative Frobenius map also induces the zero map on negative cohomology groups.

\begin{lem}
\label{lem:rel_frob_zero_on_cohomology}
Let $R\to S$ be a map of derived $\FF_p$-algebras, and suppose that the absolute Frobenius map $F_R$ is flat. Then $H^k(F_{S/R})=0$ for all $k\le -1$. 
\end{lem}
\begin{proof}
Since the absolute Frobenius map of $R$ is flat, applying $H^k$ to the relative Frobenius map
\[
S\otimes_{R,F}^L R 
\to[F_S\otimes \id_R] 
S\otimes_R^L R
\]
yields
\[
 H^k(S\otimes^L_{R,F} R) \cong H^k(S)\otimes_{H^0(R),F} H^0(R)
\to[H^k(F_S)\otimes \id_{H^0(R)}] 
H^k(S)\otimes_{H^0(R)} H^0(R) \cong H^k(S),
\]
which is zero for $k\le -1$. %Here, the first isomorphism holds by \citep[Proposition 7.2.2.13]{Lur17}.
\end{proof}

\begin{rem}
\label{rem:canonical_fibersequences_connective}
For any map $R\to S$ of animated $\FF_p$-algebras, the diagram (\ref{eq:relative_frobenius_der}) canonically induces two fiber sequences of cotangent complexes:
\[
\begin{array}{c@{\quad}c@{\quad}c}
    L_{S/R} \otimes^L_{S,F} S \to L_{S/R} \to L_{F_{S/R}} & \quad \text{and} \quad & L_{F_R} \otimes^L_R S \to L_{F_S} \to L_{F_{S/R}.}
\end{array}
\]
\end{rem}

From the first of these exact triangles, it follows that the cotangent complex of the relative Frobenius map is determined by the cotangent complex of the underlying map of animated rings.

\begin{lem}
\label{lem:cotangent_relative_frobenius}
Let $R\to S$ be a map of animated commutative $\FF_p$-algebras. Then, there exists a canonical equivalence
\[
L_{F_{S/R}}\simeq L_{S/R} \oplus (L_{S/R}\otimes^L_{S,F} S[1])
\]
of $S$-modules.
\end{lem}
\begin{proof}
We show that the map $L_{S/R} \otimes^L_{S,F} S \to L_{S/R}$ is zero. The stated equivalence then follows formally, since $L_{F_{S/R}}$ is the cofiber of this map. 

We can express $R\to S$ as a sifted colimit of maps of the form $\FF_p[X]\to \FF_p[X,Y]$, where $X$ and $Y$ are finite sets; see the paragraph preceding Definition 2.33 in Mao’s article \citep{Mao24}. The Frobenus map of $R\to S$ is obtained by passing to the colimit of the Frobenius morphisms in this system. Consequently, the above map between cotangent complexes is induced by the maps arising from the commutative diagrams
\[
\begin{tikzcd}
{\FF_p[X]} \arrow[r, "F"] \arrow[d] & {\FF_p[X]} \arrow[d] \\
{\FF_p[X,Y]} \arrow[r, "F"]           & {\FF_p[X,Y]}          
\end{tikzcd}
\]
in each stage of the sifted diagram. Thus, it suffices to prove the claim for $\FF_p[X]\to \FF_p[X,Y]$. This follows from a straightforward calculation: any element of the form $d(r)\otimes b$ is mapped to $d(r^p)b^p=0$.
\end{proof}


\section{Relative Perfectness} 
\label{sec:relative_perfectness}
We recall that a derived $\FF_p$-algebra is called \emph{perfect} if and only if its Frobenius endomorphism is an equivalence. In this section, we discuss a relative analog of perfectness using the relative Frobenius map.

\begin{defi}
A map $R\to S$ of derived commutative $\FF_p$-algebras is \emph{relatively perfect} if and only if the relative Frobenius map $F_{S/R}$ is an equivalence. In this case, we say that \emph{$S$ is a relatively perfect $R$-algebra}.

We denote by $\dalgperf{R}$ the full subcategory of $\dalg_R$ consisting of relatively perfect $R$-algebras.
\end{defi}

\begin{ex}
Any equivalence of derived $\FF_p$-algebras is relatively perfect. 

A derived $\FF_p$-algebra is relatively perfect over $\FF_p$ if and only if it is perfect. More generally, let $R\to S$ be a map of derived $\FF_p$-algebras with $R$ perfect. Then $F_S$ factors as an equivalence followed by $F_{S/R}$, so $S$ is relatively perfect over $R$ if and only if it is perfect itself.
\end{ex}

\begin{rem}
\label{rem:equivalence_of_spaces_der}
Let $R$ be a derived $\FF_p$-algebra, and let $T$ and $S$ be derived $R$-algebras. If $T$ is relatively perfect, postcomposition with $F_{S/R}$ induces an equivalence of mapping anima
\[
\operatorname{Map}_{\ACR_R}(T,S\otimes_{R,F}R)\to \operatorname{Map}_{\ACR_R}(T,S),
\]
with an inverse given by a composition
\[
\operatorname{Map}_{\ACR_R}(T,S) \to[(-)\otimes^L_{R,F}R] \operatorname{Map}_{\ACR_R}(T\otimes^L_{R,F}R,S\otimes^L_{R,F}R) \to[\circ F_{T/R}^{-1}] \operatorname{Map}_{\ACR_R}(T ,S\otimes^L_{R,F}R).
\]
\end{rem}


\begin{rem}
\label{rem:tor_independence_relative_perfect_der}
For a map $R\to S$ of discrete rings, our definition of relative perfectness requires that the classical (non-derived) relative Frobenius map is an isomorphism, and that $S$ and $F_*R$ are Tor-independent over $R$. If both rings are Noetherian, Tor-independence holds automatically whenever the classical relative Frobenius map is an isomorphism. Indeed, in this case the map $R\to S$ is formally smooth (even formally \'etale) by \citep[Théorème 21.2.7]{EGAIV} and thus flat by \citep[Théorème
19.7.1]{EGAIV}. If the base ring is regular Noetherian, our definition also coincides with the classical notion.
\end{rem}

\begin{rem}
\label{rem:der_rel_perf_bc_prop}
Let $R$ be a derived $\FF_p$-algebra. By definition, the absolute Frobenius map of any relatively perfect derived $R$-algebra inherits all properties of $F_R$ that are stable under base change. For instance, if $R$ has a flat Frobenius endomorphism, then any relatively perfect $R$-algebra also has a flat Frobenius endomorphism and is therefore coconnective by Lemma \ref{lem:flat_frobenius_implies_coconnective}. 
\end{rem}


\begin{ex}
\label{ex:etale_vs_rel_perf_der}
The notion of relative perfectness for discrete $\FF_p$-algebras is closely related to various forms of \'etaleness. We have the following implications:
\begin{align*}
\text{\'etale} 
&\implies \text{ind-\'etale} 
\implies \text{weakly \'etale} 
\implies \text{relatively perfect}
\\
&\implies \text{acyclic cotangent complex} 
\implies \text{formally \'etale};
\end{align*}
see \cite[\href{https://stacks.math.columbia.edu/tag/097N}{Lemma 097N}]{stacks-project}, \cite[\href{https://stacks.math.columbia.edu/tag/0F6W}{Lemma 0F6W}]{stacks-project}, and Proposition \ref{prop:cotangent_rel_perf_animated}. %in particular, any relatively perfect morphism of noetherian rings is flat. 
In certain situations, some of these implications become equivalences. For instance:
\begin{itemize}
\item If $R \to S$ is a map of Noetherian rings, then the vanishing of the cotangent complex is equivalent to formal \'etaleness.
\item If $R \to S$ is a map of Noetherian \textit{F}-finite rings, then $S$ is relatively perfect over $R$ if and only if the cotangent complex is acyclic; see Theorem~\ref{thm:acyclic_cotanget_implies_rel_perf}.
\end{itemize}
\end{ex}

By a result of Gabber \citep[Proposition 5.2]{Kat86}, any relatively perfect scheme over a regular locally Noetherian scheme is flat. This does not hold in general if the base is not Noetherian.

\begin{ex}
\label{ex:rel_perf_not_flat_der}
Let $R$ be a discrete commutative $\FF_p$-algebra with flat Frobenius homomorphism, and let $I\subset R$ be an ideal satisfying $I^{[p]}=I$. Then $R/I$ is relatively perfect over $R$, but it is not necessarily flat. For example, take $R=\FF_p[x^{\frac{1}{p^{\infty}}}]$ with $I=(x^{\frac{1}{p^{\infty}}})$. In particular, a relatively perfect map need not be weakly \'etale.
\end{ex}

The proof of the following lemma is a direct application of Remark \ref{rem:basic_properties_general_der} and is therefore omitted.

\begin{lem}
\label{lem:relative_perfect_basic_properties_der}
\begin{enumerate}
\item[(i)] Let $R\to S \to T$ be maps of derived $\FF_p$-algebras. If $R\to S$ is relatively perfect, then $T$ is relatively perfect over $R$ if and only if it is relatively perfect over $S$.
\item[(ii)] Let $R$ be an derived $\FF_p$-algebra and let $R'$ and $S$ be animated commutative $R$-algebras. If $S$ is relatively perfect over $R$, then $S'=S\otimes^L_R R'$ is relatively perfect over $R'$.
%\item[(iii)] Let $R$ be an animated commutative $\FF_p$-algebra and let $S$ and $T$ be animated commutative $R$-algebras. If $S$ and $T$ are relatively perfect over $R$, then $S\otimes^L_R T$ is also relatively perfect over $R$. 
\end{enumerate}
\end{lem}

The following two statements are direct analogues of Lemmas 3.16 and 3.18 in the work of Bhatt and Scholze \citep{BS17}.

\begin{prop}
\label{prop:rel_perf_tor-ind}
Let $R$ be a derived $\FF_p$-algebra with flat absolute Frobenius map. If both $S$ and $T$ are relatively perfect $R$-algebras, then $S\otimes_R^L T$ is coconnective. In particular, if $R$, $S$ and $T$ are discrete, then 
\[
S\otimes_R^L T \simeq S\otimes_R T.
\]
\end{prop}
\begin{proof}
By Lemma \ref{lem:relative_perfect_basic_properties_der}, the derived tensor product $S\otimes_R^LT$ is relatively perfect over $R$ and hence coconnective by Lemma \ref{lem:flat_frobenius_implies_coconnective}. If $R$, $S$ and $T$ are discrete, then the tensor product is both connective and coconnective, and is therefore discrete.
\end{proof}

\begin{cor}
\label{cor:perfect_base-change_der}
Let $Y$ be a discrete $\FF_p$-scheme with a flat Frobenius endomorphism, and consider the following pullback square of (discrete) $\FF_p$-schemes.
\[
\begin{tikzcd}
{X'} \arrow[r, "g'"] \arrow[d, "f'"] & {X} \arrow[d, "f"] \\
{Y'} \arrow[r, "g"]           & {Y}          
\end{tikzcd}
\]
If $X$ and $Y'$ are relatively perfect over $Y$ then, for any $K\in D_{\operatorname{qc}}(X)$, the base change morphism
\[
Lg^*Rf_*K\to Rf'_*L{g'}^*K
\]
is an isomorphism in $D_{\operatorname{qc}}(Y')$.
\end{cor}
\begin{proof}
Similarly as Lemma 3.18 is deduced from Lemma 3.16 in \citep{BS17}, the statement here reduces to the preceding Tor-independence result.
\end{proof}

The following result shows that the cotangent complex of a relatively perfect map of animated rings vanishes. We note that a similar result appears in \citep[Corollary 3.8]{Bha12}, where Bhatt proves the vanishing of the cotangent complex for relatively perfect maps in the setting of simplicial commutative rings. In \citep[Proposition 5.13]{Sch12} Scholze proves it for discrete rings.

\begin{prop}
\label{prop:cotangent_rel_perf_animated}
Let $R\to S$ be a map of animated commutative $\FF_p$-algebras. If $S$ is relatively perfect over $R$, then $L_{S/R}$ is acyclic.
\end{prop}
\begin{proof}
The cotangent complex of an equivalence is acyclic. Consequently, the proposition follows from Lemma \ref{lem:cotangent_relative_frobenius}.
\end{proof}

