\subsection{\textit{F-finiteness}}
We next consider \textit{F}-finite maps of animated $\FF_p$-algebras and examine their relation to relatively semiperfect maps.



\begin{defi}
\label{def:rel_f-finite_der}
A map $R\to S$ of animated $\FF_p$-algebras is called \emph{\textit{F}-finite} if the relative Frobenius map $F_{S/R}$ is finite on $H^0$. In this case, we also say that \emph{$S$ is a relatively \textit{F}-finite $R$-algebra}. When $R = \FF_p$, we simply say that \emph{$S$ is \textit{F}-finite}.
\end{defi}


\begin{ex}
If $R\to S$ is of finite type on $H^0$ then $S$ is relatively \textit{F}-finite over $R$.
\end{ex}


The next lemma follows directly from Remark \ref{rem:basic_properties_general_der}. It is also closely related to Lemma 2 in Hashimoto’s paper \citep{Has15}, as our notions of semiperfectness and \textit{F}-finiteness are defined entirely in terms of $H^0$.

\begin{lem}
\label{lem:basic_properties_P_der}
Let $P\in\{$relatively semiperfect, \textit{F}-finite$\}$. For maps of animated $\FF_p$-algebras, the following statements hold:
\begin{enumerate}
\item If both $A\to B$ and $A\to C$ satisfy $P$, then so does the composition. Moreover, if $A \to C$ satisfies $P$, then so does $B \to C$.
\item If $A \to B$ satisfies $P$, then for any map $A \to A^\prime$, the base change $A^\prime \to A^\prime \otimes^L_A B$ also satisfies $P$.
\item If both $A\to B$ and $A\to C$ satisfy $P$, then $A\to B\otimes^L_{A}C$ also satisfies $P$.
\end{enumerate}
\end{lem}

\begin{ex}
\label{ex:maps_of_semiperf_and_f-fin_der}
If $R \to S$ is a map of animated $\mathbb{F}_p$-algebras and $S$ is semiperfect (resp. \textit{F}-finite), then the map is relatively semiperfect (resp. relatively \textit{F}-finite).
\end{ex}

\begin{ex}
Let $R\to S$ be a map of animated $\FF_p$-algebras. If $S$ is relatively \textit{F}-finite over $R$, then any $S$-algebra of finite type is relatively \textit{F}-finite over $R$. This follows from Lemma \ref{lem:basic_properties_P_der} and the fact that $\FF_p[x]$ is \textit{F}-finite. 
\end{ex}

The following lemma relates relative semiperfectness to the vanishing of the degree-zero cohomology of the cotangent complex.

\begin{lem}
\label{lem:cotangent_semiperfect_der}
Let $R\to S$ be a map of animated $\FF_p$-algebras. If $S$ is relatively semiperfect over $R$, then $L_{S/R}$ is cohomologically $-1$-connective. 

Moreover, if $R\to S$ is \textit{F}-finite, then $S$ is relatively semiperfect over $R$ if and only if the module of Kähler differentials $\Omega_{H^0S/H^0R}\cong H^0(L_{S/R})$ vanishes.
\end{lem}
\begin{proof}
If $F_{S/R}$ is surjective on $H^0$, then $L_{F_{S/R}}$ is cohomologically $-1$-connective by \citep[Corollary 25.3.6.4]{Lur18}. Therefore,
\[
H^0(L_{S/R})=H^0(L_{F_{S/R}})=0
\]
by Lemma \ref{lem:cotangent_relative_frobenius}.

Now, suppose that $R\to S$ is \textit{F}-finite and that $L_{S/R}$ is $-1$-connective. Let $A= H^0(R)$ and $B=H^0(S)$. We have to show $B^p[A]=B$. Since 
\[
\Omega_{B/B^p[A]} \cong \Omega_{B/A} = 0,
\]
this follows from \citep[Corollaire 21.1.6]{EGAIV}.
\end{proof}

Analogous to a finite type map, an \textit{F}-finite map admits a factorization into a finite type free followed by an “\textit{F}-surjective” map. %This fact provides a structural foundation for the factorization of maps between \textit{F}-finite Noetherian $\FF_p$-algebras, as proven in \citep{BF25}. 

\begin{lem}
\label{lem:f-finite_smooth_f-surjective}
Let $R\to S$ be an \textit{F}-finite map of animated $\FF_p$-algebras. Then there exists an integer $n \ge 0$ and a factorization
\[
R \to R[x_1,\dots, x_n] \to S,
\]
where the first map is free of finite type and the second is relatively semiperfect.
\end{lem}
\begin{proof}
Let $A=H^0(R)$ and $B=H^0(S)$. If $S$ is relatively \textit{F}-finite over $R$, then there exist finitely many elements $s_1, \dots, s_n \in B$ that generate $B$ as a $B^p[A]$-algebra. These elements define a map from a free $R$-algebra $R[x_1,\dots, x_n]$ to $S$, which is relatively semiperfect since 
\[
B^p[H^0(R[x_1,\dots,x_n])]=B^p[A,s_1,\dots,s_n]=H^0(S).
\]
\end{proof}

If the base field in the following proposition is perfect, then the result is due to Kunz; see \citep[Proposition 1.1]{Kun76}.

\begin{prop}
Let $k$ be field of characteristic $p$, and let $R$ be a discrete Noetherian $k$-algebra such that the field extensions $k \to R/m$ are separable for all maximal ideals $m \subset R$. If $R$ is relatively $F$-finite over $k$, then $R$ has finite Krull dimension. More precisely, if $k[x_1,\dots,x_n] \to R$ is a relatively semiperfect map of $k$-algebras for some $n \ge 0$, then the Krull dimension of $R$ is at most~$n$.
\end{prop}
\begin{proof}
Since localizations are relatively perfect, we may assume that $(R,m)$ is a local ring such that the field extension $k\into K=R/m$ is separable. The canonical fiber sequence $L_{R/k}\otimes^L_R K \to L_{K/k} \to L_{K/R}$ induces an exact sequence of $K$-vector spaces
\[
H^{-1}(L_{K/k})\to H^{-1}(L_{K/R})\to \Omega_{R/k}\otimes_R K \to \Omega_{K/k} \to \Omega_{K/R} \to 0.
\]
Since $k\into K$ is separable—or equivalently, formally smooth by \cite[\href{https://stacks.math.columbia.edu/tag/0321}{Lemma 0321}]{stacks-project}—we have $H^{-1}(L_{K/k})=0$ by \cite[\href{https://stacks.math.columbia.edu/tag/031J}{Proposition 031J}]{stacks-project}. Furthermore, as $R\to K$ is surjective, we have $\Omega_{K/R}=0$ and $H^{-1}(L_{K/R})=m/m^2$. Hence, we have a short exact sequence
\[
0\to m/m^2 \to \Omega_{R/k} \otimes_R K \to \Omega_{K/k} \to 0
\]
which shows $\dim(R) \le \dim_K (m/m^2) \le \dim_K (\Omega_{R/k} \otimes_R K)$. Moreover, since $k[x_1,\dots, x_n]\to R$ is relatively semiperfect, the cotangent complex $L_{R/k[x_1,\dots, x_n]}$ is cohomologically $-1$-connective. Hence, the long exact cohomology sequence associated to
\[
L_{k[x_1,\dots, x_n]/k}\otimes^L_{k[x_1,\dots, x_n]}R
\to 
L_{R/k}
\to
L_{R/k[x_1,\dots, x_n]}
\]
shows that $R^n\cong \Omega_{k[x_1,\dots, x_n]/k}\otimes_{k[x_1,\dots, x_n]}R \to \Omega_{R/k}$ is surjective. Consequently, we have
\[
\dim_K (\Omega_{R/k} \otimes_R K)\le n.
\]
\end{proof}

\begin{ex}
\label{ex:gabbers_construction_der}
Let $S$ be a discrete \textit{F}-finite $\FF_p$-algebra, and let  $R=\FF_p[x_1,\dots,x_n]\to S$ be a relatively semiperfect map. Denote by $s_i$ the image of $x_i$ under this map. Then, for all $k\ge0$, we obtain commutative diagrams 
