\begin{prop}
\label{prop:perfection_is_Noetherian_der}
Let $R$ be a regular Noetherian \textit{F}-finite $\FF_p$-algebra, and let $R\to S$ be a relatively semiperfect map to an \textit{F}-finite animated $\FF_p$-algebra. If $H^0(S)$ is Noetherian, then $S^{\perfection/R}$ is regular Noetherian.
\end{prop}
\begin{proof}
By Lemma~\ref{lem:perfection_sees_only_H0_flat}, we may assume that $S$ is discrete. By Kunz’s theorem \citep[Theorem 2.1]{Kun69}, it suffices to show that $S^{\perfection/R}$ is Noetherian.

Let $n\ge0$, and let $A=\FF_p[x_1,\dots,x_n]\to R$ be a relatively semiperfect map. By Example~\ref{ex:gabbers_construction_der} and \citep[Remark 13.6]{Gab04}, the relatively perfect $A$-algebras $R^{\perfection/A}$ and $S^{\perfection/A}$ are regular Noetherian.

The map $R^{\perfection/A}\to S^{\perfection/A}$ is relatively perfect by Lemma \ref{lem:relative_perfect_basic_properties_der}, hence flat by \citep[Proposition 5.2]{Kat86}. Moreover, by Lemma \ref{lem:connective_surjective_der}, the map $R^{\perfection/A}\to R$ is surjective. Hence,
\[
S^{\perfection/A}\otimes_{R^{\perfection/A}} R\simeq S^{\perfection/A}\otimes^L_{R^{\perfection/A}} R
\]
is a discrete Noetherian $\FF_p$-algebra. Furthermore, as $R^{\perfection/A}$ is regular, $R\in D(R^{\perfection/A})$ is a perfect complex, so $-\otimes^L_{R^{\perfection/A}} R$ preserves limits. This yields the following canonical equivalences:
\begin{align*}
S^{\perfection/A}\otimes^L_{R^{\perfection/A}} R 
&\simeq 
S^{\perfection/R^{\perfection/A}}\otimes^L_{R^{\perfection/A}} R
\simeq 
(S\otimes^L_{R} R \otimes^L_{R^{\perfection/A}}R)^{\perfection/R} \\
&\simeq 
(H^0(S\otimes^L_{R} R \otimes^L_{R^{\perfection/A}}R))^{\perfection/R}
\simeq 
S^{\perfection/R}.
\end{align*}
Here, the first equivalence follows from Lemma \ref{lem:independence_of_base}, the second from the discussion above, and the third from Lemma \ref{lem:perfection_sees_only_H0_flat}.
\end{proof}


The following proposition can also be deduced from  \citep[Theorem 6.6.4.1]{Lur18} and \citep[Remark 13.6]{Gab04}.

\begin{prop}
\label{prop:dual_complex}
Noetherian\footnote{An animated ring $R$ is called \emph{Noetherian} if $H^0(R)$ has the same property and $H^k(R)$ is a finitely generated $H^0(R)$ module for all $k\le 0$.} \textit{F}-finite animated rings admit dualizing complexes.
\end{prop}
\begin{proof}
Let $S$ be a Noetherian \textit{F}-finite animated ring, and choose a relatively semiperfect map $R=\FF_p[x_1,\dots,x_n] \to S$. By Proposition \ref{prop:perfection_is_Noetherian_der}, $S^{\perfection/R}$ is regular Noetherian. The cohomology groups of $S$ are finitely generated over $H^0(S)$ and therefore also over $S^{\perfection/R}$. This shows that $S$ is an almost-perfect $S^{\perfection/R}$-module; see \citep[Proposition 7.2.4.17]{Lur17}. Now, if $\omega_{S^{\perfection/R}}^{\bullet}$ is a dualizing complex over $S^{\perfection/R}$, then $\Hom_T(S,\omega_T^{\bullet})$ is a dualizing complex over $S$ by \citep[Corollary 6.6.3.3]{Lur18}.
\end{proof}


\section{Factoring Maps of F-finite Animated Rings}
\label{sec:factorization}
In this section, we analyze how maps between \textit{F}-finite animated $\FF_p$-algebras can be decomposed into simpler maps. As a first step, we consider the case of relatively semiperfect maps.

\begin{con}
\label{con:factorization_f-surjective_map_der}
Let $R\to S$ be a relatively semiperfect map of \textit{F}-finite animated $\FF_p$-algebras. We choose a free $\FF_p$-algebra of finite type along with a relatively semiperfect map
\[
A=\FF_p[x_1,\dots,x_n] \to R
\]
for some $n\ge0$. Then $R\to S$ becomes a map in $\sperf{A}$.
Since $F_*A$ is a finite free $A$-module, the relative inverse limit perfection over $A$ is relatively perfect and thus
$R^{\perfection/A}\to S^{\perfection/A}$ is a map in $\perf{A}$. The counit $\varepsilon$ of the adjunction from Proposition \ref{prop:right_adjoint_animated} yields the following commutative diagram in the category $\sperf{A}$:
\[
\begin{tikzcd}
{R^{\perfection/A}} \arrow[r] \arrow[d, "\varepsilon_R"] & {S^{\perfection/A}} \arrow[d, "\varepsilon_S"] \\
{R} \arrow[r]           & {S}          
\end{tikzcd}
\]
This yields a factorization of the map $R\to S$:
\[
R \to R\otimes^L_{R^{\perfection/A}}S^{\perfection/A} \to S.
\]
The first of these maps is relatively perfect, and the second is surjective on $H^0$. Indeed, since $R^{\perfection/A}\to S^{\perfection/A}$ is a map in $\perf{A}$, both the map itself and its base-change are relatively perfect by Lemma \ref{lem:relative_perfect_basic_properties_der}. Moreover, the second map is surjective on $H^0$, as the same holds for $S^{\perfection/A}\to S$ by Lemma~\ref{lem:connective_surjective_der}.
\end{con}

%\begin{q}
%\textcolor{red}{Does this factorization depend on the $p$-generating set of $R$? If not, does this construction then serve as a right adjoint?}
%\end{q}


\begin{lem}
\label{lem:f-srujective_factorization_der}
Let $R\to S$ be a relatively semiperfect map of \textit{F}-finite  animated $\FF_p$-algebras. Construction \ref{con:factorization_f-surjective_map_der} gives a factorization
\[
R \to T \to S
\]
such that $T$ is relatively perfect over $R$, and the second map is surjective on $H^0$. Moreover, we have:
\begin{enumerate}
\item[(i)] If $H^0(R)$ is Noetherian and $R$ is $n$-coconnective, then $T$ is also $n$-coconnective.
\item[(ii)] If both $R$ and $H^0(S)$ are Noetherian, then $T$ is Noetherian as well.
\end{enumerate}
\end{lem}
\begin{proof}
We use the same notation as in Construction \ref{con:factorization_f-surjective_map_der}. If $H^0(R)$ is Noetherian, then $R^{\perfection/A}$ is also Noetherian by Proposition \ref{prop:perfection_is_Noetherian_der} and therefore regular. Hence, by \citep[Proposition 5.2]{Kat86}, $S^{\perfection/A}$ is flat over $R^{\perfection/A}$, which implies that $T=R\otimes^L_{R^{\perfection/A}}S^{\perfection/A}$ is flat over $R$. 
Consequently, %as explained in \citep[\S 5.2.1]{CS24}, 
we obtain canonical isomorphisms for all $k\le 0$:
\[
H^k(T)
\cong 
H^k(R)\otimes_{R^{\perfection/A}} S^{\perfection/A} 
\cong 
H^k(R)\otimes_{H^0(R)} H^0(T).
\]
The first isomorphism establishes statement (i). Now, assume that $R$ and $H^0(S)$ are Noetherian. By the same arguments as above, $S^{\perfection/A}$ is Noetherian. Therefore, by the first isomorphism, $H^0(T)$ is a quotient of a Noetherian ring. The second isomorphism shows, that the negative cohomology groups of $T$ are finitely generated over $H^0(T)$, as the same holds for $R$ by assumption.
\end{proof}

By Proposition \ref{prop:cotangent_rel_perf_animated}, the cotangent complex of any relatively perfect map is acyclic. For maps of Noetherian \textit{F}-finite rings, the converse also holds. 

%this partially answers a question of bhatt.

\begin{thm}
\label{thm:acyclic_cotanget_implies_rel_perf}
Let $ R \to S $ be a map of Noetherian $ F $-finite rings. If $ L_{S/R} \simeq 0 $, then $ S $ is relatively perfect over $ R $.
\end{thm}
\begin{proof}
By assumption, $\Omega_{S/R}=0$, so $S$ is relatively semiperfect over $R$ by Lemma  \ref{lem:cotangent_semiperfect_der}. The previous lemma now yields a factorization
\[
R\to T \to S,
\]
where $T$ is Noetherian, the map $R\to T$ is relatively perfect, and the map $T\to S$ is surjective. It suffices to show that $S$ is relatively perfect over $T$. 

The canonical triangle of cotangent complexes shows that $L_{S/T}\simeq 0$, as both $L_{S/R}$ and $L_{T/R}$ vanish by assumption and by Proposition~\ref{prop:cotangent_rel_perf_animated}, respectively. In particular, $T\to S$ is \'etale and thus relatively perfect by \cite[\href{https://stacks.math.columbia.edu/tag/0EBS}{Lemma 0EBS}]{stacks-project}. 
