\begin{cor}
Let $R$ be a discrete Noetherian \textit{F}-finite ring and $I \subset R$ an ideal. Then the $I$-adic completion $R^{\wedge}_I$ is a relatively perfect $R$-algebra. In other words, the discrete relative inverse limit perfection of $R/I$ over $R$ is relatively perfect.
\end{cor}
\begin{proof}
By \citep[Proposition 3.11]{BF25}, the cotangent complex of the natural map $R\to R^{\wedge}_I$ vanishes. Thus, by Theorem~\ref{thm:acyclic_cotanget_implies_rel_perf}, the map is relatively perfect.
\end{proof}


The following corollary shows, for instance, that a Noetherian $F$-finite $\FF_p$-algebra is regular with a $p$-basis in the sense of \citep[Définition 21.1.9]{EGAIV} if and only if it is relatively perfect over polynomial ring over $\FF_p$ in finitely many variables.

\begin{cor}
\label{cor:p-basis}
Let $R\to S$ be a map of discrete Noetherian \textit{F}-finite rings. Then $S$ admits a $p$-basis of length $n\ge0$ over $R$, and $L_{S/R}\simeq \Omega^1_{S/R}[0]$, if and only if $S$ is relatively perfect over a polynomial $R$-algebra in $n$ variables.
\end{cor}
\begin{proof}
The "if" direction follows from Proposition \ref{prop:cotangent_rel_perf_animated} since the cotangent complex of a polynomial algebra is concentrated in degree $0$, and the variables form a $p$-basis. Conversely, 
let ${s_1,\dots,s_n}$ be a $p$-basis of $S$ over $R$ and define a map $R[x_1,\dots,x_n] \to S$ by sending each free variable $x_i$ to $s_i$. Since, by \citep[Corollaire 21.2.5]{EGAIV}, any $p$-basis is also a differential basis, the induced map $L_{R[x_1,\dots,x_n]/R}\otimes^L_{R[x_1,\dots,x_n]}S \to L_{S/R}$ is an equivalence. Therefore, the canonical fiber sequence of cotangent complexes associated with $R\to R[x_1,\dots,x_n] \to S$ shows that $L_{S/R[x_1,\dots,x_n]}$ vanishes. By Theorem \ref{thm:acyclic_cotanget_implies_rel_perf}, this implies that $S$ is relatively perfect over $R[x_1,\dots,x_n]$.
\end{proof}

For a formally smooth map of locally Noetherian $F$-finite $\FF_p$-schemes we obtain a factorization result similar to \cite[\href{https://stacks.math.columbia.edu/tag/039Q}{Theorem 039Q}]{stacks-project}.

\begin{cor}
\label{cor:factorizationofschemes}
Let $f:X\to Y$ be a formally smooth morphism of locally Noetherian $F$-finite schemes. Then for any $x\in X$ and any affine open neighborhood $V\subset Y$ of $f(x)$, there exists an integer $n\ge0$, an affine open neighborhood $U$ of $x$ with $f(U)\subset V$, and a commutative diagram
\[
\begin{tikzcd}
X \arrow[d] & U \arrow[l] \arrow[d] \arrow[r, "g"] & \mathbf{A}^n_V \arrow[d]                \\
Y           & V \arrow[l]                     & V \arrow[l, equal]
\end{tikzcd}
\]
in which $g$ is formally \'etale.
\end{cor}
\begin{proof}
Let $x\in X$, and let $V\subset Y$ an affine open neighborhood of $f(x)$. By choosing an affine open subscheme $W\subset X$ containing $x$ with $f(W)\subset V$, we may reduce to the case where $X$ and $Y$ are affine; see \cite[\href{https://stacks.math.columbia.edu/tag/02H3}{Lemma 02H3}]{stacks-project}. In this case, $f$ corresponds to a formally smooth map $R \to S$ of Noetherian \textit{F}-finite $\mathbb{F}_p$-algebras. By \citep[Proposition 2.15]{BF25}, the cotangent complex $L_{S/R}$ is concentrated in degree zero and $\Omega_{S/R}$ is a finite projective $S$-module. In particular, $\Omega_{S/R}\otimes_{S}\kappa(x)$ is an $n$-dimensional $\kappa(x)$-vector space for some integer $n\ge 0$. Let $d(s_1),\dots, d(s_n)\in \Omega_{S/R}$ be elements whose images under the canonical map form a basis of this vector space. These elements induce a map $S^n\to \Omega_{S/R}$ which becomes an isomorphism on some standard open neighborhood $U=D(a)$ of $x$:
\[
S^n_a \to[\cong] (\Omega_{S/R})_a \cong \Omega_{S_a/R}.
\]
Thus, $S_a$ admits a differential basis over $R$. Since, by \citep[Theorem 1]{Tyc88}, a differential basis of Noetherian \textit{F}-finite rings is also a $p$-basis, the claim follows from the previous corollary.
\end{proof}

Applying Lemma \ref{lem:f-srujective_factorization_der}, we obtain the following result, showing that any map of \textit{F}-finite animated rings admits a free-by-surjective factorization up to a relatively perfect map.

\begin{thm}
\label{thm:F-finite_factorization_der}
Let $R \to S$ be a map of \textit{F}-finite animated $\FF_p$-algebras, and let $R\to R^{\prime} \to S$ be a factorization through a free $R$-algebra of finite type such that the second map is relatively semiperfect. Applying \ref{con:factorization_f-surjective_map_der} to the relatively semiperfect map yields a factorization
\[
R \to R^{\prime} \to T \to S
\]
where the first map is free of finite type, the second map is relatively perfect and the third map is surjective on $H^0$. Moreover:
\begin{enumerate}
\item[(i)] If $H^0(R)$ is Noetherian and $R$ is $n$-coconnective, then both $R'$ and $T$ are $n$-coconnective.
\item[(ii)] If both $R$ and $H^0(S)$ are Noetherian, then all animated rings appearing in the factorization are Noetherian.
\end{enumerate}
\end{thm}
\begin{proof}
Since $R^{\prime}$  is flat over $R$ it is $n$-coconnective whenever $R$ is $n$-coconnective. By Hilbert's basis theorem, $H^0(R^{\prime})$ is Noetherian if $H^0(R)$ has this property. Moreover, if $R$ is Noetherian, the flatness of $R^{\prime}$ over $R$ ensures that $R^{\prime}$ is Noetherian as well. Thus, the conclusion follows directly from Lemma \ref{lem:f-srujective_factorization_der} applied to $R^{\prime}\to S$.
\end{proof}

In the case where the rings are Noetherian and discrete, the following provides a new proof of \citep[Theorem 4.4]{BF25}.


\begin{cor}
\label{cor:factorization_discrete_der}
Let $R\to S$ be a homomorphism of ordinary \textit{F}-finite $\FF_p$-algebras. Theorem \ref{thm:F-finite_factorization_der} gives a factorization
\[
R \to R' \to T \to S
\]
where the first map is free of finite type, the second map is relatively perfect and the third map is surjective. If $R$ is Noetherian, then $T$ is discrete, and if both $R$ and $S$ are Noetherian, then $T$ is Noetherian as well.
\end{cor}
\begin{proof}
This follows from the previous theorem: If $R$ is Noetherian and discrete, then every ring in the factorization is discrete. Moreover, if both $R$ and $S$ are Noetherian, then all rings in the factorization are Noetherian as well.
\end{proof}

\begin{rem}
\label{rem:final_remark}
If $R$ in the previous corollary is non-Noetherian, the animated ring $T$ may not be discrete; see Construction \ref{con:factorization_f-surjective_map_der}. Nevertheless, we still obtain a factorization of classical rings
\[
R \to R^{\prime} \to H^0(T) \to S,
\]
and the discrete relative Frobenius of $H^0(T)$ over $R^{\prime}$ is an isomorphism. In particular, $H^0(T)$ is formally \'etale over $R^{\prime}$ by \citep[Théorème 21.2.7]{EGAIV}.

However, by the first part of Lemma~\ref{lem:relative_perfect_basic_properties_der} and  Corollary \ref{cor:equivalence_animated}, the map $R^{\prime} \to H^0(T)$ is not relatively perfect  in the sense of our definition unless $T$ itself is discrete; see also Remark \ref{rem:tor_independence_relative_perfect_der}.
\end{rem}

