\section{Multivariate diam mean equicontinuity and multivariate regularity}\label{sec:4}
The following result relates diam mean $m$-equicontinuity and $m$-regularity.
In Section~\ref{WeaklyMeanSensitiveTuples}, we also prove the converse under the
assumption of a local Bronstein condition. 
In the abelian case, the same results
have been established in \cite{Lino2025}. 
\begin{thm}\label{thm:regular m to one=>m-equi}
	Let $(X,G)$ be a minimal \tds. If $\pi_{\eq}$ is regular $m$-to-one, then $(X,G)$
	is diam-mean $(m+1)$-equicontinuous.
\end{thm}
\begin{proof}
By the above, we only need to prove that any $x\in X$ is a diam-mean
$m$-equicontinuous point. For convenience, we assume without loss of generality
that $\diam(X)=1$.

For any $\varepsilon>0$, since $\pi_{\eq}$ is $m$-regular, we can choose a
compact subset $K$ of $X_{\eq}$ with $\mu_{\eq}(K)>1-\varepsilon/3$ and
$|\pi_{\eq}^{-1}(y)|=m$ for any $y\in K$. Since $\pi_{\eq}^{-1}$ is upper
semi-continuous, there exists $\delta>0$ and $z_1,\ldots z_l\in K$ such that
$K\subset \cup_{i=1}^lB(z_i,\delta)$ and $\pi_{\eq}^{-1}(B(z_i,2\delta))\subset
B(\pi_{\eq}^{-1}({z_i}),\varepsilon/3)$. Now we choose $\eta>0$ such that
$\mathrm{diam}(\pi_{\eq}(B(x,\eta)))<\delta$ holds for any $x\in X$. Notice that
for any $x\in X$, if $g\in G$ such that $g\pi_{\eq}(x)=\pi_{\eq}(gx)\in K$,
there exists $j\in\{1,2,\ldots,l\}$ such that $\pi_{\eq}(gx)\in
B(z_i,\delta)$. Since
$\mathrm{diam}(g\pi_{\eq}(B(x,\eta)))=\mathrm{diam}(\pi_{\eq}(B(x,\eta)))<\delta$,
it follows that $\pi_{\eq}(gB(x,\eta))\subset B(z_i,2\delta),$. This further
implies that
\[
gB(x,\eta)\ \subset\ \pi_{\eq}^{-1}( B(z_i,2\delta)) \ \subset
\ B(\pi_{\eq}^{-1}({z_i}),\varepsilon/3) \ .
\]
As $|\pi^{-1}(z_i)|=m$, it follows that $\diam_{m+1}(gB(x,\eta))<2\varepsilon/3$. Thus,
we deduce that
\begin{eqnarray} \nonumber
	\lefteqn{\limsup_{n\to\infty}\frac{1}{|\cF_n|}\sum_{g\in
            \cF_n}\operatorname{Diam}_{m+1}(gB(x,\eta))}\\ &= & \label{eq:14}
        \limsup_{n\to\infty}\frac{1}{|\cF_n|}\left(\sum_{g\in \cF_n,\pi(gx)\in
          K}\operatorname{Diam}_{m+1}(gB(x,\eta))+\sum_{g\in \cF_n,\pi(gx)\notin
          K}\operatorname{Diam}_{m+1}(gB(x,\eta))\right)\\ &= &
        \frac{2\varepsilon}{3}\cdot \nonumber
        \limsup_{n\to\infty}\frac{1}{|\cF_n|}\left|\left\{g\in \cF_n:g\pi(x)\in
        K\right\}\right| \\ & & + \ \diam(X)\cdot
        \limsup_{n\to\infty}\frac{1}{|\cF_n|}\left|\left\{g\in \cF_n:g\pi(x)\notin
        K\right\}\right| \ .\nonumber
\end{eqnarray}
Since $(X_{\eq},G)$ is uniquely ergodic, by the Birkhoff Ergodic Theorem (by
Lindenstrauss \cite{L01}), for any tempered \Folner sequence
$\F=\{\cF_n\}_{n\in\N}$, \eqref{eq:14} implies that
\[\limsup_{n\to\infty}\frac{1}{|\cF_n|}\sum_{g\in \cF_n}\operatorname{Diam}_{m+1}(gB(x,\eta))
\le 2\varepsilon\cdot\mu_{\eq}(K)+(1-\mu_{\eq}(K))<\varepsilon \ . \] As any \Folner
sequence has a tempered \Folner subsequence \cite{L01}, this completes the
proof.
	\end{proof}

We now turn to the notion of diam mean sensitivity.

\begin{prop}\label{prop:transitive ponit}
Let $(X,T)$ be a \tds with a transitive point $x$. If $x$ is diam-mean
$m$-sensitive then $(X,T)$ is diam-mean $m$-sensitive.
\end{prop}
\begin{proof}
Since $x$ is diam-mean $m$-sensitive, there exists $\varepsilon>0$ such that for any
open neighborhood $U$ of $x$,
\[
\sup_{\cF}\limsup_{n\to\infty}\frac{1}{|\cF_n|}\sum_{g\in
  \cF_n}\operatorname{Diam}_m(g(U)) \ \geq \ \varepsilon \ .
\]
Fix a nonempty open subset $V$ of $X$. As $x$ is transitive, there exists $h\in
G$ such that $hx\in V$. By continuity of $h$, we can find an open neighborhood
$U$ of $x$ such that $hU\subset V$. Thus, we have
\begin{align*}
	\sup_{\cF} \limsup_{n\to\infty}\frac{1}{|\cF_n|}\sum_{g\in
          \cF_n}\operatorname{Diam}_m(g(V)) \ \ge
        \ \sup_{\cF}\limsup_{n\to\infty}\frac{1}{|\cF_nh|}\sum_{g\in
          \cF_nh}\operatorname{Diam}_m(g(U)) \ > \ \varepsilon.
\end{align*}
\end{proof}


