\section{Weakly mean sensitive tuples}\label{WeaklyMeanSensitiveTuples}

\subsection{Multivariate diam mean sensitivity and weakly mean sensitive tuples}
\label{MDiamMeanSensitivityAndTuples}

Following ideas in \cite[Theorem 4.4]{LiYeYu2022Equiinthemean}, we first prove
the following result.
\begin{thm}\label{lem:wealy tuple vs diammean sensitive}
Let $(X,G)$ be a \tds and $m\in\N$. If $\xg$ has an essential weakly
mean-sensitive $m$-tuple, then $(X,G)$ is diam-mean $m$-sensitive. If we further
assume that $\xg$ is transitive, then the converse direction also holds.
\end{thm}
\begin{proof}
First, we assume that $(x_1,\ldots,x_{m})$ is an essential weakly mean-sensitive
$m$-tuple. Let $\delta:=\frac{1}{2}\min_{1\le i< j\le m}d(x_i,x_j)$. We choose a
neighborhood $U_k$ of $x_k$ for each $k\in\{1,2\cdots,m\}$ such
that
\begin{equation}\label{eq1}
  \min_{1\le i< j\le m}d(U_i,U_j)>\delta.
\end{equation}
Then there exists $\eta>0$ such that for any open subset $U$ of
$X$, $$\uBD(\{g\in G: (gU)\cap U_k\neq\emptyset\text{ for }1\le k\le
m\})>\eta.$$ Let
\[
\mathcal{N}:=\{g\in G: (gU)\cap U_k\neq\emptyset\text{ for }1\le k\le m\}.
\]
Then it is easy to see that for any $g\in\mathcal{N}$, $\diam_m(g(U))>\delta.$
Thus,
\[
\sup_{\cF}\limsup_{n\to\infty}\frac{1}{|\cF_n|}\sum_{g\in
  \cF_n}\operatorname{Diam}_m(g(U))\ >\ \delta\eta\ .
\]
Therefore, $\xg$ is diam-mean $m$-sensitive with constant
$\varepsilon=\delta\eta$. \medskip

In order to prove the converse, we suppose that $\xg$ is a transitive diam-mean
$m$-sensitive \tds. Then one can show by elementary arguments that there exists
$\varepsilon>0$ such that for any nonempty open set $U$ of $X$, there exists a
subset $F$ of $G$ with $\uBD(F)\geq\varepsilon$ such that for any $g\in
F$,
\[\diam_m(g(U))\ \geq \ \varepsilon\ .\]
This implies that for any $k\in F$ there exist $x_1^k,\ldots,x_{m}^k\in U$ such
that
\begin{equation}\label{eq:123}
	\min_{1\le i< j\le m}d(kx^k_i,kx^k_j)\ge \varepsilon.
\end{equation}

Put
\[
X^{m}_\varepsilon\ := \ \{(x_1,\ldots,x_{m})\in X^{m}:\min_{1\le i< j\le
  m}d(x_i,x_j)\ge \varepsilon\}\ .
\]
Then $X^{m}_\varepsilon$ is a compact subset of $X^{m}$. Fix a transitive point
$x\in X$ and set $W_n:=B(x,1/n)$ for each $n\in\N$. By \eqref{eq:123}, for each
$n\in\N$,
\[
\uBD(\{g\in G:(gW_n)^{m}\cap X_\varepsilon^{m}\neq
\emptyset\})\ \geq\ \varepsilon\ .
\]
Due to the compactness of $X^{m}_\varepsilon$, there exists a finite family of open
sets $\{A_i^1\}_{i=1}^{N_1}$ with $\diam(A_i^1)\le 1$ such that
\[
X^{m}_\varepsilon\ \subset\ \cup_{i=1}^{N_1}A_i^1\ .
\]
By the pigeonhole principle, we may assume that for any $n\in\N$, there exists
$p_n\in\{1,2,\ldots,N_1\}$ such that
\[
\uBD(\{g\in G:(gW_n)^{m}\cap A_{p_n}^1\cap X_\varepsilon^{m}\neq
\emptyset\})\geq\varepsilon/N_1.
\]
Since the sets $W_n$ are decreasing and $N_1<\infty$, we may choose the same $p_n$ for all $n\in \N$. We can thus assume
without loss of generality that $p_n=1$ for all $n\in\N$.

Repeating the produce above, for each $l\ge1$, we may assume that there exists
an open subset $A^l$ with $\diam(A^l)<1/l$ such that $A^l\subset A^{l-1}$ and
for all $n\in\N$,
\begin{equation}\label{eq:20.44}
	\uBD\left(\left\{g\in G:(gW_n)^{m}\cap A^l\cap
        X_\varepsilon^{m}\neq \emptyset\right\}\right)\ \geq
        \ \frac{\varepsilon}{N_1N_2\ldots N_l} \ .
\end{equation}

As $\lim_{l\to\infty}\diam(A^l)=0$, it is clear that $(\cap_{l=1}^\infty
A^l)\cap X_\varepsilon^{m}$ is a singleton, denoted by $(x_1,\ldots,x_{m})$. Now we
prove this point is a weakly mean-sensitive tuple. Indeed, for any family of
open neighborhoods $U_i$ of $x_i$, $i=1,2,\ldots,m$, there exists $l>0$ such
that $A^l\cap X_\varepsilon^{m}\subset U_1\times\ldots\times U_{m}$.  By
\eqref{eq:20.44}, for all $n\in\N$,
\[
\uBD\left(\left\{g\in G:(gW_n)^{m}\cap (U_1\times\ldots\times
U_{m})\neq \emptyset\right\}\right)\ \geq \ \frac{\varepsilon}{N_1N_2\ldots N_l}\ .
\]
For any open subset $U$ of $X$, as $x\in X$ is a transitive point, there exists
$h\in G$ such that $hx\in U$. By the continuity of $h$, we can choose $n\in\N$
large enough such that $hW_n\subset U$. Then we have
\begin{align*}
	\uBD\left(\left\{g\in G:(gU)\cap U_i\neq \emptyset,\text{ for
        }i=1,2,\ldots,m\right\}\right) \ \geq \ \frac{\varepsilon}{N_1N_2\ldots
          N_l}\ .
\end{align*}
This completes the proof.
\end{proof}

In order to prove a converse to Theorem~\ref{thm:regular m to one=>m-equi}, we
need an additional condition that is required in order to apply results from
\cite{LiuXuZhang2025}. We say that a \tds $\xg$ satisfies the {\em local
  Bronstein condition} if for any minimal point $(x,x')\in X\times X$ such that
$\pi_{\eq}(x)=\pi_{\eq}(x')$ there exists a sequence $((x_n,x_n'))_{n\in\N}$ of
minimal points in $X\times X$ and a sequence $(g_n)_{n\in\N}$ in $G$ such that
$\lim_{n\to\infty} (x_n,x_n')=(x,x')$ and $\lim_{n\to\infty} d(g_nx,g_nx')=0$.
Note that this is always satisfied if $(X,G)$ is a minimal action of an abelian
group (Lemma~\ref{lem:nilpotentimpliesbronstein}) The following statement now
summarises our findings combined with the respective results in
\cite{LiuXuZhang2025}.

\begin{thm}\label{thm:m to 1<=> tuple}
Suppose that $(X,G)$ is a minimal \tds that satisfies the local Bronstein
condition. Let $m\in \N$. Then the following
statements are equivalent:
\begin{enumerate}[(i)]
	\item  $\pi_{\eq}$ is regular $m$-to-one;
	\item there exists an essential weakly $m$-sensitive tuple and no
          essential weakly $(m+1)$-sensitive tuple;
	\item for  every $y\in X_{\eq}$, $\pi_{\eq}^{-1}(y)$ contains an
          essential weakly $m$-sensitive tuple and no essential weakly
          $(m+1)$-sensitive tuples;
          \item $(X,G)$ is diam-mean $(m+1)$-equicontinuous but not
                  diam-mean $m$-equicontinuous;

		\item $(X,G)$ is not diam-mean $(m+1)$-sensitive, but diam-mean
                  $m$-sensitive.
\end{enumerate}
\end{thm}
\begin{proof}
(i) $\Rightarrow$ (iii). The first statement has been proven in \cite[Corollary
    5.3]{LiuXuZhang2025} . Now, assume for a contradiction that there exists an
  essential weakly $(m+1)$-sensitive tuple. By Theorem~\ref{lem:wealy tuple vs
    diammean sensitive}, we know that $(X,G)$ is diam-mean
  $(m+1)$-sensitive. Hence Proposition \ref{prop:auslanderyorkediammean} implies
  that $(X,G)$ is not diam-mean $(m+1)$-equicontinuous. However, this
  contradicts Theorem \ref{thm:regular m to one=>m-equi}.

(iii) $\Rightarrow$ (ii) is trivial.

(ii) $\Rightarrow$ (i).  By Corollary 5.3 in \cite{LiuXuZhang2025}, as $(X,G)$
  has no essential weakly $(m+1)$-sensitive tuple, we know that $\pi_{\eq}$ is
  regular $m'$-to-one for some $0<m'\le m$. As $(X,G)$ has an essential weakly
  $m$-sensitive tuple, the fact that (i) $\Rightarrow$ (iii) yields $m'\geq
  m$. Therefore (i) holds.

(i) $\Rightarrow$ (iv) has been proven in Theorem \ref{thm:regular m to
  one=>m-equi}.

(iv) $\Leftrightarrow$ (v) holds by Proposition \ref{prop:auslanderyorkediammean}.

(v) $\Rightarrow$ (ii) finally follows from Theorem \ref{lem:wealy tuple vs
    diammean sensitive}.
   \end{proof}


\subsection{Strong $m$-spreading and mean sensitive tuples}
\label{Strong_m_spreading}

For the sake of completeness, we discuss in this section how strong
$m$-spreading may be characterised via suitable finite collections of weakly
mean sensitive tuples. However, due to the fact that the spreading must occur
along sets of full density, it turns out that this cannot be achieved by looking
at single tuples. Instead, finite collections of suitable tuples have to be
considered.

We call a \tds $\xg$ {\em strongly $(\varepsilon,m)$-spreading} for some
$\varepsilon>0$ and $m\in\N$ if
\[
\lBD\left(\left\{ g\in G\mid \diam_m(gU)
>\varepsilon\right\}\right) \ = \ 1 \
\]
holds for any open subset $U \subseteq X$. Note that $\xg$ is {\em strongly
  $m$-spreading} if it is strongly $(\varepsilon,m)$-spreading for some $\varepsilon
>0$. Recall that we defined
\[
D_m(x) \ = \ \min_{1\leq i < j\leq m} d(x_i,x_j) \ 
\]
and 
\[
X^m_{\varepsilon} \ = \ \left\{ x\in X^m\mid D_m(x) \geq \varepsilon\right\} .
\]
Now strong $m$-spreading can be characterised in the following way. 
\begin{lem}
  If $\xg$ is strongly $(\varepsilon,m)$-spreading, then for all $\delta>0$ there
  exists $N=N(\delta)\in\N$ and $x^{(1)},\ldots, x^{(N)}\in X^m_{\varepsilon}$ such
  that
  \begin{equation}\label{e.strong_spreading_tuples_1}
 \lBD\left(\left\{ g\in G \ \left|\ \exists k\in\{1,\ldots, N\} :
 gU\cap B\left(x^{(k)}_i,\delta\right)\neq \emptyset \textrm{ for } i=1,\ldots,
 m\right\}\right)\right. \ = \ 1 \ .
  \end{equation}
holds for all nonempty open sets $U\subseteq X$.
\end{lem}
\begin{proof}
  Note that if a set $V\subseteq X$ satisfies $\diam_m(V) >\varepsilon$, then $V^m$
  intersects $X^m_{\varepsilon}$. Hence, as $\xg$ is strongly
  $(\varepsilon,m)$-spreading, we have that
  \begin{equation} \label{e.strong_spreading_hyperspace}
  \lBD \left(\left\{ g\in G \mid g(U)^m\cap X^{m,\varepsilon}\neq
  \emptyset \right\}\right) \ = \ 1 \ .
  \end{equation}

  Now fix $\delta>0$. Due to compactness, there exists $N\in\N$ and
  $x^{(1)},\ldots, x^{(N)}\in X^m_{\varepsilon}$ such that the product
  neigbourhoods
  \[
  U\left(x^{(k)},\delta\right) \ = \ \bigotimes_{k=1}^m B\left(x^{(k)}_i,\delta\right)
  \]
  with $k=1,\ldots,N$ cover $X^m_{\varepsilon}$. As a consequence,
  (\ref{e.strong_spreading_hyperspace}) implies
  (\ref{e.strong_spreading_tuples_1}).
\end{proof}
Conversely, we have
\begin{lem}
  Suppose $\xg$ be a \tds and $\varepsilon>0$ and $\delta\in (0,\varepsilon/2)$. If
  there exists $N=N(\delta)\in\N$ and $x^{(1)},\ldots, x^{(N)}\in
  X^{m}_{\varepsilon}$ such that
  \[
   \lBD\left(\left\{ g\in G \ \left| \exists k\in\{1,\ldots, N\} :
   gU\cap B\left(x^{(k)}_i,\delta\right)\neq \emptyset \textrm{ for }
   i=1,\ldots, m\right\}\right)\right. \ = \ 1 \ ,
    \]
    holds for all nonempty open sets $U\subseteq X$, then $\xg$ is strongly
    $(\varepsilon-2\delta,m)$-spreading.
\end{lem}
\begin{proof}
  The statement follows directly from the observation that $x\in X^m_{\varepsilon}$
  and $V\cap B(x_i,\delta)\neq \emptyset$ for $i=1,\ldots,m$ implies $\diam_m(V)
  > \varepsilon-2\delta$.
\end{proof}

Together, the previous two lemmas yield
\begin{prop}\label{p.strong_spreading_via_tuples}
  Let $\xg$ be a \tds, $m\in\N$ and $\varepsilon_0>0$. Then the following are
  equivalent.
  \begin{itemize}
  \item[(i)] $\xg$ is strongly $(\varepsilon,m)$-spreading for all
    $\varepsilon<\varepsilon_0$;
  \item[(ii)] for all $\varepsilon < \varepsilon_0$ and $\delta>0$ there exist
    $N=N(\varepsilon,\delta)$ and $x^{(1)},\ldots, x^{(N)}\in X^m_{\varepsilon}$ such
    that
  \[
  \lBD\left(\left\{ g\in G \ \left| \exists k\in\{1,\ldots, N\} :
  gU\cap B\left(x^{(k)}_i,\delta\right)\neq \emptyset \textrm{ for } i=1,\ldots,
  m\right\}\right)\right. \ = \ 1 \ ,
    \]
    holds for all nonempty open sets $U\subseteq X$
  \end{itemize}
\end{prop}

