\section{Preliminaries}
\label{sec: prereq}
We give a brief introduction to knot Floer homology, L-space knots, and their associated immersed curves. For arbitrary knots in $S^3$, results concerning their immersed curves can be found in~\cite{HanRasWat2022heegaardfortorusbdd}.


\subsection{Knot Floer homology}
\label{sec:knot Floer homology}
The filtered chain homotopy type of the knot Floer complex $\CFK^-(K)$ is an invariant of a knot $K$ in $S^3$~\cite[Theorem~3.1]{OS2004knotinvariants}.
The complex is freely generated over $\F[U]$. The differential counts pseudoholomorphic disks $\phi$, where $n_z(\phi)$ and $n_w(\phi)$ count the discs' intersection with certain submanifolds corresponding to basepoints $z$ and $w$. We denote the homotopy classes of these disks from $x$ to $y$ by $\pi_2(x,y)$. The expected dimension of the moduli space $\mathcal{M}(\phi)$ of pseudoholomorphic representatives of $\phi$ is denoted by $\mu(\phi)$. The differential is then given by 
\begin{align*}
\partial^- x = \sum_{y} \sum_{\substack{\phi \in \pi_2(x,y)\\ \mu(\phi) = 1}} \# \left(\mathcal{M}(\phi)/\R\right) ~ U^{n_w(\phi)}\cdot y.
\end{align*}
The Alexander grading is defined by $\gr_A(x) - \gr_A(y) = n_z(\phi) - n_w(\phi)$ for $\phi \in \pi_2(x,y)$. It is fixed by the quasi-isomorphism to $\CF^-(S^3) \cong \F[U]$ and induces a filtration
\begin{align*}
    \mathcal{F}_i = \{ x \in \CFK^-(K) \mid \gr_A(x) \leq i\}\quad\text{s.t.}\quad
\dots \subset \mathcal{F}_i \subset \mathcal{F}_{i+1} \subset \dots \subset \CFK^-(K).
\end{align*}
The associated graded complex is defined as $\gCFK^-(K) = \bigoplus_i \mathcal{F}_{i}/\mathcal{F}_{i-1}$. The differential excludes holomorphic discs that cross the basepoint $z$. 
\begin{align*}
\partial^-_g x = \sum_{y \in \mathbb{T}_\alpha \cap \mathbb{T}_\beta} \sum_{\substack{\phi \in \pi_2(x,y)\\ \mu(\phi) = 1 \\ n_z(\phi) = 0}} \# \left(\mathcal{M}(\phi)/\R\right) ~ U^{n_w(\phi)}\cdot y.
\end{align*}
We denote the homology $H_*(\gCFK^-(K), \partial^-_g)$ by $\HFK^-(K)$.
It can be decomposed as  
\begin{align}
\label{eq: HFK^- decomposition}
    \HFK^-(K) = \F[U] \oplus \HFK^-_{\operatorname{red}}(K) \quad\text{where}\quad
\HFK^-_{\operatorname{red}}(K) = \bigoplus_{k = 0}^n \F[U]/U^{i_k}.
\end{align}

\begin{definition}[\cite{JuhMilZem2020cobordism}]
    Let $K$ be a knot in $S^3$. Let $\HFK^-_{\operatorname{red}}(K)$ be the torsion submodule of its knot Floer homology. The \emph{knot Floer order} is defined as
    \[
    \Ord(K) = \min\{k \in \N \mid U^k \cdot \HFK^-_{\operatorname{red}}(K) = 0\}.
    \]
\end{definition}

Since the decomposition in~\eqref{eq: HFK^- decomposition} is finite, $\Ord(K)$ is always finite. Details on the composition can be found in~\cite[Proposition~6.1.4, Proposition~7.3.3]{OSS2015gridhomology}. Though a general result to obtain the immersed curves is stated for arbitrary complexes $\CFK^-(K)$ in~\cite{HanRasWat2022heegaardfortorusbdd}, we are interested in those that admit a special type of basis, vastly simplifying the result (see Lemma~\ref{lem:Alex to gamma}). We will see in Theorem~\ref{thm:l_space knot complex} that all L-space knots admit such bases. 

\begin{definition}[Definition~11.23,~\cite{LipOszThu2018bordered}]
    A basis $\{x_0, \dots x_n\}$ of the complex $\CFK^-(K)$ is called \emph{filtered} if its image in $\gCFK^-(K)$ is a basis. 
    The complex $\CFK^-(K)$ is called \emph{reduced} if its differential $\partial^-$ drops either $\gr_A$ or the $U$-power, i.e. 
    \begin{align*}
        \partial^- x = y_1 + U y_2, \quad\text{where}\quad \gr_A(y_1) < \gr_A(x).
    \end{align*}  
    A filtered basis $\{\xi_i\}$ is \emph{vertically simplified} if either 
    \begin{align*}
        \partial \xi_i \in U \cdot \CFK^-(K), \quad \text{ or } \quad \partial \xi_i \equiv \xi_{i+1} \text{ mod } U \cdot \CFK^-(K).
    \end{align*}
    A basis $\{\eta_i\}$ is \emph{horizontally simplified} if either
    \begin{align*}
        \gr_A(\partial \eta_i) < \gr_A(\eta_i) \quad \text{ or } \quad \exists m \colon \partial \eta_i = U^m \cdot \eta_{i+1} + y 
    \end{align*}
    where $\gr_A(\eta_i) = \gr_A(U^m \cdot \eta_{i+1})$ and $\gr_A(y) < \gr_A(\eta_i)$.
\end{definition}

More details on knot Floer homology can be found, for example, in~\cite{OS2018overviewknotfloer}~\cite{Hom2021lecturenotes} or~\cite{Manolescu2016introduction}.


\subsection{L-space knots}
\label{sec:L-space knots}
This section introduces L-space knots and highlights key aspects of their knot Floer homology. L-space knots have been defined initially, and studied by Ozsváth and Szabó in~\cite{OS2005lensespacesurgeries}. 
Their Alexander polynomial determines the knot complex completely, as proven in Theorem~1.2 in~\cite{OS2005lensespacesurgeries}. 
They conclude in Corollary~1.3 a structural result for the Alexander polynomial of L-space knots. We summarize both results here.

\begin{lemma}[Corollary~1.3~\cite{OS2005lensespacesurgeries}]
    Let $K$ be an L-space knot in $S^3$. Then there is a decreasing sequence of integers
    \begin{align*}
    \alpha_{0} > \dots > \alpha_i > \dots > \alpha_{2n},\quad \text{ s.t. } \quad -\alpha_k = \alpha_{2n-k},
    \end{align*}
    such that its symmetrized Alexander polynomial $\Delta_K(t)$ has the form
    \begin{equation*}
        \Delta_K(t) = \sum_{i=0}^{2n} (-1)^i t^{\alpha_i}.
    \end{equation*}
    \qed
\end{lemma}
\begin{theorem}[\cite{OS2005lensespacesurgeries}(cf. Theorem~2.10~\cite{OszStiSza2017concordance})]
\label{thm:l_space knot complex}
Let $K$ be an L-space knot in $S^3$ with Alexander polynomial $\Delta_K(t) = \sum_{i = 0}^{2n} (-1)^i t^{\alpha_i}$, $\alpha_0 > \dots > \alpha_{2n}$. Let for $i \in \{1, \dots, 2n\}$
\[ d_i = \alpha_{i-1} - \alpha_{i} > 0.\]
Then $\CFK^-(K)$ has a basis $\{x_0, \dots x_{2n}\}$ over $\F[U]$ such that $\gr_A(x_k) = \alpha_k$  with differentials
\begin{align*}
\displaystyle
    \partial^- x_{2i} = 0 \quad\text{and} \quad
    \partial^- x_{2i + 1} = x_{2i+2} + U^{d_{2i+1}} x_{2i}.
\end{align*}
    \qed
\end{theorem}

\begin{rem}
    \label{rem: basis for CFK^-}
    The graded complex $\gCFK^-(K)$ has a differential $\partial^-_g$ which excludes any disk with $n_z(\phi) > 0$. Theorem~2.10~\cite{OszStiSza2017concordance} yields that the disk $\phi$ from $x_{2i+1}$ to $x_{2i+2}$ has $n_z(\phi) = d_{2i + 2} > 0$. Thus 
    \begin{equation*}
        \partial^-_g x_{2i} = 0 \quad\text{and}\quad \partial^-_g x_{2i + 1} = U^{d_{2i+1}} x_{2i}.
    \end{equation*}
    From the symmetry $\alpha_{2n-k} = -\alpha_k$, we conclude that $d_{2n - i} = d_{1 + i}$. We can see that $\HFK^-(K) = \F[U] \oplus \bigoplus_{i=0}^n \F[U] / U^{d_i}$. Therefore $\Ord(K) = \max\{d_i \mid i = 0, \dots, n\}$. This is essentially the proof in~\cite[Lemma~5.1]{JuhMilZem2020cobordism}.
\end{rem}

\subsection{Immersed curves}
\label{sec:immersed curves}

The \emph{immersed curve invariant} \( \widehat{\HF}(M) \) for a 3-manifold \( M \) with torus boundary was introduced by Hanselman, Rasmussen, and Watson in~\cite{HanRasWat2022heegaardfortorusbdd, HanRasWat2024borderedviaimmersed}. This invariant is defined as a collection  
\[
\gamma = \{\gamma_0, \dots, \gamma_n\}
\]  
of curves \( \gamma_i: S^1 \looparrowright T^2 \setminus \{z\} \), up to regular homotopy, where each curve is an immersion into the punctured torus. In~\cite{HanRasWat2024borderedviaimmersed}, the authors prove that \( \widehat{\HF}(M) \) encodes the same data as a certain type of bordered Floer invariant, the type D structure \( \widehat{\operatorname{CFD}}(M) \) introduced in~\cite{LipOszThu2018bordered}. In the special case where \( M \) is the exterior of a knot \( K\) in \(S^3 \), i.e. \( M = S^3 \setminus \operatorname{int}(\nu K) \), the invariant recovers the knot Floer homology \( \HFK^-(K) \).

In this paper, we will focus on precisely this situation: \( M = S^3 \setminus \operatorname{int}(\nu K)\), where \( \nu K \) denotes a tubular neighborhood of the knot \( K\) in \(S^3 \). The boundary torus is identified with \( \partial M\). We denote by \( \mu \) the meridian and by \( \lambda \) the Seifert longitude of the knot exterior. The basepoint in \( T^2 \) is taken to be the point of transverse intersection \( z = \lambda \pitchfork \mu \).

Let \( \R^2 \) be the universal cover of the torus, with the lifts of the basepoint \( z \) lying at the lattice points \( \Z^2 + (0, 1/2) \). We lift the set of curves \( \gamma \) to the intermediate covering space \( \overline{T} = \R^2 / \lambda \), where \( \lambda \) is chosen to be the horizontal direction. We view \( \overline{T} \) as the infinite strip \( [-1/2, 1/2] \times \R \), with the identification \( (-1/2, t) \sim (1/2, t) \). The lifts of the basepoint \( z \), which we refer to as \emph{pegs}, appear at heights \( n + 1/2 \) for \( n \in \Z \). The intersections of $\widetilde{\gamma} \cap \{0\}\times \R$ will be homotoped to appear at integer heights. See Figure~\ref{fig:T23 immersed curve}(a).

We will prove the following lemma using Proposition~47 in~\cite{HanRasWat2022heegaardfortorusbdd} for the special case of L-space knots. 


\begin{lemma}(Immersed curves for L-space knots)
\label{lem:Alex to gamma}
For an L-space knot $K$ with symmetrized Alexander polynomial $\Delta_K(t)$ with exponents $\alpha_{0} > \dots > \alpha_{2n}$, the immersed multicurve $\widetilde{\gamma}$ is a single curve constructed as follows. 
\begin{enumerate}
    \item Place a horizontal segment $[-1/4, 1/4] \times \{t\}$ at hight $t = \alpha_i$.
    \item Connect the endpoints corresponding to $\alpha_{2i+1}$ and $\alpha_{2i+2}$ on the left.
    \item Connect the endpoints corresponding to $\alpha_{2i+1}$ and $\alpha_{2i}$ on the right.
    \item Connect the unattached endpoints to $(-1/2, 0)$ and $(1/2, 0)$, respectively.
\end{enumerate}
\end{lemma}

\begin{proof}
    Let $d_i$ denote the difference between the exponents $\alpha_{0} > \dots > \alpha_{2n}$ in the Alexander polynomial, i.e.
    \[
    d_i = \alpha_{i-1} - \alpha_{i}.
    \]
    Theorem~\ref{thm:l_space knot complex} yields that $\CFK^-(K)$ is freely generated by $x_0, \dots, x_{2n}$ over $\F[U]$ with differential
    \begin{align*}
        \partial x_{2i} = 0 \quad \text{and} \quad \partial x_{2i+1} =  x_{2i+2} + U^{d_{2k+1}}x_{2i}.
    \end{align*}
    To apply Proposition~47 in~\cite{HanRasWat2022heegaardfortorusbdd}, we need to verify that the basis from Theorem~\ref{thm:l_space knot complex} is horizontally and vertically simplified. It is,  $\{x_0, \dots, x_{2n}\}$ is filtered since $\gr_A(x_i) = \alpha_i$. It is reduced since $\gr_A(x_{2i + 2}) < \gr_A(x_{2i + 1})$. It is vertically simplified since $\partial x_{i} - \partial x_{i+1} \in U \cdot \CFK^-(K)$ and horizontally simplified since $\gr_A(\partial x_{2i + 1}) - \gr_A(x_{2i}) = d_{2i + 1}$. 

    Following the process from Proposition~47 in~\cite{HanRasWat2022heegaardfortorusbdd},
    we draw $2n+1$ horizontal segments at the height $t = \alpha_i$. Denote each segment by the corresponding generator. Connect $\alpha_{2i+1}$ and $\alpha_{2i+2}$ on the left. Connect the segment $\alpha_{2i+1}$ with $\alpha_{2i}$ on the right. Finish by connecting the segments $\alpha_0$ to $(-1/2, 0)$ on the left and $x_{2n}$ to $(1/2, 0)$ on the right.
\end{proof}

Given an immersed curve as in Lemma~\ref{lem:Alex to gamma}, see Figure~\ref{fig:T23 immersed curve}(a), we obtain $\gCFK^-(K)$ from \(\widehat{\HF}(S^3\setminus \operatorname{int}( \nu K))\) as follows, see Figure~\ref{fig:T23 immersed curve}(b).


\begin{figure}[htbp]
    \centering
    \subfigure[]{%
        \includegraphics[width = 0.3\linewidth]{TM_ims.png}
    }
    \subfigure[]{%
        \includegraphics[width = 0.3\linewidth]{TM_hol.png}
    }
    \caption{(a) The smoothed immersed curve $\widehat{\HF}(M)$ for $T_{2,3}$.~(b) Replace $z \in \partial M$ by marked discs. Intersections $\mu \cap \gamma$ are generators over $\F[U]$ for \(gC^-(\widehat{\HF}(M))\). Bigons that are counted in the differential are those that do not cover the marked point $z$.}
    \label{fig:T23 immersed curve}
\end{figure}

\begin{lemma}
\label{lem:gamma to gC}
    Let $\widetilde{\gamma}$ be the lift of the immersed curve $\gamma \in \widehat{\HF}(S^3\setminus\nu K)$, where $K$ is an L-space knot, such that $\widetilde{\gamma}$ is as constructed in Lemma~\ref{lem:Alex to gamma}. The graded knot Floer complex $\gCFK^-(K)$ is isomorphic to the graded complex $(C, \partial_C)$ obtained as follows. 
    Let $C$ be freely generated over $\F[U]$ by the intersections $\widetilde{\gamma} \cap \{0\} \times \R = \{x_0, \dots x_{2n}\}$, such that $\gr(x_i)$ is the height $t_i \in \Z$ of the intersection.
    The differential is given by
    \begin{align*}
    \partial_C x_{2i} = 0 \quad \text{and}\quad \partial_C x_{2i+1} = U^{\gr(x_{2i}) - \gr(x_{2i+1})} x_{2i}.
    \end{align*}
\end{lemma}

\begin{proof}
    This Lemma~is the application of Theorem~51 in~\cite[Section 4.3]{HanRasWat2022heegaardfortorusbdd}. Let $\{x_0, \dots, x_{2n}\}$ be the intersections of $\widetilde{\gamma}$ and $\{0\} \times t$. Replace the pegs with marked disks as in Figure~\ref{fig:T23 immersed curve}(b). We denote by $N^w_i(x_k, x_l)$ the number of bigons covering the basepoint $w$ exactly $i$ times.
    \begin{itemize}
        \item Let $|k-l| > 1$. Then $N^w_i(x_k, x_l) = 0$. Since $\widetilde{\gamma}$ is monotone, there are only bigons between neighboring intersections. 
        \item Let $l = k+1$. Then $N^w_i(x_k, x_l) = 0$. Any curve constructed as Lemma~\ref{lem:Alex to gamma} connects $x_{2n}$ to $x_{2n+1}$ on the right. Thus the boundary component running from $x_{2n}$ to $x_{2n+1}$ is the component running along $\mu$. Any intersection $x_{2n+1}$ is connected to $x_{2n+2}$ on the left, thus the bigon covers $z$. 
        \item $N^w_i(x_{2n+1}, x_{2n}) = 1$ if and only if $\gr(x_{2n}) - \gr(x_{2n+1}) = i$. The bigon connecting $x_{2n+1}$ to $x_{2n}$ covers for each peg between $x_{2n+1}$ and $x_{2n}$ exactly one the marked point $w$. The pegs are at heights $n+1/2$. Thus the first peg between two intersections is at height $\gr(x_{2n}) - 1/2$, the last peg is at height $\gr(x_{2n+1}) + 1/2$. Thus there are 
        \[
        \gr(x_{2n}) - 1/2 - (\gr(x_{2n+1}) + 1/2) + 1 = \gr(x_{2n}) - \gr(x_{2n+1})
        \]
        marked points $w$ that the bigon covers. 
    \end{itemize}
    Thus, we get the differentials as stated. 
\end{proof}

\begin{rem}
\label{rem: Curve to ord}
The graded complex $\gCFK^-(K)$ is isomorphic to the complex in Remark~\ref{rem: basis for CFK^-}. We can see that $\Ord(K) = \max\{\gr(x_{i-1}) - \gr(x_{i}) \mid i = 1, \dots 2n\}$. 
\end{rem}

The invariant $ \widehat{\HF}(M) $ in general includes a finite-dimensional vector space $ V_i $ over $ \F $ and an automorphism $ \Phi_i: V_i \to V_i $. However, in our setting, these will be trivial. In the case of L-space knots, $\widehat{\HF}(M)$ consists of a single component with a unique $\spinc$ structure and thus no decorations are required~\cite[Remark 16]{HanRasWat2022heegaardfortorusbdd}. 

Let $K_{p,q}$ be the $(p,q)$-cable of a knot $K$ in $S^3$. To obtain the immersed curve $\gamma_{p,q}$ for $K_{p,q}$ from the immersed curve $\gamma$ of $K$, we recall the main Theorem~from~\cite{HanWat2023cabling}.
\begin{theorem}[Theorem~1~\cite{HanWat2023cabling}]
\label{prop: cabling process}
    Let $\gamma$ be the immersed multicurve associated with $K$ and $\gamma_{p,q}$ the multicurve associated with the cable $K_{p,q}$. Let $\widetilde{\gamma}$ and $\widetilde{\gamma}_{p,q}$ be their lifts to $\R^2 \setminus \Z^2$. Then $\widetilde{\gamma}_{p,q}$ is the curve obtained by the following process. 
    \begin{enumerate}
    \item Draw $p$ copies of $\widehat{HF}(M)$ next to each other, each scaled vertically by a factor of $p$, staggered in height such that each copy of the curve is $q$ units lower than the previous copy.
    \item Connect the loose ends of the successive copies of the curve.
    \item Translate the pegs horizontally so that they lie in the same vertical line, carrying the curve along with them.
\end{enumerate}
\qed
\end{theorem}

