\begin{definition}[Constraint-Induced Spencer Operator - Constructive Definition]
The constraint-induced Spencer operator $\delta^{\lambda}_{\g}$ is a $+1$-degree graded derivation on the symmetric tensor algebra $\Sym(\g) = \bigoplus_{j=0}^{\infty} \Sym^j(\g)$, completely determined by the following two rules\cite{zheng2025geometric}:

\textbf{A. Action on Generators (j=1):}
For any Lie algebra element $v \in \g = \Sym^1(\g)$, its image $\delta^{\lambda}_{\g}(v)$ is a second-order symmetric tensor $\delta^{\lambda}_{\g}(v) \in \Sym^2(\g)$, defined by:
$$(\delta^{\lambda}_{\g}(v))(w_1,w_2) := \frac{1}{2}(\langle\lambda,[w_1,[w_2,v]]\rangle + \langle\lambda,[w_2,[w_1,v]]\rangle)$$
where $w_1,w_2 \in \g$ are test vectors, and $\langle\cdot,\cdot\rangle$ is the pairing between $\g^*$ and $\g$. This definition ensures the output is symmetric in $w_1,w_2$.

\textbf{B. Leibniz Rule:}
The operator satisfies the graded Leibniz rule. For any $s_1 \in \Sym^p(\g)$ and $s_2 \in \Sym^q(\g)$:
$$\delta^{\lambda}_{\g}(s_1 \odot s_2) := \delta^{\lambda}_{\g}(s_1) \odot s_2 + (-1)^p s_1 \odot \delta^{\lambda}_{\g}(s_2)$$
where $\odot$ denotes the symmetric tensor product.
\end{definition}

\begin{proposition}[Equivalent Symbolic Expression]
For any $v \in \g$, the operator $(\delta^{\lambda}_{\g}(v))$ given by the constructive definition is equivalent to the following expression:
$$(\delta^{\lambda}_{\g}(v))(w_1,w_2) = \langle\lambda,[w_2,[w_1,v]]\rangle + \frac{1}{2}\langle\lambda,[[w_1,w_2],v]\rangle$$
This expression is derived by applying the Jacobi identity in the Lie algebra to the constructive definition, naturally satisfying symmetry requirements and resolving all type mismatch issues.
\end{proposition}


\begin{lemma}[Bigraded Structure of Spencer Complexes]
The above definition gives a well-defined bigraded differential complex satisfying:
\begin{enumerate}
\item $(\mathcal{D}_h^{k,j})^2 = 0$ (because $d^2 = 0$)
\item $(\mathcal{D}_v^{k,j})^2 = 0$ (needs verification using the modified Cartan equation)
\item $\mathcal{D}_h^{k+1,j} \circ \mathcal{D}_v^{k,j} + \mathcal{D}_v^{k+1,j} \circ \mathcal{D}_h^{k,j} = 0$ (mixed condition)
\end{enumerate}
\end{lemma}

