\begin{figure}
  \centering
  \includegraphics[width=0.6\textwidth]{i_mix_water.png}
  \caption{Static contact angles  of binary mixtures of  water with NMP and with 1,2-ethanediol, respectively, on PTFE for different molar compositions. Predictions from DFT are compared to experimental data, at $T\approx\SI{298}{\kelvin}$. 
