\appendix

\section{ One-dimensional Markov-jump dynamics in terms of probabilities $P_t(y)$ and currents $J_t(x)$}

\label{app_JumpPJ}

In this Appendix, we describe how the section \ref{sec_diffusionPJ} of the main text
can be adapted to Markov-jump dynamics with nearest-neighbor transition rates $w(x \pm 1,x)$ for $0 \leq x \leq N$.



 \subsection{ Continuity equation for the probability $P_t(x)$ involving the currents $J_t(x) $   }

The probability $P_t(y)$ is defined on the $(N+1)$ sites $y=0,1,..,N$,
while the current $J_t(x) $ is defined on the $N$ links $(x,x+1)$ with $x=0,1,..,N-1$
(note than another possibility is to label the currents $J_t\left( x+\frac{1}{2} \right)$ via the middle-point $\left( x+\frac{1}{2} \right)$ of the associated link $(x,x+1)$ as described in \cite{c_boundarydriven})
\begin{eqnarray}
J_t(x) \equiv w(x+1,x) P_t(x) - w(x,x+1) P_t(x+1) = \sum_{y=0}^N {\bold J}(x,y) P_t(y)
\label{jlink}
\end{eqnarray}
and is computed from the probabilities $P_t(y) $
via the application of the current matrix ${\bold J}(x,y)$ of size $N \times (N+1)$ 
with matrix elements only on the diagonal $x=y $ and on the upper-diagonal $x+1=y$
\begin{eqnarray}
 {\bold J}(x,y) = w(x+1,x) \delta_{x,y}  - w(x,x+1) \delta_{x+1,y}
\label{currentMatrix}
\end{eqnarray}
This matrix ${\bold J} $ is the analog of the current differential operator ${\cal J}$ of Eq. \ref{defJop} of the main text.

When the rates are unity in the current matrix of Eq. \ref{currentMatrix},
one obtains the matrix of size $N \times (N+1)$
with matrix elements only on the diagonal $x=y $ and on the upper-diagonal $x+1=y$
\begin{eqnarray}
 {\bold I}(x,y) = \delta_{x,y}  -  \delta_{x+1,y}
\label{IncidenceMatrix}
\end{eqnarray}
that can be applied to the probability $P_t(y)$ (or any other function defined on sites) to compute the discrete difference
\begin{eqnarray}
 \sum_{y=0}^N {\bold I}(x,y) P_t(y) = P_t(x)  -  P_t(x+1)
\label{IncidenceMatrixapplied}
\end{eqnarray}
while its adjoint of size $(N+1) \times N$
with matrix elements only on the diagonal $y=x $ and on the lower-diagonal $y=x+1$
\begin{eqnarray}
 {\bold I}^{\dagger}(y,x) =  {\bold I}(x,y)  = \delta_{y,x}  -  \delta_{y,x+1}
\label{IncidenceMatrixTransposed}
\end{eqnarray}
can be applied to the current $J_t(x)$ (or any other function defined on links) to compute the discrete difference
\begin{eqnarray}
\sum_{x=0}^{N-1} {\bold I}^{\dagger}(y,x) J_t(x)=  J_t(y)  -  J_t(y-1)
\label{IncidenceMatrixTransposedapplied}
\end{eqnarray}
The matrices ${\bold I} $ and ${\bold I}^{\dagger} $ are the analogs of the derivative operators $\left( \pm \frac{\partial}{\partial x}\right)$ that appear in the main text

The continuity equation describing the evolution of the probability $P_t(y)$
involves the difference of the currents of Eq. \ref{IncidenceMatrixTransposedapplied}
and can be thus rewritten as the application of the matrix ${\bold I}^{\dagger} $ to the current $J_t(x)$
\begin{eqnarray}
 \partial_t P_t(y)   && =  J_t(y-1) -  J_t(y) = - \sum_{x=0}^{N-1}   {\bold I}^{\dagger}(y,x) J_t(x)
 \label{continuityDiscrete}
\end{eqnarray}


 \subsection{ Boundary conditions   }

 In these Appendices, to simplify the discussions, we will mostly have in mind the vanishing-current boundary conditions
\begin{eqnarray}
J_t(-1) && =0
 \nonumber \\
J_t(N) && =0
\label{vanishJDiscrete}
\end{eqnarray}
that are the analog of Eq. \ref{vanishinhJ},
so that the dynamics at the two boundary-sites $y=0$ and $y=N$ reduce to
\begin{eqnarray}
 \partial_t P_t(0) && = -  J_t(0)
 \nonumber \\
 \partial_t P_t(N)   && =  J_t(N-1)
\label{continuityDiscreteBC}
\end{eqnarray}

Of course, the other B.C. like Eqs \ref{PeriodicBC} \ref{AbsorbingBC} \ref{drivenBC} are also interesting
in the discrete case (see for instance \cite{c_ring} and references therein for the periodic B.C.
and \cite{c_boundarydriven} and references therein for the boundary-driven-by-external-reservoirs B.C.).




