\section{ Dynamics for the probability $P_t(x)$ governed by the factorized Markov matrix 
${\bold M} = - {\bold I}^{\dagger} {\bold J}$   }


\label{app_JumpP}

In this Appendix, we describe how the section \ref{sec_diffusionP} of the main text
can be adapted to the Markov-jump dynamics.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{ Factorized Markov matrix 
${\bold M} = - {\bold I}^{\dagger} {\bold J}$ governing the Master Equation for the probability $P_t(y)$}


Plugging Eq. \ref{jlink} into Eq \ref{continuityDiscrete} leads to the standard master equation
\begin{eqnarray}
 \partial_t P_t(x)   && =  w(x,x-1) P_t(x-1)  + w(x,x+1) P_t(x+1) - \bigg[ w(x-1,x) +w(x+1,x) \bigg]P_t(x)
 \nonumber \\
 && = \sum_{y=0}^N {\bold M}(x,y) P_t(y)
\label{master}
\end{eqnarray}
where the factorized Markov matrix matrix ${\bold M}=- {\bold I}^{\dagger} {\bold J}$ 
is tridiagonal with off-diagonal elements given by positive transition rates $w(.,.)$
\begin{eqnarray}
{\bold M}(x,x-1) && =  w(x,x-1)  
 \nonumber \\
{\bold M}(x,x-1) && =w(x,x+1)
\label{masteroff}
\end{eqnarray}
while the diagonal element $ {\bold M}(x,x) $ is the opposite of the total rate out of site $x$ 
\begin{eqnarray}
 {\bold M}(x,x) = - \bigg[ w(x-1,x) +w(x+1,x) \bigg] = - \sum_{x' \ne x} {\bold M}(x',x) 
\label{masterdiag}
\end{eqnarray}
as it should to conserve the total probability.

To make the link with the notations of Eq. \ref{Ux} of the main text, it is useful to introduce the following parametrization of the transition rates 
\begin{eqnarray}
 w(x+1,x)  =D(x) e^{ \frac{ U(x)-U(x+1) }{2} }
 \nonumber \\
  w(x,x+1)  =D(x) e^{  \frac{ U(x+1)-U(x) }{2} }
\label{rates}
\end{eqnarray}
where the diffusion coefficient $D(x)$ defined on the links $(x,x+1)$ with $x=0,..,N-1$
and the potential $U(y)$ defined on the sites $y=0,..,N$ can be computed from the transition rates via
\begin{eqnarray}
D(x) && = \sqrt{ w(x+1,x)   w(x,x+1) }
\nonumber \\
U(x+1)-U(x) && = \ln \left( \frac{  w(x,x+1) }{  w(x+1,x) } \right)
\label{ratesInversion}
\end{eqnarray}

Then the current matrix ${\bold J}(x,y)$ of Eq. \ref{currentMatrix} can be rewritten in the factorized form
involving the matrix ${\bold I}$ of Eq. \ref{IncidenceMatrix}
\begin{eqnarray}
 {\bold J}(x,y) && = D(x) e^{ \frac{ U(x)-U(x+1) }{2} } \delta_{x,y}  - D(x) e^{  \frac{ U(x+1)-U(x) }{2} } \delta_{x+1,y}
 \nonumber \\
 && = D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } {\bold I}(x,y) e^{U (y)}
\label{currentMatrixUD}
\end{eqnarray}
that is the analog of Eq. \ref{defJopU} of the main text,
so that the current $J_t(x) $ on the link $(x,x+1)$ of Eq. \ref{jlinkUD}
becomes
\begin{eqnarray}
J_t(x) = D(x) e^{ - \frac{ U(x)+U(x+1) }{2} } \left[ e^{U(x)} P_t(x) -  e^{  U(x+1) } P_t(x+1) \right]
\label{jlinkUD}
\end{eqnarray}

The corresponding form of the Markov matrix ${\bold M}=- {\bold I}^{\dagger} {\bold J}$
\begin{eqnarray}
{\bold M}(z,y) && =- \sum_{x=0}^{N-1} {\bold I}^{\dagger}(z,x) {\bold J}(x,y)
 \nonumber \\
 && = - \sum_{x=0}^{N-1} {\bold I}^{\dagger}(z,x) D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } {\bold I}(x,y) e^{U (y)}
\label{MatrixMUD}
\end{eqnarray}
is the analog of Eq. \ref{defJopU}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{ The two independent explicit solutions of 
$0 = {\bold M} P_*(y) $ in the bulk }


The analog of Eq. \ref{rhoeq} is the
 the equilibrium in the potential $U(y)$
\begin{eqnarray}
  \rho_{eq}(y) =  e^{  -U(y) } 
\label{steadyeqjump}
\end{eqnarray}
while the analog of Eq. \ref{rhoneq} reads 
\begin{eqnarray}
  \rho^{noneq}_*(y) && = e^{-U(y) }  \sum_{z=0}^{y-1} \frac{ e^{\frac{ U(z)+U(z+1) }{2} }  } { D(z) } 
\label{steadynoneqjump}
\end{eqnarray}



