\subsection{ Factorized adjoint matrix 
${\bold M}^{\dagger}  = - {\bold J}^{\dagger} {\bold I} $ governing the dynamics of observables $O(y)$ of the sites}

The average of an observable $O(y)$ computed with the probability $P_t(y)$ is the analog of Eq. \ref{Oav}
\begin{eqnarray}
 \sum_{y=0}^N O(y) P_t(y)  = \langle O \vert P_t \rangle
 \label{Oavdiscrete}
\end{eqnarray}
Its dynamics can be analyzed using the master Equation \ref{master}
\begin{eqnarray}
 \partial_t \sum_{y=0}^N O(y) P_t(y)  &&  =  \partial_t \sum_{y=0}^N O(y) P_t(y) 
 =\sum_{y=0}^N O(y) \sum_{z=0}^N {\bold M}(y,z) P_t(z)
 \nonumber \\
 && =   \sum_{z=0}^N  P_t(z) \bigg[ \sum_{y=0}^N O(y) {\bold M}(y,z) \bigg]
 = \sum_{z=0}^N  P_t(z) \bigg[ \sum_{y=0}^N  {\bold M}^{\dagger} (z,y) O(y) \bigg] =  \langle {\bold M}^{\dagger} O \vert P_t \rangle
\label{masterobser}
\end{eqnarray}
which is the analog of Eq. \ref{Oavdynfull} when the B.C. are taken into account in the finite matrices ${\bold M} $ and ${\bold M}^{\dagger} $.

If one uses the explicit expressions of the matrix elements ${\bold M}(y,z) $ 
of Eqs \ref{masteroff}
\ref{masterdiag}
in terms of the transition rates, one obtains the familiar expression
\begin{eqnarray}
 \partial_t \sum_{y=0}^N O(y) P_t(y)  &&  
 = \sum_{z=0}^N  P_t(z) \bigg[  O(z+1) {\bold M}(z+1,z) + O(z-1) {\bold M}(z-1,z) + O(z) {\bold M}(z,z)\bigg]
 \nonumber \\
 && 
 =  \sum_{z=0}^N  P_t(z) \bigg[  \bigg( O(z+1)-O(z) \bigg) w(z+1,z) +\bigg( O(z-1)-O(z) \bigg) w(z-1,z) \bigg]
\label{masterobserexpli}
\end{eqnarray}

The factorized form of the current matrix of Eq. \ref{currentMatrixUD}
translates for the adjoint matrix into
\begin{eqnarray}
 {\bold J}^{\dagger}(y,x)  = {\bold J}(x,y) && = D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } {\bold I}(x,y) e^{U (y)}
 \nonumber \\
 && = e^{U (y)}{\bold I}^{\dagger} (y,x)  D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } 
\label{currentMatrixUDadjoint}
\end{eqnarray}
that is the analog of Eq. \ref{defJopUadjoint}.
The corresponding factorized form of the adjoint matrix ${\bold M}=- {\bold I}^{\dagger} {\bold J}$ 
\begin{eqnarray}
{\bold M}^{\dagger} (y,z) && =- \sum_{x=0}^{N-1} {\bold J}^{\dagger}(y,x) {\bold I}(x,z)
 \nonumber \\
 && = - \sum_{x=0}^{N-1} e^{U (y)}{\bold I}^{\dagger} (y,x)  D(x) e^{-  \frac{ U(x)+U(x+1) }{2} }  {\bold I}(x,z)
\label{MatrixMUDadjoint}
\end{eqnarray}


