\subsection{ The two independent explicit solutions of 
$0 = {\bold M}^{\dagger} O(y) $ in the bulk }

The analog of Eq. \ref{l0unity} is also unity and associated to the conservation of probability
\begin{eqnarray}
l_0(y) && = 1 
\label{l0unitydiscrete}
\end{eqnarray}
while the analog of the scale function of Eq. \ref{Sx} reads
\begin{eqnarray}
s(y)  =  \sum_{x=0}^{y-1} \frac{ e^{\frac{ U(x)+U(x+1)}{2} }  } { D(x) } 
\ \ \ \text{ with $s(0)=0$ and the positive increments} \ \ s(y+1)-s(y) =\frac{ e^{\frac{ U(y)+U(y+1)}{2} }  } { D(y) }
\label{Sxdiscrete}
\end{eqnarray}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{ Physical interpretation of the discrete speed-measure $m(y)$
and of the discrete scale function $s(y)$ }

The cumulative equilibrium distribution $C_{eq}(x)$ analog to Eq. \ref{Ceqmx}
\begin{eqnarray}
C_{eq}(y) \equiv \sum_{z=0}^y P_{eq}(z)  =\sum_{z=0}^y \left( \frac{e^{-U(z) } }{ \sum_{y'=0}^N e^{-U(y') }}  \right) = \frac{ m(y) }
{ m(N) } \ \ \text{ with $C_{eq}(-1)=0$ and $C_{eq}(N)=1 $ }
\label{Ceqmxdiscrete}
\end{eqnarray}
can be used to defined the analog of the speed measure
\begin{eqnarray}
m(y)  \equiv \sum_{z=0}^y e^{-U(z) } 
\label{mydiscrete}
\end{eqnarray}
with its positive increment analogous to Eq. \ref{rhoeqmx}
\begin{eqnarray}
m(y)-m(y-1) = e^{- U(y)} 
\label{rhoeqmxdiscrete}
\end{eqnarray}


When the Markov jump process starts at position $y$,
the probability $E^{N}(y)$ to reach the right boundary $N$
before the left boundary $0$, 
and the complementary
probability $E^{0}(y)= 1- E^{N}(y)$ to reach the left boundary $0$ before the right boundary $N$,
 can be written in terms of the scale function $s(y)$ of Eq. \ref{Sxdiscrete}
 as in Eq. \ref{ExitRx}
\begin{eqnarray}
E^{N}(x) = \frac{ s(y) }{ s(N) } = 1- E^{0}(y)
  \label{ExitRxdiscrete}
\end{eqnarray}
Indeed, the probability $E^{N}(x) $ should be annihilated by the adjoint matrix ${\bold M}^{\dagger} $ 
 \begin{eqnarray}
0= {\bold M}^{\dagger} E^{N}(x) 
\label{adjointzeroExitdiscrete}
\end{eqnarray}
and can be thus written as a linear combination of the two independent solutions $l_0(y)=1$ and $s(y)$,
where the two constants are determined by the two boundary conditions at $y=0$ and $y=N$
 \begin{eqnarray}
 E^{N}(N) && =1
 \nonumber \\
 E^{N}(0) && =0
\label{BCExitdiscrete}
\end{eqnarray}



