\subsection{ Similarity transformation between the Markov matrix $ {\bold M}$ and the
hermitian supersymmetric quantum Hamiltonian 
${\bold H}(z,y)  \equiv - e^{ \frac{U(z)}{2} }  {\bold M} (z,y) e^{- \frac{U(y)}{2} } $ }


The form of Eq. \ref{currentMatrixUD}
for the Markov matrix ${\bold M}(z,y)  $
yields that the similarity transformation towards the matrix
\begin{eqnarray}
{\bold H}(z,y)  && \equiv - e^{ \frac{U(z)}{2} }  {\bold M} (z,y) e^{- \frac{U(y)}{2} }
= e^{ \frac{U(z)}{2} } \sum_{x=0}^{N-1} {\bold I}^{\dagger}(z,x) D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } 
{\bold I}(x,y)  e^{ \frac{U(y)}{2} } 
\nonumber \\
&& \equiv \sum_{x=0}^{N-1} {\bold Q}^{\dagger}(z,x)  {\bold Q}(x,y)
\label{Hsusydiscrete}
\end{eqnarray}
leads to the supersymmetric form ${\bold H}={\bold Q}^{\dagger} {\bold Q} $ involving the matrix ${\bold Q} $
and its adjoint ${\bold Q}^{\dagger}$
\begin{eqnarray}
{\bold Q}(x,y) && \equiv     \sqrt{ D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } } {\bold I}(x,y)  e^{ \frac{U(y)}{2} } 
\nonumber \\
{\bold Q}^{\dagger}(z,x) && 
 =e^{ \frac{U(z)}{2} }  {\bold I}^{\dagger}(z,x) \sqrt{ D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } }
\label{HsusyQdiscrete}
\end{eqnarray}
that are the analogs of the first order operators $Q$ and $Q^{\dagger}$ of Eq. \ref{HsusyQ}.

