\subsection{ Spectral decomposition of the Markov propagator}

The analog of the spectral decomposition of Eq. \ref{FPspectralq}
\begin{eqnarray}
 P_t(x \vert x_0)  \equiv \langle x \vert e^{ {\bold M} t} \vert x_0 \rangle  
&&  =\sum_{n=0}^{N} e^{- t E_n}  r_n(x) l_n(x_0)
= P_{eq}(x) + \sum_{n=1}^{N} e^{- t E_n}  r_n(x) l_n(x_0)
\label{Mspectral}
\end{eqnarray}
involves the $(N+1)$ eigenvalues $(-E_n) \leq 0$ of the Markov matrix ${\bold M} $,  while
 the corresponding right eigenvectors $\vert r_n \rangle $ 
and left eigenvectors $\langle l_n \vert $ satisfy the eigenvalues equations
\begin{eqnarray}
-  E_n \vert r_n \rangle && =  {\bold M} \vert r_n \rangle
  \nonumber \\
- E_n \langle l_n \vert && =  \langle l_n \vert{\bold M}  
\label{spectralrl}
\end{eqnarray}
and form a bi-orthogonal basis with the orthonormalization and closure relations
\begin{eqnarray}
\delta_{n,n'} && = \langle l_n \vert  r_{n'} \rangle = \sum_{x=0}^N \langle l_n \vert x \rangle \langle x \vert r_{n'} \rangle
\nonumber \\
{\bold 1} && = \sum_{n=0}^{N}  \vert r_n \rangle \langle l_n \vert 
\label{orthorl}
\end{eqnarray}

The vanishing eigenvalue $E_0=0$ is associated 
to the left eigenvector unity $l_0(x)=1$ 
while the right eigenvector corresponds to the equilibrium steady state $r_0(x)=P_{eq}(x)$ 
\begin{eqnarray}
  E_0 && =0
  \nonumber \\
 l_0 (x)&& =1
  \nonumber \\
 r_0 (x)&& =P_{eq}(x)
\label{rlzero}
\end{eqnarray}

As in Eq. \ref{FPspectralqleft}, it is often simpler to rewrite the spectral decomposition of Eq. \ref{Mspectral}
\begin{eqnarray}
P_t(x \vert x_0)  = P_{eq}(x) \left[ \sum_{n=0}^{N} e^{- t E_n}  l_n(x) l_n(x_0) \right]
= P_{eq}(x) \left[ 1 + \sum_{n=1}^{N} e^{- t E_n}  l_n(x) l_n(x_0) \right]
\label{Mspectralleft}
\end{eqnarray}
in terms of the left eigenvectors $l_n(x)$ that form an orthogonal property with respect to the equilibrium measure $P_{eq}(x)$
\begin{eqnarray}
\delta_{n n' } =  \sum_{x=0}^N   l_n(x) l_{n'}(x) P_{eq}(x)
 \label{ortholrldiscrete}
\end{eqnarray}



