\section{ Dynamics of the currents governed by the supersymmetric partner ${\hat {\bold M} } =  - {\bold J}^{\dagger} {\bold I}$ 
  }

\label{app_JumpJ}

In this Appendix, we describe how the section \ref{sec_diffusionJ} of the main text
can be adapted to the Markov-jump dynamics.


\subsection{ Dynamics of the currents $J_t(x)$ governed by the supersymmetric partner ${\hat {\bold M} } =  - {\bold J}^{\dagger} {\bold I}$ 
of the Markov matrix ${\bold M} = - {\bold I}^{\dagger} {\bold J}$ }

The dynamics of the $N$ currents $J_t(x)$ of Eq. \ref{jlink}
associated to the links $(x,x+1)$ with $x=0,..,N-1$
\begin{eqnarray}
\partial_t J_t(x) &&= w(x+1,x) \partial_t P_t(x) - w(x,x+1) \partial_t P_t(x+1)
\nonumber \\
&& = w(x+1,x) \left[J_t(x-1) -  J_t(x) \right]
- w(x,x+1) \left[J_t(x) -  J_t(x+1) \right]
\nonumber \\
&& = \sum_{z=0}^{N-1} {\hat {\bold M} } (x,z) J_t (z)
\label{jlinkdyn}
\end{eqnarray}
is governed by the supersymmetric partner ${\hat {\bold M} } =  - {\bold J} {\bold I}^{\dagger}$ of the Markov matrix 
${\bold M} = - {\bold I}^{\dagger} {\bold J}$ with the off-diagonal elements
\begin{eqnarray}
{\hat {\bold M} } (x,x-1) && = w(x+1,x) 
\nonumber \\
{\hat {\bold M} } (x,x+1) && = w(x,x+1) 
\label{hatwoff}
\end{eqnarray}
while the diagonal element
\begin{eqnarray}
{\hat {\bold M} } (x,x) && = - w(x+1,x) - w(x,x+1)= - {\hat {\bold M} } (x,x-1) - {\hat {\bold M} } (x,x+1) 
 = - \sum_{z \ne x} {\hat {\bold M}} (x,z)
\label{hatwdiag}
\end{eqnarray}
is the opposite of the sum of the transitions rates towards $x$.





The factorized form of Eq. \ref{currentMatrixUD} for the matrix ${\bold J}$,
leads to the factorized form 
\begin{eqnarray}
{\hat {\bold M} } (x,z) && =- \sum_{y=0}^{N} {\bold J}(x,y)  {\bold I}^{\dagger}(y,z)
 \nonumber \\
 && = -  \sum_{y=0}^{N} D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } {\bold I}(x,y) e^{U (y)} {\bold I}^{\dagger}(y,z)
\label{currentMatrixUDsusy}
\end{eqnarray}
that is the analog of Eq. \ref{susypartnerFPU}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{  Intertwining relations between the supersymmetric partners 
${\hat {\bold M} } =  - {\bold J} {\bold I}^{\dagger}$ of the Markov matrix 
${\bold M} = - {\bold I}^{\dagger} {\bold J}$ }


The Markov matrix ${\bold M} = - {\bold I}^{\dagger} {\bold J}$
and its supersymmetric partner 
${\hat {\bold M} } =  - {\bold J} {\bold I}^{\dagger}$ 
satisfy the intertwining relations
\begin{eqnarray}
{\bold J}{\bold M}   &&=  - {\bold J} {\bold I}^{\dagger} {\bold J} = {\hat {\bold M} } {\bold J}
\nonumber \\
{\bold M} {\bold I}^{\dagger}  
&&= - {\bold I}^{\dagger} {\bold J} {\bold I}^{\dagger} = {\bold I}^{\dagger}{\hat {\bold M} } 
  \label{interwJI}
\end{eqnarray}
that are the analogs of Eqs \ref{interwJ}
and \ref{interwderivative}
with similar consequences for their right and left eigenvectors.
Let us describe the case of left eigenvectors :
 the eigenvalue Eq. \ref{spectralrl} for the excited left eigenvector $ \langle l_n \vert  $ 
of ${\bold M} =- {\bold I}^{\dagger} {\bold J} $ can be split into
the two matrix equations
\begin{eqnarray}
 E_n \langle  i_n \vert && =   \langle l_n \vert {\bold I}^{\dagger}
\nonumber \\
 \langle l_n \vert  && =   \langle   i_n \vert {\bold J} 
\label{spectrallin}
\end{eqnarray}
involving the bra $\langle   i_n \vert $ which is a left eigenvector of the supersymmetric partner 
${\hat {\bold M} } \equiv -{\bold J}  {\bold I}^{\dagger} $ 
associated to the eigenvalue $(-E_n)$
\begin{eqnarray}
 E_n  \langle i_n \vert  
=  \langle l_n \vert {\bold I}^{\dagger}
=   \langle i_n \vert {\bold J}   {\bold I}^{\dagger} 
= -  \langle i_n \vert {\hat {\bold M} }
\label{excitedpartnerleft}
\end{eqnarray}

The explicit versions of Eqs \ref{spectrallin} read using 
the matrix elements of Eqs \ref{IncidenceMatrixTransposed}
and \ref{currentMatrix}
\begin{eqnarray}
 E_n i_n(x) && =   \langle l_n \vert {\bold I}^{\dagger} \vert x \rangle = \sum_y l_n(y) {\bold I}^{\dagger} (y,x) 
 = l_n(x)  - l_n(x+1)
\nonumber \\
  l_n (y) && =   \langle   i_n \vert {\bold J} \vert y \rangle = \sum_x i_n(x)  {\bold J} (x,y) 
  =   i_n(y)w(y+1,y)   - i_n(y-1) w(y-1,y) 
\label{spectrallinexpli}
\end{eqnarray}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{ Link with the supersymmetric partner ${\breve {\bold H}} = {\bold Q} {\bold Q}^{\dagger} $ 
of the quantum Hamiltonian ${\bold H}={\bold Q}^{\dagger} {\bold Q}  $} 


While $ {\bold H}={\bold Q}^{\dagger} {\bold Q} $ of Eq. \ref{Hsusydiscrete} is an $(N+1)\times (N+1)$ matrix
associated to the sites,
the supersymmetric partner ${\breve {\bold H}} = {\bold Q} {\bold Q}^{\dagger} $ is an $N \times N$ matrix
associated to the links.
Its matrix elements obtained using Eq. \ref{HsusyQdiscrete} 
\begin{eqnarray}
{\breve {\bold H}} (x,x')  &&=  \sum_{y=0}^{N} {\bold Q}(x,y) {\bold Q}^{\dagger}(y,x') 
\nonumber \\
&&=  \sum_{y=0}^{N}  \sqrt{ D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } } {\bold I}(x,y)  e^{ U(y) }  
{\bold I}^{\dagger}(y,x') \sqrt{ D(x') e^{-  \frac{ U(x')+U(x'+1) }{2} } }
\label{Hsusydiscretepartner}
\end{eqnarray}
is related to the supersymmetric partner ${\hat {\bold M} } (x,x') $ of Eq. \ref{currentMatrixUDsusy}
via the similarity transformation 
\begin{eqnarray}
{\breve {\bold H}} (x,x') = - \frac{1}{ \sqrt{ D(x) e^{-  \frac{ U(x)+U(x+1) }{2} } }}{\hat {\bold M} } (x,x') \sqrt{ D(x') e^{-  \frac{ U(x')+U(x'+1) }{2} } }\label{currentMatrixUDsusyq}
\end{eqnarray}
that is the analog of Eq. \ref{susypartnerFPUbiss}.









