\section{}\label{app:proof of triangle inequality}

In this appendix, we give the proof of the triangle inequality of the graph GOSPA metric family in \eqref{eq:gospa family defn}. We can write \eqref{eq:gospa family defn} as a function of the assignment set
as $d\left(X,Y,\gamma\right)$, where we have omitted the superscripts for notational clarity. We assume
we have three graphs $X$, $Y$ and $Z$. Let $\gamma_{XY}^{*}$,
$\gamma_{XZ}^{*}$ and $\gamma_{ZY}^{*}$ be the assignment sets that
minimise $d\left(X,Y,\gamma\right)$,
$d\left(X,Z,\gamma\right)$ and $d\left(Z,Y,\gamma\right)$.
Therefore, the triangle inequality property is met if the following
inequality is met for any $X$, $Y$ and $Z$
\begin{align}
d\left(X,Y,\gamma_{XY}^{*}\right) & \leq d\left(X,Z,\gamma_{XZ}^{*}\right)+d\left(Z,Y,\gamma_{ZY}^{*}\right).
\end{align}

Given $\gamma_{XZ}^{*}$ and $\gamma_{ZY}^{*}, $we construct an assignment
set $\gamma_{XY}$ between $X$ and $Y$ such that the nodes in $X$
and $Y$ are assigned if and only if they are assigned through the
assignment sets in $Z$. That is
\begin{align}
\gamma_{XY} & =\left\{ \left(i,j\right):\exists k:\left(i,k\right)\in\gamma_{XZ}^{*}\,\mathrm{and}\,\left(k,j\right)\in\gamma_{ZY}^{*}\right\}. \label{eq:assignment_XY}
\end{align}

If we prove 
\begin{align}
d\left(X,Y,\gamma_{XY}\right) & \leq d\left(X,Z,\gamma_{XZ}^{*}\right)+d\left(Z,Y,\gamma_{ZY}^{*}\right),
\end{align} the triangle inequality is met. 

To prove the previous equation, we show that for any $\gamma_{XY}$,
$\gamma_{XZ}$ and $\gamma_{ZY}$ that meet (\ref{eq:assignment_XY}), the following result holds

\begin{align}
d\left(X,Y,\gamma_{XY}\right) & \leq d\left(X,Z,\gamma_{XZ}\right)+d\left(Z,Y,\gamma_{ZY}\right).\label{eq:triangle_ineq_fixed_assignment}
\end{align}

We first define the following notation for the proof. Given $\gamma_{XY}$,
$\gamma_{XZ}$ and $\gamma_{ZY}$ that meet (\ref{eq:assignment_XY}),
we define the subsets $\gamma_{XZ}^{1}\subseteq\gamma_{XZ}$ and $\gamma_{ZY}^{1}\subseteq\gamma_{ZY}$
that include assignments that connect nodes from $X$ to $Y$ through
$Z$. That is, we can write 
\begin{equation}
\gamma_{XY}=\left\{ \left(i,j\right):\exists k:\left(i,k\right)\in\gamma_{XZ}^{1}\,\mathrm{and}\,\left(k,j\right)\in\gamma_{ZY}^{1}\right\}. 
\end{equation}
This implies that $|\gamma_{XY}|=|\gamma_{XZ}^{1}|=|\gamma_{ZY}^{1}|$.
Then, we also define $\gamma_{XZ}^{0}$ and $\gamma_{ZY}^{0}$ as
the sets of assignments that are not part of an assignment connecting
$X$ and $Y$ through $Z$. This also implies
\begin{flalign}
\gamma_{XZ} & =\gamma_{XZ}^{0}\cup\gamma_{XZ}^{1}\\
\gamma_{ZY} & =\gamma_{ZY}^{0}\cup\gamma_{ZY}^{1}.
\end{flalign}
Finally, we use the notation $\gamma_{XY}=\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}$
to represent that the assignments from $X$ to $Y$ are composed by
the assignments from $X$ to $Z$ in $\gamma_{XZ}^{1}$ and the assignments
from $Z$ to $Y$ in $\gamma_{ZY}^{1}$.

The proof of \eqref{eq:triangle_ineq_fixed_assignment} can be divided into two separate parts:
1) The first one is the proof of the triangle inequality for the localisation cost (including missed and false nodes). That is, we want 
\begin{flalign}
 & \sum_{\left(i,j\right)\in\gamma_{XY}}d^{p}\left(x_{i},y_{j}\right)+\frac{c^{p}}{2}\left(\left|X\right|+\left|Y\right|-2\left|\gamma_{XY}\right|\right)\nonumber \\
 & \leq\sum_{\left(i,k\right)\in\gamma_{XZ}^{1},\left(k,j\right)\in\gamma_{ZY}^{1}}\left(d\left(x_{i},z_{k}\right)+d\left(z_{k},y_{j}\right)\right)^{p}\nonumber \\
 & +\sum_{\left(i,k\right)\in\gamma_{XZ}^{0}}d^{p}\left(x_{i},z_{k}\right)+\sum_{\left(k,j\right)\in\gamma_{ZY}^{0}}d^{p}\left(z_{k},y_{j}\right)\nonumber \\
 & +\frac{c^{p}}{2}\left(\left|X\right|+|Z|-2\left|\gamma_{XZ}\right|\right)\nonumber \\
 & +\frac{c^{p}}{2}\left(|Z|+\left|Y\right|-2\left|\gamma_{ZY}\right|\right).\label{eq:loc_cost_inequality}
\end{flalign}
This part of the proof is provided in Appendix \ref{proof:loc cost triangle}. 

2) The second part of the proof is the proof of the triangle inequality for the edge cost (to the $p$-th power):
\begin{flalign}
    e_{XY}^{p}\left(\gamma_{XY}\right) & \leq e_{XZ}^{p}\left(\gamma_{XZ}\right)+e_{ZY}^{p}\left(\gamma_{ZY}\right).\label{eq:edge_cost_inequality}.
\end{flalign}
This result is proved in Appendix \ref{proof:edge cost triangle}.


To prove \eqref{eq:triangle_ineq_fixed_assignment}, we start with $d\left(X,Y,\gamma_{XY}\right)$ and apply the inequalities in \eqref{eq:loc_cost_inequality} and \eqref{eq:edge_cost_inequality}
\begin{flalign}
&d\left(X,Y,\gamma_{XY}\right) =\left(\sum_{\left(i,j\right)\in\gamma_{XY}}d^{p}\left(x_{i},y_{j}\right) \right. \nonumber \\
& \left.+\frac{c^{p}}{2}\left(\left|X\right|+\left|Y\right|-2\left|\gamma_{XY}\right|\right)+e_{XY}^{p}\left(\gamma_{XY}\right)\right)^{1/p} \nonumber \\
 & \leq\Biggl(\sum_{\left(i,k\right)\in\gamma_{XZ}^{1},\left(k,j\right)\in\gamma_{ZY}^{1}}\left(d\left(x_{i},z_{k}\right)+d\left(z_{k},y_{j}\right)\right)^{p} \nonumber \\
 &+\sum_{\left(i,k\right)\in\gamma_{XZ}^{0}}d^{p}\left(x_{i},z_{k}\right)+\sum_{\left(k,j\right)\in\gamma_{ZY}^{0}}d^{p}\left(z_{k},y_{j}\right)  \nonumber \\
 &  +\frac{c^{p}}{2}\left(\left|X\right|+|Z|-2\left|\gamma_{XZ}\right|\right) \nonumber \\
 & +\frac{c^{p}}{2}\left(|Z|+\left|Y\right|-2\left|\gamma_{ZY}\right|\right)\nonumber\\
 &  +e_{XZ}^{p}\left(\gamma_{XZ}\right)+e_{ZY}^{p}\left(\gamma_{ZY}\right)\Biggl)^{1/p}. \label{eq:full_triangle_inequality}
\end{flalign}
Then we apply Minkowski's inequality see \cite[Eq.(3)]{Rahmathullah17} and \cite{kubrusly2011elements} to obtain
\begin{flalign}
&d\left(X,Y,\gamma_{XY}\right) \nonumber \\
& \leq\left(\sum_{\left(i,k\right)\in\gamma_{XZ}^{1},\left(k,j\right)\in\gamma_{ZY}^{1}}d^{p}\left(x_{i},z_{k}\right)+\sum_{\left(i,k\right)\in\gamma_{XZ}^{0}}d^{p}\left(x_{i},z_{k}\right)\right. \nonumber \\
 & \left.+\frac{c^{p}}{2}\left(\left|X\right|+|Z|-2\left|\gamma_{XZ}\right|\right)+e_{XZ}^{p}\left(\gamma_{XZ}\right)\right)^{1/p} \nonumber\\
 & +\left(\sum_{\left(i,k\right)\in\gamma_{XZ}^{1},\left(k,j\right)\in\gamma_{ZY}^{1}}d^{p}\left(z_{k},y_{j}\right)+\sum_{\left(k,j\right)\in\gamma_{ZY}^{0}}d^{p}\left(z_{k},y_{j}\right)\right. \nonumber\\
 & \left.+\frac{c^{p}}{2}\left(|Z|+\left|Y\right|-2\left|\gamma_{ZY}\right|\right)+e_{ZY}^{p}\left(\gamma_{ZY}\right)\right)^{1/p} \nonumber \\
 & =d\left(X,Z,\gamma_{XZ}\right)+d\left(Z,Y,\gamma_{ZY}\right). \label{eq:triangle_inequality_final_form}
\end{flalign}

This finishies the proof of \eqref{eq:triangle_ineq_fixed_assignment}.

\subsection{Localisation cost inequality}\label{proof:loc cost triangle}
In this section, we prove \eqref{eq:loc_cost_inequality}. On the left-hand side of \eqref{eq:loc_cost_inequality}, we have 

\begin{flalign}
&\sum_{\left(i,j\right)\in\gamma_{XY}}d^{p}\left(x_{i},y_{j}\right)+\frac{c^{p}}{2}\left(\left|X\right|+\left|Y\right|-2\left|\gamma_{XY}\right|\right) \nonumber \\
  =&\sum_{\left(i,j\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}}d^{p}\left(x_{i},y_{j}\right)+\frac{c^{p}}{2}\left(\left|X\right|+\left|Y\right|-2\left|\gamma_{XY}\right|\right)\nonumber\\
  \leq&\sum_{\left(i,k\right)\in\gamma_{XZ}^{1},\left(k,j\right)\in\gamma_{ZY}^{1}}\left(d\left(x_{i},z_{k}\right)+d\left(z_{k},y_{j}\right)\right)^{p}\nonumber\\
 &+\frac{c^{p}}{2}\left(\left|X\right|+\left|Y\right|-2\left|\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}\right|\right)\nonumber\\ \leq&\sum_{\left(i,k\right)\in\gamma_{XZ}^{1},\left(k,j\right)\in\gamma_{ZY}^{1}}\left(d\left(x_{i},z_{k}\right)+d\left(z_{k},y_{j}\right)\right)^{p}\nonumber\\
 &+\frac{c^{p}}{2}\left(\left|X\right|+\left|Y\right|-2\left|\gamma_{XZ}\right|-2\left|\gamma_{ZY}\right|\right)\nonumber\\
 \leq&\sum_{\left(i,k\right)\in\gamma_{XZ}^{1},\left(k,j\right)\in\gamma_{ZY}^{1}}\left(d\left(x_{i},z_{k}\right)+d\left(z_{k},y_{j}\right)\right)^{p}\nonumber\\
 & +\frac{c^{p}}{2}\left(\left|X\right|+|Z|-2\left|\gamma_{XZ}\right|\right)+\frac{c^{p}}{2}\left(|Z|+\left|Y\right|-2\left|\gamma_{ZY}\right|\right)\nonumber\\
 \leq&\sum_{\left(i,k\right)\in\gamma_{XZ}^{1},\left(k,j\right)\in\gamma_{ZY}^{1}}\left(d\left(x_{i},z_{k}\right)+d\left(z_{k},y_{j}\right)\right)^{p}\nonumber\\
 & +\sum_{\left(i,k\right)\in\gamma_{XZ}^{0}}d^{p}\left(x_{i},z_{k}\right)+\sum_{\left(k,j\right)\in\gamma_{ZY}^{0}}d^{p}\left(z_{k},y_{j}\right)\nonumber\\
 & +\frac{c^{p}}{2}\left(\left|X\right|+|Z|-2\left|\gamma_{XZ}\right|\right) +\frac{c^{p}}{2}\left(|Z|+\left|Y\right|-2\left|\gamma_{ZY}\right|\right). \label{eq:proof_local_cost_1} 
\end{flalign}
Thus, the inequality in \eqref{eq:loc_cost_inequality} has been proved.

\subsection{Inequality for edge cost}\label{proof:edge cost triangle}
In this section, we prove \eqref{eq:edge_cost_inequality}. The edge mismatch cost for $X$ and $Y$ can be written as
\begin{flalign}
    &e_{XY}^{p}\left(\gamma_{XY}\right) \nonumber \\
    =& \sum_{\left(i_{1},j_{1}\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}}\sum_{\left(i_{2},j_{2}\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}}\frac{\epsilon^{p}}{2}|A_{X}(i_{1},i_{2})-A_{Y}(j_{1},j_{2})| \nonumber \\
 &+ \eta\epsilon^{p}\sum_{\left(i_{1},j_{1}\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}}\nonumber \\
 &\left[\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2}) + \sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\right] \nonumber \\
  &+\eta\epsilon^{p}\sum_{\left(i_{1},j_{1}\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}} \nonumber \\
  &\left[\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2}) + \sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}A_{Y}(j_{1},j_{2})\right] \nonumber\\
 &+\frac{\beta}{2}\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2}) \nonumber \\
 &+\beta\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber \\
 &+ \frac{\beta}{2}\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2}) \nonumber\\
 &+ \frac{\beta}{2}\epsilon^{p}\sum_{j_{1}\in U_{Y}\left(\gamma_{ZY}\right)}\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2}) \nonumber \\
 &+ \beta\epsilon^{p}\sum_{j_{1}\in U_{Y}\left(\gamma_{ZY}\right)}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}A_{Y}(j_{1},j_{2})\nonumber\\
 &+\frac{\beta}{2}\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{0}}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}A_{Y}(j_{1},j_{2}).\label{eq:edge_cost_inequality_proof}
\end{flalign}
Now, we operate based on the types of costs that appear in \eqref{eq:edge_cost_inequality_proof}.
\subsubsection{Cost for assigned edges}
The cost for the assigned edges in \eqref{eq:edge_cost_inequality_proof} meets
\begin{flalign}
     & \frac{\epsilon^{p}}{2}\sum_{\left(i_{1},j_{1}\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}}\sum_{\left(i_{2},j_{2}\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}} \nonumber \\
    & |A_{X}(i_{1},i_{2})-A_{Y}(j_{1},j_{2})| \nonumber \\
  =&\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1},\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{1},(k_{2},j_{2})\in\gamma_{ZY}^{1}} \nonumber \\
  &|A_{X}(i_{1},i_{2})-A_{Y}(j_{1},j_{2})+A_{Z}(k_{1},k_{2})-A_{Z}(k_{1},k_{2})|\nonumber\\
 \leq&\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1},\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{1},(k_{2},j_{2})\in\gamma_{ZY}^{1}} \nonumber \\ 
 &\left[|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|+|A_{Z}(k_{1},k_{2})-A_{Y}(j_{1},j_{2})|\right]\nonumber\\
 \leq&\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1},}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{1}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})| \nonumber \\
 &+\frac{\epsilon^{p}}{2}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{(k_{2},j_{2})\in\gamma_{ZY}^{1}}|A_{Z}(k_{1},k_{2})-A_{Y}(j_{1},j_{2})|. \label{eq:assigned_edge_cost}
\end{flalign}
\subsubsection{Cost for half-assigned edges}
We first consider the terms for the half-assigned edges in $X$ in \eqref{eq:edge_cost_inequality_proof} to yield the following inequality.
\begin{flalign}
     & \eta\epsilon^{p}\sum_{\left(i_{1},j_{1}\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}} \nonumber \\
     &\left[\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})+\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\right] \nonumber \\
 =& \eta\epsilon^{p}\sum_{\left(i_{1},j_{1}\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber \\
 &+ \eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1},(k_{1},j_{1})\in\gamma_{ZY}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2}) \nonumber \\
  =&\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2}) \nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber \\
  =&\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber\\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}} \nonumber\\
 &|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})+A_{Z}(k_{1},k_{2})|\nonumber\\
 \leq&\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber\\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber\\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{Z}(k_{1},k_{2})\nonumber\\
 \leq&\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber\\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber\\
 & +\eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{k_{2}\in U_{Z}\left(\gamma_{ZY}\right)}A_{Z}(k_{1},k_{2}). \label{eq:half-assigned_edge_cost_X}
\end{flalign}
Analogously, for the half-assigned edges in $Y$, we obtain
\begin{flalign}
     & \eta\epsilon^{p}\sum_{\left(i_{1},j_{1}\right)\in\gamma_{XZ}^{1}\circ\gamma_{ZY}^{1}} \nonumber \\
     &\left[\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2})+\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}A_{Y}(j_{1},j_{2})\right] \nonumber \\
 \leq&\eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2}) \nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}\text{|}A_{Y}(j_{1},j_{2})-A_{Z}(k_{1},k_{2})| \nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{k_{2}\in U_{Z}\left(\gamma_{XZ}\right)}A_{Z}(k_{1},k_{2}). \label{eq:half-assigned_edge_cost_Y}
\end{flalign}


\subsubsection{Cost for unassigned edges}
Operating with the cost for unassigned edges in $X$, we obtain the following inequality
\begin{flalign}
     & \frac{\beta}{2}\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber\\
 & +\beta\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber\\
 & \frac{\beta}{2}\beta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber\\
 =&\frac{\beta}{2}\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber\\
 & +\beta\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber\\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}\nonumber\\
 &|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})+A_{Z}(k_{1},k_{2})|\nonumber\\
  \leq&\frac{\beta}{2}\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber\\
 & +\beta\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber\\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber\\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{Z}(k_{1},k_{2})\nonumber\\
 \leq&\frac{\beta}{2}\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber\\
 & +\beta\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber\\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber\\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{k_{1}\in U_{Z}\left(\gamma_{ZY}\right)}\sum_{k_{2}\in U_{Z}\left(\gamma_{ZY}\right)}A_{Z}(k_{1},k_{2}). \label{eq:unassigned_edge_cost_X}
