Then we proceed analogously for the unassigned edges in $Y$ to obtain the inequality
\begin{flalign}
     & \frac{\beta}{2}\epsilon^{p}\sum_{j_{1}\in U_{Y}\left(\gamma_{ZY}\right)}\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2})\nonumber\\
 & +\beta\epsilon^{p}\sum_{j_{1}\in U_{Y}\left(\gamma_{ZY}\right)}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}A_{Y}(j_{1},j_{2})\nonumber\\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{0}}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}A_{Y}(j_{1},j_{2})\nonumber\\
 & \leq\frac{\beta}{2}\epsilon^{p}\sum_{j_{1}\in U_{Y}\left(\gamma_{ZY}\right)}\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2})\nonumber\\
 & +\beta\epsilon^{p}\sum_{j_{1}\in U_{Y}\left(\gamma_{ZY}\right)}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}A_{Y}(j_{1},j_{2})\nonumber\\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{0}}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}|A_{Y}(j_{1},j_{2})-A_{Z}(k_{1},k_{2})|\nonumber\\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{k_{1}\in U_{Z}\left(\gamma_{XZ}\right)}\sum_{k_{2}\in U_{Z}\left(\gamma_{XZ}\right)}A_{Z}(k_{1},k_{2}). \label{eq:unassgined_edge_cost_Y}
\end{flalign}


\subsubsection{Combination of all edge costs}\label{subsec:combination of edge costs}
By combining the inequalities in \eqref{eq:assigned_edge_cost}, \eqref{eq:half-assigned_edge_cost_X}, \eqref{eq:half-assigned_edge_cost_Y}, \eqref{eq:unassigned_edge_cost_X}, and \eqref{eq:unassgined_edge_cost_Y}, we obtain
\begin{flalign}
     & e_{XY}^{p}\left(\gamma_{XY}\right)\nonumber \\
  \leq&\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1},}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{1}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\frac{\epsilon^{p}}{2}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{(k_{2},j_{2})\in\gamma_{ZY}^{1}}|A_{Z}(k_{1},k_{2})-A_{Y}(j_{1},j_{2})|\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}\text{|}A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{k_{2}\in U_{Z}\left(\gamma_{ZY}\right)}A_{Z}(k_{1},k_{2})\nonumber \\
& +\eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2})\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}\text{|}A_{Y}(j_{1},j_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{k_{2}\in U_{Z}\left(\gamma_{XZ}\right)}A_{Z}(k_{1},k_{2})\nonumber \\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber \\
 & +\beta\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber \\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{k_{1}\in U_{Z}\left(\gamma_{ZY}\right)}\sum_{k_{2}\in U_{Z}\left(\gamma_{ZY}\right)}A_{Z}(k_{1},k_{2})\nonumber \\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{j_{1}\in U_{Y}\left(\gamma_{ZY}\right)}\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2})\nonumber \\
 & +\beta\epsilon^{p}\sum_{j_{1}\in U_{Y}\left(\gamma_{ZY}\right)}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}A_{Y}(j_{1},j_{2})\nonumber \\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{0}}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}|A_{Y}(j_{1},j_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{k_{1}\in U_{Z}\left(\gamma_{XZ}\right)}\sum_{k_{2}\in U_{Z}\left(\gamma_{XZ}\right)}A_{Z}(k_{1},k_{2}).\label{eq:substitution1}
\end{flalign}

Now, we operate again on the assigned edges and half-assigned edges.
For assigned edges, we have
\begin{flalign}
     & \frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ},}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
  =&\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}\cup\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}\cup\gamma_{XZ}^{1}} \nonumber \\
 &|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber\\
 =&\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber\\
& +\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{1}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber\\
 & +\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{1}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|.
\end{flalign}
Given fact that $\beta \leq \eta \leq 1$, the assigned parts in $X$ and $Z$ \eqref{eq:substitution1} have the following inequality:
\begin{flalign}
     & \frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1},}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{1}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}\text{|}A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
  \leq &\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1},}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{1}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}\text{|}A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{0}}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
  =&\frac{\epsilon^{p}}{2}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ},}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}}|A_{X}(i_{1},i_{2})-A_{Z}(k_{1},k_{2})|.\label{eq:assigned_edge_inequality_XZ}
\end{flalign}
This result applies to the assigned parts in $Z$ and $Y$ in \eqref{eq:substitution1}.
\begin{flalign}
    & \frac{\epsilon^{p}}{2}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{(k_{2},j_{2})\in\gamma_{ZY}^{1}}|A_{Z}(k_{1},k_{2})-A_{Y}(j_{1},j_{2})|\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}\text{|}A_{Y}(j_{1},j_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & +\frac{\beta}{2}\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{0}}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}|A_{Y}(j_{1},j_{2})-A_{Z}(k_{1},k_{2})|\nonumber \\
 & \leq\frac{\epsilon^{p}}{2}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY},}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}}|A_{Y}(j_{1},j_{2})-A_{Z}(k_{1},k_{2})|.\label{eq:assigned_edge_inequality_ZY}
\end{flalign}


Then we consider the half-assigned edges between $X$ and $Z$ in \eqref{eq:substitution1} and with the condition that $\beta\leq \eta$, we can write 
\begin{flalign}
     & \eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{k_{2}\in U_{Z}\left(\gamma_{XZ}\right)}A_{Z}(k_{1},k_{2})\nonumber \\
 & +\beta\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber \\
  \leq&\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{k_{2}\in U_{Z}\left(\gamma_{XZ}\right)}A_{Z}(k_{1},k_{2})\nonumber \\
 & +\eta\epsilon^{p}\sum_{i_{1}\in U_{X}\left(\gamma_{XZ}\right)}\sum_{\left(i_{2},k_{2}\right)\in\gamma_{XZ}^{0}}A_{X}(i_{1},i_{2})\nonumber \\
  =&\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}}\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}^{1}}\sum_{k_{2}\in U_{Z}\left(\gamma_{XZ}\right)}A_{Z}(k_{1},k_{2})\nonumber \\
 \leq&\eta\epsilon^{p}\sum_{\left(i_{1},k_{1}\right)\in\gamma_{XZ}}\nonumber \\
 &\left[\sum_{i_{2}\in U_{X}\left(\gamma_{XZ}\right)}A_{X}(i_{1},i_{2})+\sum_{k_{2}\in U_{Z}\left(\gamma_{XZ}\right)}A_{Z}(k_{1},k_{2})\right]. \label{eq:half_XZ_inequality}
\end{flalign}
We now operate similarly on the half-assigned edges between $Z$ and $Y$, we have 
\begin{flalign}
     & \eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{k_{2}\in U_{Z}\left(\gamma_{ZY}\right)}A_{Z}(k_{1},k_{2})\nonumber \\
 & +\eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}^{1}}\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2})\nonumber \\
 & +\beta\epsilon^{p}\sum_{j_{1}\in U_{Y}\left(\gamma_{ZY}\right)}\sum_{\left(k_{2},j_{2}\right)\in\gamma_{ZY}^{0}}A_{Y}(j_{1},j_{2})\nonumber \\
  \leq&\eta\epsilon^{p}\sum_{\left(k_{1},j_{1}\right)\in\gamma_{ZY}} \nonumber \\
  &\left[\sum_{k_{2}\in U_{Z}\left(\gamma_{ZY}\right)}A_{Z}(k_{1},k_{2})+\sum_{j_{2}\in U_{Y}\left(\gamma_{ZY}\right)}A_{Y}(j_{1},j_{2})\right]\label{eq:half_ZY_inequality}.
\end{flalign}
If we substitute \eqref{eq:assigned_edge_inequality_XZ}, \eqref{eq:assigned_edge_inequality_ZY}, \eqref{eq:half_XZ_inequality} and \eqref{eq:half_ZY_inequality} into \eqref{eq:substitution1}, the inequality in \eqref{eq:edge_cost_inequality} is proved.

